insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('a33a60ff-a447-41d8-8e32-2f3a8b092c6f', 1, null, 'A day ahead, season the roast all over with the salt and refrigerate uncovered on a rack.', 43200, null, null),
  ('a33a60ff-a447-41d8-8e32-2f3a8b092c6f', 2, null, 'Bring the roast out 2 hours before cooking. Heat the oven to 225°F.', 7200, 107.2, null),
  ('a33a60ff-a447-41d8-8e32-2f3a8b092c6f', 3, null, 'Mix the garlic, rosemary, pepper and oil and rub it over the meat. Set it bone-side down in a roasting pan.', null, null, null),
  ('a33a60ff-a447-41d8-8e32-2f3a8b092c6f', 4, null, 'Roast until the center reaches 145°F on an instant-read thermometer (USDA safe minimum for beef roasts), about 4 hours. Rest 30–45 minutes, loosely covered.', 14400, 107.2, 62.8),
  ('a33a60ff-a447-41d8-8e32-2f3a8b092c6f', 5, null, 'Heat the oven to 500°F. Return the roast for 8–10 minutes to brown the crust, then carve between the bones and slice.', 540, 260, null);

