insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7c24982f-215b-49b2-abe2-00585e05bfb3', 1, null, 'Cut down the top of each shell with kitchen shears and pull the tail meat out in one piece.', null, null, null),
  ('7c24982f-215b-49b2-abe2-00585e05bfb3', 2, null, 'Bring the water to a simmer in a small saucepan, then whisk in the butter a few cubes at a time over low heat to make a creamy emulsion; never let it boil.', null, null, null),
  ('7c24982f-215b-49b2-abe2-00585e05bfb3', 3, null, 'Add the lemon zest, tarragon and salt. Keep the butter at about 160–180°F.', null, null, null),
  ('7c24982f-215b-49b2-abe2-00585e05bfb3', 4, null, 'Slip in the lobster and poach, spooning butter over, until the meat is opaque and reads 145°F in the thickest part, 6–8 minutes.', 420, null, 62.8),
  ('7c24982f-215b-49b2-abe2-00585e05bfb3', 5, null, 'Lift out, season with a squeeze of lemon and spoon a little butter over to serve.', null, null, null);

