insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('c0d9c229-9100-4268-989d-44b07fedb62b', 1, null, 'Cook the guanciale in a cold skillet over medium heat until crisp and the fat has rendered, 8 minutes. Take off the heat.', 480, null, null),
  ('c0d9c229-9100-4268-989d-44b07fedb62b', 2, null, 'Whisk the yolks, eggs, cheese and most of the pepper into a thick paste.', null, null, null),
  ('c0d9c229-9100-4268-989d-44b07fedb62b', 3, null, 'Boil the spaghetti in well-salted water until al dente. Save 1 cup of the water.', 600, null, null),
  ('c0d9c229-9100-4268-989d-44b07fedb62b', 4, null, 'Toss the pasta into the guanciale pan off the heat, then add the egg mixture with a splash of pasta water and toss fast until creamy and glossy. The pan''s heat cooks the eggs gently — never put it back on the burner or they''ll scramble.', null, null, null),
  ('c0d9c229-9100-4268-989d-44b07fedb62b', 5, null, 'Serve at once with the rest of the pepper and more cheese.', null, null, null);

