insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('fcd0f627-e6c7-4b8a-b79a-9478f01ee8a7', 1, null, 'In a wide paella pan, cook the onion and pepper in the oil until soft, 8 minutes. Add the garlic and tomato and cook down to a jammy sofrito, 8 minutes.', 960, null, null),
  ('fcd0f627-e6c7-4b8a-b79a-9478f01ee8a7', 2, null, 'Stir in the paprika and rice to coat, then pour in the hot stock and saffron. Season, stir once and spread evenly. Don''t stir again.', null, null, null),
  ('fcd0f627-e6c7-4b8a-b79a-9478f01ee8a7', 3, null, 'Simmer briskly 10 minutes, then lower the heat. Nestle in the shrimp and mussels and cook until the rice is tender, the shrimp are opaque (145°F) and the mussels have opened, 10 more minutes. Throw away any that stay shut.', 1200, null, 62.8),
  ('fcd0f627-e6c7-4b8a-b79a-9478f01ee8a7', 4, null, 'Turn up the heat for 1–2 minutes until the bottom crackles — the socarrat. Rest 5 minutes under a towel and serve with lemon.', 360, null, null);

