insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('db274735-25dd-409a-aa8b-6ae03d7f74ab', 1, 'Duck', 'Season the duck and put it skin-side down in a cold oven-safe skillet. Cook over medium-low until the fat renders and the skin is crisp, 12–15 minutes; pour off fat as it builds.', 840, null, null),
  ('db274735-25dd-409a-aa8b-6ae03d7f74ab', 2, 'Duck', 'Flip and finish in a 400°F oven until 165°F in the center, 6–8 minutes. Rest 5 minutes.', 420, 204.4, 73.9),
  ('db274735-25dd-409a-aa8b-6ae03d7f74ab', 3, 'Sauce', 'Pour off all but a spoonful of fat. Soften the shallot, then add the wine and reduce by half. Add the stock, cherries and honey and simmer until syrupy, 5 minutes.', 420, null, null),
  ('db274735-25dd-409a-aa8b-6ae03d7f74ab', 4, 'Sauce', 'Off the heat, swirl in the butter. Slice the duck and spoon the sauce over.', null, null, null);

