insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('15e3d98b-40ff-4732-985b-5f429db8ad7f', 1, 'Pastry', 'Pulse the flour, sugar and butter to crumbs, add the yolk and pulse until it clumps. Press into a 9-inch tart pan and chill 30 minutes.', 1800, null, null),
  ('15e3d98b-40ff-4732-985b-5f429db8ad7f', 2, 'Pastry', 'Line with foil and weights and bake at 375°F for 15 minutes, then remove the weights and bake until golden, 10 more.', 1500, 190.6, null),
  ('15e3d98b-40ff-4732-985b-5f429db8ad7f', 3, 'Filling', 'Whisk the zest, juice, sugar, eggs and yolks in a saucepan over medium-low heat until thick enough to coat a spoon and 170°F, 8–10 minutes.', 540, null, null),
  ('15e3d98b-40ff-4732-985b-5f429db8ad7f', 4, 'Filling', 'Strain, whisk in the butter and pour into the shell. Chill until set, about 2 hours.', 7200, null, null);

