  ('6199953b-f091-486d-ad80-621036ba19d0', 1, 'Buttermilk soak', '3½ lb bone-in, skin-on chicken pieces, drumsticks, thighs and breasts, breasts halved crosswise', 'bone-in, skin-on chicken pieces', 3.5, 'lb', 'drumsticks, thighs and breasts, breasts halved crosswise', false),
  ('6199953b-f091-486d-ad80-621036ba19d0', 2, 'Buttermilk soak', '2 cups buttermilk', 'buttermilk', 2, 'cup', null, false),
