values ('d3c04a1b-6899-4588-b51c-28ddc9dc7c61', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'yankee-pot-roast', 'yankee-pot-roast-d3c04a', 'Yankee Pot Roast', 'Beef chuck browned hard, then braised low and slow with root vegetables until it falls apart into its own gravy.', 'american', 3, 30, 215, 245, 6, 'main', null, 0, array['oven', 'stove', 'dutch_oven']::text[], array['comfort', 'make-ahead', 'entertaining']::text[], array['Pot roast is even better the next day: chill it in its liquid, lift off the solid fat, and reheat gently.']::text[], 'https://images.pexels.com/photos/6545671/pexels-photo-6545671.jpeg', 'Tender pot roast with carrots and potatoes on a white plate', 'Thiago Rebouças', 'https://www.pexels.com/@thiagoreboucasft/', 'https://www.pexels.com/photo/meat-and-fruit-on-plate-6545671/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner', 'entertaining']::text[], array['roast', 'braise', 'stew', 'pan_fry']::text[], array['fresh']::text[], '{}'::text[], 'New England', 'traditional', 'pot-roast', 'classic', 'Refrigerate in its gravy up to 4 days, or freeze the beef and gravy (without the potatoes) up to 3 months.', null, 'owned', array['gluten', 'wheat']::text[], array['beef']::text[], array['dairy_free']::text[], array['chuck roast', 'yellow onion', 'garlic', 'tomato paste', 'beef stock', 'thyme', 'bay leave', 'gold potato', 'carrot', 'parsnip', 'parsley']::text[], 'bay leave|beef stock|carrot|chuck roast|garlic|gold potato|parsley|parsnip|thyme|tomato paste|yellow onion',
  null, null, null, null, null, null, null, null)
