  ('2209f8a3-e3ed-4783-8117-5b81c073bf2e', 1, null, '1½ lb boneless ribeye steak', 'boneless ribeye steak', 1.5, 'lb', null, false),
  ('2209f8a3-e3ed-4783-8117-5b81c073bf2e', 2, null, '2 tbsp vegetable oil', 'vegetable oil', 2, 'tbsp', null, false),
  ('2209f8a3-e3ed-4783-8117-5b81c073bf2e', 3, null, '1 large yellow onion, thinly sliced', 'large yellow onion', 1, null, 'thinly sliced', false),
