insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('2209f8a3-e3ed-4783-8117-5b81c073bf2e', 1, null, 'Wrap the steak and freeze until firm but not solid, 30–45 minutes, then slice it across the grain as thinly as you can.', 2400, null, null),
  ('2209f8a3-e3ed-4783-8117-5b81c073bf2e', 2, null, 'Heat 1 tablespoon oil in a large cast-iron skillet or griddle over medium heat. Cook the onion (and green pepper, if using) with a pinch of the salt until soft and golden, about 10 minutes. Push to one side of the pan.', 600, null, null),
  ('2209f8a3-e3ed-4783-8117-5b81c073bf2e', 3, null, 'Turn the heat to high and add the rest of the oil and the steak in one layer (in two batches if needed). Season with the remaining salt and the pepper. Sear 1 minute, then chop and turn it with two spatulas until no pink remains and it reaches 145°F, 2–3 minutes.', 180, null, 62.8),
  ('2209f8a3-e3ed-4783-8117-5b81c073bf2e', 4, null, 'Mix in the onions and shape into 4 long piles, each the length of a roll. Lay 2 slices of provolone over each pile and cover the pan until the cheese melts, about 1 minute.', 60, null, null),
  ('2209f8a3-e3ed-4783-8117-5b81c073bf2e', 5, null, 'Lay an open roll face-down on each pile, slide a spatula underneath and flip the whole thing into the roll. Serve right away, with cherry peppers if you like.', null, null, null);

