values ('f8cd3840-367f-428f-b9e5-0d600679e6cc', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'buttermilk-pancakes', 'buttermilk-pancakes-f8cd38', 'Buttermilk Pancakes', 'Tall, fluffy, slightly tangy diner-style pancakes — the secret is a lumpy batter and a griddle that isn''t too hot.', 'american', 1, 10, 20, 30, 4, 'breakfast', null, 0, array['stove']::text[], array['kid-friendly', 'budget', 'vegetarian']::text[], array['No buttermilk? Stir 2 tablespoons lemon juice into 2 cups milk and let it stand 5 minutes.']::text[], 'https://images.unsplash.com/photo-1757635964104-67218db55bca', 'Tall stack of golden-brown homemade pancakes on a plate', 'Sebastian Schuster', 'https://unsplash.com/@sschusterphotoart', 'https://unsplash.com/photos/a-tall-stack-of-golden-brown-pancakes-on-a-plate-vfl6y292kSI', 'unsplash', true, 'public', false,
  'pending_review', array['breakfast', 'holiday', 'budget', 'comfort']::text[], '{}'::text[], array['tangy']::text[], array['brunch-party']::text[], null, null, 'buttermilk-pancakes', 'classic', 'Freeze cooked pancakes between sheets of parchment up to 2 months; reheat in the toaster.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['baking powder', 'baking soda', 'buttermilk', 'egg', 'vanilla extract', 'maple syrup']::text[], 'baking powder|baking soda|buttermilk|egg|maple syrup|vanilla extract',
