  ('376c60f0-9a74-4010-9adf-03eeedb49915', 3, null, '4 slice thick-cut bacon, diced', 'thick-cut bacon', 4, 'slice', 'diced', false),
  ('376c60f0-9a74-4010-9adf-03eeedb49915', 4, null, '2 tbsp unsalted butter', 'unsalted butter', 2, 'tbsp', null, false),
  ('376c60f0-9a74-4010-9adf-03eeedb49915', 5, null, '1 yellow onion, diced', 'yellow onion', 1, null, 'diced', false),
  ('376c60f0-9a74-4010-9adf-03eeedb49915', 6, null, '2 stalk celery, diced', 'celery', 2, 'stalk', 'diced', false),
  ('376c60f0-9a74-4010-9adf-03eeedb49915', 7, null, '3 tbsp all-purpose flour', 'all-purpose flour', 3, 'tbsp', null, false),
  ('376c60f0-9a74-4010-9adf-03eeedb49915', 8, null, '1 cup bottled clam juice', 'bottled clam juice', 1, 'cup', null, false),
  ('376c60f0-9a74-4010-9adf-03eeedb49915', 9, null, '1½ lb Yukon Gold potatoes, cut into ½-inch dice', 'Yukon Gold potatoes', 1.5, 'lb', 'cut into ½-inch dice', false),
  ('376c60f0-9a74-4010-9adf-03eeedb49915', 10, null, '2 sprigs fresh thyme', 'fresh thyme', 2, 'sprig', null, false),
  ('376c60f0-9a74-4010-9adf-03eeedb49915', 11, null, '1 bay leaf', 'bay leaf', 1, null, null, false),
