values ('5e7a0688-e536-4bf9-924f-d0b137081ea6', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'southern-baked-mac-and-cheese', 'baked-mac-and-cheese-5e7a06', 'Baked Mac and Cheese', 'Southern-style mac and cheese baked in a cheddar custard, so it slices into rich, sturdy squares with a browned, bubbly top.', 'southern', 1, 15, 50, 65, 8, 'side', null, 0, array['oven', 'stove']::text[], array['comfort', 'kid-friendly', 'vegetarian']::text[], array['Shred the cheese yourself: bagged shredded cheese is coated in starch and melts grainy.']::text[], 'https://images.unsplash.com/photo-1701484185547-a71576b65e1a', 'Baked macaroni and cheese in a serving dish with a spoon', 'Keith Hanson Jr', 'https://unsplash.com/@khjphoto12', 'https://unsplash.com/photos/a-dish-of-macaroni-and-cheese-with-a-spoon-in-it-VKI3lU4GA1w', 'unsplash', true, 'public', false,
  'pending_review', array['comfort', 'side', 'holiday']::text[], array['bake', 'boil']::text[], array['spicy', 'smoky']::text[], array['thanksgiving', 'potluck']::text[], null, 'traditional', 'mac-and-cheese', 'classic', 'Refrigerate up to 4 days. Reheat portions covered at 325°F with a splash of milk.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['elbow macaroni', 'evaporated milk', 'milk', 'egg', 'dry mustard', 'smoked paprika', 'cayenne pepper', 'cheddar cheese', 'jack cheese']::text[], 'cayenne pepper|cheddar cheese|dry mustard|egg|elbow macaroni|evaporated milk|jack cheese|milk|smoked paprika',
