values ('39710080-f236-4c7c-a90c-a31827b8865b', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'carolina-pulled-pork-sandwiches', 'pulled-pork-sandwiches-397100', 'Pulled Pork Sandwiches', 'Spice-rubbed pork shoulder braised in the oven until it shreds, tossed with a peppery Carolina vinegar sauce and piled on buns with slaw — oven-braised instead of pit-smoked, so no smoker needed.', 'southern', 2, 30, 305, 335, 10, 'main', null, 0, array['oven', 'dutch_oven']::text[], array['entertaining', 'make-ahead', 'freezer-friendly', 'budget']::text[], array['For a smoky flavor without a smoker, add ½ teaspoon liquid smoke to the braising liquid.']::text[], 'https://images.unsplash.com/photo-1761712826051-b873907fb5d3', 'Pulled pork sandwich on a bun with coleslaw and pickles', 'nobleseed nobleseed', 'https://unsplash.com/@nobleseed', 'https://unsplash.com/photos/pulled-pork-sandwich-with-coleslaw-and-pickles-8icctIHfJIo', 'unsplash', true, 'public', false,
  'pending_review', array['grilling', 'main', 'dinner', 'holiday', 'budget', 'entertaining']::text[], array['roast', 'braise']::text[], array['spicy', 'smoky', 'tangy']::text[], array['july-4th', 'game-day']::text[], 'Carolinas', 'adapted', 'pulled-pork', 'classic', 'Refrigerate the pork up to 4 days or freeze up to 3 months with some of its juices; reheat covered at 300°F.', null, 'owned', array['egg', 'gluten', 'wheat']::text[], array['pork']::text[], array['dairy_free']::text[], array['brown sugar', 'smoked paprika', 'garlic powder', 'dry mustard', 'cayenne pepper', 'pork shoulder', 'cider vinegar', 'pepper flake', 'sauce', 'green cabbage', 'mayonnaise', 'sandwich bun']::text[], 'brown sugar|cayenne pepper|cider vinegar|dry mustard|garlic powder|green cabbage|mayonnaise|pepper flake|pork shoulder|sandwich bun|sauce|smoked paprika',
  null, null, null, null, null, null, null, null)
