insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('39710080-f236-4c7c-a90c-a31827b8865b', 1, 'Rub', 'Mix the rub ingredients. Pat the pork dry, cut it into 2 large chunks and coat all over with the rub. You can wrap and refrigerate it overnight at this point.', null, null, null),
  ('39710080-f236-4c7c-a90c-a31827b8865b', 2, 'Pork', 'Heat the oven to 300°F. Put the pork in a Dutch oven with the vinegar and water, cover tightly and braise until the meat shreds easily with a fork, 4½–5 hours. It will be far past the 145°F safe minimum — about 200°F is what makes it pull apart.', 17100, 148.9, 62.8),
  ('39710080-f236-4c7c-a90c-a31827b8865b', 3, 'Pork', 'Uncover, raise the oven to 425°F and roast 20 minutes to darken the crust.', 1200, 218.3, null),
  ('39710080-f236-4c7c-a90c-a31827b8865b', 4, 'Vinegar sauce', 'Meanwhile, whisk the sauce ingredients until the sugar dissolves. For the slaw, toss the cabbage with the mayonnaise, vinegar, sugar and a pinch of salt, and refrigerate.', null, null, null),
  ('39710080-f236-4c7c-a90c-a31827b8865b', 5, 'Pork', 'Move the pork to a board and rest 15 minutes, then shred with two forks, discarding any large pieces of fat. Skim the fat from the pan juices and toss the meat with ½ cup of the juices and ½ cup of the vinegar sauce.', 900, null, null),
  ('39710080-f236-4c7c-a90c-a31827b8865b', 6, null, 'Pile the pork on the buns, top with slaw and serve the rest of the sauce on the side.', null, null, null);

