values ('141c666d-63db-413f-a411-84eeec8f456c', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'lowcountry-shrimp-and-grits', 'shrimp-and-grits-141c66', 'Shrimp and Grits', 'Slow-cooked creamy cheddar grits topped with shrimp seared in bacon fat and a quick, lemony pan sauce.', 'southern', 2, 20, 40, 60, 4, 'main', null, 0, array['stove']::text[], array['comfort', 'entertaining']::text[], array['Stone-ground grits take longer but taste much more of corn. Quick grits are ready in about 10 minutes if you''re short on time.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner', 'entertaining']::text[], array['stew', 'pan_fry']::text[], array['spicy', 'smoky', 'tangy']::text[], '{}'::text[], 'Lowcountry', 'traditional', 'shrimp-and-grits', 'classic', 'Best fresh. Refrigerate up to 2 days; loosen the grits with milk when reheating.', null, 'owned', array['milk', 'shellfish']::text[], array['pork', 'shellfish']::text[], '{}'::text[], array['milk', 'stone-ground grit', 'cheddar cheese', 'bacon', 'shrimp', 'smoked paprika', 'cayenne pepper', 'garlic', 'chicken stock', 'lemon juice', 'sauce', 'scallion']::text[], 'bacon|cayenne pepper|cheddar cheese|chicken stock|garlic|lemon juice|milk|sauce|scallion|shrimp|smoked paprika|stone-ground grit',
