delete from public.recipe_instructions where recipe_id = '141c666d-63db-413f-a411-84eeec8f456c';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('141c666d-63db-413f-a411-84eeec8f456c', 1, 'Grits', 'Bring the water, milk and salt to a simmer in a heavy saucepan and slowly whisk in the grits. Cook on low, stirring often and scraping the bottom, until thick and creamy, 30–40 minutes; add a splash of hot water if they get too stiff.', 2100, null, null),
  ('141c666d-63db-413f-a411-84eeec8f456c', 2, 'Grits', 'Stir in the butter and cheddar, cover and keep warm.', null, null, null),
  ('141c666d-63db-413f-a411-84eeec8f456c', 3, 'Shrimp', 'Meanwhile, cook the bacon in a large skillet over medium heat until crisp, 6–8 minutes. Scoop it out and leave about 2 tablespoons of fat in the pan.', 420, null, null),
  ('141c666d-63db-413f-a411-84eeec8f456c', 4, 'Shrimp', 'Toss the shrimp with the paprika and cayenne. Sear in the bacon fat over medium-high heat in one layer, 1 minute per side, then add the garlic and cook until the shrimp are pink and opaque all the way through (145°F), about 1 minute more.', 180, null, 62.8),
  ('141c666d-63db-413f-a411-84eeec8f456c', 5, 'Shrimp', 'Add the stock, lemon juice and hot sauce and scrape up the browned bits; simmer 1 minute into a glossy sauce. Stir in the bacon and most of the scallions.', 60, null, null),
  ('141c666d-63db-413f-a411-84eeec8f456c', 6, null, 'Spoon the grits into bowls, top with the shrimp and sauce and scatter with the remaining scallions.', null, null, null);

