values ('b1139ad9-844b-481f-8077-5028b40c4af4', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-andouille-jambalaya', 'jambalaya-b1139a', 'Jambalaya', 'Creole-style red jambalaya: chicken thighs and smoky andouille cooked into tomato-rich rice with the holy trinity of onion, celery and bell pepper.', 'cajun_creole', 2, 25, 55, 80, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['one-pot', 'entertaining']::text[], array['Andouille is a smoky, spicy Louisiana pork sausage; any good smoked sausage, such as kielbasa, works in its place.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'holiday', 'entertaining']::text[], array['stew', 'pan_fry', 'boil']::text[], array['spicy']::text[], array['game-day']::text[], 'Louisiana', 'traditional', 'jambalaya', 'classic', 'Refrigerate up to 4 days and reheat with a splash of stock, or freeze up to 2 months.', null, 'owned', '{}'::text[], array['chicken', 'pork']::text[], array['dairy_free']::text[], array['paprika', 'dried thyme', 'dried oregano', 'cayenne pepper', 'andouille sausage', 'yellow onion', 'bell pepper', 'celery', 'garlic', 'white rice', 'tomato', 'chicken stock', 'bay leave', 'scallion', 'sauce']::text[], 'andouille sausage|bay leave|bell pepper|cayenne pepper|celery|chicken stock|dried oregano|dried thyme|garlic|paprika|sauce|scallion|tomato|white rice|yellow onion',
  null, null, null, null, null, null, null, null)
