delete from public.recipe_instructions where recipe_id = 'b1139ad9-844b-481f-8077-5028b40c4af4';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('b1139ad9-844b-481f-8077-5028b40c4af4', 1, null, 'Mix the paprika, thyme, oregano, cayenne, salt and pepper. Toss half of it with the chicken.', null, null, null),
  ('b1139ad9-844b-481f-8077-5028b40c4af4', 2, null, 'Heat the oil in a Dutch oven over medium-high heat. Brown the andouille, about 5 minutes, and lift it out. Brown the chicken in the same pot, about 5 minutes (it doesn''t need to be cooked through yet), and lift it out.', 600, null, null),
  ('b1139ad9-844b-481f-8077-5028b40c4af4', 3, null, 'Add the onion, bell pepper and celery and cook, scraping up the browned bits, until soft, about 7 minutes. Stir in the garlic and the rest of the spice mix for 1 minute.', 480, null, null),
  ('b1139ad9-844b-481f-8077-5028b40c4af4', 4, null, 'Stir in the rice for 1 minute to coat it, then add the tomatoes and their juice, the stock, the bay leaves, the chicken and the sausage. Bring to a boil.', 180, null, null),
  ('b1139ad9-844b-481f-8077-5028b40c4af4', 5, null, 'Cover, turn the heat to low and simmer without lifting the lid until the rice is tender, the liquid is absorbed and the chicken reaches 165°F, about 25 minutes.', 1500, null, 73.9),
  ('b1139ad9-844b-481f-8077-5028b40c4af4', 6, null, 'Take off the heat and rest, covered, 10 minutes. Remove the bay leaves, fluff, and fold in the scallions and hot sauce.', 600, null, null);

