insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('f5ebef10-34dd-4200-b164-5dcfa525e0fd', 1, null, 'Drain and rinse the soaked beans.', null, null, null),
  ('f5ebef10-34dd-4200-b164-5dcfa525e0fd', 2, null, 'Heat the oil in a Dutch oven over medium heat and brown the andouille, about 5 minutes; lift it out. Cook the onion, bell pepper and celery in the fat until soft, about 8 minutes, then add the garlic for 1 minute.', 840, null, null),
  ('f5ebef10-34dd-4200-b164-5dcfa525e0fd', 3, null, 'Add the beans, water, bay leaves, thyme, cayenne, black pepper and the sausage. Bring to a boil and boil hard for 10 minutes, then lower the heat and simmer, partly covered and stirring now and then, until the beans are very soft, 1½–2 hours. Add water if it gets too thick.', 6900, null, null),
  ('f5ebef10-34dd-4200-b164-5dcfa525e0fd', 4, null, 'Mash about a quarter of the beans against the side of the pot and simmer uncovered, stirring, until creamy, 20–30 minutes more. Season with the salt.', 1500, null, null),
  ('f5ebef10-34dd-4200-b164-5dcfa525e0fd', 5, null, 'Remove the bay leaves and serve over hot rice with scallions and hot sauce.', null, null, null);

-- Cuban Sandwich
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
