values ('1b03cc3f-3d0a-4b1c-9572-697ce757a285', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'arroz-con-gandules', 'arroz-con-gandules-1b03cc', 'Arroz con Gandules', 'Puerto Rico''s festive rice with pigeon peas, smoked ham, olives and fresh sofrito, cooked in one pot until each grain is seasoned through.', 'puerto_rican', 2, 20, 50, 70, 8, 'side', null, 0, array['stove', 'dutch_oven', 'food_processor']::text[], array['entertaining', 'one-pot']::text[], array['Sazón comes in packets in the Latin aisle. To make your own, mix ½ teaspoon each ground annatto, garlic powder, ground cumin and ground coriander with ¼ teaspoon salt.', 'Freeze the leftover sofrito in an ice-cube tray — it''s the base for beans, stews and more rice.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['side', 'holiday', 'entertaining']::text[], array['pan_fry', 'boil']::text[], array['smoky', 'tangy', 'fresh']::text[], array['christmas', 'thanksgiving']::text[], null, 'traditional', 'arroz-con-gandules', 'classic', 'Refrigerate up to 4 days; reheat covered with a splash of water. Freezes up to 2 months.', null, 'owned', '{}'::text[], array['pork']::text[], array['dairy_free']::text[], array['yellow onion', 'cubanelle pepper', 'garlic', 'cilantro', 'smoked ham', 'seasoning achiote', 'dried oregano', 'tomato sauce', 'green olive', 'caper', 'pigeon pea', 'bay leaf', 'white rice']::text[], 'bay leaf|caper|cilantro|cubanelle pepper|dried oregano|garlic|green olive|pigeon pea|seasoning achiote|smoked ham|tomato sauce|white rice|yellow onion',
