values ('cad94a0d-ed99-42e8-bb6a-2200a9ed10f3', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'tex-mex-cheese-enchiladas-chili-gravy', 'cheese-enchiladas-with-chili-gravy-cad94a', 'Cheese Enchiladas with Chili Gravy', 'Texas cafe-style cheese enchiladas baked under a silky, cumin-scented chili gravy — adapted with vegetable stock and oil instead of the usual beef stock and lard.', 'tex_mex', 1, 20, 35, 55, 4, 'main', null, 0, array['oven', 'stove']::text[], array['comfort', 'kid-friendly', 'budget', 'vegetarian']::text[], array['Many Texas cafes use orange longhorn cheddar or American cheese for an extra-melty filling — use whichever you like.']::text[], 'https://images.pexels.com/photos/35081817/pexels-photo-35081817.jpeg', 'Baked enchiladas with melted cheese and cilantro in a baking dish', 'Zehra Yılmaz', 'https://www.pexels.com/@zehra-yilmaz-407275500/', 'https://www.pexels.com/photo/delicious-baked-enchiladas-with-cheese-topping-35081817/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner', 'budget']::text[], array['stew', 'bake']::text[], array['spicy', 'aromatic']::text[], '{}'::text[], 'Texas', 'adapted', 'cheese-enchiladas', 'classic', 'Refrigerate up to 3 days; reheat covered at 350°F.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['chili powder', 'ground cumin', 'garlic powder', 'mexican oregano', 'vegetable stock', 'corn tortilla', 'cheddar cheese', 'yellow onion']::text[], 'cheddar cheese|chili powder|corn tortilla|garlic powder|ground cumin|mexican oregano|vegetable stock|yellow onion',
  null, null, null, null, null, null, null, null)
