insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('cad94a0d-ed99-42e8-bb6a-2200a9ed10f3', 1, null, 'Heat the oven to 375°F.', null, 190.6, null),
  ('cad94a0d-ed99-42e8-bb6a-2200a9ed10f3', 2, 'Chili gravy', 'Heat the oil in a saucepan over medium heat. Whisk in the flour and cook, stirring, until light tan, 2–3 minutes. Whisk in the chili powder, cumin, garlic powder and oregano for 30 seconds, then slowly whisk in the stock. Simmer until it coats a spoon, 5–8 minutes, and season with the salt.', 600, null, null),
  ('cad94a0d-ed99-42e8-bb6a-2200a9ed10f3', 3, 'Enchiladas', 'Brush the tortillas lightly with oil and warm them in a skillet over medium heat a few seconds per side until soft and bendable. Stack under a towel.', null, null, null),
  ('cad94a0d-ed99-42e8-bb6a-2200a9ed10f3', 4, 'Enchiladas', 'Spread ½ cup gravy over the bottom of a 9-by-13-inch baking dish. Fill each tortilla with about 3 tablespoons cheese and a spoonful of onion, roll up and lay seam-side down in the dish.', null, null, null),
  ('cad94a0d-ed99-42e8-bb6a-2200a9ed10f3', 5, 'Enchiladas', 'Pour the rest of the gravy over and top with the remaining cheese and onion. Bake until bubbling and the cheese has melted, 15–20 minutes.', 1080, 190.6, null),
  ('cad94a0d-ed99-42e8-bb6a-2200a9ed10f3', 6, null, 'Rest 5 minutes and serve with rice and beans.', 300, null, null);

-- Chicken Enchiladas Verdes
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
