values ('549a30bd-5320-4145-88a5-9d9661c2978a', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chilaquiles-rojos', 'chilaquiles-rojos-549a30', 'Chilaquiles Rojos', 'Crisp fried tortilla chips tossed in a smoky guajillo-tomato salsa until just softened at the edges, topped with fried eggs, queso fresco and crema.', 'mexican', 1, 15, 30, 45, 4, 'breakfast', null, 0, array['stove', 'blender']::text[], array['budget', 'vegetarian']::text[], array['Guajillos are mild, fruity dried chiles found in the Latin or spice aisle; 2 dried ancho chiles work too.', 'Short on time? Use 8 oz thick store-bought tortilla chips and skip the frying.']::text[], 'https://images.pexels.com/photos/19842784/pexels-photo-19842784.jpeg', 'Chilaquiles in red sauce topped with a fried egg and cilantro', 'Amar Preciado', 'https://www.pexels.com/@amar/', 'https://www.pexels.com/photo/egg-on-kimchi-in-white-bowl-19842784/', 'pexels', true, 'public', false,
  'pending_review', array['breakfast', 'holiday', 'budget']::text[], array['stew']::text[], array['fresh']::text[], array['brunch-party']::text[], null, 'traditional', 'chilaquiles', 'classic', 'Best eaten right away — the chips go soggy. The salsa keeps 5 days refrigerated.', 'The eggs here aren''t cooked to 160°F. Use pasteurized eggs if you''re serving anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['egg', 'milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['guajillo chile', 'roma tomato', 'white onion', 'garlic', 'corn tortilla', 'egg', 'queso fresco', 'mexican crema', 'cilantro leave']::text[], 'cilantro leave|corn tortilla|egg|garlic|guajillo chile|mexican crema|queso fresco|roma tomato|white onion',
  null, null, null, null, null, null, null, null)
