delete from public.recipe_instructions where recipe_id = '549a30bd-5320-4145-88a5-9d9661c2978a';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('549a30bd-5320-4145-88a5-9d9661c2978a', 1, 'Salsa roja', 'Toast the guajillos in a dry skillet over medium heat, 20–30 seconds per side, until fragrant but not burnt. Soak in hot water for 15 minutes.', 900, null, null),
  ('549a30bd-5320-4145-88a5-9d9661c2978a', 2, 'Salsa roja', 'Meanwhile, char the tomatoes, onion and garlic in the same skillet, turning, until blistered and soft, 8–10 minutes. Peel the garlic.', 540, null, null),
  ('549a30bd-5320-4145-88a5-9d9661c2978a', 3, 'Salsa roja', 'Blend the drained chiles, tomatoes, onion, garlic, water and salt until very smooth.', null, null, null),
  ('549a30bd-5320-4145-88a5-9d9661c2978a', 4, 'Chips', 'Heat ½ inch of oil in a deep skillet to 350°F — keep the pan no more than half full. Fry the tortilla wedges in batches until crisp and golden, 2–3 minutes, then drain on paper towels and sprinkle with salt.', 180, 176.7, null),
  ('549a30bd-5320-4145-88a5-9d9661c2978a', 5, 'Chips', 'Pour off all but 1 tablespoon of the oil. Add the salsa (it will spatter) and simmer 5 minutes until slightly thickened. Add the chips and toss for about 1 minute, until coated and softened at the edges but still a little crunchy.', 360, null, null),
  ('549a30bd-5320-4145-88a5-9d9661c2978a', 6, 'Toppings', 'Meanwhile, fry the eggs in the oil in another skillet until the whites are completely set, 3–4 minutes; cook the yolks firm if you''re serving anyone at higher risk. Pile the chilaquiles onto plates and top each with an egg, queso fresco, crema, onion, cilantro and avocado.', 240, null, null);

