values ('47e0f20c-eb56-4307-b4fe-1aa4179af0cc', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'guacamole', 'guacamole-47e0f2', 'Guacamole', 'Chunky avocado mashed with a pounded paste of onion, chile, cilantro and salt, brightened with lime — the paste spreads the flavor through every bite.', 'mexican', 1, 15, 0, 15, 6, 'starter', null, 0, '{}'::text[], array['vegan', 'entertaining', 'quick']::text[], array['To hold it for up to 2 hours, press plastic wrap directly onto the surface so it doesn''t brown.']::text[], 'https://images.unsplash.com/photo-1680992071073-cb1696ba8d3e', 'Bowl of chunky guacamole with tomato and chilli beside tortilla chips', 'Zoshua Colah', 'https://unsplash.com/@zoshuacolah', 'https://unsplash.com/photos/a-bowl-of-guacamole-next-to-a-bowl-of-tortilla-chips-iiMIegrG3Ag', 'unsplash', true, 'public', false,
  'pending_review', array['appetizer', 'holiday', 'entertaining']::text[], array['no_cook']::text[], array['spicy', 'tangy', 'fresh']::text[], array['game-day']::text[], null, 'traditional', 'guacamole', 'classic', 'Best fresh. Refrigerate up to 1 day with plastic wrap pressed against the surface; scrape off any browned layer before serving.', null, 'owned', '{}'::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], array['white onion', 'jalapeno chile', 'cilantro', 'hass avocado', 'lime juice']::text[], 'cilantro|hass avocado|jalapeno chile|lime juice|white onion',
  null, null, null, null, null, null, null, null)
