values ('194e9362-e6f2-4faf-94f9-894f5410aa08', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'pozole-rojo', 'pozole-rojo-194e93', 'Pozole Rojo', 'A deep red pork and hominy stew built on toasted guajillo and ancho chiles, served with crunchy cabbage, radish, lime and oregano at the table — adapted with canned hominy instead of home-nixtamalized corn.', 'mexican', 3, 40, 180, 220, 8, 'main', null, 0, array['stove', 'dutch_oven', 'blender']::text[], array['entertaining', 'make-ahead', 'freezer-friendly']::text[], array['Pozole tastes even better the next day: chill it overnight, lift off the fat and reheat.']::text[], 'https://images.pexels.com/photos/14179982/pexels-photo-14179982.jpeg', 'Bowl of pozole garnished with shredded lettuce, radish and spices', 'Gonzalo Guzmán García', 'https://www.pexels.com/@gonzalogfg/', 'https://www.pexels.com/photo/soup-in-a-ceramic-bowl-14179982/', 'pexels', true, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'holiday', 'entertaining']::text[], array['stew', 'boil']::text[], array['spicy', 'aromatic']::text[], array['christmas', 'new-year']::text[], 'Jalisco', 'adapted', 'pozole', 'classic', 'Refrigerate up to 4 days or freeze up to 3 months. Keep the garnishes separate.', null, 'owned', '{}'::text[], array['pork']::text[], array['gluten_free', 'dairy_free']::text[], array['pork shoulder', 'white onion', 'garlic', 'bay leave', 'guajillo chile', 'ancho chile', 'mexican oregano', 'ground cumin', 'white hominy', 'green cabbage', 'radishe', 'lime']::text[], 'ancho chile|bay leave|garlic|green cabbage|ground cumin|guajillo chile|lime|mexican oregano|pork shoulder|radishe|white hominy|white onion',
  null, null, null, null, null, null, null, null)
