  ('194e9362-e6f2-4faf-94f9-894f5410aa08', 17, 'To serve', '½ white onion, finely chopped', 'white onion', 0.5, null, 'finely chopped', false),
  ('194e9362-e6f2-4faf-94f9-894f5410aa08', 18, 'To serve', '2 limes, cut into wedges', 'limes', 2, null, 'cut into wedges', false),
  ('194e9362-e6f2-4faf-94f9-894f5410aa08', 19, 'To serve', '2 tbsp dried Mexican oregano', 'dried Mexican oregano', 2, 'tbsp', null, false),
