delete from public.recipe_ingredients where recipe_id = '795104f8-2338-4a89-8191-d23a37d95782';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('795104f8-2338-4a89-8191-d23a37d95782', 1, 'Fries', '2½ lb russet potatoes, cut into ½-inch sticks', 'russet potatoes', 2.5, 'lb', 'cut into ½-inch sticks', false),
  ('795104f8-2338-4a89-8191-d23a37d95782', 2, 'Fries', '3 tbsp vegetable oil', 'vegetable oil', 3, 'tbsp', null, false),
  ('795104f8-2338-4a89-8191-d23a37d95782', 3, 'Fries', '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('795104f8-2338-4a89-8191-d23a37d95782', 4, 'Gravy', '3 tbsp unsalted butter', 'unsalted butter', 3, 'tbsp', null, false),
  ('795104f8-2338-4a89-8191-d23a37d95782', 5, 'Gravy', '1 small shallot, minced', 'small shallot', 1, null, 'minced', false),
  ('795104f8-2338-4a89-8191-d23a37d95782', 6, 'Gravy', '3 tbsp all-purpose flour', 'all-purpose flour', 3, 'tbsp', null, false),
  ('795104f8-2338-4a89-8191-d23a37d95782', 7, 'Gravy', '2½ cups low-sodium beef stock', 'low-sodium beef stock', 2.5, 'cup', null, false),
  ('795104f8-2338-4a89-8191-d23a37d95782', 8, 'Gravy', '½ tsp black pepper', 'black pepper', 0.5, 'tsp', null, false),
  ('795104f8-2338-4a89-8191-d23a37d95782', 9, 'Gravy', '1 tsp apple cider vinegar', 'apple cider vinegar', 1, 'tsp', null, false),
  ('795104f8-2338-4a89-8191-d23a37d95782', 10, 'To serve', '12 oz fresh cheese curds, at room temperature', 'fresh cheese curds', 12, 'oz', 'at room temperature', false);
delete from public.recipe_instructions where recipe_id = '795104f8-2338-4a89-8191-d23a37d95782';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('795104f8-2338-4a89-8191-d23a37d95782', 1, 'Fries', 'Heat the oven to 450°F. Soak the potatoes in hot tap water for 10 minutes, then drain and dry very well.', 600, 232.2, null),
  ('795104f8-2338-4a89-8191-d23a37d95782', 2, 'Fries', 'Toss with the oil and salt and spread in one layer on two parchment-lined sheet pans. Roast, flipping once, until deep golden and crisp, 35–40 minutes.', 2280, 232.2, null),
  ('795104f8-2338-4a89-8191-d23a37d95782', 3, 'Gravy', 'Meanwhile, melt the butter in a saucepan over medium heat and cook the shallot for 2 minutes. Whisk in the flour and cook, stirring, until it turns a nutty light brown, 4–5 minutes.', 420, null, null),
  ('795104f8-2338-4a89-8191-d23a37d95782', 4, 'Gravy', 'Slowly whisk in the stock and simmer until the gravy coats a spoon, 8–10 minutes. Stir in the pepper and vinegar, taste for salt and keep very hot.', 540, null, null),
  ('795104f8-2338-4a89-8191-d23a37d95782', 5, null, 'Pile the hot fries into bowls, scatter the curds over and ladle on the hot gravy so the curds soften but don''t completely melt. Eat right away.', null, null, null);

-- Classic Lasagna Bolognese
