values ('dc595d25-0ab6-4227-923b-f0c7504d964e', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'cacio-e-pepe', 'cacio-e-pepe-dc595d', 'Cacio e Pepe', 'Just pasta, Pecorino Romano and toasted black pepper, tossed with starchy pasta water into a creamy sauce — Rome''s three-ingredient classic.', 'italian', 2, 10, 15, 25, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'pantry', 'vegetarian', 'quick']::text[], array['If the cheese clumps, the pan was too hot: take it off the heat, add a splash of warm water and keep tossing.', 'Pecorino Romano is usually made with animal rennet; for a strictly vegetarian version use a sheep''s-milk cheese labelled vegetarian.']::text[], 'https://images.pexels.com/photos/34797458/pexels-photo-34797458.jpeg', 'Spaghetti cacio e pepe with creamy cheese sauce and cracked black pepper, seen from above', 'Luca Volpe Productions', 'https://www.pexels.com/@luca-volpe-productions-34481466/', 'https://www.pexels.com/photo/cacio-e-pepe-italian-pasta-dish-top-view-34797458/', 'pexels', true, 'public', false,
  'pending_review', array['quick', 'main', 'dinner']::text[], array['boil']::text[], '{}'::text[], '{}'::text[], 'Rome', 'traditional', 'cacio-e-pepe', 'classic', 'Best eaten immediately; the sauce doesn''t reheat well.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['spaghetti', 'romano cheese', 'black peppercorn']::text[], 'black peppercorn|romano cheese|spaghetti',
  null, null, null, null, null, null, null, null)
