  ('dc595d25-0ab6-4227-923b-f0c7504d964e', 1, null, '12 oz spaghetti, or tonnarelli', 'spaghetti', 12, 'oz', 'or tonnarelli', false),
  ('dc595d25-0ab6-4227-923b-f0c7504d964e', 2, null, '2 cups Pecorino Romano cheese, very finely grated (about 5 oz)', 'Pecorino Romano cheese', 2, 'cup', 'very finely grated (about 5 oz)', false),
  ('dc595d25-0ab6-4227-923b-f0c7504d964e', 3, null, '2 tsp black peppercorns, coarsely cracked', 'black peppercorns', 2, 'tsp', 'coarsely cracked', false),
  ('dc595d25-0ab6-4227-923b-f0c7504d964e', 4, null, '1 tbsp kosher salt, for the pasta water', 'kosher salt', 1, 'tbsp', 'for the pasta water', false);
