insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('6008140d-3544-4161-a58e-1f3dafcf3a5e', 1, null, '6 oz guanciale, cut into ¼-inch strips, or pancetta', 'guanciale', 6, 'oz', 'cut into ¼-inch strips, or pancetta', false),
  ('6008140d-3544-4161-a58e-1f3dafcf3a5e', 2, null, '1 tbsp olive oil', 'olive oil', 1, 'tbsp', null, false),
  ('6008140d-3544-4161-a58e-1f3dafcf3a5e', 3, null, '¼ cup dry white wine', 'dry white wine', 0.25, 'cup', null, false),
  ('6008140d-3544-4161-a58e-1f3dafcf3a5e', 4, null, '28 oz canned whole peeled tomatoes, crushed by hand', 'canned whole peeled tomatoes', 28, 'oz', 'crushed by hand', false),
  ('6008140d-3544-4161-a58e-1f3dafcf3a5e', 5, null, '½ tsp red pepper flakes', 'red pepper flakes', 0.5, 'tsp', null, false),
  ('6008140d-3544-4161-a58e-1f3dafcf3a5e', 6, null, '12 oz bucatini, or spaghetti', 'bucatini', 12, 'oz', 'or spaghetti', false),
  ('6008140d-3544-4161-a58e-1f3dafcf3a5e', 7, null, '1 cup Pecorino Romano cheese, finely grated, plus more to serve', 'Pecorino Romano cheese', 1, 'cup', 'finely grated, plus more to serve', false),
  ('6008140d-3544-4161-a58e-1f3dafcf3a5e', 8, null, '1 tbsp kosher salt, for the pasta water', 'kosher salt', 1, 'tbsp', 'for the pasta water', false);
delete from public.recipe_instructions where recipe_id = '6008140d-3544-4161-a58e-1f3dafcf3a5e';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('6008140d-3544-4161-a58e-1f3dafcf3a5e', 1, null, 'Put the guanciale and oil in a cold, wide skillet and set over medium-low heat. Cook, stirring, until the fat has rendered and the strips are golden and crisp at the edges, 8–10 minutes.', 540, null, null),
  ('6008140d-3544-4161-a58e-1f3dafcf3a5e', 2, null, 'Lift out half the guanciale and set aside. Add the wine to the pan and let it bubble until nearly gone, 1 minute.', 60, null, null),
  ('6008140d-3544-4161-a58e-1f3dafcf3a5e', 3, null, 'Add the tomatoes and pepper flakes and simmer until thick, 15 minutes. Taste before salting — the guanciale is salty.', 900, null, null),
  ('6008140d-3544-4161-a58e-1f3dafcf3a5e', 4, null, 'Meanwhile, boil the pasta in salted water until 1 minute short of al dente.', 600, null, null),
  ('6008140d-3544-4161-a58e-1f3dafcf3a5e', 5, null, 'Toss the pasta into the sauce with a splash of pasta water and cook 1 minute. Off the heat, toss in the Pecorino and the reserved guanciale and serve with more cheese.', 60, null, null);

