insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('e8a0f83f-2316-41c7-876e-665159bdd53a', 1, null, 'Pat the chicken dry, season with the salt and pepper and dust lightly with flour.', null, null, null),
  ('e8a0f83f-2316-41c7-876e-665159bdd53a', 2, null, 'Heat the oil in a Dutch oven over medium-high heat. Brown the chicken skin-side down until deep golden, 6–8 minutes, turn for 2 minutes more, then set aside. Pour off all but 2 tablespoons of fat.', 600, null, null),
  ('e8a0f83f-2316-41c7-876e-665159bdd53a', 3, null, 'Add the onion, bell pepper and mushrooms and cook until the mushrooms brown, 8 minutes. Stir in the garlic and rosemary for 1 minute.', 540, null, null),
  ('e8a0f83f-2316-41c7-876e-665159bdd53a', 4, null, 'Pour in the wine and scrape up the browned bits, then add the tomatoes and pepper flakes and bring to a simmer.', null, null, null),
  ('e8a0f83f-2316-41c7-876e-665159bdd53a', 5, null, 'Nestle the chicken in skin-side up, cover partly and simmer gently until the thighs are tender and read at least 165°F (they''re best at 180°F+), 30–35 minutes. Stir in the olives for the last 5 minutes.', 1980, null, 73.9),
  ('e8a0f83f-2316-41c7-876e-665159bdd53a', 6, null, 'Remove the rosemary stems, scatter with parsley and serve with polenta, pasta or crusty bread.', null, null, null);

-- Eggplant Parmigiana
