values ('5acf2450-5f32-49b3-9c9d-693931043f04', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'eggplant-parmigiana', 'eggplant-parmigiana-5acf24', 'Eggplant Parmigiana', 'Layers of tender eggplant, basil-scented tomato sauce, mozzarella and Parmigiano; we roast the slices instead of frying them, which is lighter and far less messy.', 'italian', 3, 40, 75, 115, 6, 'main', null, 0, array['oven', 'stove']::text[], array['vegetarian', 'make-ahead', 'entertaining']::text[], array['Parmigiano-Reggiano is made with animal rennet; use a vegetarian hard cheese if that matters to you.', 'Dry the mozzarella well on paper towels or the dish will be watery.']::text[], 'https://images.unsplash.com/photo-1632229095740-8c75082087c5', 'Baked eggplant parmigiana with tomato sauce in a dish on a wooden table', 'Moira Nazzari', 'https://unsplash.com/@moiranazzari', 'https://unsplash.com/photos/a-dish-of-food-on-a-wooden-table-Y9iaZNbUHtQ', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'entertaining']::text[], array['roast', 'stew', 'pan_fry', 'bake']::text[], array['fresh', 'savory']::text[], '{}'::text[], 'Campania', 'adapted', 'eggplant-parmigiana', 'classic', 'Refrigerate up to 4 days. Reheat covered at 350°F for 20–25 minutes.', null, 'owned', array['milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['eggplant', 'garlic', 'tomato passata', 'basil', 'mozzarella', 'parmigiano-reggiano']::text[], 'basil|eggplant|garlic|mozzarella|parmigiano-reggiano|tomato passata',
  null, null, null, null, null, null, null, null)
