insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('5acf2450-5f32-49b3-9c9d-693931043f04', 1, 'Eggplant', '3 lb eggplants, about 2 large, sliced lengthwise ⅜ inch thick', 'eggplants', 3, 'lb', 'about 2 large, sliced lengthwise ⅜ inch thick', false),
  ('5acf2450-5f32-49b3-9c9d-693931043f04', 2, 'Eggplant', '2 tsp kosher salt', 'kosher salt', 2, 'tsp', null, false),
  ('5acf2450-5f32-49b3-9c9d-693931043f04', 3, 'Eggplant', '½ cup olive oil', 'olive oil', 0.5, 'cup', null, false),
  ('5acf2450-5f32-49b3-9c9d-693931043f04', 4, 'Sauce', '2 tbsp olive oil', 'olive oil', 2, 'tbsp', null, false),
  ('5acf2450-5f32-49b3-9c9d-693931043f04', 5, 'Sauce', '3 cloves garlic, smashed', 'garlic', 3, 'clove', 'smashed', false),
  ('5acf2450-5f32-49b3-9c9d-693931043f04', 6, 'Sauce', '28 oz tomato passata, or crushed tomatoes', 'tomato passata', 28, 'oz', 'or crushed tomatoes', false),
  ('5acf2450-5f32-49b3-9c9d-693931043f04', 7, 'Sauce', '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('5acf2450-5f32-49b3-9c9d-693931043f04', 8, 'Sauce', '1 bunch fresh basil, leaves picked', 'fresh basil', 1, 'bunch', 'leaves picked', false),
