values ('0839e431-e719-40ee-b57c-1cc5505103c5', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'caprese-salad', 'caprese-salad-0839e4', 'Caprese Salad', 'Ripe summer tomatoes, soft fresh mozzarella and basil with good olive oil and salt — simple, so the ingredients have to be great.', 'italian', 1, 10, 0, 10, 4, 'starter', null, 0, '{}'::text[], array['vegetarian', 'quick', 'entertaining']::text[], array['Only make this when tomatoes are in season. Balsamic glaze is an American addition — leave it off for the classic version.']::text[], 'https://images.unsplash.com/photo-1769458313937-b5ad8f84942e', 'Caprese salad of sliced tomatoes, fresh mozzarella and basil leaves', 'Brelyn Bashrum', 'https://unsplash.com/@brelynkk', 'https://unsplash.com/photos/caprese-salad-with-fresh-tomatoes-mozzarella-and-basil-vJ-qtXoD-V8', 'unsplash', true, 'public', false,
  'pending_review', array['salad', 'appetizer', 'entertaining']::text[], array['no_cook']::text[], array['fresh']::text[], '{}'::text[], 'Campania', 'traditional', 'caprese', 'classic', 'Best eaten within an hour of making; don''t refrigerate the assembled salad.', null, 'owned', array['milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['tomato', 'mozzarella', 'basil']::text[], 'basil|mozzarella|tomato',
  null, null, null, null, null, null, null, null)
