insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('0839e431-e719-40ee-b57c-1cc5505103c5', 1, null, 'Take the tomatoes and mozzarella out of the fridge 30 minutes ahead; cold dulls their flavour.', 1800, null, null),
  ('0839e431-e719-40ee-b57c-1cc5505103c5', 2, null, 'Slice the tomatoes about ⅓ inch thick, lay them on a platter and sprinkle with a little of the salt.', null, null, null),
  ('0839e431-e719-40ee-b57c-1cc5505103c5', 3, null, 'Slice or tear the mozzarella and tuck it between the tomatoes with the basil leaves.', null, null, null),
  ('0839e431-e719-40ee-b57c-1cc5505103c5', 4, null, 'Drizzle with the olive oil, finish with the rest of the salt and the pepper, and serve right away.', null, null, null);

