values ('2a442eb1-9f2d-42ed-b5b2-cd34d4b6670e', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'panna-cotta', 'panna-cotta-2a442e', 'Panna Cotta', 'Barely set vanilla cream with a gentle wobble, served with a quick berry sauce — elegant, and made a day ahead.', 'italian', 2, 20, 10, 270, 6, 'dessert', 'plated', 240, array['stove']::text[], array['make-ahead', 'entertaining']::text[], array['For a vegetarian version, replace the gelatin with ¾ tsp agar powder, boiled in the cream mixture for 2 minutes.']::text[], 'https://images.pexels.com/photos/40037724/pexels-photo-40037724.jpeg', 'Panna cotta topped with red berry sauce on a white plate', 'Anete Meira', 'https://www.pexels.com/@anete-meira-1100382961/', 'https://www.pexels.com/photo/delicious-panna-cotta-with-berry-sauce-40037724/', 'pexels', true, 'public', false,
  'pending_review', array['dessert', 'holiday', 'entertaining']::text[], array['stew', 'steam', 'boil']::text[], array['tangy', 'rich', 'sweet']::text[], array['valentines', 'dinner-party']::text[], 'Piedmont', 'traditional', 'panna-cotta', 'classic', 'Keeps 3 days covered in the fridge; add the sauce just before serving.', null, 'owned', array['milk']::text[], '{}'::text[], array['gluten_free']::text[], array['powdered gelatin', 'heavy cream', 'milk', 'vanilla bean', 'mixed berry', 'lemon juice']::text[], 'heavy cream|lemon juice|milk|mixed berry|powdered gelatin|vanilla bean',
  null, null, null, null, null, null, null, null)
