insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('2a442eb1-9f2d-42ed-b5b2-cd34d4b6670e', 1, 'Panna cotta', '3 tbsp cold water', 'cold water', 3, 'tbsp', null, false),
  ('2a442eb1-9f2d-42ed-b5b2-cd34d4b6670e', 2, 'Panna cotta', '2¼ tsp unflavored powdered gelatin, 1 envelope', 'unflavored powdered gelatin', 2.25, 'tsp', '1 envelope', false),
  ('2a442eb1-9f2d-42ed-b5b2-cd34d4b6670e', 3, 'Panna cotta', '2½ cups heavy cream', 'heavy cream', 2.5, 'cup', null, false),
  ('2a442eb1-9f2d-42ed-b5b2-cd34d4b6670e', 4, 'Panna cotta', '1 cup whole milk', 'whole milk', 1, 'cup', null, false),
  ('2a442eb1-9f2d-42ed-b5b2-cd34d4b6670e', 5, 'Panna cotta', '½ cup sugar', 'sugar', 0.5, 'cup', null, false),
  ('2a442eb1-9f2d-42ed-b5b2-cd34d4b6670e', 6, 'Panna cotta', '1 vanilla bean, split, or 2 tsp vanilla extract', 'vanilla bean', 1, null, 'split, or 2 tsp vanilla extract', false),
  ('2a442eb1-9f2d-42ed-b5b2-cd34d4b6670e', 7, 'Berry sauce', '2 cups mixed berries, fresh or frozen', 'mixed berries', 2, 'cup', 'fresh or frozen', false),
  ('2a442eb1-9f2d-42ed-b5b2-cd34d4b6670e', 8, 'Berry sauce', '2 tbsp sugar', 'sugar', 2, 'tbsp', null, false),
  ('2a442eb1-9f2d-42ed-b5b2-cd34d4b6670e', 9, 'Berry sauce', '1 tsp lemon juice', 'lemon juice', 1, 'tsp', null, false);
delete from public.recipe_instructions where recipe_id = '2a442eb1-9f2d-42ed-b5b2-cd34d4b6670e';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('2a442eb1-9f2d-42ed-b5b2-cd34d4b6670e', 1, 'Panna cotta', 'Sprinkle the gelatin over the cold water in a small bowl and leave to soften for 5 minutes.', 300, null, null),
  ('2a442eb1-9f2d-42ed-b5b2-cd34d4b6670e', 2, 'Panna cotta', 'Warm the cream, milk, sugar and vanilla (scrape in the seeds and add the pod) over medium heat, stirring, until steaming and the sugar dissolves, about 5 minutes. Don''t let it boil.', 300, null, null),
  ('2a442eb1-9f2d-42ed-b5b2-cd34d4b6670e', 3, 'Panna cotta', 'Take off the heat, remove the pod and whisk in the softened gelatin until completely dissolved.', null, null, null),
  ('2a442eb1-9f2d-42ed-b5b2-cd34d4b6670e', 4, 'Panna cotta', 'Pour through a fine strainer into a jug, then divide among six ½-cup ramekins or glasses. Cool, cover and chill until set, at least 4 hours.', 14400, null, null),
  ('2a442eb1-9f2d-42ed-b5b2-cd34d4b6670e', 5, 'Berry sauce', 'Simmer the berries, sugar and lemon juice until the berries burst and the juices thicken slightly, 5 minutes. Cool.', 300, null, null),
  ('2a442eb1-9f2d-42ed-b5b2-cd34d4b6670e', 6, null, 'Serve in the glasses, or dip each ramekin in hot water for 10 seconds and turn out onto a plate. Spoon the berry sauce around.', null, null, null);

-- Coq au Vin
