values ('80922e59-bd5e-40ff-a95c-d7a8cf608406', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'coq-au-vin', 'coq-au-vin-80922e', 'Coq au Vin', 'Chicken braised in red Burgundy wine with bacon, mushrooms and little onions; we use chicken thighs instead of the traditional rooster and skip the overnight marinade.', 'french', 3, 30, 90, 120, 6, 'main', null, 0, array['stove', 'oven', 'dutch_oven']::text[], array['comfort', 'entertaining', 'make-ahead']::text[], array['Choose a wine you''d happily drink — a cheap, harsh wine stays harsh. Serve with boiled potatoes, buttered noodles or crusty bread.']::text[], 'https://images.pexels.com/photos/36605449/pexels-photo-36605449.jpeg', 'Coq au vin in dark wine sauce over mashed potatoes, garnished with dill', 'Talha Resitoglu', 'https://www.pexels.com/@talharesitoglu/', 'https://www.pexels.com/photo/delicious-coq-au-vin-served-on-rustic-tile-36605449/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner', 'holiday', 'entertaining']::text[], array['braise', 'stew', 'pan_fry']::text[], array['fresh']::text[], array['dinner-party']::text[], 'Burgundy', 'adapted', 'coq-au-vin', 'classic', 'Refrigerate up to 3 days; the flavour deepens overnight. Reheat gently, covered.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], array['chicken', 'pork']::text[], '{}'::text[], array['thick-cut bacon', 'yellow onion', 'carrot', 'garlic', 'tomato paste', 'red wine', 'chicken stock', 'thyme', 'bay leave', 'cremini mushroom', 'pearl onion', 'parsley']::text[], 'bay leave|carrot|chicken stock|cremini mushroom|garlic|parsley|pearl onion|red wine|thick-cut bacon|thyme|tomato paste|yellow onion',
  null, null, null, null, null, null, null, null)
