values ('97e7a0cb-0be5-4f39-ab9c-c7c88ab15d94', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'beef-bourguignon', 'beef-bourguignon-97e7a0', 'Beef Bourguignon', 'Chunks of beef chuck slowly braised in red wine with bacon, mushrooms and pearl onions until spoon-tender, in a deep, glossy sauce.', 'french', 3, 40, 200, 240, 6, 'main', null, 0, array['stove', 'oven', 'dutch_oven']::text[], array['comfort', 'entertaining', 'make-ahead', 'freezer-friendly']::text[], array['Drying the beef well and browning in batches is what gives the sauce its depth — don''t rush it.']::text[], 'https://images.pexels.com/photos/3981486/pexels-photo-3981486.jpeg', 'Braised beef stew with tender meat and root vegetables on a white plate', 'tomateoignons', 'https://www.pexels.com/@tomateoignons/', 'https://www.pexels.com/photo/cooked-food-on-white-ceramic-plate-3981486/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner', 'holiday', 'entertaining']::text[], array['braise', 'stew', 'pan_fry']::text[], array['fresh']::text[], array['dinner-party', 'christmas']::text[], 'Burgundy', 'traditional', 'beef-bourguignon', 'classic', 'Refrigerate up to 4 days or freeze up to 3 months. Better made a day ahead; skim the fat off the cold stew.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], array['beef', 'pork']::text[], '{}'::text[], array['chuck roast', 'thick-cut bacon', 'yellow onion', 'carrot', 'garlic', 'tomato paste', 'red wine', 'beef stock', 'thyme', 'bay leave', 'cremini mushroom', 'pearl onion', 'parsley']::text[], 'bay leave|beef stock|carrot|chuck roast|cremini mushroom|garlic|parsley|pearl onion|red wine|thick-cut bacon|thyme|tomato paste|yellow onion',
  null, null, null, null, null, null, null, null)
