values ('775bca84-b8cb-464b-99c6-33dd335815ec', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'ratatouille', 'ratatouille-775bca', 'Ratatouille', 'Eggplant, zucchini, peppers and onion each cooked in olive oil, then gently stewed with tomatoes and herbs so every vegetable keeps its own flavour.', 'french', 2, 30, 60, 90, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['vegan', 'make-ahead', 'budget']::text[], array['Serve it with crusty bread, over polenta or with a fried egg on top for non-vegan eaters.']::text[], 'https://images.unsplash.com/photo-1652622550740-f90d03edfbf0', 'Pan of ratatouille with layered sliced vegetables on a wooden table', 'Marjan Sadeghi', 'https://unsplash.com/@marijeane', 'https://unsplash.com/photos/a-pan-filled-with-sliced-up-vegetables-on-top-of-a-wooden-table-3vDJ--i7w88', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'budget']::text[], array['stew', 'pan_fry']::text[], array['fresh']::text[], '{}'::text[], 'Provence', 'traditional', 'ratatouille', 'classic', 'Refrigerate up to 5 days; it''s even better the next day. Freezes well for 3 months.', null, 'owned', '{}'::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], array['eggplant', 'zucchini', 'bell pepper', 'yellow onion', 'garlic', 'canned tomato', 'thyme', 'bay leaf', 'basil leave']::text[], 'basil leave|bay leaf|bell pepper|canned tomato|eggplant|garlic|thyme|yellow onion|zucchini',
  null, null, null, null, null, null, null, null)
