  ('775bca84-b8cb-464b-99c6-33dd335815ec', 1, null, '1¼ lb eggplant, cut into ¾-inch cubes', 'eggplant', 1.25, 'lb', 'cut into ¾-inch cubes', false),
  ('775bca84-b8cb-464b-99c6-33dd335815ec', 2, null, '2 zucchini, cut into ¾-inch pieces', 'zucchini', 2, null, 'cut into ¾-inch pieces', false),
  ('775bca84-b8cb-464b-99c6-33dd335815ec', 3, null, '2 red bell peppers, cut into ¾-inch pieces', 'red bell peppers', 2, null, 'cut into ¾-inch pieces', false),
  ('775bca84-b8cb-464b-99c6-33dd335815ec', 4, null, '1 large yellow onion, chopped', 'large yellow onion', 1, null, 'chopped', false),
  ('775bca84-b8cb-464b-99c6-33dd335815ec', 5, null, '4 cloves garlic, sliced', 'garlic', 4, 'clove', 'sliced', false),
