insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('775bca84-b8cb-464b-99c6-33dd335815ec', 1, null, 'Heat 3 tablespoons of oil in a large skillet over medium-high heat. Brown the eggplant with a pinch of salt until golden and soft, 8–10 minutes; transfer to a bowl.', 540, null, null),
  ('775bca84-b8cb-464b-99c6-33dd335815ec', 2, null, 'Add 2 tablespoons of oil and cook the zucchini until lightly browned but still firm, 5 minutes; add to the bowl. Repeat with the peppers, 6 minutes.', 660, null, null),
  ('775bca84-b8cb-464b-99c6-33dd335815ec', 3, null, 'In a Dutch oven, warm the remaining oil and cook the onion over medium heat until soft and golden, 8 minutes. Add the garlic for 1 minute.', 540, null, null),
  ('775bca84-b8cb-464b-99c6-33dd335815ec', 4, null, 'Add the tomatoes, thyme, bay and remaining salt and simmer until thick, 10 minutes.', 600, null, null),
  ('775bca84-b8cb-464b-99c6-33dd335815ec', 5, null, 'Stir in the cooked vegetables, cover and simmer very gently, stirring now and then, until everything is tender and the flavours meld, 20–25 minutes.', 1320, null, null),
  ('775bca84-b8cb-464b-99c6-33dd335815ec', 6, null, 'Remove the herb stems and bay, season with pepper, stir in the basil and serve warm or at room temperature.', null, null, null);

-- French Onion Soup
