insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('36df9616-7e74-4f27-9c37-8ff2c3b002e8', 1, null, 'Melt the butter with the oil in a Dutch oven over medium heat. Add the onions and salt, cover and cook, stirring occasionally, until they collapse, 15 minutes.', 900, null, null),
  ('36df9616-7e74-4f27-9c37-8ff2c3b002e8', 2, null, 'Uncover, turn the heat to medium-low and keep cooking, stirring and scraping every few minutes, until the onions are a deep chestnut brown and jammy, 45–60 minutes. Add a splash of water if they start to catch.', 3000, null, null),
  ('36df9616-7e74-4f27-9c37-8ff2c3b002e8', 3, null, 'Stir in the flour for 1 minute, then add the wine and let it bubble away, scraping up the browned layer on the bottom.', 120, null, null),
  ('36df9616-7e74-4f27-9c37-8ff2c3b002e8', 4, null, 'Add the stock, thyme and bay and simmer 20 minutes. Taste and season with salt and pepper; discard the herbs.', 1200, null, null),
  ('36df9616-7e74-4f27-9c37-8ff2c3b002e8', 5, null, 'Meanwhile, toast the baguette slices on a sheet pan at 400°F until dry and golden, 8 minutes.', 480, 204.4, null),
  ('36df9616-7e74-4f27-9c37-8ff2c3b002e8', 6, null, 'Set four ovenproof bowls on a sheet pan and fill with soup. Float two toasts in each, cover with Gruyère and broil until bubbling and browned, 3–5 minutes. Warn everyone that the bowls are very hot.', 240, null, null);

