values ('ced05ff4-4800-47ad-b007-f6924a6562f6', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'quiche-lorraine', 'quiche-lorraine-ced05f', 'Quiche Lorraine', 'A crisp pastry shell filled with smoky bacon and a silky egg-and-cream custard; we use a store-bought pie crust to save time.', 'french', 2, 25, 70, 95, 6, 'main', null, 0, array['oven', 'stove']::text[], array['make-ahead', 'entertaining']::text[], array['The Lorraine original has no cheese; add ¾ cup grated Gruyère with the bacon if you like it cheesy.']::text[], 'https://images.unsplash.com/photo-1767065584177-9ceb902eec7a', 'Slice of savory quiche with a golden crust and a side salad', 'Diego Arenas de Rodrigo', 'https://unsplash.com/@diegoarenasderodrigo', 'https://unsplash.com/photos/slice-of-quiche-with-a-side-salad-qr-8HqqjqGQ', 'unsplash', true, 'public', false,
  'pending_review', array['baking', 'main', 'dinner', 'holiday', 'entertaining']::text[], array['bake']::text[], array['rich']::text[], array['mothers-day', 'easter', 'brunch-party']::text[], 'Lorraine', 'adapted', 'quiche-lorraine', 'classic', 'Refrigerate up to 3 days. Serve cold or reheat slices at 325°F for 10–15 minutes.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], array['pork']::text[], '{}'::text[], array['pie crust', 'thick-cut bacon', 'egg', 'egg yolk', 'heavy cream', 'milk', 'ground nutmeg']::text[], 'egg|egg yolk|ground nutmeg|heavy cream|milk|pie crust|thick-cut bacon',
