  ('ced05ff4-4800-47ad-b007-f6924a6562f6', 1, null, '1 refrigerated pie crust, for a 9-inch pie plate', 'refrigerated pie crust', 1, null, 'for a 9-inch pie plate', false),
  ('ced05ff4-4800-47ad-b007-f6924a6562f6', 2, null, '8 oz thick-cut bacon, cut into ½-inch pieces', 'thick-cut bacon', 8, 'oz', 'cut into ½-inch pieces', false),
