  ('60a0284c-98c8-45af-aabc-76c50b174782', 1, null, '2 cups heavy cream', 'heavy cream', 2, 'cup', null, false),
  ('60a0284c-98c8-45af-aabc-76c50b174782', 2, null, '1 vanilla bean, split, or 1½ tsp vanilla extract', 'vanilla bean', 1, null, 'split, or 1½ tsp vanilla extract', false),
  ('60a0284c-98c8-45af-aabc-76c50b174782', 3, null, '5 large egg yolks', 'large egg yolks', 5, null, null, false),
  ('60a0284c-98c8-45af-aabc-76c50b174782', 4, null, '⅓ cup sugar', 'sugar', 0.33, 'cup', null, false),
  ('60a0284c-98c8-45af-aabc-76c50b174782', 5, null, '1 pinch kosher salt', 'kosher salt', 1, 'pinch', null, false),
  ('60a0284c-98c8-45af-aabc-76c50b174782', 6, null, '4 tsp sugar, or turbinado sugar, for the topping', 'sugar', 4, 'tsp', 'or turbinado sugar, for the topping', false);
delete from public.recipe_instructions where recipe_id = '60a0284c-98c8-45af-aabc-76c50b174782';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('60a0284c-98c8-45af-aabc-76c50b174782', 1, null, 'Heat the oven to 325°F and set four 6-ounce ramekins in a roasting pan. Put a kettle of water on to boil.', null, 162.8, null),
  ('60a0284c-98c8-45af-aabc-76c50b174782', 2, null, 'Warm the cream with the vanilla seeds and pod until steaming, then cover and steep 10 minutes off the heat.', 900, null, null),
  ('60a0284c-98c8-45af-aabc-76c50b174782', 3, null, 'Whisk the yolks, ⅓ cup sugar and salt just until combined. Slowly whisk in the warm cream, then strain into a jug and skim off any foam.', null, null, null),
  ('60a0284c-98c8-45af-aabc-76c50b174782', 4, null, 'Divide among the ramekins. Pour hot water into the pan to come halfway up their sides.', null, null, null),
  ('60a0284c-98c8-45af-aabc-76c50b174782', 5, null, 'Bake until the custards are set at the edges with a slight jiggle in the center and read 170–175°F (safely past 160°F), 35–40 minutes. Lift out of the water and cool.', 2280, 162.8, 71.1),
  ('60a0284c-98c8-45af-aabc-76c50b174782', 6, null, 'Cover and chill until cold, at least 4 hours.', 14400, null, null),
  ('60a0284c-98c8-45af-aabc-76c50b174782', 7, null, 'Just before serving, blot any moisture, sprinkle each with 1 tsp sugar in an even layer and melt with a kitchen torch until deep amber. Let the caramel harden 2 minutes.', null, null, null);

