values ('69253a44-483f-4375-ac70-2d03d06bcf0c', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'patatas-bravas', 'patatas-bravas-69253a', 'Patatas Bravas', 'Crisp fried potatoes with a smoky pimentón sauce and a garlic mayo; we make the garlic sauce from store-bought mayonnaise instead of hand-whisked allioli.', 'spanish', 2, 15, 35, 50, 4, 'starter', null, 0, array['stove', 'dutch_oven']::text[], array['vegetarian', 'entertaining']::text[], array['To skip frying, toss the parboiled potatoes with 3 tbsp olive oil and roast at 450°F for 30–35 minutes, turning once.']::text[], 'https://images.pexels.com/photos/28490819/pexels-photo-28490819.jpeg', 'Patatas bravas with spicy sauce and garlic aioli in a blue bowl', 'Nano Erdozain', 'https://www.pexels.com/@nano-erdozain-120534369/', 'https://www.pexels.com/photo/delicious-patatas-bravas-with-spicy-sauce-28490819/', 'pexels', true, 'public', false,
  'pending_review', array['appetizer', 'entertaining']::text[], array['stew', 'fry', 'steam', 'boil']::text[], array['spicy', 'smoky', 'tangy']::text[], '{}'::text[], 'Madrid', 'adapted', 'patatas-bravas', 'classic', 'The potatoes are best fresh. Both sauces keep 4 days in the fridge.', null, 'owned', array['egg', 'gluten', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'dairy_free']::text[], array['gold potato', 'smoked paprika', 'vegetable broth', 'sherry vinegar', 'mayonnaise', 'garlic', 'lemon juice']::text[], 'garlic|gold potato|lemon juice|mayonnaise|sherry vinegar|smoked paprika|vegetable broth',
  null, null, null, null, null, null, null, null)
