insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('69253a44-483f-4375-ac70-2d03d06bcf0c', 1, 'Potatoes', 'Cover the potatoes with cold salted water, bring to a boil and simmer until just tender at the edges, 6–8 minutes. Drain and let them steam dry on a towel for 10 minutes.', 1080, null, null),
  ('69253a44-483f-4375-ac70-2d03d06bcf0c', 2, 'Brava sauce', 'Warm the olive oil in a small pan, stir in the flour and both paprikas for 30 seconds, then whisk in the broth. Simmer until it thickens, 5 minutes. Season with the vinegar and salt.', 300, null, null),
  ('69253a44-483f-4375-ac70-2d03d06bcf0c', 3, 'Garlic mayo', 'Stir the mayonnaise, garlic, lemon juice and olive oil together. Chill until needed.', null, null, null),
  ('69253a44-483f-4375-ac70-2d03d06bcf0c', 4, 'Potatoes', 'Heat the oil to 375°F in a heavy pot, filled no more than halfway, with a thermometer clipped to the side. Keep children and pets away and never leave hot oil unattended.', null, 190.6, null),
  ('69253a44-483f-4375-ac70-2d03d06bcf0c', 5, 'Potatoes', 'Fry the potatoes in 2 batches until deep golden and crisp, 5–7 minutes per batch. Lift out with a spider, drain on a rack and salt right away.', 720, 190.6, null),
  ('69253a44-483f-4375-ac70-2d03d06bcf0c', 6, null, 'Pile the potatoes on a plate, spoon over the brava sauce and dot with the garlic mayo. Serve hot with toothpicks.', null, null, null);

