values ('7d326de0-e1d5-4bb8-99be-9a47e272524d', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'gambas-al-ajillo', 'gambas-al-ajillo-7d326d', 'Gambas al Ajillo', 'Shrimp sizzled in plenty of olive oil with sliced garlic and chili, served bubbling with bread to mop up the oil.', 'spanish', 1, 15, 8, 23, 4, 'starter', null, 0, array['stove', 'cast_iron']::text[], array['quick', 'entertaining']::text[], array['Watch the garlic closely — once it turns brown it''s bitter, so start again rather than serve it.']::text[], 'https://images.pexels.com/photos/19393934/pexels-photo-19393934.jpeg', 'Shrimp cooked in garlic oil and sprinkled with chopped parsley', 'PIXAMD AMX', 'https://www.pexels.com/@pixamd/', 'https://www.pexels.com/photo/fried-shrimps-in-garlic-sauce-sprinkled-with-parsley-19393934/', 'pexels', true, 'public', false,
  'pending_review', array['appetizer', 'entertaining']::text[], '{}'::text[], array['spicy', 'smoky', 'tangy', 'fresh']::text[], '{}'::text[], null, 'traditional', 'gambas-al-ajillo', 'classic', 'Best eaten right away. Leftovers keep 1 day in the fridge.', null, 'owned', array['gluten', 'shellfish', 'wheat']::text[], array['shellfish']::text[], array['pescatarian', 'dairy_free']::text[], array['shrimp', 'garlic', 'pepper flake', 'smoked paprika', 'lemon juice', 'parsley', 'baguette']::text[], 'baguette|garlic|lemon juice|parsley|pepper flake|shrimp|smoked paprika',
