values ('8e8ff250-076e-4240-87fa-184c1676dc27', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'tortilla-espanola', 'tortilla-espanola-8e8ff2', 'Tortilla Española', 'Thin-sliced potatoes and onion slowly poached in olive oil, then set in eggs into a thick, tender cake that''s good hot or at room temperature.', 'spanish', 2, 20, 40, 60, 6, 'starter', null, 0, array['stove']::text[], array['vegetarian', 'budget', 'make-ahead']::text[], array['In Spain many like the center still soft (jugosa); if you cook it that way, use pasteurized eggs for anyone pregnant, very young, older or with a weakened immune system.', 'Keep the strained oil — it''s full of flavour for frying eggs or roasting potatoes.']::text[], 'https://images.pexels.com/photos/4765652/pexels-photo-4765652.jpeg', 'Slices of Spanish potato tortilla on a wooden board with basil', 'Maxi Gagliano', 'https://www.pexels.com/@maxi-gagliano-1882897/', 'https://www.pexels.com/photo/overhead-shot-of-a-slice-of-spanish-omelet-4765652/', 'pexels', true, 'public', false,
