  ('8e8ff250-076e-4240-87fa-184c1676dc27', 1, null, '1½ lb Yukon Gold potatoes, peeled, quartered and thinly sliced', 'Yukon Gold potatoes', 1.5, 'lb', 'peeled, quartered and thinly sliced', false),
  ('8e8ff250-076e-4240-87fa-184c1676dc27', 2, null, '1 yellow onion, thinly sliced', 'yellow onion', 1, null, 'thinly sliced', false),
  ('8e8ff250-076e-4240-87fa-184c1676dc27', 3, null, '1½ cups olive oil', 'olive oil', 1.5, 'cup', null, false),
  ('8e8ff250-076e-4240-87fa-184c1676dc27', 4, null, '1¼ tsp kosher salt, divided', 'kosher salt', 1.25, 'tsp', 'divided', false),
  ('8e8ff250-076e-4240-87fa-184c1676dc27', 5, null, '6 large eggs', 'large eggs', 6, null, null, false);
delete from public.recipe_instructions where recipe_id = '8e8ff250-076e-4240-87fa-184c1676dc27';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('8e8ff250-076e-4240-87fa-184c1676dc27', 1, null, 'Warm the oil in a 10-inch nonstick skillet over medium-low heat. Add the potatoes, onion and ½ tsp salt; the oil should barely bubble. Cook, turning gently now and then, until the potatoes are tender but not browned, 20–25 minutes.', 1320, null, null),
  ('8e8ff250-076e-4240-87fa-184c1676dc27', 2, null, 'Drain through a sieve set over a bowl, saving the oil.', null, null, null),
  ('8e8ff250-076e-4240-87fa-184c1676dc27', 3, null, 'Beat the eggs with the remaining salt in a large bowl. Fold in the warm potatoes and onion, pressing lightly, and let stand 10 minutes so the potatoes soak up the egg.', 600, null, null),
  ('8e8ff250-076e-4240-87fa-184c1676dc27', 4, null, 'Wipe out the skillet, heat 2 tablespoons of the saved oil over medium heat and pour in the mixture, smoothing the top. Cook, shaking the pan and tucking in the edges, until the bottom is golden and the sides are set, 6–8 minutes.', 420, null, null),
  ('8e8ff250-076e-4240-87fa-184c1676dc27', 5, null, 'Set a large flat plate over the pan and, holding both firmly with oven mitts, flip the tortilla onto it. Slide it back into the pan, uncooked side down.', null, null, null),
  ('8e8ff250-076e-4240-87fa-184c1676dc27', 6, null, 'Cook until the bottom is golden and the center is set and reads 160°F, 4–6 minutes. Slide onto a plate and rest 5 minutes before cutting into wedges.', 300, null, 71.1);

