values ('ac89debb-4fb6-472e-9bdf-1dae0e5c3c6b', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'gazpacho', 'gazpacho-ac89de', 'Gazpacho', 'A chilled, blended soup of ripe tomatoes, cucumber, pepper, garlic, bread and olive oil — bright and refreshing on hot days.', 'spanish', 1, 20, 0, 140, 4, 'main', null, 120, array['blender']::text[], array['vegan', 'make-ahead', 'budget']::text[], array['Taste your tomatoes first: if they''re not sweet and ripe, add a pinch of sugar or wait for summer.']::text[], 'https://images.pexels.com/photos/38238825/pexels-photo-38238825.jpeg', 'Chilled tomato gazpacho served in a clear glass with a green garnish', 'Alena Evseenko', 'https://www.pexels.com/@alena-evseenko-660538512/', 'https://www.pexels.com/photo/refreshing-gazpacho-in-a-glass-38238825/', 'pexels', true, 'public', false,
