values ('fc335d34-3eb8-4a19-8ed9-e5689400c294', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-souvlaki', 'chicken-souvlaki-fc335d', 'Chicken Souvlaki', 'Lemon, garlic and oregano–marinated chicken skewers grilled until charred, tucked into warm pita with tomato, onion and tzatziki.', 'greek', 2, 25, 12, 37, 4, 'main', null, 0, array['grill']::text[], array['kid-friendly', 'weeknight']::text[], array['No grill? Cook the skewers on a grill pan or under the broiler, turning, for about the same time.']::text[], 'https://images.unsplash.com/photo-1789639251460-c3645a8f138a', 'Grilled chicken skewers with bell peppers and french fries on a round plate', 'Paras Kapoor', 'https://unsplash.com/@kapoorparas28', 'https://unsplash.com/photos/chicken-skewers-with-fries-dinner-Evr53xTGQI4', 'unsplash', true, 'public', false,
