insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('fc335d34-3eb8-4a19-8ed9-e5689400c294', 1, 'Skewers', 'Whisk the oil, lemon zest and juice, garlic, oregano, salt and pepper. Toss with the chicken and marinate in the fridge 1–4 hours. Soak wooden skewers in water for 30 minutes.', 3600, null, null),
  ('fc335d34-3eb8-4a19-8ed9-e5689400c294', 2, 'Skewers', 'Heat a grill to medium-high (about 450°F) and oil the grates. Thread the chicken snugly onto the skewers.', null, 232.2, null),
  ('fc335d34-3eb8-4a19-8ed9-e5689400c294', 3, 'Skewers', 'Grill, turning every 2–3 minutes, until charred in spots and the chicken reads 165°F, 10–12 minutes.', 660, null, 73.9),
  ('fc335d34-3eb8-4a19-8ed9-e5689400c294', 4, 'To serve', 'Warm the pitas on the grill for 30 seconds a side.', null, null, null),
  ('fc335d34-3eb8-4a19-8ed9-e5689400c294', 5, null, 'Slide the chicken off the skewers into the pitas with tomato, onion and a spoonful of tzatziki. Serve with lemon wedges.', null, null, null);

