  ('5fc55885-9d3c-4053-afab-38a148fda116', 1, null, '1 cucumber, unpeeled, coarsely grated', 'cucumber', 1, null, 'unpeeled, coarsely grated', false),
  ('5fc55885-9d3c-4053-afab-38a148fda116', 2, null, '¾ tsp kosher salt, divided', 'kosher salt', 0.75, 'tsp', 'divided', false),
