insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('ef18a30f-9813-416c-aeb7-fc5cc574da23', 1, 'Topping', 'Cover the potatoes with cold salted water, bring to a boil and simmer until very tender, 15–20 minutes. Drain well, return to the pot to steam dry for a minute, then mash with the butter, milk and salt.', 1200, null, null),
  ('ef18a30f-9813-416c-aeb7-fc5cc574da23', 2, 'Filling', 'Meanwhile, heat the oil in a large skillet over medium-high heat. Brown the lamb, breaking it up, until no pink remains and it reaches 160°F, 8 minutes. Spoon off all but 1 tablespoon of fat.', 480, null, 71.1),
  ('ef18a30f-9813-416c-aeb7-fc5cc574da23', 3, 'Filling', 'Add the onion and carrots and cook until soft, 6 minutes. Stir in the garlic, tomato paste and flour for 1 minute.', 420, null, null),
  ('ef18a30f-9813-416c-aeb7-fc5cc574da23', 4, 'Filling', 'Stir in the stock, Worcestershire, thyme and salt and simmer until thick and gravy-like, 10 minutes. Stir in the peas.', 600, null, null),
  ('ef18a30f-9813-416c-aeb7-fc5cc574da23', 5, null, 'Heat the oven to 400°F. Spread the filling in a 2½-quart baking dish, spoon the mash over and rough up the top with a fork.', null, 204.4, null),
  ('ef18a30f-9813-416c-aeb7-fc5cc574da23', 6, null, 'Set the dish on a sheet pan and bake until bubbling at the edges and golden on top, 25–30 minutes. Rest 10 minutes before serving.', 1680, 204.4, null);

