values ('51d63e9a-e0ea-4252-b05b-457b4b0603f5', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'sticky-toffee-pudding', 'sticky-toffee-pudding-51d63e', 'Sticky Toffee Pudding', 'A moist date sponge soaked in warm butterscotch-like toffee sauce — Britain''s favourite pudding, made in one pan.', 'british', 2, 25, 40, 65, 9, 'dessert', 'cakes', 0, array['oven', 'stove']::text[], array['comfort', 'make-ahead', 'entertaining']::text[], array['Mashing the soaked dates with a fork gives a smoother crumb; leave them chunky if you like bits of fruit.']::text[], 'https://images.pexels.com/photos/5419205/pexels-photo-5419205.jpeg', 'Sticky toffee pudding with toffee sauce and pecans on a rustic wooden table', 'Polina Tankilevitch', 'https://www.pexels.com/@polina-tankilevitch/', 'https://www.pexels.com/photo/pudding-cake-with-toffee-icing-and-sprinkled-with-chopped-dates-5419205/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'dessert', 'baking', 'holiday', 'entertaining']::text[], array['bake', 'boil']::text[], array['rich', 'sweet']::text[], array['christmas']::text[], null, 'traditional', 'sticky-toffee-pudding', 'classic', 'Keeps 3 days covered in the fridge, or freeze the pudding up to 2 months. Rewarm slices with sauce in the microwave or a low oven.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['medjool date', 'boiling water', 'baking soda', 'baking powder', 'brown sugar', 'egg', 'vanilla extract', 'heavy cream']::text[], 'baking powder|baking soda|boiling water|brown sugar|egg|heavy cream|medjool date|vanilla extract',
  null, null, null, null, null, null, null, null)
