insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('51d63e9a-e0ea-4252-b05b-457b4b0603f5', 1, 'Pudding', 'Heat the oven to 350°F and butter an 8-inch square baking pan. Pour the boiling water over the dates, stir in the baking soda and leave 10 minutes.', 600, 176.7, null),
  ('51d63e9a-e0ea-4252-b05b-457b4b0603f5', 2, 'Pudding', 'Whisk the flour, baking powder and salt. In another bowl, beat the butter and brown sugar until fluffy, then beat in the eggs one at a time and the vanilla.', null, null, null),
  ('51d63e9a-e0ea-4252-b05b-457b4b0603f5', 3, 'Pudding', 'Fold in the flour, then the dates and their liquid, to a loose batter. Pour into the pan.', null, null, null),
  ('51d63e9a-e0ea-4252-b05b-457b4b0603f5', 4, 'Pudding', 'Bake until risen and a skewer in the center comes out clean, 30–35 minutes.', 1920, 176.7, null),
  ('51d63e9a-e0ea-4252-b05b-457b4b0603f5', 5, 'Toffee sauce', 'Meanwhile, melt the butter, sugar and half the cream in a saucepan, then boil gently, stirring, until dark and glossy, 3–4 minutes. Off the heat, stir in the remaining cream and the salt.', 300, null, null),
  ('51d63e9a-e0ea-4252-b05b-457b4b0603f5', 6, null, 'Poke holes all over the warm pudding with a skewer and pour over a third of the sauce. Let it soak in 10 minutes, then cut into squares and serve with the remaining warm sauce and cream or vanilla ice cream.', 600, null, null);

