values ('f1cca7ca-f073-4d28-8d4b-73d8950f4fdf', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'swedish-meatballs', 'swedish-meatballs-f1cca7', 'Swedish Meatballs', 'Small, tender beef and pork meatballs warmed with allspice and nutmeg, in a creamy brown gravy with lingonberry jam on the side.', 'scandinavian', 2, 30, 30, 60, 6, 'main', null, 0, array['stove']::text[], array['comfort', 'kid-friendly', 'freezer-friendly']::text[], array['Lingonberry jam is sold at IKEA and many supermarkets; whole-berry cranberry sauce is a good stand-in.']::text[], 'https://images.unsplash.com/photo-1712594533988-13a401974b44', 'Swedish meatballs with mashed potatoes, pickled cucumber and berries on a white plate', 'Divya Kothari', 'https://unsplash.com/@dk_photos', 'https://unsplash.com/photos/a-white-plate-topped-with-meatballs-mashed-potatoes-and-cucumbers-2Pme_wbWkxU', 'unsplash', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner', 'holiday']::text[], array['stew', 'pan_fry', 'boil']::text[], array['rich', 'savory', 'aromatic']::text[], array['christmas']::text[], 'Sweden', 'traditional', 'swedish-meatballs', 'classic', 'Refrigerate in the gravy up to 3 days, or freeze the browned meatballs (without gravy) up to 3 months.', null, 'owned', array['egg', 'gluten', 'milk', 'soy', 'wheat']::text[], array['beef', 'pork']::text[], '{}'::text[], array['dry breadcrumb', 'milk', 'yellow onion', 'ground beef', 'ground pork', 'egg', 'ground allspice', 'ground nutmeg', 'white pepper', 'beef stock', 'heavy cream', 'soy sauce', 'lingonberry jam']::text[], 'beef stock|dry breadcrumb|egg|ground allspice|ground beef|ground nutmeg|ground pork|heavy cream|lingonberry jam|milk|soy sauce|white pepper|yellow onion',
  null, null, null, null, null, null, null, null)
