insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('f1cca7ca-f073-4d28-8d4b-73d8950f4fdf', 1, 'Meatballs', 'Soak the breadcrumbs in the milk for 5 minutes. Melt 1 tablespoon butter in a large skillet and cook the onion until soft, 5 minutes; let cool.', 300, null, null),
  ('f1cca7ca-f073-4d28-8d4b-73d8950f4fdf', 2, 'Meatballs', 'Mix the beef, pork, soaked crumbs, onion, egg, salt and spices with your hands until just combined. With wet hands, roll into 1-inch balls (about 36).', null, null, null),
  ('f1cca7ca-f073-4d28-8d4b-73d8950f4fdf', 3, 'Meatballs', 'Melt the remaining butter in the skillet over medium heat. Brown the meatballs in batches, shaking the pan, until browned all over and cooked through to 160°F, 8–10 minutes per batch. Set aside.', 1080, null, 71.1),
  ('f1cca7ca-f073-4d28-8d4b-73d8950f4fdf', 4, 'Gravy', 'Whisk the flour into the fat in the pan and cook 1 minute. Gradually whisk in the stock and simmer, scraping up the browned bits, until thickened, 3–4 minutes.', 300, null, null),
  ('f1cca7ca-f073-4d28-8d4b-73d8950f4fdf', 5, 'Gravy', 'Stir in the cream and soy sauce and season to taste. Return the meatballs and simmer gently to heat through, 3 minutes.', 180, null, null),
  ('f1cca7ca-f073-4d28-8d4b-73d8950f4fdf', 6, null, 'Serve with mashed or boiled potatoes, lingonberry jam and quick-pickled cucumbers.', null, null, null);

