values ('c6462762-4974-4ed2-b3b4-15d5ed8b8a85', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'beef-kofta-kebabs', 'beef-kofta-kebabs-c64627', 'Beef Kofta Kebabs', 'Juicy spiced beef pressed onto skewers with onion, parsley and warm spices, grilled until charred and served with a lemony tahini sauce.', 'middle_eastern', 2, 25, 12, 37, 4, 'main', null, 0, array['grill']::text[], array['weeknight', 'entertaining', 'high-protein']::text[], array['No grill? Cook the kofta on a grill pan, or under the broiler about 4 inches from the heat, turning once.', 'Squeezing the grated onion dry keeps the kofta from falling off the skewers.']::text[], 'https://images.pexels.com/photos/32986492/pexels-photo-32986492.jpeg', 'Grilled kofta kebabs on a plate with fresh vegetables and fries', 'J KREATOR', 'https://www.pexels.com/@jkreat0r/', 'https://www.pexels.com/photo/middle-eastern-kofta-kebab-plate-with-vegetables-32986492/', 'pexels', true, 'public', false,
  'pending_review', array['grilling', 'main', 'dinner', 'entertaining']::text[], array['grill']::text[], array['tangy', 'fresh', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'kofta-kebab', 'classic', 'Refrigerate cooked kofta up to 3 days. Shaped, uncooked kofta freeze well for up to 3 months.', null, 'owned', array['gluten', 'sesame', 'wheat']::text[], array['beef']::text[], array['dairy_free']::text[], array['ground beef', 'onion', 'garlic', 'parsley', 'ground cumin', 'ground coriander', 'sweet paprika', 'ground allspice', 'ground cinnamon', 'tahini', 'lemon', 'pita bread', 'red onion']::text[], 'garlic|ground allspice|ground beef|ground cinnamon|ground coriander|ground cumin|lemon|onion|parsley|pita bread|red onion|sweet paprika|tahini',
  null, null, null, null, null, null, null, null)
