insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('c6462762-4974-4ed2-b3b4-15d5ed8b8a85', 1, 'Kofta', 'If using wooden skewers, soak 8 of them in water. Put the beef, onion, garlic, parsley, spices, salt and pepper in a bowl and knead with your hands for 2 minutes until the mixture turns tacky — that''s what helps it cling to the skewers. Chill 30 minutes.', 1800, null, null),
  ('c6462762-4974-4ed2-b3b4-15d5ed8b8a85', 2, 'Kofta', 'With wet hands, divide the meat into 8 portions and press each one around a skewer into a 5-inch log about 1 inch thick.', 600, null, null),
  ('c6462762-4974-4ed2-b3b4-15d5ed8b8a85', 3, 'Tahini sauce', 'Whisk the tahini, lemon juice, garlic and a pinch of salt (it will seize up), then whisk in the cold water a little at a time until smooth and pourable.', 300, null, null),
  ('c6462762-4974-4ed2-b3b4-15d5ed8b8a85', 4, 'Kofta', 'Heat the grill to medium-high, about 450°F, and oil the grates well.', 600, 232.2, null),
  ('c6462762-4974-4ed2-b3b4-15d5ed8b8a85', 5, 'Kofta', 'Grill the kofta, turning every 2–3 minutes, until well browned and 160°F in the center, 8–10 minutes.', 540, 232.2, 71.1),
  ('c6462762-4974-4ed2-b3b4-15d5ed8b8a85', 6, null, 'Rest 3 minutes. Toss the sliced onion with the sumac and serve the kofta in warm pita with the onions and tahini sauce.', 180, null, null);

-- Baba Ghanoush
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
