insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7308482d-f679-4a97-99a1-d02562573d24', 1, null, 'Rinse the bulgur in a fine sieve and drain well. Put it in a large bowl with the diced tomatoes, their juices and half the lemon juice, and leave it to soften for 20 minutes.', 1200, null, null),
  ('7308482d-f679-4a97-99a1-d02562573d24', 2, null, 'Meanwhile, wash the parsley and mint and dry them completely in a salad spinner, then on a towel — wet herbs make a soggy salad. Pick the parsley leaves off the thick stems.', 600, null, null),
  ('7308482d-f679-4a97-99a1-d02562573d24', 3, null, 'Gather the parsley into a tight bunch and slice it very thinly with a sharp knife; don''t chop it to a paste. Slice the mint the same way.', 600, null, null),
  ('7308482d-f679-4a97-99a1-d02562573d24', 4, null, 'Add the herbs and scallions to the bulgur. Season with the salt, allspice and pepper, then add the remaining lemon juice and the olive oil and toss well.', 180, null, null),
  ('7308482d-f679-4a97-99a1-d02562573d24', 5, null, 'Taste — it should be lemony and fresh. Serve within an hour, with lettuce leaves for scooping.', 120, null, null);

