values ('44575bce-3db0-487e-b573-554c31f11535', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'menemen', 'menemen-44575b', 'Menemen', 'Turkish breakfast eggs cooked into soft curds in a jammy pan of green peppers and fresh tomato, with a hit of Aleppo pepper.', 'turkish', 2, 10, 20, 30, 4, 'main', null, 0, array['stove']::text[], array['vegetarian', 'budget', 'quick']::text[], array['Whether menemen should contain onion is a famous Turkish debate — leave it out for the classic breakfast version.', 'Some cooks leave menemen very loose; cook it until no liquid egg remains if you''re serving anyone pregnant, very young, older or with a weakened immune system.']::text[], 'https://images.pexels.com/photos/3904924/pexels-photo-3904924.jpeg', 'Scrambled eggs with tomatoes and peppers in a metal pan on a wooden table', 'Engin Akyurt', 'https://www.pexels.com/@enginakyurt/', 'https://www.pexels.com/photo/food-in-a-stainless-pot-3904924/', 'pexels', true, 'public', false,
  'pending_review', array['breakfast', 'main', 'dinner', 'quick', 'budget']::text[], array['stew', 'raw']::text[], array['spicy', 'fresh']::text[], '{}'::text[], null, 'traditional', 'menemen', 'classic', 'Best eaten right away. Refrigerate leftovers up to 1 day and reheat gently until steaming.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['green pepper', 'tomato', 'aleppo pepper', 'egg', 'parsley', 'crusty bread']::text[], 'aleppo pepper|crusty bread|egg|green pepper|parsley|tomato',
  null, null, null, null, null, null, null, null)
