delete from public.recipe_instructions where recipe_id = '44575bce-3db0-487e-b573-554c31f11535';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('44575bce-3db0-487e-b573-554c31f11535', 1, null, 'Heat the oil and butter in a 12-inch skillet over medium heat. Cook the peppers (and the onion, if using) until soft, 6–8 minutes.', 420, null, null),
  ('44575bce-3db0-487e-b573-554c31f11535', 2, null, 'Add the grated tomatoes, Aleppo pepper and salt. Simmer, stirring now and then, until most of the liquid has cooked off and the sauce is thick and jammy, 8–10 minutes.', 540, null, null),
  ('44575bce-3db0-487e-b573-554c31f11535', 3, null, 'Beat the eggs lightly with a fork, just to break the yolks, and pour them into the pan. Lower the heat and fold gently every 20 seconds until the eggs form soft curds with no runny raw egg left (160°F), 3–4 minutes.', 240, null, 71.1),
  ('44575bce-3db0-487e-b573-554c31f11535', 4, null, 'Take off the heat, scatter with parsley and a little more Aleppo pepper and serve straight from the pan with bread for scooping.', 60, null, null);

-- Ghormeh Sabzi
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
  status, categories, methods, flavors, occasions, region, authenticity, dish_key, variant, storage_notes, safety_note, text_license, allergens, proteins, diet_tags, core_ingredients, fingerprint,
