values ('de3bec9b-4417-4e45-804c-369d91999706', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'ghormeh-sabzi', 'ghormeh-sabzi-de3bec', 'Ghormeh Sabzi', 'Iran''s beloved herb stew: lamb slow-simmered with a mountain of fried herbs, kidney beans and sour dried limes until deep green and tangy.', 'persian', 3, 40, 210, 250, 6, 'main', null, 0, array['stove', 'dutch_oven', 'food_processor']::text[], array['make-ahead', 'entertaining', 'freezer-friendly']::text[], array['Fry the herbs low and slow: they should darken but never blacken, or the stew turns bitter.', 'Dried limes and fenugreek leaves are sold at Middle Eastern and Indian grocers and online.']::text[], 'https://images.pexels.com/photos/37941013/pexels-photo-37941013.jpeg', 'Persian green herb stew served with saffron rice', 'Golboo Maghooli', 'https://www.pexels.com/@golboo/', 'https://www.pexels.com/photo/traditional-persian-meal-with-colorful-rice-37941013/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner', 'entertaining']::text[], array['stew', 'pan_fry', 'steam', 'boil']::text[], array['tangy', 'fresh', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'ghormeh-sabzi', 'classic', 'Tastes even better the next day. Refrigerate up to 4 days or freeze up to 3 months.', null, 'owned', '{}'::text[], array['lamb', 'beans']::text[], array['gluten_free', 'dairy_free']::text[], array['flat-leaf parsley', 'cilantro', 'chive', 'leek', 'fenugreek leave', 'onion', 'ground turmeric', 'lamb shoulder', 'dried lime', 'kidney bean']::text[], 'chive|cilantro|dried lime|fenugreek leave|flat-leaf parsley|ground turmeric|kidney bean|lamb shoulder|leek|onion',
  null, null, null, null, null, null, null, null)
