values ('b28dc243-88c7-4b5c-adb7-a59128b2325f', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'israeli-salad', 'israeli-salad-b28dc2', 'Israeli Salad', 'Cucumber and tomato cut into a tiny, even dice and dressed at the last minute with lemon and olive oil — crisp, juicy and endlessly useful.', 'israeli', 1, 20, 0, 20, 4, 'side', null, 0, '{}'::text[], array['vegan', 'quick', 'budget']::text[], array['A pinch of sumac or za''atar on top is a common and very good addition.']::text[], 'https://images.pexels.com/photos/33683679/pexels-photo-33683679.jpeg', 'Cucumber and tomato salad in a white bowl on a red table', 'Golboo Maghooli', 'https://www.pexels.com/@golboo/', 'https://www.pexels.com/photo/fresh-cucumber-and-tomato-salad-on-red-table-33683679/', 'pexels', true, 'public', false,
  'pending_review', array['salad', 'side', 'budget']::text[], array['no_cook']::text[], array['tangy', 'fresh']::text[], '{}'::text[], null, 'traditional', 'israeli-salad', 'classic', 'Best within an hour of dressing. Undressed, the chopped vegetables keep 1 day refrigerated.', null, 'owned', '{}'::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], array['plum tomato', 'persian cucumber', 'red onion', 'parsley', 'lemon']::text[], 'lemon|parsley|persian cucumber|plum tomato|red onion',
  null, null, null, null, null, null, null, null)
