insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('b28dc243-88c7-4b5c-adb7-a59128b2325f', 1, null, 'Halve the tomatoes and, if they''re very juicy, scoop out the seedy pulp (save it for a sauce). Cut the flesh into ¼-inch dice.', 360, null, null),
  ('b28dc243-88c7-4b5c-adb7-a59128b2325f', 2, null, 'Cut the cucumbers into the same ¼-inch dice — the small, even cut is what makes this salad.', 360, null, null),
  ('b28dc243-88c7-4b5c-adb7-a59128b2325f', 3, null, 'Combine the tomatoes, cucumbers, onion, bell pepper and parsley in a bowl.', 120, null, null),
  ('b28dc243-88c7-4b5c-adb7-a59128b2325f', 4, null, 'Just before serving, dress with the lemon juice, olive oil, salt and pepper and toss. Salt draws out water, so don''t dress it ahead.', 120, null, null);

