  ('9aabe923-b474-4db2-b820-8fc139e186ff', 20, null, '12 dates, to serve', 'dates', 12, null, 'to serve', true);
delete from public.recipe_instructions where recipe_id = '9aabe923-b474-4db2-b820-8fc139e186ff';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('9aabe923-b474-4db2-b820-8fc139e186ff', 1, null, 'Heat the oil in a Dutch oven over medium heat. Add the lamb, onion, celery, half the cilantro and parsley, and the spices. Cook, stirring, for 10 minutes.', 600, null, null),
  ('9aabe923-b474-4db2-b820-8fc139e186ff', 2, null, 'Add the crushed tomatoes, tomato paste, lentils and 8 cups of the water. Bring to a boil, then partly cover and simmer until the lamb (well past 145°F) and lentils are tender, about 45 minutes.', 2700, null, 62.8),
  ('9aabe923-b474-4db2-b820-8fc139e186ff', 3, null, 'Add the chickpeas and vermicelli (or rice) and simmer until tender, 10 minutes for vermicelli or 20 for rice.', 900, null, null),
  ('9aabe923-b474-4db2-b820-8fc139e186ff', 4, null, 'Whisk the flour into the remaining 1 cup of cold water until smooth. Pour it slowly into the simmering soup, stirring constantly, then simmer 10 minutes more, stirring, until silky and lightly thickened.', 600, null, null),
  ('9aabe923-b474-4db2-b820-8fc139e186ff', 5, null, 'Stir in the rest of the herbs and the salt. Serve with lemon wedges and dates.', 120, null, null);

