values ('c4856961-53c0-4dac-bb17-fd40dd26bf83', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'couscous-seven-vegetables', 'couscous-with-seven-vegetables-c48569', 'Couscous with Seven Vegetables', 'A festive mound of fluffy couscous crowned with seven vegetables and chickpeas in a saffron-ginger broth — adapted with vegetable stock and olive oil instead of meat broth and smen, and quick-soaked rather than steamed couscous.', 'moroccan', 2, 30, 60, 90, 6, 'side', null, 0, array['stove', 'dutch_oven']::text[], array['vegan', 'entertaining']::text[], array['For the traditional texture, steam the couscous over the simmering broth two or three times (in a couscoussier, or a colander lined with cheesecloth), raking it with oiled hands between steamings.', 'Adding the vegetables in order of cooking time keeps them from turning to mush.']::text[], 'https://images.unsplash.com/photo-1742806418170-f051cb880314', 'Couscous topped with vegetables in a red bowl', 'Marco Palumbo', 'https://unsplash.com/@sapporo2025', 'https://unsplash.com/photos/couscous-with-vegetables-in-a-red-bowl-0TJqrLinYY4', 'unsplash', true, 'public', false,
  'pending_review', array['side', 'entertaining']::text[], array['stew', 'boil']::text[], array['spicy', 'fresh', 'aromatic']::text[], '{}'::text[], null, 'adapted', 'couscous-seven-vegetables', 'classic', 'Refrigerate the vegetables and broth up to 4 days and the couscous separately up to 3 days.', null, 'owned', array['gluten', 'wheat']::text[], array['beans']::text[], array['pescatarian', 'vegetarian', 'vegan', 'dairy_free']::text[], array['onion', 'tomato', 'ground ginger', 'ground turmeric', 'saffron thread', 'cilantro', 'flat-leaf parsley', 'vegetable stock', 'carrot', 'turnip', 'green cabbage', 'butternut squash', 'zucchini', 'chickpea', 'couscou']::text[], 'butternut squash|carrot|chickpea|cilantro|couscou|flat-leaf parsley|green cabbage|ground ginger|ground turmeric|onion|saffron thread|tomato|turnip|vegetable stock|zucchini',
  null, null, null, null, null, null, null, null)
