insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('2348c04c-c577-4a5e-a215-6122360aba8d', 1, 'Crispy onions', 'Heat the oil in a heavy saucepan to 325°F; it should come no more than halfway up the pan. Fry the onions in two batches, stirring, until deep golden, 10–15 minutes. Lift out onto paper towels, salt lightly and keep the oil.', 900, 162.8, null),
  ('2348c04c-c577-4a5e-a215-6122360aba8d', 2, 'Lentils and rice', 'Simmer the lentils in 4 cups of the water until just tender but not falling apart, about 15 minutes. Drain.', 900, null, null),
  ('2348c04c-c577-4a5e-a215-6122360aba8d', 3, 'Lentils and rice', 'Heat 2 tbsp of the onion oil in a pot, add the rice and cumin and stir for 2 minutes. Add the lentils, the remaining 2 cups of water and the salt. Bring to a boil, cover and cook on low for 18 minutes, then rest 10 minutes off the heat.', 1800, null, null),
  ('2348c04c-c577-4a5e-a215-6122360aba8d', 4, 'Pasta', 'Meanwhile, boil the macaroni in salted water until al dente. Drain and toss with a spoonful of the onion oil.', 600, null, null),
  ('2348c04c-c577-4a5e-a215-6122360aba8d', 5, 'Tomato sauce', 'Fry the garlic in 2 tbsp of the onion oil for 1 minute. Add the tomato sauce, coriander and pepper flakes and simmer 10 minutes, then stir in the vinegar and season with salt.', 720, null, null),
  ('2348c04c-c577-4a5e-a215-6122360aba8d', 6, 'Garlic vinegar', 'Stir together the garlic, vinegar, water, cumin and pepper flakes with a pinch of salt.', 120, null, null),
  ('2348c04c-c577-4a5e-a215-6122360aba8d', 7, null, 'Layer each bowl with the lentil rice, macaroni and chickpeas. Spoon over the tomato sauce, top with a heap of crispy onions and add garlic vinegar to taste.', 180, null, null);

