values ('1bd35670-ed42-4cf5-ac1b-d5d345df10e6', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'ful-medames', 'ful-medames-1bd356', 'Ful Medames', 'Egypt''s everyday breakfast of warm fava beans mashed with garlic, cumin, lemon and olive oil, topped with tomato and herbs and scooped up with pita.', 'egyptian', 1, 10, 15, 25, 4, 'breakfast', null, 0, array['stove']::text[], array['vegan', 'budget', 'quick']::text[], array['Canned fava beans labelled "ful" or "ful medames" are sold in Middle Eastern shops and many international aisles. Pinto beans make a fair stand-in.']::text[], 'https://images.pexels.com/photos/5191842/pexels-photo-5191842.jpeg', 'Middle Eastern fava bean dish with fresh vegetables and lemon', 'Shameel mukkath', 'https://www.pexels.com/@shameel-mukkath-3421394/', 'https://www.pexels.com/photo/healthy-baked-beans-5191842/', 'pexels', true, 'public', false,
