insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('e9611ab4-bcb5-45bb-a6c0-28ca0bf4a1ac', 1, null, 'Cook the onion in a dry pot over medium heat, stirring, until soft and starting to colour, 5–7 minutes.', 360, null, null),
  ('e9611ab4-bcb5-45bb-a6c0-28ca0bf4a1ac', 2, null, 'Add the oil, garlic, ginger, berbere, tomato paste and chopped tomato and cook, stirring, for 5 minutes.', 300, null, null),
  ('e9611ab4-bcb5-45bb-a6c0-28ca0bf4a1ac', 3, null, 'Add 2½ cups of the warm water and bring to a simmer. Lower the heat and sprinkle in the shiro a spoonful at a time, whisking constantly so no lumps form.', 300, null, null),
  ('e9611ab4-bcb5-45bb-a6c0-28ca0bf4a1ac', 4, null, 'Simmer gently, partly covered (it spatters) and stirring often, until thick, glossy and no longer tasting of raw flour, 15–20 minutes. Whisk in the rest of the water as it thickens.', 1080, null, null),
  ('e9611ab4-bcb5-45bb-a6c0-28ca0bf4a1ac', 5, null, 'Season with salt, add the jalapeño if using and serve hot with injera or rice.', 120, null, null);

-- Doro Wat
