values ('fc40fdfa-1a1f-42d2-8c3e-a67c60f7d48b', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'doro-wat', 'doro-wat-fc40fd', 'Doro Wat', 'Ethiopia''s celebration stew: chicken and whole eggs simmered in a deep red sauce of slow-cooked onions, berbere and spiced butter.', 'ethiopian', 3, 40, 120, 160, 6, 'main', null, 0, array['stove', 'dutch_oven', 'food_processor']::text[], array['entertaining']::text[], array['Short on time? Use ½ cup store-bought niter kibbeh instead of making the spiced butter.', 'Chop the onions as finely as you can — they melt into the sauce and give doro wat its body.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['holiday', 'main', 'dinner', 'entertaining']::text[], array['stew', 'boil']::text[], array['tangy', 'aromatic']::text[], array['christmas', 'easter']::text[], null, 'traditional', 'doro-wat', 'classic', 'Refrigerate up to 4 days; the flavour deepens overnight.', null, 'owned', array['egg', 'milk']::text[], array['chicken']::text[], array['gluten_free']::text[], array['garlic', 'ginger', 'fenugreek seed', 'ground cardamom', 'ground turmeric', 'drumstick thigh', 'lemon', 'red onion', 'berbere spice', 'tomato paste', 'egg']::text[], 'berbere spice|drumstick thigh|egg|fenugreek seed|garlic|ginger|ground cardamom|ground turmeric|lemon|red onion|tomato paste',
  null, null, null, null, null, null, null, null)
