  ('fc40fdfa-1a1f-42d2-8c3e-a67c60f7d48b', 4, 'Spiced butter', '½ tsp fenugreek seeds', 'fenugreek seeds', 0.5, 'tsp', null, false),
  ('fc40fdfa-1a1f-42d2-8c3e-a67c60f7d48b', 5, 'Spiced butter', '½ tsp ground cardamom', 'ground cardamom', 0.5, 'tsp', null, false),
  ('fc40fdfa-1a1f-42d2-8c3e-a67c60f7d48b', 6, 'Spiced butter', '½ tsp ground turmeric', 'ground turmeric', 0.5, 'tsp', null, false),
  ('fc40fdfa-1a1f-42d2-8c3e-a67c60f7d48b', 7, 'Stew', '3 lb bone-in chicken drumsticks and thighs, skin removed', 'bone-in chicken drumsticks and thighs', 3, 'lb', 'skin removed', false),
