values ('0cae602a-42a7-41bb-ac3f-8b066b2935ea', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'suya', 'suya-0cae60', 'Suya', 'Thin ribbons of beef rubbed with a fiery peanut-spice mix (yaji) and grilled hot, Nigerian street-style — adapted with ground roasted peanuts in place of kuli-kuli peanut cake.', 'nigerian', 2, 30, 10, 40, 4, 'main', null, 0, array['grill', 'food_processor']::text[], array['entertaining', 'high-protein']::text[], array['No grill? Broil on a foil-lined sheet pan about 4 inches from the heat, 3–4 minutes per side.', 'Kuli-kuli (Nigerian peanut cake) is sold at West African grocers if you''d like the traditional rub.', 'Some bouillon cubes contain wheat, milk or soy; check the label if anyone you''re cooking for needs to avoid them.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['grilling', 'main', 'dinner', 'entertaining']::text[], array['grill']::text[], array['spicy']::text[], '{}'::text[], null, 'adapted', 'suya', 'classic', 'Refrigerate cooked suya up to 3 days. Extra yaji keeps in a jar for a month.', null, 'owned', array['peanut']::text[], array['beef']::text[], array['dairy_free']::text[], array['roasted peanut', 'sweet paprika', 'cayenne', 'ground ginger', 'garlic powder', 'onion powder', 'bouillon cube', 'beef sirloin', 'red onion', 'tomato', 'english cucumber']::text[], 'beef sirloin|bouillon cube|cayenne|english cucumber|garlic powder|ground ginger|onion powder|red onion|roasted peanut|sweet paprika|tomato',
  null, null, null, null, null, null, null, null)
