  ('0cae602a-42a7-41bb-ac3f-8b066b2935ea', 3, 'Yaji spice', '2 tsp cayenne, use less for milder', 'cayenne', 2, 'tsp', 'use less for milder', false),
  ('0cae602a-42a7-41bb-ac3f-8b066b2935ea', 4, 'Yaji spice', '1½ tsp ground ginger', 'ground ginger', 1.5, 'tsp', null, false),
  ('0cae602a-42a7-41bb-ac3f-8b066b2935ea', 5, 'Yaji spice', '1 tsp garlic powder', 'garlic powder', 1, 'tsp', null, false),
  ('0cae602a-42a7-41bb-ac3f-8b066b2935ea', 6, 'Yaji spice', '1 tsp onion powder', 'onion powder', 1, 'tsp', null, false),
  ('0cae602a-42a7-41bb-ac3f-8b066b2935ea', 7, 'Yaji spice', '1 beef bouillon cube, crushed', 'beef bouillon cube', 1, null, 'crushed', false),
  ('0cae602a-42a7-41bb-ac3f-8b066b2935ea', 8, 'Yaji spice', '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('0cae602a-42a7-41bb-ac3f-8b066b2935ea', 9, 'Beef', '1½ lb beef sirloin, sliced ¼ inch thick against the grain', 'beef sirloin', 1.5, 'lb', 'sliced ¼ inch thick against the grain', false),
  ('0cae602a-42a7-41bb-ac3f-8b066b2935ea', 10, 'Beef', '2 tbsp vegetable oil', 'vegetable oil', 2, 'tbsp', null, false),
