insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('e12231ae-94e3-4d85-8cfc-db3756a867d4', 1, null, 'Cut the ends off the plantains, slit the skin lengthwise and peel. Cut into ¾-inch cubes or thick diagonal slices.', 300, null, null),
  ('e12231ae-94e3-4d85-8cfc-db3756a867d4', 2, null, 'Mix the ginger, onion, garlic, spices, salt and water into a paste. Toss the plantains in it and leave 15–30 minutes.', 1200, null, null),
  ('e12231ae-94e3-4d85-8cfc-db3756a867d4', 3, null, 'Heat 2 inches of oil in a heavy pot to 350°F. Use a pot deep enough that the oil fills it no more than halfway, and keep a lid nearby.', 480, 176.7, null),
  ('e12231ae-94e3-4d85-8cfc-db3756a867d4', 4, null, 'Fry the plantains in batches without crowding, stirring gently, until deep caramel-brown, 3–4 minutes per batch. Drain on a rack or paper towels.', 720, 176.7, null),
  ('e12231ae-94e3-4d85-8cfc-db3756a867d4', 5, null, 'Serve hot, with roasted peanuts on the side.', 60, null, null);

-- Chicken Yassa
