delete from public.recipe_instructions where recipe_id = '4022a9e3-9b4a-4832-8bc2-c9c8bfd5c689';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('4022a9e3-9b4a-4832-8bc2-c9c8bfd5c689', 1, null, 'Mix the lemon juice, mustard, garlic, pepper, salt and 2 tbsp oil in a large bowl. Add the chicken and onions, toss well, cover and refrigerate 2 hours or overnight.', 7200, null, null),
  ('4022a9e3-9b4a-4832-8bc2-c9c8bfd5c689', 2, null, 'Lift out the chicken, scrape off the onions and pat dry. Brown it skin side down in the remaining oil in a Dutch oven over medium-high heat, 6–8 minutes, then turn for 2 minutes and set aside (it finishes cooking later).', 600, null, null),
  ('4022a9e3-9b4a-4832-8bc2-c9c8bfd5c689', 3, null, 'Lift the onions from the marinade, keeping the liquid. Cook them in the chicken fat over medium heat, stirring often, until soft and golden, 20–25 minutes.', 1320, null, null),
  ('4022a9e3-9b4a-4832-8bc2-c9c8bfd5c689', 4, null, 'Add the reserved marinade, stock, bay leaves and scotch bonnet. Nestle in the chicken skin side up, cover and simmer until the chicken reads 165°F at the bone, 25–30 minutes.', 1680, null, 73.9),
  ('4022a9e3-9b4a-4832-8bc2-c9c8bfd5c689', 5, null, 'Add the olives and simmer uncovered 5 minutes. Remove the pepper and bay leaves, taste — it should be tangy and savoury — and serve over rice.', 300, null, null);

