insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('88b6ff01-07fe-49b1-885e-18c92a93be7a', 1, null, 'Heat the oven to 350°F. Soak the bread in the milk for 10 minutes.', 600, 176.7, null),
  ('88b6ff01-07fe-49b1-885e-18c92a93be7a', 2, 'Filling', 'Cook the onions in the oil in a large skillet over medium heat until soft and golden, 8 minutes. Add the garlic, curry powder and turmeric and stir for 1 minute.', 540, null, null),
  ('88b6ff01-07fe-49b1-885e-18c92a93be7a', 3, 'Filling', 'Add the beef and cook, breaking it up, until no longer pink, about 8 minutes. Take off the heat. Squeeze the bread (keep the milk) and mash it into the meat with the chutney, raisins, lemon juice, almonds, salt and pepper.', 600, null, null),
  ('88b6ff01-07fe-49b1-885e-18c92a93be7a', 4, 'Topping', 'Pack the meat into a 2-quart baking dish (about 8 × 11 inches) and smooth the top. Whisk the eggs into the reserved milk with a pinch of salt (top up with milk to make about 1 cup), pour it over the meat and tuck the bay leaves in upright.', 300, null, null),
  ('88b6ff01-07fe-49b1-885e-18c92a93be7a', 5, null, 'Bake until the custard is set and golden and the center of the meat reads 160°F, 35–40 minutes.', 2280, 176.7, 71.1),
  ('88b6ff01-07fe-49b1-885e-18c92a93be7a', 6, null, 'Rest 10 minutes, then serve with yellow rice, extra chutney and sliced banana.', 600, null, null);

