values ('74033305-f563-4b9e-9c7c-b7ff2b81f201', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-paprikash', 'chicken-paprikash-740333', 'Chicken Paprikash', 'Chicken braised in a sweet Hungarian paprika and onion sauce, finished with sour cream and served over soft homemade nokedli dumplings.', 'hungarian', 2, 20, 65, 85, 4, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['comfort', 'kid-friendly']::text[], array['Use fresh, sweet Hungarian paprika — old paprika tastes dusty, and the whole sauce depends on it.']::text[], 'https://images.pexels.com/photos/10338435/pexels-photo-10338435.jpeg', 'Chicken paprikash in creamy paprika sauce with spaetzle, tomatoes and pickles', 'Istvan Szabo', 'https://www.pexels.com/@istvanpszabo/', 'https://www.pexels.com/photo/a-close-up-shot-of-a-chicken-paprikash-dish-10338435/', 'pexels', true, 'public', false,
