values ('b9094052-49c7-4426-922f-82b0c3f8612b', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'goulash-soup', 'goulash-soup-b90940', 'Goulash Soup', 'Hungarian gulyásleves: beef, onions and plenty of sweet paprika simmered with caraway, root vegetables and potatoes into a brothy, warming soup.', 'hungarian', 2, 25, 135, 160, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['comfort', 'freezer-friendly']::text[], array['Always take the pot off the heat before adding paprika — it scorches in seconds and turns bitter.']::text[], 'https://images.pexels.com/photos/38441087/pexels-photo-38441087.jpeg', 'Hungarian goulash served in a red pot on a checkered tablecloth', 'kirpiklipencere', 'https://www.pexels.com/@kirpiklipencere-2158386200/', 'https://www.pexels.com/photo/traditional-hungarian-goulash-in-pot-38441087/', 'pexels', true, 'public', false,
