insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('b9094052-49c7-4426-922f-82b0c3f8612b', 1, null, 'Heat the oil in a Dutch oven over medium heat and cook the onions until golden, about 10 minutes.', 600, null, null),
  ('b9094052-49c7-4426-922f-82b0c3f8612b', 2, null, 'Add the beef and stir until it''s no longer red on the outside, about 5 minutes; it doesn''t need a hard sear.', 300, null, null),
  ('b9094052-49c7-4426-922f-82b0c3f8612b', 3, null, 'Take the pot off the heat and stir in the paprika, caraway and garlic, then the tomato paste and 2 cups of the water. Return to the heat, cover and simmer gently for 1 hour, stirring now and then.', 3600, null, null),
  ('b9094052-49c7-4426-922f-82b0c3f8612b', 4, null, 'Add the remaining water, the tomato, pepper, carrots, parsnip, salt and pepper and simmer 30 minutes.', 1800, null, null),
  ('b9094052-49c7-4426-922f-82b0c3f8612b', 5, null, 'Add the potatoes and simmer until they and the beef are tender (well past the 145°F safe minimum), 25–30 minutes.', 1680, null, 62.8),
  ('b9094052-49c7-4426-922f-82b0c3f8612b', 6, null, 'Taste for salt and serve with crusty bread and a spoonful of sour cream.', 120, null, null);

