insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('0670fa7e-c9c9-4c7a-9e92-490ddbf75bd5', 1, null, 'Heat the oil in a large skillet over medium heat and cook the onion, carrot and bell pepper until soft, 8 minutes.', 480, null, null),
  ('0670fa7e-c9c9-4c7a-9e92-490ddbf75bd5', 2, null, 'Add the beets, 2 tbsp of the vinegar, the tomato paste, sugar and ½ cup of the stock. Cover and stew, stirring now and then, for 20 minutes — the vinegar keeps the beets ruby red.', 1200, null, null),
  ('0670fa7e-c9c9-4c7a-9e92-490ddbf75bd5', 3, null, 'Meanwhile, bring the rest of the stock to a boil in a Dutch oven with the bay leaves. Add the potatoes and simmer 10 minutes.', 600, null, null),
  ('0670fa7e-c9c9-4c7a-9e92-490ddbf75bd5', 4, null, 'Add the cabbage (and beans, if using) to the pot and simmer 5 minutes.', 300, null, null),
  ('0670fa7e-c9c9-4c7a-9e92-490ddbf75bd5', 5, null, 'Stir in the beet mixture, garlic, salt and pepper and simmer until the cabbage is tender, 10 minutes. Taste and add the remaining vinegar until it''s pleasantly sweet-sour.', 600, null, null),
  ('0670fa7e-c9c9-4c7a-9e92-490ddbf75bd5', 6, null, 'Off the heat, stir in half the dill, cover and rest 15 minutes. Serve with sour cream and the rest of the dill.', 900, null, null);

