insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('2deaf634-0aa5-4de5-aee0-4171dc1ecf8e', 1, null, 'Heat a large cast-iron skillet over medium-high heat with 2 tablespoons of the oil. Add the beans in a single layer (in two batches if needed) and cook, turning occasionally, until blistered, wrinkled and tender, 8–10 minutes. Move to a plate.', 540, null, null),
  ('2deaf634-0aa5-4de5-aee0-4171dc1ecf8e', 2, null, 'Add the remaining oil and the pork and fry, breaking it up, until browned and crisp, no pink remains and it reaches 160°F, about 4 minutes.', 240, null, 71.1),
  ('2deaf634-0aa5-4de5-aee0-4171dc1ecf8e', 3, null, 'Lower the heat to medium, add the chiles and Sichuan peppercorns and stir 20 seconds, then add the garlic, ginger and preserved greens for 30 seconds more.', 60, null, null),
  ('2deaf634-0aa5-4de5-aee0-4171dc1ecf8e', 4, null, 'Return the beans, add the Shaoxing wine, soy sauce, sugar and salt and toss over high heat until dry and coated, about 1 minute. Serve hot.', 60, null, null);

