insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('9a61a023-5cd9-41b3-ab68-759fe02a9ff2', 1, null, 'Bring the dashi, soy sauce, mirin and sugar to a simmer in a 10- or 12-inch skillet over medium heat.', 120, null, null),
  ('9a61a023-5cd9-41b3-ab68-759fe02a9ff2', 2, null, 'Add the onion and simmer until soft, about 3 minutes.', 180, null, null),
  ('9a61a023-5cd9-41b3-ab68-759fe02a9ff2', 3, null, 'Add the chicken in a single layer and simmer, turning once, until cooked through and 165°F in the thickest piece, 6–7 minutes.', 420, null, 73.9),
  ('9a61a023-5cd9-41b3-ab68-759fe02a9ff2', 4, null, 'Beat the eggs lightly — just a few strokes so streaks of white remain. Pour two-thirds over the chicken in a circle, cover and cook 1 minute.', 60, null, null),
  ('9a61a023-5cd9-41b3-ab68-759fe02a9ff2', 5, null, 'Pour over the rest of the egg and most of the scallions, cover and cook until the egg is softly set, 30–60 seconds (or 2–3 minutes for firm egg).', 60, null, null),
  ('9a61a023-5cd9-41b3-ab68-759fe02a9ff2', 6, null, 'Divide the rice among bowls and slide a quarter of the chicken and egg over each, with its broth. Top with the remaining scallions.', null, null, null);

