insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('18efb42f-bf8c-4ca3-9a33-f11bc3c6bf5c', 1, 'Dashi', '5 cups cold water', 'cold water', 5, 'cup', null, false),
  ('18efb42f-bf8c-4ca3-9a33-f11bc3c6bf5c', 2, 'Dashi', '1 piece kombu (dried kelp), about 4 by 6 inches', 'kombu (dried kelp)', 1, 'piece', 'about 4 by 6 inches', false),
  ('18efb42f-bf8c-4ca3-9a33-f11bc3c6bf5c', 3, 'Dashi', '1 cup bonito flakes (katsuobushi), loosely packed', 'bonito flakes (katsuobushi)', 1, 'cup', 'loosely packed', false),
  ('18efb42f-bf8c-4ca3-9a33-f11bc3c6bf5c', 4, 'Soup', '2 tbsp dried wakame seaweed', 'dried wakame seaweed', 2, 'tbsp', null, false),
  ('18efb42f-bf8c-4ca3-9a33-f11bc3c6bf5c', 5, 'Soup', '¼ cup white or yellow miso', 'white or yellow miso', 0.25, 'cup', null, false),
  ('18efb42f-bf8c-4ca3-9a33-f11bc3c6bf5c', 6, 'Soup', '14 oz silken or soft tofu, cut into ½-inch cubes', 'silken or soft tofu', 14, 'oz', 'cut into ½-inch cubes', false),
