values ('b3eba16a-1699-4ccc-8b86-204d2d6a85fb', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'bibimbap-beef', 'bibimbap-b3eba1', 'Bibimbap', 'Warm rice crowned with sesame-seasoned vegetables, soy-garlic beef and a fried egg, mixed at the table with sweet-spicy gochujang sauce.', 'korean', 2, 35, 25, 60, 4, 'main', null, 0, array['stove']::text[], array['entertaining']::text[], array['For dolsot-style crispy rice, press the rice into a hot oiled cast-iron skillet for 5 minutes before topping.']::text[], 'https://images.unsplash.com/photo-1741295017668-c8132acd6fc0', 'Bowl of bibimbap served with Korean side dishes', 'Dmitry Pavlovsky', 'https://unsplash.com/@vectorburn', 'https://unsplash.com/photos/korean-bibimbap-with-side-dishes-is-served-SbHulgzS_eo', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'entertaining']::text[], array['stir_fry', 'boil']::text[], array['spicy', 'tangy', 'savory']::text[], '{}'::text[], null, 'traditional', 'bibimbap', 'classic', 'Keep vegetables, beef and rice separately, refrigerated, up to 3 days. Fry eggs fresh.', 'The eggs here aren''t cooked to 160°F. Use pasteurized eggs if you''re serving anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['egg', 'gluten', 'sesame', 'soy', 'wheat']::text[], array['beef']::text[], array['dairy_free']::text[], array['sirloin ribeye', 'soy sauce', 'garlic', 'sesame oil', 'spinach', 'bean sprout', 'carrot', 'zucchini', 'shiitake mushroom', 'gochujang', 'rice vinegar', 'short-grain rice', 'egg', 'sesame seed']::text[], 'bean sprout|carrot|egg|garlic|gochujang|rice vinegar|sesame oil|sesame seed|shiitake mushroom|short-grain rice|sirloin ribeye|soy sauce|spinach|zucchini',
  null, null, null, null, null, null, null, null)
