  ('b3eba16a-1699-4ccc-8b86-204d2d6a85fb', 17, 'Sauce', '1 tbsp rice vinegar', 'rice vinegar', 1, 'tbsp', null, false),
  ('b3eba16a-1699-4ccc-8b86-204d2d6a85fb', 18, 'Sauce', '1 tbsp water', 'water', 1, 'tbsp', null, false),
  ('b3eba16a-1699-4ccc-8b86-204d2d6a85fb', 19, 'To serve', '5 cups cooked short-grain rice, hot', 'cooked short-grain rice', 5, 'cup', 'hot', false),
  ('b3eba16a-1699-4ccc-8b86-204d2d6a85fb', 20, 'To serve', '4 large eggs', 'large eggs', 4, null, null, false),
