insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('db084f2b-d7d1-4912-a122-116a7db90c19', 1, null, 'Bring the stock to a simmer with the galangal, lemongrass, lime leaves and chiles and simmer 5 minutes to infuse.', 300, null, null),
  ('db084f2b-d7d1-4912-a122-116a7db90c19', 2, null, 'Add the coconut milk and bring back to a gentle simmer — don''t let it boil hard or it may split.', 240, null, null),
  ('db084f2b-d7d1-4912-a122-116a7db90c19', 3, null, 'Add the chicken and mushrooms and simmer gently until the chicken is cooked through and 165°F, 8–10 minutes.', 540, null, 73.9),
  ('db084f2b-d7d1-4912-a122-116a7db90c19', 4, null, 'Season with the fish sauce and sugar, turn off the heat and stir in the lime juice. Taste: it should be creamy, salty and clearly sour.', 60, null, null),
  ('db084f2b-d7d1-4912-a122-116a7db90c19', 5, null, 'Ladle into bowls and top with cilantro. The galangal, lemongrass and lime leaves flavor the soup but aren''t meant to be eaten.', null, null, null);

