  ('4eb545cd-c851-4368-a651-2f6d46e3f175', 10, 'Larb', '½ cup fresh mint leaves', 'fresh mint leaves', 0.5, 'cup', null, false),
  ('4eb545cd-c851-4368-a651-2f6d46e3f175', 11, 'Larb', '½ cup fresh cilantro, chopped', 'fresh cilantro', 0.5, 'cup', 'chopped', false),
