insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('4eb545cd-c851-4368-a651-2f6d46e3f175', 1, 'Toasted rice', 'Toast the uncooked rice in a dry skillet over medium heat, shaking often, until deep golden, 6–8 minutes. Cool, then grind to a coarse powder in a mortar or spice grinder.', 420, null, null),
  ('4eb545cd-c851-4368-a651-2f6d46e3f175', 2, 'Larb', 'Bring the stock to a simmer in a skillet over medium heat. Add the chicken and cook, breaking it into small crumbs, until no pink remains and it reaches 165°F, 5–6 minutes.', 360, null, 73.9),
  ('4eb545cd-c851-4368-a651-2f6d46e3f175', 3, 'Larb', 'Take the pan off the heat and let it cool for a minute. Stir in the lime juice, fish sauce, sugar and chili flakes.', 60, null, null),
  ('4eb545cd-c851-4368-a651-2f6d46e3f175', 4, 'Larb', 'Fold in the shallots, scallions, mint, cilantro and 1½ tablespoons of the toasted rice powder. Taste for sour, salty and hot.', 60, null, null),
  ('4eb545cd-c851-4368-a651-2f6d46e3f175', 5, null, 'Pile onto a platter, sprinkle with the remaining rice powder and serve warm or at room temperature with lettuce, cucumber and sticky rice.', null, null, null);

