values ('b08701c5-a1da-4467-b855-3ffee9abd8be', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'pad-kra-pao-pork', 'pad-kra-pao-holy-basil-stir-fry-b08701', 'Pad Kra Pao (Holy Basil Stir-Fry)', 'Ground pork stir-fried hot with garlic, chiles and peppery holy basil, served over jasmine rice with a crisp-edged fried egg — Bangkok''s go-to lunch.', 'thai', 2, 10, 15, 25, 4, 'main', null, 0, array['stove']::text[], array['weeknight']::text[], array['Holy basil (kra pao) is peppery and clove-like; look for it at Thai or Southeast Asian grocers. Thai basil makes a sweeter but still delicious version.']::text[], 'https://images.unsplash.com/photo-1669863329825-6e4e39ce752c', 'Rice topped with stir-fried pork and basil and a fried egg', 'suradeach saetang', 'https://unsplash.com/@jointstar', 'https://unsplash.com/photos/a-plate-of-food-X6ilNZbrRLM', 'unsplash', true, 'public', false,
  'pending_review', array['quick', 'main', 'dinner']::text[], array['stir_fry']::text[], array['spicy', 'fresh', 'savory']::text[], '{}'::text[], null, 'traditional', 'pad-kra-pao', 'classic', 'Refrigerate the pork up to 3 days; fry eggs fresh.', 'The eggs here aren''t cooked to 160°F. Use pasteurized eggs if you''re serving anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['egg', 'fish', 'gluten', 'shellfish', 'soy', 'wheat']::text[], array['pork', 'fish']::text[], array['dairy_free']::text[], array['oyster sauce', 'soy sauce', 'fish sauce', 'garlic', 'thai chile', 'ground pork', 'shallot', 'basil leave', 'egg', 'jasmine rice']::text[], 'basil leave|egg|fish sauce|garlic|ground pork|jasmine rice|oyster sauce|shallot|soy sauce|thai chile',
  null, null, null, null, null, null, null, null)
