insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('b08701c5-a1da-4467-b855-3ffee9abd8be', 1, 'Sauce', 'Stir the sauce ingredients together until the sugar dissolves.', null, null, null),
  ('b08701c5-a1da-4467-b855-3ffee9abd8be', 2, 'Stir-fry', 'Pound the garlic and chiles to a rough paste in a mortar, or chop them very finely together.', 180, null, null),
  ('b08701c5-a1da-4467-b855-3ffee9abd8be', 3, 'Stir-fry', 'Heat the oil in a wok over high heat. Fry the garlic-chile paste and shallot for 20 seconds until fragrant (stand back — the chile fumes are strong).', 60, null, null),
  ('b08701c5-a1da-4467-b855-3ffee9abd8be', 4, 'Stir-fry', 'Add the pork and beans and stir-fry, breaking up the meat, until browned with no pink left and 160°F, 4–5 minutes.', 300, null, 71.1),
  ('b08701c5-a1da-4467-b855-3ffee9abd8be', 5, 'Sauce', 'Add the sauce and toss until it coats the pork and mostly evaporates, 1 minute. Turn off the heat and stir in the basil until just wilted.', 60, null, null),
  ('b08701c5-a1da-4467-b855-3ffee9abd8be', 6, 'To serve', 'Heat the frying oil in a small skillet over medium-high. Fry the eggs one or two at a time, spooning hot oil over the whites, until puffed with crisp brown edges, about 2 minutes each.', 360, null, null),
  ('b08701c5-a1da-4467-b855-3ffee9abd8be', 7, null, 'Serve the pork over rice with a fried egg on top.', null, null, null);

-- Fresh Summer Rolls (Gỏi Cuốn)
