insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('20634be2-a488-4515-bd93-0d359096660a', 1, 'Spice paste', 'Pound or blitz the shallots, garlic, chiles and shrimp paste into a coarse paste.', 180, null, null),
  ('20634be2-a488-4515-bd93-0d359096660a', 2, 'Rice', 'Heat 2 tablespoons oil in a wok over medium-high heat. Fry the paste, stirring, until it smells sweet and darkens slightly, 2–3 minutes.', 180, null, null),
  ('20634be2-a488-4515-bd93-0d359096660a', 3, 'Rice', 'Add the chicken and stir-fry until cooked through and 165°F, 4–5 minutes.', 300, null, 73.9),
  ('20634be2-a488-4515-bd93-0d359096660a', 4, 'Rice', 'Turn the heat to high, add the rice and break up any clumps. Add the sweet soy, soy sauce and sambal and toss until every grain is coated and some catch and toast, 3–4 minutes. Stir in the scallions.', 240, null, null),
  ('20634be2-a488-4515-bd93-0d359096660a', 5, 'To serve', 'In a skillet, fry the eggs in the remaining oil until the whites are set and the edges crisp, about 2 minutes.', 120, null, null),
  ('20634be2-a488-4515-bd93-0d359096660a', 6, null, 'Serve the rice topped with a fried egg, with cucumber and tomato on the side and fried shallots scattered over.', null, null, null);

