insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('9406f8c4-c75d-4034-9fad-780a4667a177', 1, null, 'Heat the oil in a large wok or deep skillet over medium-high. Cook the onion and garlic until fragrant and soft, 2 minutes.', 120, null, null),
  ('9406f8c4-c75d-4034-9fad-780a4667a177', 2, null, 'Add the chicken and stir-fry until no longer pink and 165°F, 4–5 minutes. Add the shrimp and cook until pink and opaque (145°F), 2 minutes. Lift the chicken and shrimp out.', 420, null, 73.9),
  ('9406f8c4-c75d-4034-9fad-780a4667a177', 3, null, 'Add the carrots and celery and stir-fry 2 minutes, then the cabbage and snow peas for 1 minute more. Lift out half the vegetables to keep them crisp.', 180, null, null),
  ('9406f8c4-c75d-4034-9fad-780a4667a177', 4, null, 'Pour in the stock, soy sauce, oyster sauce and pepper and bring to a boil.', 120, null, null),
  ('9406f8c4-c75d-4034-9fad-780a4667a177', 5, null, 'Add the noodles and toss with tongs as they soften and soak up the liquid, 3–4 minutes, adding a splash of water if they look dry before they''re tender.', 240, null, null),
  ('9406f8c4-c75d-4034-9fad-780a4667a177', 6, null, 'Return the chicken, shrimp and reserved vegetables and toss to combine. Top with scallions and serve with calamansi or lemon to squeeze over.', 60, null, null);

