insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('77160b41-c48b-4b75-9ac0-75cdbc7e8710', 1, 'Tikka', 'Stir together the yogurt, lemon juice, garlic, ginger, spices and salt. Coat the chicken and marinate in the fridge at least 1 hour or up to 24 hours.', 3600, null, null),
  ('77160b41-c48b-4b75-9ac0-75cdbc7e8710', 2, 'Tikka', 'Heat the broiler with a rack about 6 inches from the element. Thread the chicken onto skewers or spread on a foil-lined sheet pan with a rack.', 300, null, null),
  ('77160b41-c48b-4b75-9ac0-75cdbc7e8710', 3, 'Tikka', 'Broil, turning once, until charred in spots and 165°F in the thickest piece, 12–15 minutes.', 840, null, 73.9),
  ('77160b41-c48b-4b75-9ac0-75cdbc7e8710', 4, 'Masala', 'Meanwhile, heat the ghee in a large pot over medium heat and cook the onions until deep golden, 12–15 minutes, stirring often.', 840, null, null),
  ('77160b41-c48b-4b75-9ac0-75cdbc7e8710', 5, 'Masala', 'Add the green chile, garlic and ginger for 1 minute, then the coriander, cumin, paprika, turmeric and tomato paste for 1 minute more.', 120, null, null),
  ('77160b41-c48b-4b75-9ac0-75cdbc7e8710', 6, 'Masala', 'Add the tomato purée and water and simmer, stirring now and then, until thick and the oil glistens at the edges, 12–15 minutes. Blend with a stick blender if you like it smooth.', 780, null, null),
  ('77160b41-c48b-4b75-9ac0-75cdbc7e8710', 7, null, 'Stir in the cream, garam masala and chicken with any juices and simmer 5 minutes. Season with salt and finish with cilantro. Serve with rice or naan.', 300, null, null);

