insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('5dc808b3-47ba-4d0e-add1-0fd8876a3cbb', 1, null, 'Heat the oil in a heavy pot over medium heat. Add the cumin seeds and bay leaf and let them sizzle 30 seconds.', 60, null, null),
  ('5dc808b3-47ba-4d0e-add1-0fd8876a3cbb', 2, null, 'Add the onions and cook, stirring often, until deep golden brown, 12–15 minutes — this is where the flavor comes from.', 840, null, null),
  ('5dc808b3-47ba-4d0e-add1-0fd8876a3cbb', 3, null, 'Add the garlic, ginger and green chile for 1 minute, then the coriander, chili powder, turmeric and chana masala for 30 seconds.', 120, null, null),
  ('5dc808b3-47ba-4d0e-add1-0fd8876a3cbb', 4, null, 'Add the tomatoes and cook until they break down and the oil separates at the edges, 6–8 minutes.', 420, null, null),
  ('5dc808b3-47ba-4d0e-add1-0fd8876a3cbb', 5, null, 'Add the chickpeas, water and salt and simmer 15 minutes. Mash a few chickpeas against the side of the pot to thicken the gravy.', 900, null, null),
  ('5dc808b3-47ba-4d0e-add1-0fd8876a3cbb', 6, null, 'Stir in the amchur, taste for salt and tang, and finish with cilantro. Serve with rice, flatbread or sliced red onion.', 60, null, null);

