values ('f6d8c17b-a29a-48c1-a382-c5c931bb3c56', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'skillet-smash-burgers', 'smash-burgers-f6d8c1', 'Smash Burgers', 'Thin beef patties smashed onto a very hot skillet so they form lacy, crackling-brown edges, doubled up with melted American cheese, pickles and a tangy burger sauce on soft potato buns.', 'american', 2, 10, 15, 25, 4, 'main', null, 0, array['stove', 'cast_iron']::text[], array['weeknight', 'kid-friendly', 'comfort']::text[], array['Keep the beef cold and handle it as little as possible — loose, cold meat smashes thin and crisps instead of steaming.', 'Use a stiff, flat metal spatula, not a slotted or flexible one: you need to press hard and scrape the crust up in one piece.']::text[], 'https://images.unsplash.com/photo-1607013251379-e6eecfffe234', 'Double cheeseburger with pickles on a dark surface', 'Eiliv Aceron', 'https://unsplash.com/@shootdelicious', 'https://unsplash.com/photos/double-cheeseburger-with-pickles-pu6b4yIlQF4', 'unsplash', true, 'public', false,
  'pending_review', array['comfort', 'quick', 'main', 'dinner']::text[], '{}'::text[], array['fresh']::text[], '{}'::text[], null, 'traditional', 'smash-burger', 'classic', 'Best eaten straight from the pan. Leftover sauce keeps 1 week in the fridge.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], array['beef']::text[], '{}'::text[], array['mayonnaise', 'ketchup', 'yellow mustard', 'pickle relish', 'garlic powder', 'ground beef', 'american cheese', 'burger bun', 'pickle chip']::text[], 'american cheese|burger bun|garlic powder|ground beef|ketchup|mayonnaise|pickle chip|pickle relish|yellow mustard',
  null, null, null, null, null, null, null, null)
