  ('f6d8c17b-a29a-48c1-a382-c5c931bb3c56', 1, 'Sauce', '⅓ cup mayonnaise', 'mayonnaise', 0.33, 'cup', null, false),
  ('f6d8c17b-a29a-48c1-a382-c5c931bb3c56', 2, 'Sauce', '2 tbsp ketchup', 'ketchup', 2, 'tbsp', null, false),
