  ('f6d8c17b-a29a-48c1-a382-c5c931bb3c56', 5, 'Sauce', '¼ tsp garlic powder', 'garlic powder', 0.25, 'tsp', null, false),
  ('f6d8c17b-a29a-48c1-a382-c5c931bb3c56', 6, 'Burgers', '1½ lb ground beef, 80/20, well chilled', 'ground beef', 1.5, 'lb', '80/20, well chilled', false),
  ('f6d8c17b-a29a-48c1-a382-c5c931bb3c56', 7, 'Burgers', '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('f6d8c17b-a29a-48c1-a382-c5c931bb3c56', 8, 'Burgers', '½ tsp black pepper', 'black pepper', 0.5, 'tsp', null, false),
  ('f6d8c17b-a29a-48c1-a382-c5c931bb3c56', 9, 'Burgers', '8 slice American cheese', 'American cheese', 8, 'slice', null, false),
