values ('9485bb96-2894-4d41-ae29-2b6b13144ff4', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'diner-style-patty-melt', 'diner-style-patty-melt-9485bb', 'Diner-Style Patty Melt', 'A thin beef patty, slow-cooked sweet onions and melted Swiss pressed between buttery, crisp rye bread — the lunch-counter cousin of the burger.', 'american', 1, 10, 45, 55, 4, 'main', null, 0, array['stove', 'cast_iron']::text[], array['comfort']::text[], array['Keep the heat low for the final cook: it gives the cheese time to melt before the rye scorches.', 'Caramelize the onions up to 3 days ahead and this becomes a 20-minute lunch.']::text[], 'https://images.unsplash.com/photo-1655279563187-a4010cc494f5', 'Toasted sandwich filled with beef and melted cheese', 'Eiliv Aceron', 'https://unsplash.com/@shootdelicious', 'https://unsplash.com/photos/a-sandwich-with-meat-and-cheese-VYKhs9HOKjw', 'unsplash', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner']::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, 'traditional', 'patty-melt', 'classic', 'Best fresh. Refrigerate cooked patties and onions separately up to 3 days and assemble to order.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], array['beef']::text[], '{}'::text[], array['yellow onion', 'ground beef', 'rye bread', 'swiss cheese']::text[], 'ground beef|rye bread|swiss cheese|yellow onion',
  null, null, null, null, null, null, null, null)
