  ('9485bb96-2894-4d41-ae29-2b6b13144ff4', 1, 'Onions', '2 tbsp unsalted butter', 'unsalted butter', 2, 'tbsp', null, false),
  ('9485bb96-2894-4d41-ae29-2b6b13144ff4', 2, 'Onions', '2 large yellow onions, halved and thinly sliced', 'large yellow onions', 2, null, 'halved and thinly sliced', false),
  ('9485bb96-2894-4d41-ae29-2b6b13144ff4', 3, 'Onions', '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('9485bb96-2894-4d41-ae29-2b6b13144ff4', 4, 'Melts', '1¼ lb ground beef, 80/20', 'ground beef', 1.25, 'lb', '80/20', false),
  ('9485bb96-2894-4d41-ae29-2b6b13144ff4', 5, 'Melts', '¾ tsp kosher salt', 'kosher salt', 0.75, 'tsp', null, false),
  ('9485bb96-2894-4d41-ae29-2b6b13144ff4', 6, 'Melts', '½ tsp black pepper', 'black pepper', 0.5, 'tsp', null, false),
  ('9485bb96-2894-4d41-ae29-2b6b13144ff4', 7, 'Melts', '8 slice rye bread, seeded or marbled', 'rye bread', 8, 'slice', 'seeded or marbled', false),
