delete from public.recipe_instructions where recipe_id = '9485bb96-2894-4d41-ae29-2b6b13144ff4';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('9485bb96-2894-4d41-ae29-2b6b13144ff4', 1, 'Onions', 'Melt the butter in a large skillet over medium heat. Add the onions and salt and cook, stirring every few minutes and adding a splash of water if they catch, until soft, sweet and deep golden, about 25 minutes. Scrape into a bowl and wipe out the pan.', 1500, null, null),
  ('9485bb96-2894-4d41-ae29-2b6b13144ff4', 2, 'Melts', 'Divide the beef into 4 portions and press each into a thin oval patty roughly the shape of a slice of bread, about ⅓ inch thick. Season both sides with the salt and pepper.', null, null, null),
  ('9485bb96-2894-4d41-ae29-2b6b13144ff4', 3, 'Melts', 'Cook the patties in the skillet over medium-high heat until browned and no longer pink inside (160°F), about 3 minutes per side. Transfer to a plate and pour off the fat.', 360, null, 71.1),
  ('9485bb96-2894-4d41-ae29-2b6b13144ff4', 4, 'Melts', 'Build each sandwich: rye, a slice of Swiss, a patty, a quarter of the onions, another slice of Swiss, then rye. Spread the outsides of the bread with the softened butter.', null, null, null),
  ('9485bb96-2894-4d41-ae29-2b6b13144ff4', 5, 'Melts', 'Cook two sandwiches at a time over medium-low heat, pressing gently with a spatula, until the bread is deep golden and crisp and the cheese has melted, 3–4 minutes per side. Repeat with the rest.', 840, null, null),
  ('9485bb96-2894-4d41-ae29-2b6b13144ff4', 6, null, 'Cut in half on the diagonal and serve hot, with Thousand Island dressing for dipping if you like.', null, null, null);

-- Thanksgiving Roast Turkey
