values ('95d16bd9-c29c-4a9a-8161-f18756a415bb', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'dry-brined-thanksgiving-turkey', 'thanksgiving-roast-turkey-95d16b', 'Thanksgiving Roast Turkey', 'A dry-brined whole turkey roasted hot and then low, for seasoned, juicy meat and crisp golden skin — with drippings left over for the gravy.', 'american', 3, 90, 220, 1750, 12, 'main', null, 1440, array['oven']::text[], array['entertaining', 'feeds-a-crowd']::text[], array['Thaw a frozen turkey in the fridge — allow about 1 day for every 4–5 lb — and roast it within 2 days of thawing.', 'Bake stuffing in its own dish rather than inside the bird: stuffing in the cavity has to reach 165°F too, and it slows the roasting.']::text[], 'https://images.unsplash.com/photo-1764296931376-cfcd613e9f7f', 'Golden-brown whole roast turkey in a roasting pan', 'Dan Dennis', 'https://unsplash.com/@cameramandan83', 'https://unsplash.com/photos/a-golden-brown-roasted-turkey-in-a-roasting-pan-2gYb1HTW_tQ', 'unsplash', true, 'public', false,
  'pending_review', array['holiday', 'main', 'dinner', 'entertaining']::text[], array['roast']::text[], array['tangy']::text[], array['thanksgiving', 'christmas']::text[], null, 'traditional', 'roast-turkey', 'classic', 'Refrigerate carved meat within 2 hours, up to 4 days, or freeze up to 3 months. Reheat covered with a splash of broth.', 'Thaw the turkey in the fridge, never on the counter. Don''t rinse it — splashing spreads bacteria around the sink — and wash your hands, boards and anything the uncooked turkey touched in hot, soapy water.', 'owned', array['milk']::text[], array['turkey']::text[], '{}'::text[], array['turkey', 'brown sugar', 'rubbed sage', 'dried thyme', 'yellow onion', 'carrot', 'celery', 'lemon', 'garlic', 'thyme', 'sage', 'chicken broth']::text[], 'brown sugar|carrot|celery|chicken broth|dried thyme|garlic|lemon|rubbed sage|sage|thyme|turkey|yellow onion',
  null, null, null, null, null, null, null, null)
