values ('59d13393-9e60-4aad-bc12-54e586073cda', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'southern-cornbread-stuffing', 'cornbread-stuffing-59d133', 'Cornbread Stuffing', 'Crumbled buttermilk cornbread baked with sautéed onion, celery, sage and broth until crisp on top and spoonably soft inside, the way it''s served across the South (where it''s usually called dressing).', 'american', 2, 30, 110, 140, 10, 'side', null, 0, array['oven', 'stove']::text[], array['make-ahead', 'entertaining']::text[], array['Make and dry the cornbread up to 2 days ahead and keep the crumbs in a paper bag.', 'Use low-sodium broth: the cornbread is already seasoned, and full-salt broth can tip it over. Vegetable broth works for a meat-free version.']::text[], 'https://images.unsplash.com/photo-1511996946289-f0c071823341', 'Tray of baked cornbread stuffing with vegetables for the holidays', 'Chelsea shapouri', 'https://unsplash.com/@primal_harmony', 'https://unsplash.com/photos/mixed-vegetable-in-tray-1rq-jAmPlz4', 'unsplash', true, 'public', false,
  'pending_review', array['holiday', 'side', 'entertaining']::text[], array['bake']::text[], array['tangy', 'fresh']::text[], array['thanksgiving', 'christmas']::text[], null, 'traditional', 'cornbread-stuffing', 'classic', 'Refrigerate up to 4 days. Reheat covered at 350°F with a splash of broth until hot through.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], '{}'::text[], array['yellow cornmeal', 'baking powder', 'baking soda', 'buttermilk', 'egg', 'yellow onion', 'celery', 'garlic', 'sage', 'dried thyme', 'chicken broth', 'parsley']::text[], 'baking powder|baking soda|buttermilk|celery|chicken broth|dried thyme|egg|garlic|parsley|sage|yellow cornmeal|yellow onion',
  null, null, null, null, null, null, null, null)
