delete from public.recipe_instructions where recipe_id = '59d13393-9e60-4aad-bc12-54e586073cda';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('59d13393-9e60-4aad-bc12-54e586073cda', 1, 'Cornbread', 'Heat the oven to 425°F and butter a 9-by-13-inch pan or 10-inch cast-iron skillet. Whisk the cornmeal, flour, baking powder, baking soda, salt and sugar. Whisk the buttermilk, eggs and melted butter, stir them into the dry ingredients just until combined and spread in the pan.', null, 218.3, null),
  ('59d13393-9e60-4aad-bc12-54e586073cda', 2, 'Cornbread', 'Bake until golden and a toothpick comes out clean, 20–25 minutes. Cool, then crumble into bite-size pieces on a sheet pan.', 1320, 218.3, null),
  ('59d13393-9e60-4aad-bc12-54e586073cda', 3, 'Cornbread', 'Dry the crumbs: leave them out uncovered overnight, or bake at 300°F, stirring once, until dry to the touch but not browned, about 30 minutes.', 1800, 148.9, null),
  ('59d13393-9e60-4aad-bc12-54e586073cda', 4, 'Stuffing', 'Melt the butter in a large skillet over medium heat. Cook the onions and celery with the salt until soft, about 10 minutes, then add the garlic, sage, thyme and pepper for 1 minute.', 660, null, null),
  ('59d13393-9e60-4aad-bc12-54e586073cda', 5, 'Stuffing', 'Heat the oven to 350°F and butter a 9-by-13-inch baking dish. In a large bowl, whisk the broth and eggs, then fold in the cornbread, vegetables and parsley until evenly moist — it should look like wet sand. Add a splash more broth if it seems dry.', null, 176.7, null),
  ('59d13393-9e60-4aad-bc12-54e586073cda', 6, 'Stuffing', 'Spread in the dish, cover with foil and bake 25 minutes. Uncover and bake until the top is golden and crisp and the center reaches 165°F, 20–25 minutes more.', 2700, 176.7, 73.9);

-- Green Bean Casserole
