values ('8f940ccf-1487-44c1-a30b-3c336764b8ce', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'from-scratch-green-bean-casserole', 'green-bean-casserole-8f940c', 'Green Bean Casserole', 'The Thanksgiving favorite of crisp-tender green beans in a creamy mushroom sauce under a crunchy fried-onion top; we use fresh beans and a quick homemade sauce instead of canned beans and canned soup.', 'american', 1, 20, 45, 65, 8, 'side', null, 0, array['oven', 'stove']::text[], array['make-ahead', 'kid-friendly']::text[], array['Store-bought crispy fried onions are coated in wheat flour; check the label if anyone you''re cooking for avoids wheat.', 'Make the beans and sauce a day ahead and refrigerate them in the baking dish; add 10 minutes to the first bake and add the onions only at the end.']::text[], 'https://images.unsplash.com/photo-1764756994789-ca8a2b4c99a1', 'Creamy green bean casserole with a crispy onion topping', 'Phil Hearing', 'https://unsplash.com/@philhearing', 'https://unsplash.com/photos/creamy-green-bean-casserole-with-crispy-topping-uHggZfKi8Ks', 'unsplash', true, 'public', false,
  'pending_review', array['holiday', 'side', 'comfort']::text[], array['bake', 'boil']::text[], '{}'::text[], array['thanksgiving', 'christmas']::text[], null, 'adapted', 'green-bean-casserole', 'classic', 'Refrigerate up to 3 days. Reheat covered at 350°F; the topping softens, so add a fresh handful of onions if you have them.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['green bean', 'cremini mushroom', 'yellow onion', 'garlic', 'vegetable broth', 'milk', 'ground nutmeg', 'fried onion']::text[], 'cremini mushroom|fried onion|garlic|green bean|ground nutmeg|milk|vegetable broth|yellow onion',
  null, null, null, null, null, null, null, null)
