  ('8f940ccf-1487-44c1-a30b-3c336764b8ce', 5, null, '½ small yellow onion, finely chopped', 'small yellow onion', 0.5, null, 'finely chopped', false),
  ('8f940ccf-1487-44c1-a30b-3c336764b8ce', 6, null, '2 cloves garlic, minced', 'garlic', 2, 'clove', 'minced', false),
  ('8f940ccf-1487-44c1-a30b-3c336764b8ce', 7, null, '3 tbsp all-purpose flour', 'all-purpose flour', 3, 'tbsp', null, false),
  ('8f940ccf-1487-44c1-a30b-3c336764b8ce', 8, null, '1 cup low-sodium vegetable broth', 'low-sodium vegetable broth', 1, 'cup', null, false),
