insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('8f940ccf-1487-44c1-a30b-3c336764b8ce', 1, null, 'Heat the oven to 375°F. Bring a large pot of water to a boil with the tablespoon of salt and fill a bowl with ice water.', null, 190.6, null),
  ('8f940ccf-1487-44c1-a30b-3c336764b8ce', 2, null, 'Boil the green beans until bright green and just tender, 5 minutes. Drain, plunge into the ice water to stop the cooking, then drain well and pat dry.', 300, null, null),
  ('8f940ccf-1487-44c1-a30b-3c336764b8ce', 3, null, 'Melt the butter in a large ovenproof skillet over medium-high heat. Add the mushrooms and cook, stirring now and then, until they release their liquid and brown, 8 minutes. Add the onion and garlic and cook until soft, 3 minutes.', 660, null, null),
  ('8f940ccf-1487-44c1-a30b-3c336764b8ce', 4, null, 'Sprinkle in the flour and stir 1 minute. Slowly whisk in the broth, then the milk, and bubble gently, stirring, until thick enough to coat a spoon, 4–5 minutes. Season with the salt, pepper and nutmeg.', 360, null, null),
  ('8f940ccf-1487-44c1-a30b-3c336764b8ce', 5, null, 'Stir in the green beans and 1 cup of the fried onions. Spread evenly in the skillet (or tip into a 2-quart baking dish) and bake until bubbling, 15 minutes.', 900, 190.6, null),
  ('8f940ccf-1487-44c1-a30b-3c336764b8ce', 6, null, 'Scatter the remaining onions over the top and bake until they''re a shade darker, 5 minutes more. Let it settle 5 minutes before serving.', 600, 190.6, null);

