values ('9fff18f7-d32f-4bc4-adfa-0ae033e9c0f7', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'whole-berry-cranberry-sauce', 'cranberry-sauce-9fff18', 'Cranberry Sauce', 'Whole fresh cranberries simmered with sugar and orange until they burst into a glossy, sweet-tart sauce that sets as it cools.', 'american', 1, 5, 15, 140, 8, 'sauce', null, 120, array['stove']::text[], array['make-ahead', 'budget']::text[], array['Taste once it''s cool: if your berries are very tart, rewarm briefly and stir in up to ¼ cup more sugar.', 'Frozen cranberries work just as well — no need to thaw them first.']::text[], 'https://images.unsplash.com/photo-1764296922399-e140273581ae', 'Bowl of deep red cranberry sauce', 'Dan Dennis', 'https://unsplash.com/@cameramandan83', 'https://unsplash.com/photos/close-up-of-a-bowl-of-dark-berry-compote-Rlf16rIKufg', 'unsplash', true, 'public', false,
  'pending_review', array['holiday', 'sauce', 'budget']::text[], array['boil']::text[], array['aromatic']::text[], array['thanksgiving', 'christmas']::text[], null, 'traditional', 'cranberry-sauce', 'classic', 'Refrigerate up to 10 days or freeze up to 2 months.', null, 'owned', '{}'::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], array['cranberry', 'orange juice', 'orange zest']::text[], 'cranberry|orange juice|orange zest',
  null, null, null, null, null, null, null, null)
