  ('9fff18f7-d32f-4bc4-adfa-0ae033e9c0f7', 1, null, '12 oz fresh cranberries, rinsed', 'fresh cranberries', 12, 'oz', 'rinsed', false),
  ('9fff18f7-d32f-4bc4-adfa-0ae033e9c0f7', 2, null, '¾ cup sugar', 'sugar', 0.75, 'cup', null, false),
  ('9fff18f7-d32f-4bc4-adfa-0ae033e9c0f7', 3, null, '½ cup orange juice', 'orange juice', 0.5, 'cup', null, false),
  ('9fff18f7-d32f-4bc4-adfa-0ae033e9c0f7', 4, null, '¼ cup water', 'water', 0.25, 'cup', null, false),
  ('9fff18f7-d32f-4bc4-adfa-0ae033e9c0f7', 5, null, '1 tsp orange zest', 'orange zest', 1, 'tsp', null, false),
  ('9fff18f7-d32f-4bc4-adfa-0ae033e9c0f7', 6, null, '1 pinch kosher salt', 'kosher salt', 1, 'pinch', null, false),
  ('9fff18f7-d32f-4bc4-adfa-0ae033e9c0f7', 7, null, '1 cinnamon stick', 'cinnamon stick', 1, null, null, true);
delete from public.recipe_instructions where recipe_id = '9fff18f7-d32f-4bc4-adfa-0ae033e9c0f7';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('9fff18f7-d32f-4bc4-adfa-0ae033e9c0f7', 1, null, 'Pick over the cranberries and throw out any soft or shriveled ones.', null, null, null),
  ('9fff18f7-d32f-4bc4-adfa-0ae033e9c0f7', 2, null, 'Bring the sugar, orange juice, water and cinnamon stick to a boil in a medium saucepan over medium-high heat, stirring until the sugar dissolves.', 180, null, null),
  ('9fff18f7-d32f-4bc4-adfa-0ae033e9c0f7', 3, null, 'Add the cranberries and cook at a lively bubble, stirring now and then, until most of the berries have popped and the sauce looks thick and glossy, 8–10 minutes. Leave some berries whole for texture, or mash for a smoother sauce.', 600, null, null),
  ('9fff18f7-d32f-4bc4-adfa-0ae033e9c0f7', 4, null, 'Off the heat, stir in the zest and salt and remove the cinnamon stick. It will look loose but thickens a lot as it cools.', null, null, null),
  ('9fff18f7-d32f-4bc4-adfa-0ae033e9c0f7', 5, null, 'Cool to room temperature, then refrigerate until set, at least 2 hours. Serve cold or at room temperature.', 7200, null, null);

