values ('1b549442-6aea-4c6d-afb4-81f0d11e966a', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'classic-pumpkin-pie', 'pumpkin-pie-1b5494', 'Pumpkin Pie', 'A silky, warmly spiced pumpkin custard in a flaky all-butter crust, baked until just set — the centerpiece of the Thanksgiving dessert table.', 'american', 2, 30, 75, 285, 8, 'dessert', 'pastries', 180, array['oven']::text[], array['make-ahead']::text[], array['Cracks across the top mean the pie baked too long — take it out while the center still jiggles.', 'A store-bought 9-inch crust works too; blind-bake it the same way.']::text[], 'https://images.pexels.com/photos/5491339/pexels-photo-5491339.jpeg', 'Close-up of a sliced homemade pumpkin pie', 'cottonbro studio', 'https://www.pexels.com/@cottonbro/', 'https://www.pexels.com/photo/close-up-photo-of-sliced-pumpkin-pie-5491339/', 'pexels', true, 'public', false,
  'pending_review', array['holiday', 'baking', 'dessert']::text[], array['bake']::text[], array['rich', 'aromatic', 'sweet']::text[], array['thanksgiving']::text[], null, 'traditional', 'pumpkin-pie', 'classic', 'Once cool, cover and refrigerate up to 4 days.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['ice water', 'pumpkin puree', 'brown sugar', 'ground cinnamon', 'ground ginger', 'ground nutmeg', 'ground clove', 'egg', 'egg yolk', 'evaporated milk', 'vanilla extract']::text[], 'brown sugar|egg|egg yolk|evaporated milk|ground cinnamon|ground clove|ground ginger|ground nutmeg|ice water|pumpkin puree|vanilla extract',
  null, null, null, null, null, null, null, null)
