delete from public.recipe_instructions where recipe_id = '1b549442-6aea-4c6d-afb4-81f0d11e966a';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('1b549442-6aea-4c6d-afb4-81f0d11e966a', 1, 'Crust', 'Whisk the flour, sugar and salt. Rub or cut in the butter until the biggest pieces are pea-size, then sprinkle in the ice water a tablespoon at a time, tossing with a fork, until the dough holds together when squeezed. Press into a disk, wrap and chill at least 1 hour.', 3600, null, null),
  ('1b549442-6aea-4c6d-afb4-81f0d11e966a', 2, 'Crust', 'Roll the dough into a 12-inch round on a floured surface, ease it into a 9-inch pie plate and crimp the edge. Freeze 15 minutes while the oven heats to 400°F.', 900, 204.4, null),
  ('1b549442-6aea-4c6d-afb4-81f0d11e966a', 3, 'Crust', 'Line the crust with parchment, fill with pie weights or dried beans and bake 15 minutes. Lift out the weights and bake until the bottom looks dry and pale golden, 5–8 minutes more. Lower the oven to 350°F.', 1320, 204.4, null),
  ('1b549442-6aea-4c6d-afb4-81f0d11e966a', 4, 'Filling', 'Whisk the pumpkin, brown sugar, spices and salt until smooth, then whisk in the eggs, yolk, evaporated milk and vanilla.', null, null, null),
  ('1b549442-6aea-4c6d-afb4-81f0d11e966a', 5, 'Filling', 'Pour the filling into the warm crust and bake at 350°F until the edges are set and the center still wobbles slightly like gelatin, 45–55 minutes; the center should read at least 160°F (most pies set at about 175°F). Shield the crust edge with foil if it darkens too quickly.', 3000, 176.7, 71.1),
  ('1b549442-6aea-4c6d-afb4-81f0d11e966a', 6, null, 'Cool on a rack at least 2 hours so the custard finishes setting before you slice it. Serve at room temperature or chilled, with whipped cream.', 7200, null, null);

-- Lobster Rolls
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
