values ('c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'maine-lobster-rolls', 'lobster-rolls-c3fb7f', 'Lobster Rolls', 'Maine-style rolls of sweet, freshly cooked lobster lightly dressed in lemony mayonnaise and piled into butter-toasted split-top buns (the warm, butter-only Connecticut roll is the other classic).', 'american', 3, 40, 20, 90, 4, 'main', null, 30, array['stove']::text[], array['summer', 'entertaining']::text[], array['Short on time? Buy 1 pound of freshly cooked lobster meat from the fish counter and go straight to the salad.', 'Split-top buns have flat sides that toast like bread; regular hot dog buns or brioche rolls work in a pinch.']::text[], 'https://images.pexels.com/photos/30776096/pexels-photo-30776096.jpeg', 'Lobster roll with coleslaw and a lemon wedge', 'Deane Bayas', 'https://www.pexels.com/@dbaler/', 'https://www.pexels.com/photo/delicious-lobster-roll-with-coleslaw-in-vancouver-30776096/', 'pexels', true, 'public', false,
  'pending_review', array['seafood_raw_bar', 'main', 'dinner', 'entertaining']::text[], array['steam', 'boil']::text[], array['tangy', 'fresh']::text[], '{}'::text[], 'Maine', 'traditional', 'lobster-roll', 'classic', 'The dressed lobster keeps 1 day in the fridge; toast the buns just before serving.', 'Cook lobsters the day you buy them, and only while they''re still lively; discard any that die before cooking. Keep the dressed lobster cold and eat it within a day.', 'owned', array['egg', 'gluten', 'milk', 'shellfish', 'wheat']::text[], array['shellfish']::text[], '{}'::text[], array['live lobster', 'mayonnaise', 'lemon juice', 'chive', 'dog bun']::text[], 'chive|dog bun|lemon juice|live lobster|mayonnaise',
  null, null, null, null, null, null, null, null)
