insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45', 1, 'Lobster', '4 live lobsters, about 1¼ lb each', 'live lobsters', 4, null, 'about 1¼ lb each', false),
  ('c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45', 2, 'Lobster', '2 tbsp kosher salt, for the pot', 'kosher salt', 2, 'tbsp', 'for the pot', false),
  ('c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45', 3, 'Salad', '⅓ cup mayonnaise', 'mayonnaise', 0.33, 'cup', null, false),
  ('c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45', 4, 'Salad', '1 tbsp lemon juice', 'lemon juice', 1, 'tbsp', null, false),
  ('c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45', 5, 'Salad', '1 stalk celery, very finely diced', 'celery', 1, 'stalk', 'very finely diced', true),
  ('c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45', 6, 'Salad', '1 tbsp fresh chives, finely chopped', 'fresh chives', 1, 'tbsp', 'finely chopped', false),
  ('c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45', 7, 'Salad', '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45', 8, 'Salad', '1 pinch black pepper', 'black pepper', 1, 'pinch', null, false),
  ('c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45', 9, 'Rolls', '4 New England-style split-top hot dog buns', 'New England-style split-top hot dog buns', 4, null, null, false),
  ('c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45', 10, 'Rolls', '3 tbsp unsalted butter, softened', 'unsalted butter', 3, 'tbsp', 'softened', false),
  ('c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45', 11, 'Rolls', '4 Bibb lettuce leaves', 'Bibb lettuce leaves', 4, null, null, true);
delete from public.recipe_instructions where recipe_id = 'c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45', 1, 'Lobster', 'Put the lobsters in the freezer for 20 minutes to make them sluggish. Meanwhile, bring 2 inches of water and the salt to a rolling boil in a pot big enough to hold all four, with a steamer rack in the bottom if you have one.', 1200, null, null),
  ('c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45', 2, 'Lobster', 'Add the lobsters head first, cover and steam until the shells are bright red, the meat is opaque and an instant-read thermometer in the thickest part of the tail reads 145°F, 12–14 minutes. Move them to a bowl of ice water for 5 minutes to stop the cooking.', 840, null, 62.8),
  ('c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45', 3, 'Lobster', 'Twist off the tails and claws. Crack the claws and knuckles with the back of a heavy knife or lobster crackers and pull out the meat; cut down the underside of each tail with kitchen shears, lift out the meat and pull out the dark vein. Cut into ¾-inch chunks, leaving the claw meat whole. You should have about 1 pound.', 900, null, null),
  ('c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45', 4, 'Salad', 'Gently fold the lobster with the mayonnaise, lemon juice, celery, chives, salt and pepper — just enough dressing to coat. Cover and chill 30 minutes.', 1800, null, null),
  ('c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45', 5, 'Rolls', 'Spread the butter on the flat outer sides of the buns and toast in a skillet over medium heat until golden, 1–2 minutes per side.', 180, null, null),
  ('c3fb7f16-bdfb-4a5e-9b7b-7ac2a38dfa45', 6, null, 'Line each bun with a lettuce leaf if using and pile in the lobster. Serve with potato chips and lemon wedges.', null, null, null);

-- New York Cheesecake
