values ('e289dd5e-ba81-4713-be04-3e5e915b221c', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'new-york-cheesecake', 'new-york-cheesecake-e289dd', 'New York Cheesecake', 'Tall, dense and creamy, with a graham cracker crust and a tangy edge from sour cream — baked hot and then slow, New York deli style.', 'american', 2, 30, 95, 665, 12, 'dessert', 'cakes', 540, array['oven']::text[], array['make-ahead', 'entertaining']::text[], array['Room-temperature ingredients are the key to a lump-free filling: leave the cream cheese, eggs and sour cream out for about an hour first.', 'A small crack is only cosmetic — cover it with fresh berries or a thin layer of sweetened sour cream.']::text[], 'https://images.pexels.com/photos/10964794/pexels-photo-10964794.jpeg', 'Creamy classic cheesecake on a rustic wooden board', 'Sena', 'https://www.pexels.com/@sena-124841843/', 'https://www.pexels.com/photo/cheesecake-on-a-wooden-plate-10964794/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'dessert', 'entertaining']::text[], array['bake']::text[], array['tangy', 'rich', 'sweet']::text[], '{}'::text[], 'New York', 'traditional', 'new-york-cheesecake', 'classic', 'Refrigerate covered up to 5 days, or freeze slices up to 2 months.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['cracker crumb', 'cream cheese', 'vanilla extract', 'lemon zest', 'sour cream', 'heavy cream', 'egg']::text[], 'cracker crumb|cream cheese|egg|heavy cream|lemon zest|sour cream|vanilla extract',
