insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 1, 'Crust', '1½ cups graham cracker crumbs, about 12 full sheets', 'graham cracker crumbs', 1.5, 'cup', 'about 12 full sheets', false),
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 2, 'Crust', '2 tbsp sugar', 'sugar', 2, 'tbsp', null, false),
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 3, 'Crust', '6 tbsp unsalted butter, melted', 'unsalted butter', 6, 'tbsp', 'melted', false),
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 4, 'Filling', '32 oz cream cheese, four 8-oz blocks, at room temperature', 'cream cheese', 32, 'oz', 'four 8-oz blocks, at room temperature', false),
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 5, 'Filling', '1¼ cups sugar', 'sugar', 1.25, 'cup', null, false),
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 6, 'Filling', '3 tbsp all-purpose flour', 'all-purpose flour', 3, 'tbsp', null, false),
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 7, 'Filling', '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 8, 'Filling', '2 tsp vanilla extract', 'vanilla extract', 2, 'tsp', null, false),
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 9, 'Filling', '1 tsp lemon zest', 'lemon zest', 1, 'tsp', null, false),
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 10, 'Filling', '½ cup sour cream, at room temperature', 'sour cream', 0.5, 'cup', 'at room temperature', false),
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 11, 'Filling', '¼ cup heavy cream', 'heavy cream', 0.25, 'cup', null, false),
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 12, 'Filling', '4 large eggs, at room temperature', 'large eggs', 4, null, 'at room temperature', false);
delete from public.recipe_instructions where recipe_id = 'e289dd5e-ba81-4713-be04-3e5e915b221c';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 1, 'Crust', 'Heat the oven to 350°F. Wrap the outside of a 9-inch springform pan in a double layer of foil. Mix the crumbs, sugar and butter, press firmly over the bottom of the pan and bake 10 minutes. Let it cool while you make the filling, and raise the oven to 475°F.', 600, 176.7, null),
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 2, 'Filling', 'Beat the cream cheese with a stand or hand mixer on medium-low until completely smooth, about 2 minutes, scraping the bowl. Beat in the sugar, flour and salt, then the vanilla, zest, sour cream and cream.', 240, null, null),
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 3, 'Filling', 'Add the eggs one at a time on low speed, mixing just until each disappears — overbeating whips in air that causes cracks. Pour over the crust and tap the pan on the counter to release bubbles.', null, null, null),
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 4, 'Filling', 'Bake at 475°F for 10 minutes to set and color the top.', 600, 246.1, null),
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 5, 'Filling', 'Without opening the door, lower the oven to 250°F and bake until the edges are firm, the center wobbles slightly and an instant-read thermometer in the center reads 160°F, 70–80 minutes more.', 4500, 121.1, 71.1),
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 6, null, 'Turn the oven off, prop the door open a crack and leave the cheesecake inside for 1 hour. Run a thin knife around the edge and cool completely on a rack.', 3600, null, null),
  ('e289dd5e-ba81-4713-be04-3e5e915b221c', 7, null, 'Cover and refrigerate at least 8 hours or overnight. Release the ring and slice with a hot, dry knife, wiping it between cuts.', 28800, null, null);

-- Texas Smoked Brisket
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
