  attribution, reviewed_by, reviewed_at, calories_per_serving, protein_g, carbs_g, fat_g, nutrition_source)
values ('16c3c16c-c07d-4e5b-99ac-22c8a59c7756', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'central-texas-smoked-brisket', 'texas-smoked-brisket-16c3c1', 'Texas Smoked Brisket', 'A whole packer brisket seasoned with nothing but salt and coarse pepper, smoked low over oak until it wobbles, then wrapped in butcher paper and rested long — central-Texas barbecue at home.', 'southern', 3, 45, 780, 825, 20, 'main', null, 0, array['smoker']::text[], array['entertaining', 'feeds-a-crowd', 'weekend-project']::text[], array['You''ll need a smoker that can hold 250–275°F for 12 hours (offset, pellet, or a kettle grill set up for indirect heat), a leave-in probe thermometer and unwaxed butcher paper.', 'Every brisket cooks differently — go by feel, not the clock, and plan to finish 2–3 hours early; it holds beautifully in the cooler.']::text[], 'https://images.unsplash.com/photo-1774923097632-c98e17b7e842', 'Sliced smoked brisket on pink butcher paper', 'Kris Tian', 'https://unsplash.com/@kris_tian', 'https://unsplash.com/photos/sliced-smoked-brisket-on-pink-butcher-paper-APGihs2AsjQ', 'unsplash', true, 'public', false,
  'pending_review', array['grilling', 'main', 'dinner', 'entertaining']::text[], array['smoke']::text[], '{}'::text[], '{}'::text[], 'Texas', 'traditional', 'smoked-brisket', 'classic', 'Refrigerate leftovers in large unsliced pieces up to 4 days or freeze up to 3 months. Reheat wrapped in foil with a splash of the juices at 275°F until hot.', null, 'owned', '{}'::text[], array['beef']::text[], array['gluten_free', 'dairy_free']::text[], array['beef brisket']::text[], 'beef brisket',
  null, null, null, null, null, null, null, null)
