delete from public.recipe_ingredients where recipe_id = '16c3c16c-c07d-4e5b-99ac-22c8a59c7756';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('16c3c16c-c07d-4e5b-99ac-22c8a59c7756', 1, null, '1 whole packer beef brisket, 12–14 lb, point and flat attached', 'whole packer beef brisket', 1, null, '12–14 lb, point and flat attached', false),
  ('16c3c16c-c07d-4e5b-99ac-22c8a59c7756', 2, null, '¼ cup kosher salt', 'kosher salt', 0.25, 'cup', null, false),
  ('16c3c16c-c07d-4e5b-99ac-22c8a59c7756', 3, null, '¼ cup coarsely ground black pepper, 16-mesh if you can find it', 'coarsely ground black pepper', 0.25, 'cup', '16-mesh if you can find it', false),
  ('16c3c16c-c07d-4e5b-99ac-22c8a59c7756', 4, null, '1 tbsp granulated garlic', 'granulated garlic', 1, 'tbsp', null, true),
  ('16c3c16c-c07d-4e5b-99ac-22c8a59c7756', 5, null, '½ cup beef tallow, or rendered brisket trimmings, melted', 'beef tallow', 0.5, 'cup', 'or rendered brisket trimmings, melted', true);
delete from public.recipe_instructions where recipe_id = '16c3c16c-c07d-4e5b-99ac-22c8a59c7756';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('16c3c16c-c07d-4e5b-99ac-22c8a59c7756', 1, null, 'Trim the brisket while it''s cold: remove the hard fat between the point and the flat and the silverskin on the meat side, trim the fat cap to an even ¼ inch and round off thin edges that would dry out. Save the trimmings to render into tallow if you like.', 1800, null, null),
  ('16c3c16c-c07d-4e5b-99ac-22c8a59c7756', 2, null, 'Mix the salt, pepper and garlic and season the brisket evenly all over. Leave it out while the smoker heats, or refrigerate it uncovered overnight.', null, null, null),
  ('16c3c16c-c07d-4e5b-99ac-22c8a59c7756', 3, null, 'Bring the smoker to a steady 250–275°F with oak (post oak is the Texas choice; hickory or pecan also work). Set the brisket on the grate fat side up, with the thicker point end toward the heat, and close the lid.', null, 129.4, null),
  ('16c3c16c-c07d-4e5b-99ac-22c8a59c7756', 4, null, 'Smoke, keeping the temperature steady and adding wood as needed, until the bark is dark and firm and doesn''t smear when you touch it and the thickest part of the flat reads 165–170°F — well past the 145°F safe point — usually 6–8 hours.', 25200, 129.4, 62.8),
  ('16c3c16c-c07d-4e5b-99ac-22c8a59c7756', 5, null, 'Lay out a double length of unwaxed pink butcher paper, brush the center with a little melted tallow if using and wrap the brisket snugly. Return it seam side down and cook until a probe slides into the flat like it''s going into soft butter, usually at 200–205°F, 3–5 hours more.', 14400, 129.4, null),
  ('16c3c16c-c07d-4e5b-99ac-22c8a59c7756', 6, null, 'Rest the wrapped brisket in a dry, empty cooler lined with towels (or a 150°F oven) for at least 1 and up to 4 hours, keeping it above 140°F.', 7200, null, null),
  ('16c3c16c-c07d-4e5b-99ac-22c8a59c7756', 7, null, 'Unwrap, saving the juices. Separate the point from the flat. Slice the flat across the grain into pencil-thick slices and the point a little thicker (or cube it for burnt ends). Spoon the juices over and serve right away.', 900, null, null);

-- Chicken and Andouille Gumbo
