values ('c589b08b-d1b4-4b4f-a23f-08d9e7df8eb8', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-andouille-gumbo', 'chicken-and-andouille-gumbo-c589b0', 'Chicken and Andouille Gumbo', 'A Cajun-style gumbo built on a dark, nutty roux, with tender chicken thighs, smoky andouille and the holy trinity of onion, celery and bell pepper, simmered low and served over rice.', 'cajun_creole', 3, 30, 150, 180, 8, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['comfort', 'make-ahead', 'freezer-friendly']::text[], array['Gumbo is even better the next day: cool it quickly, refrigerate, then lift off the solid fat before reheating.', 'Cajun seasoning blends vary a lot in salt — taste before adding any more.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'comfort']::text[], array['stew', 'pan_fry', 'boil']::text[], array['spicy', 'fresh']::text[], '{}'::text[], 'Louisiana', 'traditional', 'chicken-andouille-gumbo', 'classic', 'Refrigerate up to 4 days or freeze (without rice) up to 3 months.', null, 'owned', array['gluten', 'wheat']::text[], array['chicken', 'pork']::text[], array['dairy_free']::text[], array['chicken thigh', 'cajun seasoning', 'andouille sausage', 'yellow onion', 'bell pepper', 'celery', 'garlic', 'chicken stock', 'bay leave', 'dried thyme', 'cayenne pepper', 'white rice', 'scallion', 'parsley']::text[], 'andouille sausage|bay leave|bell pepper|cajun seasoning|cayenne pepper|celery|chicken stock|chicken thigh|dried thyme|garlic|parsley|scallion|white rice|yellow onion',
  null, null, null, null, null, null, null, null)
