insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('c589b08b-d1b4-4b4f-a23f-08d9e7df8eb8', 1, 'Gumbo', '2½ lb bone-in chicken thighs, skin removed', 'bone-in chicken thighs', 2.5, 'lb', 'skin removed', false),
  ('c589b08b-d1b4-4b4f-a23f-08d9e7df8eb8', 2, 'Gumbo', '1½ tsp kosher salt', 'kosher salt', 1.5, 'tsp', null, false),
  ('c589b08b-d1b4-4b4f-a23f-08d9e7df8eb8', 3, 'Gumbo', '2 tsp Cajun seasoning', 'Cajun seasoning', 2, 'tsp', null, false),
  ('c589b08b-d1b4-4b4f-a23f-08d9e7df8eb8', 4, 'Gumbo', '1 lb andouille sausage, sliced into ¼-inch half-moons', 'andouille sausage', 1, 'lb', 'sliced into ¼-inch half-moons', false),
  ('c589b08b-d1b4-4b4f-a23f-08d9e7df8eb8', 5, 'Gumbo', '¾ cup vegetable oil, divided', 'vegetable oil', 0.75, 'cup', 'divided', false),
  ('c589b08b-d1b4-4b4f-a23f-08d9e7df8eb8', 6, 'Gumbo', '¾ cup all-purpose flour', 'all-purpose flour', 0.75, 'cup', null, false),
  ('c589b08b-d1b4-4b4f-a23f-08d9e7df8eb8', 7, 'Gumbo', '2 yellow onions, chopped', 'yellow onions', 2, null, 'chopped', false),
