  ('c589b08b-d1b4-4b4f-a23f-08d9e7df8eb8', 11, 'Gumbo', '8 cups low-sodium chicken stock, warmed', 'low-sodium chicken stock', 8, 'cup', 'warmed', false),
  ('c589b08b-d1b4-4b4f-a23f-08d9e7df8eb8', 12, 'Gumbo', '3 bay leaves', 'bay leaves', 3, null, null, false),
