values ('707116f5-bf2a-4bb2-9cb5-6f81218febc5', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'cajun-crawfish-etouffee', 'crawfish-etouffee-707116', 'Crawfish Étouffée', 'Sweet crawfish tails ''smothered'' in a buttery blond-roux gravy with the trinity, garlic and cayenne, served over rice — the Cajun-country style, made without tomato.', 'cajun_creole', 3, 20, 45, 65, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['comfort']::text[], array['Look for Louisiana crawfish tails in the freezer case; the yellow-orange fat in the bag is where the flavor is, so don''t rinse it off.', 'No crawfish? Use 2 lb peeled medium shrimp and simmer them in the sauce until pink and opaque (145°F), 3–4 minutes.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'comfort']::text[], array['stew', 'steam', 'boil']::text[], array['spicy', 'tangy', 'fresh']::text[], '{}'::text[], 'Louisiana', 'traditional', 'crawfish-etouffee', 'classic', 'Refrigerate up to 3 days and reheat gently, or freeze (without rice) up to 2 months.', null, 'owned', array['gluten', 'milk', 'shellfish', 'wheat']::text[], array['shellfish']::text[], '{}'::text[], array['yellow onion', 'bell pepper', 'celery', 'garlic', 'seafood stock', 'cajun seasoning', 'cayenne pepper', 'dried thyme', 'bay leave', 'crawfish tail', 'scallion', 'parsley', 'white rice']::text[], 'bay leave|bell pepper|cajun seasoning|cayenne pepper|celery|crawfish tail|dried thyme|garlic|parsley|scallion|seafood stock|white rice|yellow onion',
  null, null, null, null, null, null, null, null)
