  ('707116f5-bf2a-4bb2-9cb5-6f81218febc5', 9, null, '¼ tsp cayenne pepper', 'cayenne pepper', 0.25, 'tsp', null, false),
  ('707116f5-bf2a-4bb2-9cb5-6f81218febc5', 10, null, '½ tsp dried thyme', 'dried thyme', 0.5, 'tsp', null, false),
  ('707116f5-bf2a-4bb2-9cb5-6f81218febc5', 11, null, '2 bay leaves', 'bay leaves', 2, null, null, false),
