delete from public.recipe_instructions where recipe_id = '707116f5-bf2a-4bb2-9cb5-6f81218febc5';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('707116f5-bf2a-4bb2-9cb5-6f81218febc5', 1, null, 'Melt the butter in a heavy pot over medium heat. Whisk in the flour and cook, stirring constantly, until it turns the color of peanut butter and smells toasty, 10–12 minutes.', 720, null, null),
  ('707116f5-bf2a-4bb2-9cb5-6f81218febc5', 2, null, 'Add the onion, bell pepper and celery and cook, stirring, until very soft, 10 minutes. Stir in the garlic for 1 minute.', 660, null, null),
  ('707116f5-bf2a-4bb2-9cb5-6f81218febc5', 3, null, 'Gradually whisk in the warm stock until smooth, then add the Cajun seasoning, cayenne, thyme and bay leaves. Simmer gently, stirring often, until it thickens to a velvety gravy, 15 minutes.', 900, null, null),
  ('707116f5-bf2a-4bb2-9cb5-6f81218febc5', 4, null, 'Stir in the crawfish tails with all the fat and juices from the package. Cook just until heated through and steaming (165°F), about 5 minutes — they''re already cooked and toughen if boiled.', 300, null, 73.9),
  ('707116f5-bf2a-4bb2-9cb5-6f81218febc5', 5, null, 'Remove the bay leaves, stir in most of the scallions, the parsley and lemon juice, and taste for salt (crawfish packs vary). Serve over rice with the remaining scallions and hot sauce.', null, null, null);

-- Cajun Seafood Boil
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
