  attribution, reviewed_by, reviewed_at, calories_per_serving, protein_g, carbs_g, fat_g, nutrition_source)
values ('5d7b769f-45d8-4764-8255-f855eb616359', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'cajun-shrimp-and-crab-boil', 'cajun-seafood-boil-5d7b76', 'Cajun Seafood Boil', 'Shrimp, snow crab, andouille, red potatoes and corn boiled in a fiery, lemony broth and poured straight onto a paper-covered table — made the most common home way, with shrimp and crab rather than crawfish.', 'cajun_creole', 2, 20, 60, 80, 8, 'main', null, 0, array['stove']::text[], array['entertaining', 'summer', 'feeds-a-crowd']::text[], array['Seafood boil seasonings range from mild to fiery and are often very salty; if yours lists salt first, halve the added salt.', 'Live crawfish are the Louisiana spring classic: rinse 5 lb in several changes of fresh water, then boil 3 minutes and soak 20.']::text[], 'https://images.pexels.com/photos/8352802/pexels-photo-8352802.jpeg', 'Seafood boil of crab, shrimp, corn and vegetables on a tray', 'Kindel Media', 'https://www.pexels.com/@kindelmedia/', 'https://www.pexels.com/photo/close-up-of-a-seafood-boil-on-a-tray-8352802/', 'pexels', true, 'public', false,
  'pending_review', array['seafood_raw_bar', 'entertaining', 'main', 'dinner']::text[], array['boil']::text[], array['smoky', 'tangy']::text[], '{}'::text[], 'Louisiana', 'traditional', 'cajun-seafood-boil', 'classic', 'Peel leftover shrimp and crab and refrigerate up to 2 days; leftover potatoes and sausage make a great breakfast hash.', null, 'owned', array['milk', 'shellfish']::text[], array['pork', 'shellfish']::text[], '{}'::text[], array['boil seasoning', 'lemon', 'garlic', 'yellow onion', 'bay leave', 'red potato', 'ear corn', 'andouille sausage', 'crab cluster', 'shell-on shrimp', 'cajun seasoning', 'lemon juice']::text[], 'andouille sausage|bay leave|boil seasoning|cajun seasoning|crab cluster|ear corn|garlic|lemon|lemon juice|red potato|shell-on shrimp|yellow onion',
  null, null, null, null, null, null, null, null)
