delete from public.recipe_instructions where recipe_id = '5d7b769f-45d8-4764-8255-f855eb616359';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('5d7b769f-45d8-4764-8255-f855eb616359', 1, 'Boil', 'Use a stockpot of at least 16 quarts (or an outdoor propane burner with a boil pot and strainer basket). Add the water — the pot should be no more than about two-thirds full — the seasoning, salt, squeezed lemons and their juice, garlic, onions and bay leaves. Cover, bring to a rolling boil, then boil 10 minutes to flavor the water.', 1500, null, null),
  ('5d7b769f-45d8-4764-8255-f855eb616359', 2, 'Boil', 'Add the potatoes and boil 12 minutes. Add the corn and andouille and boil 7 minutes more, until the potatoes are just tender.', 1140, null, null),
  ('5d7b769f-45d8-4764-8255-f855eb616359', 3, 'Boil', 'Add the crab clusters and boil 3 minutes to heat through. Add the shrimp, stir and boil just until they turn pink and opaque (145°F), 2–3 minutes.', 300, null, 62.8),
  ('5d7b769f-45d8-4764-8255-f855eb616359', 4, 'Boil', 'Turn off the heat and let everything sit in the hot broth for 10 minutes to soak up the seasoning. Taste a shrimp: leave it a few minutes longer for more spice, or drain sooner if the shrimp are already firm.', 600, null, null),
  ('5d7b769f-45d8-4764-8255-f855eb616359', 5, 'Garlic butter', 'Meanwhile, melt the butter in a small saucepan with the garlic and cook gently 2 minutes; stir in the Cajun seasoning and lemon juice.', 180, null, null),
  ('5d7b769f-45d8-4764-8255-f855eb616359', 6, null, 'Drain everything (lift out the basket, or scoop with a spider), spread over a table lined with newspaper or butcher paper and drizzle with the garlic butter. Serve with plenty of paper towels and crab crackers.', null, null, null);

