values ('4ff376d6-8366-4cbb-96eb-8e5e084a5022', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'tex-mex-beef-fajitas', 'beef-fajitas-4ff376', 'Beef Fajitas', 'Lime-and-cumin-marinated skirt steak seared hard in cast iron, sliced thin and served sizzling with charred peppers and onions and warm flour tortillas.', 'tex_mex', 2, 140, 25, 165, 4, 'main', null, 0, array['stove', 'cast_iron']::text[], array['entertaining', 'kid-friendly']::text[], array['Cooking over a very hot charcoal fire is the original South Texas way: give the steak 3–4 minutes per side over the coals.', 'Skirt steak is thin and cooks fast; flank steak works too but needs 5–6 minutes per side.']::text[], 'https://images.pexels.com/photos/40135708/pexels-photo-40135708.jpeg', 'Sizzling beef fajitas with bell peppers and condiments', 'mehmetakifarts', 'https://www.pexels.com/@mehmetakifarts/', 'https://www.pexels.com/photo/sizzling-beef-fajitas-with-colorful-vegetables-40135708/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner', 'comfort', 'entertaining']::text[], array['pan_fry']::text[], array['spicy', 'tangy', 'fresh', 'aromatic']::text[], '{}'::text[], 'Texas', 'traditional', 'beef-fajitas', 'classic', 'Refrigerate steak and vegetables up to 3 days; reheat quickly in a hot skillet.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], array['beef']::text[], array['dairy_free']::text[], array['lime juice', 'orange juice', 'garlic', 'jalapeno', 'chile powder', 'ground cumin', 'mexican oregano', 'cilantro', 'skirt steak', 'white onion', 'bell pepper', 'flour tortilla', 'lime']::text[], 'bell pepper|chile powder|cilantro|flour tortilla|garlic|ground cumin|jalapeno|lime|lime juice|mexican oregano|orange juice|skirt steak|white onion',
  null, null, null, null, null, null, null, null)
