insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('4ff376d6-8366-4cbb-96eb-8e5e084a5022', 1, 'Marinade', 'Whisk the marinade ingredients together. Put the steak in a zip-top bag, pour in the marinade, squeeze out the air and refrigerate 2–8 hours (no longer, or the lime turns the meat mushy).', 7200, null, null),
  ('4ff376d6-8366-4cbb-96eb-8e5e084a5022', 2, 'Fajitas', 'Take the steak out of the marinade, scrape off the excess and pat it dry. Let it sit at room temperature while you cook the vegetables.', null, null, null),
  ('4ff376d6-8366-4cbb-96eb-8e5e084a5022', 3, 'Fajitas', 'Heat 1 tablespoon of the oil in a large cast-iron skillet over high heat until shimmering. Add the onion and peppers with the salt and cook, tossing only now and then, until charred in spots but still a little crisp, 6–8 minutes. Transfer to a plate.', 480, null, null),
  ('4ff376d6-8366-4cbb-96eb-8e5e084a5022', 4, 'Fajitas', 'Add the remaining oil to the skillet and heat until it''s just starting to haze. Sear the steak in batches without moving it until deeply browned, 3–4 minutes per side, until an instant-read thermometer reads 145°F.', 600, null, 62.8),
  ('4ff376d6-8366-4cbb-96eb-8e5e084a5022', 5, 'Fajitas', 'Rest the steak on a board 5 minutes, then slice it thinly across the grain (skirt''s grain runs across the short side, so cut each piece into shorter lengths first, then slice).', 300, null, null),
  ('4ff376d6-8366-4cbb-96eb-8e5e084a5022', 6, null, 'Return the vegetables and the sliced steak with its juices to the hot skillet, toss for 30 seconds until sizzling, and bring the pan to the table with the tortillas, toppings and lime wedges.', 60, null, null);

-- Ahi Poke Bowl
