values ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'hawaiian-shoyu-ahi-poke-bowl', 'ahi-poke-bowl-7a371f', 'Ahi Poke Bowl', 'Cubes of sashimi-grade ahi tossed shoyu-style with soy sauce, sesame oil, sweet onion and scallions and spooned over warm rice — the poke you''ll find at almost any Hawaiian market counter.', 'hawaiian', 2, 25, 25, 65, 4, 'main', null, 15, array['stove']::text[], array['summer']::text[], array['Ask the fishmonger for tuna they sell for sashimi or poke and buy it the day you serve it. Frozen sashimi-grade ahi, thawed overnight in the fridge, is a good choice far from the coast.', 'Ogo is a crunchy Hawaiian seaweed sold at Asian and Hawaiian markets; a little rehydrated wakame is a fine stand-in.']::text[], 'https://images.pexels.com/photos/15913461/pexels-photo-15913461.jpeg', 'Poke bowl of fresh tuna, avocado and tobiko with sesame seeds', 'Valeria Boltneva', 'https://www.pexels.com/@valeriya/', 'https://www.pexels.com/photo/salad-with-caviar-15913461/', 'pexels', true, 'public', false,
  'pending_review', array['seafood_raw_bar', 'main', 'dinner']::text[], array['boil', 'raw']::text[], array['spicy', 'savory']::text[], '{}'::text[], 'Hawaii', 'traditional', 'ahi-poke-bowl', 'classic', 'Eat the same day; don''t keep leftover poke.', 'The tuna in poke is eaten raw. Buy fish sold for eating raw from a fishmonger you trust, keep it on ice or in the fridge until you mix it, and eat it within an hour or two. Not recommended for pregnant people, young children, older adults or anyone with a weakened immune system.', 'owned', array['fish', 'gluten', 'sesame', 'soy', 'wheat']::text[], array['fish']::text[], array['pescatarian', 'dairy_free']::text[], array['ahi tuna', 'soy sauce', 'sesame oil', 'sweet onion', 'scallion', 'sesame seed', 'white rice', 'persian cucumber']::text[], 'ahi tuna|persian cucumber|scallion|sesame oil|sesame seed|soy sauce|sweet onion|white rice',
  null, null, null, null, null, null, null, null)
