  ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', 1, 'Poke', '1¼ lb sashimi-grade ahi tuna, well chilled', 'sashimi-grade ahi tuna', 1.25, 'lb', 'well chilled', false),
  ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', 2, 'Poke', '3 tbsp soy sauce', 'soy sauce', 3, 'tbsp', null, false),
  ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', 3, 'Poke', '1 tbsp toasted sesame oil', 'toasted sesame oil', 1, 'tbsp', null, false),
  ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', 4, 'Poke', '½ sweet onion, Maui or Vidalia, thinly sliced and cut into 1-inch pieces', 'sweet onion', 0.5, null, 'Maui or Vidalia, thinly sliced and cut into 1-inch pieces', false),
  ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', 5, 'Poke', '3 scallions, thinly sliced', 'scallions', 3, null, 'thinly sliced', false),
  ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', 6, 'Poke', '1 tsp toasted sesame seeds', 'toasted sesame seeds', 1, 'tsp', null, false),
  ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', 7, 'Poke', '½ tsp red pepper flakes', 'red pepper flakes', 0.5, 'tsp', null, true),
  ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', 8, 'Poke', '½ cup ogo seaweed, chopped', 'ogo seaweed', 0.5, 'cup', 'chopped', true),
  ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', 9, 'Poke', '1 pinch Hawaiian sea salt, or flaky sea salt', 'Hawaiian sea salt', 1, 'pinch', 'or flaky sea salt', true),
  ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', 10, 'Bowls', '1½ cups short-grain white rice', 'short-grain white rice', 1.5, 'cup', null, false),
  ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', 11, 'Bowls', '1¾ cups water', 'water', 1.75, 'cup', null, false),
  ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', 12, 'Bowls', '2 Persian cucumbers, thinly sliced', 'Persian cucumbers', 2, null, 'thinly sliced', false),
  ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', 13, 'Bowls', '1 avocado, sliced', 'avocado', 1, null, 'sliced', true);
delete from public.recipe_instructions where recipe_id = '7a371fee-bcba-4b6c-9f43-6d1cf59ffd45';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', 1, 'Bowls', 'Rinse the rice until the water runs almost clear. Cook it with the water in a rice cooker, or in a covered saucepan brought to a boil and then kept on low heat for 15 minutes and rested off the heat for 10. Keep warm.', 1500, null, null),
  ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', 2, 'Poke', 'Keep the tuna in the fridge until the last moment. On a clean, cold board, trim away any dark bloodline or sinew and cut the tuna into ¾-inch cubes. It''s served raw, so work quickly and keep everything cold.', 600, null, null),
  ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', 3, 'Poke', 'In a chilled bowl, gently toss the tuna with the soy sauce, sesame oil, onion, scallions, sesame seeds, and the chili flakes and ogo if using. Taste and add a pinch of salt if it needs it.', null, null, null),
  ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', 4, 'Poke', 'Refrigerate 15 minutes (and no longer than 1 hour) so the flavors soak in.', 900, null, null),
  ('7a371fee-bcba-4b6c-9f43-6d1cf59ffd45', 5, null, 'Spoon the warm rice into bowls, top with the poke, cucumber and avocado and eat right away.', null, null, null);

-- Kalua Pork
