values ('9d3ec270-4411-4a99-a3c0-dfce81c9546e', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'oven-kalua-pork', 'kalua-pork-9d3ec2', 'Kalua Pork', 'Smoky, salty, fall-apart shredded pork in the spirit of the luau''s underground imu; we slow-roast it in a covered pot with liquid smoke and Hawaiian sea salt instead of cooking it in a pit.', 'hawaiian', 2, 15, 345, 360, 10, 'main', null, 0, array['oven', 'dutch_oven']::text[], array['make-ahead', 'freezer-friendly', 'entertaining', 'budget']::text[], array['Liquid smoke is potent and brands vary in strength; resist adding more than the recipe calls for.', 'Slow-cooker method: season the same way and cook on low 8–10 hours with no added water.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'budget', 'entertaining']::text[], array['roast']::text[], array['smoky']::text[], '{}'::text[], 'Hawaii', 'adapted', 'kalua-pork', 'classic', 'Refrigerate with its juices up to 4 days or freeze up to 3 months.', null, 'owned', '{}'::text[], array['pork']::text[], array['gluten_free', 'dairy_free']::text[], array['pork shoulder', 'hawaiian salt', 'liquid smoke']::text[], 'hawaiian salt|liquid smoke|pork shoulder',
  null, null, null, null, null, null, null, null)
