delete from public.recipe_ingredients where recipe_id = '9d3ec270-4411-4a99-a3c0-dfce81c9546e';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('9d3ec270-4411-4a99-a3c0-dfce81c9546e', 1, null, '5 lb boneless pork shoulder, pork butt, cut in half if needed to fit the pot', 'boneless pork shoulder', 5, 'lb', 'pork butt, cut in half if needed to fit the pot', false),
  ('9d3ec270-4411-4a99-a3c0-dfce81c9546e', 2, null, '1½ tbsp alaea Hawaiian sea salt, or 2 tbsp kosher salt', 'alaea Hawaiian sea salt', 1.5, 'tbsp', 'or 2 tbsp kosher salt', false),
  ('9d3ec270-4411-4a99-a3c0-dfce81c9546e', 3, null, '1½ tbsp liquid smoke, hickory or mesquite', 'liquid smoke', 1.5, 'tbsp', 'hickory or mesquite', false),
  ('9d3ec270-4411-4a99-a3c0-dfce81c9546e', 4, null, '4 banana leaves, or ti leaves, rinsed', 'banana leaves', 4, null, 'or ti leaves, rinsed', true),
  ('9d3ec270-4411-4a99-a3c0-dfce81c9546e', 5, null, '½ cup water', 'water', 0.5, 'cup', null, false),
  ('9d3ec270-4411-4a99-a3c0-dfce81c9546e', 6, null, '½ head green cabbage, cored and cut into 1-inch pieces', 'green cabbage', 0.5, 'head', 'cored and cut into 1-inch pieces', true),
  ('9d3ec270-4411-4a99-a3c0-dfce81c9546e', 7, null, '6 cups cooked white rice, to serve', 'cooked white rice', 6, 'cup', 'to serve', true);
delete from public.recipe_instructions where recipe_id = '9d3ec270-4411-4a99-a3c0-dfce81c9546e';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('9d3ec270-4411-4a99-a3c0-dfce81c9546e', 1, null, 'Heat the oven to 325°F. Pierce the pork all over with a paring knife, about every inch, so the seasoning gets inside.', null, 162.8, null),
  ('9d3ec270-4411-4a99-a3c0-dfce81c9546e', 2, null, 'Rub the bottled smoky liquid all over the pork, then the salt, working both into the slits.', null, null, null),
  ('9d3ec270-4411-4a99-a3c0-dfce81c9546e', 3, null, 'If using banana leaves, line a Dutch oven with them, set the pork on top and fold the leaves over it; otherwise just set the pork in the pot. Pour the water around it and cover tightly with foil and then the lid.', null, null, null),
  ('9d3ec270-4411-4a99-a3c0-dfce81c9546e', 4, null, 'Roast until the pork is falling-apart tender and shreds easily with a fork, 5–6 hours (it will be far past the 145°F safe point, around 200°F).', 19800, 162.8, 62.8),
  ('9d3ec270-4411-4a99-a3c0-dfce81c9546e', 5, null, 'Lift the pork onto a board, saving the juices, shred it with two forks and discard any large pieces of fat. Skim the fat from the juices and stir back enough to keep the meat moist. Taste — it should be well salted; add more salt if needed.', 600, null, null),
  ('9d3ec270-4411-4a99-a3c0-dfce81c9546e', 6, null, 'If using the cabbage, cook it in ½ cup of the juices in a skillet until just tender, 5 minutes, then fold into the pork. Serve with rice, plate-lunch style.', 300, null, null);

-- Mole Poblano
