values ('d063e49e-7f7e-481d-82b5-6207ca43c39a', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'mole-poblano-de-guajolote', 'mole-poblano-d063e4', 'Mole Poblano', 'Puebla''s celebrated sauce of mulato, ancho and pasilla chiles ground with toasted nuts, seeds, spices, tortilla and a little chocolate, simmered until deep and silky and served over turkey, as is traditional (chicken is the everyday swap).', 'mexican', 4, 75, 180, 255, 10, 'main', null, 0, array['stove', 'blender', 'dutch_oven']::text[], array['make-ahead', 'entertaining', 'weekend-project']::text[], array['Mexican chocolate tablets already contain sugar and cinnamon, and some brands contain milk or soy; check the label if that matters to anyone at the table.', 'Chicken thighs and drumsticks work instead of turkey (poach them 35–40 minutes). The mole deepens overnight, so it''s ideal made a day or two ahead.']::text[], 'https://images.pexels.com/photos/34035523/pexels-photo-34035523.jpeg', 'Chicken in mole sauce with rice and garnish', 'César O''neill', 'https://www.pexels.com/@cesar-o-neill-26650613/', 'https://www.pexels.com/photo/traditional-mexican-dish-with-mole-sauce-34035523/', 'pexels', true, 'public', false,
  'pending_review', array['holiday', 'main', 'dinner', 'entertaining']::text[], array['stew', 'boil']::text[], array['spicy', 'smoky', 'aromatic']::text[], array['christmas', 'birthday']::text[], 'Puebla', 'traditional', 'mole-poblano', 'classic', 'Refrigerate up to 5 days; freeze the sauce on its own up to 6 months.', null, 'owned', array['gluten', 'peanut', 'sesame', 'tree_nut', 'wheat']::text[], array['turkey']::text[], '{}'::text[], array['thigh drumstick', 'white onion', 'garlic', 'bay leave', 'mulato chile', 'ancho chile', 'pasilla chile', 'chipotle chile', 'lard', 'almond', 'peanut', 'raisin', 'corn tortilla', 'french bread', 'sesame seed', 'cinnamon stick', 'clove', 'black peppercorn', 'anise seed', 'coriander seed', 'roma tomato', 'tomatillo', 'mexican oregano', 'dried thyme', 'mexican chocolate']::text[], 'almond|ancho chile|anise seed|bay leave|black peppercorn|chipotle chile|cinnamon stick|clove|coriander seed|corn tortilla|dried thyme|french bread|garlic|lard|mexican chocolate|mexican oregano|mulato chile|pasilla chile|peanut|raisin|roma tomato|sesame seed|thigh drumstick|tomatillo|white onion',
