delete from public.recipe_instructions where recipe_id = 'd063e49e-7f7e-481d-82b5-6207ca43c39a';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('d063e49e-7f7e-481d-82b5-6207ca43c39a', 1, 'Turkey', 'Put the turkey in a large pot with the onion, garlic, bay leaves, salt and enough water to cover by 1 inch. Bring to a boil, skim, then partly cover and simmer gently until tender and 165°F at the bone, about 1¼ hours. Lift out the turkey and strain and save the broth (you need about 8 cups).', 4500, null, 73.9),
  ('d063e49e-7f7e-481d-82b5-6207ca43c39a', 2, 'Chiles', 'Meanwhile, wipe the chiles, cut off the stems, slit them open and shake out the seeds and veins (save 1 tablespoon of seeds). Toast the chiles a few at a time in a dry skillet over medium heat, pressing them flat, until fragrant and blistered, 10–15 seconds per side — scorched chiles make the mole bitter. Soak in 4 cups of the hot broth for 20 minutes.', 1500, null, null),
  ('d063e49e-7f7e-481d-82b5-6207ca43c39a', 3, 'Mole', 'Heat 3 tablespoons of the lard in the skillet over medium heat. Fry each in turn, lifting it into a bowl when done: almonds and peanuts until golden, 3 minutes; raisins until puffed, 30 seconds; tortilla and bread until crisp and brown, 2 minutes. Toast the sesame seeds, pumpkin seeds, reserved chile seeds, cinnamon, cloves, peppercorns, anise and coriander in the dry pan until fragrant, about 2 minutes.', 720, null, null),
  ('d063e49e-7f7e-481d-82b5-6207ca43c39a', 4, 'Mole', 'Char the tomatoes, tomatillos, onion and garlic in the dry skillet, turning, until blackened in spots and soft, about 10 minutes. Peel the garlic.', 600, null, null),
  ('d063e49e-7f7e-481d-82b5-6207ca43c39a', 5, 'Mole', 'Blend the chiles with their soaking broth until very smooth. Blend everything else with the oregano, thyme and 2 more cups of broth, in batches, until completely smooth, 2–3 minutes per batch. Push both purées through a mesh strainer for the silkiest sauce.', 900, null, null),
  ('d063e49e-7f7e-481d-82b5-6207ca43c39a', 6, 'Mole', 'Heat the remaining lard in a Dutch oven over medium-high heat until very hot. Pour in the purée all at once — stand back, it spatters — and cook, stirring constantly and scraping the bottom, until it darkens and thickens to a paste, 10–15 minutes.', 720, null, null),
  ('d063e49e-7f7e-481d-82b5-6207ca43c39a', 7, 'Mole', 'Stir in 2 cups of broth, the chocolate, sugar and salt. Simmer on low, partly covered and stirring often, for 45 minutes, adding broth as needed until the mole coats the back of a spoon like heavy cream. Taste and balance with salt or sugar.', 2700, null, null),
  ('d063e49e-7f7e-481d-82b5-6207ca43c39a', 8, null, 'Add the turkey and simmer 15 minutes to heat through. Serve with plenty of sauce, a scattering of sesame seeds, rice and warm tortillas.', 900, null, null);

