values ('a083ce6b-dcad-496a-b9a0-9c509a60c8f1', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'beef-birria-tacos', 'birria-tacos-a083ce', 'Birria Tacos', 'Beef braised for hours in a guajillo-and-ancho adobo, shredded into cheesy tortillas crisped in the red fat and served with the rich consomé for dipping; we use beef, as most birria taco stands now do, instead of Jalisco''s traditional goat.', 'mexican', 3, 40, 250, 290, 8, 'main', null, 0, array['stove', 'oven', 'dutch_oven', 'blender']::text[], array['entertaining', 'weekend-project', 'freezer-friendly']::text[], array['For the Jalisco original, use 5 lb bone-in goat (or lamb) shoulder and braise until tender, about 3 hours.', 'Chill the consomé overnight and lift off the fat as a solid disk — the easiest way to save it for frying the tortillas.']::text[], 'https://images.pexels.com/photos/31632714/pexels-photo-31632714.jpeg', 'Birria tacos with a cup of consommé and fresh radishes', 'lucia photography in progress cano', 'https://www.pexels.com/@lucia-photography-in-progress-cano-318039738/', 'https://www.pexels.com/photo/authentic-birria-tacos-with-consomme-31632714/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner', 'entertaining']::text[], array['braise', 'pan_fry', 'boil']::text[], array['tangy', 'fresh', 'aromatic']::text[], '{}'::text[], 'Jalisco', 'adapted', 'birria-tacos', 'classic', 'Refrigerate meat and consomé separately up to 4 days, or freeze up to 3 months.', null, 'owned', array['milk']::text[], array['beef']::text[], array['gluten_free']::text[], array['guajillo chile', 'ancho chile', 'roma tomato', 'white onion', 'garlic', 'cider vinegar', 'ground cumin', 'mexican oregano', 'dried thyme', 'clove', 'black peppercorn', 'cinnamon stick', 'chuck roast', 'short rib', 'bay leave', 'corn tortilla', 'oaxaca cheese', 'cilantro', 'lime']::text[], 'ancho chile|bay leave|black peppercorn|chuck roast|cider vinegar|cilantro|cinnamon stick|clove|corn tortilla|dried thyme|garlic|ground cumin|guajillo chile|lime|mexican oregano|oaxaca cheese|roma tomato|short rib|white onion',
  null, null, null, null, null, null, null, null)
