insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('a083ce6b-dcad-496a-b9a0-9c509a60c8f1', 1, 'Adobo', 'Stem and seed the dried chiles and toast them in a dry skillet over medium heat until fragrant, 15–20 seconds per side. Cover with boiling water and soak 20 minutes. Meanwhile, char the tomatoes, onion and garlic in the skillet until spotted black, about 8 minutes, and peel the garlic.', 1200, null, null),
  ('a083ce6b-dcad-496a-b9a0-9c509a60c8f1', 2, 'Adobo', 'Drain the chiles and blend them with the charred vegetables, vinegar, cumin, oregano, thyme, cloves, peppercorns, cinnamon and 1 cup of the water until very smooth. Strain.', 300, null, null),
  ('a083ce6b-dcad-496a-b9a0-9c509a60c8f1', 3, 'Beef', 'Heat the oven to 325°F. Season the beef with the salt. Heat the oil in a large Dutch oven over medium-high heat and brown the meat well in batches, 8–10 minutes per batch.', 1200, 162.8, null),
  ('a083ce6b-dcad-496a-b9a0-9c509a60c8f1', 4, 'Beef', 'Return all the meat to the pot, pour over the adobo and the remaining 5 cups of water, add the bay leaves and bring to a boil. Cover and braise in the oven until the beef falls apart, 3–3½ hours; it will be well past the 145°F safe point.', 11700, 162.8, 62.8),
  ('a083ce6b-dcad-496a-b9a0-9c509a60c8f1', 5, 'Beef', 'Lift out the meat and shred it, discarding bones and gristle. Skim the red fat off the cooking liquid into a small bowl. Season the liquid — the consomé — with salt; it should taste rich and brothy. Moisten the meat with a ladleful.', 600, null, null),
  ('a083ce6b-dcad-496a-b9a0-9c509a60c8f1', 6, 'Tacos', 'Heat a griddle or large skillet over medium heat. Dip a tortilla in the red fat, lay it in the pan, cover half with cheese and meat, fold it over and cook until crisp and the cheese melts, 2–3 minutes per side. Repeat, keeping finished tacos warm in a low oven.', 1500, null, null),
  ('a083ce6b-dcad-496a-b9a0-9c509a60c8f1', 7, null, 'Serve the tacos with cups of hot consomé topped with onion and cilantro for dipping, and lime wedges on the side.', null, null, null);

