values ('5aa9ac39-0cc2-4eee-9bf7-8ff824cc033f', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'loaf-pan-tacos-al-pastor', 'tacos-al-pastor-5aa9ac', 'Tacos al Pastor', 'Thin pork shoulder slices marinated in a brick-red guajillo-achiote adobo with pineapple juice, stacked and roasted, then shaved, crisped and tucked into small tortillas with pineapple, onion and cilantro; we roast the stack in a loaf pan instead of on a vertical spit.', 'mexican', 3, 270, 115, 385, 6, 'main', null, 0, array['oven', 'stove', 'blender', 'cast_iron']::text[], array['entertaining']::text[], array['Achiote paste (also sold as recado rojo) is in the Mexican aisle; it stains, so wear gloves and use a board you don''t mind tinting.', 'Partly freezing the pork makes thin slicing much easier — or ask the butcher to slice it for you.']::text[], 'https://images.pexels.com/photos/7388095/pexels-photo-7388095.jpeg', 'Three tacos al pastor with cilantro and onion and salsa', 'Amy Farías', 'https://www.pexels.com/@amfaru/', 'https://www.pexels.com/photo/cooked-food-on-brown-wooden-tray-7388095/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner', 'entertaining']::text[], array['roast', 'pan_fry']::text[], array['spicy', 'smoky', 'tangy', 'fresh', 'aromatic']::text[], '{}'::text[], 'Mexico City', 'adapted', 'tacos-al-pastor', 'classic', 'Refrigerate the unsliced stack up to 4 days; shave and crisp portions as needed.', null, 'owned', '{}'::text[], array['pork']::text[], array['gluten_free', 'dairy_free']::text[], array['guajillo chile', 'achiote paste', 'pineapple juice', 'white vinegar', 'garlic', 'chile adobo', 'mexican oregano', 'ground cumin', 'ground clove', 'pork shoulder', 'pineapple', 'corn tortilla', 'white onion', 'cilantro', 'lime']::text[], 'achiote paste|chile adobo|cilantro|corn tortilla|garlic|ground clove|ground cumin|guajillo chile|lime|mexican oregano|pineapple|pineapple juice|pork shoulder|white onion|white vinegar',
  null, null, null, null, null, null, null, null)
