values ('48e2011b-e505-495d-a6c7-15f72d424730', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'pork-tamales-rojos', 'pork-tamales-48e201', 'Pork Tamales', 'Tender masa tamales filled with pork shoulder simmered in red guajillo chile sauce, wrapped in corn husks and steamed — the classic Christmas tamal rojo, made by the batch.', 'mexican', 3, 150, 240, 390, 12, 'main', null, 0, array['stove']::text[], array['make-ahead', 'freezer-friendly', 'entertaining', 'weekend-project']::text[], array['You''ll need a tall pot with a steamer basket (or a tamalera) that holds the tamales standing up. Make the filling a day ahead and invite friends — a tamalada is the traditional way to tackle a big batch.', 'To freeze, cool steamed tamales completely and freeze in bags up to 4 months; steam from frozen for 25–30 minutes.']::text[], 'https://images.pexels.com/photos/33490796/pexels-photo-33490796.jpeg', 'Plate of tamales being cut with a fork', 'Urian Rivera', 'https://www.pexels.com/@urianrivera/', 'https://www.pexels.com/photo/hand-cutting-into-delicious-tamales-on-plate-33490796/', 'pexels', true, 'public', false,
  'pending_review', array['holiday', 'main', 'dinner', 'entertaining']::text[], array['stew', 'steam', 'boil']::text[], array['aromatic']::text[], array['christmas', 'new-year']::text[], null, 'traditional', 'pork-tamales', 'classic', 'Refrigerate up to 1 week; steam 15 minutes, or microwave in the husk wrapped in a damp paper towel.', null, 'owned', '{}'::text[], array['pork']::text[], array['dairy_free']::text[], array['pork shoulder', 'white onion', 'garlic', 'bay leave', 'guajillo chile', 'ancho chile', 'ground cumin', 'mexican oregano', 'lard', 'baking powder', 'masa harina', 'pork broth', 'corn husk']::text[], 'ancho chile|baking powder|bay leave|corn husk|garlic|ground cumin|guajillo chile|lard|masa harina|mexican oregano|pork broth|pork shoulder|white onion',
  null, null, null, null, null, null, null, null)
