delete from public.recipe_instructions where recipe_id = '48e2011b-e505-495d-a6c7-15f72d424730';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('48e2011b-e505-495d-a6c7-15f72d424730', 1, 'Pork', 'Simmer the pork with the onion, garlic, bay leaves, salt and water, partly covered, until fork-tender, 2–2½ hours (well past 145°F). Lift out the pork and shred it; strain and save the broth.', 8100, null, 62.8),
  ('48e2011b-e505-495d-a6c7-15f72d424730', 2, 'Wrapping', 'Meanwhile, soak the corn husks in a large bowl of very hot water, weighed down with a plate, until pliable, at least 1 hour.', 3600, null, null),
  ('48e2011b-e505-495d-a6c7-15f72d424730', 3, 'Red chile', 'Stem and seed the chiles, toast them in a dry skillet 15–20 seconds per side and soak in hot water 20 minutes. Blend with the garlic, cumin, oregano and 2 cups of the pork broth until smooth, then strain. Heat the lard in a skillet, pour in the sauce (it spatters), add the salt and simmer 10 minutes. Stir 2 cups into the shredded pork and keep the rest.', 2100, null, null),
  ('48e2011b-e505-495d-a6c7-15f72d424730', 4, 'Masa', 'Beat the lard with the baking powder and salt in a stand mixer or with a hand mixer until white and fluffy, 3 minutes. On low, add the masa harina in thirds, alternating with the warm broth, then beat on medium for 5 minutes. A ½-teaspoon dab should float in a glass of cold water; if it sinks, beat 2 minutes more and test again. Beat in ½ cup of the leftover red sauce for color.', 720, null, null),
  ('48e2011b-e505-495d-a6c7-15f72d424730', 5, 'Wrapping', 'Pat a husk dry and lay it smooth side up, wide end toward you. Spread about 3 tablespoons of masa thinly over the wide two-thirds, leaving a border at the sides. Spoon 1½ tablespoons of filling down the middle, fold the sides over to enclose it, then fold the narrow end up. Repeat.', 2700, null, null),
  ('48e2011b-e505-495d-a6c7-15f72d424730', 6, 'Wrapping', 'Set a steamer basket in a tall pot (or use a tamalera) with water below the basket. Stand the tamales upright, open end up, packed snugly but not tightly. Cover with extra husks and a damp towel, then the lid, and steam over medium heat for 1½ hours, adding boiling water as needed so the pot never runs dry.', 5400, null, null),
  ('48e2011b-e505-495d-a6c7-15f72d424730', 7, null, 'The tamales are done when the masa pulls cleanly away from the husk. Let them rest in the pot off the heat for 15 minutes to firm up, then serve with the remaining sauce.', 900, null, null);

-- Tlayudas
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
