values ('588a3f65-b351-4c5c-acd1-2539a5fcb401', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'oaxacan-tlayudas', 'tlayudas-588a3f', 'Tlayudas', 'Oaxaca''s giant crisp tortillas spread with pork lard and black beans, layered with stringy quesillo and thin salted beef and toasted until crackly; we swap Oaxacan tasajo for thin-sliced sirloin and offer tostadas as a stand-in for hard-to-find tlayudas.', 'mexican', 3, 25, 40, 65, 4, 'main', null, 0, array['stove', 'cast_iron']::text[], array['entertaining']::text[], array['Tlayudas are sold in Mexican markets and online. Large corn tostadas give a similar crunch but are best left open-faced and baked at 425°F until the cheese melts, 6–8 minutes.', 'Asiento — the toasty, brown pork lard left from making chicharrón — is the Oaxacan secret, but plain lard still tastes great.']::text[], 'https://images.pexels.com/photos/35020125/pexels-photo-35020125.jpeg', 'Tlayuda topped with avocado, cheese and vegetables', 'César O''neill', 'https://www.pexels.com/@cesar-o-neill-26650613/', 'https://www.pexels.com/photo/traditional-mexican-tlayuda-with-avocado-35020125/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner', 'entertaining']::text[], array['pan_fry']::text[], array['tangy']::text[], '{}'::text[], 'Oaxaca', 'adapted', 'tlayudas', 'classic', 'Best eaten right away. Refrigerate leftover beans and beef up to 4 days.', null, 'owned', array['milk']::text[], array['beef', 'pork', 'beans']::text[], array['gluten_free']::text[], array['lard', 'white onion', 'garlic', 'black bean', 'beef sirloin', 'lime juice', 'corn tlayuda', 'pork lard', 'oaxaca cheese', 'green cabbage', 'roma tomato', 'avocado']::text[], 'avocado|beef sirloin|black bean|corn tlayuda|garlic|green cabbage|lard|lime juice|oaxaca cheese|pork lard|roma tomato|white onion',
  null, null, null, null, null, null, null, null)
