  ('588a3f65-b351-4c5c-acd1-2539a5fcb401', 10, 'Tlayudas', '4 corn tlayudas, 12-inch, or 8 large corn tostadas', 'corn tlayudas', 4, null, '12-inch, or 8 large corn tostadas', false),
  ('588a3f65-b351-4c5c-acd1-2539a5fcb401', 11, 'Tlayudas', '¼ cup pork lard, asiento if you can find it, softened', 'pork lard', 0.25, 'cup', 'asiento if you can find it, softened', false),
  ('588a3f65-b351-4c5c-acd1-2539a5fcb401', 12, 'Tlayudas', '12 oz Oaxaca cheese, pulled into thin strings', 'Oaxaca cheese', 12, 'oz', 'pulled into thin strings', false),
