delete from public.recipe_instructions where recipe_id = '588a3f65-b351-4c5c-acd1-2539a5fcb401';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('588a3f65-b351-4c5c-acd1-2539a5fcb401', 1, 'Beans', 'Heat the lard in a skillet over medium heat and cook the onion until soft, 5 minutes; add the garlic for 30 seconds. Add the beans with their liquid, the salt and avocado leaves and bubble 5 minutes, then mash and keep cooking, stirring, until you have a thick paste you can spread, 5–8 minutes more (or blend it smooth).', 1080, null, null),
  ('588a3f65-b351-4c5c-acd1-2539a5fcb401', 2, 'Beef', 'Rub the beef with the lime juice and salt. Sear it in a very hot, dry cast-iron skillet until browned and 145°F, 1–2 minutes per side. Rest 3 minutes and cut into strips.', 240, null, 62.8),
  ('588a3f65-b351-4c5c-acd1-2539a5fcb401', 3, 'Tlayudas', 'Wipe out the skillet and set it over medium heat. Spread each tlayuda thinly with a tablespoon of the softened lard, then a thin layer of beans, and scatter a quarter of the cheese over one half.', null, null, null),
  ('588a3f65-b351-4c5c-acd1-2539a5fcb401', 4, 'Tlayudas', 'Lay one in the skillet (a big tlayuda will hang over the edge — that''s fine), add a quarter of the beef over the cheese, fold it in half and press. Toast until the tortilla is crackly and the cheese has melted, 3–4 minutes per side. Repeat, keeping the finished ones warm in a 200°F oven.', 960, null, null),
  ('588a3f65-b351-4c5c-acd1-2539a5fcb401', 5, null, 'Open them up and top with cabbage, tomato and avocado, or serve folded with the toppings and salsa on the side.', null, null, null);

