values ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'huachinango-a-la-veracruzana', 'huachinango-a-la-veracruzana-6e79c1', 'Huachinango a la Veracruzana', 'Whole red snapper baked in Veracruz''s bright tomato sauce with green olives, capers, pickled chiles and bay — a Gulf Coast classic with Spanish roots.', 'mexican', 3, 25, 55, 80, 4, 'main', null, 0, array['oven', 'stove']::text[], array['entertaining']::text[], array['Fillets work too: use four 6-ounce snapper or other firm white fish fillets and bake 12–15 minutes.', 'Ask the fishmonger to scale and gut the fish and trim the fins for you.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'entertaining']::text[], array['stew', 'bake']::text[], array['spicy', 'tangy', 'fresh']::text[], '{}'::text[], 'Veracruz', 'traditional', 'huachinango-veracruzana', 'classic', 'Best fresh; refrigerate leftovers up to 2 days and reheat gently.', null, 'owned', array['fish']::text[], array['fish']::text[], array['pescatarian', 'gluten_free', 'dairy_free']::text[], array['red snapper', 'lime juice', 'white onion', 'garlic', 'tomato', 'green olive', 'caper', 'pickled jalapeno', 'bay leave', 'mexican oregano', 'dried thyme', 'parsley', 'white rice']::text[], 'bay leave|caper|dried thyme|garlic|green olive|lime juice|mexican oregano|parsley|pickled jalapeno|red snapper|tomato|white onion|white rice',
