  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 3, 'Fish', '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 4, 'Sauce', '⅓ cup olive oil', 'olive oil', 0.33, 'cup', null, false),
  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 5, 'Sauce', '1 white onion, thinly sliced', 'white onion', 1, null, 'thinly sliced', false),
  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 6, 'Sauce', '5 cloves garlic, thinly sliced', 'garlic', 5, 'clove', 'thinly sliced', false),
  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 7, 'Sauce', '2 lb ripe tomatoes, chopped, or one 28-oz can diced tomatoes', 'ripe tomatoes', 2, 'lb', 'chopped, or one 28-oz can diced tomatoes', false),
  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 8, 'Sauce', '½ cup pimiento-stuffed green olives, halved', 'pimiento-stuffed green olives', 0.5, 'cup', 'halved', false),
  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 9, 'Sauce', '2 tbsp capers, drained', 'capers', 2, 'tbsp', 'drained', false),
  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 10, 'Sauce', '4 pickled jalapeños, or chiles güeros, plus 2 tbsp of their brine', 'pickled jalapeños', 4, null, 'or chiles güeros, plus 2 tbsp of their brine', false),
  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 11, 'Sauce', '3 bay leaves', 'bay leaves', 3, null, null, false),
  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 12, 'Sauce', '½ tsp dried Mexican oregano', 'dried Mexican oregano', 0.5, 'tsp', null, false),
  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 13, 'Sauce', '½ tsp dried thyme', 'dried thyme', 0.5, 'tsp', null, false),
  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 14, 'Sauce', '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 15, 'Sauce', '¼ cup fresh parsley, chopped', 'fresh parsley', 0.25, 'cup', 'chopped', false),
