delete from public.recipe_instructions where recipe_id = '6e79c14c-ac23-494b-bbdf-7768a02eb92e';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 1, 'Fish', 'Rinse the snapper and pat it dry. Cut 3 diagonal slashes down to the bone on each side, rub inside and out with the lime juice and salt and refrigerate 15 minutes while you make the sauce.', 900, null, null),
  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 2, 'Sauce', 'Heat the oil in a large skillet over medium heat. Cook the onion until soft, 6 minutes, then the garlic for 1 minute. Add the tomatoes and simmer, stirring now and then, until they collapse into a chunky sauce, 12–15 minutes.', 1200, null, null),
  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 3, 'Sauce', 'Stir in the olives, capers, pickled chiles and brine, bay leaves, oregano, thyme and salt and simmer 5 minutes more. It should taste bright, briny and savory.', 300, null, null),
  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 4, 'Fish', 'Heat the oven to 400°F. Spoon a third of the sauce into a baking dish big enough for the fish, lay the snapper on top and spoon the rest over it and into the slashes.', null, 204.4, null),
  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 5, 'Fish', 'Bake until the flesh is opaque, flakes away from the bone at the thickest part and reads 145°F, 25–30 minutes.', 1680, 204.4, 62.8),
  ('6e79c14c-ac23-494b-bbdf-7768a02eb92e', 6, null, 'Scatter with parsley and bring the dish to the table. Lift the top fillet off the bone, then pull out the backbone to free the bottom fillet. Serve with rice and plenty of sauce.', null, null, null);

