values ('5d91c3c6-f822-4a0c-998d-c61290b4a87d', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'oaxacan-mole-negro', 'mole-negro-5d91c3', 'Mole Negro', 'Oaxaca''s darkest, most complex mole — chiles toasted nearly black, charred tortilla and chile seeds, fried plantain, nuts, spices and chocolate ground into an inky, bittersweet sauce for chicken; we use easy-to-find mulato and pasilla chiles in place of the rare chilhuacle negro.', 'mexican', 4, 75, 180, 255, 8, 'main', null, 0, array['stove', 'blender', 'dutch_oven']::text[], array['make-ahead', 'entertaining', 'weekend-project']::text[], array['Mexican chocolate tablets can contain milk or soy; check the label if that matters to anyone at the table.', 'Buy dried avocado leaves (hojas de aguacate) sold for cooking at Mexican markets; they add a faint anise note. The finished mole keeps and freezes beautifully, so it''s worth a double batch.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'entertaining']::text[], array['stew', 'boil']::text[], array['spicy', 'smoky', 'aromatic']::text[], '{}'::text[], 'Oaxaca', 'adapted', 'mole-negro', 'classic', 'Refrigerate up to 5 days; freeze the sauce on its own up to 6 months.', null, 'owned', array['egg', 'gluten', 'sesame', 'tree_nut', 'wheat']::text[], array['chicken']::text[], '{}'::text[], array['thigh drumstick', 'white onion', 'garlic', 'mulato chile', 'pasilla chile', 'guajillo chile', 'chipotle chile', 'lard', 'corn tortilla', 'very plantain', 'almond', 'pecan halve', 'raisin', 'challah bread', 'sesame seed', 'allspice berry', 'clove', 'black peppercorn', 'cinnamon stick', 'roma tomato', 'tomatillo', 'mexican oregano', 'dried thyme', 'dried marjoram', 'mexican chocolate']::text[], 'allspice berry|almond|black peppercorn|challah bread|chipotle chile|cinnamon stick|clove|corn tortilla|dried marjoram|dried thyme|garlic|guajillo chile|lard|mexican chocolate|mexican oregano|mulato chile|pasilla chile|pecan halve|raisin|roma tomato|sesame seed|thigh drumstick|tomatillo|very plantain|white onion',
