delete from public.recipe_instructions where recipe_id = '5d91c3c6-f822-4a0c-998d-c61290b4a87d';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('5d91c3c6-f822-4a0c-998d-c61290b4a87d', 1, 'Chicken', 'Put the chicken in a large pot with the onion, garlic, salt and enough water to cover. Bring to a boil, skim, then simmer partly covered until tender and 165°F at the bone, 35–40 minutes. Lift out the chicken and strain and save the broth (about 10 cups).', 2400, null, 73.9),
  ('5d91c3c6-f822-4a0c-998d-c61290b4a87d', 2, 'Chiles', 'Stem and seed the chiles, saving all the seeds. Toast the chiles a few at a time in a dry skillet over medium heat until very dark — nearly black but not crumbling to ash — 30–45 seconds per side. Soak in 4 cups of hot broth for 30 minutes. Open a window and run the fan: toasting chiles this dark gives off harsh, peppery fumes.', 1800, null, null),
  ('5d91c3c6-f822-4a0c-998d-c61290b4a87d', 3, 'Mole', 'In the same dry skillet, toast the chile seeds over medium-high heat, stirring, until completely black, 5–6 minutes. Hold the tortilla with tongs over a gas flame (or press it in the skillet) until charred black all over. Cover the seeds and tortilla with water for 10 minutes, then drain — this tames the bitterness.', 900, null, null),
  ('5d91c3c6-f822-4a0c-998d-c61290b4a87d', 4, 'Mole', 'Heat 3 tablespoons of the lard in the skillet over medium heat. Fry each in turn, lifting it out when done: plantain until deep brown, 4 minutes; almonds and pecans until toasted, 3 minutes; raisins until puffed, 30 seconds; bread until golden, 1 minute. Toast the sesame seeds, allspice, cloves, peppercorns and cinnamon in the dry pan until fragrant, 2 minutes.', 720, null, null),
  ('5d91c3c6-f822-4a0c-998d-c61290b4a87d', 5, 'Mole', 'Char the tomatoes, tomatillos, onion and garlic in the skillet until blackened and soft, 10 minutes; peel the garlic. Blend the chiles with their soaking broth until smooth, then blend everything else with the oregano, thyme, marjoram and 2 cups of broth, in batches, until very smooth. Strain both purées.', 1500, null, null),
  ('5d91c3c6-f822-4a0c-998d-c61290b4a87d', 6, 'Mole', 'Heat the remaining lard in a Dutch oven over medium-high heat. Pour in the purée (stand back, it spatters) and fry, stirring constantly and scraping the bottom, until it turns nearly black and very thick, about 15 minutes.', 900, null, null),
  ('5d91c3c6-f822-4a0c-998d-c61290b4a87d', 7, 'Mole', 'Stir in 3 cups of broth, the chocolate, sugar, salt and avocado leaves. Simmer on low, stirring often, for 1 hour, adding broth as needed, until glossy, nearly black and thick enough to coat a spoon. Remove the leaves.', 3600, null, null),
  ('5d91c3c6-f822-4a0c-998d-c61290b4a87d', 8, null, 'Add the chicken and simmer 15 minutes to heat through. Serve with a scattering of sesame seeds, white rice and warm tortillas.', 900, null, null);

-- Churros with Chocolate
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
  status, categories, methods, flavors, occasions, region, authenticity, dish_key, variant, storage_notes, safety_note, text_license, allergens, proteins, diet_tags, core_ingredients, fingerprint,
  attribution, reviewed_by, reviewed_at, calories_per_serving, protein_g, carbs_g, fat_g, nutrition_source)
values ('e30b7272-c940-4411-a7a2-017b8d9e8f1a', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'churros-con-chocolate', 'churros-with-chocolate-e30b72', 'Churros with Chocolate', 'Crisp, ridged fried dough rolled in cinnamon sugar and dunked in thick Mexican hot chocolate, made the common Mexican way with an egg in the dough for a light, tender center.', 'mexican', 2, 20, 35, 55, 6, 'dessert', 'pastries', 0, array['stove']::text[], array['kid-friendly', 'entertaining']::text[], array['The star tip isn''t just for looks: the ridges help churros cook evenly and keep them from bursting in the oil.', 'Mexican chocolate tablets can contain soy; check the label if that matters. Let the oil cool completely before straining and storing or discarding it.']::text[], 'https://images.pexels.com/photos/36361402/pexels-photo-36361402.jpeg', 'Cinnamon-sugar churros with a chocolate dip on a dark plate', 'Çiğdem Bilgin', 'https://www.pexels.com/@cigdem-bilgin-2154409770/', 'https://www.pexels.com/photo/delicious-cinnamon-churros-with-chocolate-dip-36361402/', 'pexels', true, 'public', false,
  'pending_review', array['dessert', 'comfort', 'entertaining']::text[], array['fry', 'boil']::text[], array['aromatic', 'sweet']::text[], '{}'::text[], null, 'traditional', 'churros', 'classic', 'Churros are best within an hour. Re-crisp in a 375°F oven for 5 minutes; the chocolate keeps 3 days in the fridge.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['milk', 'mexican chocolate', 'bittersweet chocolate', 'cornstarch', 'ground cinnamon', 'egg', 'vanilla extract']::text[], 'bittersweet chocolate|cornstarch|egg|ground cinnamon|mexican chocolate|milk|vanilla extract',
  null, null, null, null, null, null, null, null)
