  ('e30b7272-c940-4411-a7a2-017b8d9e8f1a', 8, 'Churros', '1 cup water', 'water', 1, 'cup', null, false),
  ('e30b7272-c940-4411-a7a2-017b8d9e8f1a', 9, 'Churros', '4 tbsp unsalted butter', 'unsalted butter', 4, 'tbsp', null, false),
  ('e30b7272-c940-4411-a7a2-017b8d9e8f1a', 10, 'Churros', '2 tbsp sugar', 'sugar', 2, 'tbsp', null, false),
  ('e30b7272-c940-4411-a7a2-017b8d9e8f1a', 11, 'Churros', '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('e30b7272-c940-4411-a7a2-017b8d9e8f1a', 12, 'Churros', '1 cup all-purpose flour', 'all-purpose flour', 1, 'cup', null, false),
  ('e30b7272-c940-4411-a7a2-017b8d9e8f1a', 13, 'Churros', '1 large egg', 'large egg', 1, null, null, false),
