values ('45e067f6-0e6e-4501-bb3a-ff48c42d3844', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'tres-leches-cake', 'tres-leches-cake-45e067', 'Tres Leches Cake', 'A light, airy sponge soaked with evaporated milk, sweetened condensed milk and cream, then topped with whipped cream and cinnamon — cool, rich and best made a day ahead.', 'mexican', 2, 30, 40, 310, 12, 'dessert', 'cakes', 240, array['oven']::text[], array['make-ahead', 'entertaining', 'kid-friendly']::text[], array['Fold gently and stop as soon as the whites disappear — the airy sponge is what lets the cake drink up the milks without turning soggy.', 'Pour the soak slowly, pausing to let it sink in, so it doesn''t pool around the edges.']::text[], 'https://images.pexels.com/photos/37228442/pexels-photo-37228442.jpeg', 'Slice of tres leches cake topped with cherries', 'Cristian Arteaga', 'https://www.pexels.com/@cristian-arteaga-1679611/', 'https://www.pexels.com/photo/delicious-tres-leches-cake-with-cherries-in-quito-ecuador-37228442/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'dessert', 'comfort', 'entertaining']::text[], array['bake']::text[], array['rich', 'aromatic', 'sweet']::text[], '{}'::text[], null, 'traditional', 'tres-leches-cake', 'classic', 'Keep covered in the fridge up to 4 days. Not suitable for freezing once soaked.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['baking powder', 'egg', 'milk', 'vanilla extract', 'evaporated milk', 'condensed milk', 'heavy cream', 'powdered sugar', 'ground cinnamon']::text[], 'baking powder|condensed milk|egg|evaporated milk|ground cinnamon|heavy cream|milk|powdered sugar|vanilla extract',
  null, null, null, null, null, null, null, null)
