delete from public.recipe_instructions where recipe_id = '45e067f6-0e6e-4501-bb3a-ff48c42d3844';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('45e067f6-0e6e-4501-bb3a-ff48c42d3844', 1, 'Cake', 'Heat the oven to 350°F and butter a 9-by-13-inch baking pan. Whisk the flour, baking powder and salt together.', null, 176.7, null),
  ('45e067f6-0e6e-4501-bb3a-ff48c42d3844', 2, 'Cake', 'With a stand or hand mixer, beat the egg yolks with ¾ cup of the sugar until pale and thick, 2 minutes, then beat in the milk and vanilla. In a clean bowl with clean beaters, whip the whites to soft peaks, add the remaining ¼ cup sugar and whip to firm, glossy peaks.', 360, null, null),
  ('45e067f6-0e6e-4501-bb3a-ff48c42d3844', 3, 'Cake', 'Fold the flour mixture into the yolks, then gently fold in the whites in three additions until no streaks remain. Spread evenly in the pan.', null, null, null),
  ('45e067f6-0e6e-4501-bb3a-ff48c42d3844', 4, 'Cake', 'Bake until golden and springy and a toothpick comes out clean, 22–25 minutes. Cool in the pan 15 minutes.', 2400, 176.7, null),
  ('45e067f6-0e6e-4501-bb3a-ff48c42d3844', 5, 'Soak', 'Whisk the three milks together. Poke the warm cake all over with a fork or skewer, then pour the milk mixture slowly and evenly over it. It looks like too much, but it all soaks in. Cover and refrigerate at least 4 hours, ideally overnight.', 14400, null, null),
  ('45e067f6-0e6e-4501-bb3a-ff48c42d3844', 6, 'Topping', 'Whip the cold cream with the powdered sugar and vanilla to soft peaks. Spread over the chilled cake and dust with cinnamon. Cut into squares and serve cold, with strawberries if you like.', null, null, null);

-- Curry Goat
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
