values ('b3834e3d-abca-42c9-8f76-74a326b795c6', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'jamaican-curry-goat', 'curry-goat-b3834e', 'Curry Goat', 'Bone-in goat marinated in Jamaican curry powder, allspice, thyme and Scotch bonnet, then braised low and slow until it falls from the bone in a rich, golden gravy with potatoes.', 'caribbean', 3, 30, 165, 435, 6, 'main', null, 240, array['stove', 'dutch_oven']::text[], array['comfort', 'make-ahead', 'entertaining']::text[], array['No goat? Bone-in lamb shoulder is the closest swap and cooks in about the same time.', 'Some curry powder blends contain mustard or wheat; check the label if anyone at the table has those allergies.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'comfort', 'entertaining']::text[], array['stew', 'pan_fry', 'boil']::text[], array['spicy', 'aromatic']::text[], '{}'::text[], 'Jamaica', 'traditional', 'curry-goat', 'classic', 'Refrigerate up to 4 days or freeze up to 3 months — it tastes even better the next day. Reheat gently with a splash of water.', null, 'owned', '{}'::text[], array['goat']::text[], array['gluten_free', 'dairy_free']::text[], array['goat meat', 'curry powder', 'ground allspice', 'yellow onion', 'garlic', 'ginger', 'scallion', 'thyme', 'bonnet pepper', 'gold potato', 'white rice']::text[], 'bonnet pepper|curry powder|garlic|ginger|goat meat|gold potato|ground allspice|scallion|thyme|white rice|yellow onion',
  null, null, null, null, null, null, null, null)
