  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 1, 'Marinade', '3 lb bone-in goat meat, cut into 2-inch pieces (ask the butcher to saw it)', 'bone-in goat meat', 3, 'lb', 'cut into 2-inch pieces (ask the butcher to saw it)', false),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 2, 'Marinade', '3 tbsp Jamaican curry powder, divided', 'Jamaican curry powder', 3, 'tbsp', 'divided', false),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 3, 'Marinade', '2 tsp kosher salt', 'kosher salt', 2, 'tsp', null, false),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 4, 'Marinade', '1 tsp black pepper', 'black pepper', 1, 'tsp', null, false),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 5, 'Marinade', '1 tsp ground allspice', 'ground allspice', 1, 'tsp', null, false),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 6, 'Marinade', '1 yellow onion, chopped', 'yellow onion', 1, null, 'chopped', false),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 7, 'Marinade', '6 cloves garlic, minced', 'garlic', 6, 'clove', 'minced', false),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 8, 'Marinade', '1 tbsp fresh ginger, grated', 'fresh ginger', 1, 'tbsp', 'grated', false),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 9, 'Marinade', '4 scallions, chopped', 'scallions', 4, null, 'chopped', false),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 10, 'Marinade', '6 sprigs fresh thyme', 'fresh thyme', 6, 'sprig', null, false),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 11, 'Braise', '3 tbsp vegetable oil', 'vegetable oil', 3, 'tbsp', null, false),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 12, 'Braise', '1 Scotch bonnet pepper, left whole, or seeded and minced for more heat', 'Scotch bonnet pepper', 1, null, 'left whole, or seeded and minced for more heat', false),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 13, 'Braise', '4 cups water, plus more as needed', 'water', 4, 'cup', 'plus more as needed', false),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 14, 'Braise', '1½ lb Yukon Gold potatoes, peeled and cut into 1½-inch chunks', 'Yukon Gold potatoes', 1.5, 'lb', 'peeled and cut into 1½-inch chunks', false),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 15, 'Braise', '6 cups cooked white rice, or rice and peas, to serve', 'cooked white rice', 6, 'cup', 'or rice and peas, to serve', false);
delete from public.recipe_instructions where recipe_id = 'b3834e3d-abca-42c9-8f76-74a326b795c6';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 1, 'Marinade', 'Rinse the goat, pat it dry and toss in a large bowl with 2 tablespoons of the curry powder, the salt, pepper, allspice, onion, garlic, ginger, scallions and thyme. Cover and refrigerate at least 4 hours or overnight.', 14400, null, null),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 2, 'Braise', 'Heat the oil in a Dutch oven over medium heat. Add the remaining 1 tablespoon curry powder and stir for 30–60 seconds until it darkens slightly and smells toasty — this ''burning'' of the curry is what gives the dish its depth.', 60, null, null),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 3, 'Braise', 'Scrape the marinade off the meat and set it aside. Raise the heat to medium-high and brown the goat in 2 batches, turning, about 8 minutes per batch.', 960, null, null),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 4, 'Braise', 'Return all the meat with the reserved marinade, the Scotch bonnet and the water. Bring to a boil, then cover and simmer gently, stirring now and then and topping up with water so it stays saucy, until the goat is tender, 1½–2 hours.', 6300, null, null),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 5, 'Braise', 'Add the potatoes and simmer uncovered until they are soft and starting to break down into the gravy and the goat is falling off the bone (far past the 145°F safe minimum), about 30 minutes more.', 1800, null, 62.8),
  ('b3834e3d-abca-42c9-8f76-74a326b795c6', 6, null, 'Fish out the thyme stems and the whole Scotch bonnet. Taste for salt and serve with rice.', null, null, null);

-- Braised Oxtail with Butter Beans
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
