values ('d656dec0-078e-4dd8-b0cb-09af9ed093ad', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'jamaican-oxtail-butter-beans', 'braised-oxtail-with-butter-beans-d656de', 'Braised Oxtail with Butter Beans', 'Oxtail seasoned with allspice, thyme and browning, seared dark and braised for hours until sticky and tender, with butter beans folded into the glossy gravy at the end.', 'jamaican', 3, 30, 210, 480, 6, 'main', null, 240, array['stove', 'dutch_oven']::text[], array['comfort', 'make-ahead', 'sunday-dinner']::text[], array['Butter beans are large lima beans; any canned brand works.', 'Short on time? Cook the seared oxtail with its liquid in a pressure cooker on high for 45 minutes, then finish on the stove.', 'Soy sauce contains wheat; browning sauce brands vary, so check the label if that matters.']::text[], 'https://images.pexels.com/photos/30746554/pexels-photo-30746554.jpeg', 'Jamaican braised oxtail in rich gravy served with rice and peas', 'Thomas Wilson', 'https://www.pexels.com/@thomas-wilson-1334312084/', 'https://www.pexels.com/photo/delicious-jamaican-oxtail-and-rice-dish-30746554/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner']::text[], array['stew', 'pan_fry', 'boil']::text[], array['spicy', 'savory', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'oxtail-butter-beans', 'classic', 'Refrigerate up to 4 days (the fat sets on top and is easy to lift off) or freeze up to 3 months.', null, 'owned', array['gluten', 'soy', 'wheat']::text[], array['beef', 'beans']::text[], array['dairy_free']::text[], array['oxtail', 'soy sauce', 'browning sauce', 'ground allspice', 'brown sugar', 'garlic', 'ginger', 'yellow onion', 'scallion', 'thyme', 'allspice berry', 'bonnet pepper', 'ketchup', 'carrot', 'lima bean']::text[], 'allspice berry|bonnet pepper|brown sugar|browning sauce|carrot|garlic|ginger|ground allspice|ketchup|lima bean|oxtail|scallion|soy sauce|thyme|yellow onion',
  null, null, null, null, null, null, null, null)
