  ('d656dec0-078e-4dd8-b0cb-09af9ed093ad', 1, 'Oxtail', '4 lb oxtail, cut into 2-inch pieces, excess fat trimmed', 'oxtail', 4, 'lb', 'cut into 2-inch pieces, excess fat trimmed', false),
  ('d656dec0-078e-4dd8-b0cb-09af9ed093ad', 2, 'Oxtail', '2 tsp kosher salt', 'kosher salt', 2, 'tsp', null, false),
  ('d656dec0-078e-4dd8-b0cb-09af9ed093ad', 3, 'Oxtail', '1 tsp black pepper', 'black pepper', 1, 'tsp', null, false),
  ('d656dec0-078e-4dd8-b0cb-09af9ed093ad', 4, 'Oxtail', '2 tbsp soy sauce', 'soy sauce', 2, 'tbsp', null, false),
  ('d656dec0-078e-4dd8-b0cb-09af9ed093ad', 5, 'Oxtail', '1 tbsp browning sauce', 'browning sauce', 1, 'tbsp', null, false),
  ('d656dec0-078e-4dd8-b0cb-09af9ed093ad', 6, 'Oxtail', '1 tsp ground allspice', 'ground allspice', 1, 'tsp', null, false),
  ('d656dec0-078e-4dd8-b0cb-09af9ed093ad', 7, 'Oxtail', '1 tbsp brown sugar', 'brown sugar', 1, 'tbsp', null, false),
