  ('d656dec0-078e-4dd8-b0cb-09af9ed093ad', 11, 'Braise', '1 yellow onion, chopped', 'yellow onion', 1, null, 'chopped', false),
  ('d656dec0-078e-4dd8-b0cb-09af9ed093ad', 12, 'Braise', '4 scallions, cut into 2-inch lengths', 'scallions', 4, null, 'cut into 2-inch lengths', false),
  ('d656dec0-078e-4dd8-b0cb-09af9ed093ad', 13, 'Braise', '6 sprigs fresh thyme', 'fresh thyme', 6, 'sprig', null, false),
  ('d656dec0-078e-4dd8-b0cb-09af9ed093ad', 14, 'Braise', '8 whole allspice berries', 'whole allspice berries', 8, null, null, false),
