values ('7055738e-5853-4bd3-b841-7e620636830a', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'jamaican-rice-and-peas', 'rice-and-peas-705573', 'Rice and Peas', 'Long-grain rice simmered in coconut milk with red kidney beans, thyme, allspice and a whole Scotch bonnet for fragrance; we use canned beans instead of soaking and boiling dried ones.', 'jamaican', 1, 10, 30, 40, 6, 'side', null, 0, array['stove']::text[], array['budget', 'vegan', 'sunday-dinner']::text[], array['Keep the Scotch bonnet whole — it adds fruity aroma, not fire. If it bursts the rice will be very hot.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['side', 'budget']::text[], array['stew', 'boil']::text[], array['spicy', 'rich', 'aromatic']::text[], '{}'::text[], null, 'adapted', 'rice-and-peas', 'classic', 'Cool quickly and refrigerate up to 4 days. Reheat with a splash of water, covered, until steaming hot.', null, 'owned', '{}'::text[], array['beans']::text[], array['pescatarian', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], array['kidney bean', 'coconut milk', 'garlic', 'scallion', 'thyme', 'allspice berry', 'bonnet pepper', 'white rice']::text[], 'allspice berry|bonnet pepper|coconut milk|garlic|kidney bean|scallion|thyme|white rice',
  null, null, null, null, null, null, null, null)
