delete from public.recipe_instructions where recipe_id = '7055738e-5853-4bd3-b841-7e620636830a';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7055738e-5853-4bd3-b841-7e620636830a', 1, null, 'Put the beans and their liquid, coconut milk, water, garlic, scallions, thyme, allspice, Scotch bonnet and salt in a heavy saucepan with a tight lid. Bring to a boil and simmer 5 minutes so the aromatics flavor the liquid.', 420, null, null),
  ('7055738e-5853-4bd3-b841-7e620636830a', 2, null, 'Stir in the rice, making sure it is just covered by liquid (add a splash of water if not). Return to a boil.', 120, null, null),
  ('7055738e-5853-4bd3-b841-7e620636830a', 3, null, 'Cover tightly, turn the heat to the lowest setting and cook without lifting the lid until the rice is tender and the liquid absorbed, 20–25 minutes.', 1320, null, null),
  ('7055738e-5853-4bd3-b841-7e620636830a', 4, null, 'Take off the heat and let stand, covered, 5 minutes. Carefully lift out the Scotch bonnet without breaking it, plus the scallions and thyme stems, then fluff with a fork.', 300, null, null);

-- Fried Plantains
