values ('bcc46ff3-059e-423f-96a1-1ec4fe709fba', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'jamaican-fried-plantains', 'fried-plantains-bcc46f', 'Fried Plantains', 'Very ripe, black-skinned plantains fried in a shallow layer of oil until caramelized at the edges and custardy inside — the sweet side that goes with almost every Jamaican plate.', 'jamaican', 1, 5, 12, 17, 4, 'side', null, 0, array['stove', 'cast_iron']::text[], array['budget', 'vegan', 'kid-friendly', 'quick']::text[], array['The riper the plantain, the sweeter and softer the result; yellow plantains with a few black spots work but will be firmer and less sweet.']::text[], 'https://images.pexels.com/photos/27556971/pexels-photo-27556971.jpeg', 'Golden fried plantain slices on a white plate', 'Snappr', 'https://www.pexels.com/@snappr/', 'https://www.pexels.com/photo/traditional-caribbean-cuisine-27556971/', 'pexels', true, 'public', false,
  'pending_review', array['side', 'budget', 'comfort']::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, 'traditional', 'fried-sweet-plantains', 'classic', 'Best hot. Refrigerate up to 2 days and re-crisp in a dry skillet or air fryer.', null, 'owned', '{}'::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], array['very plantain']::text[], 'very plantain',
  null, null, null, null, null, null, null, null)
