  ('bcc46ff3-059e-423f-96a1-1ec4fe709fba', 1, null, '2 very ripe plantains, skins mostly black', 'very ripe plantains', 2, null, 'skins mostly black', false),
  ('bcc46ff3-059e-423f-96a1-1ec4fe709fba', 2, null, '½ cup vegetable oil, for shallow frying', 'vegetable oil', 0.5, 'cup', 'for shallow frying', false),
  ('bcc46ff3-059e-423f-96a1-1ec4fe709fba', 3, null, '¼ tsp flaky salt', 'flaky salt', 0.25, 'tsp', null, false);
delete from public.recipe_instructions where recipe_id = 'bcc46ff3-059e-423f-96a1-1ec4fe709fba';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('bcc46ff3-059e-423f-96a1-1ec4fe709fba', 1, null, 'Cut the ends off the plantains, slit the skin lengthwise and peel. Slice on a long diagonal about ½ inch thick.', 180, null, null),
  ('bcc46ff3-059e-423f-96a1-1ec4fe709fba', 2, null, 'Heat the oil in a large skillet (it should be about ¼ inch deep, and the pan well under half full) over medium heat to about 350°F, when a slice sizzles steadily on contact.', 180, 176.7, null),
  ('bcc46ff3-059e-423f-96a1-1ec4fe709fba', 3, null, 'Fry the slices in a single layer, in batches, until deep golden-brown and caramelized, 2–3 minutes per side. Lower the heat if they darken too fast — the sugar burns easily.', 360, 176.7, null),
  ('bcc46ff3-059e-423f-96a1-1ec4fe709fba', 4, null, 'Drain on paper towels, sprinkle with salt and serve warm.', null, null, null);

-- Pernil
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
