values ('d8aa1b5a-a97d-4ec9-93d3-16543d48cbd6', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'puerto-rican-pernil', 'pernil-d8aa1b', 'Pernil', 'A whole pork shoulder rubbed inside and out with a garlic-oregano adobo, marinated overnight and slow-roasted until it pulls apart, then blasted so the skin turns into crackling cuero.', 'puerto_rican', 3, 30, 330, 1080, 10, 'main', null, 720, array['oven']::text[], array['entertaining', 'make-ahead', 'holiday']::text[], array['A 7-pound bone-in shoulder feeds about 10; allow roughly ¾ pound per person, bone in.', 'If the skin hasn''t crackled in 30 minutes, cut it off, lay it on a sheet pan and give it 10 more minutes alone.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['holiday', 'main', 'dinner', 'entertaining']::text[], array['roast']::text[], array['tangy', 'aromatic']::text[], array['christmas', 'new-year', 'thanksgiving']::text[], null, 'traditional', 'pernil', 'classic', 'Refrigerate the meat with its juices up to 4 days or freeze up to 3 months. The cuero is best the day it''s made.', null, 'owned', '{}'::text[], array['pork']::text[], array['gluten_free', 'dairy_free']::text[], array['garlic', 'dried oregano', 'white vinegar']::text[], 'dried oregano|garlic|white vinegar',
  null, null, null, null, null, null, null, null)
