insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('d8aa1b5a-a97d-4ec9-93d3-16543d48cbd6', 1, 'Adobo', '14 cloves garlic, peeled', 'garlic', 14, 'clove', 'peeled', false),
  ('d8aa1b5a-a97d-4ec9-93d3-16543d48cbd6', 2, 'Adobo', '3 tbsp kosher salt', 'kosher salt', 3, 'tbsp', null, false),
  ('d8aa1b5a-a97d-4ec9-93d3-16543d48cbd6', 3, 'Adobo', '1 tbsp dried oregano', 'dried oregano', 1, 'tbsp', null, false),
  ('d8aa1b5a-a97d-4ec9-93d3-16543d48cbd6', 4, 'Adobo', '2 tsp black pepper', 'black pepper', 2, 'tsp', null, false),
  ('d8aa1b5a-a97d-4ec9-93d3-16543d48cbd6', 5, 'Adobo', '1 tsp ground cumin', 'ground cumin', 1, 'tsp', null, true),
  ('d8aa1b5a-a97d-4ec9-93d3-16543d48cbd6', 6, 'Adobo', '¼ cup olive oil', 'olive oil', 0.25, 'cup', null, false),
  ('d8aa1b5a-a97d-4ec9-93d3-16543d48cbd6', 7, 'Adobo', '2 tbsp distilled white vinegar, or sour orange juice', 'distilled white vinegar', 2, 'tbsp', 'or sour orange juice', false),
  ('d8aa1b5a-a97d-4ec9-93d3-16543d48cbd6', 8, 'Pork', '7 lb bone-in, skin-on pork shoulder (picnic roast)', 'bone-in, skin-on pork shoulder (picnic roast)', 7, 'lb', null, false);
delete from public.recipe_instructions where recipe_id = 'd8aa1b5a-a97d-4ec9-93d3-16543d48cbd6';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('d8aa1b5a-a97d-4ec9-93d3-16543d48cbd6', 1, 'Adobo', 'Pound the garlic with the salt in a mortar (or pulse in a small food processor) to a coarse paste, then mix in the oregano, pepper, cumin, oil and vinegar.', null, null, null),
  ('d8aa1b5a-a97d-4ec9-93d3-16543d48cbd6', 2, 'Pork', 'Using a small sharp knife, loosen the skin from the meat along one side so it lifts like a flap, keeping it attached. Cut 1-inch-deep slits all over the meat. Rub the adobo into the slits, all over the meat and under the skin; rub only a little on top of the skin. Fold the skin back down.', 1200, null, null),
  ('d8aa1b5a-a97d-4ec9-93d3-16543d48cbd6', 3, 'Pork', 'Set the pork skin side up in a roasting pan, cover and refrigerate at least 12 hours and up to 48.', 43200, null, null),
  ('d8aa1b5a-a97d-4ec9-93d3-16543d48cbd6', 4, 'Pork', 'Take the pork out 1 hour before cooking and heat the oven to 325°F. Pat the skin very dry. Pour 1 cup water into the pan, cover tightly with foil and roast for 3 hours.', 10800, 162.8, null),
  ('d8aa1b5a-a97d-4ec9-93d3-16543d48cbd6', 5, 'Pork', 'Uncover and keep roasting until the meat is fork-tender and reads about 190°F near the bone (well past the 145°F safe minimum), 1½–2 hours more. Add a splash of water if the pan runs dry.', 6300, 162.8, 62.8),
  ('d8aa1b5a-a97d-4ec9-93d3-16543d48cbd6', 6, 'Pork', 'Raise the oven to 425°F and roast until the skin blisters and turns crisp all over, 20–30 minutes; watch closely so it doesn''t scorch.', 1500, 218.3, null),
  ('d8aa1b5a-a97d-4ec9-93d3-16543d48cbd6', 7, null, 'Rest 20 minutes. Break the cuero (skin) into pieces, then pull or chop the meat and toss it with the pan juices.', 1200, null, null);

-- Classic Ceviche
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
