values ('1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'peruvian-classic-ceviche', 'classic-ceviche-1c3e0f', 'Classic Ceviche', 'Lima-style ceviche: cubes of very fresh white fish tossed for just a few minutes in lime juice with ají, red onion and cilantro, served with sweet potato and corn to soak up the leche de tigre.', 'peruvian', 2, 30, 25, 55, 4, 'starter', null, 0, array['stove']::text[], array['entertaining', 'summer']::text[], array['Squeeze the limes gently and don''t scrape the pith — pressing hard makes the juice bitter.', 'Ají limo and ají amarillo paste are sold in Latin markets; half a habanero gives a similar fruity heat.']::text[], 'https://images.pexels.com/photos/26586571/pexels-photo-26586571.jpeg', 'Peruvian fish ceviche topped with red onion, chili and herbs', 'Luiz Henrique Mendes', 'https://www.pexels.com/@luiz-henrique-mendes-1417367475/', 'https://www.pexels.com/photo/fish-and-red-onion-appetizer-26586571/', 'pexels', true, 'public', false,
  'pending_review', array['seafood_raw_bar', 'appetizer', 'entertaining']::text[], array['raw', 'boil']::text[], array['spicy', 'tangy', 'fresh']::text[], '{}'::text[], 'Lima', 'traditional', 'ceviche', 'classic', 'Serve within 15 minutes of mixing; ceviche doesn''t keep. Any leftover fish should be thrown away.', 'Use very fresh fish sold for eating raw and keep it cold. Citrus doesn''t kill bacteria or parasites the way cooking does. Not recommended for pregnant people, young children, older adults or anyone with a weakened immune system.', 'owned', array['fish']::text[], array['fish']::text[], array['pescatarian', 'gluten_free', 'dairy_free']::text[], array['sweet potato', 'ear corn', 'fish fillet', 'red onion', 'limo pepper', 'garlic', 'lime juice', 'cilantro', 'ice cube']::text[], 'cilantro|ear corn|fish fillet|garlic|ice cube|lime juice|limo pepper|red onion|sweet potato',
  null, null, null, null, null, null, null, null)
