insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed', 1, 'Sides', '1 sweet potato, about 12 oz, peeled and cut into thick rounds', 'sweet potato', 1, null, 'about 12 oz, peeled and cut into thick rounds', false),
  ('1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed', 2, 'Sides', '2 ears of corn, cut into 2-inch pieces', 'ears of corn', 2, null, 'cut into 2-inch pieces', false),
  ('1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed', 3, 'Ceviche', '1 lb skinless white fish fillet, such as sea bass, fluke or halibut, sold for eating raw', 'skinless white fish fillet', 1, 'lb', 'such as sea bass, fluke or halibut, sold for eating raw', false),
  ('1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed', 4, 'Ceviche', '1 tsp kosher salt, plus more to taste', 'kosher salt', 1, 'tsp', 'plus more to taste', false),
  ('1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed', 5, 'Ceviche', '½ red onion, sliced paper-thin, soaked in ice water 10 minutes', 'red onion', 0.5, null, 'sliced paper-thin, soaked in ice water 10 minutes', false),
  ('1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed', 6, 'Ceviche', '1 ají limo pepper, seeded and minced, or ½ habanero', 'ají limo pepper', 1, null, 'seeded and minced, or ½ habanero', false),
  ('1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed', 7, 'Ceviche', '1 tbsp ají amarillo paste', 'ají amarillo paste', 1, 'tbsp', null, true),
  ('1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed', 8, 'Ceviche', '1 clove garlic, grated', 'garlic', 1, 'clove', 'grated', false),
  ('1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed', 9, 'Ceviche', '⅔ cup fresh lime juice, about 10 limes, squeezed gently just before using', 'fresh lime juice', 0.66, 'cup', 'about 10 limes, squeezed gently just before using', false),
  ('1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed', 10, 'Ceviche', '2 tbsp fresh cilantro, finely chopped', 'fresh cilantro', 2, 'tbsp', 'finely chopped', false),
  ('1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed', 11, 'Ceviche', '2 ice cubes', 'ice cubes', 2, null, null, false),
  ('1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed', 12, 'Ceviche', '1 leaf Bibb lettuce, per plate, to serve', 'Bibb lettuce', 1, 'leaf', 'per plate, to serve', true);
delete from public.recipe_instructions where recipe_id = '1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed', 1, 'Sides', 'Boil the sweet potato in salted water until tender, 15–20 minutes, and the corn for the last 5–7 minutes. Drain and let cool to room temperature.', 1200, null, null),
  ('1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed', 2, 'Ceviche', 'Chill a glass or stainless-steel bowl. Cut the fish into ¾-inch cubes, put them in the cold bowl and toss with the salt. Keep refrigerated while you prepare the rest.', 600, null, null),
  ('1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed', 3, 'Ceviche', 'Drain the onion. Add the ají limo, ají amarillo paste (if using) and garlic to the fish and toss.', 120, null, null),
  ('1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed', 4, 'Ceviche', 'Pour the lime juice over, add the ice cubes and toss for about 1 minute, then let stand just 2–3 minutes until the outside of the fish turns opaque while the center stays translucent. Remove the ice.', 180, null, null),
  ('1c3e0f91-89ba-4bd0-a848-a66c0f7ae7ed', 5, 'Ceviche', 'Fold in the onion and cilantro, taste and add salt. Spoon into shallow bowls with plenty of the juice (the leche de tigre) and serve right away with the sweet potato and corn.', null, null, null);

-- Ají de Gallina
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
