values ('43772a13-0b56-4e25-849a-c5e84e04d2e6', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'peruvian-aji-de-gallina', 'aji-de-gallina-43772a', 'Ají de Gallina', 'Shredded chicken in a creamy, gently spicy sauce of ají amarillo, milk-soaked bread, walnuts and Parmesan, served over rice with potatoes, egg and olives — made, as most Lima home cooks do today, with chicken rather than an old hen.', 'peruvian', 2, 25, 50, 75, 6, 'main', null, 0, array['stove', 'blender']::text[], array['comfort', 'make-ahead']::text[], array['No ají amarillo paste? Blend 1 roasted yellow bell pepper with ½ seeded habanero; the color and fruitiness are close.', 'Pecans are a common, slightly sweeter swap for the walnuts.']::text[], 'https://images.pexels.com/photos/6763281/pexels-photo-6763281.jpeg', 'Peruvian creamy chicken with boiled egg, olives and lettuce in a ceramic bowl', 'Joao Sócola', 'https://www.pexels.com/@joao-socola-26036810/', 'https://www.pexels.com/photo/cooked-food-on-black-ceramic-bowl-6763281/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner']::text[], array['stew', 'steam', 'poach']::text[], array['savory', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'aji-de-gallina', 'classic', 'Refrigerate the sauced chicken up to 3 days; it thickens as it sits, so loosen with broth or milk when reheating.', null, 'owned', array['egg', 'gluten', 'milk', 'tree_nut', 'wheat']::text[], array['chicken']::text[], '{}'::text[], array['carrot', 'celery', 'sandwich bread', 'evaporated milk', 'yellow onion', 'garlic', 'amarillo paste', 'ground cumin', 'ground turmeric', 'walnut', 'parmesan cheese', 'yellow potato', 'egg', 'black olive', 'white rice']::text[], 'amarillo paste|black olive|carrot|celery|egg|evaporated milk|garlic|ground cumin|ground turmeric|parmesan cheese|sandwich bread|walnut|white rice|yellow onion|yellow potato',
  null, null, null, null, null, null, null, null)
