insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('43772a13-0b56-4e25-849a-c5e84e04d2e6', 1, 'Chicken', 'Put the chicken, carrot, celery, salt and water in a saucepan, bring to a gentle simmer and poach until the thickest piece reads 165°F, 15–20 minutes. Lift out the chicken and keep 2 cups of the broth.', 1080, null, 73.9),
  ('43772a13-0b56-4e25-849a-c5e84e04d2e6', 2, 'Chicken', 'When cool enough to handle, shred the chicken into thin strands with your fingers or two forks.', null, null, null),
  ('43772a13-0b56-4e25-849a-c5e84e04d2e6', 3, 'Sauce', 'Tear the bread into a blender, pour over the evaporated milk and let soak 5 minutes. Add the walnuts and blend until completely smooth.', 300, null, null),
  ('43772a13-0b56-4e25-849a-c5e84e04d2e6', 4, 'Sauce', 'Heat the oil in a wide pot over medium heat and cook the onion until soft and golden, about 10 minutes. Add the garlic, ají amarillo paste, cumin and turmeric and cook, stirring, 3 minutes until fragrant and the paste darkens slightly.', 780, null, null),
  ('43772a13-0b56-4e25-849a-c5e84e04d2e6', 5, 'Sauce', 'Pour in the bread mixture and 1 cup of the reserved broth and simmer, stirring often so it doesn''t catch, until thick and creamy, about 5 minutes.', 300, null, null),
  ('43772a13-0b56-4e25-849a-c5e84e04d2e6', 6, 'Sauce', 'Stir in the chicken and Parmesan and heat through until steaming, 3–4 minutes, adding more broth until it''s the texture of a thick stew. Season with salt.', 240, null, null),
  ('43772a13-0b56-4e25-849a-c5e84e04d2e6', 7, null, 'Serve over rice with the potatoes, egg quarters and olives alongside.', null, null, null);

-- Anticuchos
