values ('de9202f3-cf9a-42ed-a9fa-3116ead67b46', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'peruvian-anticuchos', 'anticuchos-de9202', 'Anticuchos', 'Peru''s street-corner skewers of beef heart marinated in ají panca, vinegar, garlic and cumin, then charred over high heat and served with grilled potatoes and corn.', 'peruvian', 3, 40, 30, 310, 4, 'main', null, 240, array['grill', 'stove']::text[], array['summer', 'entertaining']::text[], array['Beef heart is lean, cheap and tastes like a deeply beefy steak; Latin butchers sell it cleaned. Sirloin cut the same way is a good substitute.', 'Ají panca paste is sold in Latin markets; 2 soaked, blended ancho chiles make a fair swap.']::text[], 'https://images.unsplash.com/photo-1761315414620-7f0f3ebdd866', 'Peruvian grilled meat skewers with roasted potatoes, onions and herbs', 'Diego Arenas de Rodrigo', 'https://unsplash.com/@diegoarenasderodrigo', 'https://unsplash.com/photos/roasted-potatoes-and-meat-with-fresh-herbs-and-onions-CD0SRHCHOvU', 'unsplash', true, 'public', false,
  'pending_review', array['grilling', 'main', 'dinner', 'entertaining']::text[], array['grill', 'boil']::text[], array['tangy', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'anticuchos', 'classic', 'Best straight off the grill. Refrigerate leftovers up to 2 days and reheat quickly in a hot skillet.', null, 'owned', '{}'::text[], array['beef']::text[], array['gluten_free', 'dairy_free']::text[], array['beef heart', 'panca paste', 'wine vinegar', 'garlic', 'ground cumin', 'dried oregano', 'yellow potato', 'ear corn']::text[], 'beef heart|dried oregano|ear corn|garlic|ground cumin|panca paste|wine vinegar|yellow potato',
  null, null, null, null, null, null, null, null)
