insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('de9202f3-cf9a-42ed-a9fa-3116ead67b46', 1, 'Skewers', '2 lb beef heart, trimmed of fat, sinew and membrane, cut into 1½-inch pieces about ½ inch thick', 'beef heart', 2, 'lb', 'trimmed of fat, sinew and membrane, cut into 1½-inch pieces about ½ inch thick', false),
  ('de9202f3-cf9a-42ed-a9fa-3116ead67b46', 2, 'Marinade', '⅓ cup ají panca paste', 'ají panca paste', 0.33, 'cup', null, false),
  ('de9202f3-cf9a-42ed-a9fa-3116ead67b46', 3, 'Marinade', '⅓ cup red wine vinegar', 'red wine vinegar', 0.33, 'cup', null, false),
  ('de9202f3-cf9a-42ed-a9fa-3116ead67b46', 4, 'Marinade', '6 cloves garlic, grated', 'garlic', 6, 'clove', 'grated', false),
  ('de9202f3-cf9a-42ed-a9fa-3116ead67b46', 5, 'Marinade', '2 tsp ground cumin', 'ground cumin', 2, 'tsp', null, false),
  ('de9202f3-cf9a-42ed-a9fa-3116ead67b46', 6, 'Marinade', '1 tsp dried oregano', 'dried oregano', 1, 'tsp', null, false),
  ('de9202f3-cf9a-42ed-a9fa-3116ead67b46', 7, 'Marinade', '2 tsp kosher salt', 'kosher salt', 2, 'tsp', null, false),
  ('de9202f3-cf9a-42ed-a9fa-3116ead67b46', 8, 'Marinade', '1 tsp black pepper', 'black pepper', 1, 'tsp', null, false),
  ('de9202f3-cf9a-42ed-a9fa-3116ead67b46', 9, 'Marinade', '3 tbsp vegetable oil', 'vegetable oil', 3, 'tbsp', null, false),
  ('de9202f3-cf9a-42ed-a9fa-3116ead67b46', 10, 'Sides', '1½ lb small yellow potatoes', 'small yellow potatoes', 1.5, 'lb', null, false),
  ('de9202f3-cf9a-42ed-a9fa-3116ead67b46', 11, 'Sides', '2 ears of corn, halved', 'ears of corn', 2, null, 'halved', false),
  ('de9202f3-cf9a-42ed-a9fa-3116ead67b46', 12, 'Sides', '1 tbsp vegetable oil', 'vegetable oil', 1, 'tbsp', null, false);
delete from public.recipe_instructions where recipe_id = 'de9202f3-cf9a-42ed-a9fa-3116ead67b46';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('de9202f3-cf9a-42ed-a9fa-3116ead67b46', 1, 'Marinade', 'Whisk the ají panca paste, vinegar, garlic, cumin, oregano, salt, pepper and oil. Set aside ¼ cup for basting. Toss the beef heart in the rest, cover and refrigerate at least 4 hours or up to 24.', 14400, null, null),
  ('de9202f3-cf9a-42ed-a9fa-3116ead67b46', 2, 'Sides', 'Boil the potatoes in salted water until just tender, 15 minutes, adding the corn for the last 5 minutes. Drain, halve the potatoes and toss both with the oil.', 900, null, null),
  ('de9202f3-cf9a-42ed-a9fa-3116ead67b46', 3, 'Skewers', 'Soak 12 bamboo skewers in water for 30 minutes. Thread 3–4 pieces of meat onto each, pushing them snugly together.', 1800, null, null),
  ('de9202f3-cf9a-42ed-a9fa-3116ead67b46', 4, 'Skewers', 'Heat a grill to high (about 500°F) and oil the grates. Grill the potatoes and corn until charred in spots, 5 minutes, and move them to the cooler side.', 300, 260, null),
  ('de9202f3-cf9a-42ed-a9fa-3116ead67b46', 5, 'Skewers', 'Grill the skewers, basting with the reserved marinade, until well charred and 145°F in the center, 3–4 minutes per side. Rest 3 minutes before serving.', 480, 260, 62.8);

-- Asado
