values ('44de16e3-5d9f-4191-9806-3e6ac9c40ede', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'argentine-asado', 'asado-44de16', 'Asado', 'A home-grill version of the Argentine Sunday asado: chorizo, flanken-cut short ribs and skirt steak cooked slowly over a moderate charcoal fire with nothing but coarse salt, served with chimichurri.', 'argentine', 3, 90, 90, 180, 8, 'main', null, 0, array['grill']::text[], array['entertaining', 'summer', 'weekend']::text[], array['A real asado runs on wood embers raked under a parrilla; we use a kettle charcoal grill and serve the cuts in the traditional order — sausages first, then the slower cuts.', 'Look for flanken-cut ribs at Korean or Latin markets (sold for kalbi or tira de asado).']::text[], 'https://images.pexels.com/photos/37112852/pexels-photo-37112852.jpeg', 'Argentine asado meats cooking over a wood-fire grill', 'Andres Idda Bianchi', 'https://www.pexels.com/@davincidelasfotos/', 'https://www.pexels.com/photo/traditional-argentine-asado-bbq-in-uribelarrea-37112852/', 'pexels', true, 'public', false,
  'pending_review', array['grilling', 'entertaining', 'main', 'dinner', 'holiday']::text[], array['grill', 'pan_fry']::text[], array['spicy', 'tangy']::text[], array['fathers-day', 'dinner-party']::text[], null, 'adapted', 'asado', 'classic', 'Refrigerate leftover meat up to 3 days and chimichurri up to 1 week (stir before using).', null, 'owned', '{}'::text[], array['beef', 'pork']::text[], array['gluten_free', 'dairy_free']::text[], array['flat-leaf parsley', 'dried oregano', 'garlic', 'pepper flake', 'wine vinegar', 'chorizo link', 'short rib', 'skirt steak', 'coarse salt']::text[], 'chorizo link|coarse salt|dried oregano|flat-leaf parsley|garlic|pepper flake|short rib|skirt steak|wine vinegar',
  null, null, null, null, null, null, null, null)
