  ('44de16e3-5d9f-4191-9806-3e6ac9c40ede', 4, 'Chimichurri', '1 tsp red pepper flakes', 'red pepper flakes', 1, 'tsp', null, false),
  ('44de16e3-5d9f-4191-9806-3e6ac9c40ede', 5, 'Chimichurri', '¼ cup red wine vinegar', 'red wine vinegar', 0.25, 'cup', null, false),
