values ('f0130bca-19fa-4c42-961f-d4517c630513', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'argentine-beef-empanadas', 'beef-empanadas-f0130b', 'Beef Empanadas', 'Hand-pleated baked empanadas filled with juicy, cumin-spiced beef, onion, green olives and hard-boiled egg, in a tender homemade lard pastry.', 'argentine', 3, 75, 45, 180, 8, 'starter', null, 60, array['stove', 'oven']::text[], array['make-ahead', 'freezer-friendly', 'entertaining']::text[], array['Short on time? Use store-bought empanada discs (in the freezer case of Latin markets); one 10-count package makes 10.', 'Freeze unbaked empanadas on a tray, then bag them; bake from frozen, adding 8–10 minutes.']::text[], 'https://images.pexels.com/photos/36905236/pexels-photo-36905236.jpeg', 'Golden Argentine beef empanadas on a wooden board', 'jessica olivella', 'https://www.pexels.com/@jessica-olivella-555697728/', 'https://www.pexels.com/photo/traditional-argentine-empanadas-on-wooden-board-36905236/', 'pexels', true, 'public', false,
  'pending_review', array['appetizer', 'holiday', 'entertaining']::text[], array['bake']::text[], array['spicy', 'aromatic']::text[], array['game-day', 'potluck']::text[], null, 'traditional', 'beef-empanadas', 'classic', 'Refrigerate baked empanadas up to 3 days; reheat at 350°F for 10 minutes. Freeze unbaked ones up to 3 months.', null, 'owned', array['egg', 'gluten', 'wheat']::text[], array['beef']::text[], array['dairy_free']::text[], array['lard', 'yellow onion', 'bell pepper', 'ground beef', 'sweet paprika', 'ground cumin', 'pepper flake', 'scallion', 'green olive', 'egg']::text[], 'bell pepper|egg|green olive|ground beef|ground cumin|lard|pepper flake|scallion|sweet paprika|yellow onion',
  null, null, null, null, null, null, null, null)
