  ('f0130bca-19fa-4c42-961f-d4517c630513', 10, 'Filling', '2 tsp ground cumin', 'ground cumin', 2, 'tsp', null, false),
  ('f0130bca-19fa-4c42-961f-d4517c630513', 11, 'Filling', '½ tsp red pepper flakes', 'red pepper flakes', 0.5, 'tsp', null, false),
  ('f0130bca-19fa-4c42-961f-d4517c630513', 12, 'Filling', '1½ tsp kosher salt', 'kosher salt', 1.5, 'tsp', null, false),
  ('f0130bca-19fa-4c42-961f-d4517c630513', 13, 'Filling', '3 scallions, thinly sliced', 'scallions', 3, null, 'thinly sliced', false),
  ('f0130bca-19fa-4c42-961f-d4517c630513', 14, 'Filling', '½ cup pitted green olives, chopped', 'pitted green olives', 0.5, 'cup', 'chopped', false),
  ('f0130bca-19fa-4c42-961f-d4517c630513', 15, 'Filling', '3 large eggs, hard-boiled and chopped', 'large eggs', 3, null, 'hard-boiled and chopped', false),
  ('f0130bca-19fa-4c42-961f-d4517c630513', 16, 'Assembly', '1 large egg, beaten with 1 tbsp water, for brushing', 'large egg', 1, null, 'beaten with 1 tbsp water, for brushing', false);
delete from public.recipe_instructions where recipe_id = 'f0130bca-19fa-4c42-961f-d4517c630513';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('f0130bca-19fa-4c42-961f-d4517c630513', 1, 'Dough', 'Mix the flour and salt, rub in the lard with your fingertips until it looks like coarse crumbs, then add enough warm water to make a soft, smooth dough. Knead 3 minutes, wrap and rest at room temperature 30 minutes.', 2100, null, null),
  ('f0130bca-19fa-4c42-961f-d4517c630513', 2, 'Filling', 'Heat the oil in a large skillet over medium heat and cook the onions and bell pepper until very soft, 12 minutes. Add the beef, paprika, cumin, pepper flakes and salt and cook, breaking it up, until no pink remains and it reaches 160°F, about 8 minutes.', 1200, null, 71.1),
  ('f0130bca-19fa-4c42-961f-d4517c630513', 3, 'Filling', 'Stir in the scallions and spread on a sheet pan. Refrigerate until completely cold, at least 1 hour; then fold in the olives and chopped egg.', 3600, null, null),
  ('f0130bca-19fa-4c42-961f-d4517c630513', 4, 'Assembly', 'Heat the oven to 400°F and line 2 sheet pans with parchment. Roll the dough ⅛ inch thick and cut 5-inch rounds (you''ll get about 20), rerolling the scraps once.', null, null, null),
  ('f0130bca-19fa-4c42-961f-d4517c630513', 5, 'Assembly', 'Put a heaping 2 tablespoons of filling on each round, moisten the edge with water, fold into a half-moon and press out the air. Seal by folding and pinching the edge over itself in a rope pattern, or press with a fork.', 1500, null, null),
  ('f0130bca-19fa-4c42-961f-d4517c630513', 6, 'Assembly', 'Brush with the egg wash and bake until golden brown, 20–25 minutes. Cool 5 minutes — the filling is very hot.', 1320, 204.4, null);

-- Alfajores
