values ('be7fc2ff-819b-4595-877a-68d03163b9cc', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'argentine-alfajores-de-maicena', 'alfajores-be7fc2', 'Alfajores', 'Melt-in-your-mouth cornstarch shortbread cookies sandwiched with thick dulce de leche and rolled in coconut — Argentina''s alfajores de maicena.', 'argentine', 2, 40, 24, 124, 20, 'dessert', 'cookies', 60, array['oven', 'stand_mixer']::text[], array['make-ahead', 'entertaining', 'gift']::text[], array['Look for ''repostero'' (baker''s) dulce de leche — it''s thicker and won''t squeeze out. Regular jarred dulce de leche works if you chill the filled cookies.', 'They''re better on day 2, once the cookies soften a little against the filling.']::text[], 'https://images.pexels.com/photos/17358380/pexels-photo-17358380.jpeg', 'Stack of alfajores filled with dulce de leche and rolled in coconut', 'Agustina R Street', 'https://www.pexels.com/@agustina-r-street-353574760/', 'https://www.pexels.com/photo/tower-of-argentinian-cookies-17358380/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'dessert', 'holiday', 'entertaining']::text[], array['bake']::text[], array['tangy', 'sweet']::text[], array['christmas']::text[], null, 'traditional', 'alfajores', 'classic', 'Keep filled alfajores in an airtight tin up to 5 days. Unfilled cookies keep 1 week.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['cornstarch', 'baking powder', 'baking soda', 'egg yolk', 'vanilla extract', 'lemon zest', 'de leche', 'unsweetened coconut']::text[], 'baking powder|baking soda|cornstarch|de leche|egg yolk|lemon zest|unsweetened coconut|vanilla extract',
  null, null, null, null, null, null, null, null)
