insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 1, 'Cookies', '1½ cups cornstarch', 'cornstarch', 1.5, 'cup', null, false),
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 2, 'Cookies', '1 cup all-purpose flour', 'all-purpose flour', 1, 'cup', null, false),
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 3, 'Cookies', '1 tsp baking powder', 'baking powder', 1, 'tsp', null, false),
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 4, 'Cookies', '¼ tsp baking soda', 'baking soda', 0.25, 'tsp', null, false),
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 5, 'Cookies', '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 6, 'Cookies', '10 tbsp unsalted butter, softened', 'unsalted butter', 10, 'tbsp', 'softened', false),
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 7, 'Cookies', '½ cup sugar', 'sugar', 0.5, 'cup', null, false),
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 8, 'Cookies', '3 large egg yolks', 'large egg yolks', 3, null, null, false),
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 9, 'Cookies', '1 tsp vanilla extract', 'vanilla extract', 1, 'tsp', null, false),
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 10, 'Cookies', '1 tsp lemon zest, finely grated', 'lemon zest', 1, 'tsp', 'finely grated', false),
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 11, 'Cookies', '1 tbsp brandy, or milk', 'brandy', 1, 'tbsp', 'or milk', true),
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 12, 'Filling', '1½ cups dulce de leche, thick, store-bought or homemade', 'dulce de leche', 1.5, 'cup', 'thick, store-bought or homemade', false),
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 13, 'Filling', '½ cup unsweetened shredded coconut, finely shredded', 'unsweetened shredded coconut', 0.5, 'cup', 'finely shredded', false),
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 14, 'Filling', '2 tbsp powdered sugar, for dusting', 'powdered sugar', 2, 'tbsp', 'for dusting', true);
delete from public.recipe_instructions where recipe_id = 'be7fc2ff-819b-4595-877a-68d03163b9cc';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 1, 'Cookies', 'Whisk the cornstarch, flour, baking powder, baking soda and salt in a bowl.', null, null, null),
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 2, 'Cookies', 'Beat the butter and sugar in a stand mixer until pale and fluffy, 3 minutes. Beat in the egg yolks one at a time, then the vanilla, lemon zest and brandy.', 300, null, null),
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 3, 'Cookies', 'On low speed, add the dry ingredients just until a soft dough forms. Pat into 2 discs, wrap and chill 1 hour.', 3600, null, null),
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 4, 'Cookies', 'Heat the oven to 350°F and line 2 sheet pans with parchment. Roll the dough ¼ inch thick between sheets of parchment and cut 2-inch rounds (about 40). The dough is crumbly — press any cracks back together.', null, null, null),
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 5, 'Cookies', 'Bake one pan at a time until set and just barely colored on the bottom but still pale on top, 10–12 minutes. Cool on the pan 5 minutes (they''re fragile while warm), then on a rack.', 1320, 176.7, null),
  ('be7fc2ff-819b-4595-877a-68d03163b9cc', 6, 'Filling', 'Spread about 2 teaspoons of dulce de leche on the flat side of half the cookies and top with the rest, pressing gently so the filling reaches the edges. Roll the edges in the coconut and dust with powdered sugar.', null, null, null);

-- Feijoada
