values ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'brazilian-feijoada', 'feijoada-d1dc4b', 'Feijoada', 'Brazil''s black bean and pork stew, simmered for hours with ribs, smoked sausage, bacon and beef and served with rice, garlicky collards and orange slices; we use supermarket cuts in place of salt-dried beef and pig''s ears and feet.', 'brazilian', 3, 510, 180, 690, 8, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['comfort', 'entertaining', 'make-ahead', 'weekend']::text[], array['Forgot to soak? Boil the beans 2 minutes, cover and let stand 1 hour, then drain and carry on.', 'If you can find carne seca (Brazilian salt-dried beef) at a Latin market, soak it overnight in several changes of water and use it in place of the chuck.']::text[], 'https://images.pexels.com/photos/34442367/pexels-photo-34442367.jpeg', 'Brazilian feijoada of black beans and sausage garnished with fresh herbs', 'Laura oliveira', 'https://www.pexels.com/@laura-oliveira-2156849568/', 'https://www.pexels.com/photo/delicious-brazilian-feijoada-with-sausages-and-greens-34442367/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner', 'entertaining']::text[], array['stew', 'boil']::text[], array['smoky']::text[], '{}'::text[], null, 'adapted', 'feijoada', 'classic', 'Refrigerate up to 4 days or freeze up to 3 months; it''s even better the next day. Thin with water when reheating.', null, 'owned', '{}'::text[], array['beef', 'pork', 'beans']::text[], array['dairy_free']::text[], array['black bean', 'thick-cut bacon', 'pork sparerib', 'beef chuck', 'pork sausage', 'yellow onion', 'garlic', 'bay leave', 'collard green', 'white rice', 'orange']::text[], 'bay leave|beef chuck|black bean|collard green|garlic|orange|pork sausage|pork sparerib|thick-cut bacon|white rice|yellow onion',
  null, null, null, null, null, null, null, null)
