  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 1, 'Stew', '1 lb dried black beans, picked over and rinsed', 'dried black beans', 1, 'lb', 'picked over and rinsed', false),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 2, 'Stew', '8 oz thick-cut bacon, cut into 1-inch pieces', 'thick-cut bacon', 8, 'oz', 'cut into 1-inch pieces', false),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 3, 'Stew', '1½ lb pork spareribs, cut into single ribs', 'pork spareribs', 1.5, 'lb', 'cut into single ribs', false),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 4, 'Stew', '1 lb boneless beef chuck, cut into 1½-inch cubes', 'boneless beef chuck', 1, 'lb', 'cut into 1½-inch cubes', false),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 5, 'Stew', '12 oz smoked pork sausage, linguiça calabresa or kielbasa, sliced ½ inch thick', 'smoked pork sausage', 12, 'oz', 'linguiça calabresa or kielbasa, sliced ½ inch thick', false),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 6, 'Stew', '1 large yellow onion, chopped', 'large yellow onion', 1, null, 'chopped', false),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 7, 'Stew', '6 cloves garlic, minced', 'garlic', 6, 'clove', 'minced', false),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 8, 'Stew', '3 bay leaves', 'bay leaves', 3, null, null, false),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 9, 'Stew', '10 cups water, plus more as needed', 'water', 10, 'cup', 'plus more as needed', false),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 10, 'Stew', '1 tsp kosher salt, plus more to taste', 'kosher salt', 1, 'tsp', 'plus more to taste', false),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 11, 'Stew', '½ tsp black pepper', 'black pepper', 0.5, 'tsp', null, false),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 12, 'Collards', '2 tbsp olive oil', 'olive oil', 2, 'tbsp', null, false),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 13, 'Collards', '3 cloves garlic, thinly sliced', 'garlic', 3, 'clove', 'thinly sliced', false),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 14, 'Collards', '1 bunch collard greens, stems removed, leaves rolled and sliced into very thin ribbons', 'collard greens', 1, 'bunch', 'stems removed, leaves rolled and sliced into very thin ribbons', false),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 15, 'Collards', '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 16, 'To serve', '8 cups cooked white rice', 'cooked white rice', 8, 'cup', null, false),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 17, 'To serve', '2 oranges, peeled and sliced', 'oranges', 2, null, 'peeled and sliced', false),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 18, 'To serve', '1 cup farofa (toasted cassava flour), store-bought', 'farofa (toasted cassava flour)', 1, 'cup', 'store-bought', true);
delete from public.recipe_instructions where recipe_id = 'd1dc4b39-56b2-4afd-afc9-e5644d88debc';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 1, 'Stew', 'Cover the beans with plenty of cold water and soak overnight, 8–12 hours. Drain.', 28800, null, null),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 2, 'Stew', 'Cook the bacon in a large Dutch oven over medium heat until the fat renders, 6 minutes. Add the ribs and beef and brown in batches, 10 minutes. Lift out the meat, add the sausage and brown 5 minutes, then lift it out too.', 1260, null, null),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 3, 'Stew', 'Cook the onion in the fat until soft, 6 minutes, then the garlic for 1 minute. Return the bacon, ribs and beef with the beans, bay leaves and water. Bring to a boil, skim, cover partly and simmer gently 1½ hours.', 5820, null, null),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 4, 'Stew', 'Add the sausage, salt and pepper and keep simmering until the beans are creamy, the ribs pull off the bone and the meat is very tender (far past the 145°F safe minimum), about 1 hour more. Add water if it gets too thick.', 3600, null, 62.8),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 5, 'Stew', 'Scoop out 1 cup of beans, mash them and stir back in to thicken the broth. Taste for salt and remove the bay leaves.', null, null, null),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 6, 'Collards', 'Just before serving, heat the oil in a large skillet over medium-high heat, add the garlic for 30 seconds, then the collards and salt. Toss until bright green and just wilted, 2–3 minutes.', 180, null, null),
  ('d1dc4b39-56b2-4afd-afc9-e5644d88debc', 7, null, 'Serve the feijoada with rice, collards, orange slices and farofa to sprinkle over.', null, null, null);

-- Moqueca (Fish Stew)
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
