values ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'bahian-moqueca', 'moqueca-fish-stew-951f1e', 'Moqueca (Fish Stew)', 'Bahia''s fragrant fish stew: lime-marinated white fish gently cooked in layers of peppers, tomato and onion with coconut milk and golden dendê palm oil.', 'brazilian', 2, 40, 30, 70, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['entertaining', 'weekend']::text[], array['Dendê is sold at Brazilian and West African markets; if you can''t find it, use 2 tablespoons olive oil plus 1 extra teaspoon of paprika for color.', 'Serve with farofa or pirão (a porridge made from the broth and cassava flour) for the full Bahian table.']::text[], 'https://images.pexels.com/photos/34130782/pexels-photo-34130782.jpeg', 'Brazilian moqueca in a clay pot served with rice and plantains', 'Letícia Alvares', 'https://www.pexels.com/@leticia-alvares-1805702/', 'https://www.pexels.com/photo/authentic-brazilian-moqueca-on-rustic-table-34130782/', 'pexels', true, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'entertaining']::text[], array['stew']::text[], array['spicy', 'tangy', 'rich', 'fresh']::text[], '{}'::text[], 'Bahia', 'traditional', 'moqueca', 'classic', 'Best the day it''s made. Refrigerate up to 2 days and reheat gently so the fish doesn''t fall apart.', null, 'owned', array['fish']::text[], array['fish']::text[], array['pescatarian', 'gluten_free', 'dairy_free']::text[], array['fish fillet', 'lime juice', 'garlic', 'yellow onion', 'bell pepper', 'tomato', 'malagueta pepper', 'cilantro', 'coconut milk', 'dende', 'sweet paprika', 'scallion', 'white rice']::text[], 'bell pepper|cilantro|coconut milk|dende|fish fillet|garlic|lime juice|malagueta pepper|scallion|sweet paprika|tomato|white rice|yellow onion',
  null, null, null, null, null, null, null, null)
