insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 1, 'Fish', '2 lb firm white fish fillets, such as cod, halibut or snapper, cut into 3-inch pieces', 'firm white fish fillets', 2, 'lb', 'such as cod, halibut or snapper, cut into 3-inch pieces', false),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 2, 'Fish', '3 tbsp fresh lime juice', 'fresh lime juice', 3, 'tbsp', null, false),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 3, 'Fish', '3 cloves garlic, grated', 'garlic', 3, 'clove', 'grated', false),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 4, 'Fish', '1½ tsp kosher salt', 'kosher salt', 1.5, 'tsp', null, false),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 5, 'Stew', '2 tbsp olive oil', 'olive oil', 2, 'tbsp', null, false),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 6, 'Stew', '1 large yellow onion, sliced into thin rings', 'large yellow onion', 1, null, 'sliced into thin rings', false),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 7, 'Stew', '1 red bell pepper, sliced into thin rings', 'red bell pepper', 1, null, 'sliced into thin rings', false),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 8, 'Stew', '1 yellow bell pepper, sliced into thin rings', 'yellow bell pepper', 1, null, 'sliced into thin rings', false),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 9, 'Stew', '3 ripe tomatoes, sliced into rounds', 'ripe tomatoes', 3, null, 'sliced into rounds', false),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 10, 'Stew', '1 malagueta pepper, or 1 small fresh red chile, minced', 'malagueta pepper', 1, null, 'or 1 small fresh red chile, minced', false),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 11, 'Stew', '½ cup fresh cilantro, chopped, divided', 'fresh cilantro', 0.5, 'cup', 'chopped, divided', false),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 12, 'Stew', '1 can coconut milk, 13.5 oz', 'coconut milk', 1, 'can', '13.5 oz', false),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 13, 'Stew', '2 tbsp dendê (red palm oil)', 'dendê (red palm oil)', 2, 'tbsp', null, false),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 14, 'Stew', '1 tsp sweet paprika', 'sweet paprika', 1, 'tsp', null, false),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 15, 'Stew', '3 scallions, sliced', 'scallions', 3, null, 'sliced', false),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 16, 'To serve', '6 cups cooked white rice', 'cooked white rice', 6, 'cup', null, false);
delete from public.recipe_instructions where recipe_id = '951f1ed8-9421-4e54-8c00-f1368b4aaea9';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 1, 'Fish', 'Toss the fish with the lime juice, garlic and salt and refrigerate 30 minutes while you prepare the vegetables.', 1800, null, null),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 2, 'Stew', 'Drizzle the olive oil over the base of a wide Dutch oven or clay pot. Layer half the onion, peppers and tomatoes, then all the fish with its marinade, the chile and half the cilantro. Finish with the rest of the onion, peppers and tomatoes.', null, null, null),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 3, 'Stew', 'Whisk the coconut milk with the dendê and paprika and pour it over. Cover and bring to a simmer over medium heat, about 10 minutes.', 600, null, null),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 4, 'Stew', 'Lower the heat and simmer gently, covered and without stirring (shake the pot instead so the fish doesn''t break), until the fish is opaque, flakes easily and reads 145°F, 12–15 minutes.', 840, null, 62.8),
  ('951f1ed8-9421-4e54-8c00-f1368b4aaea9', 5, 'Stew', 'Taste the broth for salt and lime, scatter with the remaining cilantro and the scallions and serve straight from the pot with rice.', 60, null, null);

-- Pão de Queijo
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
