  attribution, reviewed_by, reviewed_at, calories_per_serving, protein_g, carbs_g, fat_g, nutrition_source)
values ('e47ae3f3-bf10-4c90-ac8a-8a6fbfeb7c0b', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'brazilian-pao-de-queijo', 'pao-de-queijo-e47ae3', 'Pão de Queijo', 'Crisp-shelled, chewy, cheesy rolls from Minas Gerais made with tapioca starch; we use Parmesan and mozzarella in place of the region''s cured Minas cheese.', 'brazilian', 2, 30, 30, 60, 8, 'starter', null, 0, array['stove', 'oven', 'stand_mixer']::text[], array['kid-friendly', 'freezer-friendly', 'vegetarian', 'entertaining']::text[], array['Freeze the shaped balls on a tray, then bag them; bake from frozen at 375°F for 25–30 minutes.', 'Brazilian markets sell polvilho azedo (sour tapioca starch) — swapping it in for half the tapioca flour gives a lighter, tangier roll.']::text[], 'https://images.pexels.com/photos/34259860/pexels-photo-34259860.jpeg', 'Freshly baked pão de queijo cheese breads in a wicker basket', 'Nathalia Crispim', 'https://www.pexels.com/@nathalia-crispim-271245353/', 'https://www.pexels.com/photo/basket-of-traditional-brazilian-pao-de-queijo-34259860/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'appetizer', 'comfort', 'entertaining']::text[], array['bake', 'boil']::text[], array['savory']::text[], '{}'::text[], null, 'adapted', 'pao-de-queijo', 'classic', 'Best warm from the oven. Keep baked rolls airtight 1 day and re-crisp at 350°F for 5 minutes, or freeze unbaked balls up to 3 months.', null, 'owned', array['egg', 'milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['milk', 'tapioca flour', 'egg', 'parmesan cheese', 'low-moisture mozzarella']::text[], 'egg|low-moisture mozzarella|milk|parmesan cheese|tapioca flour',
  null, null, null, null, null, null, null, null)
