insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('e47ae3f3-bf10-4c90-ac8a-8a6fbfeb7c0b', 1, null, '1 cup whole milk', 'whole milk', 1, 'cup', null, false),
  ('e47ae3f3-bf10-4c90-ac8a-8a6fbfeb7c0b', 2, null, '⅓ cup vegetable oil', 'vegetable oil', 0.33, 'cup', null, false),
  ('e47ae3f3-bf10-4c90-ac8a-8a6fbfeb7c0b', 3, null, '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('e47ae3f3-bf10-4c90-ac8a-8a6fbfeb7c0b', 4, null, '2½ cups tapioca flour, also sold as tapioca starch (about 10 oz)', 'tapioca flour', 2.5, 'cup', 'also sold as tapioca starch (about 10 oz)', false),
  ('e47ae3f3-bf10-4c90-ac8a-8a6fbfeb7c0b', 5, null, '2 large eggs, at room temperature', 'large eggs', 2, null, 'at room temperature', false),
  ('e47ae3f3-bf10-4c90-ac8a-8a6fbfeb7c0b', 6, null, '1 cup Parmesan cheese, finely grated', 'Parmesan cheese', 1, 'cup', 'finely grated', false),
  ('e47ae3f3-bf10-4c90-ac8a-8a6fbfeb7c0b', 7, null, '1 cup low-moisture mozzarella, finely shredded', 'low-moisture mozzarella', 1, 'cup', 'finely shredded', false);
