insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('e47ae3f3-bf10-4c90-ac8a-8a6fbfeb7c0b', 1, null, 'Heat the oven to 400°F and line 2 sheet pans with parchment.', null, 204.4, null),
  ('e47ae3f3-bf10-4c90-ac8a-8a6fbfeb7c0b', 2, null, 'Bring the milk, oil and salt to a boil in a saucepan. Pour it over the tapioca flour in the bowl of a stand mixer and beat with the paddle until it forms a smooth, sticky, elastic dough.', 300, null, null),
  ('e47ae3f3-bf10-4c90-ac8a-8a6fbfeb7c0b', 3, null, 'Let the dough cool for 10 minutes until warm but not hot, then beat in the eggs one at a time, then both cheeses, until smooth and stretchy.', 720, null, null),
  ('e47ae3f3-bf10-4c90-ac8a-8a6fbfeb7c0b', 4, null, 'With oiled hands, roll tablespoon-size balls (about 24) and set them 2 inches apart on the pans.', null, null, null),
  ('e47ae3f3-bf10-4c90-ac8a-8a6fbfeb7c0b', 5, null, 'Bake until puffed and golden with a few cracks, 20–25 minutes, swapping the pans halfway. Serve warm.', 1320, 204.4, null);

-- Picanha
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
