values ('9d5d1c83-8ecd-43c8-99d3-592f85900e3b', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'brazilian-picanha', 'picanha-9d5d1c', 'Picanha', 'Churrascaria-style top sirloin cap, cut into thick steaks, bent into a C onto skewers so the fat cap bastes the meat, seasoned only with coarse salt and grilled over high heat.', 'brazilian', 3, 20, 30, 50, 6, 'main', null, 0, array['grill']::text[], array['entertaining', 'summer', 'weekend']::text[], array['Ask the butcher for ''top sirloin cap'' or ''coulotte'' with the fat left on — the fat is the point.', 'In Brazil it''s often carved in stages: slice off the browned outside, serve it, then return the skewer to the fire.']::text[], 'https://images.pexels.com/photos/28893439/pexels-photo-28893439.jpeg', 'Grilled picanha on skewers, Brazilian churrasco style', 'pedro furtado', 'https://www.pexels.com/@pedrofurtadoo/', 'https://www.pexels.com/photo/grilled-brazilian-picanha-skewers-outdoors-28893439/', 'pexels', true, 'public', false,
  'pending_review', array['grilling', 'main', 'dinner', 'holiday', 'entertaining']::text[], array['grill', 'roast']::text[], array['tangy']::text[], array['fathers-day', 'game-day']::text[], null, 'traditional', 'picanha', 'classic', 'Refrigerate sliced leftovers up to 3 days; they''re great cold in sandwiches or warmed quickly in a skillet.', null, 'owned', '{}'::text[], array['beef']::text[], array['gluten_free', 'dairy_free']::text[], array['picanha', 'coarse salt', 'tomato', 'white onion', 'bell pepper', 'flat-leaf parsley', 'wine vinegar']::text[], 'bell pepper|coarse salt|flat-leaf parsley|picanha|tomato|white onion|wine vinegar',
  null, null, null, null, null, null, null, null)
