insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('9d5d1c83-8ecd-43c8-99d3-592f85900e3b', 1, 'Picanha', '2½ lb picanha (beef top sirloin cap), with its fat cap', 'picanha (beef top sirloin cap)', 2.5, 'lb', 'with its fat cap', false),
  ('9d5d1c83-8ecd-43c8-99d3-592f85900e3b', 2, 'Picanha', '2 tbsp coarse sea salt, or 1½ tbsp kosher salt', 'coarse sea salt', 2, 'tbsp', 'or 1½ tbsp kosher salt', false),
  ('9d5d1c83-8ecd-43c8-99d3-592f85900e3b', 3, 'Vinagrete', '2 ripe tomatoes, seeded and finely diced', 'ripe tomatoes', 2, null, 'seeded and finely diced', false),
  ('9d5d1c83-8ecd-43c8-99d3-592f85900e3b', 4, 'Vinagrete', '½ white onion, finely diced', 'white onion', 0.5, null, 'finely diced', false),
  ('9d5d1c83-8ecd-43c8-99d3-592f85900e3b', 5, 'Vinagrete', '½ green bell pepper, finely diced', 'green bell pepper', 0.5, null, 'finely diced', false),
  ('9d5d1c83-8ecd-43c8-99d3-592f85900e3b', 6, 'Vinagrete', '2 tbsp fresh flat-leaf parsley, chopped', 'fresh flat-leaf parsley', 2, 'tbsp', 'chopped', false),
  ('9d5d1c83-8ecd-43c8-99d3-592f85900e3b', 7, 'Vinagrete', '3 tbsp white wine vinegar', 'white wine vinegar', 3, 'tbsp', null, false),
  ('9d5d1c83-8ecd-43c8-99d3-592f85900e3b', 8, 'Vinagrete', '3 tbsp olive oil', 'olive oil', 3, 'tbsp', null, false),
  ('9d5d1c83-8ecd-43c8-99d3-592f85900e3b', 9, 'Vinagrete', '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false);
delete from public.recipe_instructions where recipe_id = '9d5d1c83-8ecd-43c8-99d3-592f85900e3b';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('9d5d1c83-8ecd-43c8-99d3-592f85900e3b', 1, 'Vinagrete', 'Mix the tomatoes, onion, bell pepper, parsley, vinegar, oil and salt and set aside while you grill.', null, null, null),
  ('9d5d1c83-8ecd-43c8-99d3-592f85900e3b', 2, 'Picanha', 'Trim the fat cap to about ½ inch thick if it''s thicker, and score it lightly in a crosshatch without cutting into the meat. Cut the roast with the grain into 3–4 steaks about 1½ inches thick.', 600, null, null),
  ('9d5d1c83-8ecd-43c8-99d3-592f85900e3b', 3, 'Picanha', 'Bend each steak into a C shape, fat on the outside, and thread onto long metal skewers (1–2 per skewer). Rub all over with the coarse salt.', 300, null, null),
  ('9d5d1c83-8ecd-43c8-99d3-592f85900e3b', 4, 'Picanha', 'Heat a grill to high (about 500°F), with one cooler zone. Grill the skewers fat side down first until the fat sizzles and browns, 4–5 minutes, moving them to the cooler side if flare-ups get big.', 300, 260, null),
  ('9d5d1c83-8ecd-43c8-99d3-592f85900e3b', 5, 'Picanha', 'Turn and grill the meat sides until well browned and 145°F in the center, 15–20 minutes total, turning every few minutes. Rest 5 minutes.', 1080, 260, 62.8),
  ('9d5d1c83-8ecd-43c8-99d3-592f85900e3b', 6, null, 'Slide the steaks off the skewers and slice thinly against the grain. Serve with the vinagrete.', null, null, null);

-- Bandeja Paisa
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
