values ('3172e8f1-ea21-4d32-add8-26861f08f5b1', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'colombian-bandeja-paisa', 'bandeja-paisa-3172e8', 'Bandeja Paisa', 'Antioquia''s famously generous platter: red beans with hogao, rice, seasoned ground beef, crisp pork belly chicharrón, chorizo, a fried egg, sweet plantain, avocado and an arepa; we use canned beans and store-bought arepas to keep it manageable at home.', 'colombian', 3, 40, 90, 130, 4, 'main', null, 0, array['stove', 'oven', 'cast_iron']::text[], array['comfort', 'weekend']::text[], array['Pork belly is easiest to slice for serving once it has cooled for 10 minutes after roasting.']::text[], 'https://images.unsplash.com/photo-1723693407562-bb4fcae76797', 'Colombian bandeja paisa platter on a wooden table', 'WILLIAN REIS', 'https://unsplash.com/@wriopomba', 'https://unsplash.com/photos/a-plate-of-food-on-a-wooden-table-9MVNGosobLU', 'unsplash', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner']::text[], array['roast', 'stew']::text[], array['aromatic']::text[], '{}'::text[], 'Antioquia', 'adapted', 'bandeja-paisa', 'classic', 'Refrigerate each component separately up to 3 days; fry eggs and plantains fresh.', 'The eggs here aren''t cooked to 160°F. Use pasteurized eggs if you''re serving anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['egg']::text[], array['beef', 'pork', 'beans']::text[], array['gluten_free', 'dairy_free']::text[], array['pork belly', 'scallion', 'tomato', 'garlic', 'ground cumin', 'kidney bean', 'carrot', 'ground beef', 'sweet paprika', 'chorizo link', 'very plantain', 'egg', 'corn arepa', 'white rice', 'avocado']::text[], 'avocado|carrot|chorizo link|corn arepa|egg|garlic|ground beef|ground cumin|kidney bean|pork belly|scallion|sweet paprika|tomato|very plantain|white rice',
  null, null, null, null, null, null, null, null)
