delete from public.recipe_instructions where recipe_id = '3172e8f1-ea21-4d32-add8-26861f08f5b1';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('3172e8f1-ea21-4d32-add8-26861f08f5b1', 1, 'Chicharrón', 'Put the pork belly in a pot, cover with water, add 1 teaspoon of the salt and simmer 45 minutes until tender. Drain and pat very dry.', 2700, null, null),
  ('3172e8f1-ea21-4d32-add8-26861f08f5b1', 2, 'Hogao and beans', 'Meanwhile, heat the oil in a saucepan over medium heat and cook the scallions 3 minutes. Add the tomatoes, garlic, cumin and salt and cook until thick and jammy, 10 minutes. Spoon out half the hogao for the beef. Add the beans, carrot and water to the pan and simmer until thick, 20 minutes, mashing a few beans.', 1980, null, null),
  ('3172e8f1-ea21-4d32-add8-26861f08f5b1', 3, 'Chicharrón', 'Heat the oven to 425°F. Score the pork skin, rub with the remaining salt and roast skin side up on a rack over a sheet pan until the skin is puffed and crackling and the meat is well past 145°F, 30–35 minutes. Roast the chorizo alongside until browned and 160°F inside, about 25 minutes.', 1980, 218.3, 71.1),
  ('3172e8f1-ea21-4d32-add8-26861f08f5b1', 4, 'Beef', 'Cook the ground beef in a skillet with the cumin, paprika and salt, breaking it into fine crumbs, until browned, no pink remains and it reaches 160°F, 8 minutes. Stir in the reserved hogao.', 480, null, 71.1),
  ('3172e8f1-ea21-4d32-add8-26861f08f5b1', 5, 'Plate', 'Heat the oil (about ¼ inch deep, pan no more than half full) in a cast-iron skillet to 350°F and fry the plantain slices until deep golden, 2–3 minutes per side. Drain on paper towels.', 360, 176.7, null),
  ('3172e8f1-ea21-4d32-add8-26861f08f5b1', 6, 'Plate', 'Pour off all but 1 tablespoon of the oil and fry the eggs until the whites are set and the edges crisp, 2–3 minutes (cook the yolks through if anyone at the table should avoid soft eggs). Warm the arepas in a dry pan.', 300, null, null),
  ('3172e8f1-ea21-4d32-add8-26861f08f5b1', 7, 'Plate', 'Fill each large plate with rice, beans and beef, then add a piece of chicharrón, a chorizo, plantain, avocado, an arepa and a fried egg on top of the rice.', null, null, null);

-- Pabellón Criollo
