values ('d48c4d60-301b-44b9-a1b0-2011e0c9db5a', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'venezuelan-pabellon-criollo', 'pabellon-criollo-d48c4d', 'Pabellón Criollo', 'Venezuela''s national dish: tender shredded beef stewed in a peppery sofrito, sweet-savory black beans, white rice and fried ripe plantain, all on one plate.', 'venezuelan', 3, 510, 150, 660, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['comfort', 'make-ahead', 'weekend']::text[], array['Worcestershire sauce contains anchovies (fish); leave it out and add a splash more salt and a squeeze of lime if that''s a concern.', 'Many Venezuelans top it with a fried egg (''a caballo'') and a sprinkle of crumbled white cheese.']::text[], 'https://images.pexels.com/photos/29450672/pexels-photo-29450672.jpeg', 'Pabellón criollo with shredded beef, black beans, white rice and fried plantains', 'Nano Erdozain', 'https://www.pexels.com/@nano-erdozain-120534369/', 'https://www.pexels.com/photo/traditional-venezuelan-pabellon-criollo-dish-29450672/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner']::text[], array['stew']::text[], array['savory', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'pabellon-criollo', 'classic', 'Refrigerate the beef and beans separately up to 4 days, or freeze up to 3 months. Fry plantains fresh.', null, 'owned', array['fish']::text[], array['beef', 'beans']::text[], array['gluten_free', 'dairy_free']::text[], array['black bean', 'yellow onion', 'bell pepper', 'garlic', 'ground cumin', 'brown sugar', 'flank steak', 'bay leaf', 'tomato', 'worcestershire sauce', 'very plantain', 'white rice']::text[], 'bay leaf|bell pepper|black bean|brown sugar|flank steak|garlic|ground cumin|tomato|very plantain|white rice|worcestershire sauce|yellow onion',
  null, null, null, null, null, null, null, null)
