delete from public.recipe_instructions where recipe_id = 'd48c4d60-301b-44b9-a1b0-2011e0c9db5a';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('d48c4d60-301b-44b9-a1b0-2011e0c9db5a', 1, 'Black beans', 'Soak the beans in plenty of cold water overnight, 8–12 hours, then drain.', 28800, null, null),
  ('d48c4d60-301b-44b9-a1b0-2011e0c9db5a', 2, 'Black beans', 'Simmer the beans in the 8 cups fresh water, partly covered, until creamy-tender, 1½–2 hours, adding water if needed.', 6300, null, null),
  ('d48c4d60-301b-44b9-a1b0-2011e0c9db5a', 3, 'Carne mechada', 'Meanwhile, put the flank steak and bay leaf in a Dutch oven, cover with water by an inch and simmer gently, covered, until very tender and easy to shred (well past the 145°F safe minimum), about 1½ hours. Keep 1 cup of the broth, then shred the beef with two forks along the grain.', 5400, null, 62.8),
  ('d48c4d60-301b-44b9-a1b0-2011e0c9db5a', 4, 'Black beans', 'In a skillet, cook the onion and pepper in the oil until soft, 6 minutes, add the garlic and cumin for 1 minute, then stir the mixture into the beans with the sugar and salt. Simmer uncovered until thick and glossy, 15 minutes.', 1320, null, null),
  ('d48c4d60-301b-44b9-a1b0-2011e0c9db5a', 5, 'Carne mechada', 'Wipe out the Dutch oven, heat the oil and cook the onion and pepper until soft, 8 minutes. Add the garlic, tomatoes and cumin and cook to a thick sauce, 8 minutes. Add the beef, Worcestershire, salt and the reserved broth and simmer, stirring, until the sauce clings to the meat, 10 minutes.', 1560, null, null),
  ('d48c4d60-301b-44b9-a1b0-2011e0c9db5a', 6, 'Plate', 'Heat the oil (about ¼ inch deep, pan no more than half full) in a skillet to 350°F and fry the plantains until caramelized, 2–3 minutes per side. Drain on paper towels.', 360, 176.7, null),
  ('d48c4d60-301b-44b9-a1b0-2011e0c9db5a', 7, 'Plate', 'Serve the rice, beef, beans and plantains side by side on each plate.', null, null, null);

-- Osso Buco alla Milanese
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
