values ('5e980402-6517-4833-a8f0-b6cafeb4dbcc', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'osso-buco-alla-milanese', 'osso-buco-alla-milanese-5e9804', 'Osso Buco alla Milanese', 'Cross-cut veal shanks braised the Milanese way — with white wine, broth and soffritto rather than tomato — until the meat falls from the bone, finished with bright lemon-garlic gremolata.', 'italian', 4, 30, 150, 180, 4, 'main', null, 0, array['stove', 'oven', 'dutch_oven']::text[], array['entertaining', 'make-ahead']::text[], array['Order veal shanks ahead — most butchers will cut them to the thickness you want. Beef shanks work too but need about 45 minutes longer.', 'Store-bought broth and bouillon can contain celery, wheat or other allergens; check the label if needed.']::text[], 'https://images.pexels.com/photos/15186040/pexels-photo-15186040.jpeg', 'Braised osso buco with roasted vegetables on a plate', 'Eduardo Krajan', 'https://www.pexels.com/@eduardo-krajan-424982200/', 'https://www.pexels.com/photo/meat-and-vegetable-meal-on-plate-15186040/', 'pexels', true, 'public', false,
  'pending_review', array['entertaining', 'main', 'dinner', 'holiday']::text[], array['braise', 'stew', 'pan_fry']::text[], array['tangy']::text[], array['dinner-party', 'christmas']::text[], 'Lombardy', 'traditional', 'osso-buco', 'classic', 'Refrigerate up to 3 days (it reheats beautifully, covered, at 325°F) or freeze up to 3 months. Make the gremolata fresh.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], array['veal']::text[], '{}'::text[], array['veal shank', 'yellow onion', 'carrot', 'celery', 'white wine', 'chicken broth', 'bay leaf', 'lemon peel', 'lemon', 'garlic', 'flat-leaf parsley']::text[], 'bay leaf|carrot|celery|chicken broth|flat-leaf parsley|garlic|lemon|lemon peel|veal shank|white wine|yellow onion',
  null, null, null, null, null, null, null, null)
