  ('5e980402-6517-4833-a8f0-b6cafeb4dbcc', 9, 'Osso buco', '1 stalk celery, finely diced', 'celery', 1, 'stalk', 'finely diced', false),
  ('5e980402-6517-4833-a8f0-b6cafeb4dbcc', 10, 'Osso buco', '1 cup dry white wine', 'dry white wine', 1, 'cup', null, false),
  ('5e980402-6517-4833-a8f0-b6cafeb4dbcc', 11, 'Osso buco', '2 cups low-sodium chicken broth, or veal or beef broth', 'low-sodium chicken broth', 2, 'cup', 'or veal or beef broth', false),
  ('5e980402-6517-4833-a8f0-b6cafeb4dbcc', 12, 'Osso buco', '1 bay leaf', 'bay leaf', 1, null, null, false),
  ('5e980402-6517-4833-a8f0-b6cafeb4dbcc', 13, 'Osso buco', '2 piece lemon peel, wide strips removed with a peeler', 'lemon peel', 2, 'piece', 'wide strips removed with a peeler', false),
  ('5e980402-6517-4833-a8f0-b6cafeb4dbcc', 14, 'Gremolata', '1 lemon, zest finely grated', 'lemon', 1, null, 'zest finely grated', false),
  ('5e980402-6517-4833-a8f0-b6cafeb4dbcc', 15, 'Gremolata', '1 clove garlic, minced very fine', 'garlic', 1, 'clove', 'minced very fine', false),
  ('5e980402-6517-4833-a8f0-b6cafeb4dbcc', 16, 'Gremolata', '¼ cup fresh flat-leaf parsley, finely chopped', 'fresh flat-leaf parsley', 0.25, 'cup', 'finely chopped', false);
delete from public.recipe_instructions where recipe_id = '5e980402-6517-4833-a8f0-b6cafeb4dbcc';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('5e980402-6517-4833-a8f0-b6cafeb4dbcc', 1, 'Osso buco', 'Heat the oven to 325°F. Pat the shanks dry and, to keep them neat, tie kitchen string around the middle of each. Season with the salt and pepper and dredge lightly in flour, shaking off the excess.', null, 162.8, null),
  ('5e980402-6517-4833-a8f0-b6cafeb4dbcc', 2, 'Osso buco', 'Heat the oil and 1 tablespoon of the butter in a Dutch oven just wide enough for the shanks in one layer over medium-high heat. Brown the shanks well, 4–5 minutes per side, and set aside.', 600, null, null),
  ('5e980402-6517-4833-a8f0-b6cafeb4dbcc', 3, 'Osso buco', 'Lower the heat to medium, add the remaining butter and the onion, carrot and celery and cook until soft and lightly golden, 8 minutes. Pour in the wine and simmer, scraping up the browned bits, until reduced by half, 4 minutes.', 720, null, null),
  ('5e980402-6517-4833-a8f0-b6cafeb4dbcc', 4, 'Osso buco', 'Return the shanks, add the broth, bay leaf and lemon peel — the liquid should come about two-thirds up the meat. Bring to a simmer, cover and braise in the oven, basting every 30 minutes, until the meat is very tender and pulling from the bone (well past the 145°F safe minimum), about 2 hours.', 7200, 162.8, 62.8),
  ('5e980402-6517-4833-a8f0-b6cafeb4dbcc', 5, 'Gremolata', 'Mix the lemon zest, garlic and parsley just before serving.', null, null, null),
  ('5e980402-6517-4833-a8f0-b6cafeb4dbcc', 6, 'Osso buco', 'Lift out the shanks and snip off the string. If the sauce is thin, simmer it on the stove until it coats a spoon, 5 minutes. Spoon over the shanks and top each with gremolata. Serve with risotto alla Milanese and a small spoon for the marrow.', 300, null, null);

-- Risotto alla Milanese
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
