values ('5144ee7e-7681-42f7-af6b-225691389920', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'risotto-alla-milanese', 'risotto-alla-milanese-5144ee', 'Risotto alla Milanese', 'Golden saffron risotto made the Milanese way with a little beef marrow, white wine and broth, finished with cold butter and Parmigiano — the classic partner for osso buco.', 'italian', 3, 10, 30, 40, 4, 'main', null, 0, array['stove']::text[], array['entertaining', 'date-night']::text[], array['Ask the butcher for 2 marrow bones and push the marrow out with your thumb; without it the risotto is still delicious, just a little less rich.', 'Parmigiano-Reggiano is made with animal rennet; for a vegetarian version use vegetable broth, skip the marrow and use a vegetarian hard cheese.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'holiday', 'date_night', 'entertaining']::text[], array['stew']::text[], array['rich', 'savory']::text[], array['date-night', 'dinner-party']::text[], 'Lombardy', 'traditional', 'risotto-milanese', 'classic', 'Best immediately. Refrigerate leftovers up to 2 days and turn them into arancini or a crisp risotto cake in a buttered pan.', null, 'owned', array['milk']::text[], '{}'::text[], '{}'::text[], array['beef broth', 'saffron thread', 'yellow onion', 'arborio rice', 'white wine', 'parmigiano-reggiano']::text[], 'arborio rice|beef broth|parmigiano-reggiano|saffron thread|white wine|yellow onion',
  null, null, null, null, null, null, null, null)
