insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('5144ee7e-7681-42f7-af6b-225691389920', 1, null, '6 cups low-sodium beef broth, or chicken broth', 'low-sodium beef broth', 6, 'cup', 'or chicken broth', false),
  ('5144ee7e-7681-42f7-af6b-225691389920', 2, null, '½ tsp saffron threads, loosely packed', 'saffron threads', 0.5, 'tsp', 'loosely packed', false),
  ('5144ee7e-7681-42f7-af6b-225691389920', 3, null, '4 tbsp unsalted butter, divided, 2 tbsp kept cold', 'unsalted butter', 4, 'tbsp', 'divided, 2 tbsp kept cold', false),
  ('5144ee7e-7681-42f7-af6b-225691389920', 4, null, '1 oz beef bone marrow, chopped (scoop from 2 marrow bones)', 'beef bone marrow', 1, 'oz', 'chopped (scoop from 2 marrow bones)', true),
  ('5144ee7e-7681-42f7-af6b-225691389920', 5, null, '1 small yellow onion, very finely chopped', 'small yellow onion', 1, null, 'very finely chopped', false),
  ('5144ee7e-7681-42f7-af6b-225691389920', 6, null, '1½ cups Carnaroli or Arborio rice', 'Carnaroli or Arborio rice', 1.5, 'cup', null, false),
  ('5144ee7e-7681-42f7-af6b-225691389920', 7, null, '½ cup dry white wine', 'dry white wine', 0.5, 'cup', null, false),
  ('5144ee7e-7681-42f7-af6b-225691389920', 8, null, '¾ cup Parmigiano-Reggiano, finely grated', 'Parmigiano-Reggiano', 0.75, 'cup', 'finely grated', false),
  ('5144ee7e-7681-42f7-af6b-225691389920', 9, null, '½ tsp kosher salt, to taste', 'kosher salt', 0.5, 'tsp', 'to taste', false);
delete from public.recipe_instructions where recipe_id = '5144ee7e-7681-42f7-af6b-225691389920';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('5144ee7e-7681-42f7-af6b-225691389920', 1, null, 'Bring the broth to a bare simmer in a saucepan and keep it there. Crumble the saffron into ½ cup of the hot broth in a cup and let it steep.', 300, null, null),
  ('5144ee7e-7681-42f7-af6b-225691389920', 2, null, 'In a heavy, wide saucepan over medium heat, melt 2 tablespoons of the butter with the marrow (if using). Add the onion and cook gently until soft and translucent but not browned, 6 minutes.', 360, null, null),
  ('5144ee7e-7681-42f7-af6b-225691389920', 3, null, 'Add the rice and stir until the grains are hot and shiny and just turning translucent at the edges, 2 minutes. Pour in the wine and stir until it is absorbed.', 180, null, null),
  ('5144ee7e-7681-42f7-af6b-225691389920', 4, null, 'Add a ladle of hot broth and stir until mostly absorbed, then keep adding broth a ladle at a time, stirring often, for about 10 minutes. Add the saffron broth and keep going until the rice is creamy and just tender with a slight bite, 6–8 minutes more.', 1080, null, null),
  ('5144ee7e-7681-42f7-af6b-225691389920', 5, null, 'Take the pan off the heat. Beat in the cold butter and Parmigiano vigorously for 1 minute until glossy and flowing — it should spread in a wave when you shake the pan (all''onda). Season with salt, cover and rest 2 minutes, then serve right away.', 180, null, null);

-- Handmade Tagliatelle al Ragù
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
