values ('984a3d1a-c3dc-4f1c-8d9e-ba9e0a3e96a3', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'tagliatelle-al-ragu-bolognese', 'handmade-tagliatelle-al-ragu-984a3d', 'Handmade Tagliatelle al Ragù', 'Silky hand-rolled egg tagliatelle with Bologna''s slow-cooked ragù of beef, pancetta, a little tomato, wine and milk — never spaghetti in Bologna.', 'italian', 3, 75, 190, 265, 6, 'main', null, 0, array['stove']::text[], array['comfort', 'weekend', 'make-ahead']::text[], array['Make the ragù a day ahead — it improves overnight and turns this into an easy pasta night.', 'Short on time? 1 pound of good dried egg tagliatelle stands in for the handmade pasta.']::text[], 'https://images.pexels.com/photos/13640223/pexels-photo-13640223.jpeg', 'Tagliatelle with rich ragù on a ceramic plate in Bologna', 'Tugce Turan', 'https://www.pexels.com/@tugce-turan-275581022/', 'https://www.pexels.com/photo/pasta-dish-on-ceramic-plate-13640223/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner']::text[], array['stew', 'boil']::text[], array['savory']::text[], '{}'::text[], 'Bologna', 'traditional', 'tagliatelle-al-ragu', 'classic', 'Refrigerate the ragù up to 4 days or freeze up to 3 months. Fresh pasta nests can be frozen on a tray and boiled from frozen.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], array['beef', 'pork']::text[], '{}'::text[], array['pancetta', 'yellow onion', 'carrot', 'celery', 'beef chuck', 'white wine', 'tomato paste', 'tomato passata', 'beef broth', 'milk', 'egg', 'parmigiano-reggiano']::text[], 'beef broth|beef chuck|carrot|celery|egg|milk|pancetta|parmigiano-reggiano|tomato passata|tomato paste|white wine|yellow onion',
  null, null, null, null, null, null, null, null)
