values ('c662d898-5490-4e85-b07d-d871273ae928', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'potato-gnocchi-brown-butter-sage', 'potato-gnocchi-with-brown-butter-and-sage-c662d8', 'Potato Gnocchi with Brown Butter & Sage', 'Light, pillowy potato gnocchi made with baked russets, a little flour and an egg yolk, tossed in nutty brown butter with crisp sage leaves and Parmigiano.', 'italian', 3, 40, 75, 115, 4, 'main', null, 0, array['stove', 'oven']::text[], array['vegetarian', 'comfort', 'date-night']::text[], array['Freeze shaped gnocchi in a single layer on the floured tray, then bag them; boil straight from frozen.', 'Parmigiano-Reggiano is made with animal rennet; use a vegetarian hard cheese if that matters to you.']::text[], 'https://images.pexels.com/photos/6659625/pexels-photo-6659625.jpeg', 'Golden pan-fried potato gnocchi garnished with herbs', 'Kaboompics.com', 'https://www.pexels.com/@karola-g/', 'https://www.pexels.com/photo/gnocchi-dish-in-close-up-shot-6659625/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner', 'comfort', 'date_night']::text[], array['steam', 'bake', 'boil']::text[], array['savory']::text[], '{}'::text[], null, 'traditional', 'potato-gnocchi', 'classic', 'Uncooked gnocchi keep 1 day on a floured tray in the fridge or 2 months frozen. Cooked gnocchi are best eaten right away.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['russet potato', 'egg yolk', 'sage', 'parmigiano-reggiano']::text[], 'egg yolk|parmigiano-reggiano|russet potato|sage',
  null, null, null, null, null, null, null, null)
