delete from public.recipe_ingredients where recipe_id = 'c662d898-5490-4e85-b07d-d871273ae928';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('c662d898-5490-4e85-b07d-d871273ae928', 1, 'Gnocchi', '2 lb russet potatoes, about 3 large, scrubbed', 'russet potatoes', 2, 'lb', 'about 3 large, scrubbed', false),
  ('c662d898-5490-4e85-b07d-d871273ae928', 2, 'Gnocchi', '1 cup all-purpose flour, plus up to ¼ cup more and extra for dusting', 'all-purpose flour', 1, 'cup', 'plus up to ¼ cup more and extra for dusting', false),
  ('c662d898-5490-4e85-b07d-d871273ae928', 3, 'Gnocchi', '1 large egg yolk', 'large egg yolk', 1, null, null, false),
  ('c662d898-5490-4e85-b07d-d871273ae928', 4, 'Gnocchi', '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('c662d898-5490-4e85-b07d-d871273ae928', 5, 'Gnocchi', '1 tbsp kosher salt, for the cooking water', 'kosher salt', 1, 'tbsp', 'for the cooking water', false),
  ('c662d898-5490-4e85-b07d-d871273ae928', 6, 'Sauce', '6 tbsp unsalted butter', 'unsalted butter', 6, 'tbsp', null, false),
  ('c662d898-5490-4e85-b07d-d871273ae928', 7, 'Sauce', '16 leaf fresh sage', 'fresh sage', 16, 'leaf', null, false),
  ('c662d898-5490-4e85-b07d-d871273ae928', 8, 'Sauce', '½ cup Parmigiano-Reggiano, finely grated', 'Parmigiano-Reggiano', 0.5, 'cup', 'finely grated', false),
  ('c662d898-5490-4e85-b07d-d871273ae928', 9, 'Sauce', '¼ tsp black pepper', 'black pepper', 0.25, 'tsp', null, false);
delete from public.recipe_instructions where recipe_id = 'c662d898-5490-4e85-b07d-d871273ae928';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('c662d898-5490-4e85-b07d-d871273ae928', 1, 'Gnocchi', 'Heat the oven to 400°F. Prick the potatoes and bake directly on the rack until completely tender, about 1 hour. Baking (rather than boiling) keeps them dry so you need less flour.', 3600, 204.4, null),
  ('c662d898-5490-4e85-b07d-d871273ae928', 2, 'Gnocchi', 'While still hot, halve the potatoes, scoop out the flesh and press it through a ricer or food mill onto a floured board. Spread out to let the steam escape for 5 minutes.', 300, null, null),
  ('c662d898-5490-4e85-b07d-d871273ae928', 3, 'Gnocchi', 'Sprinkle over the flour and salt, add the yolk and gently gather into a soft dough with a bench scraper, adding a little more flour only if it''s very sticky. Knead just a few turns — overworking makes gnocchi tough.', null, null, null),
  ('c662d898-5490-4e85-b07d-d871273ae928', 4, 'Gnocchi', 'Divide into 6 pieces and roll each into a rope ¾ inch thick. Cut into ¾-inch pillows and, if you like, roll each down the back of a fork for ridges. Set on a floured sheet pan.', 1200, null, null),
  ('c662d898-5490-4e85-b07d-d871273ae928', 5, 'Sauce', 'Melt the butter in a large skillet over medium heat and cook, swirling, until it foams, turns golden-brown and smells nutty, 3–4 minutes. Add the sage and fry until crisp, 30 seconds. Take off the heat.', 240, null, null),
  ('c662d898-5490-4e85-b07d-d871273ae928', 6, 'Gnocchi', 'Boil the gnocchi in salted water in 2 batches; once they float, give them 30 seconds more, then lift them straight into the brown butter with a slotted spoon.', 240, null, null),
  ('c662d898-5490-4e85-b07d-d871273ae928', 7, 'Sauce', 'Toss over medium heat for 1 minute with a splash of cooking water until glossy. Serve topped with Parmigiano and pepper.', 60, null, null);

-- Neapolitan Margherita Pizza
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
  status, categories, methods, flavors, occasions, region, authenticity, dish_key, variant, storage_notes, safety_note, text_license, allergens, proteins, diet_tags, core_ingredients, fingerprint,
  attribution, reviewed_by, reviewed_at, calories_per_serving, protein_g, carbs_g, fat_g, nutrition_source)
values ('f59e2a2f-d062-40c8-94bd-cbba33921993', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'neapolitan-margherita-pizza', 'neapolitan-margherita-pizza-f59e2a', 'Neapolitan Margherita Pizza', 'Naples'' original pizza — a soft, blistered crust with San Marzano tomato, fresh mozzarella, basil and olive oil; we cold-ferment the dough and bake on a pizza steel under the broiler since home ovens can''t reach a wood oven''s 900°F.', 'italian', 3, 210, 75, 1725, 4, 'main', null, 1440, array['oven', 'stand_mixer']::text[], array['vegetarian', 'weekend', 'kid-friendly']::text[], array['A pizza steel holds more heat than a stone and gives the closest result to a pizzeria oven at home. An upturned heavy sheet pan, preheated, works in a pinch.', 'Scale matters for pizza dough — 500 g flour and 325 ml water is the recipe; the cup measures are approximate.']::text[], 'https://images.pexels.com/photos/18437684/pexels-photo-18437684.jpeg', 'Wood-fired Margherita pizza with tomato, mozzarella and fresh basil', 'Nadin Sh', 'https://www.pexels.com/@nadin-sh-78971847/', 'https://www.pexels.com/photo/pizza-on-table-18437684/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'main', 'dinner', 'comfort']::text[], '{}'::text[], array['fresh', 'savory']::text[], '{}'::text[], 'Naples', 'adapted', 'margherita-pizza', 'classic', 'Dough balls keep 3 days in the fridge or 1 month frozen (thaw overnight in the fridge). Leftover pizza reheats best in a hot skillet.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['pizza flour', 'cool water', 'instant yeast', 'marzano tomato', 'mozzarella', 'basil', 'semolina']::text[], 'basil|cool water|instant yeast|marzano tomato|mozzarella|pizza flour|semolina',
  null, null, null, null, null, null, null, null)
