delete from public.recipe_ingredients where recipe_id = 'f59e2a2f-d062-40c8-94bd-cbba33921993';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('f59e2a2f-d062-40c8-94bd-cbba33921993', 1, 'Dough', '3¾ cups ''00'' pizza flour, about 500 g, or bread flour', '''00'' pizza flour', 3.75, 'cup', 'about 500 g, or bread flour', false),
  ('f59e2a2f-d062-40c8-94bd-cbba33921993', 2, 'Dough', '1½ cups cool water, 325 ml', 'cool water', 1.5, 'cup', '325 ml', false),
  ('f59e2a2f-d062-40c8-94bd-cbba33921993', 3, 'Dough', '2½ tsp fine sea salt', 'fine sea salt', 2.5, 'tsp', null, false),
  ('f59e2a2f-d062-40c8-94bd-cbba33921993', 4, 'Dough', '¼ tsp instant yeast', 'instant yeast', 0.25, 'tsp', null, false),
  ('f59e2a2f-d062-40c8-94bd-cbba33921993', 5, 'Topping', '1 can whole peeled San Marzano tomatoes, 28 oz, drained', 'whole peeled San Marzano tomatoes', 1, 'can', '28 oz, drained', false),
  ('f59e2a2f-d062-40c8-94bd-cbba33921993', 6, 'Topping', '½ tsp fine sea salt', 'fine sea salt', 0.5, 'tsp', null, false),
  ('f59e2a2f-d062-40c8-94bd-cbba33921993', 7, 'Topping', '12 oz fresh mozzarella, torn into small pieces and drained on paper towels', 'fresh mozzarella', 12, 'oz', 'torn into small pieces and drained on paper towels', false),
  ('f59e2a2f-d062-40c8-94bd-cbba33921993', 8, 'Topping', '16 leaf fresh basil', 'fresh basil', 16, 'leaf', null, false),
  ('f59e2a2f-d062-40c8-94bd-cbba33921993', 9, 'Topping', '3 tbsp extra-virgin olive oil', 'extra-virgin olive oil', 3, 'tbsp', null, false),
  ('f59e2a2f-d062-40c8-94bd-cbba33921993', 10, 'Topping', '¼ cup Parmigiano-Reggiano, finely grated', 'Parmigiano-Reggiano', 0.25, 'cup', 'finely grated', true),
  ('f59e2a2f-d062-40c8-94bd-cbba33921993', 11, 'Topping', '¼ cup semolina, for the peel', 'semolina', 0.25, 'cup', 'for the peel', false);
delete from public.recipe_instructions where recipe_id = 'f59e2a2f-d062-40c8-94bd-cbba33921993';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('f59e2a2f-d062-40c8-94bd-cbba33921993', 1, 'Dough', 'Mix the flour, water, salt and yeast in a stand mixer with the dough hook on low until it comes together, then knead on medium-low until smooth and elastic, 8 minutes. Cover and let rise at room temperature 2 hours.', 7800, null, null),
  ('f59e2a2f-d062-40c8-94bd-cbba33921993', 2, 'Dough', 'Divide into 4 pieces (about 7 oz each), shape each into a tight ball and put in an oiled container with room to grow. Cover and refrigerate 24 hours (or up to 72) to develop flavor.', 86400, null, null),
  ('f59e2a2f-d062-40c8-94bd-cbba33921993', 3, 'Dough', 'Take the dough out 1½ hours before baking and leave it covered at room temperature. Put a pizza steel or stone on the top rack, about 6 inches below the broiler, and heat the oven to its highest setting (500–550°F) for 45 minutes.', 5400, 287.8, null),
  ('f59e2a2f-d062-40c8-94bd-cbba33921993', 4, 'Topping', 'Crush the tomatoes by hand or pass them through a food mill and stir in the salt. Don''t cook the sauce — it cooks on the pizza.', null, null, null),
  ('f59e2a2f-d062-40c8-94bd-cbba33921993', 5, 'Topping', 'On a floured surface, press one ball from the center outward with your fingertips into a 10-inch round, leaving a puffy 1-inch rim; don''t use a rolling pin. Lay it on a semolina-dusted peel and spread with ¼ cup tomato, leaving the rim bare.', 180, null, null),
  ('f59e2a2f-d062-40c8-94bd-cbba33921993', 6, 'Topping', 'Switch the oven to broil (high). Slide the pizza onto the steel, broil 2 minutes, then scatter on a quarter of the mozzarella and broil until the rim is puffed and charred in spots and the cheese has melted, 2–3 minutes more.', 300, null, null),
  ('f59e2a2f-d062-40c8-94bd-cbba33921993', 7, null, 'Top with basil leaves, a drizzle of oil and Parmigiano if you like. Reheat the steel at 550°F for 5 minutes between pizzas, then repeat.', 300, 287.8, null);

-- Linguine alle Vongole
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
