values ('97d44580-1ff9-4da8-8ab4-630f790f0b47', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'linguine-alle-vongole', 'linguine-alle-vongole-97d445', 'Linguine alle Vongole', 'Linguine tossed with sweet little clams steamed open in garlic, olive oil, chili and white wine, finished with parsley — the Neapolitan Christmas Eve classic, made in bianco without tomato.', 'italian', 3, 40, 20, 60, 4, 'main', null, 0, array['stove']::text[], array['date-night', 'entertaining']::text[], array['Pull half the clams from their shells before tossing them back in so every forkful gets some, and leave the rest in shell for looks.']::text[], 'https://images.unsplash.com/photo-1768204038645-b50312187392', 'Pasta with clams and herbs on a white plate', 'Lee Milo', 'https://unsplash.com/@miloleetw', 'https://unsplash.com/photos/spaghetti-with-clams-and-herbs-on-a-white-plate-5kO64X4-Peo', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'holiday', 'date_night', 'entertaining']::text[], array['boil']::text[], array['spicy']::text[], array['christmas', 'date-night']::text[], 'Campania', 'traditional', 'linguine-vongole', 'classic', 'Best immediately. Refrigerate leftovers up to 1 day and reheat gently in a covered skillet.', 'Use live clams: before cooking, throw away any with cracked shells or that stay open when tapped, and after cooking discard any that haven''t opened. Keep them cold until they go in the pan.', 'owned', array['gluten', 'shellfish', 'wheat']::text[], array['shellfish']::text[], array['pescatarian', 'dairy_free']::text[], array['manila clam', 'linguine', 'garlic', 'pepper flake', 'white wine', 'flat-leaf parsley']::text[], 'flat-leaf parsley|garlic|linguine|manila clam|pepper flake|white wine',
  null, null, null, null, null, null, null, null)
