delete from public.recipe_ingredients where recipe_id = '97d44580-1ff9-4da8-8ab4-630f790f0b47';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('97d44580-1ff9-4da8-8ab4-630f790f0b47', 1, null, '3 lb littleneck or Manila clams, scrubbed', 'littleneck or Manila clams', 3, 'lb', 'scrubbed', false),
  ('97d44580-1ff9-4da8-8ab4-630f790f0b47', 2, null, '2 tbsp kosher salt, for purging, plus 1 tbsp for the pasta water', 'kosher salt', 2, 'tbsp', 'for purging, plus 1 tbsp for the pasta water', false),
  ('97d44580-1ff9-4da8-8ab4-630f790f0b47', 3, null, '1 lb linguine, or spaghetti', 'linguine', 1, 'lb', 'or spaghetti', false),
  ('97d44580-1ff9-4da8-8ab4-630f790f0b47', 4, null, '⅓ cup extra-virgin olive oil, plus more to finish', 'extra-virgin olive oil', 0.33, 'cup', 'plus more to finish', false),
  ('97d44580-1ff9-4da8-8ab4-630f790f0b47', 5, null, '5 cloves garlic, thinly sliced', 'garlic', 5, 'clove', 'thinly sliced', false),
  ('97d44580-1ff9-4da8-8ab4-630f790f0b47', 6, null, '½ tsp red pepper flakes', 'red pepper flakes', 0.5, 'tsp', null, false),
  ('97d44580-1ff9-4da8-8ab4-630f790f0b47', 7, null, '½ cup dry white wine', 'dry white wine', 0.5, 'cup', null, false),
  ('97d44580-1ff9-4da8-8ab4-630f790f0b47', 8, null, '½ cup fresh flat-leaf parsley, finely chopped', 'fresh flat-leaf parsley', 0.5, 'cup', 'finely chopped', false);
delete from public.recipe_instructions where recipe_id = '97d44580-1ff9-4da8-8ab4-630f790f0b47';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('97d44580-1ff9-4da8-8ab4-630f790f0b47', 1, null, 'Purge the clams: soak them in a bowl of cold water with the 2 tablespoons salt for 30 minutes so they spit out sand, then lift them out (leaving the grit behind) and rinse.', 1800, null, null),
  ('97d44580-1ff9-4da8-8ab4-630f790f0b47', 2, null, 'Bring a large pot of water to a boil with 1 tablespoon salt — go easy, the clam juices are salty. Cook the linguine until 2 minutes short of al dente.', 540, null, null),
  ('97d44580-1ff9-4da8-8ab4-630f790f0b47', 3, null, 'Meanwhile, warm the oil, garlic and pepper flakes in a large, deep skillet with a lid over medium heat until the garlic is fragrant and just pale gold, 2 minutes.', 120, null, null),
  ('97d44580-1ff9-4da8-8ab4-630f790f0b47', 4, null, 'Add the clams and wine, cover and cook over high heat, shaking the pan, until the shells open, 4–6 minutes (the meat reaches 145°F once the shells are open). Move the opened clams to a bowl as they''re ready and discard any that stay shut.', 300, null, 62.8),
  ('97d44580-1ff9-4da8-8ab4-630f790f0b47', 5, null, 'Drain the pasta (keep a cup of water) and add it to the clam juices in the skillet. Toss over high heat for 2 minutes until the pasta absorbs most of the liquid, adding pasta water if it gets dry.', 120, null, null),
  ('97d44580-1ff9-4da8-8ab4-630f790f0b47', 6, null, 'Return the clams with their juices, add the parsley and a drizzle of oil and toss once more. Serve right away — no cheese, as is the custom with seafood pasta.', null, null, null);

-- Arancini
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
