values ('7888ecc8-9715-45a5-80ee-9d4c4686a986', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'sicilian-arancini-al-ragu', 'arancini-7888ec', 'Arancini', 'Golden fried saffron rice balls from Sicily stuffed with a little beef and pea ragù and melting cheese, the most common filling, coated in crisp breadcrumbs.', 'italian', 3, 60, 70, 250, 6, 'starter', null, 120, array['stove', 'dutch_oven']::text[], array['entertaining', 'make-ahead']::text[], array['Cool cooked rice quickly and keep it in the fridge — rice left out at room temperature for hours can grow bacteria that reheating won''t destroy.', 'Leftover risotto makes excellent arancini: you''ll need about 5 cups, well chilled.']::text[], 'https://images.pexels.com/photos/19260791/pexels-photo-19260791.jpeg', 'Fried Sicilian arancini on a bed of arugula on a wooden tray', 'Giona Mason', 'https://www.pexels.com/@giona-mason-1751396/', 'https://www.pexels.com/photo/meat-on-tray-19260791/', 'pexels', true, 'public', false,
  'pending_review', array['appetizer', 'holiday', 'entertaining']::text[], array['stew', 'boil']::text[], '{}'::text[], array['game-day', 'dinner-party']::text[], 'Sicily', 'traditional', 'arancini', 'classic', 'Shaped, coated arancini keep 1 day in the fridge or 2 months frozen (fry from frozen at 325°F for 8–10 minutes). Re-crisp leftovers at 375°F for 15 minutes.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], array['beef']::text[], '{}'::text[], array['chicken broth', 'saffron thread', 'arborio rice', 'romano cheese', 'yellow onion', 'ground beef', 'tomato paste', 'tomato passata', 'frozen pea', 'caciocavallo cheese', 'dry breadcrumb']::text[], 'arborio rice|caciocavallo cheese|chicken broth|dry breadcrumb|frozen pea|ground beef|romano cheese|saffron thread|tomato passata|tomato paste|yellow onion',
  null, null, null, null, null, null, null, null)
