insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 1, 'Rice', '4 cups low-sodium chicken broth', 'low-sodium chicken broth', 4, 'cup', null, false),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 2, 'Rice', '¼ tsp saffron threads', 'saffron threads', 0.25, 'tsp', null, false),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 3, 'Rice', '2 cups Arborio rice', 'Arborio rice', 2, 'cup', null, false),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 4, 'Rice', '2 tbsp unsalted butter', 'unsalted butter', 2, 'tbsp', null, false),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 5, 'Rice', '⅔ cup Pecorino Romano cheese, finely grated', 'Pecorino Romano cheese', 0.66, 'cup', 'finely grated', false),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 6, 'Ragù', '1 tbsp olive oil', 'olive oil', 1, 'tbsp', null, false),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 7, 'Ragù', '½ small yellow onion, finely diced', 'small yellow onion', 0.5, null, 'finely diced', false),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 8, 'Ragù', '8 oz ground beef', 'ground beef', 8, 'oz', null, false),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 9, 'Ragù', '1 tbsp tomato paste', 'tomato paste', 1, 'tbsp', null, false),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 10, 'Ragù', '½ cup tomato passata', 'tomato passata', 0.5, 'cup', null, false),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 11, 'Ragù', '½ cup frozen peas', 'frozen peas', 0.5, 'cup', null, false),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 12, 'Ragù', '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 13, 'Ragù', '3 oz provolone or caciocavallo cheese, cut into ½-inch cubes', 'provolone or caciocavallo cheese', 3, 'oz', 'cut into ½-inch cubes', false),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 14, 'Coating', '1 cup all-purpose flour', 'all-purpose flour', 1, 'cup', null, false),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 15, 'Coating', '1 cup cold water', 'cold water', 1, 'cup', null, false),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 16, 'Coating', '2 cups fine dry breadcrumbs', 'fine dry breadcrumbs', 2, 'cup', null, false),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 17, 'Coating', '8 cups vegetable oil, for deep-frying', 'vegetable oil', 8, 'cup', 'for deep-frying', false);
delete from public.recipe_instructions where recipe_id = '7888ecc8-9715-45a5-80ee-9d4c4686a986';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 1, 'Rice', 'Bring the broth and saffron to a boil, stir in the rice, cover and simmer on low until the liquid is absorbed and the rice is tender, 18 minutes. Stir in the butter and Pecorino, spread on a sheet pan, cool 15 minutes, then refrigerate until fully cold and firm, at least 2 hours.', 1200, null, null),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 2, 'Ragù', 'Heat the oil in a small skillet over medium heat and soften the onion, 5 minutes. Add the beef and cook, breaking it up finely, until no pink remains and it reaches 160°F, 5 minutes. Stir in the tomato paste, passata and salt and simmer until very thick, 10 minutes; add the peas for the last 2 minutes. Cool completely.', 1200, null, 71.1),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 3, 'Coating', 'Whisk the flour and cold water into a smooth, thin batter. Put the breadcrumbs in a shallow dish.', null, null, null),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 4, 'Ragù', 'With wet hands, flatten about ⅓ cup of rice in your palm, add a teaspoon of ragù and a cube of cheese, then close the rice around it and shape into a firm ball or cone. You''ll get about 14.', 1500, null, null),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 5, 'Coating', 'Dip each ball in the batter, then roll in the breadcrumbs, pressing so they stick. Chill 15 minutes to set.', 900, null, null),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 6, 'Coating', 'Heat the oil in a heavy Dutch oven — no more than half full — to 350°F, with a thermometer clipped to the side. Keep children and pets away and never leave hot oil unattended.', 720, 176.7, null),
  ('7888ecc8-9715-45a5-80ee-9d4c4686a986', 7, 'Coating', 'Fry 3–4 at a time, turning, until deep golden all over and hot in the center, 4–5 minutes. Drain on a rack and rest 5 minutes before serving.', 1080, 176.7, null);

-- Cannoli
