values ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'sicilian-cannoli', 'cannoli-3bb04b', 'Cannoli', 'Crisp, bubbly Marsala-scented shells fried around metal tubes and filled to order with sweetened ricotta, chocolate and candied orange; we use cow''s-milk ricotta, as sheep''s-milk ricotta is hard to find outside Sicily.', 'italian', 3, 75, 30, 825, 16, 'dessert', 'pastries', 720, array['stove', 'dutch_oven']::text[], array['entertaining', 'holiday']::text[], array['You''ll need metal cannoli tubes (about 1 inch wide, sold in sets of 8–12 at kitchen shops or online); fry in batches and reuse them once cool.', 'Fill only at the last minute — filled shells go soft within an hour. Semisweet chocolate chips often contain milk and soy; check the label if needed.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['dessert', 'holiday', 'entertaining']::text[], '{}'::text[], array['tangy', 'aromatic', 'sweet']::text[], array['christmas', 'easter']::text[], 'Sicily', 'adapted', 'cannoli', 'classic', 'Unfilled shells keep 1 week airtight at room temperature; the filling keeps 3 days in the fridge. Don''t store filled cannoli.', null, 'owned', array['egg', 'gluten', 'milk', 'tree_nut', 'wheat']::text[], '{}'::text[], '{}'::text[], array['whole-milk ricotta', 'powdered sugar', 'ground cinnamon', 'vanilla extract', 'chocolate chip', 'cocoa powder', 'lard', 'egg', 'marsala wine', 'wine vinegar']::text[], 'chocolate chip|cocoa powder|egg|ground cinnamon|lard|marsala wine|powdered sugar|vanilla extract|whole-milk ricotta|wine vinegar',
  null, null, null, null, null, null, null, null)
