insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 1, 'Filling', '2 lb whole-milk ricotta', 'whole-milk ricotta', 2, 'lb', null, false),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 2, 'Filling', '¾ cup powdered sugar, plus more for dusting', 'powdered sugar', 0.75, 'cup', 'plus more for dusting', false),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 3, 'Filling', '½ tsp ground cinnamon', 'ground cinnamon', 0.5, 'tsp', null, false),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 4, 'Filling', '½ tsp vanilla extract', 'vanilla extract', 0.5, 'tsp', null, false),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 5, 'Filling', '⅓ cup mini semisweet chocolate chips', 'mini semisweet chocolate chips', 0.33, 'cup', null, false),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 6, 'Filling', '¼ cup candied orange peel, finely chopped', 'candied orange peel', 0.25, 'cup', 'finely chopped', true),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 7, 'Shells', '2 cups all-purpose flour, plus more for rolling', 'all-purpose flour', 2, 'cup', 'plus more for rolling', false),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 8, 'Shells', '2 tbsp sugar', 'sugar', 2, 'tbsp', null, false),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 9, 'Shells', '1 tbsp unsweetened cocoa powder', 'unsweetened cocoa powder', 1, 'tbsp', null, false),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 10, 'Shells', '¼ tsp ground cinnamon', 'ground cinnamon', 0.25, 'tsp', null, false),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 11, 'Shells', '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 12, 'Shells', '2 tbsp lard, or unsalted butter, cold', 'lard', 2, 'tbsp', 'or unsalted butter, cold', false),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 13, 'Shells', '1 large egg, separated, white kept for sealing', 'large egg', 1, null, 'separated, white kept for sealing', false),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 14, 'Shells', '½ cup dry Marsala wine', 'dry Marsala wine', 0.5, 'cup', null, false),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 15, 'Shells', '1 tbsp white wine vinegar', 'white wine vinegar', 1, 'tbsp', null, false),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 16, 'Shells', '8 cups vegetable oil, for deep-frying', 'vegetable oil', 8, 'cup', 'for deep-frying', false),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 17, 'Garnish', '¼ cup shelled pistachios, finely chopped', 'shelled pistachios', 0.25, 'cup', 'finely chopped', true);
delete from public.recipe_instructions where recipe_id = '3bb04ba3-0dcd-40da-9157-0f3fdd22918b';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 1, 'Filling', 'Line a sieve with cheesecloth or paper towels, add the ricotta, set over a bowl and drain in the fridge overnight (at least 8 hours). Then beat in the powdered sugar, cinnamon and vanilla until smooth and fold in the chocolate chips and candied peel. Keep chilled.', 43200, null, null),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 2, 'Shells', 'Mix the flour, sugar, cocoa, cinnamon and salt. Rub in the lard, then add the egg yolk, Marsala and vinegar and knead into a firm, smooth dough, 5 minutes. Wrap and rest 30 minutes.', 2100, null, null),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 3, 'Shells', 'Roll the dough very thin — about 1/16 inch (a pasta machine helps). Cut 4-inch rounds, rerolling scraps once. Wrap each round around a lightly oiled metal cannoli tube, dab the overlap with egg white and press to seal.', 1500, null, null),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 4, 'Shells', 'Heat the oil in a heavy Dutch oven — no more than half full — to 360°F, with a thermometer clipped to the side. Keep children and pets away and never leave hot oil unattended.', 720, 182.2, null),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 5, 'Shells', 'Fry 3–4 at a time until blistered and deep golden, 1½–2 minutes. Lift out with tongs, drain on paper towels and, holding the tube with a towel, slide the shell off while warm. Cool the tubes before reusing.', 960, 182.2, null),
  ('3bb04ba3-0dcd-40da-9157-0f3fdd22918b', 6, null, 'Just before serving, pipe the filling into both ends of each shell. Dip the ends in pistachios if you like and dust with powdered sugar.', null, null, null);

-- Beef Wellington
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
