values ('ffc89a2b-7295-4ddf-81b7-c2d1fa19e5c0', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'beef-wellington', 'beef-wellington-ffc89a', 'Beef Wellington', 'A center-cut beef tenderloin coated in Dijon mustard, mushroom duxelles and prosciutto, wrapped in golden puff pastry — a showpiece for a holiday table.', 'french', 4, 60, 50, 155, 6, 'main', null, 45, array['stove', 'oven', 'cast_iron', 'food_processor']::text[], array['entertaining', 'make-ahead']::text[], array['Many restaurants serve Wellington medium-rare, pulled at about 120°F; that''s below the USDA''s 145°F recommendation for whole cuts of beef.', 'Wrap it in pastry up to 12 hours ahead and keep it chilled; add 5–10 minutes to the baking time.']::text[], 'https://images.pexels.com/photos/37322867/pexels-photo-37322867.jpeg', 'Sliced beef Wellington showing a pink centre inside golden puff pastry on a wooden board', 'Kemal Can', 'https://www.pexels.com/@kemalcanfilm/', 'https://www.pexels.com/photo/delicious-beef-wellington-on-wooden-board-37322867/', 'pexels', true, 'public', false,
  'pending_review', array['entertaining', 'holiday', 'main', 'dinner']::text[], array['pan_fry', 'bake']::text[], '{}'::text[], array['christmas', 'new-year', 'dinner-party']::text[], null, 'traditional', 'beef-wellington', 'classic', 'Best the day it''s baked. Refrigerate leftovers up to 3 days and reheat slices at 350°F for 10–12 minutes to re-crisp the pastry.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], array['beef', 'pork']::text[], '{}'::text[], array['beef tenderloin', 'dijon mustard', 'cremini mushroom', 'shallot', 'garlic', 'thyme leave', 'white wine', 'prosciutto', 'puff pastry', 'egg']::text[], 'beef tenderloin|cremini mushroom|dijon mustard|egg|garlic|prosciutto|puff pastry|shallot|thyme leave|white wine',
  null, null, null, null, null, null, null, null)
