insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('ffc89a2b-7295-4ddf-81b7-c2d1fa19e5c0', 1, 'Beef', '2½ lb center-cut beef tenderloin, trimmed and tied', 'center-cut beef tenderloin', 2.5, 'lb', 'trimmed and tied', false),
  ('ffc89a2b-7295-4ddf-81b7-c2d1fa19e5c0', 2, 'Beef', '1½ tsp kosher salt', 'kosher salt', 1.5, 'tsp', null, false),
  ('ffc89a2b-7295-4ddf-81b7-c2d1fa19e5c0', 3, 'Beef', '½ tsp black pepper', 'black pepper', 0.5, 'tsp', null, false),
  ('ffc89a2b-7295-4ddf-81b7-c2d1fa19e5c0', 4, 'Beef', '2 tbsp vegetable oil', 'vegetable oil', 2, 'tbsp', null, false),
  ('ffc89a2b-7295-4ddf-81b7-c2d1fa19e5c0', 5, 'Beef', '2 tbsp Dijon mustard', 'Dijon mustard', 2, 'tbsp', null, false),
  ('ffc89a2b-7295-4ddf-81b7-c2d1fa19e5c0', 6, 'Duxelles', '1½ lb cremini mushrooms, roughly chopped', 'cremini mushrooms', 1.5, 'lb', 'roughly chopped', false),
  ('ffc89a2b-7295-4ddf-81b7-c2d1fa19e5c0', 7, 'Duxelles', '2 tbsp unsalted butter', 'unsalted butter', 2, 'tbsp', null, false),
  ('ffc89a2b-7295-4ddf-81b7-c2d1fa19e5c0', 8, 'Duxelles', '2 shallots, finely chopped', 'shallots', 2, null, 'finely chopped', false),
