values ('1ce2806b-757d-4708-a5bb-6e809ae6df1f', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'duck-confit', 'duck-confit-1ce280', 'Duck Confit', 'Duck legs salt-cured overnight with garlic and thyme, cooked slowly in duck fat until meltingly tender, then crisped skin-side down — Gascony''s great preserved dish.', 'french', 3, 20, 190, 930, 4, 'main', null, 720, array['stove', 'oven', 'dutch_oven', 'cast_iron']::text[], array['make-ahead', 'entertaining']::text[], array['Duck fat is sold in tubs at butchers, well-stocked supermarkets and online. Strain and refrigerate it after cooking — it can be reused for confit or roast potatoes.', 'Duck legs are often sold frozen; thaw them in the fridge for a day before curing.']::text[], 'https://images.pexels.com/photos/14537674/pexels-photo-14537674.jpeg', 'Crisp duck leg with rich sauce and creamy mashed potatoes on a rustic plate', 'Cristian Mihaila', 'https://www.pexels.com/@crysnet/', 'https://www.pexels.com/photo/meat-on-plate-14537674/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner', 'holiday', 'entertaining']::text[], array['stew', 'bake']::text[], array['rich']::text[], array['dinner-party']::text[], 'Gascony', 'traditional', 'duck-confit', 'classic', 'Refrigerate the cooled legs covered in their fat up to 1 week, or freeze up to 3 months.', 'The salt cure here is for flavour, not preservation. Keep the legs refrigerated while they cure, and store the finished confit in the fridge, fully covered in fat, for no more than 1 week — keeping confit at room temperature isn''t safe at home.', 'owned', '{}'::text[], array['duck']::text[], array['gluten_free', 'dairy_free']::text[], array['duck leg', 'garlic', 'thyme', 'bay leave', 'duck fat']::text[], 'bay leave|duck fat|duck leg|garlic|thyme',
  null, null, null, null, null, null, null, null)
