insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('1ce2806b-757d-4708-a5bb-6e809ae6df1f', 1, 'Cure', '4 duck legs, about 3 lb total', 'duck legs', 4, null, 'about 3 lb total', false),
  ('1ce2806b-757d-4708-a5bb-6e809ae6df1f', 2, 'Cure', '2 tbsp kosher salt', 'kosher salt', 2, 'tbsp', null, false),
  ('1ce2806b-757d-4708-a5bb-6e809ae6df1f', 3, 'Cure', '½ tsp black pepper, coarsely ground', 'black pepper', 0.5, 'tsp', 'coarsely ground', false),
  ('1ce2806b-757d-4708-a5bb-6e809ae6df1f', 4, 'Cure', '4 cloves garlic, smashed', 'garlic', 4, 'clove', 'smashed', false),
  ('1ce2806b-757d-4708-a5bb-6e809ae6df1f', 5, 'Cure', '6 sprigs fresh thyme', 'fresh thyme', 6, 'sprig', null, false),
  ('1ce2806b-757d-4708-a5bb-6e809ae6df1f', 6, 'Cure', '2 bay leaves, crumbled', 'bay leaves', 2, null, 'crumbled', false),
  ('1ce2806b-757d-4708-a5bb-6e809ae6df1f', 7, 'Confit', '4 cups duck fat, melted, or half duck fat and half olive oil', 'duck fat', 4, 'cup', 'melted, or half duck fat and half olive oil', false);
delete from public.recipe_instructions where recipe_id = '1ce2806b-757d-4708-a5bb-6e809ae6df1f';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('1ce2806b-757d-4708-a5bb-6e809ae6df1f', 1, 'Cure', 'Rub the salt and pepper all over the duck legs. Lay them skin-side up in a dish in one layer, tuck the garlic, thyme and bay around and over them, cover and refrigerate 12–24 hours.', 43200, null, null),
  ('1ce2806b-757d-4708-a5bb-6e809ae6df1f', 2, 'Confit', 'Heat the oven to 275°F. Rinse the legs under cold water to remove the salt and herbs (keep the garlic) and pat them very dry.', null, 135, null),
  ('1ce2806b-757d-4708-a5bb-6e809ae6df1f', 3, 'Confit', 'Fit the legs snugly, skin-side up, in a Dutch oven or small baking dish. Warm the duck fat until liquid and pour it over so the legs are just submerged. Add the garlic.', null, null, null),
  ('1ce2806b-757d-4708-a5bb-6e809ae6df1f', 4, 'Confit', 'Cover and bake until the meat is very tender and pulls easily from the bone, 2½–3 hours; it will be far past 165°F. The fat should only bubble lazily — lower the oven to 250°F if it simmers hard.', 9900, 135, 73.9),
  ('1ce2806b-757d-4708-a5bb-6e809ae6df1f', 5, 'Confit', 'Lift the legs out of the fat and let the excess drip off. Heat a cast-iron skillet over medium heat and cook them skin-side down, without moving, until the skin is crisp and deep golden, 8–10 minutes; flip for 2 minutes to heat through.', 720, null, null),
  ('1ce2806b-757d-4708-a5bb-6e809ae6df1f', 6, null, 'Serve with potatoes fried in a spoonful of the duck fat, a green salad with a sharp vinaigrette, or garlicky white beans.', null, null, null);

-- Bouillabaisse
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
