values ('09b544b7-8294-416e-a192-837792483735', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'bouillabaisse', 'bouillabaisse-09b544', 'Bouillabaisse', 'Marseille''s saffron, fennel and orange-scented fish stew with firm white fish, mussels and potatoes, served with toasts and garlicky rouille; we use fish from North American markets in place of Mediterranean rockfish and build the broth on store-bought fish stock.', 'french', 4, 45, 60, 105, 6, 'main', null, 0, array['stove', 'oven', 'dutch_oven']::text[], array['entertaining']::text[], array['Ask the fishmonger for a mix of firm white fish; flaky cod falls apart, so add it in the last 3 minutes if you use it.', 'Before cooking, tap any open mussels on the counter and throw away any that don''t close, plus any with cracked shells.']::text[], 'https://images.pexels.com/photos/17568746/pexels-photo-17568746.jpeg', 'Red seafood soup garnished with basil leaves in a white bowl on a wooden table', 'Nadin Sh', 'https://www.pexels.com/@nadin-sh-78971847/', 'https://www.pexels.com/photo/delicious-red-soup-on-table-17568746/', 'pexels', true, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'holiday', 'entertaining']::text[], array['stew', 'boil']::text[], array['spicy']::text[], array['dinner-party']::text[], 'Marseille', 'adapted', 'bouillabaisse', 'classic', 'Best eaten the day it''s made. Refrigerate leftover broth and fish separately up to 1 day and reheat gently without boiling. Rouille keeps 2 days in the fridge.', null, 'owned', array['fish', 'gluten', 'shellfish', 'wheat']::text[], array['fish', 'shellfish']::text[], array['pescatarian', 'dairy_free']::text[], array['yellow onion', 'leek', 'fennel bulb', 'garlic', 'tomato paste', 'tomato', 'fish stock', 'saffron thread', 'orange peel', 'thyme', 'bay leaf', 'pepper flake', 'gold potato', 'monkfish fillet', 'snapper fillet', 'halibut fillet', 'mussel', 'russet potato', 'cayenne pepper', 'baguette']::text[], 'baguette|bay leaf|cayenne pepper|fennel bulb|fish stock|garlic|gold potato|halibut fillet|leek|monkfish fillet|mussel|orange peel|pepper flake|russet potato|saffron thread|snapper fillet|thyme|tomato|tomato paste|yellow onion',
  null, null, null, null, null, null, null, null)
