  ('09b544b7-8294-416e-a192-837792483735', 17, 'Seafood', '1 lb monkfish fillet, membrane removed, cut into 2-inch chunks', 'monkfish fillet', 1, 'lb', 'membrane removed, cut into 2-inch chunks', false),
  ('09b544b7-8294-416e-a192-837792483735', 18, 'Seafood', '1 lb red snapper fillets, skin on, cut into 3-inch pieces', 'red snapper fillets', 1, 'lb', 'skin on, cut into 3-inch pieces', false),
  ('09b544b7-8294-416e-a192-837792483735', 19, 'Seafood', '1 lb halibut fillet, or sea bass, cut into 2-inch chunks', 'halibut fillet', 1, 'lb', 'or sea bass, cut into 2-inch chunks', false),
  ('09b544b7-8294-416e-a192-837792483735', 20, 'Seafood', '1 lb mussels, scrubbed and debearded', 'mussels', 1, 'lb', 'scrubbed and debearded', false),
  ('09b544b7-8294-416e-a192-837792483735', 21, 'Rouille', '1 small russet potato, about 5 oz, peeled and cut into chunks', 'small russet potato', 1, null, 'about 5 oz, peeled and cut into chunks', false),
  ('09b544b7-8294-416e-a192-837792483735', 22, 'Rouille', '3 cloves garlic', 'garlic', 3, 'clove', null, false),
  ('09b544b7-8294-416e-a192-837792483735', 23, 'Rouille', '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
