values ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'steak-frites', 'steak-frites-75e198', 'Steak Frites', 'Seared rib eye (entrecôte, the most common bistro cut) with a quick shallot, red wine and butter pan sauce and crisp twice-fried frites — the Paris bistro classic for two.', 'french', 2, 45, 35, 80, 2, 'main', null, 0, array['stove', 'cast_iron', 'dutch_oven']::text[], array['entertaining', 'date-night']::text[], array['Bistros often serve steak rare (saignant, about 120°F) or medium-rare; both are below the USDA''s 145°F recommendation for whole cuts of beef.', 'Let the frying oil cool completely before straining and storing or discarding it.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['date_night', 'main', 'dinner', 'holiday', 'entertaining']::text[], array['fry', 'boil']::text[], array['fresh']::text[], array['date-night', 'valentines']::text[], null, 'traditional', 'steak-frites', 'classic', 'Best eaten right away. Refrigerate leftover steak up to 3 days; re-crisp frites on a rack at 400°F for 8 minutes.', null, 'owned', array['milk']::text[], array['beef']::text[], '{}'::text[], array['russet potato', 'eye steak', 'shallot', 'red wine', 'beef stock', 'parsley']::text[], 'beef stock|eye steak|parsley|red wine|russet potato|shallot',
  null, null, null, null, null, null, null, null)
