delete from public.recipe_ingredients where recipe_id = '75e198f7-7f0d-4fdd-97d2-9badc9dfaf18';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', 1, 'Frites', '1½ lb russet potatoes, cut into ¼-inch sticks', 'russet potatoes', 1.5, 'lb', 'cut into ¼-inch sticks', false),
  ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', 2, 'Frites', '2 quart vegetable oil, for frying', 'vegetable oil', 2, 'quart', 'for frying', false),
  ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', 3, 'Frites', '¾ tsp fine sea salt', 'fine sea salt', 0.75, 'tsp', null, false),
  ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', 4, 'Steak', '2 boneless rib eye steaks, about 1 inch thick, 10–12 oz each', 'boneless rib eye steaks', 2, null, 'about 1 inch thick, 10–12 oz each', false),
  ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', 5, 'Steak', '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', 6, 'Steak', '½ tsp black pepper, coarsely cracked', 'black pepper', 0.5, 'tsp', 'coarsely cracked', false),
  ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', 7, 'Steak', '1 tbsp vegetable oil', 'vegetable oil', 1, 'tbsp', null, false),
  ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', 8, 'Pan sauce', '3 tbsp unsalted butter, divided', 'unsalted butter', 3, 'tbsp', 'divided', false),
  ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', 9, 'Pan sauce', '1 shallot, finely chopped', 'shallot', 1, null, 'finely chopped', false),
  ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', 10, 'Pan sauce', '⅓ cup dry red wine', 'dry red wine', 0.33, 'cup', null, false),
  ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', 11, 'Pan sauce', '⅓ cup beef stock', 'beef stock', 0.33, 'cup', null, false),
  ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', 12, 'Pan sauce', '1 tbsp fresh parsley, chopped', 'fresh parsley', 1, 'tbsp', 'chopped', false);
delete from public.recipe_instructions where recipe_id = '75e198f7-7f0d-4fdd-97d2-9badc9dfaf18';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', 1, 'Frites', 'Rinse the potato sticks in cold water until it runs clear, then soak in fresh cold water 30 minutes. Drain and dry very well on towels. Meanwhile, take the steaks out of the fridge and season with the salt and pepper.', 1800, null, null),
  ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', 2, 'Frites', 'Heat the oil to 325°F in a heavy pot filled no more than halfway, with a thermometer clipped to the side. Keep children and pets away and never leave hot oil unattended. Fry the potatoes in 2 batches until soft and limp but still pale, 4–5 minutes per batch; drain on a rack.', 600, 162.8, null),
  ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', 3, 'Steak', 'Heat a cast-iron skillet over high heat until smoking, add the oil and lay in the steaks. Cook, turning every minute or so, until well browned and an instant-read thermometer reads 145°F in the thickest part, 7–9 minutes in all. Rest on a board 5 minutes.', 780, null, 62.8),
  ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', 4, 'Pan sauce', 'Pour the fat out of the skillet, lower the heat to medium and melt 1 tablespoon butter. Cook the shallot 1 minute, add the wine and stock and boil, scraping up the browned bits, until reduced by half, 3 minutes. Off the heat, swirl in the remaining butter and the parsley.', 240, null, null),
  ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', 5, 'Frites', 'While the steaks rest, heat the oil to 375°F and fry the potatoes again in batches until crisp and golden, 2–3 minutes. Drain and toss with the fine salt right away.', 300, 190.6, null),
  ('75e198f7-7f0d-4fdd-97d2-9badc9dfaf18', 6, null, 'Slice the steaks or serve them whole, spoon the pan sauce over and pile the frites alongside, with Dijon mustard and a green salad.', null, null, null);

-- Cheese Soufflé
