values ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'cheese-souffle', 'cheese-souffle-7972e7', 'Cheese Soufflé', 'A tall, golden Gruyère soufflé built on a mustard-spiked béchamel and lifted with whipped egg whites — bring it to the table the moment it leaves the oven.', 'french', 4, 30, 35, 65, 4, 'starter', null, 0, array['stove', 'oven', 'stand_mixer']::text[], array['vegetarian', 'entertaining']::text[], array['For individual soufflés, use four 8-ounce ramekins and bake 18–22 minutes.', 'Gruyère and Parmigiano-Reggiano are traditionally made with animal rennet; choose cheeses labelled vegetarian if that matters to you.']::text[], 'https://images.pexels.com/photos/5023040/pexels-photo-5023040.jpeg', 'Risen cheese soufflé in a ramekin with a whisk and cheese slices on a wooden table', 'Lucas Oliveira', 'https://www.pexels.com/@cais/', 'https://www.pexels.com/photo/souffle-on-ramekin-cup-5023040/', 'pexels', true, 'public', false,
  'pending_review', array['appetizer', 'holiday', 'entertaining']::text[], array['bake']::text[], array['spicy', 'savory']::text[], array['dinner-party']::text[], null, 'traditional', 'cheese-souffle', 'classic', 'A soufflé doesn''t keep — serve it straight from the oven.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['parmigiano-reggiano', 'milk', 'cayenne pepper', 'ground nutmeg', 'dijon mustard', 'egg yolk', 'egg white', 'cream tartar', 'gruyere cheese']::text[], 'cayenne pepper|cream tartar|dijon mustard|egg white|egg yolk|ground nutmeg|gruyere cheese|milk|parmigiano-reggiano',
  null, null, null, null, null, null, null, null)
