  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 1, null, '1 tbsp unsalted butter, softened, for the dish', 'unsalted butter', 1, 'tbsp', 'softened, for the dish', false),
  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 2, null, '2 tbsp Parmigiano-Reggiano, finely grated, for the dish', 'Parmigiano-Reggiano', 2, 'tbsp', 'finely grated, for the dish', false),
  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 3, null, '3 tbsp unsalted butter', 'unsalted butter', 3, 'tbsp', null, false),
  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 4, null, '3 tbsp all-purpose flour', 'all-purpose flour', 3, 'tbsp', null, false),
  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 5, null, '1 cup whole milk, warm', 'whole milk', 1, 'cup', 'warm', false),
  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 6, null, '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 7, null, '⅛ tsp cayenne pepper', 'cayenne pepper', 0.125, 'tsp', null, false),
  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 8, null, '⅛ tsp ground nutmeg', 'ground nutmeg', 0.125, 'tsp', null, false),
  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 9, null, '1 tsp Dijon mustard', 'Dijon mustard', 1, 'tsp', null, false),
  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 10, null, '4 large egg yolks', 'large egg yolks', 4, null, null, false),
  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 11, null, '5 large egg whites, at room temperature', 'large egg whites', 5, null, 'at room temperature', false),
  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 12, null, '¼ tsp cream of tartar', 'cream of tartar', 0.25, 'tsp', null, false),
  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 13, null, '4 oz Gruyère cheese, finely grated (about 1 cup)', 'Gruyère cheese', 4, 'oz', 'finely grated (about 1 cup)', false);
delete from public.recipe_instructions where recipe_id = '7972e708-81fc-4bcf-b1a9-1874d4ff5432';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 1, null, 'Set a rack in the lower third of the oven and heat to 400°F. Brush a 1½-quart soufflé dish with the softened butter using upward strokes, then coat with the Parmigiano, tipping out the excess.', null, 204.4, null),
  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 2, null, 'Melt the 3 tablespoons butter in a saucepan over medium heat, whisk in the flour and cook 1 minute without browning. Whisk in the warm milk and cook, whisking, until very thick, 2–3 minutes. Off the heat, whisk in the salt, cayenne, nutmeg and mustard, then the yolks one at a time.', 240, null, null),
  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 3, null, 'Beat the egg whites with the cream of tartar until they hold firm, glossy peaks that don''t slide in the bowl, 3–4 minutes.', 240, null, null),
  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 4, null, 'Stir a quarter of the whites into the warm base to loosen it, then stir in all but 2 tablespoons of the Gruyère. Gently fold in the remaining whites in two additions until no large white streaks remain.', null, null, null),
  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 5, null, 'Pour into the dish, smooth the top, sprinkle with the remaining cheese and run your thumb around the inside rim to make a shallow groove, which helps it rise straight. Put it in the oven and immediately lower the heat to 375°F.', null, 190.6, null),
  ('7972e708-81fc-4bcf-b1a9-1874d4ff5432', 6, null, 'Bake without opening the door for the first 20 minutes, until tall, deep golden and only slightly wobbly when nudged and the center reads 160°F, 30–35 minutes. Serve at once — it starts to sink within minutes.', 1920, 190.6, 71.1);

-- Béarnaise Sauce
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
