values ('0072c9d0-d620-464b-b882-e63de2ef223c', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'bearnaise-sauce', 'bearnaise-sauce-0072c9', 'Béarnaise Sauce', 'A warm, buttery emulsion of egg yolks and butter sharpened with a tarragon, shallot and white wine vinegar reduction — the classic sauce for steak.', 'french', 3, 15, 15, 30, 4, 'sauce', null, 0, array['stove']::text[], array['entertaining', 'vegetarian']::text[], array['If it splits, whisk 1 tablespoon hot water in a clean bowl and slowly whisk the broken sauce back into it.', 'Keep it warm for up to an hour in a thermos or in a bowl set over warm (not hot) water.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['sauce', 'entertaining']::text[], array['stew']::text[], array['tangy', 'fresh']::text[], '{}'::text[], null, 'traditional', 'bearnaise', 'classic', 'Best served within an hour. Leftovers keep 2 days in the fridge; rewarm very gently over warm water, whisking.', 'This recipe brings the yolks to 160°F before the butter goes in. If you don''t check with a thermometer, use pasteurized eggs for anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['egg', 'milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['wine vinegar', 'white wine', 'shallot', 'tarragon', 'black peppercorn', 'egg yolk']::text[], 'black peppercorn|egg yolk|shallot|tarragon|white wine|wine vinegar',
  null, null, null, null, null, null, null, null)
