insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('0072c9d0-d620-464b-b882-e63de2ef223c', 1, 'Reduction', '¼ cup white wine vinegar', 'white wine vinegar', 0.25, 'cup', null, false),
  ('0072c9d0-d620-464b-b882-e63de2ef223c', 2, 'Reduction', '¼ cup dry white wine', 'dry white wine', 0.25, 'cup', null, false),
  ('0072c9d0-d620-464b-b882-e63de2ef223c', 3, 'Reduction', '1 shallot, finely chopped', 'shallot', 1, null, 'finely chopped', false),
  ('0072c9d0-d620-464b-b882-e63de2ef223c', 4, 'Reduction', '2 tbsp fresh tarragon, leaves chopped, stems saved', 'fresh tarragon', 2, 'tbsp', 'leaves chopped, stems saved', false),
  ('0072c9d0-d620-464b-b882-e63de2ef223c', 5, 'Reduction', '¼ tsp black peppercorns, crushed', 'black peppercorns', 0.25, 'tsp', 'crushed', false),
  ('0072c9d0-d620-464b-b882-e63de2ef223c', 6, 'Sauce', '3 large egg yolks', 'large egg yolks', 3, null, null, false),
  ('0072c9d0-d620-464b-b882-e63de2ef223c', 7, 'Sauce', '1 tbsp water', 'water', 1, 'tbsp', null, false),
  ('0072c9d0-d620-464b-b882-e63de2ef223c', 8, 'Sauce', '12 tbsp unsalted butter, melted and kept warm (1½ sticks)', 'unsalted butter', 12, 'tbsp', 'melted and kept warm (1½ sticks)', false),
  ('0072c9d0-d620-464b-b882-e63de2ef223c', 9, 'Sauce', '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('0072c9d0-d620-464b-b882-e63de2ef223c', 10, 'Sauce', '1 tbsp fresh chervil or parsley, chopped', 'fresh chervil or parsley', 1, 'tbsp', 'chopped', true);
delete from public.recipe_instructions where recipe_id = '0072c9d0-d620-464b-b882-e63de2ef223c';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('0072c9d0-d620-464b-b882-e63de2ef223c', 1, 'Reduction', 'Simmer the vinegar, wine, shallot, tarragon stems and crushed peppercorns in a small saucepan until only about 2 tablespoons of liquid remain, 5–7 minutes. Strain, pressing on the solids, and cool slightly.', 360, null, null),
  ('0072c9d0-d620-464b-b882-e63de2ef223c', 2, 'Sauce', 'Bring an inch of water to a bare simmer in a saucepan. In a heatproof bowl that sits above (not in) the water, whisk the yolks with the reduction and the tablespoon of water.', null, null, null),
  ('0072c9d0-d620-464b-b882-e63de2ef223c', 3, 'Sauce', 'Whisk constantly over the simmering water until the yolks are thick, pale and foamy, leave a ribbon on the surface and read 160°F on an instant-read thermometer, 3–5 minutes. Lift the bowl off the heat for a few seconds whenever the edges start to set.', 240, null, 71.1),
  ('0072c9d0-d620-464b-b882-e63de2ef223c', 4, 'Sauce', 'Off the heat, whisk in the warm butter a few drops at first, then in a thin stream, until thick and glossy; leave the milky solids at the bottom of the butter pan behind.', null, null, null),
  ('0072c9d0-d620-464b-b882-e63de2ef223c', 5, 'Sauce', 'Stir in the chopped tarragon leaves, the salt and the chervil, if using. Taste, add a drop of vinegar if it needs sharpening, and serve warm with steak, fish, eggs or asparagus.', null, null, null);

-- Hollandaise Sauce
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
