values ('a2339759-5d10-46c1-a45a-cbfd277feee6', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'hollandaise-sauce', 'hollandaise-sauce-a23397', 'Hollandaise Sauce', 'Egg yolks and lemon whisked over gentle heat, then emulsified with hot melted butter into a smooth, tangy sauce for eggs Benedict, asparagus and fish.', 'french', 3, 10, 10, 20, 4, 'sauce', null, 0, array['stove']::text[], array['vegetarian', 'quick', 'brunch']::text[], array['Blender shortcut: tip the cooked yolk mixture from step 2 into a blender and drizzle in the hot butter with the motor running.', 'If it breaks, whisk a teaspoon of hot water in a clean bowl and slowly whisk the sauce back into it.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['sauce', 'holiday']::text[], array['stew']::text[], array['spicy', 'tangy']::text[], array['brunch-party']::text[], null, 'traditional', 'hollandaise', 'classic', 'Best served right away; it keeps warm up to 1 hour in a thermos. Leftovers keep 2 days in the fridge — rewarm gently over warm water, whisking.', 'This recipe brings the yolks to 160°F before the butter goes in. If you don''t check with a thermometer, use pasteurized eggs for anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['egg', 'milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['egg yolk', 'lemon juice', 'cayenne pepper']::text[], 'cayenne pepper|egg yolk|lemon juice',
  null, null, null, null, null, null, null, null)
