delete from public.recipe_ingredients where recipe_id = 'a2339759-5d10-46c1-a45a-cbfd277feee6';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('a2339759-5d10-46c1-a45a-cbfd277feee6', 1, null, '3 large egg yolks', 'large egg yolks', 3, null, null, false),
  ('a2339759-5d10-46c1-a45a-cbfd277feee6', 2, null, '1 tbsp lemon juice, plus more to taste', 'lemon juice', 1, 'tbsp', 'plus more to taste', false),
  ('a2339759-5d10-46c1-a45a-cbfd277feee6', 3, null, '1 tbsp water', 'water', 1, 'tbsp', null, false),
  ('a2339759-5d10-46c1-a45a-cbfd277feee6', 4, null, '10 tbsp unsalted butter, melted and hot', 'unsalted butter', 10, 'tbsp', 'melted and hot', false),
  ('a2339759-5d10-46c1-a45a-cbfd277feee6', 5, null, '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('a2339759-5d10-46c1-a45a-cbfd277feee6', 6, null, '1 pinch cayenne pepper', 'cayenne pepper', 1, 'pinch', null, false);
delete from public.recipe_instructions where recipe_id = 'a2339759-5d10-46c1-a45a-cbfd277feee6';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('a2339759-5d10-46c1-a45a-cbfd277feee6', 1, null, 'Bring an inch of water to a bare simmer in a saucepan and set a heatproof bowl over it, not touching the water.', null, null, null),
  ('a2339759-5d10-46c1-a45a-cbfd277feee6', 2, null, 'Whisk the yolks, lemon juice and water in the bowl, constantly, until thick and pale, they leave a trail and they read 160°F on an instant-read thermometer, 3–4 minutes. Lift the bowl off the heat for a few seconds whenever it looks close to scrambling.', 240, null, 71.1),
  ('a2339759-5d10-46c1-a45a-cbfd277feee6', 3, null, 'Off the heat, whisk in the hot butter a little at a time, then in a thin stream, until the sauce is thick and creamy.', null, null, null),
  ('a2339759-5d10-46c1-a45a-cbfd277feee6', 4, null, 'Whisk in the salt and cayenne, taste and add more lemon if you like. If it''s too thick, loosen with a teaspoon of warm water. Serve right away.', null, null, null);

-- Chocolate Soufflé
