values ('00a4181b-013b-4422-a061-b54f05114b0d', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chocolate-souffle', 'chocolate-souffle-00a418', 'Chocolate Soufflé', 'Individual dark chocolate soufflés that rise high above their ramekins with a light, airy middle, dusted with powdered sugar and served straight from the oven.', 'french', 4, 25, 20, 45, 4, 'dessert', 'plated', 0, array['stove', 'oven', 'stand_mixer']::text[], array['entertaining', 'date-night']::text[], array['Fill the ramekins up to 2 hours ahead and refrigerate them uncovered; bake straight from the fridge, adding 2–3 minutes.', 'Some bistros serve them with a soft, saucy center that hasn''t reached 160°F; if you do, use pasteurized eggs for anyone pregnant, very young, older or with a weakened immune system.']::text[], 'https://images.pexels.com/photos/3599974/pexels-photo-3599974.jpeg', 'Freshly risen chocolate soufflés in white ramekins', 'Sebastian Coman Photography', 'https://www.pexels.com/@sebastian-coman-photography-1598188/', 'https://www.pexels.com/photo/souffles-in-the-oven-3599974/', 'pexels', true, 'public', false,
  'pending_review', array['date_night', 'dessert', 'baking', 'holiday', 'entertaining']::text[], array['stew', 'bake']::text[], array['sweet']::text[], array['valentines', 'date-night', 'dinner-party']::text[], null, 'traditional', 'chocolate-souffle', 'classic', 'Serve straight from the oven; soufflés don''t keep.', null, 'owned', array['egg', 'milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['bittersweet chocolate', 'egg yolk', 'vanilla extract', 'egg white', 'cream tartar', 'powdered sugar']::text[], 'bittersweet chocolate|cream tartar|egg white|egg yolk|powdered sugar|vanilla extract',
  null, null, null, null, null, null, null, null)
