  ('00a4181b-013b-4422-a061-b54f05114b0d', 1, null, '1 tbsp unsalted butter, softened, for the ramekins', 'unsalted butter', 1, 'tbsp', 'softened, for the ramekins', false),
  ('00a4181b-013b-4422-a061-b54f05114b0d', 2, null, '2 tbsp sugar, for the ramekins', 'sugar', 2, 'tbsp', 'for the ramekins', false),
  ('00a4181b-013b-4422-a061-b54f05114b0d', 3, null, '4 oz bittersweet chocolate, 60–70% cacao, chopped', 'bittersweet chocolate', 4, 'oz', '60–70% cacao, chopped', false),
  ('00a4181b-013b-4422-a061-b54f05114b0d', 4, null, '3 tbsp unsalted butter', 'unsalted butter', 3, 'tbsp', null, false),
  ('00a4181b-013b-4422-a061-b54f05114b0d', 5, null, '3 large egg yolks', 'large egg yolks', 3, null, null, false),
  ('00a4181b-013b-4422-a061-b54f05114b0d', 6, null, '1 tsp vanilla extract', 'vanilla extract', 1, 'tsp', null, false),
  ('00a4181b-013b-4422-a061-b54f05114b0d', 7, null, '4 large egg whites, at room temperature', 'large egg whites', 4, null, 'at room temperature', false),
  ('00a4181b-013b-4422-a061-b54f05114b0d', 8, null, '¼ tsp cream of tartar', 'cream of tartar', 0.25, 'tsp', null, false),
  ('00a4181b-013b-4422-a061-b54f05114b0d', 9, null, '1 pinch kosher salt', 'kosher salt', 1, 'pinch', null, false),
  ('00a4181b-013b-4422-a061-b54f05114b0d', 10, null, '¼ cup sugar', 'sugar', 0.25, 'cup', null, false),
  ('00a4181b-013b-4422-a061-b54f05114b0d', 11, null, '1 tbsp powdered sugar, to dust', 'powdered sugar', 1, 'tbsp', 'to dust', false);
delete from public.recipe_instructions where recipe_id = '00a4181b-013b-4422-a061-b54f05114b0d';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('00a4181b-013b-4422-a061-b54f05114b0d', 1, null, 'Heat the oven to 375°F with a rack in the lower third. Brush four 8-ounce ramekins with the softened butter in upward strokes, coat with the 2 tablespoons sugar, tap out the excess and set them on a sheet pan.', null, 190.6, null),
  ('00a4181b-013b-4422-a061-b54f05114b0d', 2, null, 'Melt the chocolate and 3 tablespoons butter in a heatproof bowl over barely simmering water, stirring, until smooth, 3–4 minutes. Cool 5 minutes, then whisk in the yolks one at a time and the vanilla.', 540, null, null),
  ('00a4181b-013b-4422-a061-b54f05114b0d', 3, null, 'Beat the whites with the cream of tartar and salt until foamy, then gradually add the ¼ cup sugar and beat to firm, glossy peaks, 3–4 minutes.', 240, null, null),
  ('00a4181b-013b-4422-a061-b54f05114b0d', 4, null, 'Stir a quarter of the whites into the chocolate to lighten it, then gently fold in the rest until just combined.', null, null, null),
  ('00a4181b-013b-4422-a061-b54f05114b0d', 5, null, 'Divide among the ramekins, level the tops and run your thumb around the inside rim of each. Bake until well risen with a slightly cracked top and the centers read 160°F, 14–16 minutes.', 900, 190.6, 71.1),
  ('00a4181b-013b-4422-a061-b54f05114b0d', 6, null, 'Dust with powdered sugar and serve at once, with whipped cream or vanilla ice cream if you like.', null, null, null);

-- Tarte Tatin
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
