values ('6a0e7e66-a7ee-43ac-9b5a-e189ea6de77f', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'tarte-tatin', 'tarte-tatin-6a0e7e', 'Tarte Tatin', 'Apples cooked slowly in butter and caramel in a skillet, baked under a pastry lid and turned out upside down; it''s made with shortcrust or puff pastry, and we use store-bought all-butter puff pastry.', 'french', 3, 30, 75, 105, 8, 'dessert', 'pastries', 0, array['stove', 'oven', 'cast_iron']::text[], array['entertaining', 'comfort']::text[], array['Choose apples that hold their shape; soft varieties like McIntosh turn to mush.', 'If the tarte cools too long and sticks, warm the skillet over low heat for 2 minutes before flipping.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['baking', 'dessert', 'holiday', 'comfort', 'entertaining']::text[], array['bake']::text[], array['tangy', 'rich', 'sweet']::text[], array['dinner-party', 'thanksgiving']::text[], null, 'traditional', 'tarte-tatin', 'classic', 'Best the day it''s made. Refrigerate leftovers, covered, up to 2 days and rewarm at 350°F for 10 minutes.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['apple', 'lemon juice', 'puff pastry']::text[], 'apple|lemon juice|puff pastry',
  null, null, null, null, null, null, null, null)
