insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('6a0e7e66-a7ee-43ac-9b5a-e189ea6de77f', 1, null, '3½ lb firm apples, such as Honeycrisp, Braeburn or Granny Smith (about 7)', 'firm apples', 3.5, 'lb', 'such as Honeycrisp, Braeburn or Granny Smith (about 7)', false),
  ('6a0e7e66-a7ee-43ac-9b5a-e189ea6de77f', 2, null, '1 tbsp lemon juice', 'lemon juice', 1, 'tbsp', null, false),
  ('6a0e7e66-a7ee-43ac-9b5a-e189ea6de77f', 3, null, '6 tbsp unsalted butter', 'unsalted butter', 6, 'tbsp', null, false),
  ('6a0e7e66-a7ee-43ac-9b5a-e189ea6de77f', 4, null, '¾ cup sugar', 'sugar', 0.75, 'cup', null, false),
  ('6a0e7e66-a7ee-43ac-9b5a-e189ea6de77f', 5, null, '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('6a0e7e66-a7ee-43ac-9b5a-e189ea6de77f', 6, null, '8 oz all-butter puff pastry, 1 sheet, thawed in the fridge', 'all-butter puff pastry', 8, 'oz', '1 sheet, thawed in the fridge', false),
  ('6a0e7e66-a7ee-43ac-9b5a-e189ea6de77f', 7, null, '1 tbsp all-purpose flour, for rolling', 'all-purpose flour', 1, 'tbsp', 'for rolling', false),
  ('6a0e7e66-a7ee-43ac-9b5a-e189ea6de77f', 8, null, '1 cup crème fraîche, to serve', 'crème fraîche', 1, 'cup', 'to serve', true);
delete from public.recipe_instructions where recipe_id = '6a0e7e66-a7ee-43ac-9b5a-e189ea6de77f';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('6a0e7e66-a7ee-43ac-9b5a-e189ea6de77f', 1, null, 'Peel, core and quarter the apples and toss with the lemon juice. Heat the oven to 375°F.', null, 190.6, null),
  ('6a0e7e66-a7ee-43ac-9b5a-e189ea6de77f', 2, null, 'Melt the butter in a 10-inch cast-iron or other ovenproof skillet over medium heat. Sprinkle in the sugar and salt and cook, swirling the pan, until it turns a light amber caramel, 5–8 minutes. Take care — caramel is extremely hot.', 420, null, null),
  ('6a0e7e66-a7ee-43ac-9b5a-e189ea6de77f', 3, null, 'Off the heat, stand the apple quarters on their sides in tight circles, packing them in (they shrink). Return to medium-low heat and cook, basting with the juices now and then, until the caramel bubbles up thickly and the apples are golden and half-tender, 20–25 minutes.', 1320, null, null),
  ('6a0e7e66-a7ee-43ac-9b5a-e189ea6de77f', 4, null, 'Meanwhile, roll the pastry on a floured counter into an 11-inch round, prick it all over with a fork and chill until needed.', null, null, null),
  ('6a0e7e66-a7ee-43ac-9b5a-e189ea6de77f', 5, null, 'Lay the pastry over the apples and tuck the edges down inside the pan. Cut 3 small slits in the top. Bake until the pastry is puffed and deep golden, 30–35 minutes.', 1920, 190.6, null),
  ('6a0e7e66-a7ee-43ac-9b5a-e189ea6de77f', 6, null, 'Cool in the pan 10 minutes. Set a large plate over the skillet and, wearing oven mitts and holding both firmly, flip it over in one confident move. Put back any apples that stick and serve warm with crème fraîche.', 600, null, null);

