values ('224fd026-759c-47e9-9167-fdf9cb65333e', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'paella-valenciana', 'paella-valenciana-224fd0', 'Paella Valenciana', 'The original Valencian paella of chicken, rabbit, flat green beans and lima beans in saffron rice, cooked in a wide, shallow pan until a crisp socarrat forms on the bottom.', 'spanish', 3, 25, 75, 100, 6, 'main', null, 0, array['stove']::text[], array['entertaining']::text[], array['Rabbit is sold frozen at many butchers and some supermarkets; if you can''t find it, use 3½ lb chicken in total.', 'Bomba rice soaks up lots of liquid without going mushy; if you use Arborio instead, use ½ cup less water and watch it closely.']::text[], 'https://images.pexels.com/photos/24906297/pexels-photo-24906297.jpeg', 'Valencian paella with chicken, green beans and butter beans in a wide pan, seen from above', 'Wijs (Wise)', 'https://www.pexels.com/@wijs-wise-136435282/', 'https://www.pexels.com/photo/top-view-of-paella-24906297/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner', 'grilling', 'holiday', 'entertaining']::text[], array['grill', 'stew', 'boil']::text[], '{}'::text[], array['dinner-party']::text[], 'Valencia', 'traditional', 'paella-valenciana', 'classic', 'Best eaten right away. Refrigerate leftovers up to 3 days and reheat in a skillet with a splash of water.', null, 'owned', '{}'::text[], array['chicken', 'rabbit', 'beans']::text[], array['gluten_free', 'dairy_free']::text[], array['thigh drumstick', 'rabbit', 'green bean', 'lima bean', 'tomato', 'sweet paprika', 'saffron thread', 'bomba rice', 'rosemary']::text[], 'bomba rice|green bean|lima bean|rabbit|rosemary|saffron thread|sweet paprika|thigh drumstick|tomato',
  null, null, null, null, null, null, null, null)
