insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('224fd026-759c-47e9-9167-fdf9cb65333e', 1, null, 'Set a 15- to 16-inch paella pan over your largest burner or straddle two burners (an outdoor grill or paella burner gives the most even heat). Heat the oil over medium-high, season the chicken and rabbit with 1 tsp salt and brown slowly on all sides until deep golden, 15–20 minutes.', 1080, null, null),
  ('224fd026-759c-47e9-9167-fdf9cb65333e', 2, null, 'Push the meat to the edges, add the green beans and lima beans to the center and cook, stirring, 4 minutes. Add the grated tomato and cook until it darkens and thickens, 3 minutes, then stir in the paprika for a few seconds — don''t let it burn.', 420, null, null),
  ('224fd026-759c-47e9-9167-fdf9cb65333e', 3, null, 'Pour in the water, add the saffron and the remaining salt and bring to a boil. Simmer uncovered 20 minutes so the broth takes on the flavour of the meat; taste — it should be well seasoned, almost salty. If it reduces a lot, top it back up to where it started.', 1200, null, null),
  ('224fd026-759c-47e9-9167-fdf9cb65333e', 4, null, 'Scatter the rice evenly across the pan and nudge it under the liquid with a spoon. From now on, don''t stir. Boil hard 10 minutes, rotating the pan over the heat so it cooks evenly.', 600, null, null),
  ('224fd026-759c-47e9-9167-fdf9cb65333e', 5, null, 'Lower to a steady simmer, lay the rosemary on top and cook until the rice is just tender and the liquid has been absorbed, 8–10 minutes; the chicken will be well past 165°F.', 540, null, 73.9),
  ('224fd026-759c-47e9-9167-fdf9cb65333e', 6, null, 'For the socarrat, raise the heat for 1–2 minutes until you hear crackling and smell toasting rice (not burning). Take off the heat, cover with a clean towel and rest 5 minutes, then serve from the pan.', 420, null, null);

-- Crema Catalana
