values ('a3eb9538-d41e-4e55-a091-f88784523d10', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'crema-catalana', 'crema-catalana-a3eb95', 'Crema Catalana', 'A silky lemon- and cinnamon-scented custard thickened on the stove and finished with a crackly burnt-sugar top — Catalonia''s cousin of crème brûlée.', 'spanish', 2, 15, 30, 285, 6, 'dessert', 'plated', 240, array['stove']::text[], array['make-ahead', 'entertaining']::text[], array['In Catalonia it''s eaten on St Joseph''s Day, March 19, and the sugar is traditionally burned with a hot iron disc; a kitchen torch does the same job.']::text[], 'https://images.unsplash.com/photo-1615235739538-95040f341ba8', 'Custard with a caramelised sugar crust in a white ceramic dish', 'Max Griss', 'https://unsplash.com/@grissphoto', 'https://unsplash.com/photos/white-ceramic-bowl-with-brown-soup-Wp7ZsJYWP0M', 'unsplash', true, 'public', false,
  'pending_review', array['dessert', 'holiday', 'entertaining']::text[], array['steam', 'boil']::text[], array['tangy', 'aromatic', 'sweet']::text[], array['dinner-party']::text[], 'Catalonia', 'traditional', 'crema-catalana', 'classic', 'Keep the chilled custards covered up to 3 days; caramelize just before serving.', null, 'owned', array['egg', 'milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['milk', 'lemon', 'cinnamon stick', 'egg yolk', 'cornstarch']::text[], 'cinnamon stick|cornstarch|egg yolk|lemon|milk',
  null, null, null, null, null, null, null, null)
