delete from public.recipe_ingredients where recipe_id = 'a3eb9538-d41e-4e55-a091-f88784523d10';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('a3eb9538-d41e-4e55-a091-f88784523d10', 1, null, '3 cups whole milk, divided', 'whole milk', 3, 'cup', 'divided', false),
  ('a3eb9538-d41e-4e55-a091-f88784523d10', 2, null, '1 lemon, peel only, in wide strips without the white pith', 'lemon', 1, null, 'peel only, in wide strips without the white pith', false),
  ('a3eb9538-d41e-4e55-a091-f88784523d10', 3, null, '1 cinnamon stick', 'cinnamon stick', 1, null, null, false),
  ('a3eb9538-d41e-4e55-a091-f88784523d10', 4, null, '6 large egg yolks', 'large egg yolks', 6, null, null, false),
  ('a3eb9538-d41e-4e55-a091-f88784523d10', 5, null, '½ cup sugar', 'sugar', 0.5, 'cup', null, false),
  ('a3eb9538-d41e-4e55-a091-f88784523d10', 6, null, '3 tbsp cornstarch', 'cornstarch', 3, 'tbsp', null, false),
  ('a3eb9538-d41e-4e55-a091-f88784523d10', 7, null, '6 tbsp sugar, for the topping', 'sugar', 6, 'tbsp', 'for the topping', false);
delete from public.recipe_instructions where recipe_id = 'a3eb9538-d41e-4e55-a091-f88784523d10';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('a3eb9538-d41e-4e55-a091-f88784523d10', 1, null, 'Warm 2½ cups of the milk with the lemon peel and cinnamon stick until steaming, then cover and steep off the heat 15 minutes.', 1200, null, null),
  ('a3eb9538-d41e-4e55-a091-f88784523d10', 2, null, 'Whisk the yolks and ½ cup sugar until pale, then whisk in the cornstarch and the remaining ½ cup cold milk until smooth.', null, null, null),
  ('a3eb9538-d41e-4e55-a091-f88784523d10', 3, null, 'Remove the peel and cinnamon from the warm milk and slowly whisk the milk into the yolk mixture. Pour it all back into the pan.', null, null, null),
  ('a3eb9538-d41e-4e55-a091-f88784523d10', 4, null, 'Cook over medium-low heat, stirring constantly and reaching into the corners, until it thickens to a soft pudding and bubbles once or twice, 6–8 minutes (well past 160°F). Don''t let it boil hard.', 420, null, 71.1),
  ('a3eb9538-d41e-4e55-a091-f88784523d10', 5, null, 'Divide among six shallow 5- to 6-ounce dishes, cool, then cover and chill until cold, at least 4 hours.', 14400, null, null),
  ('a3eb9538-d41e-4e55-a091-f88784523d10', 6, null, 'Just before serving, sprinkle each with 1 tablespoon sugar and caramelize with a kitchen torch until deep amber, or under a very hot broiler for 2–3 minutes, watching closely. Serve within 15 minutes, while the top is crisp.', null, null, null);

-- Bacalhau à Brás
