values ('4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'bacalhau-a-bras', 'bacalhau-a-bras-4ae5b8', 'Bacalhau à Brás', 'Flakes of salt cod tossed with slow-cooked onions, crisp matchstick potatoes and softly set eggs, finished with parsley and black olives — a Lisbon tavern favourite.', 'portuguese', 3, 40, 35, 1515, 4, 'main', null, 1440, array['stove', 'dutch_oven']::text[], array['comfort']::text[], array['Short on time? Plain store-bought shoestring potato sticks are what many Lisbon home cooks use; fold them in just before the eggs.', 'Salt cod is sold at Portuguese, Spanish, Italian and Caribbean groceries and at many supermarket fish counters.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'comfort']::text[], array['stew', 'fry', 'poach']::text[], array['fresh']::text[], '{}'::text[], 'Lisbon', 'traditional', 'bacalhau-a-bras', 'classic', 'Best eaten right away; the potatoes soften as it stands. Refrigerate leftovers up to 2 days and reheat gently.', 'The eggs here aren''t cooked to 160°F. Use pasteurized eggs if you''re serving anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['egg', 'fish']::text[], array['fish']::text[], array['pescatarian', 'gluten_free', 'dairy_free']::text[], array['salt cod', 'russet potato', 'yellow onion', 'garlic', 'bay leaf', 'egg', 'parsley', 'black olive']::text[], 'bay leaf|black olive|egg|garlic|parsley|russet potato|salt cod|yellow onion',
  null, null, null, null, null, null, null, null)
