insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90', 1, 'Cod', '1 lb salt cod, boneless, skinless', 'salt cod', 1, 'lb', 'boneless, skinless', false),
  ('4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90', 2, 'Potatoes', '1½ lb russet potatoes, peeled and cut into very thin matchsticks', 'russet potatoes', 1.5, 'lb', 'peeled and cut into very thin matchsticks', false),
  ('4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90', 3, 'Potatoes', '2 quart vegetable oil, for frying', 'vegetable oil', 2, 'quart', 'for frying', false),
  ('4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90', 4, 'Finish', '⅓ cup olive oil', 'olive oil', 0.33, 'cup', null, false),
  ('4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90', 5, 'Finish', '2 yellow onions, halved and thinly sliced', 'yellow onions', 2, null, 'halved and thinly sliced', false),
  ('4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90', 6, 'Finish', '3 cloves garlic, thinly sliced', 'garlic', 3, 'clove', 'thinly sliced', false),
  ('4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90', 7, 'Finish', '1 bay leaf', 'bay leaf', 1, null, null, false),
  ('4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90', 8, 'Finish', '6 large eggs', 'large eggs', 6, null, null, false),
  ('4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90', 9, 'Finish', '¼ tsp black pepper', 'black pepper', 0.25, 'tsp', null, false),
  ('4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90', 10, 'Finish', '3 tbsp fresh parsley, chopped', 'fresh parsley', 3, 'tbsp', 'chopped', false),
  ('4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90', 11, 'Finish', '⅓ cup black olives, pitted', 'black olives', 0.33, 'cup', 'pitted', false);
delete from public.recipe_instructions where recipe_id = '4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90', 1, 'Cod', 'Rinse the salt cod, then soak it in a large bowl of cold water in the fridge for 24–36 hours, changing the water 3 or 4 times. Taste a flake: it should be pleasantly seasoned, not harsh.', 86400, null, null),
  ('4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90', 2, 'Cod', 'Put the cod in a saucepan, cover with fresh water and bring to a gentle simmer. Poach until it flakes easily and reads 145°F, about 5 minutes. Drain, cool slightly and shred into fine flakes, removing any bones or skin.', 480, null, 62.8),
  ('4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90', 3, 'Potatoes', 'Rinse the potato matchsticks in cold water and dry very thoroughly. Heat the oil to 350°F in a heavy pot filled no more than halfway, with a thermometer clipped to the side; keep children and pets away and never leave hot oil unattended. Fry in batches until golden and crisp, 3–4 minutes per batch, and drain on paper towels.', 720, 176.7, null),
  ('4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90', 4, 'Finish', 'Warm the olive oil in a large skillet over medium-low heat. Cook the onions, garlic and bay slowly until soft, sweet and pale gold, 15 minutes. Add the cod and stir for 3 minutes so it soaks up the oil.', 1080, null, null),
  ('4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90', 5, 'Finish', 'Beat the eggs with the pepper. Discard the bay leaf, fold the fried potatoes into the pan, then pour in the eggs. Stir gently over low heat just until the eggs are softly set and creamy, 1–2 minutes.', 120, null, null),
  ('4ae5b8c6-47ec-47c3-a98c-6f3ac4838e90', 6, 'Finish', 'Off the heat, stir in most of the parsley. Taste for salt (the cod may be enough), scatter with the olives and remaining parsley and serve right away.', null, null, null);

-- Pastéis de Nata
