values ('ddd7a053-af3a-46bd-824c-6fba3ce6851e', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'pasteis-de-nata', 'pasteis-de-nata-ddd7a0', 'Pastéis de Nata', 'Crisp, flaky pastry cups filled with a lemon- and cinnamon-scented custard and baked very hot until blistered on top; we roll store-bought puff pastry into spirals instead of making the laminated dough from scratch.', 'portuguese', 3, 40, 35, 105, 12, 'dessert', 'pastries', 30, array['stove', 'oven']::text[], array['entertaining']::text[], array['Home ovens can''t match a Lisbon bakery''s fierce heat, so the blistering varies; for more colour, broil for the last 1–2 minutes, watching constantly.']::text[], 'https://images.pexels.com/photos/7595396/pexels-photo-7595396.jpeg', 'Portuguese custard tarts dusted with cinnamon on a white plate', 'Recep Tayyip Çelik', 'https://www.pexels.com/@receptcelik/', 'https://www.pexels.com/photo/baked-tarts-on-a-white-plate-7595396/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'dessert', 'holiday', 'entertaining']::text[], array['steam', 'bake', 'boil']::text[], array['tangy', 'aromatic', 'sweet']::text[], array['brunch-party']::text[], 'Lisbon', 'adapted', 'pasteis-de-nata', 'classic', 'Best the day they''re baked. Keep at room temperature up to 1 day or refrigerate up to 3 days; re-crisp at 400°F for 5 minutes.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['puff pastry', 'cinnamon stick', 'lemon', 'milk', 'egg yolk', 'vanilla extract', 'ground cinnamon']::text[], 'cinnamon stick|egg yolk|ground cinnamon|lemon|milk|puff pastry|vanilla extract',
  null, null, null, null, null, null, null, null)
