insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('ddd7a053-af3a-46bd-824c-6fba3ce6851e', 1, 'Pastry', '1 lb all-butter puff pastry, 2 sheets, thawed in the fridge', 'all-butter puff pastry', 1, 'lb', '2 sheets, thawed in the fridge', false),
  ('ddd7a053-af3a-46bd-824c-6fba3ce6851e', 2, 'Pastry', '2 tbsp all-purpose flour, for rolling', 'all-purpose flour', 2, 'tbsp', 'for rolling', false),
  ('ddd7a053-af3a-46bd-824c-6fba3ce6851e', 3, 'Pastry', '1 tbsp unsalted butter, softened, for the tin', 'unsalted butter', 1, 'tbsp', 'softened, for the tin', false),
  ('ddd7a053-af3a-46bd-824c-6fba3ce6851e', 4, 'Syrup', '1 cup sugar', 'sugar', 1, 'cup', null, false),
  ('ddd7a053-af3a-46bd-824c-6fba3ce6851e', 5, 'Syrup', '½ cup water', 'water', 0.5, 'cup', null, false),
  ('ddd7a053-af3a-46bd-824c-6fba3ce6851e', 6, 'Syrup', '1 cinnamon stick', 'cinnamon stick', 1, null, null, false),
  ('ddd7a053-af3a-46bd-824c-6fba3ce6851e', 7, 'Syrup', '1 lemon, peel only, in 2 wide strips', 'lemon', 1, null, 'peel only, in 2 wide strips', false),
  ('ddd7a053-af3a-46bd-824c-6fba3ce6851e', 8, 'Custard', '3 tbsp all-purpose flour', 'all-purpose flour', 3, 'tbsp', null, false),
