delete from public.recipe_instructions where recipe_id = 'ddd7a053-af3a-46bd-824c-6fba3ce6851e';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('ddd7a053-af3a-46bd-824c-6fba3ce6851e', 1, 'Pastry', 'Lay one pastry sheet on a lightly floured counter, brush lightly with water and lay the second sheet on top. Roll up tightly from a short side into a log, wrap and chill 30 minutes.', 1800, null, null),
  ('ddd7a053-af3a-46bd-824c-6fba3ce6851e', 2, 'Syrup', 'Bring the sugar, water, cinnamon stick and lemon peel to a boil and boil without stirring until slightly syrupy (220°F on a candy thermometer), about 4 minutes. Discard the cinnamon and peel and let the syrup cool slightly.', 240, null, null),
  ('ddd7a053-af3a-46bd-824c-6fba3ce6851e', 3, 'Custard', 'Whisk the flour with ¼ cup of the milk until smooth. Heat the remaining milk until steaming, whisk in the flour mixture and cook, whisking, until thickened like heavy cream, 2 minutes. Whisk in the warm syrup in a thin stream, cool 10 minutes, then whisk in the yolks and vanilla. Strain into a jug.', 720, null, null),
  ('ddd7a053-af3a-46bd-824c-6fba3ce6851e', 4, 'Pastry', 'Heat the oven to 500°F (or as hot as it goes) with a rack in the upper third. Butter a standard 12-cup muffin tin. Cut the pastry log into 12 rounds about ¾ inch thick.', null, 260, null),
  ('ddd7a053-af3a-46bd-824c-6fba3ce6851e', 5, 'Pastry', 'Set a round cut-side up in each cup. With wet thumbs, press it from the center outward and up the sides until the pastry is thin at the bottom and rises just above the rim.', null, null, null),
  ('ddd7a053-af3a-46bd-824c-6fba3ce6851e', 6, null, 'Fill each cup about three-quarters full with custard. Bake until the pastry is deep golden and the custard is puffed with dark, blistered spots, 12–16 minutes; it will be far past 160°F.', 840, 260, 71.1),
  ('ddd7a053-af3a-46bd-824c-6fba3ce6851e', 7, null, 'Cool in the tin 5 minutes, then lift out onto a rack. Serve warm or at room temperature, dusted with cinnamon.', 300, null, null);

-- Moussaka
