values ('bf4f8916-91d0-42b5-b185-1cef46b9d2ac', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'moussaka', 'moussaka-bf4f89', 'Moussaka', 'Layers of tender eggplant and potato, a cinnamon-spiced lamb and tomato sauce and a thick, golden béchamel; we roast the eggplant instead of frying it, as many Greek home cooks now do.', 'greek', 3, 45, 130, 175, 8, 'main', null, 0, array['stove', 'oven']::text[], array['comfort', 'make-ahead', 'entertaining', 'freezer-friendly']::text[], array['Kefalotyri is a salty Greek sheep''s-milk cheese sold at Greek and Mediterranean shops; Pecorino Romano or Parmigiano-Reggiano are good substitutes.', 'Assemble it a day ahead and refrigerate; bake from cold, adding 15–20 minutes.']::text[], 'https://images.unsplash.com/photo-1777199311086-ec5ff230aefd', 'Portion of Greek moussaka with minced meat and creamy béchamel', 'Arne Buss', 'https://unsplash.com/@arnedaman', 'https://unsplash.com/photos/baked-dish-with-cheese-and-bread-garnish-ZYFdlqvNWFg', 'unsplash', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner', 'holiday', 'entertaining']::text[], array['roast', 'stew', 'pan_fry', 'bake']::text[], array['fresh', 'savory', 'aromatic']::text[], array['dinner-party']::text[], null, 'adapted', 'moussaka', 'classic', 'Refrigerate up to 4 days or freeze in portions up to 3 months. Reheat covered at 350°F until hot in the center.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], array['lamb']::text[], '{}'::text[], array['eggplant', 'russet potato', 'ground lamb', 'yellow onion', 'garlic', 'tomato paste', 'red wine', 'tomato', 'cinnamon stick', 'ground allspice', 'dried oregano', 'bay leaf', 'parsley', 'milk', 'ground nutmeg', 'egg yolk', 'kefalotyri cheese']::text[], 'bay leaf|cinnamon stick|dried oregano|egg yolk|eggplant|garlic|ground allspice|ground lamb|ground nutmeg|kefalotyri cheese|milk|parsley|red wine|russet potato|tomato|tomato paste|yellow onion',
