delete from public.recipe_instructions where recipe_id = 'bf4f8916-91d0-42b5-b185-1cef46b9d2ac';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('bf4f8916-91d0-42b5-b185-1cef46b9d2ac', 1, 'Vegetables', 'Heat the oven to 425°F. Toss the eggplant and potato slices with the oil and salt and spread on three sheet pans (or roast in batches). Roast, flipping once, until the eggplant is golden and soft and the potatoes are just tender, 25–30 minutes.', 1680, 218.3, null),
  ('bf4f8916-91d0-42b5-b185-1cef46b9d2ac', 2, 'Meat sauce', 'Meanwhile, heat the oil in a large deep skillet over medium-high heat and brown the lamb, breaking it up, until no pink remains and it reaches 160°F, 8–10 minutes. Spoon off the excess fat.', 540, null, 71.1),
  ('bf4f8916-91d0-42b5-b185-1cef46b9d2ac', 3, 'Meat sauce', 'Add the onion and cook until soft, 6 minutes; stir in the garlic and tomato paste for 1 minute. Pour in the wine and let it bubble, then add the tomatoes, cinnamon, allspice, oregano, bay and salt. Simmer uncovered, stirring now and then, until thick and not watery, 25–30 minutes. Remove the cinnamon stick and bay and stir in the parsley.', 2100, null, null),
  ('bf4f8916-91d0-42b5-b185-1cef46b9d2ac', 4, 'Béchamel', 'Melt the butter in a saucepan, whisk in the flour and cook 2 minutes. Gradually whisk in the warm milk and simmer, whisking, until very thick, 8 minutes. Off the heat, whisk in the nutmeg, salt and half the cheese, cool 5 minutes, then whisk in the yolks.', 900, null, null),
  ('bf4f8916-91d0-42b5-b185-1cef46b9d2ac', 5, null, 'Lower the oven to 350°F. In a deep 9-by-13-inch baking dish, layer the potatoes, half the eggplant, all the meat sauce, then the remaining eggplant. Pour the béchamel over, smooth it to the edges and sprinkle with the remaining cheese.', null, 176.7, null),
  ('bf4f8916-91d0-42b5-b185-1cef46b9d2ac', 6, null, 'Set the dish on a sheet pan and bake until the top is puffed and deep golden and the center reads 160°F, 45–55 minutes.', 3000, 176.7, 71.1),
  ('bf4f8916-91d0-42b5-b185-1cef46b9d2ac', 7, null, 'Rest at least 30 minutes before cutting so the layers set and slice cleanly.', 1800, null, null);

-- Spanakopita
