values ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'spanakopita', 'spanakopita-fe9c8d', 'Spanakopita', 'A big, flaky phyllo pie filled with spinach, feta, scallions and dill — the family-size pan pie most Greek homes make, rather than the small party triangles.', 'greek', 3, 40, 65, 105, 8, 'main', null, 0, array['stove', 'oven']::text[], array['vegetarian', 'make-ahead', 'entertaining']::text[], array['Phyllo cracks when it dries out: work quickly, keep it covered, and don''t worry about tears — they disappear between the layers.', 'Feta is sometimes made with animal rennet; choose one labelled vegetarian if that matters to you.']::text[], 'https://images.pexels.com/photos/18884737/pexels-photo-18884737.jpeg', 'Slices of spinach and feta spanakopita in flaky filo on parchment paper', 'Valeria Boltneva', 'https://www.pexels.com/@valeriya/', 'https://www.pexels.com/photo/spanakopita-savory-pastry-with-spinach-18884737/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'main', 'dinner', 'holiday', 'entertaining']::text[], array['bake']::text[], array['fresh']::text[], array['picnic', 'easter']::text[], null, 'traditional', 'spanakopita', 'classic', 'Keep at room temperature up to 4 hours or refrigerate up to 4 days; re-crisp slices at 350°F. Freeze unbaked up to 2 months and bake from frozen, adding 15 minutes.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['spinach', 'yellow onion', 'scallion', 'dill', 'parsley', 'feta cheese', 'egg', 'ground nutmeg', 'phyllo dough']::text[], 'dill|egg|feta cheese|ground nutmeg|parsley|phyllo dough|scallion|spinach|yellow onion',
  null, null, null, null, null, null, null, null)
