insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 1, 'Filling', '2 lb fresh spinach, washed and roughly chopped, or 20 oz frozen chopped spinach, thawed', 'fresh spinach', 2, 'lb', 'washed and roughly chopped, or 20 oz frozen chopped spinach, thawed', false),
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 2, 'Filling', '2 tbsp olive oil', 'olive oil', 2, 'tbsp', null, false),
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 3, 'Filling', '1 yellow onion, finely chopped', 'yellow onion', 1, null, 'finely chopped', false),
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 4, 'Filling', '1 bunch scallions, sliced', 'scallions', 1, 'bunch', 'sliced', false),
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 5, 'Filling', '½ cup fresh dill, chopped', 'fresh dill', 0.5, 'cup', 'chopped', false),
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 6, 'Filling', '¼ cup fresh parsley, chopped', 'fresh parsley', 0.25, 'cup', 'chopped', false),
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 7, 'Filling', '12 oz feta cheese, crumbled', 'feta cheese', 12, 'oz', 'crumbled', false),
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 8, 'Filling', '3 large eggs, beaten', 'large eggs', 3, null, 'beaten', false),
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 9, 'Filling', '½ tsp black pepper', 'black pepper', 0.5, 'tsp', null, false),
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 10, 'Filling', '¼ tsp ground nutmeg', 'ground nutmeg', 0.25, 'tsp', null, false),
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 11, 'Pastry', '1 lb phyllo dough, thawed in the fridge overnight', 'phyllo dough', 1, 'lb', 'thawed in the fridge overnight', false),
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 12, 'Pastry', '½ cup olive oil', 'olive oil', 0.5, 'cup', null, false),
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 13, 'Pastry', '4 tbsp unsalted butter, melted', 'unsalted butter', 4, 'tbsp', 'melted', false);
delete from public.recipe_instructions where recipe_id = 'fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 1, 'Filling', 'If using fresh spinach, wilt it in batches in a large pot with a splash of water, 2–3 minutes per batch. Cool, then squeeze out as much liquid as you can with your hands or a clean towel (do the same with thawed frozen spinach).', 600, null, null),
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 2, 'Filling', 'Warm the olive oil in a skillet and cook the onion and scallions until soft, 6 minutes. Cool slightly, then mix with the spinach, dill, parsley, feta, eggs, pepper and nutmeg. Taste before adding salt — feta is salty.', 360, null, null),
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 3, 'Pastry', 'Heat the oven to 375°F. Mix the olive oil and melted butter. Unroll the phyllo and keep it covered with a damp towel as you work so it doesn''t dry out.', null, 190.6, null),
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 4, 'Pastry', 'Brush a 9-by-13-inch baking dish with the oil mixture. Lay in a phyllo sheet, letting any excess hang over the sides, and brush it lightly with oil. Repeat with half the sheets.', null, null, null),
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 5, null, 'Spread the filling evenly. Layer the remaining sheets on top, brushing each one, then fold the overhang in and brush the top well. Score the top layers into 8 squares with a sharp knife, without cutting into the filling, and flick a few drops of water over the top so it doesn''t curl.', null, null, null),
  ('fe9c8dca-01a8-40aa-96ec-b9e7e3a000f1', 6, null, 'Bake until puffed, deep golden and crisp and the filling reads 160°F in the center, 45–50 minutes. Rest 15 minutes, then cut along the scored lines.', 2880, 190.6, 71.1);

-- Grilled Octopus
