values ('4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'grilled-octopus', 'grilled-octopus-4d3dfd', 'Grilled Octopus', 'Octopus simmered in its own juices until tender, then charred over a hot grill and dressed with lemon, olive oil and oregano, Greek taverna style.', 'greek', 3, 20, 90, 110, 4, 'main', null, 0, array['stove', 'grill', 'dutch_oven']::text[], array['entertaining', 'make-ahead']::text[], array['Frozen octopus is often more tender than fresh because freezing breaks down its tough fibres; thaw it in the fridge overnight.', 'Simmer the octopus a day ahead and refrigerate it in its liquid; grill just before serving.']::text[], 'https://images.pexels.com/photos/37068830/pexels-photo-37068830.jpeg', 'Charred grilled octopus tentacles on a textured white plate', 'Paolo Bici', 'https://www.pexels.com/@paolobici/', 'https://www.pexels.com/photo/grilled-octopus-on-elegant-white-plate-37068830/', 'pexels', true, 'public', false,
  'pending_review', array['seafood_raw_bar', 'grilling', 'main', 'dinner', 'entertaining']::text[], array['grill', 'stew']::text[], array['tangy', 'fresh']::text[], '{}'::text[], null, 'traditional', 'grilled-octopus', 'classic', 'Refrigerate the simmered octopus up to 2 days. Grilled leftovers keep 1 day; serve them cold in a salad.', null, 'owned', array['shellfish']::text[], array['shellfish']::text[], array['pescatarian', 'gluten_free', 'dairy_free']::text[], array['octopu', 'bay leave', 'black peppercorn', 'wine vinegar', 'lemon juice', 'dried oregano', 'garlic', 'parsley', 'lemon']::text[], 'bay leave|black peppercorn|dried oregano|garlic|lemon|lemon juice|octopu|parsley|wine vinegar',
  null, null, null, null, null, null, null, null)
