insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9', 1, 'Octopus', '3 lb octopus, cleaned, thawed if frozen', 'octopus', 3, 'lb', 'cleaned, thawed if frozen', false),
  ('4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9', 2, 'Octopus', '2 bay leaves', 'bay leaves', 2, null, null, false),
  ('4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9', 3, 'Octopus', '1 tsp black peppercorns', 'black peppercorns', 1, 'tsp', null, false),
  ('4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9', 4, 'Octopus', '2 tbsp red wine vinegar', 'red wine vinegar', 2, 'tbsp', null, false),
  ('4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9', 5, 'Dressing', '⅓ cup extra-virgin olive oil, plus more for grilling', 'extra-virgin olive oil', 0.33, 'cup', 'plus more for grilling', false),
  ('4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9', 6, 'Dressing', '3 tbsp lemon juice', 'lemon juice', 3, 'tbsp', null, false),
  ('4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9', 7, 'Dressing', '1 tsp dried oregano, preferably Greek', 'dried oregano', 1, 'tsp', 'preferably Greek', false),
  ('4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9', 8, 'Dressing', '1 clove garlic, finely grated', 'garlic', 1, 'clove', 'finely grated', false),
  ('4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9', 9, 'Dressing', '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9', 10, 'Dressing', '1 tbsp fresh parsley, chopped', 'fresh parsley', 1, 'tbsp', 'chopped', false),
  ('4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9', 11, 'To serve', '1 lemon, cut into wedges', 'lemon', 1, null, 'cut into wedges', false);
delete from public.recipe_instructions where recipe_id = '4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9', 1, 'Octopus', 'Rinse the octopus and put it in a Dutch oven with the bay leaves, peppercorns and vinegar — no water. Cover tightly and set over medium-low heat; it will soon release plenty of pink liquid.', null, null, null),
  ('4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9', 2, 'Octopus', 'Simmer gently, covered, until a knife slides easily into the thickest part of a tentacle, 50–70 minutes; it passes the 145°F safe temperature long before it''s tender. Add a splash of water only if the pot starts to run dry.', 3600, null, 62.8),
  ('4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9', 3, 'Octopus', 'Let it cool in its liquid 15 minutes, then lift it out and cut into individual tentacles, discarding the beak if it''s still attached. Toss with a tablespoon of olive oil.', 900, null, null),
  ('4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9', 4, 'Dressing', 'Whisk the olive oil, lemon juice, oregano, garlic and salt.', null, null, null),
  ('4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9', 5, 'Octopus', 'Heat a grill to high (about 500°F) and oil the grates. Grill the tentacles, turning, until charred and crisp at the edges, 3–4 minutes per side.', 420, 260, null),
  ('4d3dfdb2-3860-4f16-a5a5-5a890af6f0a9', 6, null, 'Cut into chunks or leave whole, spoon the dressing over, scatter with parsley and serve with lemon wedges and crusty bread.', null, null, null);

-- Baklava
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
