  attribution, reviewed_by, reviewed_at, calories_per_serving, protein_g, carbs_g, fat_g, nutrition_source)
values ('06e33da7-b285-4a57-9cfb-2f6b8d4a636c', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'baklava', 'baklava-06e33d', 'Baklava', 'Crisp layers of buttered phyllo filled with cinnamon-spiced walnuts and soaked in honey-lemon syrup — the Greek version, made with walnuts and honey.', 'greek', 3, 45, 65, 470, 24, 'dessert', 'pastries', 360, array['oven', 'stove', 'food_processor']::text[], array['make-ahead', 'entertaining']::text[], array['Hot pastry and cool syrup is the rule — it''s what keeps the layers crisp instead of soggy.', 'Pistachios, or a mix of walnuts and almonds, are common in other regions; use the same weight.']::text[], 'https://images.pexels.com/photos/5323489/pexels-photo-5323489.jpeg', 'Close-up of baklava pieces topped with chopped green pistachios', 'Jacob Yavin', 'https://www.pexels.com/@jacobyavin/', 'https://www.pexels.com/photo/a-close-up-shot-of-delicious-baklava-5323489/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'dessert', 'holiday', 'entertaining']::text[], array['stew', 'bake', 'boil']::text[], array['tangy', 'aromatic', 'sweet']::text[], array['christmas', 'easter']::text[], null, 'traditional', 'baklava', 'classic', 'Keep loosely covered at room temperature up to 1 week; the fridge makes it hard.', null, 'owned', array['gluten', 'milk', 'tree_nut', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['walnut', 'ground cinnamon', 'ground clove', 'phyllo dough', 'honey', 'cinnamon stick', 'lemon']::text[], 'cinnamon stick|ground cinnamon|ground clove|honey|lemon|phyllo dough|walnut',
  null, null, null, null, null, null, null, null)
