insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('06e33da7-b285-4a57-9cfb-2f6b8d4a636c', 1, 'Filling', '1 lb walnuts', 'walnuts', 1, 'lb', null, false),
  ('06e33da7-b285-4a57-9cfb-2f6b8d4a636c', 2, 'Filling', '¼ cup sugar', 'sugar', 0.25, 'cup', null, false),
  ('06e33da7-b285-4a57-9cfb-2f6b8d4a636c', 3, 'Filling', '1½ tsp ground cinnamon', 'ground cinnamon', 1.5, 'tsp', null, false),
  ('06e33da7-b285-4a57-9cfb-2f6b8d4a636c', 4, 'Filling', '¼ tsp ground cloves', 'ground cloves', 0.25, 'tsp', null, false),
  ('06e33da7-b285-4a57-9cfb-2f6b8d4a636c', 5, 'Pastry', '1 lb phyllo dough, about 20 sheets, thawed in the fridge overnight', 'phyllo dough', 1, 'lb', 'about 20 sheets, thawed in the fridge overnight', false),
  ('06e33da7-b285-4a57-9cfb-2f6b8d4a636c', 6, 'Pastry', '1 cup unsalted butter, melted (2 sticks)', 'unsalted butter', 1, 'cup', 'melted (2 sticks)', false),
  ('06e33da7-b285-4a57-9cfb-2f6b8d4a636c', 7, 'Syrup', '1 cup sugar', 'sugar', 1, 'cup', null, false),
  ('06e33da7-b285-4a57-9cfb-2f6b8d4a636c', 8, 'Syrup', '1 cup water', 'water', 1, 'cup', null, false),
  ('06e33da7-b285-4a57-9cfb-2f6b8d4a636c', 9, 'Syrup', '½ cup honey', 'honey', 0.5, 'cup', null, false),
  ('06e33da7-b285-4a57-9cfb-2f6b8d4a636c', 10, 'Syrup', '1 cinnamon stick', 'cinnamon stick', 1, null, null, false),
  ('06e33da7-b285-4a57-9cfb-2f6b8d4a636c', 11, 'Syrup', '1 lemon, peel in 2 strips, plus 1 tbsp juice', 'lemon', 1, null, 'peel in 2 strips, plus 1 tbsp juice', false);
delete from public.recipe_instructions where recipe_id = '06e33da7-b285-4a57-9cfb-2f6b8d4a636c';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('06e33da7-b285-4a57-9cfb-2f6b8d4a636c', 1, 'Syrup', 'Bring the sugar, water, honey, cinnamon stick and lemon peel to a boil, stirring until the sugar dissolves, then simmer 10 minutes. Stir in the lemon juice, discard the peel and cinnamon and let the syrup cool completely.', 600, null, null),
  ('06e33da7-b285-4a57-9cfb-2f6b8d4a636c', 2, 'Filling', 'Pulse the walnuts in a food processor until finely chopped but not powdery, then mix with the sugar, cinnamon and cloves.', null, null, null),
  ('06e33da7-b285-4a57-9cfb-2f6b8d4a636c', 3, 'Pastry', 'Heat the oven to 325°F and brush a 9-by-13-inch baking pan with butter. Trim the phyllo to fit if needed and keep it covered with a damp towel as you work.', null, 162.8, null),
  ('06e33da7-b285-4a57-9cfb-2f6b8d4a636c', 4, 'Pastry', 'Lay in 6 sheets, brushing each with butter. Scatter a third of the nuts over, then add 4 buttered sheets; repeat with another third of the nuts and 4 sheets, then the last of the nuts and the remaining 6 sheets, buttering each. Brush the top generously.', null, null, null),
  ('06e33da7-b285-4a57-9cfb-2f6b8d4a636c', 5, 'Pastry', 'With a sharp knife, cut all the way through into diamonds or squares (about 24 pieces) before baking. Bake until deep golden and crisp, 50–60 minutes.', 3300, 162.8, null),
  ('06e33da7-b285-4a57-9cfb-2f6b8d4a636c', 6, null, 'As soon as it comes out of the oven, slowly ladle the cooled syrup over the hot baklava, letting it run into the cuts. Leave uncovered at room temperature at least 6 hours, or overnight, before serving.', 21600, null, null);

-- Sunday Roast Beef
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
