values ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'sunday-roast-beef', 'sunday-roast-beef-0e9605', 'Sunday Roast Beef', 'A roast of beef with crisp, towering Yorkshire puddings and a red wine pan gravy — the centerpiece of a British Sunday lunch.', 'british', 3, 70, 150, 220, 8, 'main', null, 0, array['oven', 'stove']::text[], array['entertaining', 'comfort']::text[], array['Many British cooks serve roast beef pink, pulled at 120–125°F; that''s below the USDA''s 145°F recommendation for whole cuts of beef.', 'Don''t open the oven door while the Yorkshire puddings bake, or they''ll collapse.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['holiday', 'main', 'dinner', 'comfort', 'entertaining']::text[], array['roast', 'stew', 'bake', 'boil']::text[], '{}'::text[], array['christmas', 'easter', 'dinner-party']::text[], null, 'traditional', 'sunday-roast-beef', 'classic', 'Refrigerate sliced beef up to 4 days — it makes great sandwiches with horseradish. Re-crisp Yorkshire puddings at 400°F for 5 minutes.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], array['beef']::text[], '{}'::text[], array['sirloin roast', 'mustard powder', 'yellow onion', 'egg', 'milk', 'beef dripping', 'red wine', 'beef stock']::text[], 'beef dripping|beef stock|egg|milk|mustard powder|red wine|sirloin roast|yellow onion',
  null, null, null, null, null, null, null, null)
