delete from public.recipe_ingredients where recipe_id = '0e960573-7ce0-4c22-ae33-a66fcfb6964d';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 1, 'Beef', '4 lb boneless beef top sirloin roast, or boneless rib roast, tied', 'boneless beef top sirloin roast', 4, 'lb', 'or boneless rib roast, tied', false),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 2, 'Beef', '1 tbsp kosher salt', 'kosher salt', 1, 'tbsp', null, false),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 3, 'Beef', '1 tsp black pepper', 'black pepper', 1, 'tsp', null, false),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 4, 'Beef', '1 tsp dry mustard powder', 'dry mustard powder', 1, 'tsp', null, false),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 5, 'Beef', '2 tbsp vegetable oil', 'vegetable oil', 2, 'tbsp', null, false),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 6, 'Beef', '2 yellow onions, thickly sliced', 'yellow onions', 2, null, 'thickly sliced', false),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 7, 'Yorkshire puddings', '1 cup all-purpose flour', 'all-purpose flour', 1, 'cup', null, false),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 8, 'Yorkshire puddings', '4 large eggs', 'large eggs', 4, null, null, false),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 9, 'Yorkshire puddings', '1 cup whole milk', 'whole milk', 1, 'cup', null, false),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 10, 'Yorkshire puddings', '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 11, 'Yorkshire puddings', '¼ cup beef drippings, from the roast, topped up with vegetable oil', 'beef drippings', 0.25, 'cup', 'from the roast, topped up with vegetable oil', false),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 12, 'Gravy', '2 tbsp all-purpose flour', 'all-purpose flour', 2, 'tbsp', null, false),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 13, 'Gravy', '½ cup dry red wine', 'dry red wine', 0.5, 'cup', null, false),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 14, 'Gravy', '2 cups beef stock', 'beef stock', 2, 'cup', null, false);
delete from public.recipe_instructions where recipe_id = '0e960573-7ce0-4c22-ae33-a66fcfb6964d';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 1, 'Yorkshire puddings', 'Whisk the flour, eggs, milk and salt into a smooth batter about as thick as heavy cream. Cover and rest at room temperature 1 hour (or refrigerate overnight).', 3600, null, null),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 2, 'Beef', 'At the same time, take the beef out of the fridge, pat it dry and rub all over with the salt, pepper and mustard powder. Heat the oven to 450°F.', null, 232.2, null),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 3, 'Beef', 'Scatter the onions in a roasting pan, set the beef on top, fat-side up, and drizzle with the oil. Roast 20 minutes, then lower the oven to 325°F and roast until an instant-read thermometer in the center reads 135°F, 60–80 minutes more.', 5400, 162.8, null),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 4, 'Beef', 'Move the beef to a board, cover loosely with foil and rest 30 minutes; it will rise to at least 145°F (medium) as it rests.', 1800, null, 62.8),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 5, 'Yorkshire puddings', 'As soon as the beef comes out, raise the oven to 450°F. Spoon 1 teaspoon of drippings into each cup of a 12-cup muffin tin and heat in the oven until smoking, 10 minutes. Carefully pour the batter into the hot fat, filling each cup about halfway, and bake without opening the door until puffed, crisp and deep golden, 18–22 minutes.', 1800, 232.2, null),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 6, 'Gravy', 'While the puddings bake, pour off all but 2 tablespoons of fat from the roasting pan, set it over medium heat and stir in the flour for 1 minute. Add the wine and boil, scraping up the browned bits and mashing the onions, then whisk in the stock and simmer until glossy, 8–10 minutes. Strain, season and add the beef''s resting juices.', 600, null, null),
  ('0e960573-7ce0-4c22-ae33-a66fcfb6964d', 7, null, 'Carve the beef thinly across the grain and serve with the Yorkshire puddings and gravy, plus roast potatoes, seasonal vegetables and horseradish sauce.', null, null, null);

-- Full English Breakfast
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
