values ('4e63e84d-7a76-4149-af39-7fa1e87558e0', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'full-english-breakfast', 'full-english-breakfast-4e63e8', 'Full English Breakfast', 'Sausages, bacon, fried eggs, mushrooms, fried tomatoes, baked beans, black pudding and toast on one plate — the classic weekend fry-up.', 'british', 2, 10, 40, 50, 4, 'breakfast', null, 0, array['stove', 'oven', 'cast_iron']::text[], array['comfort', 'brunch']::text[], array['British sausages and black pudding usually contain rusk, oats or barley (gluten), and black pudding is made with pork blood — check the labels.', 'Two pans, or a large griddle, make the timing much easier.']::text[], 'https://images.pexels.com/photos/15352990/pexels-photo-15352990.jpeg', 'Full English breakfast with fried eggs, sausage, bacon, baked beans, tomato and toast', 'MikeGz', 'https://www.pexels.com/@mikegz-400576129/', 'https://www.pexels.com/photo/close-up-shot-of-an-english-breakfast-15352990/', 'pexels', true, 'public', false,
  'pending_review', array['breakfast', 'holiday', 'comfort']::text[], array['pan_fry']::text[], '{}'::text[], array['brunch-party', 'fathers-day']::text[], null, 'traditional', 'full-english-breakfast', 'classic', 'Best eaten fresh. Refrigerate leftover sausages and bacon up to 3 days.', 'Runny yolks aren''t cooked to a safe temperature. Cook the eggs until the yolks are firm, or use pasteurized eggs, for anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], array['pork', 'beans']::text[], '{}'::text[], array['pork sausage', 'back bacon', 'cremini mushroom', 'tomato', 'tomato sauce', 'egg', 'bread']::text[], 'back bacon|bread|cremini mushroom|egg|pork sausage|tomato|tomato sauce',
  null, null, null, null, null, null, null, null)
