  ('4e63e84d-7a76-4149-af39-7fa1e87558e0', 1, null, '8 British-style pork sausages, or fresh breakfast links', 'British-style pork sausages', 8, null, 'or fresh breakfast links', false),
  ('4e63e84d-7a76-4149-af39-7fa1e87558e0', 2, null, '8 slice back bacon, or Canadian bacon or thick-cut bacon', 'back bacon', 8, 'slice', 'or Canadian bacon or thick-cut bacon', false),
  ('4e63e84d-7a76-4149-af39-7fa1e87558e0', 3, null, '4 slice black pudding, ½ inch thick', 'black pudding', 4, 'slice', '½ inch thick', true),
  ('4e63e84d-7a76-4149-af39-7fa1e87558e0', 4, null, '8 oz cremini mushrooms, halved', 'cremini mushrooms', 8, 'oz', 'halved', false),
  ('4e63e84d-7a76-4149-af39-7fa1e87558e0', 5, null, '2 ripe tomatoes, halved', 'ripe tomatoes', 2, null, 'halved', false),
  ('4e63e84d-7a76-4149-af39-7fa1e87558e0', 6, null, '1 can baked beans in tomato sauce, 15 oz', 'baked beans in tomato sauce', 1, 'can', '15 oz', false),
  ('4e63e84d-7a76-4149-af39-7fa1e87558e0', 7, null, '2 tbsp vegetable oil, divided', 'vegetable oil', 2, 'tbsp', 'divided', false),
  ('4e63e84d-7a76-4149-af39-7fa1e87558e0', 8, null, '2 tbsp unsalted butter', 'unsalted butter', 2, 'tbsp', null, false),
  ('4e63e84d-7a76-4149-af39-7fa1e87558e0', 9, null, '4 large eggs', 'large eggs', 4, null, null, false),
  ('4e63e84d-7a76-4149-af39-7fa1e87558e0', 10, null, '4 slice bread, for toast', 'bread', 4, 'slice', 'for toast', false),
  ('4e63e84d-7a76-4149-af39-7fa1e87558e0', 11, null, '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('4e63e84d-7a76-4149-af39-7fa1e87558e0', 12, null, '¼ tsp black pepper', 'black pepper', 0.25, 'tsp', null, false);
delete from public.recipe_instructions where recipe_id = '4e63e84d-7a76-4149-af39-7fa1e87558e0';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('4e63e84d-7a76-4149-af39-7fa1e87558e0', 1, null, 'Heat the oven to 200°F and put in a sheet pan to keep everything warm as it''s done.', null, 93.3, null),
  ('4e63e84d-7a76-4149-af39-7fa1e87558e0', 2, null, 'Heat 1 tablespoon oil in a large cast-iron skillet over medium heat. Cook the sausages, turning often, until browned all over and they reach 160°F inside, 15–18 minutes. Move to the oven.', 960, null, 71.1),
  ('4e63e84d-7a76-4149-af39-7fa1e87558e0', 3, null, 'In the same pan, fry the bacon until cooked through and lightly crisp, 3–4 minutes per side, then the black pudding, if using, 2 minutes per side. Keep warm.', 600, null, null),
  ('4e63e84d-7a76-4149-af39-7fa1e87558e0', 4, null, 'Add the butter, mushrooms and tomatoes (cut-side down) to the pan, season with the salt and pepper and cook until the mushrooms are browned and the tomatoes softened and charred in spots, 6–8 minutes. Meanwhile, warm the beans in a small saucepan and make the toast.', 420, null, null),
  ('4e63e84d-7a76-4149-af39-7fa1e87558e0', 5, null, 'Wipe out the pan, heat the remaining oil over medium-low heat and crack in the eggs. Fry, spooning hot fat over the tops, until the whites are completely set, 3–4 minutes; cook longer, or flip, for firm yolks.', 240, null, null),
  ('4e63e84d-7a76-4149-af39-7fa1e87558e0', 6, null, 'Pile everything onto warm plates and serve with brown sauce or ketchup and a pot of tea.', null, null, null);

