values ('4f2be02a-54ba-40a2-864b-040a54793189', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'apple-crumble', 'apple-crumble-4f2be0', 'Apple Crumble', 'Tart apples baked under a buttery, sandy flour-and-sugar crumble until bubbling — a British pudding best served with hot custard or cream.', 'british', 1, 20, 55, 75, 6, 'dessert', 'fruit', 0, array['oven']::text[], array['comfort', 'budget', 'kid-friendly', 'make-ahead']::text[], array['Make a double batch of topping and freeze it in a bag; it goes straight from the freezer onto the fruit.', 'Swap a third of the apples for blackberries or rhubarb in season.']::text[], 'https://images.pexels.com/photos/9266852/pexels-photo-9266852.jpeg', 'Close-up of apple crumble on a plate with a creamy topping', 'Valeria Boltneva', 'https://www.pexels.com/@valeriya/', 'https://www.pexels.com/photo/closeup-of-an-apple-crumble-on-a-plate-9266852/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'dessert', 'baking', 'budget']::text[], array['bake']::text[], array['tangy', 'rich', 'aromatic', 'sweet']::text[], '{}'::text[], null, 'traditional', 'apple-crumble', 'classic', 'Keep covered at room temperature 1 day or refrigerate up to 4 days. Reheat at 350°F for 15 minutes to re-crisp the top.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['baking apple', 'brown sugar', 'lemon juice', 'ground cinnamon', 'demerara sugar']::text[], 'baking apple|brown sugar|demerara sugar|ground cinnamon|lemon juice',
  null, null, null, null, null, null, null, null)
