insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('4f2be02a-54ba-40a2-864b-040a54793189', 1, 'Filling', '2½ lb tart baking apples, such as Bramley or Granny Smith, peeled, cored and sliced', 'tart baking apples', 2.5, 'lb', 'such as Bramley or Granny Smith, peeled, cored and sliced', false),
  ('4f2be02a-54ba-40a2-864b-040a54793189', 2, 'Filling', '⅓ cup light brown sugar', 'light brown sugar', 0.33, 'cup', null, false),
  ('4f2be02a-54ba-40a2-864b-040a54793189', 3, 'Filling', '1 tbsp lemon juice', 'lemon juice', 1, 'tbsp', null, false),
  ('4f2be02a-54ba-40a2-864b-040a54793189', 4, 'Filling', '1 tsp ground cinnamon', 'ground cinnamon', 1, 'tsp', null, false),
  ('4f2be02a-54ba-40a2-864b-040a54793189', 5, 'Filling', '1 tbsp all-purpose flour', 'all-purpose flour', 1, 'tbsp', null, false),
  ('4f2be02a-54ba-40a2-864b-040a54793189', 6, 'Topping', '1½ cups all-purpose flour', 'all-purpose flour', 1.5, 'cup', null, false),
  ('4f2be02a-54ba-40a2-864b-040a54793189', 7, 'Topping', '½ cup demerara sugar, or light brown sugar', 'demerara sugar', 0.5, 'cup', 'or light brown sugar', false),
  ('4f2be02a-54ba-40a2-864b-040a54793189', 8, 'Topping', '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('4f2be02a-54ba-40a2-864b-040a54793189', 9, 'Topping', '10 tbsp cold unsalted butter, cubed', 'cold unsalted butter', 10, 'tbsp', 'cubed', false),
