delete from public.recipe_instructions where recipe_id = '4f2be02a-54ba-40a2-864b-040a54793189';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('4f2be02a-54ba-40a2-864b-040a54793189', 1, 'Filling', 'Heat the oven to 375°F. Toss the apples with the brown sugar, lemon juice, cinnamon and flour and spread in a 2-quart baking dish.', null, 190.6, null),
  ('4f2be02a-54ba-40a2-864b-040a54793189', 2, 'Topping', 'Rub the flour, sugar, salt and butter together with your fingertips until the mixture looks like coarse breadcrumbs with a few pea-sized lumps. Squeeze a few handfuls so some clumps form.', null, null, null),
  ('4f2be02a-54ba-40a2-864b-040a54793189', 3, 'Topping', 'Scatter the crumble evenly over the apples without pressing it down.', null, null, null),
  ('4f2be02a-54ba-40a2-864b-040a54793189', 4, null, 'Set the dish on a sheet pan and bake until the topping is golden and the fruit is bubbling thickly at the edges, 40–45 minutes.', 2520, 190.6, null),
  ('4f2be02a-54ba-40a2-864b-040a54793189', 5, null, 'Cool 10 minutes and serve warm with cream, custard or ice cream.', 600, null, null);

