values ('09af820a-8d78-4304-b07e-66c8ea123f1b', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'colcannon', 'colcannon-09af82', 'Colcannon', 'Fluffy mashed potatoes folded with buttery cabbage and scallion-infused milk — the Irish favourite (kale is the other common version), traditional at Halloween.', 'irish', 1, 15, 30, 45, 6, 'side', null, 0, array['stove']::text[], array['vegetarian', 'budget', 'comfort', 'kid-friendly']::text[], array['For the kale version, use 8 oz curly kale, stems removed and finely chopped, in place of the cabbage.', 'Leftovers make great potato cakes: shape, dust with flour and fry in butter until crisp.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['side', 'holiday', 'budget', 'comfort']::text[], array['stew', 'steam', 'boil']::text[], '{}'::text[], array['halloween']::text[], null, 'traditional', 'colcannon', 'classic', 'Refrigerate up to 3 days. Reheat with a splash of milk, or fry as potato cakes.', null, 'owned', array['milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['russet potato', 'green cabbage', 'scallion', 'milk']::text[], 'green cabbage|milk|russet potato|scallion',
  null, null, null, null, null, null, null, null)
