  ('09af820a-8d78-4304-b07e-66c8ea123f1b', 1, null, '3 lb russet potatoes, peeled and cut into 2-inch chunks', 'russet potatoes', 3, 'lb', 'peeled and cut into 2-inch chunks', false),
  ('09af820a-8d78-4304-b07e-66c8ea123f1b', 2, null, '1 tbsp kosher salt, for the cooking water', 'kosher salt', 1, 'tbsp', 'for the cooking water', false),
  ('09af820a-8d78-4304-b07e-66c8ea123f1b', 3, null, '6 tbsp unsalted butter, divided', 'unsalted butter', 6, 'tbsp', 'divided', false),
  ('09af820a-8d78-4304-b07e-66c8ea123f1b', 4, null, '1 lb green cabbage, cored and finely shredded', 'green cabbage', 1, 'lb', 'cored and finely shredded', false),
  ('09af820a-8d78-4304-b07e-66c8ea123f1b', 5, null, '1 bunch scallions, thinly sliced', 'scallions', 1, 'bunch', 'thinly sliced', false),
  ('09af820a-8d78-4304-b07e-66c8ea123f1b', 6, null, '1 cup whole milk', 'whole milk', 1, 'cup', null, false),
  ('09af820a-8d78-4304-b07e-66c8ea123f1b', 7, null, '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('09af820a-8d78-4304-b07e-66c8ea123f1b', 8, null, '¼ tsp black pepper', 'black pepper', 0.25, 'tsp', null, false);
delete from public.recipe_instructions where recipe_id = '09af820a-8d78-4304-b07e-66c8ea123f1b';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('09af820a-8d78-4304-b07e-66c8ea123f1b', 1, null, 'Cover the potatoes with cold water, add the tablespoon of salt and bring to a boil. Simmer until very tender, 15–20 minutes.', 1080, null, null),
  ('09af820a-8d78-4304-b07e-66c8ea123f1b', 2, null, 'Meanwhile, melt 2 tablespoons butter in a large skillet over medium heat and cook the cabbage with a pinch of salt, stirring, until tender and bright, 6–8 minutes.', 420, null, null),
  ('09af820a-8d78-4304-b07e-66c8ea123f1b', 3, null, 'Warm the milk with the scallions in a small saucepan until steaming, then turn off the heat and let them infuse.', 180, null, null),
  ('09af820a-8d78-4304-b07e-66c8ea123f1b', 4, null, 'Drain the potatoes, let them steam dry in the pot for a minute, then mash until smooth. Beat in the hot milk and scallions, 2 tablespoons butter, the teaspoon of salt and the pepper, then fold in the cabbage.', null, null, null),
  ('09af820a-8d78-4304-b07e-66c8ea123f1b', 5, null, 'Pile into a warm dish, make a well in the center and drop in the remaining 2 tablespoons butter to melt into a golden pool. Serve hot.', null, null, null);

-- Sauerbraten
