values ('f6ad07c6-1ed8-46f9-abbc-23d8cb7c40ba', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'sauerbraten', 'sauerbraten-f6ad07', 'Sauerbraten', 'Beef marinated in spiced red wine vinegar, braised until tender and served in a sweet-sour gravy with raisins, Rhineland style; we marinate for 2–3 days instead of up to a week and thicken the gravy with gingersnap cookies in place of Aachener Printen gingerbread.', 'german', 3, 30, 195, 3105, 8, 'main', null, 2880, array['stove', 'oven', 'dutch_oven']::text[], array['make-ahead', 'comfort', 'entertaining']::text[], array['Gingersnap cookies contain wheat. Aachener Printen gingerbread, the Rhineland original, is sold at German shops and online around Christmas.', 'Keep the beef in the fridge the whole time it marinates, and only use the marinade once it has been boiled in the gravy — never uncooked.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'holiday', 'comfort', 'entertaining']::text[], array['braise', 'stew', 'pan_fry', 'boil']::text[], array['tangy', 'aromatic']::text[], array['christmas', 'dinner-party']::text[], 'Rhineland', 'adapted', 'sauerbraten', 'classic', 'Refrigerate in the gravy up to 4 days or freeze up to 3 months; it slices more neatly cold and reheats beautifully.', null, 'owned', array['gluten', 'wheat']::text[], array['beef']::text[], array['dairy_free']::text[], array['wine vinegar', 'red wine', 'yellow onion', 'carrot', 'celery', 'juniper berry', 'clove', 'black peppercorn', 'mustard seed', 'bay leave', 'round roast', 'gingersnap cooky', 'raisin']::text[], 'bay leave|black peppercorn|carrot|celery|clove|gingersnap cooky|juniper berry|mustard seed|raisin|red wine|round roast|wine vinegar|yellow onion',
  null, null, null, null, null, null, null, null)
