  ('f6ad07c6-1ed8-46f9-abbc-23d8cb7c40ba', 14, 'Beef', '3½ lb beef bottom round roast, or chuck roast', 'beef bottom round roast', 3.5, 'lb', 'or chuck roast', false),
  ('f6ad07c6-1ed8-46f9-abbc-23d8cb7c40ba', 15, 'Beef', '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
