values ('a6e3fe59-dca5-419e-82f0-da20853f39f1', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'bratwurst-with-sauerkraut', 'bratwurst-with-sauerkraut-a6e3fe', 'Bratwurst with Sauerkraut', 'Browned fresh bratwurst simmered on sauerkraut braised with onion, apple, caraway and beer, served with mustard and potatoes or rye bread.', 'german', 2, 15, 45, 60, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'comfort', 'one-pot']::text[], array['Bratwurst recipes vary and some contain milk, wheat or soy — check the label if anyone has allergies.', 'Precooked bratwurst works too; simmer it in the sauerkraut just until heated through, about 10 minutes.']::text[], 'https://images.unsplash.com/photo-1745827223757-c98bc93108d2', 'Bratwurst with sauerkraut and mashed potatoes on a plate', 'Minyeong Jeong', 'https://unsplash.com/@manonsfoto', 'https://unsplash.com/photos/sausages-sauerkraut-and-mashed-potatoes-on-a-plate-nZ0MB73Clxc', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'holiday', 'comfort']::text[], array['stew', 'pan_fry', 'boil']::text[], '{}'::text[], array['game-day']::text[], null, 'traditional', 'bratwurst-with-sauerkraut', 'classic', 'Refrigerate up to 4 days; the sauerkraut is even better reheated.', null, 'owned', array['gluten', 'milk']::text[], array['pork']::text[], '{}'::text[], array['pork bratwurst', 'yellow onion', 'tart apple', 'caraway seed', 'sauerkraut', 'bay leaf', 'lager beer', 'brown sugar', 'german mustard']::text[], 'bay leaf|brown sugar|caraway seed|german mustard|lager beer|pork bratwurst|sauerkraut|tart apple|yellow onion',
  null, null, null, null, null, null, null, null)
