insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('a6e3fe59-dca5-419e-82f0-da20853f39f1', 1, null, 'Heat the oil in a large deep skillet over medium heat. Brown the bratwurst on all sides, 8–10 minutes; they won''t be cooked through yet. Set aside.', 540, null, null),
  ('a6e3fe59-dca5-419e-82f0-da20853f39f1', 2, null, 'Add the butter and onion to the pan and cook until soft and golden, 8 minutes. Stir in the apple and caraway for 1 minute.', 540, null, null),
  ('a6e3fe59-dca5-419e-82f0-da20853f39f1', 3, null, 'Add the sauerkraut, juniper (if using), bay leaf, beer and brown sugar, stir well and bring to a simmer.', null, null, null),
  ('a6e3fe59-dca5-419e-82f0-da20853f39f1', 4, null, 'Nestle the bratwurst into the sauerkraut, cover and simmer gently until the sausages reach 160°F inside and the sauerkraut is soft and mellow, 20–25 minutes. Uncover for the last 5 minutes if it''s watery.', 1320, null, 71.1),
  ('a6e3fe59-dca5-419e-82f0-da20853f39f1', 5, null, 'Discard the bay leaf and serve the bratwurst on the sauerkraut with mustard and boiled potatoes, mashed potatoes or rye bread.', null, null, null);

