values ('b334301f-b006-4081-b334-d7891961fbbc', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'spaetzle', 'spatzle-b33430', 'Spätzle', 'Tender, chewy little Swabian egg noodles made from a quick batter pressed into simmering water, then tossed in nutty browned butter.', 'german', 2, 25, 20, 45, 4, 'side', null, 0, array['stove']::text[], array['vegetarian', 'kid-friendly', 'budget', 'comfort']::text[], array['For Käsespätzle, layer the hot spätzle with 8 oz grated Emmentaler cheese and top with onions fried until crisp and deep golden.', 'Serve with sauerbraten, goulash or any dish with plenty of gravy.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['side', 'budget', 'comfort']::text[], array['stew', 'boil']::text[], array['fresh']::text[], '{}'::text[], 'Swabia', 'traditional', 'spaetzle', 'classic', 'Refrigerate boiled spätzle up to 3 days or freeze up to 2 months; pan-fry in butter straight from cold.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['ground nutmeg', 'egg']::text[], 'egg|ground nutmeg',
  null, null, null, null, null, null, null, null)
