delete from public.recipe_ingredients where recipe_id = 'b334301f-b006-4081-b334-d7891961fbbc';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('b334301f-b006-4081-b334-d7891961fbbc', 1, 'Spätzle', '2 cups all-purpose flour', 'all-purpose flour', 2, 'cup', null, false),
  ('b334301f-b006-4081-b334-d7891961fbbc', 2, 'Spätzle', '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('b334301f-b006-4081-b334-d7891961fbbc', 3, 'Spätzle', '⅛ tsp ground nutmeg', 'ground nutmeg', 0.125, 'tsp', null, false),
  ('b334301f-b006-4081-b334-d7891961fbbc', 4, 'Spätzle', '4 large eggs', 'large eggs', 4, null, null, false),
  ('b334301f-b006-4081-b334-d7891961fbbc', 5, 'Spätzle', '½ cup water, plus more as needed', 'water', 0.5, 'cup', 'plus more as needed', false),
  ('b334301f-b006-4081-b334-d7891961fbbc', 6, 'Spätzle', '1 tbsp kosher salt, for the cooking water', 'kosher salt', 1, 'tbsp', 'for the cooking water', false),
  ('b334301f-b006-4081-b334-d7891961fbbc', 7, 'To finish', '4 tbsp unsalted butter', 'unsalted butter', 4, 'tbsp', null, false),
  ('b334301f-b006-4081-b334-d7891961fbbc', 8, 'To finish', '2 tbsp fresh parsley, chopped', 'fresh parsley', 2, 'tbsp', 'chopped', true);
delete from public.recipe_instructions where recipe_id = 'b334301f-b006-4081-b334-d7891961fbbc';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('b334301f-b006-4081-b334-d7891961fbbc', 1, 'Spätzle', 'Whisk the flour, salt and nutmeg in a bowl. Beat the eggs with the water, add to the flour and beat hard with a wooden spoon until the batter is smooth, thick and elastic and bubbles start to form, 2–3 minutes. It should drip slowly from the spoon; add a splash more water if it''s too stiff. Rest 15 minutes.', 900, null, null),
  ('b334301f-b006-4081-b334-d7891961fbbc', 2, 'Spätzle', 'Bring a large pot of water to a boil with the tablespoon of salt, then lower to a steady simmer.', null, null, null),
  ('b334301f-b006-4081-b334-d7891961fbbc', 3, 'Spätzle', 'Working in 3 batches, press the batter into the water with a spätzle maker, or push it through the large holes of a colander or box grater with a spatula. Or, Swabian style, spread some on a wet cutting board and scrape thin strips into the water with a knife.', null, null, null),
  ('b334301f-b006-4081-b334-d7891961fbbc', 4, 'Spätzle', 'Cook until the spätzle float, then 1 minute more, 2–3 minutes per batch. Lift out with a slotted spoon into a colander.', 540, null, null),
  ('b334301f-b006-4081-b334-d7891961fbbc', 5, 'To finish', 'Melt the butter in a large skillet over medium heat until it foams and smells nutty, about 3 minutes. Add the spätzle and toss until hot and lightly golden in spots, 3–4 minutes. Season, sprinkle with parsley and serve.', 420, null, null);

