values ('1dc86d92-5408-4909-9142-280c5e095656', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'black-forest-cake', 'black-forest-cake-1dc86d', 'Black Forest Cake', 'Light chocolate sponge layers brushed with kirsch, filled with sour cherries and whipped cream and covered in chocolate shavings — Baden''s Schwarzwälder Kirschtorte.', 'german', 3, 60, 40, 220, 12, 'dessert', 'cakes', 120, array['oven', 'stove', 'stand_mixer']::text[], array['entertaining', 'make-ahead']::text[], array['The kirsch isn''t cooked, so the cake contains alcohol; for a family version, brush the layers with plain cherry syrup or cherry juice instead.', 'Jarred sour (Morello) cherries are sold at many supermarkets, Eastern European shops and online; drained canned tart cherries work too.']::text[], 'https://images.pexels.com/photos/29487450/pexels-photo-29487450.jpeg', 'Black Forest cake topped with chocolate shavings and fresh cherries, seen from above', 'Janine Speidel', 'https://www.pexels.com/@janine-speidel-1933619854/', 'https://www.pexels.com/photo/delicious-black-forest-cake-with-fresh-cherries-29487450/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'dessert', 'holiday', 'entertaining']::text[], array['bake', 'boil']::text[], array['rich', 'sweet']::text[], array['birthday', 'christmas']::text[], 'Baden', 'traditional', 'black-forest-cake', 'classic', 'Refrigerate, loosely covered, up to 3 days. The unfilled sponge layers freeze well, wrapped, for 1 month.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['egg', 'vanilla extract', 'cocoa powder', 'cornstarch', 'cherry syrup', 'kirsch', 'heavy cream', 'powdered sugar', 'bittersweet chocolate']::text[], 'bittersweet chocolate|cherry syrup|cocoa powder|cornstarch|egg|heavy cream|kirsch|powdered sugar|vanilla extract',
  null, null, null, null, null, null, null, null)
