  ('1dc86d92-5408-4909-9142-280c5e095656', 1, 'Sponge', '6 large eggs, at room temperature', 'large eggs', 6, null, 'at room temperature', false),
  ('1dc86d92-5408-4909-9142-280c5e095656', 2, 'Sponge', '1 cup sugar', 'sugar', 1, 'cup', null, false),
