  ('1dc86d92-5408-4909-9142-280c5e095656', 4, 'Sponge', '¾ cup all-purpose flour', 'all-purpose flour', 0.75, 'cup', null, false),
  ('1dc86d92-5408-4909-9142-280c5e095656', 5, 'Sponge', '⅓ cup unsweetened cocoa powder', 'unsweetened cocoa powder', 0.33, 'cup', null, false),
  ('1dc86d92-5408-4909-9142-280c5e095656', 6, 'Sponge', '¼ cup cornstarch', 'cornstarch', 0.25, 'cup', null, false),
  ('1dc86d92-5408-4909-9142-280c5e095656', 7, 'Sponge', '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('1dc86d92-5408-4909-9142-280c5e095656', 8, 'Sponge', '4 tbsp unsalted butter, melted and cooled', 'unsalted butter', 4, 'tbsp', 'melted and cooled', false),
  ('1dc86d92-5408-4909-9142-280c5e095656', 9, 'Cherries', '1 jar sour cherries in light syrup, about 24 oz, such as Morello', 'sour cherries in light syrup', 1, 'jar', 'about 24 oz, such as Morello', false),
  ('1dc86d92-5408-4909-9142-280c5e095656', 10, 'Cherries', '2 tbsp cornstarch', 'cornstarch', 2, 'tbsp', null, false),
  ('1dc86d92-5408-4909-9142-280c5e095656', 11, 'Cherries', '2 tbsp sugar', 'sugar', 2, 'tbsp', null, false),
  ('1dc86d92-5408-4909-9142-280c5e095656', 12, 'Cherries', '⅓ cup kirsch, cherry brandy, divided', 'kirsch', 0.33, 'cup', 'cherry brandy, divided', false),
  ('1dc86d92-5408-4909-9142-280c5e095656', 13, 'Cream', '3 cups heavy cream, cold', 'heavy cream', 3, 'cup', 'cold', false),
  ('1dc86d92-5408-4909-9142-280c5e095656', 14, 'Cream', '⅓ cup powdered sugar', 'powdered sugar', 0.33, 'cup', null, false),
  ('1dc86d92-5408-4909-9142-280c5e095656', 15, 'Cream', '1 tsp vanilla extract', 'vanilla extract', 1, 'tsp', null, false),
  ('1dc86d92-5408-4909-9142-280c5e095656', 16, 'Garnish', '4 oz bittersweet chocolate, in a block, for shavings', 'bittersweet chocolate', 4, 'oz', 'in a block, for shavings', false),
  ('1dc86d92-5408-4909-9142-280c5e095656', 17, 'Garnish', '12 fresh cherries, with stems, or reserved jarred cherries', 'fresh cherries', 12, null, 'with stems, or reserved jarred cherries', true);
delete from public.recipe_instructions where recipe_id = '1dc86d92-5408-4909-9142-280c5e095656';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('1dc86d92-5408-4909-9142-280c5e095656', 1, 'Sponge', 'Heat the oven to 350°F. Line the bottom of a 9-inch springform pan with parchment; don''t grease the sides. Sift together the flour, cocoa, cornstarch and salt.', null, 176.7, null),
  ('1dc86d92-5408-4909-9142-280c5e095656', 2, 'Sponge', 'In a stand mixer, whisk the eggs and sugar on high speed until tripled in volume, very pale and thick enough to hold a ribbon for a few seconds, 8–10 minutes. Beat in the vanilla.', 600, null, null),
  ('1dc86d92-5408-4909-9142-280c5e095656', 3, 'Sponge', 'Sift the dry ingredients over in three additions, folding gently with a large spatula after each. Fold a scoop of batter into the melted butter, then fold that back into the batter. Pour into the pan.', null, null, null),
  ('1dc86d92-5408-4909-9142-280c5e095656', 4, 'Sponge', 'Bake until risen and springy and a skewer comes out clean, 30–35 minutes. Cool completely in the pan, then run a knife around the edge, unmould and slice horizontally into 3 even layers.', 1920, 176.7, null),
  ('1dc86d92-5408-4909-9142-280c5e095656', 5, 'Cherries', 'Drain the cherries, saving the syrup. Whisk 1 cup of the syrup with the cornstarch and sugar in a saucepan and boil, stirring, until thick and clear, 1–2 minutes. Stir in the cherries and 1 tablespoon kirsch and cool completely. Mix the remaining kirsch with ¼ cup of the leftover syrup for brushing.', 300, null, null),
  ('1dc86d92-5408-4909-9142-280c5e095656', 6, 'Cream', 'Whip the cold cream, powdered sugar and vanilla to firm peaks, 3–4 minutes.', 240, null, null),
  ('1dc86d92-5408-4909-9142-280c5e095656', 7, null, 'Set a sponge layer on a plate and brush with a third of the kirsch syrup. Spread with a thin layer of cream, pipe or spoon a ring of cream around the edge and fill the center with half the cherries. Repeat with the second layer, then top with the last layer, brush with the remaining syrup and cover the top and sides with cream.', null, null, null),
  ('1dc86d92-5408-4909-9142-280c5e095656', 8, null, 'Pipe 12 rosettes of cream around the top and set a cherry on each. Shave the chocolate with a vegetable peeler and press the shavings onto the sides and scatter over the center. Chill at least 2 hours before slicing.', 7200, null, null);

-- Wiener Schnitzel (Veal)
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
