values ('fb98e65a-0f99-47f3-b950-1dffe5396d6c', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'wiener-schnitzel-veal', 'wiener-schnitzel-veal-fb98e6', 'Wiener Schnitzel (Veal)', 'Veal pounded paper-thin, coated in a loose, rippled crumb and fried in plenty of fat until it puffs — Vienna''s signature dish, served simply with lemon.', 'austrian', 3, 25, 15, 40, 4, 'main', null, 0, array['stove', 'cast_iron']::text[], array['entertaining', 'kid-friendly']::text[], array['Ask the butcher for veal scaloppine from the leg — it''s already thin and evenly cut.', 'In Austria, the same dish made with pork must be called "Schnitzel Wiener Art"; pork loin works with exactly this method.']::text[], 'https://images.unsplash.com/photo-1599921841143-819065a55cc6', 'Golden breaded Wiener schnitzel on a white plate', 'Mark König', 'https://unsplash.com/@markkoenig', 'https://unsplash.com/photos/fried-food-on-white-ceramic-plate-MyfbM2QYF4o', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'comfort', 'entertaining']::text[], '{}'::text[], array['tangy', 'fresh']::text[], '{}'::text[], 'Vienna', 'traditional', 'wiener-schnitzel', 'classic', 'Best eaten right away. Leftovers keep 2 days in the fridge; reheat on a rack at 400°F for 8–10 minutes to re-crisp.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], array['veal']::text[], '{}'::text[], array['veal cutlet', 'egg', 'milk', 'dry breadcrumb', 'lemon']::text[], 'dry breadcrumb|egg|lemon|milk|veal cutlet',
  null, null, null, null, null, null, null, null)
