insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('fb98e65a-0f99-47f3-b950-1dffe5396d6c', 1, null, '1¼ lb veal cutlets, from the leg (top round), 4 pieces', 'veal cutlets', 1.25, 'lb', 'from the leg (top round), 4 pieces', false),
  ('fb98e65a-0f99-47f3-b950-1dffe5396d6c', 2, null, '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('fb98e65a-0f99-47f3-b950-1dffe5396d6c', 3, null, '½ cup all-purpose flour', 'all-purpose flour', 0.5, 'cup', null, false),
  ('fb98e65a-0f99-47f3-b950-1dffe5396d6c', 4, null, '2 large eggs', 'large eggs', 2, null, null, false),
  ('fb98e65a-0f99-47f3-b950-1dffe5396d6c', 5, null, '1 tbsp whole milk', 'whole milk', 1, 'tbsp', null, false),
  ('fb98e65a-0f99-47f3-b950-1dffe5396d6c', 6, null, '1½ cups fine dry breadcrumbs, plain, not panko', 'fine dry breadcrumbs', 1.5, 'cup', 'plain, not panko', false),
  ('fb98e65a-0f99-47f3-b950-1dffe5396d6c', 7, null, '1½ cups vegetable oil, or lard', 'vegetable oil', 1.5, 'cup', 'or lard', false),
  ('fb98e65a-0f99-47f3-b950-1dffe5396d6c', 8, null, '3 tbsp unsalted butter', 'unsalted butter', 3, 'tbsp', null, false),
  ('fb98e65a-0f99-47f3-b950-1dffe5396d6c', 9, null, '1 lemon, cut into wedges', 'lemon', 1, null, 'cut into wedges', false),
  ('fb98e65a-0f99-47f3-b950-1dffe5396d6c', 10, null, '2 tbsp fresh parsley, chopped', 'fresh parsley', 2, 'tbsp', 'chopped', true);
delete from public.recipe_instructions where recipe_id = 'fb98e65a-0f99-47f3-b950-1dffe5396d6c';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('fb98e65a-0f99-47f3-b950-1dffe5396d6c', 1, null, 'Lay each cutlet between sheets of plastic wrap and pound with a flat mallet or small pan to an even ⅛ inch thick, working from the center out. Pat dry and season both sides with the salt.', null, null, null),
  ('fb98e65a-0f99-47f3-b950-1dffe5396d6c', 2, null, 'Set out three shallow dishes: flour; the eggs beaten with the milk; breadcrumbs. Dredge a cutlet in flour and shake off the excess, dip it in egg and let it drip, then lay it in the crumbs and toss crumbs over it. Don''t press — a loose coat is what lets it puff. Bread just before frying.', 480, null, null),
  ('fb98e65a-0f99-47f3-b950-1dffe5396d6c', 3, null, 'Heat the oil and butter in a large cast-iron or heavy skillet to 340–350°F; there should be about ½ inch of fat and the pan no more than half full. Keep children away and never leave hot fat unattended.', 360, 176.7, null),
  ('fb98e65a-0f99-47f3-b950-1dffe5396d6c', 4, null, 'Fry one or two cutlets at a time, constantly shaking the pan and spooning hot fat over the top so the crumb lifts into waves. Turn once; cook until deep golden and 145°F inside, 1½–2 minutes per side.', 480, null, 62.8),
  ('fb98e65a-0f99-47f3-b950-1dffe5396d6c', 5, null, 'Drain briefly on a rack set over paper towels and serve at once with lemon wedges, parsley, and potato salad or lingonberry jam.', null, null, null);

-- Apfelstrudel
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
