values ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'apfelstrudel', 'apfelstrudel-5cfae5', 'Apfelstrudel', 'A whisper-thin, hand-stretched dough rolled around cinnamon apples, rum-soaked raisins and buttery toasted crumbs — Vienna''s coffee-house classic.', 'austrian', 4, 100, 45, 145, 8, 'dessert', 'pastries', 0, array['oven', 'stove']::text[], array['entertaining', 'make-ahead']::text[], array['Short on time or nerve? Use 8 sheets of thawed phyllo, each brushed with butter and sprinkled with crumbs, in place of the stretched dough.', 'Serve warm with lightly sweetened whipped cream or vanilla sauce.']::text[], 'https://images.pexels.com/photos/14093961/pexels-photo-14093961.jpeg', 'Slice of apple strudel with whipped cream and vanilla sauce on a white plate', 'Fatih Maraşlıoğlu', 'https://www.pexels.com/@fatih-maraslioglu-193600170/', 'https://www.pexels.com/photo/piece-of-cake-on-a-plate-with-a-sauce-14093961/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'dessert', 'entertaining']::text[], array['bake']::text[], array['tangy', 'aromatic', 'sweet']::text[], '{}'::text[], 'Vienna', 'traditional', 'apfelstrudel', 'classic', 'Best the day it''s baked. Keep loosely covered at room temperature up to 1 day or refrigerated up to 3 days; re-crisp at 350°F for 10 minutes.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['bread flour', 'lukewarm water', 'white vinegar', 'raisin', 'rum', 'tart apple', 'lemon', 'granulated sugar', 'ground cinnamon', 'dry breadcrumb', 'powdered sugar']::text[], 'bread flour|dry breadcrumb|granulated sugar|ground cinnamon|lemon|lukewarm water|powdered sugar|raisin|rum|tart apple|white vinegar',
  null, null, null, null, null, null, null, null)
