insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 1, 'Dough', '1⅔ cups bread flour, about 7½ oz, plus more for the cloth', 'bread flour', 1.66, 'cup', 'about 7½ oz, plus more for the cloth', false),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 2, 'Dough', '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 3, 'Dough', '½ cup lukewarm water, plus 1–2 tbsp if needed', 'lukewarm water', 0.5, 'cup', 'plus 1–2 tbsp if needed', false),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 4, 'Dough', '3 tbsp vegetable oil, plus more for coating', 'vegetable oil', 3, 'tbsp', 'plus more for coating', false),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 5, 'Dough', '1 tsp white vinegar', 'white vinegar', 1, 'tsp', null, false),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 6, 'Filling', '⅓ cup raisins', 'raisins', 0.33, 'cup', null, false),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 7, 'Filling', '2 tbsp dark rum, or apple juice', 'dark rum', 2, 'tbsp', 'or apple juice', false),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 8, 'Filling', '2½ lb tart apples, such as Granny Smith or Braeburn, about 5', 'tart apples', 2.5, 'lb', 'such as Granny Smith or Braeburn, about 5', false),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 9, 'Filling', '1 lemon, juiced', 'lemon', 1, null, 'juiced', false),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 10, 'Filling', '½ cup granulated sugar', 'granulated sugar', 0.5, 'cup', null, false),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 11, 'Filling', '1½ tsp ground cinnamon', 'ground cinnamon', 1.5, 'tsp', null, false),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 12, 'Crumbs', '4 tbsp unsalted butter', 'unsalted butter', 4, 'tbsp', null, false),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 13, 'Crumbs', '1 cup fine dry breadcrumbs', 'fine dry breadcrumbs', 1, 'cup', null, false),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 14, 'Assembly', '6 tbsp unsalted butter, melted', 'unsalted butter', 6, 'tbsp', 'melted', false),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 15, 'Assembly', '2 tbsp powdered sugar, for dusting', 'powdered sugar', 2, 'tbsp', 'for dusting', false);
delete from public.recipe_instructions where recipe_id = '5cfae5c6-5b0e-4c82-94df-2db81219d6db';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 1, 'Dough', 'Mix the flour and salt, then add the water, oil and vinegar and knead until very smooth and elastic, about 8 minutes by hand; it should be soft but not sticky. Form a ball, coat with oil, cover and rest at room temperature for at least 1 hour.', 4200, null, null),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 2, 'Filling', 'Soak the raisins in the rum. Peel, core and thinly slice the apples, toss with the lemon juice, then just before assembling add the sugar, cinnamon and drained raisins.', null, null, null),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 3, 'Crumbs', 'Melt the butter in a skillet over medium heat and toast the breadcrumbs, stirring, until golden and nutty, 4–5 minutes. Let cool.', 300, null, null),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 4, 'Assembly', 'Heat the oven to 375°F and line a sheet pan with parchment. Cover a table with a clean cotton tablecloth (about 3 by 4 feet) and rub flour into it.', null, 190.6, null),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 5, 'Assembly', 'Roll the dough into a rectangle on the cloth, then slip the backs of your hands under it and gently pull from the center outwards, walking around the table, until it is thin enough to read a newspaper through and about 30 by 24 inches. Trim off the thick edge. Small holes are fine.', 900, null, null),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 6, 'Assembly', 'Brush the dough with some of the melted butter. Scatter the crumbs over the third nearest you, leaving a 2-inch border, and pile the apples on top. Fold in the sides, then lift the cloth so the strudel rolls itself up. Roll it seam-side down onto the pan, curving it into a horseshoe if needed, and brush with butter.', null, null, null),
  ('5cfae5c6-5b0e-4c82-94df-2db81219d6db', 7, 'Assembly', 'Bake, brushing with butter twice more, until deep golden and the apples are tender, 40–45 minutes. Cool at least 20 minutes, dust with powdered sugar and slice with a serrated knife.', 2580, 190.6, null);

