values ('42d20d16-79cd-475a-ab7f-ac324a11411d', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'swiss-cheese-fondue', 'cheese-fondue-42d20d', 'Cheese Fondue', 'Gruyère and Emmental melted into dry white wine with garlic and a splash of kirsch — the classic moitié-moitié Swiss blend — for dunking bread and potatoes.', 'swiss', 2, 20, 20, 40, 4, 'main', null, 0, array['stove']::text[], array['entertaining', 'vegetarian', 'date-night']::text[], array['If it turns stringy or splits, whisk in 1 tsp cornstarch mixed with 1 tbsp lemon juice over low heat until it comes back together.', 'Emmental and Gruyère are traditionally made with animal rennet. Let the last layer brown at the bottom of the pot — the crisp crust (la religieuse) is a treat.']::text[], 'https://images.unsplash.com/photo-1765099271832-258bee41458b', 'Cube of crusty bread lifted out of a pot of molten cheese fondue', 'Vitalii Kyktov', 'https://unsplash.com/@i_am_vitality', 'https://unsplash.com/photos/a-piece-of-bread-dipped-in-cheese-fondue-ZNG5Ujw4XiU', 'unsplash', true, 'public', false,
  'pending_review', array['entertaining', 'main', 'dinner', 'holiday', 'date_night']::text[], array['stew', 'steam', 'boil']::text[], array['tangy']::text[], array['date-night', 'dinner-party']::text[], null, 'traditional', 'cheese-fondue', 'classic', 'Best eaten fresh. Chill leftovers up to 3 days and use them as a sauce for potatoes or macaroni, reheating gently with a splash of wine or milk.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['garlic', 'white wine', 'lemon juice', 'gruyere cheese', 'emmental cheese', 'cornstarch', 'ground nutmeg', 'crusty bread', 'potato']::text[], 'cornstarch|crusty bread|emmental cheese|garlic|ground nutmeg|gruyere cheese|lemon juice|potato|white wine',
  null, null, null, null, null, null, null, null)
