insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('42d20d16-79cd-475a-ab7f-ac324a11411d', 1, 'Fondue', '1 clove garlic, halved', 'garlic', 1, 'clove', 'halved', false),
  ('42d20d16-79cd-475a-ab7f-ac324a11411d', 2, 'Fondue', '1¼ cups dry white wine, such as Swiss Fendant or Sauvignon Blanc', 'dry white wine', 1.25, 'cup', 'such as Swiss Fendant or Sauvignon Blanc', false),
  ('42d20d16-79cd-475a-ab7f-ac324a11411d', 3, 'Fondue', '1 tbsp lemon juice', 'lemon juice', 1, 'tbsp', null, false),
  ('42d20d16-79cd-475a-ab7f-ac324a11411d', 4, 'Fondue', '10 oz Gruyère cheese, coarsely grated', 'Gruyère cheese', 10, 'oz', 'coarsely grated', false),
  ('42d20d16-79cd-475a-ab7f-ac324a11411d', 5, 'Fondue', '10 oz Emmental cheese, coarsely grated', 'Emmental cheese', 10, 'oz', 'coarsely grated', false),
  ('42d20d16-79cd-475a-ab7f-ac324a11411d', 6, 'Fondue', '2 tbsp cornstarch', 'cornstarch', 2, 'tbsp', null, false),
  ('42d20d16-79cd-475a-ab7f-ac324a11411d', 7, 'Fondue', '2 tbsp kirsch, cherry brandy', 'kirsch', 2, 'tbsp', 'cherry brandy', true),
  ('42d20d16-79cd-475a-ab7f-ac324a11411d', 8, 'Fondue', '1 pinch ground nutmeg', 'ground nutmeg', 1, 'pinch', null, false),
  ('42d20d16-79cd-475a-ab7f-ac324a11411d', 9, 'Fondue', '¼ tsp black pepper, freshly ground', 'black pepper', 0.25, 'tsp', 'freshly ground', false),
  ('42d20d16-79cd-475a-ab7f-ac324a11411d', 10, 'For dipping', '1 lb crusty bread, a day old, cut into 1-inch cubes with crust on each', 'crusty bread', 1, 'lb', 'a day old, cut into 1-inch cubes with crust on each', false),
  ('42d20d16-79cd-475a-ab7f-ac324a11411d', 11, 'For dipping', '1 lb small potatoes, boiled until tender', 'small potatoes', 1, 'lb', 'boiled until tender', false),
  ('42d20d16-79cd-475a-ab7f-ac324a11411d', 12, 'For dipping', '½ cup cornichons', 'cornichons', 0.5, 'cup', null, true);
delete from public.recipe_instructions where recipe_id = '42d20d16-79cd-475a-ab7f-ac324a11411d';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('42d20d16-79cd-475a-ab7f-ac324a11411d', 1, null, 'Toss the grated cheeses with the cornstarch so every shred is coated.', null, null, null),
  ('42d20d16-79cd-475a-ab7f-ac324a11411d', 2, null, 'Rub the inside of a heavy saucepan or ceramic fondue pot with the cut garlic, then leave the garlic in. Add the wine and lemon juice and heat over medium until steaming with small bubbles at the edge — don''t let it boil hard.', 240, null, null),
  ('42d20d16-79cd-475a-ab7f-ac324a11411d', 3, null, 'Turn the heat to medium-low and add the cheese a handful at a time, stirring in a figure-eight with a wooden spoon and letting each handful melt before adding the next. Keep it at a bare simmer until smooth and creamy, 10–12 minutes.', 720, null, null),
  ('42d20d16-79cd-475a-ab7f-ac324a11411d', 4, null, 'Stir in the kirsch, nutmeg and pepper. If it''s too thick, add a splash of warm wine; if too thin, add a little more cheese.', 120, null, null),
  ('42d20d16-79cd-475a-ab7f-ac324a11411d', 5, null, 'Set the pot over a fondue burner on low at the table. Spear bread and potatoes and swirl them through, stirring the pot as you dip so it stays smooth.', null, null, null);

