values ('226c5838-33a4-4008-988c-40fa612eb49f', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'gravlax', 'gravlax-226c58', 'Gravlax', 'Salmon cured for two days under salt, sugar, white pepper and a blanket of dill, sliced thin and served with sweet mustard-dill sauce.', 'scandinavian', 3, 30, 0, 2910, 8, 'starter', null, 2880, '{}'::text[], array['make-ahead', 'entertaining']::text[], array['The cure firms the fish and seasons it deeply but leaves it silky; for a firmer, saltier result leave it a third day.', 'Ask the fishmonger for salmon that''s been frozen for raw eating (often sold as sushi- or sashimi-grade).']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['seafood_raw_bar', 'appetizer', 'holiday', 'entertaining']::text[], array['raw', 'no_cook']::text[], array['tangy', 'fresh']::text[], array['christmas', 'easter']::text[], 'Scandinavia', 'traditional', 'gravlax', 'classic', 'Wrapped tightly, keep refrigerated up to 4 days after curing, or freeze unsliced up to 1 month.', 'Curing doesn''t kill parasites. Use salmon sold for eating raw or commercially frozen, or freeze it at -4°F or below for 7 days first. Keep it at 40°F or below the whole time and eat within 4 days. Not for anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['fish', 'gluten', 'wheat']::text[], array['fish']::text[], array['pescatarian', 'dairy_free']::text[], array['salmon fillet', 'granulated sugar', 'white peppercorn', 'dill', 'dijon mustard', 'wine vinegar', 'rye bread']::text[], 'dijon mustard|dill|granulated sugar|rye bread|salmon fillet|white peppercorn|wine vinegar',
  null, null, null, null, null, null, null, null)
