insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('226c5838-33a4-4008-988c-40fa612eb49f', 1, 'Gravlax', '2 lb center-cut salmon fillet, skin on, pin bones removed, previously frozen', 'center-cut salmon fillet', 2, 'lb', 'skin on, pin bones removed, previously frozen', false),
  ('226c5838-33a4-4008-988c-40fa612eb49f', 2, 'Gravlax', '⅓ cup kosher salt, use ¼ cup if using Morton', 'kosher salt', 0.33, 'cup', 'use ¼ cup if using Morton', false),
  ('226c5838-33a4-4008-988c-40fa612eb49f', 3, 'Gravlax', '⅓ cup granulated sugar', 'granulated sugar', 0.33, 'cup', null, false),
  ('226c5838-33a4-4008-988c-40fa612eb49f', 4, 'Gravlax', '1 tbsp white peppercorns, coarsely crushed', 'white peppercorns', 1, 'tbsp', 'coarsely crushed', false),
  ('226c5838-33a4-4008-988c-40fa612eb49f', 5, 'Gravlax', '2 bunch fresh dill, with stems, coarsely chopped', 'fresh dill', 2, 'bunch', 'with stems, coarsely chopped', false),
  ('226c5838-33a4-4008-988c-40fa612eb49f', 6, 'Gravlax', '2 tbsp aquavit, or vodka', 'aquavit', 2, 'tbsp', 'or vodka', true),
  ('226c5838-33a4-4008-988c-40fa612eb49f', 7, 'Mustard sauce', '3 tbsp Dijon mustard, or Swedish sweet mustard', 'Dijon mustard', 3, 'tbsp', 'or Swedish sweet mustard', false),
  ('226c5838-33a4-4008-988c-40fa612eb49f', 8, 'Mustard sauce', '1 tbsp granulated sugar', 'granulated sugar', 1, 'tbsp', null, false),
  ('226c5838-33a4-4008-988c-40fa612eb49f', 9, 'Mustard sauce', '1 tbsp white wine vinegar', 'white wine vinegar', 1, 'tbsp', null, false),
  ('226c5838-33a4-4008-988c-40fa612eb49f', 10, 'Mustard sauce', '⅓ cup vegetable oil', 'vegetable oil', 0.33, 'cup', null, false),
  ('226c5838-33a4-4008-988c-40fa612eb49f', 11, 'Mustard sauce', '3 tbsp fresh dill, finely chopped', 'fresh dill', 3, 'tbsp', 'finely chopped', false),
  ('226c5838-33a4-4008-988c-40fa612eb49f', 12, 'To serve', '8 slice dark rye bread, or crispbread', 'dark rye bread', 8, 'slice', 'or crispbread', false);
delete from public.recipe_instructions where recipe_id = '226c5838-33a4-4008-988c-40fa612eb49f';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('226c5838-33a4-4008-988c-40fa612eb49f', 1, 'Gravlax', 'Run your fingers along the salmon and pull out any pin bones with tweezers. Pat dry and cut the fillet in half crosswise into two equal pieces.', null, null, null),
  ('226c5838-33a4-4008-988c-40fa612eb49f', 2, 'Gravlax', 'Mix the salt, sugar and crushed white pepper. Sprinkle a quarter of the mix in a glass or ceramic dish just big enough for the fish and lay one piece skin-side down on it.', null, null, null),
  ('226c5838-33a4-4008-988c-40fa612eb49f', 3, 'Gravlax', 'Drizzle the flesh with the aquavit, rub half the remaining cure over it and cover thickly with the dill. Rub the rest of the cure on the second piece and lay it flesh-side down on top, thick end over thin end, so the dill is sandwiched between.', null, null, null),
  ('226c5838-33a4-4008-988c-40fa612eb49f', 4, 'Gravlax', 'Cover with plastic wrap, set a small board weighted with a couple of cans on top and refrigerate for 48 hours. Turn the whole package every 12 hours and spoon the brine that collects back over the fish.', 172800, null, null),
  ('226c5838-33a4-4008-988c-40fa612eb49f', 5, 'Mustard sauce', 'Whisk the mustard, sugar and vinegar, then whisk in the oil in a thin stream until thick. Stir in the dill. Refrigerate up to 1 week.', null, null, null),
  ('226c5838-33a4-4008-988c-40fa612eb49f', 6, 'Gravlax', 'Scrape off the dill and pepper and pat the fish dry. With a long, sharp knife, slice it very thinly on a sharp angle, leaving the skin behind. Serve cold with the sauce and rye bread.', null, null, null);

-- Pierogi Ruskie
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
