values ('2899ddcb-41c2-4608-bfba-820273f2746d', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'pierogi-ruskie', 'pierogi-ruskie-2899dd', 'Pierogi Ruskie', 'Tender half-moon dumplings filled with mashed potato, tangy farmer''s cheese and sweet fried onion, finished in onion butter with sour cream on the side.', 'polish', 3, 90, 40, 130, 6, 'main', null, 0, array['stove']::text[], array['comfort', 'vegetarian', 'freezer-friendly', 'make-ahead']::text[], array['No farmer cheese? Press dry-curd or small-curd cottage cheese in a sieve to drain it well.', 'Freeze uncooked pierogi on a floured tray, then bag them; boil from frozen, adding 2–3 minutes.']::text[], 'https://images.unsplash.com/photo-1788603377815-fd9f7ed95fd7', 'Pan-fried pierogi topped with caramelized onions and fresh dill on a white plate', 'Zoshua Colah', 'https://unsplash.com/@zoshuacolah', 'https://unsplash.com/photos/pierogi-with-caramelized-onions-and-dill-9zgj7soTsFg', 'unsplash', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner']::text[], array['stew', 'boil']::text[], '{}'::text[], '{}'::text[], null, 'traditional', 'pierogi-ruskie', 'classic', 'Refrigerate cooked pierogi up to 3 days and pan-fry in butter to reheat. Freeze uncooked up to 3 months.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['russet potato', 'yellow onion', 'farmer cheese', 'sour cream']::text[], 'farmer cheese|russet potato|sour cream|yellow onion',
  null, null, null, null, null, null, null, null)
