delete from public.recipe_ingredients where recipe_id = '2899ddcb-41c2-4608-bfba-820273f2746d';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 1, 'Dough', '3 cups all-purpose flour, plus more for rolling', 'all-purpose flour', 3, 'cup', 'plus more for rolling', false),
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 2, 'Dough', '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 3, 'Dough', '1 cup warm water', 'warm water', 1, 'cup', null, false),
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 4, 'Dough', '3 tbsp unsalted butter, melted', 'unsalted butter', 3, 'tbsp', 'melted', false),
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 5, 'Filling', '1½ lb russet potatoes, peeled and quartered', 'russet potatoes', 1.5, 'lb', 'peeled and quartered', false),
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 6, 'Filling', '2 tbsp unsalted butter', 'unsalted butter', 2, 'tbsp', null, false),
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 7, 'Filling', '1 yellow onion, finely diced', 'yellow onion', 1, null, 'finely diced', false),
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 8, 'Filling', '8 oz farmer cheese, Polish twaróg, crumbled', 'farmer cheese', 8, 'oz', 'Polish twaróg, crumbled', false),
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 9, 'Filling', '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 10, 'Filling', '¾ tsp black pepper', 'black pepper', 0.75, 'tsp', null, false),
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 11, 'Topping', '4 tbsp unsalted butter', 'unsalted butter', 4, 'tbsp', null, false),
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 12, 'Topping', '1 yellow onion, thinly sliced', 'yellow onion', 1, null, 'thinly sliced', false),
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 13, 'Topping', '1 cup sour cream, to serve', 'sour cream', 1, 'cup', 'to serve', false);
delete from public.recipe_instructions where recipe_id = '2899ddcb-41c2-4608-bfba-820273f2746d';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 1, 'Filling', 'Boil the potatoes in salted water until very tender, 18–20 minutes. Meanwhile, cook the diced onion in the butter over medium-low heat until soft and golden, 12 minutes.', 1200, null, null),
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 2, 'Filling', 'Drain the potatoes well and mash or rice them while hot. Mix in the fried onion, farmer cheese, salt and pepper; it should taste well seasoned. Cool completely.', null, null, null),
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 3, 'Dough', 'Mix the flour and salt, add the warm water and melted butter and knead until smooth and soft, about 6 minutes. Cover and rest 30 minutes.', 2160, null, null),
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 4, 'Dough', 'Roll half the dough about 1/16 inch thick and cut 3-inch rounds. Put a heaped teaspoon of filling on each, fold over and pinch the edges firmly to seal, pressing out the air. Re-roll scraps once. Keep finished pierogi under a towel on a floured tray.', 2400, null, null),
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 5, 'Topping', 'Melt the butter in a large skillet and cook the sliced onion slowly until deep golden, 15 minutes. Keep warm.', 900, null, null),
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 6, null, 'Bring a large pot of salted water to a gentle boil. Cook the pierogi in batches of 12–15, stirring once so they don''t stick; once they float, simmer 2 minutes more, about 4 minutes in all. Lift out with a slotted spoon straight into the onion butter.', 900, null, null),
  ('2899ddcb-41c2-4608-bfba-820273f2746d', 7, null, 'Toss gently to coat (or fry until golden in spots) and serve with sour cream.', null, null, null);

