values ('2e02530a-5bdd-4263-8ebd-012adda2cf86', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'bigos-hunters-stew', 'bigos-hunter-s-stew-2e0253', 'Bigos (Hunter''s Stew)', 'Sauerkraut and fresh cabbage slowly stewed with pork shoulder, smoked kielbasa, bacon, wild mushrooms, prunes and red wine — Poland''s deep, sour-smoky stew that gets better every day.', 'polish', 3, 40, 180, 220, 8, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['comfort', 'make-ahead', 'freezer-friendly', 'one-pot']::text[], array['Some kielbasa contains milk powder, soy or wheat fillers; read the label if allergies matter at your table.', 'Too sour? Add a grated apple or another handful of prunes. Not sour enough? Stir in a splash of sauerkraut juice.']::text[], 'https://images.pexels.com/photos/37645620/pexels-photo-37645620.png', 'Bigos sauerkraut and meat stew served in a bread bowl on a rustic table', 'Anh Nguyen', 'https://www.pexels.com/@anh-nguyen-517648218/', 'https://www.pexels.com/photo/traditional-polish-bread-bowl-bigos-in-breslau-37645620/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner', 'soup', 'holiday']::text[], array['stew', 'pan_fry', 'boil']::text[], array['smoky', 'aromatic']::text[], array['christmas', 'new-year']::text[], null, 'traditional', 'bigos', 'classic', 'Refrigerate up to 5 days or freeze up to 3 months. Reheat slowly, covered, with a splash of water.', null, 'owned', '{}'::text[], array['pork']::text[], array['gluten_free', 'dairy_free']::text[], array['porcini mushroom', 'thick-cut bacon', 'pork shoulder', 'yellow onion', 'red wine', 'sauerkraut', 'green cabbage', 'tomato paste', 'pitted prune', 'bay leave', 'allspice berry', 'smoked kielbasa']::text[], 'allspice berry|bay leave|green cabbage|pitted prune|porcini mushroom|pork shoulder|red wine|sauerkraut|smoked kielbasa|thick-cut bacon|tomato paste|yellow onion',
