delete from public.recipe_instructions where recipe_id = '2e02530a-5bdd-4263-8ebd-012adda2cf86';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('2e02530a-5bdd-4263-8ebd-012adda2cf86', 1, null, 'Soak the porcini in the hot water for 20 minutes. Lift them out, chop, and strain the soaking liquid through a paper towel to catch any grit.', 1200, null, null),
  ('2e02530a-5bdd-4263-8ebd-012adda2cf86', 2, null, 'Cook the bacon in a large Dutch oven over medium heat until the fat runs and it starts to crisp, 6 minutes. Lift out. Brown the pork in the bacon fat in two batches, 6–8 minutes each, and set aside with the bacon.', 1200, null, null),
  ('2e02530a-5bdd-4263-8ebd-012adda2cf86', 3, null, 'Add the onions and cook until soft and golden, 8 minutes. Pour in the wine and scrape up the browned bits.', 480, null, null),
  ('2e02530a-5bdd-4263-8ebd-012adda2cf86', 4, null, 'Add the sauerkraut, fresh cabbage, mushrooms and their liquid, tomato paste, prunes, bay leaves, allspice, juniper, salt and pepper, then return the pork and bacon. Stir, cover and simmer on the lowest heat, stirring every 20 minutes and adding a splash of water if it catches, for 2 hours, until the pork is fork-tender (well past 145°F).', 7200, null, 62.8),
  ('2e02530a-5bdd-4263-8ebd-012adda2cf86', 5, null, 'Add the kielbasa and simmer uncovered 30 minutes more until the stew is thick and glossy. Taste for salt and sourness.', 1800, null, null),
  ('2e02530a-5bdd-4263-8ebd-012adda2cf86', 6, null, 'Ideally, cool and refrigerate overnight, then reheat gently to serve with rye bread or boiled potatoes — Polish cooks reheat it over two or three days and swear it improves each time.', null, null, null);

-- Khachapuri Adjaruli
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
