values ('9dfccdf3-42cf-4ff0-84d7-77d85d483483', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'khachapuri-adjaruli', 'khachapuri-adjaruli-9dfccd', 'Khachapuri Adjaruli', 'Boat-shaped bread filled with molten cheese, crowned with a just-set egg and a pat of butter to stir in at the table; we use mozzarella and feta in place of Georgian sulguni and imeruli cheeses.', 'georgian', 3, 100, 20, 120, 4, 'main', null, 0, array['oven']::text[], array['vegetarian', 'comfort', 'entertaining']::text[], array['If you find sulguni at an Eastern European or Russian grocer, use 1 lb of it with 6 oz feta for a more authentic stretch and tang.', 'Pinch the boat ends very firmly or they''ll unfurl in the oven.']::text[], 'https://images.unsplash.com/photo-1790498943034-4bc40b444032', 'Boat-shaped Adjaruli khachapuri with a runny egg yolk on a white plate', 'Kristian Kulijanov', 'https://unsplash.com/@filmijanov', 'https://unsplash.com/photos/khachapuri-with-egg-yolk-breakfast-Pd92hAA7Qk0', 'unsplash', true, 'public', false,
  'pending_review', array['baking', 'main', 'dinner', 'comfort', 'entertaining']::text[], array['bake']::text[], '{}'::text[], '{}'::text[], 'Adjara', 'adapted', 'khachapuri-adjaruli', 'classic', 'Best straight from the oven. Bake-ahead boats (without the egg) can be reheated at 400°F and finished with the egg.', 'The eggs here aren''t cooked to 160°F. Use pasteurized eggs if you''re serving anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['bread flour', 'instant yeast', 'granulated sugar', 'milk', 'whole-milk mozzarella', 'feta cheese', 'egg']::text[], 'bread flour|egg|feta cheese|granulated sugar|instant yeast|milk|whole-milk mozzarella',
  null, null, null, null, null, null, null, null)
