insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('9dfccdf3-42cf-4ff0-84d7-77d85d483483', 1, 'Dough', '2½ cups bread flour, plus more for shaping', 'bread flour', 2.5, 'cup', 'plus more for shaping', false),
  ('9dfccdf3-42cf-4ff0-84d7-77d85d483483', 2, 'Dough', '1 tsp instant yeast', 'instant yeast', 1, 'tsp', null, false),
  ('9dfccdf3-42cf-4ff0-84d7-77d85d483483', 3, 'Dough', '1 tsp granulated sugar', 'granulated sugar', 1, 'tsp', null, false),
  ('9dfccdf3-42cf-4ff0-84d7-77d85d483483', 4, 'Dough', '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('9dfccdf3-42cf-4ff0-84d7-77d85d483483', 5, 'Dough', '¾ cup warm whole milk', 'warm whole milk', 0.75, 'cup', null, false),
  ('9dfccdf3-42cf-4ff0-84d7-77d85d483483', 6, 'Dough', '2 tbsp vegetable oil', 'vegetable oil', 2, 'tbsp', null, false),
  ('9dfccdf3-42cf-4ff0-84d7-77d85d483483', 7, 'Filling', '10 oz low-moisture whole-milk mozzarella, shredded', 'low-moisture whole-milk mozzarella', 10, 'oz', 'shredded', false),
  ('9dfccdf3-42cf-4ff0-84d7-77d85d483483', 8, 'Filling', '6 oz feta cheese, crumbled', 'feta cheese', 6, 'oz', 'crumbled', false),
