values ('4b0a408e-3d8e-4f2a-ba2b-17d9718f1327', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'khinkali', 'khinkali-4b0a40', 'Khinkali', 'Big, pleated Georgian dumplings filled with peppery beef and pork that turns into a mouthful of hot broth — eaten by hand, topknot left on the plate.', 'georgian', 3, 90, 35, 125, 6, 'main', null, 0, array['stove']::text[], array['entertaining', 'freezer-friendly']::text[], array['Mountain-style khinkali (mtiuluri) uses only meat, onion, salt, pepper and caraway — leave out the cilantro, garlic and cumin for that version.', 'Freeze shaped dumplings on a floured tray, then bag; boil from frozen for 16–18 minutes.']::text[], 'https://images.unsplash.com/photo-1762206083047-d83b6db1f757', 'Plate of khinkali dumplings on a patterned tablecloth', 'Nikita Pishchugin', 'https://unsplash.com/@nikita_pishchugin', 'https://unsplash.com/photos/plate-of-khinkali-dumplings-on-a-patterned-tablecloth-BFdgd6UfZcU', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'entertaining']::text[], array['boil']::text[], array['spicy', 'fresh', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'khinkali', 'classic', 'Leftovers keep 2 days in the fridge; pan-fry until crisp to reheat. Freeze uncooked up to 3 months.', null, 'owned', array['gluten', 'wheat']::text[], array['beef', 'pork']::text[], array['dairy_free']::text[], array['ground beef', 'ground pork', 'yellow onion', 'garlic', 'cilantro', 'ground cumin', 'pepper flake']::text[], 'cilantro|garlic|ground beef|ground cumin|ground pork|pepper flake|yellow onion',
  null, null, null, null, null, null, null, null)
