insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('4b0a408e-3d8e-4f2a-ba2b-17d9718f1327', 1, 'Dough', 'Mix the flour and salt, add the water and knead into a firm, smooth dough, 8–10 minutes. It should be stiffer than pasta dough. Wrap and rest 30 minutes.', 2400, null, null),
  ('4b0a408e-3d8e-4f2a-ba2b-17d9718f1327', 2, 'Filling', 'Mix the beef, pork, onions, garlic, cilantro, salt, pepper, cumin and pepper flakes. Add the cold water a little at a time, squishing it in with your hand until the mixture is loose and soupy but holds together. Refrigerate while you roll.', null, null, null),
  ('4b0a408e-3d8e-4f2a-ba2b-17d9718f1327', 3, 'Dough', 'Divide the dough into 24 pieces and roll each into a 6-inch round, thinner at the edges than in the middle. Keep the rest covered.', 1200, null, null),
  ('4b0a408e-3d8e-4f2a-ba2b-17d9718f1327', 4, 'Dough', 'Put a heaped tablespoon of filling in the center of a round. Holding it in one hand, pleat the edge up and around the filling, making 12–18 folds, then pinch and twist the top into a knot to seal. Set on a floured tray.', 1800, null, null),
  ('4b0a408e-3d8e-4f2a-ba2b-17d9718f1327', 5, null, 'Bring a large pot of well-salted water to a boil. Lower in 8 dumplings at a time, stir gently so they don''t stick, and boil until they float, then 10 minutes more — 12–14 minutes in all. Cut one open: the filling should be 160°F with no pink.', 780, null, 71.1),
  ('4b0a408e-3d8e-4f2a-ba2b-17d9718f1327', 6, null, 'Lift out with a slotted spoon and grind plenty of black pepper over them. To eat, hold by the knot, bite a small hole, sip the broth, then eat the rest and leave the knot.', null, null, null);

-- Kibbeh
