values ('597dda5d-803b-46af-9288-c605f3c14c06', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'kibbeh-fried', 'kibbeh-597dda', 'Kibbeh', 'Fried, torpedo-shaped kibbeh — the most common kind on a Lebanese mezze table — with a crisp shell of beef and bulgur around spiced meat, onion and pine nuts.', 'lebanese', 3, 75, 30, 145, 6, 'main', null, 40, array['stove', 'food_processor']::text[], array['entertaining', 'freezer-friendly']::text[], array['Lebanese seven spice (baharat) is a blend of allspice, black pepper, cinnamon, cloves, nutmeg, coriander and ginger; allspice alone is a fine stand-in.', 'Freeze shaped, unfried kibbeh on a tray, then bag; fry from frozen at 325°F for 7–8 minutes until 160°F inside.']::text[], 'https://images.unsplash.com/photo-1786174044931-d395bf77e58e', 'Fried kibbeh on lettuce with tomato and lemon slices', 'Chez Le Libanais', 'https://unsplash.com/@chezlelibanais', 'https://unsplash.com/photos/kibbeh-appetizer-with-tomato-and-lemon-Go_BsrnVId4', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'entertaining']::text[], '{}'::text[], array['tangy', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'kibbeh', 'classic', 'Refrigerate up to 3 days and reheat at 375°F for 10–12 minutes. Freeze unfried up to 3 months.', null, 'owned', array['gluten', 'milk', 'tree_nut', 'wheat']::text[], array['beef']::text[], '{}'::text[], array['bulgur', 'yellow onion', 'seven spice', 'ground beef', 'ice water', 'pine nut', 'ground cinnamon', 'whole-milk yogurt', 'lemon']::text[], 'bulgur|ground beef|ground cinnamon|ice water|lemon|pine nut|seven spice|whole-milk yogurt|yellow onion',
  null, null, null, null, null, null, null, null)
