  ('597dda5d-803b-46af-9288-c605f3c14c06', 1, 'Shell', '1 cup fine bulgur, #1 grind', 'fine bulgur', 1, 'cup', '#1 grind', false),
  ('597dda5d-803b-46af-9288-c605f3c14c06', 2, 'Shell', '1 small yellow onion, quartered', 'small yellow onion', 1, null, 'quartered', false),
  ('597dda5d-803b-46af-9288-c605f3c14c06', 3, 'Shell', '1½ tsp Lebanese seven spice, or ground allspice', 'Lebanese seven spice', 1.5, 'tsp', 'or ground allspice', false),
  ('597dda5d-803b-46af-9288-c605f3c14c06', 4, 'Shell', '1¼ tsp kosher salt', 'kosher salt', 1.25, 'tsp', null, false),
  ('597dda5d-803b-46af-9288-c605f3c14c06', 5, 'Shell', '1 lb lean ground beef, 93% lean, or lean ground lamb', 'lean ground beef', 1, 'lb', '93% lean, or lean ground lamb', false),
  ('597dda5d-803b-46af-9288-c605f3c14c06', 6, 'Shell', '¼ cup ice water, as needed', 'ice water', 0.25, 'cup', 'as needed', false),
  ('597dda5d-803b-46af-9288-c605f3c14c06', 7, 'Filling', '1 tbsp olive oil', 'olive oil', 1, 'tbsp', null, false),
