  ('597dda5d-803b-46af-9288-c605f3c14c06', 9, 'Filling', '1 yellow onion, finely chopped', 'yellow onion', 1, null, 'finely chopped', false),
  ('597dda5d-803b-46af-9288-c605f3c14c06', 10, 'Filling', '½ lb ground beef, 85% lean, or ground lamb', 'ground beef', 0.5, 'lb', '85% lean, or ground lamb', false),
  ('597dda5d-803b-46af-9288-c605f3c14c06', 11, 'Filling', '1 tsp Lebanese seven spice, or ground allspice', 'Lebanese seven spice', 1, 'tsp', 'or ground allspice', false),
  ('597dda5d-803b-46af-9288-c605f3c14c06', 12, 'Filling', '¼ tsp ground cinnamon', 'ground cinnamon', 0.25, 'tsp', null, false),
  ('597dda5d-803b-46af-9288-c605f3c14c06', 13, 'Filling', '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('597dda5d-803b-46af-9288-c605f3c14c06', 14, 'Frying', '6 cups vegetable oil, for deep-frying', 'vegetable oil', 6, 'cup', 'for deep-frying', false),
  ('597dda5d-803b-46af-9288-c605f3c14c06', 15, 'To serve', '1 cup plain whole-milk yogurt', 'plain whole-milk yogurt', 1, 'cup', null, false),
  ('597dda5d-803b-46af-9288-c605f3c14c06', 16, 'To serve', '1 lemon, cut into wedges', 'lemon', 1, null, 'cut into wedges', false);
delete from public.recipe_instructions where recipe_id = '597dda5d-803b-46af-9288-c605f3c14c06';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('597dda5d-803b-46af-9288-c605f3c14c06', 1, 'Shell', 'Rinse the bulgur in a sieve, cover with cold water and soak 15 minutes. Drain and squeeze out as much water as you can with your hands.', 900, null, null),
  ('597dda5d-803b-46af-9288-c605f3c14c06', 2, 'Shell', 'In a food processor, pulse the onion, seven spice and salt to a paste. Add the lean beef and bulgur and process, adding ice water a tablespoon at a time, until it forms a smooth, sticky, putty-like dough, about 2 minutes. Refrigerate 30 minutes.', 1920, null, null),
  ('597dda5d-803b-46af-9288-c605f3c14c06', 3, 'Filling', 'Toast the pine nuts in the oil in a skillet over medium heat until golden, 2 minutes; lift out. Cook the onion until soft, 6 minutes, then add the ground beef, spices and salt and cook, breaking it up, until browned and 160°F, about 7 minutes. Stir in the pine nuts and cool.', 900, null, 71.1),
  ('597dda5d-803b-46af-9288-c605f3c14c06', 4, 'Shell', 'With wet hands, roll a golf-ball-sized piece of shell mix. Push your index finger into it and turn it against your palm to make a thin, hollow torpedo about ¼ inch thick. Fill with a tablespoon of filling, pinch closed and taper both ends to a point. Patch any cracks with a wet finger. Chill the shaped kibbeh 10 minutes.', 1800, null, null),
  ('597dda5d-803b-46af-9288-c605f3c14c06', 5, 'Frying', 'Heat the oil in a deep heavy pot — no more than half full — to 350°F. Fry 5 or 6 at a time, turning, until deep brown and the shell reaches 160°F in the middle, 4–5 minutes. Drain on paper towels. Never leave hot oil unattended.', 1200, 176.7, 71.1),
  ('597dda5d-803b-46af-9288-c605f3c14c06', 6, null, 'Serve warm with yogurt and lemon wedges.', null, null, null);

-- Manakish Za'atar
