values ('f2bbc7bd-4adc-4ecf-a28b-c4a96299dd24', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'manakish-zaatar', 'manakish-za-atar-f2bbc7', 'Manakish Za''atar', 'Soft, chewy Lebanese flatbreads spread with a fragrant paste of za''atar and olive oil and baked in a very hot oven — the classic Beirut breakfast.', 'lebanese', 2, 90, 25, 115, 6, 'starter', null, 0, array['oven']::text[], array['vegetarian', 'budget', 'kid-friendly']::text[], array['Za''atar contains sesame seeds, and some commercial blends add wheat or other fillers — check the label.', 'For manakish jibneh, top half the rounds with shredded mozzarella or akkawi cheese instead.']::text[], 'https://images.pexels.com/photos/32592723/pexels-photo-32592723.jpeg', 'Freshly baked za''atar manakish flatbreads on paper', 'Anthony Rahayel', 'https://www.pexels.com/@anthony-rahayel-125801377/', 'https://www.pexels.com/photo/delicious-middle-eastern-manakish-with-zaatar-32592723/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'appetizer', 'holiday', 'budget', 'comfort']::text[], array['bake']::text[], array['tangy', 'fresh', 'aromatic']::text[], array['brunch-party']::text[], null, 'traditional', 'manakish-zaatar', 'classic', 'Best warm. Keep in a bag at room temperature up to 1 day or freeze up to 1 month; warm in a hot oven for 3–4 minutes.', null, 'owned', array['gluten', 'milk', 'sesame', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'dairy_free']::text[], array['instant yeast', 'granulated sugar', 'za atar', 'tomato', 'english cucumber', 'mint']::text[], 'english cucumber|granulated sugar|instant yeast|mint|tomato|za atar',
  null, null, null, null, null, null, null, null)
