  ('f2bbc7bd-4adc-4ecf-a28b-c4a96299dd24', 5, 'Dough', '1 cup warm water', 'warm water', 1, 'cup', null, false),
  ('f2bbc7bd-4adc-4ecf-a28b-c4a96299dd24', 6, 'Dough', '3 tbsp olive oil', 'olive oil', 3, 'tbsp', null, false),
  ('f2bbc7bd-4adc-4ecf-a28b-c4a96299dd24', 7, 'Topping', '½ cup za''atar, a blend of wild thyme, sumac, salt and sesame seeds', 'za''atar', 0.5, 'cup', 'a blend of wild thyme, sumac, salt and sesame seeds', false),
  ('f2bbc7bd-4adc-4ecf-a28b-c4a96299dd24', 8, 'Topping', '½ cup extra-virgin olive oil', 'extra-virgin olive oil', 0.5, 'cup', null, false),
