delete from public.recipe_instructions where recipe_id = 'f2bbc7bd-4adc-4ecf-a28b-c4a96299dd24';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('f2bbc7bd-4adc-4ecf-a28b-c4a96299dd24', 1, 'Dough', 'Mix the flour, yeast, sugar and salt. Add the warm water and oil and knead until smooth and soft, 8 minutes. Cover and leave until doubled, about 1 hour.', 4080, null, null),
  ('f2bbc7bd-4adc-4ecf-a28b-c4a96299dd24', 2, 'Topping', 'Stir the za''atar and olive oil into a loose, spreadable paste.', null, null, null),
  ('f2bbc7bd-4adc-4ecf-a28b-c4a96299dd24', 3, 'Dough', 'Heat the oven to 500°F with a pizza stone or upside-down sheet pan on the lowest rack for 30 minutes. Divide the dough into 6 balls and rest them, covered, 10 minutes.', 1800, 260, null),
  ('f2bbc7bd-4adc-4ecf-a28b-c4a96299dd24', 4, 'Dough', 'On a floured sheet of parchment, press each ball into a 7-inch round about ¼ inch thick. Dimple all over with your fingertips, leaving a slight rim, and spread with 2 tablespoons of the za''atar paste.', null, null, null),
  ('f2bbc7bd-4adc-4ecf-a28b-c4a96299dd24', 5, 'Dough', 'Slide two or three rounds, on their parchment, onto the hot stone and bake until the edges are golden and the bottoms spotty brown, 6–8 minutes. Repeat.', 420, 260, null),
  ('f2bbc7bd-4adc-4ecf-a28b-c4a96299dd24', 6, null, 'Serve warm, folded around tomato, cucumber and mint, with labneh if you like.', null, null, null);

