values ('3f3659c5-5e8b-4b6e-89c2-b81120cade79', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'adana-kebab', 'adana-kebab-3f3659', 'Adana Kebab', 'Long, hand-pressed skewers of fatty minced lamb with red pepper and chili flakes, grilled over hot coals; we use store-bought ground lamb in place of hand-chopped lamb and tail fat.', 'turkish', 3, 30, 12, 102, 4, 'main', null, 60, array['grill']::text[], array['entertaining', 'spicy']::text[], array['Use wide (¾–1 inch) flat skewers; round ones let the meat spin and slide off.', 'No skewers? Shape the meat into long logs and cook them on an oiled grill pan or under the broiler until 160°F.']::text[], 'https://images.pexels.com/photos/7439809/pexels-photo-7439809.jpeg', 'Adana kebab on a wooden plate with greens, tomatoes and flatbread', 'Furkan Tumer', 'https://www.pexels.com/@furkan-tumer-1560109/', 'https://www.pexels.com/photo/flat-lay-photography-of-adana-kebab-on-wooden-plate-7439809/', 'pexels', true, 'public', false,
  'pending_review', array['grilling', 'main', 'dinner', 'entertaining']::text[], array['grill']::text[], array['tangy', 'fresh']::text[], '{}'::text[], null, 'adapted', 'adana-kebab', 'classic', 'Refrigerate up to 3 days. Shaped raw kebabs freeze well on the skewers or off for up to 3 months.', null, 'owned', array['gluten', 'wheat']::text[], array['lamb']::text[], array['dairy_free']::text[], array['ground lamb', 'yellow onion', 'bell pepper', 'aleppo pepper', 'sweet paprika', 'red onion', 'parsley', 'sumac', 'lavash', 'plum tomato', 'green pepper']::text[], 'aleppo pepper|bell pepper|green pepper|ground lamb|lavash|parsley|plum tomato|red onion|sumac|sweet paprika|yellow onion',
  null, null, null, null, null, null, null, null)
