values ('c4d093aa-67de-476c-9800-c19ed2365ded', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'iskender-kebab', 'iskender-kebab-c4d093', 'İskender Kebab', 'Thin slices of seared, onion-marinated lamb over toasted pide with tomato sauce, cool yogurt and sizzling browned butter poured on at the table; we sear sliced lamb in a skillet in place of meat shaved from a vertical rotisserie.', 'turkish', 3, 60, 30, 90, 4, 'main', null, 0, array['stove', 'cast_iron']::text[], array['entertaining', 'comfort']::text[], array['Freeze the lamb for 45 minutes before slicing — it''s much easier to cut paper-thin.', 'A thinly sliced lamb gyro or döner from a Turkish butcher makes an even closer version; just warm it through on the skillet.']::text[], 'https://images.pexels.com/photos/36720642/pexels-photo-36720642.jpeg', 'İskender kebab with yogurt, grilled tomato and pepper on a copper plate', 'Mohamed Olwy', 'https://www.pexels.com/@mohamed9380/', 'https://www.pexels.com/photo/delicious-traditional-turkish-iskender-kebab-dish-36720642/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner', 'comfort', 'entertaining']::text[], array['stew', 'pan_fry']::text[], array['tangy', 'aromatic']::text[], '{}'::text[], 'Bursa', 'adapted', 'iskender-kebab', 'classic', 'Store meat, sauce and yogurt separately up to 3 days; assemble fresh with newly toasted bread and hot butter.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], array['lamb']::text[], '{}'::text[], array['leg lamb', 'yellow onion', 'sweet paprika', 'ground cumin', 'tomato paste', 'canned tomato', 'pide bread', 'greek yogurt']::text[], 'canned tomato|greek yogurt|ground cumin|leg lamb|pide bread|sweet paprika|tomato paste|yellow onion',
  null, null, null, null, null, null, null, null)
