insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('c4d093aa-67de-476c-9800-c19ed2365ded', 1, 'Lamb', 'Toss the sliced lamb with the onion juice, oil, salt, pepper, paprika and cumin. Cover and refrigerate 30 minutes to 2 hours.', 1800, null, null),
  ('c4d093aa-67de-476c-9800-c19ed2365ded', 2, 'Sauce', 'Melt the butter in a saucepan, stir in the tomato and pepper pastes and fry 1 minute. Add the crushed tomatoes, water and salt and simmer until slightly thickened, 10 minutes. Keep warm.', 660, null, null),
  ('c4d093aa-67de-476c-9800-c19ed2365ded', 3, 'Assembly', 'Toast the bread squares in a dry skillet or a 400°F oven until crisp at the edges, 5 minutes, and divide among four warm plates.', 300, 204.4, null),
  ('c4d093aa-67de-476c-9800-c19ed2365ded', 4, 'Lamb', 'Heat a cast-iron skillet over high heat until smoking. Sear the lamb in a single layer in batches, 1–2 minutes, turning once, until browned at the edges and 145°F. Pile each batch onto a warm plate.', 600, null, 62.8),
  ('c4d093aa-67de-476c-9800-c19ed2365ded', 5, 'Assembly', 'Spoon a little sauce over the bread, lay the lamb on top and spoon over more sauce. Add a big dollop of yogurt beside the meat and a charred pepper.', null, null, null),
  ('c4d093aa-67de-476c-9800-c19ed2365ded', 6, 'Assembly', 'Melt the butter in a small pan until it foams and smells nutty, about 3 minutes. Pour it, sizzling, over the meat at the table and eat right away.', 180, null, null);

