values ('82d0b5a0-ce1a-422e-81e6-83978f703673', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'lahmacun', 'lahmacun-82d0b5', 'Lahmacun', 'Paper-thin flatbreads spread with a spiced paste of minced lamb, tomato, pepper and parsley, baked until crisp at the edges and rolled up with lemon and herbs.', 'turkish', 3, 100, 35, 135, 4, 'main', null, 0, array['oven', 'food_processor']::text[], array['entertaining']::text[], array['Keep the meat layer thin — a thick layer won''t cook through before the bread overbakes.', 'Store-bought pizza dough (1½ lb) works well when you''re short on time.']::text[], 'https://images.unsplash.com/photo-1777891257696-29f0d175f236', 'Round lahmacun flatbread topped with spiced ground meat, herbs and a lemon slice', 'Husien Bisky', 'https://unsplash.com/@husien_bisky1', 'https://unsplash.com/photos/a-round-flatbread-topped-with-seasoned-ground-meat-and-herbs-ueeQYUce-P8', 'unsplash', true, 'public', false,
  'pending_review', array['baking', 'main', 'dinner', 'entertaining']::text[], array['bake']::text[], array['tangy', 'fresh', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'lahmacun', 'classic', 'Refrigerate up to 3 days or freeze up to 2 months; reheat in a hot skillet or a 425°F oven for 4–5 minutes.', null, 'owned', array['gluten', 'wheat']::text[], array['lamb']::text[], array['dairy_free']::text[], array['instant yeast', 'granulated sugar', 'yellow onion', 'plum tomato', 'bell pepper', 'garlic', 'parsley', 'ground lamb', 'tomato paste', 'aleppo pepper', 'ground cumin', 'red onion', 'lemon']::text[], 'aleppo pepper|bell pepper|garlic|granulated sugar|ground cumin|ground lamb|instant yeast|lemon|parsley|plum tomato|red onion|tomato paste|yellow onion',
