insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('82d0b5a0-ce1a-422e-81e6-83978f703673', 1, 'Dough', 'Mix the flour, yeast, sugar and salt, add the warm water and oil and knead until smooth, 8 minutes. Cover and leave until doubled, about 1 hour.', 4080, null, null),
  ('82d0b5a0-ce1a-422e-81e6-83978f703673', 2, 'Topping', 'Pulse the onion, tomato, bell pepper, garlic and parsley in a food processor until finely chopped but not liquid. Add the lamb, pastes, Aleppo pepper, cumin and salt and pulse to a soft, spreadable paste.', null, null, null),
  ('82d0b5a0-ce1a-422e-81e6-83978f703673', 3, 'Dough', 'Heat the oven to 500°F with a pizza stone or upside-down sheet pan on the lowest rack for 30 minutes. Divide the dough into 8 balls and rest 10 minutes.', 1800, 260, null),
  ('82d0b5a0-ce1a-422e-81e6-83978f703673', 4, 'Dough', 'On floured parchment, roll each ball into a very thin oval, about 10 by 7 inches. Spread a thin, even layer of the meat paste right to the edges with the back of a spoon or wet fingers.', null, null, null),
  ('82d0b5a0-ce1a-422e-81e6-83978f703673', 5, 'Dough', 'Slide two at a time, on their parchment, onto the hot stone and bake until the edges are crisp and browned and the topping is cooked through and 160°F, 7–9 minutes. Stack them, meat-side together, under a towel so they stay soft enough to roll.', 480, 260, 71.1),
  ('82d0b5a0-ce1a-422e-81e6-83978f703673', 6, null, 'Serve warm: scatter with parsley and sumac onion, squeeze over lemon and roll up to eat.', null, null, null);

-- Chelo Kabab Koobideh
