values ('d9128a4f-1458-48fc-a364-c99596550831', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chelo-kabab-koobideh', 'chelo-kabab-koobideh-d9128a', 'Chelo Kabab Koobideh', 'Juicy skewers of minced lamb and beef with grated onion, grilled over high heat and served on fluffy saffron basmati with charred tomatoes, butter and sumac.', 'persian', 3, 90, 60, 150, 6, 'main', null, 0, array['grill', 'stove']::text[], array['entertaining']::text[], array['Squeeze the grated onion really dry; extra water is why koobideh slides off skewers.', 'No wide skewers? Shape flat logs and cook them on a hot grill pan until 160°F.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['grilling', 'main', 'dinner', 'entertaining']::text[], array['grill', 'steam', 'boil']::text[], array['tangy', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'kabab-koobideh', 'classic', 'Refrigerate kebabs and rice separately up to 3 days. Reheat rice with a splash of water, covered.', null, 'owned', array['milk']::text[], array['beef', 'lamb']::text[], array['gluten_free']::text[], array['basmati rice', 'saffron thread', 'ground lamb', 'ground beef', 'yellow onion', 'ground turmeric', 'plum tomato', 'sumac']::text[], 'basmati rice|ground beef|ground lamb|ground turmeric|plum tomato|saffron thread|sumac|yellow onion',
  null, null, null, null, null, null, null, null)
