insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('d9128a4f-1458-48fc-a364-c99596550831', 1, 'Rice', '2 cups basmati rice', 'basmati rice', 2, 'cup', null, false),
  ('d9128a4f-1458-48fc-a364-c99596550831', 2, 'Rice', '2 tbsp kosher salt, for the cooking water', 'kosher salt', 2, 'tbsp', 'for the cooking water', false),
  ('d9128a4f-1458-48fc-a364-c99596550831', 3, 'Rice', '4 tbsp unsalted butter, divided', 'unsalted butter', 4, 'tbsp', 'divided', false),
  ('d9128a4f-1458-48fc-a364-c99596550831', 4, 'Rice', '½ tsp saffron threads', 'saffron threads', 0.5, 'tsp', null, false),
  ('d9128a4f-1458-48fc-a364-c99596550831', 5, 'Rice', '3 tbsp hot water', 'hot water', 3, 'tbsp', null, false),
  ('d9128a4f-1458-48fc-a364-c99596550831', 6, 'Kabab', '1 lb ground lamb', 'ground lamb', 1, 'lb', null, false),
  ('d9128a4f-1458-48fc-a364-c99596550831', 7, 'Kabab', '1 lb ground beef, 80% lean', 'ground beef', 1, 'lb', '80% lean', false),
  ('d9128a4f-1458-48fc-a364-c99596550831', 8, 'Kabab', '1 large yellow onion, grated and squeezed very dry', 'large yellow onion', 1, null, 'grated and squeezed very dry', false),
  ('d9128a4f-1458-48fc-a364-c99596550831', 9, 'Kabab', '1½ tsp kosher salt', 'kosher salt', 1.5, 'tsp', null, false),
  ('d9128a4f-1458-48fc-a364-c99596550831', 10, 'Kabab', '1 tsp black pepper', 'black pepper', 1, 'tsp', null, false),
  ('d9128a4f-1458-48fc-a364-c99596550831', 11, 'Kabab', '½ tsp ground turmeric', 'ground turmeric', 0.5, 'tsp', null, false),
  ('d9128a4f-1458-48fc-a364-c99596550831', 12, 'To serve', '6 plum tomatoes', 'plum tomatoes', 6, null, null, false),
  ('d9128a4f-1458-48fc-a364-c99596550831', 13, 'To serve', '2 tsp sumac', 'sumac', 2, 'tsp', null, false);
delete from public.recipe_instructions where recipe_id = 'd9128a4f-1458-48fc-a364-c99596550831';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('d9128a4f-1458-48fc-a364-c99596550831', 1, 'Rice', 'Rinse the rice in several changes of water until it runs clear, then soak in lukewarm water for 1 hour. Grind the saffron with a pinch of sugar or salt and steep it in the hot water.', 3600, null, null),
  ('d9128a4f-1458-48fc-a364-c99596550831', 2, 'Kabab', 'Knead the lamb, beef, onion, salt, pepper and turmeric firmly for 5 minutes until sticky and smooth. Cover and refrigerate at least 1 hour (or overnight).', 3900, null, null),
  ('d9128a4f-1458-48fc-a364-c99596550831', 3, 'Rice', 'Bring 3 quarts of water and the salt to a rolling boil. Drain the rice, add it and boil until the grains are soft outside but still firm in the center, 5–7 minutes. Drain and rinse with lukewarm water.', 480, null, null),
  ('d9128a4f-1458-48fc-a364-c99596550831', 4, 'Rice', 'Melt 2 tablespoons of the butter with 2 tablespoons of water in a nonstick pot, then mound the rice back in. Poke a few holes to the bottom with a spoon handle, wrap the lid in a towel (tie up the corners, away from the flame), cover and steam on low for 45 minutes.', 2700, null, null),
  ('d9128a4f-1458-48fc-a364-c99596550831', 5, 'Kabab', 'Heat the grill to high. With wet hands, press each portion of meat (about 5 oz) along a wide flat skewer into a long, flat kebab, pinching ridges every inch. Grill the tomatoes on skewers too.', 900, null, null),
  ('d9128a4f-1458-48fc-a364-c99596550831', 6, 'Kabab', 'Grill the kebabs, turning often for the first minute so the meat sets on the skewer, then every 2 minutes until browned and 160°F, 7–9 minutes in all.', 540, null, 71.1),
  ('d9128a4f-1458-48fc-a364-c99596550831', 7, null, 'Mix a cup of rice with the saffron water to tint it gold. Plate the white rice topped with the saffron rice and a pat of the remaining butter, the kebabs slid off their skewers and the charred tomatoes. Sprinkle with sumac.', null, null, null);

-- Tahdig
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
