values ('2c8bd46f-e9e4-4726-a748-f6a8e118c8db', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'tahdig', 'tahdig-2c8bd4', 'Tahdig', 'Persian steamed basmati with a golden, crunchy crust of saffron-yogurt rice on the bottom, turned out like a cake — the yogurt version is the most common.', 'persian', 4, 75, 70, 145, 6, 'side', null, 0, array['stove']::text[], array['vegetarian', 'entertaining']::text[], array['A good nonstick pot with straight sides is the single biggest key to a crust that releases in one piece.', 'For potato tahdig, line the oiled pot with ¼-inch potato slices instead of the yogurt rice.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['side', 'entertaining']::text[], array['steam', 'boil']::text[], array['tangy']::text[], '{}'::text[], null, 'traditional', 'tahdig', 'classic', 'The crust is best right away. Refrigerate leftover rice up to 3 days and reheat covered with a splash of water.', null, 'owned', array['milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['basmati rice', 'saffron thread', 'whole-milk yogurt']::text[], 'basmati rice|saffron thread|whole-milk yogurt',
  null, null, null, null, null, null, null, null)
