  ('2c8bd46f-e9e4-4726-a748-f6a8e118c8db', 1, null, '2 cups basmati rice', 'basmati rice', 2, 'cup', null, false),
  ('2c8bd46f-e9e4-4726-a748-f6a8e118c8db', 2, null, '2 tbsp kosher salt, for the cooking water', 'kosher salt', 2, 'tbsp', 'for the cooking water', false),
  ('2c8bd46f-e9e4-4726-a748-f6a8e118c8db', 3, null, '½ tsp saffron threads', 'saffron threads', 0.5, 'tsp', null, false),
  ('2c8bd46f-e9e4-4726-a748-f6a8e118c8db', 4, null, '3 tbsp hot water', 'hot water', 3, 'tbsp', null, false),
  ('2c8bd46f-e9e4-4726-a748-f6a8e118c8db', 5, null, '½ cup plain whole-milk yogurt', 'plain whole-milk yogurt', 0.5, 'cup', null, false),
  ('2c8bd46f-e9e4-4726-a748-f6a8e118c8db', 6, null, '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('2c8bd46f-e9e4-4726-a748-f6a8e118c8db', 7, null, '⅓ cup vegetable oil', 'vegetable oil', 0.33, 'cup', null, false),
