delete from public.recipe_instructions where recipe_id = '2c8bd46f-e9e4-4726-a748-f6a8e118c8db';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('2c8bd46f-e9e4-4726-a748-f6a8e118c8db', 1, null, 'Rinse the rice in several changes of water until it runs clear, then soak it in lukewarm water for 1 hour. Grind the saffron with a pinch of salt and steep it in the hot water.', 3600, null, null),
  ('2c8bd46f-e9e4-4726-a748-f6a8e118c8db', 2, null, 'Bring 3 quarts of water and the 2 tablespoons of salt to a rolling boil. Drain the rice, add it and boil until soft outside but firm in the center, 5–6 minutes. Drain and rinse briefly with lukewarm water.', 480, null, null),
  ('2c8bd46f-e9e4-4726-a748-f6a8e118c8db', 3, null, 'Mix 1½ cups of the rice with the yogurt, the ¼ tsp salt and half the saffron water.', null, null, null),
  ('2c8bd46f-e9e4-4726-a748-f6a8e118c8db', 4, null, 'Heat the oil and 1 tablespoon of the butter in a 10-inch nonstick pot over medium heat until shimmering. Press the yogurt rice firmly over the bottom. Mound the rest of the rice on top in a pyramid, and poke 5 holes to the bottom with a spoon handle.', 180, null, null),
  ('2c8bd46f-e9e4-4726-a748-f6a8e118c8db', 5, null, 'Wrap the lid in a clean kitchen towel, tying the corners on top so nothing hangs near the flame, and cover tightly. Cook on medium until you hear a steady sizzle and see steam, about 10 minutes.', 600, null, null),
  ('2c8bd46f-e9e4-4726-a748-f6a8e118c8db', 6, null, 'Turn the heat to low and steam 45–50 minutes, until the rice is fluffy and the crust is golden (peek at an edge with a spatula). Drizzle the remaining saffron water and melted butter over the top.', 2880, null, null),
  ('2c8bd46f-e9e4-4726-a748-f6a8e118c8db', 7, null, 'Set the pot in a sink with 1 inch of cold water for 1 minute to loosen the crust. Put a platter on top and flip confidently. Serve at once, breaking the crust into pieces at the table.', 120, null, null);

-- Fesenjan
