values ('82c5cc82-e729-46b3-84ed-658bcbe329c2', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'fesenjan', 'fesenjan-82c5cc', 'Fesenjan', 'Chicken simmered slowly in a dark, glossy sauce of ground toasted walnuts and pomegranate molasses — sweet, sour and rich; chicken is the most common choice, though duck and meatballs are traditional too.', 'persian', 3, 20, 130, 150, 6, 'main', null, 0, array['stove', 'dutch_oven', 'food_processor']::text[], array['entertaining', 'make-ahead']::text[], array['Pomegranate molasses varies a lot in sourness — add the sugar a little at a time.', 'Like most stews, it''s even better the next day.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['holiday', 'main', 'dinner', 'entertaining']::text[], array['stew', 'pan_fry']::text[], array['aromatic']::text[], '{}'::text[], null, 'traditional', 'fesenjan', 'classic', 'Refrigerate up to 4 days or freeze up to 3 months. Reheat gently with a splash of water.', null, 'owned', array['tree_nut']::text[], array['chicken']::text[], array['gluten_free', 'dairy_free']::text[], array['walnut halve', 'chicken thigh', 'yellow onion', 'ground turmeric', 'ground cinnamon', 'pomegranate molasse']::text[], 'chicken thigh|ground cinnamon|ground turmeric|pomegranate molasse|walnut halve|yellow onion',
  null, null, null, null, null, null, null, null)
