values ('ee65a98c-0518-4d87-a299-da0740808f36', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-bastilla', 'chicken-bastilla-ee65a9', 'Chicken Bastilla', 'A showpiece pie from Fez: saffron-and-ginger braised chicken, lemony herbed eggs and sweet cinnamon almonds layered in crisp pastry and dusted with powdered sugar; we use phyllo in place of hand-made warqa and chicken in place of the original pigeon.', 'moroccan', 4, 60, 115, 175, 8, 'main', null, 0, array['stove', 'oven', 'dutch_oven', 'food_processor']::text[], array['entertaining', 'make-ahead']::text[], array['Make the filling a day ahead and keep it chilled; assemble and bake just before guests arrive.', 'Seafood bastilla, with shrimp, white fish and vermicelli, is another popular version — leave off the sugar and cinnamon for that.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['entertaining', 'main', 'dinner', 'holiday']::text[], array['stew', 'bake', 'boil']::text[], array['tangy', 'fresh', 'aromatic']::text[], array['dinner-party', 'eid-al-fitr']::text[], 'Fez', 'adapted', 'chicken-bastilla', 'classic', 'Refrigerate up to 3 days; re-crisp at 350°F for 15–20 minutes.', null, 'owned', array['egg', 'gluten', 'milk', 'tree_nut', 'wheat']::text[], array['chicken']::text[], '{}'::text[], array['yellow onion', 'ground ginger', 'ground cinnamon', 'ground turmeric', 'saffron thread', 'cilantro', 'parsley', 'egg', 'lemon juice', 'blanched almond', 'powdered sugar', 'phyllo dough']::text[], 'blanched almond|cilantro|egg|ground cinnamon|ground ginger|ground turmeric|lemon juice|parsley|phyllo dough|powdered sugar|saffron thread|yellow onion',
  null, null, null, null, null, null, null, null)
