delete from public.recipe_instructions where recipe_id = 'ee65a98c-0518-4d87-a299-da0740808f36';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('ee65a98c-0518-4d87-a299-da0740808f36', 1, 'Chicken', 'Put the chicken, onions, butter, spices, salt, pepper, herbs and water in a Dutch oven. Bring to a simmer, cover and cook gently, turning once, until the chicken is falling off the bone and 165°F, about 50 minutes.', 3000, null, 73.9),
  ('ee65a98c-0518-4d87-a299-da0740808f36', 2, 'Chicken', 'Lift out the chicken, cool slightly and shred the meat, discarding skin and bones. Boil the sauce uncovered, stirring, until reduced to about 1½ cups, 15 minutes.', 900, null, null),
  ('ee65a98c-0518-4d87-a299-da0740808f36', 3, 'Eggs', 'Lower the heat, stir the lemon juice into the beaten eggs and pour them into the simmering sauce. Stir slowly until the eggs form soft, moist curds with no liquid egg left (160°F), 5–6 minutes. Drain in a sieve so the filling isn''t wet, and cool.', 360, null, 71.1),
  ('ee65a98c-0518-4d87-a299-da0740808f36', 4, 'Almonds', 'Fry the almonds in the oil over medium heat, stirring, until golden, 5 minutes. Cool, then pulse in a food processor with the powdered sugar and cinnamon until coarsely ground.', 300, null, null),
  ('ee65a98c-0518-4d87-a299-da0740808f36', 5, 'Assembly', 'Heat the oven to 375°F. Brush a 10-inch round cake pan or ovenproof skillet with butter. Lay in 7 phyllo sheets, brushing each with butter and fanning them so they cover the base and hang well over the sides.', null, 190.6, null),
  ('ee65a98c-0518-4d87-a299-da0740808f36', 6, 'Assembly', 'Spread the egg mixture in the pan, top with the chicken, then the almond mixture. Fold the overhanging phyllo over the filling, brushing with butter, then cover with the remaining 5 sheets, buttered and tucked under the edge like a bedsheet. Brush the top with butter.', null, null, null),
  ('ee65a98c-0518-4d87-a299-da0740808f36', 7, 'Assembly', 'Bake until deep golden and crisp, 35–40 minutes. Rest 10 minutes, invert onto a platter if you like a flat top, then dust with powdered sugar and draw a lattice of cinnamon over it.', 2280, 190.6, null);

