values ('1ce6de48-96b5-4862-8bca-a4ce58e94645', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'lablabi', 'lablabi-1ce6de', 'Lablabi', 'Tunisia''s beloved chickpea soup with garlic, cumin and harissa, ladled over torn bread and finished with a soft egg, olive oil, capers and lemon.', 'tunisian', 3, 740, 110, 850, 4, 'main', null, 0, array['stove']::text[], array['budget', 'vegetarian', 'comfort']::text[], array['Short on time? Use three 15-oz cans of chickpeas, rinsed, with 6 cups of water and simmer 20 minutes.', 'Some harissa brands add other ingredients such as wheat or nuts — check the label if allergies matter.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'budget', 'comfort']::text[], array['stew', 'poach', 'boil']::text[], array['spicy', 'tangy', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'lablabi', 'classic', 'Refrigerate the soup (without bread or eggs) up to 4 days or freeze up to 3 months.', 'The eggs here aren''t cooked to 160°F. Use pasteurized eggs if you''re serving anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['egg', 'fish', 'gluten', 'wheat']::text[], array['beans']::text[], array['pescatarian', 'vegetarian', 'dairy_free']::text[], array['dried chickpea', 'garlic', 'bay leaf', 'ground cumin', 'harissa paste', 'lemon', 'crusty bread', 'egg', 'caper']::text[], 'bay leaf|caper|crusty bread|dried chickpea|egg|garlic|ground cumin|harissa paste|lemon',
  null, null, null, null, null, null, null, null)
