  ('1ce6de48-96b5-4862-8bca-a4ce58e94645', 6, 'Soup', '2 tsp ground cumin, plus more to serve', 'ground cumin', 2, 'tsp', 'plus more to serve', false),
  ('1ce6de48-96b5-4862-8bca-a4ce58e94645', 7, 'Soup', '2 tbsp harissa paste, plus more to serve', 'harissa paste', 2, 'tbsp', 'plus more to serve', false),
  ('1ce6de48-96b5-4862-8bca-a4ce58e94645', 8, 'Soup', '2 tbsp olive oil', 'olive oil', 2, 'tbsp', null, false),
  ('1ce6de48-96b5-4862-8bca-a4ce58e94645', 9, 'Soup', '1 lemon, juiced', 'lemon', 1, null, 'juiced', false),
  ('1ce6de48-96b5-4862-8bca-a4ce58e94645', 10, 'Bowls', '6 oz day-old crusty bread, torn into bite-size pieces', 'day-old crusty bread', 6, 'oz', 'torn into bite-size pieces', false),
  ('1ce6de48-96b5-4862-8bca-a4ce58e94645', 11, 'Bowls', '4 large eggs', 'large eggs', 4, null, null, false),
