delete from public.recipe_instructions where recipe_id = '1ce6de48-96b5-4862-8bca-a4ce58e94645';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('1ce6de48-96b5-4862-8bca-a4ce58e94645', 1, 'Soup', 'The night before, cover the chickpeas with plenty of cold water and soak at least 12 hours. Drain.', 43200, null, null),
  ('1ce6de48-96b5-4862-8bca-a4ce58e94645', 2, 'Soup', 'Put the chickpeas, water, smashed garlic and bay leaf in a large pot. Bring to a boil, skim any foam, then simmer partly covered until very tender, 1½–2 hours, adding the salt in the last 30 minutes.', 6000, null, null),
  ('1ce6de48-96b5-4862-8bca-a4ce58e94645', 3, 'Soup', 'Stir in the grated garlic, cumin, harissa, olive oil and lemon juice and simmer 5 minutes. The broth should be well seasoned and a little spicy.', 300, null, null),
  ('1ce6de48-96b5-4862-8bca-a4ce58e94645', 4, 'Bowls', 'Meanwhile, bring a small pan of water to a gentle simmer. Crack in the eggs and poach until the whites are set but the yolks still runny, about 3½ minutes (5–6 minutes for firm yolks). Lift out with a slotted spoon.', 240, null, null),
  ('1ce6de48-96b5-4862-8bca-a4ce58e94645', 5, 'Bowls', 'Put a handful of bread in each bowl and ladle the hot chickpeas and broth over it. Top with an egg, a drizzle of olive oil, the capers, tuna if using, an extra pinch of cumin and a dab of harissa. Serve with lemon wedges and break the egg into the soup as you eat.', null, null, null);

