values ('fcc815a6-2512-4595-8580-29349aea149e', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'key-wat', 'key-wat-fcc815', 'Key Wat', 'Tender beef simmered in a deep red sauce of slow-cooked onions, berbere and spiced butter — Ethiopia''s fiery beef stew, made for scooping up with injera.', 'ethiopian', 3, 25, 150, 175, 6, 'main', null, 0, array['stove', 'dutch_oven', 'food_processor']::text[], array['spicy', 'make-ahead', 'freezer-friendly']::text[], array['No niter kibbeh? Gently simmer the butter for 10 minutes with a smashed garlic clove, a slice of ginger, ½ tsp fenugreek seeds and ¼ tsp turmeric, then strain.', 'Berbere heat varies widely by brand; start with 2 tablespoons if you''re unsure.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner']::text[], array['stew']::text[], array['aromatic']::text[], '{}'::text[], null, 'traditional', 'key-wat', 'classic', 'Refrigerate up to 4 days or freeze up to 3 months; the flavor deepens overnight.', null, 'owned', array['milk']::text[], array['beef']::text[], array['gluten_free']::text[], array['red onion', 'clarified butter', 'berbere spice', 'tomato paste', 'garlic', 'ginger', 'beef chuck', 'ground cardamom']::text[], 'beef chuck|berbere spice|clarified butter|garlic|ginger|ground cardamom|red onion|tomato paste',
  null, null, null, null, null, null, null, null)
