  ('fcc815a6-2512-4595-8580-29349aea149e', 2, null, '⅓ cup spiced clarified butter (niter kibbeh), or unsalted butter', 'spiced clarified butter (niter kibbeh)', 0.33, 'cup', 'or unsalted butter', false),
  ('fcc815a6-2512-4595-8580-29349aea149e', 3, null, '¼ cup berbere spice, use less for a milder stew', 'berbere spice', 0.25, 'cup', 'use less for a milder stew', false),
  ('fcc815a6-2512-4595-8580-29349aea149e', 4, null, '2 tbsp tomato paste', 'tomato paste', 2, 'tbsp', null, false),
  ('fcc815a6-2512-4595-8580-29349aea149e', 5, null, '5 cloves garlic, minced', 'garlic', 5, 'clove', 'minced', false),
  ('fcc815a6-2512-4595-8580-29349aea149e', 6, null, '1 tbsp fresh ginger, grated', 'fresh ginger', 1, 'tbsp', 'grated', false),
  ('fcc815a6-2512-4595-8580-29349aea149e', 7, null, '2 lb beef chuck, cut into ¾-inch cubes', 'beef chuck', 2, 'lb', 'cut into ¾-inch cubes', false),
