insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('fcc815a6-2512-4595-8580-29349aea149e', 1, null, 'Pulse the onions in a food processor until very finely chopped, almost a paste. Cook them in a dry Dutch oven over medium-low heat, stirring often, until reduced, soft and jammy, about 30 minutes; add a splash of water if they catch.', 1800, null, null),
  ('fcc815a6-2512-4595-8580-29349aea149e', 2, null, 'Add the spiced butter, berbere and tomato paste and cook, stirring, until deep brick red and the butter starts to separate, about 10 minutes. Stir in the garlic and ginger for 2 minutes.', 720, null, null),
  ('fcc815a6-2512-4595-8580-29349aea149e', 3, null, 'Add the beef and stir to coat, cooking 5 minutes. Pour in the water and add the salt.', 300, null, null),
  ('fcc815a6-2512-4595-8580-29349aea149e', 4, null, 'Cover and simmer gently, stirring now and then and adding water as needed, until the beef is fork-tender (well past 145°F) and the sauce is thick, 1½–1¾ hours.', 6000, null, 62.8),
  ('fcc815a6-2512-4595-8580-29349aea149e', 5, null, 'Stir in the cardamom, simmer 5 minutes, then taste for salt. Serve with injera or rice.', 300, null, null);

-- Injera
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
