values ('eb4d0246-2049-4c76-ab3d-df7bdd62d6f9', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'injera-teff', 'injera-eb4d02', 'Injera', 'Spongy, tangy Ethiopian flatbread made the traditional way from 100% teff flour fermented for about two days, then steamed on one side in a skillet until covered in tiny holes.', 'ethiopian', 4, 2880, 50, 2930, 8, 'side', null, 0, array['stove']::text[], array['make-ahead', 'vegan']::text[], array['Look for teff flour at health-food stores, Ethiopian grocers or online. If your first ones are gummy, the batter is too thick or the pan too cool.', 'Many Ethiopian-American cooks replace a quarter of the teff with all-purpose or barley flour for easier handling — note that this adds gluten.']::text[], 'https://images.pexels.com/photos/17486836/pexels-photo-17486836.jpeg', 'Injera topped with colourful Ethiopian vegetable stews on a white plate', 'Deane Bayas', 'https://www.pexels.com/@dbaler/', 'https://www.pexels.com/photo/meal-on-plate-17486836/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'side']::text[], array['steam']::text[], '{}'::text[], '{}'::text[], null, 'traditional', 'injera', 'classic', 'Wrap the cooled stack in a towel inside a bag and keep at room temperature up to 2 days or refrigerated up to 1 week; warm briefly in a covered skillet.', 'This batter is fermented at home. Use a very clean bowl and spoon and keep it loosely covered. A sour smell and a layer of gray-brown liquid on top are normal; throw it out if you see fuzzy mold or pink, orange or black spots, or it smells rotten.', 'owned', '{}'::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], array['ground teff', 'lukewarm water']::text[], 'ground teff|lukewarm water',
  null, null, null, null, null, null, null, null)
