delete from public.recipe_ingredients where recipe_id = 'eb4d0246-2049-4c76-ab3d-df7bdd62d6f9';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('eb4d0246-2049-4c76-ab3d-df7bdd62d6f9', 1, null, '3 cups ground teff, ivory or brown, about 15 oz', 'ground teff', 3, 'cup', 'ivory or brown, about 15 oz', false),
  ('eb4d0246-2049-4c76-ab3d-df7bdd62d6f9', 2, null, '4 cups lukewarm water, filtered or left out overnight, divided', 'lukewarm water', 4, 'cup', 'filtered or left out overnight, divided', false),
  ('eb4d0246-2049-4c76-ab3d-df7bdd62d6f9', 3, null, '¼ tsp active dry yeast, to help get it started', 'active dry yeast', 0.25, 'tsp', 'to help get it started', true),
  ('eb4d0246-2049-4c76-ab3d-df7bdd62d6f9', 4, null, '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('eb4d0246-2049-4c76-ab3d-df7bdd62d6f9', 5, null, '1 tsp vegetable oil, for the pan', 'vegetable oil', 1, 'tsp', 'for the pan', true);
delete from public.recipe_instructions where recipe_id = 'eb4d0246-2049-4c76-ab3d-df7bdd62d6f9';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('eb4d0246-2049-4c76-ab3d-df7bdd62d6f9', 1, null, 'In a large glass or ceramic bowl, whisk the ground teff, 3 cups of the water and the yeast (if using) into a smooth, thick batter. Cover loosely with a clean towel and leave at warm room temperature (70–75°F), stirring once a day, until bubbly and pleasantly sour, about 2 days.', 172800, null, null),
  ('eb4d0246-2049-4c76-ab3d-df7bdd62d6f9', 2, null, 'Carefully pour off the dark liquid that has collected on top. Whisk ½ cup of the batter with ½ cup of the remaining water in a small saucepan and stir over medium heat until it thickens like pudding, 2–3 minutes. Cool to warm and stir it back into the batter (this ''absit'' helps the holes form).', 300, null, null),
  ('eb4d0246-2049-4c76-ab3d-df7bdd62d6f9', 3, null, 'Leave the batter until it rises and looks foamy, 30–60 minutes, then stir in the salt and enough of the remaining water to make it the consistency of heavy cream.', 2700, null, null),
  ('eb4d0246-2049-4c76-ab3d-df7bdd62d6f9', 4, null, 'Heat a 12-inch nonstick skillet with a lid over medium heat; wipe it with a little oil only if it tends to stick. Pour about ½ cup batter in a spiral from the outside in and tilt to fill any gaps in a thin, even layer.', 180, null, null),
  ('eb4d0246-2049-4c76-ab3d-df7bdd62d6f9', 5, null, 'Cook uncovered until holes appear all over the surface, about 30 seconds, then cover and steam until the top is dry and the edges lift away, 1–2 minutes more. Don''t flip it.', 120, null, null),
  ('eb4d0246-2049-4c76-ab3d-df7bdd62d6f9', 6, null, 'Slide onto a clean towel to cool completely in a single layer before stacking, and keep going with the rest of the batter (about 10 injera).', 1800, null, null);

-- Egusi Soup
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
