values ('016af92a-fa07-4340-a4d6-876b803b5a35', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'egusi-soup', 'egusi-soup-016af9', 'Egusi Soup', 'A rich Nigerian soup of ground melon seeds fried in palm oil with peppers, simmered with tender beef, smoked fish and crayfish and finished with plenty of greens; beef is the most common meat.', 'nigerian', 3, 30, 100, 130, 6, 'main', null, 0, array['stove', 'dutch_oven', 'blender']::text[], array['comfort', 'spicy', 'make-ahead']::text[], array['Bouillon cubes often contain wheat, soy, milk or celery, and crayfish is a shellfish — check labels if allergies matter.', 'Find ground egusi, red palm oil and ground crayfish at African grocers or online; pumpkin seeds ground fine are a rough stand-in for egusi.']::text[], 'https://images.pexels.com/photos/35490114/pexels-photo-35490114.jpeg', 'Nigerian egusi soup with red peppers and herbs in a red bowl', 'Tim Yisa', 'https://www.pexels.com/@tim-yisa-1040794498/', 'https://www.pexels.com/photo/spicy-nigerian-egusi-soup-in-red-bowl-35490114/', 'pexels', true, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'grilling', 'comfort']::text[], array['smoke', 'stew']::text[], array['spicy', 'smoky']::text[], '{}'::text[], null, 'traditional', 'egusi-soup', 'classic', 'Refrigerate up to 4 days or freeze up to 3 months. Reheat gently with a splash of water.', null, 'owned', array['fish', 'shellfish']::text[], array['beef', 'shellfish']::text[], array['dairy_free']::text[], array['beef chuck', 'yellow onion', 'bouillon cube', 'bell pepper', 'bonnet pepper', 'egusi seed', 'palm oil', 'dried crayfish', 'spinach']::text[], 'beef chuck|bell pepper|bonnet pepper|bouillon cube|dried crayfish|egusi seed|palm oil|spinach|yellow onion',
  null, null, null, null, null, null, null, null)
