insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('016af92a-fa07-4340-a4d6-876b803b5a35', 1, 'Beef', '2 lb beef chuck, cut into 1½-inch cubes', 'beef chuck', 2, 'lb', 'cut into 1½-inch cubes', false),
  ('016af92a-fa07-4340-a4d6-876b803b5a35', 2, 'Beef', '1 yellow onion, half chopped, half reserved for the pepper base', 'yellow onion', 1, null, 'half chopped, half reserved for the pepper base', false),
  ('016af92a-fa07-4340-a4d6-876b803b5a35', 3, 'Beef', '2 bouillon cubes, crumbled', 'bouillon cubes', 2, null, 'crumbled', false),
  ('016af92a-fa07-4340-a4d6-876b803b5a35', 4, 'Beef', '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('016af92a-fa07-4340-a4d6-876b803b5a35', 5, 'Beef', '5 cups water', 'water', 5, 'cup', null, false),
  ('016af92a-fa07-4340-a4d6-876b803b5a35', 6, 'Soup', '2 red bell peppers, seeded', 'red bell peppers', 2, null, 'seeded', false),
  ('016af92a-fa07-4340-a4d6-876b803b5a35', 7, 'Soup', '1 Scotch bonnet pepper, seeded for less heat', 'Scotch bonnet pepper', 1, null, 'seeded for less heat', false),
  ('016af92a-fa07-4340-a4d6-876b803b5a35', 8, 'Soup', '1½ cups ground egusi seeds, melon seeds', 'ground egusi seeds', 1.5, 'cup', 'melon seeds', false),
  ('016af92a-fa07-4340-a4d6-876b803b5a35', 9, 'Soup', '½ cup red palm oil', 'red palm oil', 0.5, 'cup', null, false),
  ('016af92a-fa07-4340-a4d6-876b803b5a35', 10, 'Soup', '2 tbsp ground dried crayfish', 'ground dried crayfish', 2, 'tbsp', null, false),
  ('016af92a-fa07-4340-a4d6-876b803b5a35', 11, 'Soup', '6 oz smoked mackerel, skin and bones removed, flaked', 'smoked mackerel', 6, 'oz', 'skin and bones removed, flaked', true),
  ('016af92a-fa07-4340-a4d6-876b803b5a35', 12, 'Soup', '10 oz fresh spinach, roughly chopped', 'fresh spinach', 10, 'oz', 'roughly chopped', false);
delete from public.recipe_instructions where recipe_id = '016af92a-fa07-4340-a4d6-876b803b5a35';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('016af92a-fa07-4340-a4d6-876b803b5a35', 1, 'Beef', 'Put the beef, chopped onion, bouillon cubes and salt in a Dutch oven and cook over medium heat, stirring, for 10 minutes as the meat releases its juices. Add the water, cover and simmer until tender (well past 145°F), about 1 hour.', 4200, null, 62.8),
  ('016af92a-fa07-4340-a4d6-876b803b5a35', 2, 'Soup', 'Blend the bell peppers, Scotch bonnet and reserved onion half until smooth. In a bowl, mix the egusi with about ½ cup water into a thick paste.', null, null, null),
  ('016af92a-fa07-4340-a4d6-876b803b5a35', 3, 'Soup', 'Heat the palm oil in a large pot over medium heat for 2 minutes (don''t let it smoke). Add the pepper purée and fry, stirring, until thickened and the oil rises, 8–10 minutes.', 600, null, null),
  ('016af92a-fa07-4340-a4d6-876b803b5a35', 4, 'Soup', 'Spoon in the egusi paste and fry, stirring and scraping often, until it curdles into small clumps and smells nutty, about 10 minutes.', 600, null, null),
  ('016af92a-fa07-4340-a4d6-876b803b5a35', 5, 'Soup', 'Pour in the beef and all its stock, the crayfish and the smoked fish. Simmer gently, stirring now and then, 15 minutes, adding hot water if it gets too thick — it should be like a chunky stew.', 900, null, null),
  ('016af92a-fa07-4340-a4d6-876b803b5a35', 6, 'Soup', 'Stir in the spinach and cook until just wilted, 3 minutes. Taste for salt and serve with pounded yam, fufu, eba or rice.', 180, null, null);

-- Moi Moi
