values ('ae22553c-12cd-45ee-a2cc-9295b9932cbd', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'moi-moi', 'moi-moi-ae2255', 'Moi Moi', 'Silky Nigerian steamed bean pudding of peeled black-eyed peas blended with red peppers, onion and oil, often studded with boiled egg.', 'nigerian', 2, 90, 60, 150, 6, 'side', null, 0, array['stove', 'blender']::text[], array['make-ahead', 'budget']::text[], array['Peeled bean flour (sold at African grocers as ewa or moin-moin flour) skips the peeling: whisk 2 cups of it with the blended pepper mixture and about 1½ cups water.', 'Bouillon cubes often contain wheat, soy or milk, and crayfish is a shellfish — leave them out or check labels if allergies matter.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['side', 'budget']::text[], array['steam', 'boil']::text[], array['spicy']::text[], '{}'::text[], null, 'traditional', 'moi-moi', 'classic', 'Refrigerate up to 4 days or freeze up to 3 months; steam or microwave covered to reheat.', null, 'owned', array['egg', 'shellfish']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'dairy_free']::text[], array['black-eyed pea', 'bell pepper', 'bonnet pepper', 'yellow onion']::text[], 'bell pepper|black-eyed pea|bonnet pepper|yellow onion',
  null, null, null, null, null, null, null, null)
