insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('ae22553c-12cd-45ee-a2cc-9295b9932cbd', 1, null, '2 cups dried black-eyed peas', 'dried black-eyed peas', 2, 'cup', null, false),
  ('ae22553c-12cd-45ee-a2cc-9295b9932cbd', 2, null, '1 red bell pepper, seeded', 'red bell pepper', 1, null, 'seeded', false),
  ('ae22553c-12cd-45ee-a2cc-9295b9932cbd', 3, null, '½ Scotch bonnet pepper, seeded for less heat', 'Scotch bonnet pepper', 0.5, null, 'seeded for less heat', false),
  ('ae22553c-12cd-45ee-a2cc-9295b9932cbd', 4, null, '1 small yellow onion, quartered', 'small yellow onion', 1, null, 'quartered', false),
  ('ae22553c-12cd-45ee-a2cc-9295b9932cbd', 5, null, '1 cup warm water, or vegetable stock', 'warm water', 1, 'cup', 'or vegetable stock', false),
  ('ae22553c-12cd-45ee-a2cc-9295b9932cbd', 6, null, '⅓ cup vegetable oil, or red palm oil, plus more for greasing', 'vegetable oil', 0.33, 'cup', 'or red palm oil, plus more for greasing', false),
  ('ae22553c-12cd-45ee-a2cc-9295b9932cbd', 7, null, '1½ tsp kosher salt', 'kosher salt', 1.5, 'tsp', null, false),
  ('ae22553c-12cd-45ee-a2cc-9295b9932cbd', 8, null, '1 bouillon cube, crumbled', 'bouillon cube', 1, null, 'crumbled', true),
  ('ae22553c-12cd-45ee-a2cc-9295b9932cbd', 9, null, '1 tbsp ground dried crayfish', 'ground dried crayfish', 1, 'tbsp', null, true),
  ('ae22553c-12cd-45ee-a2cc-9295b9932cbd', 10, null, '3 large eggs, for hard-boiling', 'large eggs', 3, null, 'for hard-boiling', true);
delete from public.recipe_instructions where recipe_id = 'ae22553c-12cd-45ee-a2cc-9295b9932cbd';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('ae22553c-12cd-45ee-a2cc-9295b9932cbd', 1, null, 'Soak the black-eyed peas in plenty of water for 30–60 minutes until the skins loosen. Rub handfuls between your palms (or pulse briefly in a blender with water) and swirl to float the skins off; pour them away and repeat until almost all the beans are white.', 3600, null, null),
  ('ae22553c-12cd-45ee-a2cc-9295b9932cbd', 2, null, 'If using eggs, cover them with cold water, bring to a boil, then cover off the heat for 11 minutes until the yolks are firm (160°F). Cool, peel and quarter.', 900, null, 71.1),
  ('ae22553c-12cd-45ee-a2cc-9295b9932cbd', 3, null, 'Blend the peeled beans with the bell pepper, Scotch bonnet, onion and warm water until completely smooth and thick, like pancake batter. Pour into a bowl and whisk in the oil, salt, and bouillon and crayfish if using. Whisk for a minute to lighten it.', 300, null, null),
  ('ae22553c-12cd-45ee-a2cc-9295b9932cbd', 4, null, 'Grease six 8-oz ramekins or heatproof cups and fill each two-thirds full, pushing a piece of egg into each. Cover tightly with greased foil.', null, null, null),
  ('ae22553c-12cd-45ee-a2cc-9295b9932cbd', 5, null, 'Set a rack or folded towel in a large pot, add 2 inches of water and bring to a boil. Stand the cups on the rack, cover and steam over medium heat, topping up with boiling water as needed, until firm and a knife comes out clean, 45–60 minutes.', 3300, null, null),
  ('ae22553c-12cd-45ee-a2cc-9295b9932cbd', 6, null, 'Rest 5 minutes, then run a knife around and turn out, or eat straight from the cup with rice, pap or jollof.', 300, null, null);

