values ('22f45715-5972-4f72-bc9c-c8f1e1874029', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'thieboudienne', 'thieboudienne-22f457', 'Thieboudienne', 'Senegal''s national dish: white fish stuffed with a parsley-chili paste, simmered with vegetables in a rich tomato broth that the broken rice then soaks up; we use snapper or sea bass in place of West African grouper (thiof).', 'senegalese', 3, 40, 105, 145, 6, 'main', null, 0, array['stove', 'dutch_oven', 'blender']::text[], array['entertaining', 'one-pot']::text[], array['No broken rice? Pulse jasmine rice in a food processor a few times to crack the grains.', 'Bouillon cubes often contain wheat, soy or milk — check the label if allergies matter.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'entertaining']::text[], array['stew', 'pan_fry', 'boil']::text[], array['spicy', 'fresh']::text[], '{}'::text[], null, 'adapted', 'thieboudienne', 'classic', 'Refrigerate up to 3 days; reheat the rice covered with a splash of broth.', null, 'owned', array['fish']::text[], array['fish']::text[], array['pescatarian', 'gluten_free', 'dairy_free']::text[], array['snapper bass', 'parsley', 'garlic', 'scallion', 'bonnet pepper', 'yellow onion', 'bell pepper', 'tomato paste', 'carrot', 'green cabbage', 'eggplant', 'sweet potato', 'jasmine rice', 'lime']::text[], 'bell pepper|bonnet pepper|carrot|eggplant|garlic|green cabbage|jasmine rice|lime|parsley|scallion|snapper bass|sweet potato|tomato paste|yellow onion',
  null, null, null, null, null, null, null, null)
