values ('ce4968d9-9367-4606-a368-6948049ff079', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'nyama-choma', 'nyama-choma-ce4968', 'Nyama Choma', 'Kenya''s beloved grilled goat — the most common choice, though beef is popular too — rubbed simply with salt, garlic and lemon and slow-grilled over coals, served with fresh kachumbari salad.', 'kenyan', 2, 80, 75, 155, 6, 'main', null, 0, array['grill']::text[], array['entertaining']::text[], array['Look for goat at halal, Caribbean, African or Latin butchers and ask them to cut it into pieces on the bone.', 'Goat is lean and chewy if rushed — the slow time on the cool side is what makes it tender.']::text[], 'https://images.pexels.com/photos/31927206/pexels-photo-31927206.jpeg', 'Beef ribs roasting over a charcoal grill', 'Michael Mwase', 'https://www.pexels.com/@michael-mwase-184978781/', 'https://www.pexels.com/photo/juicy-grilled-beef-ribs-on-a-barbecue-31927206/', 'pexels', true, 'public', false,
  'pending_review', array['grilling', 'main', 'dinner', 'holiday', 'entertaining']::text[], array['grill', 'pan_fry']::text[], array['spicy', 'tangy', 'fresh']::text[], array['game-day']::text[], null, 'traditional', 'nyama-choma', 'classic', 'Refrigerate up to 3 days; reheat on a hot grill or skillet. Kachumbari is best within a few hours.', null, 'owned', '{}'::text[], array['goat']::text[], array['gluten_free', 'dairy_free']::text[], array['leg rib', 'garlic', 'ginger', 'lemon', 'tomato', 'red onion', 'cilantro', 'serrano chile', 'lime']::text[], 'cilantro|garlic|ginger|leg rib|lemon|lime|red onion|serrano chile|tomato',
  null, null, null, null, null, null, null, null)
