  ('ce4968d9-9367-4606-a368-6948049ff079', 1, 'Goat', '3 lb bone-in goat leg or ribs, cut into 3-inch pieces, or lamb ribs or shoulder chops', 'bone-in goat leg or ribs', 3, 'lb', 'cut into 3-inch pieces, or lamb ribs or shoulder chops', false),
  ('ce4968d9-9367-4606-a368-6948049ff079', 2, 'Goat', '2 tsp kosher salt', 'kosher salt', 2, 'tsp', null, false),
  ('ce4968d9-9367-4606-a368-6948049ff079', 3, 'Goat', '1 tsp black pepper', 'black pepper', 1, 'tsp', null, false),
  ('ce4968d9-9367-4606-a368-6948049ff079', 4, 'Goat', '3 cloves garlic, grated', 'garlic', 3, 'clove', 'grated', false),
  ('ce4968d9-9367-4606-a368-6948049ff079', 5, 'Goat', '1 tbsp fresh ginger, grated', 'fresh ginger', 1, 'tbsp', 'grated', false),
  ('ce4968d9-9367-4606-a368-6948049ff079', 6, 'Goat', '1 lemon, juiced', 'lemon', 1, null, 'juiced', false),
  ('ce4968d9-9367-4606-a368-6948049ff079', 7, 'Goat', '2 tbsp vegetable oil', 'vegetable oil', 2, 'tbsp', null, false),
  ('ce4968d9-9367-4606-a368-6948049ff079', 8, 'Kachumbari', '3 ripe tomatoes, diced', 'ripe tomatoes', 3, null, 'diced', false),
  ('ce4968d9-9367-4606-a368-6948049ff079', 9, 'Kachumbari', '1 red onion, thinly sliced', 'red onion', 1, null, 'thinly sliced', false),
