  ('ce4968d9-9367-4606-a368-6948049ff079', 12, 'Kachumbari', '1 lime, juiced', 'lime', 1, null, 'juiced', false),
  ('ce4968d9-9367-4606-a368-6948049ff079', 13, 'Kachumbari', '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false);
delete from public.recipe_instructions where recipe_id = 'ce4968d9-9367-4606-a368-6948049ff079';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('ce4968d9-9367-4606-a368-6948049ff079', 1, 'Goat', 'Rub the meat all over with the salt, pepper, garlic, ginger, lemon juice and oil. Leave at room temperature for up to 1 hour, or refrigerate up to overnight.', 3600, null, null),
  ('ce4968d9-9367-4606-a368-6948049ff079', 2, 'Goat', 'Set up a grill for two-zone cooking: hot coals or burners on one side, none on the other, with the lid temperature around 300–325°F.', 1200, 162.8, null),
  ('ce4968d9-9367-4606-a368-6948049ff079', 3, 'Goat', 'Lay the meat on the cool side, close the lid and cook, turning every 15 minutes, until tender when pierced and well past 145°F, 60–70 minutes.', 3900, null, 62.8),
  ('ce4968d9-9367-4606-a368-6948049ff079', 4, 'Kachumbari', 'Meanwhile, soak the sliced onion in salted water for 10 minutes to soften its bite, drain, then toss with the tomatoes, cilantro, chile, lime juice and salt.', 600, null, null),
  ('ce4968d9-9367-4606-a368-6948049ff079', 5, 'Goat', 'Move the meat over the hot side and sear, turning, until crusty and charred in spots, 5–8 minutes. Rest 5 minutes, then chop into bite-size pieces on the bone.', 720, null, null),
  ('ce4968d9-9367-4606-a368-6948049ff079', 6, null, 'Serve with kachumbari, a little extra salt for dipping and ugali (stiff cornmeal porridge) or flatbread.', null, null, null);

-- Boerewors
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
