values ('ec31e484-124b-4c5d-a693-b299310525f2', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'boerewors', 'boerewors-ec31e4', 'Boerewors', 'South Africa''s coiled "farmer''s sausage" of coarsely ground beef and pork seasoned with toasted coriander, cloves, nutmeg and vinegar, cooked whole on the braai.', 'south_african', 2, 60, 20, 200, 6, 'main', null, 120, array['grill', 'stand_mixer']::text[], array['entertaining', 'freezer-friendly']::text[], array['No stuffer? Shape the mixture into long, thin logs about 1 inch thick, chill until firm and grill the same way.', 'Malt vinegar is made from barley; use apple cider vinegar if you''re cooking for anyone avoiding gluten.']::text[], 'https://images.pexels.com/photos/4078164/pexels-photo-4078164.jpeg', 'Coiled boerewors sausage sizzling on a grill over charcoal', 'Anna Guerrero', 'https://www.pexels.com/@anna-guerrero-788383/', 'https://www.pexels.com/photo/brown-sausage-on-black-metal-grill-4078164/', 'pexels', true, 'public', false,
  'pending_review', array['grilling', 'main', 'dinner', 'holiday', 'entertaining']::text[], array['grill']::text[], array['tangy', 'aromatic']::text[], array['game-day']::text[], null, 'traditional', 'boerewors', 'classic', 'Refrigerate uncooked boerewors up to 2 days or freeze up to 3 months. Cooked, it keeps 3 days in the fridge.', null, 'owned', array['gluten']::text[], array['beef', 'pork']::text[], array['dairy_free']::text[], array['beef chuck', 'ground pork', 'coriander seed', 'ground clove', 'ground nutmeg', 'ground allspice', 'malt vinegar', 'hog casing']::text[], 'beef chuck|coriander seed|ground allspice|ground clove|ground nutmeg|ground pork|hog casing|malt vinegar',
  null, null, null, null, null, null, null, null)
