insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('ec31e484-124b-4c5d-a693-b299310525f2', 1, null, '2 lb ground beef chuck, coarsely ground, about 20% fat', 'ground beef chuck', 2, 'lb', 'coarsely ground, about 20% fat', false),
  ('ec31e484-124b-4c5d-a693-b299310525f2', 2, null, '1 lb ground pork, coarsely ground', 'ground pork', 1, 'lb', 'coarsely ground', false),
  ('ec31e484-124b-4c5d-a693-b299310525f2', 3, null, '2 tbsp coriander seeds', 'coriander seeds', 2, 'tbsp', null, false),
  ('ec31e484-124b-4c5d-a693-b299310525f2', 4, null, '2½ tsp kosher salt', 'kosher salt', 2.5, 'tsp', null, false),
  ('ec31e484-124b-4c5d-a693-b299310525f2', 5, null, '1 tsp black pepper, freshly ground', 'black pepper', 1, 'tsp', 'freshly ground', false),
  ('ec31e484-124b-4c5d-a693-b299310525f2', 6, null, '¼ tsp ground cloves', 'ground cloves', 0.25, 'tsp', null, false),
  ('ec31e484-124b-4c5d-a693-b299310525f2', 7, null, '½ tsp ground nutmeg', 'ground nutmeg', 0.5, 'tsp', null, false),
  ('ec31e484-124b-4c5d-a693-b299310525f2', 8, null, '¼ tsp ground allspice', 'ground allspice', 0.25, 'tsp', null, false),
  ('ec31e484-124b-4c5d-a693-b299310525f2', 9, null, '3 tbsp malt vinegar, or apple cider vinegar', 'malt vinegar', 3, 'tbsp', 'or apple cider vinegar', false),
  ('ec31e484-124b-4c5d-a693-b299310525f2', 10, null, '3 tbsp cold water', 'cold water', 3, 'tbsp', null, false),
  ('ec31e484-124b-4c5d-a693-b299310525f2', 11, null, '1 package natural hog casings, you need about 8 feet, 1¼ inch wide', 'natural hog casings', 1, 'package', 'you need about 8 feet, 1¼ inch wide', false);
delete from public.recipe_instructions where recipe_id = 'ec31e484-124b-4c5d-a693-b299310525f2';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('ec31e484-124b-4c5d-a693-b299310525f2', 1, null, 'Soak the casings in lukewarm water for 30 minutes, then run water through each one to rinse the inside.', 1800, null, null),
  ('ec31e484-124b-4c5d-a693-b299310525f2', 2, null, 'Toast the coriander seeds in a dry skillet until fragrant, about 1 minute. Cool and crush coarsely in a mortar or spice grinder; sift out some of the husks if you like.', 120, null, null),
  ('ec31e484-124b-4c5d-a693-b299310525f2', 3, null, 'In a cold bowl, mix the beef and pork with the coriander, salt, pepper, cloves, nutmeg, allspice, vinegar and water. Mix gently with your hands just until evenly seasoned — don''t overwork it, boerewors should be coarse. Fry a small patty to taste and adjust the seasoning.', 480, null, null),
  ('ec31e484-124b-4c5d-a693-b299310525f2', 4, null, 'Fit a stand mixer with the sausage-stuffing attachment, thread on a casing and stuff it loosely in one long, continuous rope, without twisting into links. Prick any air bubbles with a pin. Coil the rope into a spiral and push a skewer or two through it crosswise to hold the shape.', 1200, null, null),
  ('ec31e484-124b-4c5d-a693-b299310525f2', 5, null, 'Refrigerate, uncovered, for at least 2 hours (or overnight) so the casing dries and the flavors settle.', 7200, null, null),
  ('ec31e484-124b-4c5d-a693-b299310525f2', 6, null, 'Heat a grill to medium (about 375°F). Grill the coil, turning it carefully once with a wide spatula or in a hinged grill basket, until browned and 160°F in the thickest part, 8–10 minutes per side. Don''t prick it while cooking or the juices run out.', 1080, 190.6, 71.1),
  ('ec31e484-124b-4c5d-a693-b299310525f2', 7, null, 'Rest 5 minutes, then cut into pieces and serve with pap (stiff cornmeal porridge) and tomato-onion relish, or in a soft roll as a boerewors roll.', null, null, null);

-- Pork and Chive Dumplings
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
