values ('d54eb975-146a-4a16-86a3-01f0bbbe9059', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'pork-and-chive-dumplings-jiaozi', 'pork-and-chive-dumplings-d54eb9', 'Pork and Chive Dumplings', 'Northern-style boiled jiaozi with hand-rolled wrappers and a juicy pork and garlic chive filling, served with a black vinegar dipping sauce.', 'chinese', 3, 95, 20, 115, 6, 'starter', null, 0, array['stove']::text[], array['make-ahead', 'freezer-friendly', 'entertaining']::text[], array['To freeze, set uncooked dumplings on a floured tray until solid, then bag them. Boil from frozen, adding 2–3 minutes.', 'Short on time? Round store-bought dumpling wrappers work; seal them with a dab of water.']::text[], 'https://images.unsplash.com/photo-1639119419998-b1f2ea5e5342', 'Close-up of boiled Chinese dumplings on a tray', 'ji jiali', 'https://unsplash.com/@jijiali', 'https://unsplash.com/photos/a-close-up-of-some-dumplings-on-a-tray-nGoRcWrksb4', 'unsplash', true, 'public', false,
  'pending_review', array['appetizer', 'entertaining']::text[], array['boil']::text[], array['spicy', 'tangy', 'savory']::text[], '{}'::text[], null, 'traditional', 'pork-chive-jiaozi', 'classic', 'Refrigerate cooked dumplings up to 2 days and pan-fry to reheat. Freeze uncooked up to 3 months.', null, 'owned', array['gluten', 'sesame', 'soy', 'wheat']::text[], array['pork']::text[], array['dairy_free']::text[], array['ground pork', 'soy sauce', 'shaoxing wine', 'ginger', 'white pepper', 'garlic chive', 'sesame oil', 'black vinegar']::text[], 'black vinegar|garlic chive|ginger|ground pork|sesame oil|shaoxing wine|soy sauce|white pepper',
  null, null, null, null, null, null, null, null)
