  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 1, 'Dough', '2½ cups all-purpose flour, plus more for dusting', 'all-purpose flour', 2.5, 'cup', 'plus more for dusting', false),
  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 2, 'Dough', '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 3, 'Dough', '¾ cup cold water, plus 1–2 tbsp as needed', 'cold water', 0.75, 'cup', 'plus 1–2 tbsp as needed', false),
  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 4, 'Filling', '1 lb ground pork, not extra-lean', 'ground pork', 1, 'lb', 'not extra-lean', false),
  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 5, 'Filling', '2 tbsp soy sauce', 'soy sauce', 2, 'tbsp', null, false),
  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 6, 'Filling', '1 tbsp Shaoxing wine, or dry sherry', 'Shaoxing wine', 1, 'tbsp', 'or dry sherry', false),
  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 7, 'Filling', '1 tbsp fresh ginger, finely grated', 'fresh ginger', 1, 'tbsp', 'finely grated', false),
