  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 10, 'Filling', '⅓ cup water, cold', 'water', 0.33, 'cup', 'cold', false),
  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 11, 'Filling', '4 oz Chinese garlic chives, about 1 bunch, finely chopped; or 1 bunch chives plus 2 scallions', 'Chinese garlic chives', 4, 'oz', 'about 1 bunch, finely chopped; or 1 bunch chives plus 2 scallions', false),
  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 12, 'Filling', '1 tbsp toasted sesame oil', 'toasted sesame oil', 1, 'tbsp', null, false),
  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 13, 'Dipping sauce', '3 tbsp Chinkiang black vinegar, or rice vinegar', 'Chinkiang black vinegar', 3, 'tbsp', 'or rice vinegar', false),
  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 14, 'Dipping sauce', '1 tbsp soy sauce', 'soy sauce', 1, 'tbsp', null, false),
  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 15, 'Dipping sauce', '1 clove garlic, grated', 'garlic', 1, 'clove', 'grated', true),
