delete from public.recipe_instructions where recipe_id = 'd54eb975-146a-4a16-86a3-01f0bbbe9059';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 1, 'Dough', 'Mix the flour and salt in a bowl, then drizzle in the water while stirring with chopsticks until shaggy. Knead 5 minutes into a smooth, firm dough, adding a spoonful more water only if it won''t come together. Cover and rest 30 minutes.', 2100, null, null),
  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 2, 'Filling', 'Stir the pork with the soy sauce, Shaoxing wine, ginger, white pepper and salt in one direction until sticky. Beat in the water a tablespoon at a time, letting each addition soak in, then fold in the chives and sesame oil.', 600, null, null),
  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 3, 'Dough', 'Divide the dough into 4 pieces and roll each into a rope about 1 inch thick. Cut each rope into 10–12 pieces, flatten them with your palm and roll into 3-inch rounds that are thinner at the edge than in the middle. Keep the dough you aren''t using covered.', 1500, null, null),
  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 4, 'Filling', 'Set a heaping teaspoon of filling in the center of a wrapper, fold it into a half-moon and pinch the middle shut, then pleat or pinch each side to seal. Set on a floured tray and repeat.', 1500, null, null),
  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 5, null, 'Bring a large pot of water to a rolling boil. Add about 16 dumplings and stir gently so they don''t stick. When the water returns to a boil, add ½ cup cold water; repeat twice more. They''re done when they float, the wrappers look puffy and the filling reaches 160°F, 6–7 minutes in all. Lift out with a slotted spoon and cook the rest.', 420, null, 71.1),
  ('d54eb975-146a-4a16-86a3-01f0bbbe9059', 6, 'Dipping sauce', 'Stir the vinegar, soy sauce, garlic and chili oil together and serve with the hot dumplings.', null, null, null);

-- Peking Duck
