values ('92fe5d01-e4e7-4e8c-a652-257558c2c88b', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'peking-duck-home-oven', 'peking-duck-92fe5d', 'Peking Duck', 'Lacquered, crackling-skinned duck sliced and rolled into thin pancakes with hoisin, scallion and cucumber; adapted for a home oven — the duck is air-dried in the fridge and roasted over a water pan instead of hung in a wood-fired oven.', 'chinese', 5, 90, 115, 1645, 6, 'main', null, 1440, array['oven', 'stove']::text[], array['entertaining', 'holiday', 'project']::text[], array['Frozen mandarin pancakes (sometimes labeled duck wrappers) from Asian grocers save 50 minutes; steam them to soften.', 'Pour off and save the rendered duck fat — it makes outstanding roast potatoes.']::text[], 'https://images.unsplash.com/photo-1765441012353-10fb4701a276', 'Slices of crispy Peking duck on a white plate', 'Wenhao Wang', 'https://unsplash.com/@retter', 'https://unsplash.com/photos/crispy-peking-duck-with-mint-leaves-on-white-plate-tm4Y0NAUA48', 'unsplash', true, 'public', false,
  'pending_review', array['entertaining', 'main', 'dinner']::text[], array['roast', 'steam', 'boil']::text[], array['tangy', 'savory', 'aromatic']::text[], '{}'::text[], 'Beijing', 'adapted', 'peking-duck', 'classic', 'Refrigerate leftover duck up to 3 days; the skin softens, so use it in fried rice or noodle soup.', 'While the duck dries, keep it uncovered on a tray on the lowest fridge shelf, away from ready-to-eat food. Clean the sink and anything splashed while scalding it, and roast until the thigh reaches 165°F.', 'owned', array['gluten', 'sesame', 'soy', 'wheat']::text[], array['duck']::text[], array['dairy_free']::text[], array['duck', 'five-spice powder', 'boiling water', 'honey', 'rice vinegar', 'soy sauce', 'sesame oil', 'hoisin sauce', 'scallion', 'english cucumber']::text[], 'boiling water|duck|english cucumber|five-spice powder|hoisin sauce|honey|rice vinegar|scallion|sesame oil|soy sauce',
  null, null, null, null, null, null, null, null)
