values ('a0da8751-038c-4f85-a110-3f6859741568', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'hong-shao-rou-red-braised-pork-belly', 'red-braised-pork-belly-hong-shao-rou-a0da87', 'Red-Braised Pork Belly (Hong Shao Rou)', 'Cubes of skin-on pork belly glazed in caramelized rock sugar and braised with soy and Shaoxing wine until meltingly tender — the glossy, sweet-savory Shanghai-style red braise.', 'chinese', 3, 15, 105, 120, 6, 'main', null, 0, array['stove']::text[], array['comfort', 'make-ahead']::text[], array['Ask the butcher for belly with the skin on; skinless belly works but misses the signature wobbly texture.', 'Add 4 peeled hard-boiled eggs for the last 30 minutes of braising — they soak up the sauce beautifully.']::text[], 'https://images.unsplash.com/photo-1767974911771-e49a477916a8', 'Pieces of braised pork belly simmering in a large pan', 'tommao wang', 'https://unsplash.com/@tommaomaoer', 'https://unsplash.com/photos/pork-belly-pieces-simmering-in-a-large-pan-bDV1an6G6ds', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'comfort']::text[], array['braise', 'stew', 'stir_fry', 'boil']::text[], array['savory', 'aromatic']::text[], '{}'::text[], 'Shanghai', 'traditional', 'hong-shao-rou', 'classic', 'Refrigerate up to 4 days; the flavor improves overnight. Reheat gently, covered, with a splash of water.', null, 'owned', array['gluten', 'soy', 'wheat']::text[], array['pork']::text[], array['dairy_free']::text[], array['pork belly', 'rock sugar', 'shaoxing wine', 'soy sauce', 'ginger', 'scallion', 'star anise', 'jasmine rice']::text[], 'ginger|jasmine rice|pork belly|rock sugar|scallion|shaoxing wine|soy sauce|star anise',
  null, null, null, null, null, null, null, null)
