values ('b745b5e3-e375-4fee-bf8b-6eb472719543', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'beef-and-broccoli-oyster-sauce', 'beef-and-broccoli-b745b5', 'Beef and Broccoli', 'Velveted flank steak and crisp-tender broccoli in a glossy oyster-sauce gravy — a Chinese American takeout favorite adapted from Cantonese beef with gai lan, using broccoli.', 'chinese', 2, 25, 10, 35, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'kid-friendly']::text[], array['Freeze the steak for 20 minutes before slicing; it firms up and slices paper-thin.', 'Swap in Chinese broccoli (gai lan) for the Cantonese original.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['quick', 'main', 'dinner', 'comfort']::text[], array['stir_fry', 'pan_fry', 'steam']::text[], array['savory']::text[], '{}'::text[], null, 'adapted', 'beef-and-broccoli', 'classic', 'Refrigerate up to 3 days; reheat in a hot skillet so the broccoli stays crisp.', null, 'owned', array['gluten', 'sesame', 'shellfish', 'soy', 'wheat']::text[], array['beef']::text[], array['dairy_free']::text[], array['flank steak', 'baking soda', 'soy sauce', 'shaoxing wine', 'cornstarch', 'oyster sauce', 'sesame oil', 'broccoli', 'garlic', 'ginger', 'jasmine rice']::text[], 'baking soda|broccoli|cornstarch|flank steak|garlic|ginger|jasmine rice|oyster sauce|sesame oil|shaoxing wine|soy sauce',
  null, null, null, null, null, null, null, null)
