  ('b745b5e3-e375-4fee-bf8b-6eb472719543', 1, 'Beef', '1¼ lb flank steak, sliced ¼ inch thick across the grain', 'flank steak', 1.25, 'lb', 'sliced ¼ inch thick across the grain', false),
  ('b745b5e3-e375-4fee-bf8b-6eb472719543', 2, 'Beef', '¼ tsp baking soda', 'baking soda', 0.25, 'tsp', null, false),
  ('b745b5e3-e375-4fee-bf8b-6eb472719543', 3, 'Beef', '1 tbsp soy sauce', 'soy sauce', 1, 'tbsp', null, false),
  ('b745b5e3-e375-4fee-bf8b-6eb472719543', 4, 'Beef', '1 tbsp Shaoxing wine, or dry sherry', 'Shaoxing wine', 1, 'tbsp', 'or dry sherry', false),
  ('b745b5e3-e375-4fee-bf8b-6eb472719543', 5, 'Beef', '2 tsp cornstarch', 'cornstarch', 2, 'tsp', null, false),
