  ('b745b5e3-e375-4fee-bf8b-6eb472719543', 10, 'Sauce', '1 tsp toasted sesame oil', 'toasted sesame oil', 1, 'tsp', null, false),
  ('b745b5e3-e375-4fee-bf8b-6eb472719543', 11, 'Sauce', '2 tsp cornstarch', 'cornstarch', 2, 'tsp', null, false),
  ('b745b5e3-e375-4fee-bf8b-6eb472719543', 12, 'Sauce', '½ cup water', 'water', 0.5, 'cup', null, false),
  ('b745b5e3-e375-4fee-bf8b-6eb472719543', 13, 'Stir-fry', '4 tbsp vegetable oil, divided', 'vegetable oil', 4, 'tbsp', 'divided', false),
  ('b745b5e3-e375-4fee-bf8b-6eb472719543', 14, 'Stir-fry', '1¼ lb broccoli, cut into bite-size florets, stems peeled and sliced', 'broccoli', 1.25, 'lb', 'cut into bite-size florets, stems peeled and sliced', false),
