insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('b745b5e3-e375-4fee-bf8b-6eb472719543', 1, 'Beef', 'Toss the beef with the baking soda, soy sauce, Shaoxing wine and cornstarch, then stir in 1 tablespoon of the oil. Let it sit 15 minutes.', 900, null, null),
  ('b745b5e3-e375-4fee-bf8b-6eb472719543', 2, 'Sauce', 'Stir the oyster sauce, soy sauces, sugar, sesame oil, cornstarch and water together in a small bowl.', null, null, null),
  ('b745b5e3-e375-4fee-bf8b-6eb472719543', 3, 'Stir-fry', 'Heat 1 tablespoon oil in a wok or large skillet over high heat. Add the broccoli and 3 tablespoons water, cover and steam-fry until bright green and crisp-tender, 2–3 minutes. Tip onto a plate.', 180, null, null),
  ('b745b5e3-e375-4fee-bf8b-6eb472719543', 4, 'Stir-fry', 'Add the remaining 2 tablespoons oil and heat until shimmering. Spread the beef in one layer, sear 1 minute, then stir-fry until browned and 145°F, about 2 minutes more. Work in two batches if your pan is small.', 180, null, 62.8),
  ('b745b5e3-e375-4fee-bf8b-6eb472719543', 5, 'Stir-fry', 'Push the beef aside, add the garlic and ginger and stir 20 seconds. Return the broccoli, give the sauce a stir and pour it in. Toss until it thickens and turns glossy, about 1 minute.', 60, null, null),
  ('b745b5e3-e375-4fee-bf8b-6eb472719543', 6, null, 'Serve right away over rice.', null, null, null);

