values ('d4466df7-156f-4eb8-9cf6-d4a7be1e4fef', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'twice-cooked-pork-hui-guo-rou', 'twice-cooked-pork-d4466d', 'Twice-Cooked Pork', 'Pork belly simmered, chilled and sliced thin, then fried until the slices curl and tossed with chili bean paste, fermented black beans and leeks — Sichuan''s classic hui guo rou.', 'sichuan', 3, 15, 35, 80, 4, 'main', null, 30, array['stove']::text[], array['spicy']::text[], array['Chili bean paste and sweet bean sauce are often made with wheat flour — check the labels if that matters for anyone at the table.', 'Save the pork-simmering water; skimmed, it''s a light stock for soup.']::text[], 'https://images.unsplash.com/photo-1767354063817-ad6d91d39478', 'Stir-fried sliced pork belly with chili peppers and scallions', 'wang binghua', 'https://unsplash.com/@wangbinghua', 'https://unsplash.com/photos/a-platter-of-seasoned-meat-with-peppers-and-vegetables-c6CArzIVXes', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner']::text[], array['stew', 'stir_fry', 'boil']::text[], array['spicy', 'savory']::text[], '{}'::text[], 'Sichuan', 'traditional', 'twice-cooked-pork', 'classic', 'Refrigerate up to 3 days; reheat in a hot wok.', null, 'owned', array['gluten', 'soy', 'wheat']::text[], array['pork']::text[], array['dairy_free']::text[], array['pork belly', 'ginger', 'scallion', 'bean paste', 'black soybean', 'bean sauce', 'shaoxing wine', 'soy sauce', 'leek', 'jasmine rice']::text[], 'bean paste|bean sauce|black soybean|ginger|jasmine rice|leek|pork belly|scallion|shaoxing wine|soy sauce',
  null, null, null, null, null, null, null, null)
