insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('d4466df7-156f-4eb8-9cf6-d4a7be1e4fef', 1, null, 'Put the pork, ginger and scallion in a pot, cover with water and bring to a boil. Lower the heat and simmer gently until a chopstick slides into the meat easily and it reaches at least 145°F, about 25 minutes.', 1500, null, 62.8),
  ('d4466df7-156f-4eb8-9cf6-d4a7be1e4fef', 2, null, 'Drain, let cool, then refrigerate until firm, at least 30 minutes (or overnight). Slice very thinly, about ⅛ inch, keeping the skin on each slice.', 1800, null, null),
  ('d4466df7-156f-4eb8-9cf6-d4a7be1e4fef', 3, null, 'Heat the oil in a wok over medium heat. Add the pork slices in a single layer and fry, turning, until the fat renders and the slices curl into little cups, 4–5 minutes. Pour off all but about 2 tablespoons of fat.', 300, null, null),
  ('d4466df7-156f-4eb8-9cf6-d4a7be1e4fef', 4, null, 'Add the chili bean paste and black beans and stir-fry until the oil turns red and smells toasty, about 1 minute. Add the sweet bean sauce, Shaoxing wine, soy sauce and sugar and toss with the pork.', 120, null, null),
  ('d4466df7-156f-4eb8-9cf6-d4a7be1e4fef', 5, null, 'Add the leek and bell pepper and stir-fry until just tender and bright, 1–2 minutes. Serve with rice.', 120, null, null);

-- Chongqing Hot Pot
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
