values ('210d6c09-16dd-4466-ac01-096489ab14c1', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chongqing-spicy-hot-pot', 'chongqing-hot-pot-210d6c', 'Chongqing Hot Pot', 'A fiery, numbing broth built on beef tallow, chili bean paste, dried chiles and Sichuan peppercorns, kept bubbling at the table for cooking thin-sliced meat, shrimp, tofu and vegetables — you need a tabletop burner and a wide pot.', 'sichuan', 4, 50, 75, 125, 6, 'main', null, 0, array['stove']::text[], array['entertaining', 'spicy', 'party']::text[], array['Too fiery? Halve the chiles and Sichuan peppercorns, or use a divided pot with plain stock on one side.', 'Chili bean paste and ready-made hot pot base blocks often contain wheat — check the labels if that matters for your guests.']::text[], 'https://images.unsplash.com/photo-1792587043423-c39e2f8e00b6', 'Metal pot of spicy Sichuan hot pot broth with dried chilies and peppercorns', 'Kris Tian', 'https://unsplash.com/@kris_tian', 'https://unsplash.com/photos/spicy-sichuan-hot-pot-base-tIHPX0fEfY0', 'unsplash', true, 'public', false,
  'pending_review', array['entertaining', 'main', 'dinner']::text[], array['stew', 'boil']::text[], array['spicy', 'fresh', 'aromatic']::text[], '{}'::text[], 'Chongqing', 'traditional', 'chongqing-hot-pot', 'classic', 'Strain leftover broth and refrigerate up to 4 days or freeze up to 3 months; the fat sets on top and can be lifted off.', 'Meat and shrimp go into the pot uncooked: keep them chilled until cooking, use separate chopsticks or tongs for them, keep the broth at a full boil, and cook meat until no pink remains and shrimp until opaque. Use butane burners only in a ventilated room (never charcoal indoors) and keep children clear of the boiling pot.', 'owned', array['gluten', 'sesame', 'shellfish', 'soy', 'wheat']::text[], array['beef', 'lamb', 'shellfish', 'tofu']::text[], array['dairy_free']::text[], array['beef tallow', 'ginger', 'garlic', 'scallion', 'red chile', 'sichuan peppercorn', 'bean paste', 'black soybean', 'star anise', 'cinnamon stick', 'bay leave', 'rock sugar', 'shaoxing wine', 'beef ribeye', 'lamb shoulder', 'shrimp', 'tofu', 'oyster mushroom', 'napa cabbage', 'russet potato', 'glass noodle', 'sesame oil', 'cilantro']::text[], 'bay leave|bean paste|beef ribeye|beef tallow|black soybean|cilantro|cinnamon stick|garlic|ginger|glass noodle|lamb shoulder|napa cabbage|oyster mushroom|red chile|rock sugar|russet potato|scallion|sesame oil|shaoxing wine|shrimp|sichuan peppercorn|star anise|tofu',
  null, null, null, null, null, null, null, null)
