delete from public.recipe_instructions where recipe_id = '210d6c09-16dd-4466-ac01-096489ab14c1';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('210d6c09-16dd-4466-ac01-096489ab14c1', 1, 'Dippers', 'Arrange the dippers on platters. Keep the meat and shrimp on their own plates, with their own tongs or chopsticks, in the fridge until everyone sits down.', 1800, null, null),
  ('210d6c09-16dd-4466-ac01-096489ab14c1', 2, 'Broth', 'Melt the tallow with the oil in a wide pot over medium-low heat. Add the ginger, garlic and scallions and fry 3 minutes. Drain the chiles and add them with the Sichuan peppercorns; stir 1 minute without letting them blacken.', 300, null, null),
  ('210d6c09-16dd-4466-ac01-096489ab14c1', 3, 'Broth', 'Add the chili bean paste and black beans and fry over low heat, stirring often, until the fat turns deep red and smells toasty, 8–10 minutes. Add the star anise, cinnamon, bay leaves, sugar and Shaoxing wine.', 600, null, null),
  ('210d6c09-16dd-4466-ac01-096489ab14c1', 4, 'Broth', 'Pour in the water, bring to a boil and simmer 20 minutes so the flavors meld. Taste and add salt if needed.', 1200, null, null),
  ('210d6c09-16dd-4466-ac01-096489ab14c1', 5, 'Dipping oil', 'Divide the sesame oil, garlic, cilantro and salt among small bowls, one per person.', null, null, null),
  ('210d6c09-16dd-4466-ac01-096489ab14c1', 6, null, 'Set the pot on a tabletop butane or induction burner and keep it at a rolling boil. Swish meat slices in the broth until no pink remains (145°F), 30–60 seconds; cook shrimp until pink and opaque, 2–3 minutes; give potatoes, tofu, vegetables and noodles a few minutes. Dip in the sesame oil and eat as you go.', 2400, null, 62.8),
  ('210d6c09-16dd-4466-ac01-096489ab14c1', 7, null, 'Top up the pot with hot water as the broth reduces so it doesn''t get too salty or scorch.', null, null, null);

-- Har Gow (Shrimp Dumplings)
