values ('7e1ee977-c63e-4ba4-a3c2-b345d5a7bd2d', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'har-gow-shrimp-dumplings', 'har-gow-shrimp-dumplings-7e1ee9', 'Har Gow (Shrimp Dumplings)', 'Pleated, see-through dim sum dumplings with a snappy shrimp and bamboo shoot filling, wrapped in a chewy wheat-starch dough and steamed.', 'cantonese', 4, 90, 15, 105, 6, 'starter', null, 0, array['stove']::text[], array['entertaining', 'dim-sum']::text[], array['Wheat starch (not wheat flour) is sold in bags at Asian grocers; flour makes an opaque, gummy wrapper, so there''s no good substitute.', 'You need a bamboo steamer set over a wok, or a metal steamer insert in a wide pot.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['appetizer', 'entertaining']::text[], array['steam', 'boil']::text[], array['spicy', 'savory']::text[], '{}'::text[], 'Guangdong', 'traditional', 'har-gow', 'classic', 'Best eaten fresh. Freeze uncooked dumplings on a tray, then bag up to 1 month; steam from frozen for 9–10 minutes.', null, 'owned', array['gluten', 'sesame', 'shellfish', 'soy', 'wheat']::text[], array['shellfish']::text[], array['pescatarian', 'dairy_free']::text[], array['shrimp', 'white pepper', 'cornstarch', 'bamboo shoot', 'sesame oil', 'wheat starch', 'tapioca starch', 'boiling water', 'soy sauce']::text[], 'bamboo shoot|boiling water|cornstarch|sesame oil|shrimp|soy sauce|tapioca starch|wheat starch|white pepper',
  null, null, null, null, null, null, null, null)
