delete from public.recipe_instructions where recipe_id = '7e1ee977-c63e-4ba4-a3c2-b345d5a7bd2d';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7e1ee977-c63e-4ba4-a3c2-b345d5a7bd2d', 1, 'Filling', 'Chop half the shrimp into pea-size pieces and smash the rest into a coarse paste with the flat of a knife. Mix both with the salt, sugar, white pepper and cornstarch, stirring in one direction for 2 minutes until sticky. Fold in the bamboo shoots, sesame oil and fatback and chill 20 minutes.', 1500, null, null),
  ('7e1ee977-c63e-4ba4-a3c2-b345d5a7bd2d', 2, 'Dough', 'Whisk the wheat starch, tapioca starch and salt in a heatproof bowl. Pour in the boiling water all at once, stirring hard with chopsticks, then cover for 5 minutes. Add the oil and knead into a smooth, soft dough while it''s still warm. Keep covered.', 600, null, null),
  ('7e1ee977-c63e-4ba4-a3c2-b345d5a7bd2d', 3, 'Dough', 'Roll the dough into a log and cut 24 pieces. Press each into a thin 3-inch round with an oiled cleaver blade, or roll it between two pieces of oiled plastic.', 1500, null, null),
  ('7e1ee977-c63e-4ba4-a3c2-b345d5a7bd2d', 4, null, 'Set 2 teaspoons of filling in the center of a wrapper. Fold it in half and pleat one side 8–10 times against the flat side to make a crescent, then pinch to seal. Set on a parchment-lined steamer basket, 1 inch apart.', 1800, null, null),
  ('7e1ee977-c63e-4ba4-a3c2-b345d5a7bd2d', 5, null, 'Heat a steamer over rapidly boiling water and steam until the wrappers turn translucent and the shrimp inside is pink, opaque and 145°F, 6–7 minutes.', 420, null, 62.8),
  ('7e1ee977-c63e-4ba4-a3c2-b345d5a7bd2d', 6, 'To serve', 'Serve straight from the steamer with soy sauce and chili oil.', null, null, null);

-- Siu Mai
