values ('c689771b-f892-4e97-9f85-a38a391dc9ac', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'siu-mai-pork-shrimp', 'siu-mai-c68977', 'Siu Mai', 'Open-topped pork, shrimp and shiitake dumplings in thin yellow wrappers, steamed until juicy — the dim sum cart staple.', 'cantonese', 3, 50, 20, 70, 6, 'starter', null, 0, array['stove']::text[], array['entertaining', 'dim-sum', 'freezer-friendly']::text[], array['Freeze shaped, uncooked siu mai on a tray, then bag them; steam from frozen for 12–14 minutes.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['appetizer', 'entertaining']::text[], array['steam', 'boil']::text[], array['spicy', 'savory']::text[], '{}'::text[], 'Guangdong', 'traditional', 'siu-mai', 'classic', 'Refrigerate cooked siu mai up to 2 days and re-steam 4–5 minutes; freeze uncooked up to 3 months.', null, 'owned', array['gluten', 'sesame', 'shellfish', 'soy', 'wheat']::text[], array['pork', 'shellfish']::text[], array['dairy_free']::text[], array['shiitake mushroom', 'ground pork', 'shrimp', 'soy sauce', 'oyster sauce', 'shaoxing wine', 'white pepper', 'cornstarch', 'sesame oil', 'wonton wrapper', 'carrot']::text[], 'carrot|cornstarch|ground pork|oyster sauce|sesame oil|shaoxing wine|shiitake mushroom|shrimp|soy sauce|white pepper|wonton wrapper',
