insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('c689771b-f892-4e97-9f85-a38a391dc9ac', 1, null, 'Soak the shiitake in hot water until soft, about 20 minutes. Squeeze dry, discard the stems and finely dice the caps.', 1200, null, null),
  ('c689771b-f892-4e97-9f85-a38a391dc9ac', 2, null, 'Stir the pork with the soy sauce, oyster sauce, Shaoxing wine, sugar, salt, white pepper and cornstarch in one direction until tacky, about 2 minutes. Fold in the shrimp, mushrooms and sesame oil.', 300, null, null),
  ('c689771b-f892-4e97-9f85-a38a391dc9ac', 3, null, 'Make a ring with your thumb and index finger and lay a wrapper over it. Press in a heaping tablespoon of filling, squeeze gently into an open-topped cylinder and smooth the top with a wet spoon. Dot with diced carrot.', 1500, null, null),
  ('c689771b-f892-4e97-9f85-a38a391dc9ac', 4, null, 'Set the dumplings in a parchment-lined steamer basket, ½ inch apart. Heat a steamer over boiling water and cook the dumplings until the filling is firm and 160°F, 8–10 minutes. Steam in batches if needed.', 600, null, 71.1),
  ('c689771b-f892-4e97-9f85-a38a391dc9ac', 5, null, 'Serve hot with chili oil or soy sauce.', null, null, null);

