values ('e1f7f17a-a9fc-4d23-a6ec-862be922eca8', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'char-siu-cantonese-bbq-pork', 'char-siu-e1f7f1', 'Char Siu', 'Strips of pork shoulder marinated overnight in hoisin, five-spice and honey, then roasted and glazed until sticky and charred at the edges — Cantonese barbecue pork from a home oven.', 'cantonese', 3, 15, 55, 790, 6, 'main', null, 720, array['oven']::text[], array['make-ahead', 'entertaining']::text[], array['Red fermented bean curd, sold in jars at Asian grocers, gives char siu its classic rosy color and savory depth.', 'Leftovers make the best fried rice, noodle soup or cha siu bao filling.']::text[], 'https://images.unsplash.com/photo-1743297907277-fbc749a56a4b', 'Plate of sliced char siu barbecue pork', 'Harrison Chang', 'https://unsplash.com/@harrisonchang', 'https://unsplash.com/photos/delicious-char-siu-pork-is-beautifully-plated-c1PNKwlEDKw', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'entertaining']::text[], array['roast']::text[], array['savory', 'aromatic']::text[], '{}'::text[], 'Guangdong', 'traditional', 'char-siu', 'classic', 'Refrigerate up to 4 days or freeze sliced up to 2 months.', null, 'owned', array['gluten', 'sesame', 'soy', 'wheat']::text[], array['pork']::text[], array['dairy_free']::text[], array['pork shoulder', 'hoisin sauce', 'soy sauce', 'shaoxing wine', 'five-spice powder', 'garlic', 'sesame oil', 'honey']::text[], 'five-spice powder|garlic|hoisin sauce|honey|pork shoulder|sesame oil|shaoxing wine|soy sauce',
  null, null, null, null, null, null, null, null)
