insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('e1f7f17a-a9fc-4d23-a6ec-862be922eca8', 1, 'Pork', '2½ lb boneless pork shoulder (butt), cut into strips about 2 inches wide and 1½ inches thick', 'boneless pork shoulder (butt)', 2.5, 'lb', 'cut into strips about 2 inches wide and 1½ inches thick', false),
  ('e1f7f17a-a9fc-4d23-a6ec-862be922eca8', 2, 'Marinade', '¼ cup hoisin sauce', 'hoisin sauce', 0.25, 'cup', null, false),
  ('e1f7f17a-a9fc-4d23-a6ec-862be922eca8', 3, 'Marinade', '3 tbsp soy sauce', 'soy sauce', 3, 'tbsp', null, false),
  ('e1f7f17a-a9fc-4d23-a6ec-862be922eca8', 4, 'Marinade', '1 tbsp dark soy sauce', 'dark soy sauce', 1, 'tbsp', null, true),
  ('e1f7f17a-a9fc-4d23-a6ec-862be922eca8', 5, 'Marinade', '2 tbsp Shaoxing wine, or dry sherry', 'Shaoxing wine', 2, 'tbsp', 'or dry sherry', false),
  ('e1f7f17a-a9fc-4d23-a6ec-862be922eca8', 6, 'Marinade', '2 tbsp sugar', 'sugar', 2, 'tbsp', null, false),
  ('e1f7f17a-a9fc-4d23-a6ec-862be922eca8', 7, 'Marinade', '1 tsp five-spice powder', 'five-spice powder', 1, 'tsp', null, false),
  ('e1f7f17a-a9fc-4d23-a6ec-862be922eca8', 8, 'Marinade', '3 cloves garlic, grated', 'garlic', 3, 'clove', 'grated', false),
  ('e1f7f17a-a9fc-4d23-a6ec-862be922eca8', 9, 'Marinade', '1 tsp toasted sesame oil', 'toasted sesame oil', 1, 'tsp', null, false),
  ('e1f7f17a-a9fc-4d23-a6ec-862be922eca8', 10, 'Marinade', '2 piece red fermented bean curd, mashed with 1 tbsp of its brine', 'red fermented bean curd', 2, 'piece', 'mashed with 1 tbsp of its brine', true),
  ('e1f7f17a-a9fc-4d23-a6ec-862be922eca8', 11, 'Glaze', '3 tbsp honey', 'honey', 3, 'tbsp', null, false),
  ('e1f7f17a-a9fc-4d23-a6ec-862be922eca8', 12, 'Glaze', '1 tbsp hot water', 'hot water', 1, 'tbsp', null, false);
delete from public.recipe_instructions where recipe_id = 'e1f7f17a-a9fc-4d23-a6ec-862be922eca8';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('e1f7f17a-a9fc-4d23-a6ec-862be922eca8', 1, 'Marinade', 'Whisk the marinade ingredients together and set aside 3 tablespoons in a small covered cup for the glaze before the pork goes in. Coat the pork in the rest and refrigerate, covered, at least 4 hours and ideally overnight.', 43200, null, null),
  ('e1f7f17a-a9fc-4d23-a6ec-862be922eca8', 2, 'Pork', 'Heat the oven to 375°F. Line a sheet pan with foil, pour in ½ inch of water and set a rack on top. Lay the pork on the rack, letting the excess marinade drip off, and roast 25 minutes.', 1500, 190.6, null),
  ('e1f7f17a-a9fc-4d23-a6ec-862be922eca8', 3, 'Glaze', 'Stir the reserved marinade with the honey and hot water. Turn the pork, brush it with glaze and roast 15 minutes more.', 900, null, null),
  ('e1f7f17a-a9fc-4d23-a6ec-862be922eca8', 4, 'Pork', 'Turn and brush again, then broil 3–4 minutes per side until the edges blacken in spots and the glaze bubbles; the center should reach at least 145°F (most cooks take shoulder to 160–175°F for tender slices). Watch closely — honey burns fast.', 480, null, 62.8),
  ('e1f7f17a-a9fc-4d23-a6ec-862be922eca8', 5, null, 'Rest 10 minutes, brush with any remaining glaze and slice ½ inch thick. Serve with rice and greens.', 600, null, null);

-- Steamed Whole Fish with Ginger & Scallion
