values ('9aa478d9-228c-45b8-80b4-6d734d7b4859', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'cantonese-steamed-whole-fish', 'steamed-whole-fish-with-ginger-and-scallion-9aa478', 'Steamed Whole Fish with Ginger & Scallion', 'A whole white fish steamed just until it flakes, then finished with seasoned soy and a sizzle of hot oil over shredded ginger and scallion — a Cantonese banquet centerpiece.', 'cantonese', 3, 15, 15, 30, 4, 'main', null, 0, array['stove']::text[], array['entertaining', 'holiday']::text[], array['Snapper, black bass or tilapia all work. For fillets, steam 6–8 minutes depending on thickness.', 'Ask the fishmonger to scale and gut the fish and trim the fins so it fits your plate.']::text[], 'https://images.unsplash.com/photo-1767436093457-84ea9122eb4e', 'Whole cooked fish topped with chopped green onions in sauce', 'wang binghua', 'https://unsplash.com/@wangbinghua', 'https://unsplash.com/photos/whole-fish-dish-with-chopped-green-onions-and-sauce-3wT2zoO2KV0', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'quick', 'entertaining']::text[], array['steam']::text[], array['fresh', 'savory']::text[], '{}'::text[], 'Guangdong', 'traditional', 'steamed-fish-ginger-scallion', 'classic', 'Best eaten right away; refrigerate leftovers up to 1 day and flake into congee or fried rice.', null, 'owned', array['fish', 'gluten', 'soy', 'wheat']::text[], array['fish']::text[], array['pescatarian', 'dairy_free']::text[], array['branzino bass', 'ginger', 'scallion', 'shaoxing wine', 'soy sauce', 'cilantro sprig', 'jasmine rice']::text[], 'branzino bass|cilantro sprig|ginger|jasmine rice|scallion|shaoxing wine|soy sauce',
  null, null, null, null, null, null, null, null)
