insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('9aa478d9-228c-45b8-80b4-6d734d7b4859', 1, null, '1 whole branzino or sea bass, about 2 lb, scaled and gutted', 'whole branzino or sea bass', 1, null, 'about 2 lb, scaled and gutted', false),
  ('9aa478d9-228c-45b8-80b4-6d734d7b4859', 2, null, '2 oz fresh ginger, half thinly sliced, half cut into fine matchsticks', 'fresh ginger', 2, 'oz', 'half thinly sliced, half cut into fine matchsticks', false),
  ('9aa478d9-228c-45b8-80b4-6d734d7b4859', 3, null, '6 scallions, 2 cut into 3-inch lengths, 4 cut into fine 3-inch strips', 'scallions', 6, null, '2 cut into 3-inch lengths, 4 cut into fine 3-inch strips', false),
  ('9aa478d9-228c-45b8-80b4-6d734d7b4859', 4, null, '1 tbsp Shaoxing wine, or dry sherry', 'Shaoxing wine', 1, 'tbsp', 'or dry sherry', false),
  ('9aa478d9-228c-45b8-80b4-6d734d7b4859', 5, null, '3 tbsp soy sauce', 'soy sauce', 3, 'tbsp', null, false),
  ('9aa478d9-228c-45b8-80b4-6d734d7b4859', 6, null, '3 tbsp hot water', 'hot water', 3, 'tbsp', null, false),
  ('9aa478d9-228c-45b8-80b4-6d734d7b4859', 7, null, '2 tsp sugar', 'sugar', 2, 'tsp', null, false),
  ('9aa478d9-228c-45b8-80b4-6d734d7b4859', 8, null, '3 tbsp vegetable oil', 'vegetable oil', 3, 'tbsp', null, false),
  ('9aa478d9-228c-45b8-80b4-6d734d7b4859', 9, null, '¼ cup cilantro sprigs', 'cilantro sprigs', 0.25, 'cup', null, false),
  ('9aa478d9-228c-45b8-80b4-6d734d7b4859', 10, null, '4 cups cooked jasmine rice, hot, to serve', 'cooked jasmine rice', 4, 'cup', 'hot, to serve', false);
delete from public.recipe_instructions where recipe_id = '9aa478d9-228c-45b8-80b4-6d734d7b4859';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('9aa478d9-228c-45b8-80b4-6d734d7b4859', 1, null, 'Pat the fish dry inside and out and cut 2–3 diagonal slashes down to the bone on each side. Lay the ginger slices and scallion lengths on a heatproof plate that fits your steamer, set the fish on top and tuck a few in the cavity. Drizzle with the Shaoxing wine.', 300, null, null),
  ('9aa478d9-228c-45b8-80b4-6d734d7b4859', 2, null, 'Set a rack in a wok or wide pot with 2 inches of water and bring to a rolling boil. Put the plate on the rack, cover and steam on high until the flesh is opaque, flakes easily at the backbone and reaches 145°F, 10–12 minutes for a 2-lb fish.', 720, null, 62.8),
  ('9aa478d9-228c-45b8-80b4-6d734d7b4859', 3, null, 'Lift out the plate carefully (use a towel or plate gripper). Pour off the steaming liquid and discard the cooked ginger and scallion. Pile the fresh ginger and scallion strips on the fish.', 120, null, null),
  ('9aa478d9-228c-45b8-80b4-6d734d7b4859', 4, null, 'Warm the soy sauce, hot water and sugar in a small pan until the sugar dissolves, then pour it around the fish.', 60, null, null),
  ('9aa478d9-228c-45b8-80b4-6d734d7b4859', 5, null, 'Heat the oil in a small pan until it shimmers and is very hot, about 375°F, and carefully pour it over the ginger and scallion — it will sizzle. Top with cilantro and serve with rice.', 120, 190.6, null);

