values ('71f20e4f-dd6f-47e7-83f7-94a074586782', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'hong-kong-wonton-noodle-soup', 'wonton-noodle-soup-71f20e', 'Wonton Noodle Soup', 'Silky shrimp and pork wontons and springy thin egg noodles in a clear, gingery broth with greens — the Hong Kong noodle-shop bowl.', 'cantonese', 2, 40, 30, 70, 4, 'main', null, 0, array['stove']::text[], array['comfort', 'freezer-friendly']::text[], array['Freeze extra wontons on a floured tray, then bag them; cook from frozen, adding 2 minutes.']::text[], 'https://images.unsplash.com/photo-1763994685090-c0927ff195d1', 'Bowl of wonton noodle soup with bok choy and green onions', 'Fenghua', 'https://unsplash.com/@fenghua1975', 'https://unsplash.com/photos/bowl-of-wonton-noodle-soup-with-green-onions-00E1ohHqVJ0', 'unsplash', true, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'comfort']::text[], array['stew', 'boil']::text[], array['savory']::text[], '{}'::text[], 'Hong Kong', 'traditional', 'wonton-noodle-soup', 'classic', 'Store broth, wontons and noodles separately. Broth keeps 4 days refrigerated; cooked noodles get soft, so cook them fresh.', null, 'owned', array['egg', 'gluten', 'sesame', 'shellfish', 'soy', 'wheat']::text[], array['pork', 'shellfish']::text[], array['dairy_free']::text[], array['chicken stock', 'ginger', 'soy sauce', 'white pepper', 'shrimp', 'ground pork', 'shaoxing wine', 'sesame oil', 'cornstarch', 'wonton wrapper', 'egg noodle', 'bok choy', 'scallion']::text[], 'bok choy|chicken stock|cornstarch|egg noodle|ginger|ground pork|scallion|sesame oil|shaoxing wine|shrimp|soy sauce|white pepper|wonton wrapper',
