insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('71f20e4f-dd6f-47e7-83f7-94a074586782', 1, 'Broth', 'Bring the stock, dried shrimp and ginger to a boil, then simmer 20 minutes. Strain, season with the soy sauce, sugar and white pepper, and keep hot.', 1200, null, null),
  ('71f20e4f-dd6f-47e7-83f7-94a074586782', 2, 'Wontons', 'Mix the shrimp, pork, soy sauce, Shaoxing wine, sugar, salt, sesame oil and cornstarch, stirring in one direction until sticky.', 300, null, null),
  ('71f20e4f-dd6f-47e7-83f7-94a074586782', 3, 'Wontons', 'Put a heaping teaspoon of filling in the center of a wrapper, wet the edges, fold into a triangle and press out the air, then bring the two side corners together and pinch. Set on a floured tray.', 1200, null, null),
  ('71f20e4f-dd6f-47e7-83f7-94a074586782', 4, 'Wontons', 'Bring a large pot of water to a boil. Cook the wontons until they float and the filling reaches 160°F, 4–5 minutes. Lift into four bowls.', 300, null, 71.1),
  ('71f20e4f-dd6f-47e7-83f7-94a074586782', 5, 'Bowls', 'In the same water, boil the noodles until just tender, 30–60 seconds, shaking them loose; drain and divide among the bowls. Blanch the greens 1 minute and add them too.', 120, null, null),
  ('71f20e4f-dd6f-47e7-83f7-94a074586782', 6, 'Bowls', 'Ladle the hot broth over everything, scatter with scallions and serve right away, with chili oil on the side if you like.', null, null, null);

