values ('c49a4306-31bd-440c-ad61-cf255cae7e6f', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'cha-siu-bao-steamed-bbq-pork-buns', 'cha-siu-bao-c49a43', 'Cha Siu Bao', 'Pillowy steamed buns that split open at the top around a sweet, savory char siu filling — the steamed dim sum version, which is the most common (a baked variation is in the tips).', 'cantonese', 3, 150, 30, 180, 6, 'starter', null, 0, array['stove']::text[], array['dim-sum', 'make-ahead', 'freezer-friendly']::text[], array['Use leftover char siu or buy it from a Chinese barbecue shop.', 'For baked buns, brush with beaten egg and bake at 350°F for 18–20 minutes until golden, then brush with honey water.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['baking', 'appetizer']::text[], array['stew', 'steam', 'boil']::text[], array['savory']::text[], '{}'::text[], 'Guangdong', 'traditional', 'cha-siu-bao', 'classic', 'Refrigerate up to 3 days or freeze up to 2 months; re-steam 8 minutes (12 from frozen).', null, 'owned', array['gluten', 'sesame', 'shellfish', 'soy', 'wheat']::text[], array['pork']::text[], array['dairy_free']::text[], array['instant yeast', 'baking powder', 'shallot', 'oyster sauce', 'soy sauce', 'cornstarch', 'siu pork', 'sesame oil']::text[], 'baking powder|cornstarch|instant yeast|oyster sauce|sesame oil|shallot|siu pork|soy sauce',
  null, null, null, null, null, null, null, null)
