  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 3, 'Dough', '2 tsp instant yeast', 'instant yeast', 2, 'tsp', null, false),
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 4, 'Dough', '¾ cup warm water, about 105°F, plus 1–2 tbsp as needed', 'warm water', 0.75, 'cup', 'about 105°F, plus 1–2 tbsp as needed', false),
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 5, 'Dough', '2 tbsp vegetable oil', 'vegetable oil', 2, 'tbsp', null, false),
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 6, 'Dough', '2 tsp baking powder', 'baking powder', 2, 'tsp', null, false),
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 7, 'Filling', '1 tbsp vegetable oil', 'vegetable oil', 1, 'tbsp', null, false),
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 8, 'Filling', '1 shallot, minced', 'shallot', 1, null, 'minced', false),
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 9, 'Filling', '2 tbsp oyster sauce', 'oyster sauce', 2, 'tbsp', null, false),
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 10, 'Filling', '1 tbsp soy sauce', 'soy sauce', 1, 'tbsp', null, false),
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 11, 'Filling', '1 tsp dark soy sauce', 'dark soy sauce', 1, 'tsp', null, true),
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 12, 'Filling', '1 tbsp sugar', 'sugar', 1, 'tbsp', null, false),
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 13, 'Filling', '½ cup water', 'water', 0.5, 'cup', null, false),
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 14, 'Filling', '1½ tbsp cornstarch, mixed with 2 tbsp water', 'cornstarch', 1.5, 'tbsp', 'mixed with 2 tbsp water', false),
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 15, 'Filling', '10 oz cooked char siu pork, cut into ¼-inch dice', 'cooked char siu pork', 10, 'oz', 'cut into ¼-inch dice', false),
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 16, 'Filling', '1 tsp toasted sesame oil', 'toasted sesame oil', 1, 'tsp', null, false);
delete from public.recipe_instructions where recipe_id = 'c49a4306-31bd-440c-ad61-cf255cae7e6f';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 1, 'Dough', 'Mix the flour, sugar and yeast in a large bowl. Add the water and oil and knead 8–10 minutes into a smooth, soft dough (add a spoonful more water if it feels dry). Cover and let rise somewhere warm until doubled, 1–1½ hours.', 5400, null, null),
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 2, 'Filling', 'Meanwhile, heat the oil in a small pan over medium heat and soften the shallot 1 minute. Add the oyster sauce, soy sauces, sugar and water and bring to a simmer. Stir in the cornstarch mixture and cook until very thick. Off the heat, stir in the char siu and sesame oil. Cool completely, then chill 20 minutes.', 1800, null, null),
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 3, 'Dough', 'Punch the dough down, flatten it, sprinkle with the baking powder and knead 2 minutes until evenly mixed. Divide into 12 pieces and roll each into a 4-inch round that''s thicker in the middle.', 900, null, null),
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 4, null, 'Put a heaping tablespoon of filling in the center of each round, gather the edge into pleats and pinch closed at the top. Set each bun on a 3-inch square of parchment, cover and rest 15 minutes.', 1200, null, null),
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 5, null, 'Steam in batches, 2 inches apart, over boiling water for 12 minutes. Turn off the heat and leave the lid on 3 minutes before opening so the buns don''t collapse.', 900, null, null),
  ('c49a4306-31bd-440c-ad61-cf255cae7e6f', 6, null, 'Serve warm.', null, null, null);

