values ('15fe396c-713a-4311-b081-c2c654e0ca34', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'taiwanese-beef-noodle-soup', 'beef-noodle-soup-15fe39', 'Beef Noodle Soup', 'Beef shank braised for hours with chili bean paste, star anise and tomato into a deep, spicy broth, served over chewy wheat noodles with bok choy and pickled mustard greens — Taiwan''s national dish.', 'taiwanese', 3, 25, 160, 185, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['comfort', 'make-ahead', 'freezer-friendly']::text[], array['In a pressure cooker, cook the beef and broth 45 minutes on high pressure with natural release.', 'Chili bean paste often contains wheat flour — check the label if that matters to you.']::text[], 'https://images.unsplash.com/photo-1774702541015-101e48834357', 'Bowl of beef noodle soup with sliced beef, chili oil and scallions', 'yang jia', 'https://unsplash.com/@jyredrose', 'https://unsplash.com/photos/bowl-of-noodles-with-sliced-meat-and-greens-WnPghXNUnZM', 'unsplash', true, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'comfort']::text[], array['stew', 'boil']::text[], array['spicy', 'tangy', 'fresh', 'savory', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'taiwanese-beef-noodle-soup', 'classic', 'Refrigerate the beef and broth up to 4 days or freeze up to 3 months; cook noodles fresh.', null, 'owned', array['gluten', 'soy', 'wheat']::text[], array['beef']::text[], array['dairy_free']::text[], array['beef shank', 'yellow onion', 'garlic', 'ginger', 'scallion', 'bean paste', 'tomato', 'shaoxing wine', 'soy sauce', 'rock sugar', 'star anise', 'sichuan peppercorn', 'cinnamon stick', 'bay leave', 'wheat noodle', 'bok choy', 'mustard green', 'cilantro']::text[], 'bay leave|bean paste|beef shank|bok choy|cilantro|cinnamon stick|garlic|ginger|mustard green|rock sugar|scallion|shaoxing wine|sichuan peppercorn|soy sauce|star anise|tomato|wheat noodle|yellow onion',
