delete from public.recipe_instructions where recipe_id = '15fe396c-713a-4311-b081-c2c654e0ca34';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('15fe396c-713a-4311-b081-c2c654e0ca34', 1, 'Soup', 'Cover the beef with cold water in a pot, bring to a boil and boil 5 minutes. Drain and rinse off the scum.', 720, null, null),
  ('15fe396c-713a-4311-b081-c2c654e0ca34', 2, 'Soup', 'Heat the oil in a Dutch oven over medium heat. Fry the onion, garlic, ginger and scallions until lightly browned, 4 minutes. Add the chili bean paste and stir until the oil turns red, 1 minute, then add the tomatoes and cook 2 minutes.', 420, null, null),
  ('15fe396c-713a-4311-b081-c2c654e0ca34', 3, 'Soup', 'Add the beef, Shaoxing wine, both soy sauces, rock sugar, star anise, Sichuan peppercorns, cinnamon, bay leaves and water. Bring to a boil, then cover and simmer on low until the beef is fork-tender (far past 145°F), 2–2½ hours.', 8100, null, 62.8),
  ('15fe396c-713a-4311-b081-c2c654e0ca34', 4, 'Soup', 'Skim off the fat, fish out the spices and taste the broth; add a splash of soy sauce or water to balance.', null, null, null),
  ('15fe396c-713a-4311-b081-c2c654e0ca34', 5, 'Bowls', 'Cook the noodles in a separate pot of boiling water following the package; add the bok choy for the last minute. Drain.', 360, null, null),
  ('15fe396c-713a-4311-b081-c2c654e0ca34', 6, 'Bowls', 'Divide the noodles and bok choy among bowls, ladle in the beef and broth and top with pickled greens, cilantro, scallions and chili oil.', null, null, null);

-- Tonkotsu Ramen
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
  status, categories, methods, flavors, occasions, region, authenticity, dish_key, variant, storage_notes, safety_note, text_license, allergens, proteins, diet_tags, core_ingredients, fingerprint,
  attribution, reviewed_by, reviewed_at, calories_per_serving, protein_g, carbs_g, fat_g, nutrition_source)
values ('ef4d6891-7676-43d6-8969-ea9609f52b77', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'tonkotsu-ramen-pressure-cooker', 'tonkotsu-ramen-ef4d68', 'Tonkotsu Ramen', 'Creamy, milky pork-bone broth with thin noodles, soy-braised pork belly and wood ear mushrooms in the Hakata style; adapted with a pressure cooker so the broth takes about 3 hours instead of 12 or more.', 'japanese', 3, 30, 200, 230, 4, 'main', null, 0, array['pressure_cooker', 'stove']::text[], array['project', 'comfort']::text[], array['No pressure cooker? Keep the bones at a rolling boil for 10–12 hours, topping up with water, for the traditional method.', 'Pork trotters are sold at Asian and Latin markets; a few chicken feet also add body.']::text[], 'https://images.unsplash.com/photo-1635379511574-bc167ca085c8', 'Bowl of tonkotsu ramen topped with slices of pork', 'Frank from 5 AM Ramen', 'https://unsplash.com/@5amramen', 'https://unsplash.com/photos/a-bowl-of-soup-with-meat-and-vegetables-vPMQl71yFDI', 'unsplash', true, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'comfort']::text[], array['pressure_cook', 'braise', 'stew', 'boil']::text[], array['tangy', 'savory']::text[], '{}'::text[], 'Fukuoka', 'adapted', 'tonkotsu-ramen', 'classic', 'Refrigerate broth up to 4 days (it sets to jelly) or freeze up to 3 months. Chashu keeps 5 days in its liquid.', 'Never fill a pressure cooker more than two-thirds full with bones and water, and let the pressure release naturally — opening it early can spray scalding broth.', 'owned', array['gluten', 'sesame', 'soy', 'wheat']::text[], array['pork']::text[], array['dairy_free']::text[], array['pork trotter', 'pork neck', 'yellow onion', 'garlic', 'ginger', 'pork belly', 'soy sauce', 'mirin', 'sake', 'ramen noodle', 'ear mushroom', 'scallion', 'red ginger', 'sesame seed']::text[], 'ear mushroom|garlic|ginger|mirin|pork belly|pork neck|pork trotter|ramen noodle|red ginger|sake|scallion|sesame seed|soy sauce|yellow onion',
  null, null, null, null, null, null, null, null)
