  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 1, 'Broth', '3 lb split pork trotters, ask the butcher to split them', 'split pork trotters', 3, 'lb', 'ask the butcher to split them', false),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 2, 'Broth', '2 lb pork neck bones', 'pork neck bones', 2, 'lb', null, false),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 3, 'Broth', '1 yellow onion, halved', 'yellow onion', 1, null, 'halved', false),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 4, 'Broth', '1 head garlic, halved crosswise', 'garlic', 1, 'head', 'halved crosswise', false),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 5, 'Broth', '2 oz fresh ginger, sliced', 'fresh ginger', 2, 'oz', 'sliced', false),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 6, 'Broth', '10 cups water, or to your pressure cooker''s max line', 'water', 10, 'cup', 'or to your pressure cooker''s max line', false),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 7, 'Chashu', '1½ lb skinless pork belly, in one slab', 'skinless pork belly', 1.5, 'lb', 'in one slab', false),
