  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 10, 'Chashu', '½ cup sake', 'sake', 0.5, 'cup', null, false),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 11, 'Chashu', '2 tbsp sugar', 'sugar', 2, 'tbsp', null, false),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 12, 'Chashu', '1 cup water', 'water', 1, 'cup', null, false),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 13, 'Bowls', '1 lb thin straight fresh ramen noodles, Hakata-style, about 4 portions', 'thin straight fresh ramen noodles', 1, 'lb', 'Hakata-style, about 4 portions', false),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 14, 'Bowls', '½ cup dried wood ear mushrooms (kikurage), soaked 20 minutes and thinly sliced', 'dried wood ear mushrooms (kikurage)', 0.5, 'cup', 'soaked 20 minutes and thinly sliced', false),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 15, 'Bowls', '4 scallions, thinly sliced', 'scallions', 4, null, 'thinly sliced', false),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 16, 'Bowls', '¼ cup pickled red ginger (beni shoga)', 'pickled red ginger (beni shoga)', 0.25, 'cup', null, false),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 17, 'Bowls', '2 tbsp toasted sesame seeds', 'toasted sesame seeds', 2, 'tbsp', null, false),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 18, 'Bowls', '1 tsp kosher salt, to taste', 'kosher salt', 1, 'tsp', 'to taste', false);
