insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 1, 'Broth', 'Cover the trotters and neck bones with cold water in a large pot, bring to a hard boil and boil 10 minutes. Drain, then rinse each bone under running water, scrubbing off any dark bits.', 900, null, null),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 2, 'Broth', 'Put the bones, onion, garlic and ginger in a 6- to 8-quart pressure cooker and add water no higher than two-thirds full. Cook on high pressure 2 hours, then let the pressure release naturally, about 20 minutes.', 8400, null, null),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 3, 'Chashu', 'Meanwhile, roll the pork belly into a tight log and tie it with kitchen string. Simmer it in a small covered pot with the soy sauce, mirin, sake, sugar and water over low heat, turning every 20 minutes, until tender and well past 145°F, about 90 minutes. Let it cool in the liquid.', 5400, null, 62.8),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 4, 'Broth', 'Pour the broth and bones into a large pot and boil hard, uncovered, for 30 minutes, stirring and mashing the bones, until the broth turns opaque and milky. Strain through a fine sieve; you want about 8 cups (add water if needed).', 1800, null, null),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 5, 'Bowls', 'Warm four bowls with hot water. Slice the chashu and spoon 3 tablespoons of its braising liquid into each bowl as the seasoning (tare). Boil the noodles until just firm, usually 60–90 seconds, and drain well.', 180, null, null),
  ('ef4d6891-7676-43d6-8969-ea9609f52b77', 6, 'Bowls', 'Ladle 2 cups of boiling broth into each bowl and stir to mix with the tare; taste and add salt. Add the noodles and top with chashu, wood ear, scallions, pickled ginger and sesame seeds.', null, null, null);

-- Shoyu Ramen
