values ('91e766a7-d220-4670-9547-97e55d3ef55b', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'tokyo-shoyu-ramen', 'shoyu-ramen-91e766', 'Shoyu Ramen', 'A clear, golden chicken and dashi broth seasoned with soy tare, with wavy noodles, braised pork, bamboo shoots and nori — the Tokyo-style bowl.', 'japanese', 3, 30, 175, 205, 4, 'main', null, 0, array['stove']::text[], array['project', 'comfort']::text[], array['Short on time? Simmer 8 cups of low-sodium chicken stock for 20 minutes with the shiitake, then steep the kombu and bonito as above.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'comfort']::text[], array['stew', 'boil']::text[], array['savory']::text[], '{}'::text[], 'Tokyo', 'traditional', 'shoyu-ramen', 'classic', 'Refrigerate broth up to 4 days or freeze up to 3 months; chashu and eggs keep 3 days in their liquid.', 'The eggs here aren''t cooked to 160°F. Use pasteurized eggs if you''re serving anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['egg', 'fish', 'gluten', 'soy', 'wheat']::text[], array['chicken', 'pork']::text[], array['dairy_free']::text[], array['back wing', 'yellow onion', 'ginger', 'garlic', 'shiitake mushroom', 'kombu', 'bonito flake', 'pork shoulder', 'soy sauce', 'mirin', 'sake', 'ramen noodle', 'menma', 'scallion', 'nori']::text[], 'back wing|bonito flake|garlic|ginger|kombu|menma|mirin|nori|pork shoulder|ramen noodle|sake|scallion|shiitake mushroom|soy sauce|yellow onion',
  null, null, null, null, null, null, null, null)
