delete from public.recipe_instructions where recipe_id = '91e766a7-d220-4670-9547-97e55d3ef55b';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('91e766a7-d220-4670-9547-97e55d3ef55b', 1, 'Broth', 'Rinse the chicken, put it in a large pot with the water and bring to a boil, skimming off the foam for 10 minutes. Lower to a bare simmer, add the onion, ginger, garlic and shiitake and simmer uncovered for 2½ hours (the chicken will be well past 165°F).', 9600, null, 73.9),
  ('91e766a7-d220-4670-9547-97e55d3ef55b', 2, 'Chashu', 'Meanwhile, simmer the pork in a small covered pot with the soy sauce, mirin, sake, sugar and water over low heat, turning every 30 minutes, until tender and at least 145°F, 1½–2 hours. Let it cool in the liquid.', 6300, null, 62.8),
  ('91e766a7-d220-4670-9547-97e55d3ef55b', 3, null, 'For eggs, lower them into boiling water for 6½ minutes, chill in ice water and peel. Marinate in ½ cup of the cooled chashu liquid for at least 2 hours.', 420, null, null),
  ('91e766a7-d220-4670-9547-97e55d3ef55b', 4, 'Broth', 'Turn off the heat, add the kombu and bonito flakes and steep 10 minutes. Strain through a fine sieve; you want about 8 cups. Keep it very hot.', 600, null, null),
  ('91e766a7-d220-4670-9547-97e55d3ef55b', 5, 'Tare', 'Simmer the soy sauce, mirin and sake for 1 minute, then stir in 2 tablespoons of chashu liquid.', 120, null, null),
  ('91e766a7-d220-4670-9547-97e55d3ef55b', 6, 'Bowls', 'Spoon 3 tablespoons of tare into each warmed bowl and add 2 cups of hot broth. Boil the noodles following the package, drain well and add to the bowls. Top with sliced chashu, menma, halved eggs, scallions and nori.', 180, null, null);

-- Nigiri Sushi
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
