values ('9e65bc7a-88bc-4a38-953a-02057cd3e81d', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'nigiri-sushi-tuna-salmon', 'nigiri-sushi-9e65bc', 'Nigiri Sushi', 'Hand-pressed fingers of seasoned sushi rice topped with slices of tuna and salmon — a home sushi night built on good fish and well-made rice.', 'japanese', 4, 75, 25, 100, 4, 'main', null, 0, array['stove']::text[], array['entertaining', 'date-night']::text[], array['"Sushi-grade" isn''t a regulated term — tell the fishmonger you''re serving it raw and ask whether it was frozen.', 'Most supermarket wasabi is horseradish-based; real wasabi is a treat if you can find it.']::text[], 'https://images.unsplash.com/photo-1791386809533-5c2e79e34665', 'Salmon, tuna and shrimp nigiri sushi on a black plate', 'Travis Palma', 'https://unsplash.com/@palmavisuals', 'https://unsplash.com/photos/assorted-nigiri-sushi-on-black-plate-d6IhYcbo84Q', 'unsplash', true, 'public', false,
  'pending_review', array['seafood_raw_bar', 'main', 'dinner', 'date_night', 'entertaining']::text[], array['boil', 'raw']::text[], array['tangy', 'savory']::text[], '{}'::text[], null, 'traditional', 'nigiri-sushi', 'classic', 'Eat the same day. Don''t keep raw-fish leftovers more than 24 hours in the fridge.', 'Nigiri is made with raw fish. Buy fish the fishmonger sells specifically for eating raw (it should have been frozen to kill parasites — farmed salmon and commercially frozen tuna are the safest choices), keep it refrigerated until you slice it, and eat within an hour. Not recommended for pregnant people, young children, older adults or anyone with a weakened immune system.', 'owned', array['fish', 'gluten', 'soy', 'wheat']::text[], array['fish']::text[], array['pescatarian', 'dairy_free']::text[], array['sushi rice', 'rice vinegar', 'sushi-grade tuna', 'sushi-grade salmon', 'wasabi paste', 'soy sauce', 'sushi ginger']::text[], 'rice vinegar|soy sauce|sushi ginger|sushi rice|sushi-grade salmon|sushi-grade tuna|wasabi paste',
  null, null, null, null, null, null, null, null)
