insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('9e65bc7a-88bc-4a38-953a-02057cd3e81d', 1, 'Rice', '2½ cups Japanese short-grain sushi rice', 'Japanese short-grain sushi rice', 2.5, 'cup', null, false),
  ('9e65bc7a-88bc-4a38-953a-02057cd3e81d', 2, 'Rice', '2¾ cups water', 'water', 2.75, 'cup', null, false),
  ('9e65bc7a-88bc-4a38-953a-02057cd3e81d', 3, 'Rice', '⅓ cup rice vinegar', 'rice vinegar', 0.33, 'cup', null, false),
  ('9e65bc7a-88bc-4a38-953a-02057cd3e81d', 4, 'Rice', '2 tbsp sugar', 'sugar', 2, 'tbsp', null, false),
  ('9e65bc7a-88bc-4a38-953a-02057cd3e81d', 5, 'Rice', '2 tsp kosher salt', 'kosher salt', 2, 'tsp', null, false),
  ('9e65bc7a-88bc-4a38-953a-02057cd3e81d', 6, 'Fish', '12 oz sushi-grade tuna, one block, kept cold', 'sushi-grade tuna', 12, 'oz', 'one block, kept cold', false),
  ('9e65bc7a-88bc-4a38-953a-02057cd3e81d', 7, 'Fish', '12 oz sushi-grade salmon, one skinless block, previously frozen, kept cold', 'sushi-grade salmon', 12, 'oz', 'one skinless block, previously frozen, kept cold', false),
  ('9e65bc7a-88bc-4a38-953a-02057cd3e81d', 8, 'To serve', '2 tsp wasabi paste', 'wasabi paste', 2, 'tsp', null, false),
  ('9e65bc7a-88bc-4a38-953a-02057cd3e81d', 9, 'To serve', '¼ cup soy sauce', 'soy sauce', 0.25, 'cup', null, false),
  ('9e65bc7a-88bc-4a38-953a-02057cd3e81d', 10, 'To serve', '¼ cup pickled sushi ginger (gari)', 'pickled sushi ginger (gari)', 0.25, 'cup', null, false),
  ('9e65bc7a-88bc-4a38-953a-02057cd3e81d', 11, 'To serve', '½ cup water, mixed with 1 tbsp rice vinegar, for wetting your hands', 'water', 0.5, 'cup', 'mixed with 1 tbsp rice vinegar, for wetting your hands', false);
delete from public.recipe_instructions where recipe_id = '9e65bc7a-88bc-4a38-953a-02057cd3e81d';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('9e65bc7a-88bc-4a38-953a-02057cd3e81d', 1, 'Rice', 'Rinse the rice in several changes of cold water, swishing gently, until the water runs almost clear. Drain in a sieve for 15 minutes.', 1200, null, null),
  ('9e65bc7a-88bc-4a38-953a-02057cd3e81d', 2, 'Rice', 'Put the rice and water in a heavy pot, bring to a boil, then cover and cook on the lowest heat for 15 minutes. Turn off the heat and rest, covered, 10 minutes (or use a rice cooker).', 1500, null, null),
  ('9e65bc7a-88bc-4a38-953a-02057cd3e81d', 3, 'Rice', 'Warm the vinegar, sugar and salt until dissolved. Spread the rice in a wide bowl and fold in the vinegar with a paddle using slicing strokes, fanning it as you go, until glossy and about body temperature. Cover with a damp towel; don''t refrigerate.', 900, null, null),
  ('9e65bc7a-88bc-4a38-953a-02057cd3e81d', 4, 'Fish', 'Keep the raw fish in the fridge until the moment you slice it. With your sharpest long knife, cut across the grain on a slight angle into slices about 3 inches long, 1 inch wide and ¼ inch thick, using one long pull per slice.', 900, null, null),
  ('9e65bc7a-88bc-4a38-953a-02057cd3e81d', 5, null, 'Wet your hands with the vinegared water. Gently shape about 1 tablespoon of rice into a firm oblong. Smear a dab of wasabi on the underside of a slice of fish, lay it over the rice and press with two fingers to mold it on. Repeat to make about 32 pieces.', 1800, null, null),
  ('9e65bc7a-88bc-4a38-953a-02057cd3e81d', 6, null, 'Serve right away with soy sauce and pickled ginger; dip the fish side, not the rice, into the soy.', null, null, null);

-- Homemade Maki Rolls
