values ('55ad02e4-ae0c-4941-be1a-56beae5250b2', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'homemade-maki-rolls', 'homemade-maki-rolls-55ad02', 'Homemade Maki Rolls', 'Seaweed-wrapped sushi rolls filled with cooked shrimp, avocado and cucumber — the California-roll style most home cooks start with, adapted with cooked shrimp in place of crab so there''s no raw fish.', 'japanese', 2, 60, 25, 85, 4, 'main', null, 0, array['stove']::text[], array['kid-friendly', 'date-night']::text[], array['No bamboo mat? A clean kitchen towel covered with plastic wrap works.', 'For a simple cucumber roll (kappa maki), use half sheets of nori and a single strip of cucumber.']::text[], 'https://images.unsplash.com/photo-1780291117619-c58ee7aa740e', 'Plate of salmon sushi rolls with pickled ginger and chopsticks', 'Brooke Balentine', 'https://unsplash.com/@brookebalentine', 'https://unsplash.com/photos/a-plate-of-sushi-rolls-with-chopsticks-and-ginger-XrJHeBNTNFI', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'comfort', 'date_night']::text[], array['boil']::text[], array['spicy', 'tangy', 'savory']::text[], '{}'::text[], null, 'adapted', 'maki-rolls', 'classic', 'Best within a few hours. Refrigerate up to 1 day, well wrapped; the rice firms up when cold.', null, 'owned', array['egg', 'gluten', 'sesame', 'shellfish', 'soy', 'wheat']::text[], array['shellfish']::text[], array['pescatarian', 'dairy_free']::text[], array['sushi rice', 'rice vinegar', 'nori', 'shrimp', 'avocado', 'english cucumber', 'sesame seed', 'soy sauce', 'wasabi paste', 'sushi ginger']::text[], 'avocado|english cucumber|nori|rice vinegar|sesame seed|shrimp|soy sauce|sushi ginger|sushi rice|wasabi paste',
  null, null, null, null, null, null, null, null)
