insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 1, 'Rice', '2 cups Japanese short-grain sushi rice', 'Japanese short-grain sushi rice', 2, 'cup', null, false),
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 2, 'Rice', '2¼ cups water', 'water', 2.25, 'cup', null, false),
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 3, 'Rice', '¼ cup rice vinegar', 'rice vinegar', 0.25, 'cup', null, false),
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 4, 'Rice', '1½ tbsp sugar', 'sugar', 1.5, 'tbsp', null, false),
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 5, 'Rice', '1½ tsp kosher salt', 'kosher salt', 1.5, 'tsp', null, false),
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 6, 'Rolls', '6 sheet nori', 'nori', 6, 'sheet', null, false),
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 7, 'Rolls', '8 oz cooked peeled shrimp, halved lengthwise', 'cooked peeled shrimp', 8, 'oz', 'halved lengthwise', false),
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 8, 'Rolls', '2 ripe avocados, sliced', 'ripe avocados', 2, null, 'sliced', false),
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 9, 'Rolls', '1 English cucumber, seeded and cut into long thin strips', 'English cucumber', 1, null, 'seeded and cut into long thin strips', false),
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 10, 'Rolls', '2 tbsp toasted sesame seeds', 'toasted sesame seeds', 2, 'tbsp', null, false),
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 11, 'To serve', '¼ cup soy sauce', 'soy sauce', 0.25, 'cup', null, false),
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 12, 'To serve', '2 tsp wasabi paste', 'wasabi paste', 2, 'tsp', null, false),
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 13, 'To serve', '¼ cup pickled sushi ginger (gari)', 'pickled sushi ginger (gari)', 0.25, 'cup', null, false),
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 14, 'To serve', '¼ cup mayonnaise, mixed with 1 tbsp sriracha for spicy mayo', 'mayonnaise', 0.25, 'cup', 'mixed with 1 tbsp sriracha for spicy mayo', true);
delete from public.recipe_instructions where recipe_id = '55ad02e4-ae0c-4941-be1a-56beae5250b2';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 1, 'Rice', 'Rinse the rice in several changes of cold water until the water runs almost clear, then drain 15 minutes.', 900, null, null),
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 2, 'Rice', 'Bring the rice and water to a boil in a heavy pot, cover and cook on the lowest heat 15 minutes. Rest off the heat, covered, 10 minutes.', 1500, null, null),
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 3, 'Rice', 'Dissolve the sugar and salt in the vinegar, fold it into the rice in a wide bowl and fan until glossy and about body temperature. Cover with a damp towel.', 900, null, null),
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 4, 'Rolls', 'Set a nori sheet shiny-side down on a bamboo rolling mat. With wet hands, spread about ¾ cup rice evenly over it, leaving a 1-inch strip bare along the far edge. Sprinkle with sesame seeds and lay a line of shrimp, avocado and cucumber across the rice a third of the way from you.', 300, null, null),
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 5, 'Rolls', 'Lift the near edge of the mat and roll it over the filling, tucking it in, then squeeze gently and keep rolling to the bare strip. Dab the strip with water to seal. Repeat with the rest.', 1200, null, null),
  ('55ad02e4-ae0c-4941-be1a-56beae5250b2', 6, null, 'With a sharp knife wiped with a damp cloth between cuts, slice each roll into 8 pieces. Serve with soy sauce, wasabi, ginger and spicy mayo.', 300, null, null);

