values ('5b61f79c-7240-432d-8067-e9000fcbc140', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'shrimp-vegetable-tempura', 'shrimp-and-vegetable-tempura-5b61f7', 'Shrimp and Vegetable Tempura', 'Shrimp, sweet potato, eggplant and shiitake in a lacy, barely-there batter, deep-fried until crisp and served with a warm dashi dipping sauce and grated daikon.', 'japanese', 3, 30, 35, 65, 4, 'main', null, 0, array['stove']::text[], array['entertaining']::text[], array['Cold batter plus hot oil is the secret: mix it at the last minute and don''t overstir.', 'Instant dashi granules usually contain bonito (fish), so the dipping sauce isn''t vegetarian.']::text[], 'https://images.pexels.com/photos/3622477/pexels-photo-3622477.jpeg', 'Golden shrimp tempura on a ceramic plate', 'Jonathan Borba', 'https://www.pexels.com/@jonathanborba/', 'https://www.pexels.com/photo/tempura-on-ceramic-plate-3622477/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner', 'entertaining']::text[], array['stew', 'fry']::text[], array['savory']::text[], '{}'::text[], null, 'traditional', 'shrimp-vegetable-tempura', 'classic', 'Best eaten immediately. Re-crisp leftovers on a rack in a 400°F oven for 5–8 minutes.', null, 'owned', array['egg', 'fish', 'gluten', 'shellfish', 'soy', 'wheat']::text[], array['shellfish']::text[], array['pescatarian', 'dairy_free']::text[], array['dashi', 'soy sauce', 'mirin', 'daikon radish', 'shrimp', 'sweet potato', 'japanese eggplant', 'shiitake mushroom', 'shishito pepper', 'cornstarch', 'egg', 'sparkling water']::text[], 'cornstarch|daikon radish|dashi|egg|japanese eggplant|mirin|shiitake mushroom|shishito pepper|shrimp|soy sauce|sparkling water|sweet potato',
  null, null, null, null, null, null, null, null)
