insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 1, 'Dipping sauce', '1 cup dashi, or water with ½ tsp instant dashi granules', 'dashi', 1, 'cup', 'or water with ½ tsp instant dashi granules', false),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 2, 'Dipping sauce', '¼ cup soy sauce', 'soy sauce', 0.25, 'cup', null, false),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 3, 'Dipping sauce', '¼ cup mirin', 'mirin', 0.25, 'cup', null, false),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 4, 'Dipping sauce', '½ cup daikon radish, finely grated and squeezed', 'daikon radish', 0.5, 'cup', 'finely grated and squeezed', false),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 5, 'Fry', '1 lb large shrimp, 16–20 per lb, peeled with tails on, deveined', 'large shrimp', 1, 'lb', '16–20 per lb, peeled with tails on, deveined', false),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 6, 'Fry', '1 small Japanese sweet potato, about 8 oz, sliced ¼ inch thick', 'small Japanese sweet potato', 1, null, 'about 8 oz, sliced ¼ inch thick', false),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 7, 'Fry', '1 Japanese eggplant, sliced ¼ inch thick on the diagonal', 'Japanese eggplant', 1, null, 'sliced ¼ inch thick on the diagonal', false),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 8, 'Fry', '8 shiitake mushrooms, stems removed', 'shiitake mushrooms', 8, null, 'stems removed', false),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 9, 'Fry', '8 shishito peppers, pricked once with a knife', 'shishito peppers', 8, null, 'pricked once with a knife', false),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 10, 'Fry', '8 cups vegetable oil, for deep-frying', 'vegetable oil', 8, 'cup', 'for deep-frying', false),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 11, 'Batter', '1¼ cups all-purpose flour, or cake flour, divided', 'all-purpose flour', 1.25, 'cup', 'or cake flour, divided', false),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 12, 'Batter', '2 tbsp cornstarch', 'cornstarch', 2, 'tbsp', null, false),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 13, 'Batter', '1 large egg', 'large egg', 1, null, null, false),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 14, 'Batter', '1 cup ice-cold sparkling water', 'ice-cold sparkling water', 1, 'cup', null, false),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 15, 'Batter', '1 tsp flaky sea salt, to serve', 'flaky sea salt', 1, 'tsp', 'to serve', false);
delete from public.recipe_instructions where recipe_id = '5b61f79c-7240-432d-8067-e9000fcbc140';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 1, 'Dipping sauce', 'Simmer the dashi, soy sauce and mirin for 1 minute and keep warm. Put the grated daikon in a small dish.', 120, null, null),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 2, 'Fry', 'Make 3–4 shallow cuts across the underside of each shrimp and press gently to straighten them so they don''t curl. Pat the shrimp and vegetables very dry.', 900, null, null),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 3, 'Fry', 'Pour the oil into a heavy pot no more than half full and heat to 340–350°F. Keep children and pets away and never leave hot oil unattended.', 600, 176.7, null),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 4, 'Batter', 'Right before frying, beat the egg with the sparkling water. Add 1 cup of the flour and the cornstarch all at once and stir just a few strokes with chopsticks — leave it lumpy. Set the bowl over ice.', 120, null, null),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 5, 'Fry', 'Dust the vegetables in the remaining flour, dip in batter and let the excess drip off. Deep-fry a few at a time until crisp and pale golden and the sweet potato is tender, 2–3 minutes. Drain on a rack and skim out loose bits of batter between batches.', 720, 176.7, null),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 6, 'Fry', 'Dust and batter the shrimp and fry 4–5 at a time until the coating is crisp and the shrimp are opaque and 145°F, 2–3 minutes.', 480, 176.7, 62.8),
  ('5b61f79c-7240-432d-8067-e9000fcbc140', 7, null, 'Serve at once with the warm dipping sauce, grated daikon and a pinch of salt.', null, null, null);

