values ('a84e223c-8ee2-4cf2-8a17-d6fced94fd5b', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'yakitori-negima-tare', 'yakitori-a84e22', 'Yakitori', 'Skewers of juicy chicken thigh and scallion grilled over high heat and lacquered with a sweet soy tare — negima, the most popular yakitori.', 'japanese', 2, 35, 25, 60, 4, 'main', null, 0, array['grill', 'stove']::text[], array['weeknight', 'kid-friendly', 'summer']::text[], array['No grill? Cook under a hot broiler on a foil-lined pan, 4 inches from the heat, turning often.', 'For shio (salt) yakitori, skip the tare and season with salt before grilling, then finish with lemon.']::text[], 'https://images.unsplash.com/photo-1775379995350-43098b52d8ed', 'Two grilled chicken yakitori skewers with a lemon slice', 'Jaz. Mine', 'https://unsplash.com/@jazmine_r4', 'https://unsplash.com/photos/two-skewers-of-grilled-chicken-with-lemon-slice-WLJdIA86-k0', 'unsplash', true, 'public', false,
  'pending_review', array['grilling', 'main', 'dinner', 'comfort']::text[], array['grill', 'stew']::text[], array['savory']::text[], '{}'::text[], null, 'traditional', 'yakitori', 'classic', 'Refrigerate up to 3 days; reheat in a hot skillet or oven.', null, 'owned', array['gluten', 'soy', 'wheat']::text[], array['chicken']::text[], array['dairy_free']::text[], array['soy sauce', 'mirin', 'sake', 'scallion', 'bamboo skewer']::text[], 'bamboo skewer|mirin|sake|scallion|soy sauce',
  null, null, null, null, null, null, null, null)
