  ('a84e223c-8ee2-4cf2-8a17-d6fced94fd5b', 1, 'Tare', '½ cup soy sauce', 'soy sauce', 0.5, 'cup', null, false),
  ('a84e223c-8ee2-4cf2-8a17-d6fced94fd5b', 2, 'Tare', '½ cup mirin', 'mirin', 0.5, 'cup', null, false),
  ('a84e223c-8ee2-4cf2-8a17-d6fced94fd5b', 3, 'Tare', '¼ cup sake', 'sake', 0.25, 'cup', null, false),
  ('a84e223c-8ee2-4cf2-8a17-d6fced94fd5b', 4, 'Tare', '3 tbsp sugar', 'sugar', 3, 'tbsp', null, false),
  ('a84e223c-8ee2-4cf2-8a17-d6fced94fd5b', 5, 'Skewers', '2 lb boneless, skin-on chicken thighs, or skinless, cut into 1-inch pieces', 'boneless, skin-on chicken thighs', 2, 'lb', 'or skinless, cut into 1-inch pieces', false),
  ('a84e223c-8ee2-4cf2-8a17-d6fced94fd5b', 6, 'Skewers', '2 bunch scallions, white and light green parts, cut into 1½-inch lengths', 'scallions', 2, 'bunch', 'white and light green parts, cut into 1½-inch lengths', false),
  ('a84e223c-8ee2-4cf2-8a17-d6fced94fd5b', 7, 'Skewers', '16 bamboo skewers, soaked in water 30 minutes', 'bamboo skewers', 16, null, 'soaked in water 30 minutes', false),
  ('a84e223c-8ee2-4cf2-8a17-d6fced94fd5b', 8, 'Skewers', '1 tbsp vegetable oil, for the grill', 'vegetable oil', 1, 'tbsp', 'for the grill', false),
  ('a84e223c-8ee2-4cf2-8a17-d6fced94fd5b', 9, 'Skewers', '1 tsp shichimi togarashi, to serve', 'shichimi togarashi', 1, 'tsp', 'to serve', true);
