insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('a84e223c-8ee2-4cf2-8a17-d6fced94fd5b', 1, 'Skewers', 'Soak the skewers in water for 30 minutes so they don''t burn.', 1800, null, null),
  ('a84e223c-8ee2-4cf2-8a17-d6fced94fd5b', 2, 'Tare', 'Simmer the soy sauce, mirin, sake and sugar in a small pan until reduced by about a third and syrupy, 10–12 minutes. Pour a third into a separate dish for serving; use the rest for basting.', 720, null, null),
  ('a84e223c-8ee2-4cf2-8a17-d6fced94fd5b', 3, 'Skewers', 'Thread the chicken and scallion pieces alternately onto the skewers, packing them snugly.', 900, null, null),
  ('a84e223c-8ee2-4cf2-8a17-d6fced94fd5b', 4, 'Skewers', 'Heat a grill to medium-high and oil the grates. Grill the skewers, turning every 1–2 minutes, until the fat renders and the chicken is lightly charred, about 8 minutes.', 480, null, null),
  ('a84e223c-8ee2-4cf2-8a17-d6fced94fd5b', 5, 'Tare', 'Brush with the basting tare and turn; repeat 2–3 times over the last 3–4 minutes until glossy and the chicken reaches 165°F.', 240, null, 73.9),
  ('a84e223c-8ee2-4cf2-8a17-d6fced94fd5b', 6, null, 'Serve with the reserved tare and shichimi togarashi.', null, null, null);

-- Matcha Mochi
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
