values ('ac080b3a-5c8a-4f20-83b4-78d7b35c83ed', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'matcha-mochi-daifuku', 'matcha-mochi-ac080b', 'Matcha Mochi', 'Soft, chewy matcha-tinted rice cakes wrapped around sweet red bean paste — microwave matcha daifuku, the most common way to make mochi at home.', 'japanese', 2, 35, 4, 39, 4, 'dessert', 'plated', 0, array['microwave']::text[], array['make-ahead', 'kid-friendly']::text[], array['Use mochiko or another sweet (glutinous-type) rice flour — regular rice flour won''t turn stretchy.', 'Culinary-grade matcha is fine here and much cheaper than ceremonial grade.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['dessert', 'comfort']::text[], '{}'::text[], array['sweet']::text[], '{}'::text[], null, 'traditional', 'matcha-mochi', 'classic', 'Keep wrapped at room temperature and eat within 2 days; mochi hardens in the fridge. Freeze individually wrapped up to 1 month and thaw at room temperature.', 'Mochi is very sticky and a known choking risk. Cut it into small pieces for young children and older adults, and eat it slowly with something to drink.', 'owned', '{}'::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], array['bean paste', 'rice flour', 'matcha powder', 'cornstarch']::text[], 'bean paste|cornstarch|matcha powder|rice flour',
  null, null, null, null, null, null, null, null)
