delete from public.recipe_ingredients where recipe_id = 'ac080b3a-5c8a-4f20-83b4-78d7b35c83ed';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('ac080b3a-5c8a-4f20-83b4-78d7b35c83ed', 1, 'Filling', '¾ cup sweetened red bean paste (anko), smooth or chunky', 'sweetened red bean paste (anko)', 0.75, 'cup', 'smooth or chunky', false),
  ('ac080b3a-5c8a-4f20-83b4-78d7b35c83ed', 2, 'Mochi', '1 cup sweet rice flour (mochiko)', 'sweet rice flour (mochiko)', 1, 'cup', null, false),
  ('ac080b3a-5c8a-4f20-83b4-78d7b35c83ed', 3, 'Mochi', '2 tsp matcha powder', 'matcha powder', 2, 'tsp', null, false),
  ('ac080b3a-5c8a-4f20-83b4-78d7b35c83ed', 4, 'Mochi', '¼ cup sugar', 'sugar', 0.25, 'cup', null, false),
  ('ac080b3a-5c8a-4f20-83b4-78d7b35c83ed', 5, 'Mochi', '¾ cup water', 'water', 0.75, 'cup', null, false),
  ('ac080b3a-5c8a-4f20-83b4-78d7b35c83ed', 6, 'Dusting', '⅓ cup cornstarch, or potato starch', 'cornstarch', 0.33, 'cup', 'or potato starch', false),
  ('ac080b3a-5c8a-4f20-83b4-78d7b35c83ed', 7, 'Dusting', '1 tsp matcha powder', 'matcha powder', 1, 'tsp', null, false);
delete from public.recipe_instructions where recipe_id = 'ac080b3a-5c8a-4f20-83b4-78d7b35c83ed';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('ac080b3a-5c8a-4f20-83b4-78d7b35c83ed', 1, 'Filling', 'Scoop the bean paste into 8 balls (about 1½ tablespoons each) on parchment and freeze 20 minutes to firm up.', 1200, null, null),
  ('ac080b3a-5c8a-4f20-83b4-78d7b35c83ed', 2, 'Mochi', 'Whisk the sweet rice flour, matcha and sugar in a microwave-safe bowl, then whisk in the water until smooth.', null, null, null),
  ('ac080b3a-5c8a-4f20-83b4-78d7b35c83ed', 3, 'Mochi', 'Cover loosely and cook in the microwave on high 1 minute, then stir with a wet spatula. Microwave 1 minute more and stir again, then 30–60 seconds until the dough is glossy, slightly translucent and has no white streaks.', 180, null, null),
  ('ac080b3a-5c8a-4f20-83b4-78d7b35c83ed', 4, 'Dusting', 'Mix the cornstarch and matcha and dust a tray heavily. Scrape the hot dough onto it, dust the top and let it cool 2–3 minutes until you can handle it. Cut into 8 pieces.', 300, null, null),
  ('ac080b3a-5c8a-4f20-83b4-78d7b35c83ed', 5, null, 'Flatten each piece into a 3-inch round, set a ball of bean paste in the center and pull the edges up and around it, pinching to seal. Set seam-side down and brush off excess starch.', 900, null, null);

