values ('1ecc37fa-27f8-4292-99d9-e7cb0e40e079', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'la-galbi-grilled-short-ribs', 'galbi-grilled-short-ribs-1ecc37', 'Galbi (Grilled Short Ribs)', 'Thin, cross-cut beef short ribs soaked in a soy, Asian pear and garlic marinade, then seared over high heat until caramelized — made with the LA-style flanken cut most Korean home cooks use today.', 'korean', 3, 20, 15, 275, 4, 'main', null, 240, array['grill', 'blender']::text[], array['entertaining', 'summer', 'make-ahead']::text[], array['No grill? Sear in a very hot cast-iron skillet or under the broiler, 3 minutes per side.', 'Store-bought ssamjang usually contains wheat — check the label if that matters to you.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['grilling', 'main', 'dinner', 'entertaining']::text[], array['grill']::text[], array['savory']::text[], '{}'::text[], null, 'traditional', 'galbi', 'classic', 'Refrigerate cooked ribs up to 3 days. Raw marinated ribs freeze well for up to 3 months; thaw in the fridge.', null, 'owned', array['gluten', 'sesame', 'soy', 'wheat']::text[], array['beef']::text[], array['dairy_free']::text[], array['short rib', 'asian pear', 'yellow onion', 'garlic', 'ginger', 'soy sauce', 'brown sugar', 'mirin', 'sesame oil', 'scallion', 'sesame seed', 'bibb lettuce', 'short-grain rice']::text[], 'asian pear|bibb lettuce|brown sugar|garlic|ginger|mirin|scallion|sesame oil|sesame seed|short rib|short-grain rice|soy sauce|yellow onion',
  null, null, null, null, null, null, null, null)
