delete from public.recipe_instructions where recipe_id = '1ecc37fa-27f8-4292-99d9-e7cb0e40e079';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('1ecc37fa-27f8-4292-99d9-e7cb0e40e079', 1, 'Ribs', 'Rinse the ribs under cold water to wash off any bone dust and pat dry.', 300, null, null),
  ('1ecc37fa-27f8-4292-99d9-e7cb0e40e079', 2, 'Marinade', 'Blend the pear, onion, garlic and ginger with the soy sauce, water, brown sugar and mirin until smooth. Stir in the sesame oil, pepper and scallions.', 300, null, null),
  ('1ecc37fa-27f8-4292-99d9-e7cb0e40e079', 3, 'Ribs', 'Layer the ribs in a dish or zip-top bag, pour over the marinade and refrigerate at least 4 hours or up to 24, turning once.', 14400, null, null),
  ('1ecc37fa-27f8-4292-99d9-e7cb0e40e079', 4, 'Ribs', 'Heat a grill to high and oil the grates. Shake off excess marinade and grill the ribs until well charred and caramelized and 145°F, 3–4 minutes per side. Move them off the flames if the sugar flares up.', 480, null, 62.8),
  ('1ecc37fa-27f8-4292-99d9-e7cb0e40e079', 5, null, 'Rest 3 minutes, then snip between the bones into pieces with kitchen shears. Sprinkle with sesame seeds and serve with lettuce for wrapping, rice and ssamjang.', 180, null, null);

-- Korean Fried Chicken
