values ('96a857aa-33e7-484a-b028-ada2fce345ef', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'korean-fried-chicken-yangnyeom', 'korean-fried-chicken-96a857', 'Korean Fried Chicken', 'Double-fried, shatteringly crisp chicken wings tossed in a sticky, sweet-spicy gochujang glaze — yangnyeom chicken, the most popular sauced style.', 'korean', 3, 25, 50, 75, 4, 'main', null, 0, array['stove']::text[], array['comfort', 'game-day', 'spicy']::text[], array['Most gochujang contains wheat — check the label if that matters for anyone you''re feeding.', 'The rest between the two fries lets moisture escape, which is what makes the crust stay crisp under the glaze.']::text[], 'https://images.pexels.com/photos/5773996/pexels-photo-5773996.jpeg', 'Platter of Korean fried chicken with garnishes', 'Luis Becerra Fotógrafo', 'https://www.pexels.com/@luisbecerrafotografo/', 'https://www.pexels.com/photo/fried-chicken-on-ceramic-plate-5773996/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner']::text[], array['stew', 'fry']::text[], array['spicy', 'tangy', 'savory']::text[], '{}'::text[], null, 'traditional', 'korean-fried-chicken', 'classic', 'Best fresh. Refrigerate up to 2 days and re-crisp on a rack in a 400°F oven or air fryer for 8–10 minutes.', null, 'owned', array['gluten', 'sesame', 'soy', 'wheat']::text[], array['chicken']::text[], array['dairy_free']::text[], array['chicken wing', 'garlic', 'potato starch', 'baking powder', 'gochujang', 'ketchup', 'honey', 'soy sauce', 'rice vinegar', 'sesame oil', 'sesame seed', 'scallion']::text[], 'baking powder|chicken wing|garlic|gochujang|honey|ketchup|potato starch|rice vinegar|scallion|sesame oil|sesame seed|soy sauce',
  null, null, null, null, null, null, null, null)
