delete from public.recipe_instructions where recipe_id = '96a857aa-33e7-484a-b028-ada2fce345ef';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('96a857aa-33e7-484a-b028-ada2fce345ef', 1, 'Chicken', 'Pat the wings very dry and toss with the salt, pepper and garlic. Whisk the starch, flour and baking powder in a large bowl, add the wings and toss until evenly coated. Shake off the excess and rest on a rack 10 minutes.', 900, null, null),
  ('96a857aa-33e7-484a-b028-ada2fce345ef', 2, 'Chicken', 'Pour the oil into a heavy pot no more than half full and heat to 325°F. Keep children and pets away and never leave hot oil unattended.', 600, 162.8, null),
  ('96a857aa-33e7-484a-b028-ada2fce345ef', 3, 'Chicken', 'Deep-fry the wings in batches, without crowding, until pale golden and 165°F at the thickest part, 8–10 minutes. Drain on a rack and rest 10 minutes.', 1500, 162.8, 73.9),
  ('96a857aa-33e7-484a-b028-ada2fce345ef', 4, 'Chicken', 'Raise the oil to 375°F and fry the wings again in batches until deep golden and very crisp, 3–4 minutes. Drain on the rack.', 600, 190.6, null),
  ('96a857aa-33e7-484a-b028-ada2fce345ef', 5, 'Glaze', 'Simmer the gochujang, ketchup, honey, soy sauce, vinegar, garlic and sesame oil in a large skillet until bubbling and glossy, 2–3 minutes.', 180, null, null),
  ('96a857aa-33e7-484a-b028-ada2fce345ef', 6, null, 'Off the heat, toss the wings in the glaze, sprinkle with sesame seeds and scallions and serve right away. (Toss only half for the half-and-half style, with plain wings on the side.)', null, null, null);

