values ('e1c19741-a729-45d1-bec3-9b1618ee5cf6', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'tteokbokki-spicy-rice-cakes', 'tteokbokki-e1c197', 'Tteokbokki', 'Chewy cylinder rice cakes and fish cakes simmered in a sweet, fiery gochujang sauce with scallions and hard-boiled eggs — Korea''s favorite street snack.', 'korean', 2, 15, 30, 45, 4, 'main', null, 0, array['stove']::text[], array['spicy', 'weeknight', 'budget']::text[], array['Gochujang and Korean fish cakes usually contain wheat — check the labels if that matters for anyone at the table.', 'Short on time? Use water plus 1 teaspoon of instant dashi granules instead of the anchovy stock.']::text[], 'https://images.unsplash.com/photo-1747228469541-f0e7f56e7ec7', 'Rice cakes simmering in a spicy red sauce', 'lee seunghyub', 'https://unsplash.com/@sobalc', 'https://unsplash.com/photos/korean-tteokbokki-simmers-in-a-spicy-sauce-Uf2O1CnIpkY', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'budget']::text[], array['stew', 'boil']::text[], array['spicy', 'savory']::text[], '{}'::text[], null, 'traditional', 'tteokbokki', 'classic', 'Best eaten right away; the rice cakes harden in the fridge. Refrigerate up to 2 days and reheat with a splash of water.', null, 'owned', array['egg', 'fish', 'gluten', 'soy', 'wheat']::text[], array['fish']::text[], array['pescatarian', 'dairy_free']::text[], array['dried anchovy', 'kombu', 'rice cake', 'fish cake', 'gochujang', 'gochugaru', 'soy sauce', 'garlic', 'scallion', 'egg']::text[], 'dried anchovy|egg|fish cake|garlic|gochugaru|gochujang|kombu|rice cake|scallion|soy sauce',
  null, null, null, null, null, null, null, null)
