  ('e1c19741-a729-45d1-bec3-9b1618ee5cf6', 5, 'Tteokbokki', '6 oz Korean fish cakes (eomuk), cut into triangles', 'Korean fish cakes (eomuk)', 6, 'oz', 'cut into triangles', false),
  ('e1c19741-a729-45d1-bec3-9b1618ee5cf6', 6, 'Tteokbokki', '3 tbsp gochujang', 'gochujang', 3, 'tbsp', null, false),
