  ('e1c19741-a729-45d1-bec3-9b1618ee5cf6', 12, 'Tteokbokki', '4 large eggs', 'large eggs', 4, null, null, false),
  ('e1c19741-a729-45d1-bec3-9b1618ee5cf6', 13, 'Tteokbokki', '2 cups green cabbage, cut into bite-size pieces', 'green cabbage', 2, 'cup', 'cut into bite-size pieces', true);
