insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('e1c19741-a729-45d1-bec3-9b1618ee5cf6', 1, 'Stock', 'Simmer the anchovies and kombu in the water for 10 minutes, lifting out the kombu after 5. Strain; you should have about 3 cups.', 720, null, null),
  ('e1c19741-a729-45d1-bec3-9b1618ee5cf6', 2, 'Tteokbokki', 'Meanwhile, put the eggs in a pot of cold water, bring to a boil and boil 10 minutes until the yolks are fully set. Cool in cold water and peel.', 720, null, null),
  ('e1c19741-a729-45d1-bec3-9b1618ee5cf6', 3, 'Tteokbokki', 'Pour the stock into a wide pan and stir in the gochujang, gochugaru, sugar, soy sauce and garlic. Bring to a boil.', 180, null, null),
  ('e1c19741-a729-45d1-bec3-9b1618ee5cf6', 4, 'Tteokbokki', 'Add the rice cakes and simmer, stirring often so they don''t stick, until soft and chewy and the sauce thickens, 8–10 minutes.', 600, null, null),
  ('e1c19741-a729-45d1-bec3-9b1618ee5cf6', 5, 'Tteokbokki', 'Add the fish cakes, eggs, scallions and cabbage and simmer until the sauce is glossy and clings to everything, 3–4 minutes. Serve hot.', 240, null, null);

-- Napa Cabbage Kimchi
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
