values ('bf57fac8-f47e-4544-8fc3-2419e1249601', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'napa-cabbage-kimchi-baechu', 'napa-cabbage-kimchi-bf57fa', 'Napa Cabbage Kimchi', 'Napa cabbage salted, then rubbed with a garlicky chili paste of gochugaru, fish sauce and salted shrimp and left to ferment — cut into bite-size pieces (mak kimchi), the easiest way to make it at home.', 'korean', 3, 210, 5, 1655, 16, 'side', null, 1440, array['stove']::text[], array['make-ahead', 'fermented', 'budget']::text[], array['Gochugaru is essential for the flavor and color; cayenne or crushed red pepper is far hotter and tastes different.', 'Set the jar on a plate while it ferments — the brine often bubbles over.']::text[], 'https://images.unsplash.com/photo-1540162621994-4b096ef8523b', 'Dish of red-seasoned cabbage kimchi', 'charlesdeluvio', 'https://unsplash.com/@charlesdeluvio', 'https://unsplash.com/photos/kimchi-food-jdMEMbsWd70', 'unsplash', true, 'public', false,
  'pending_review', array['side', 'budget']::text[], array['raw']::text[], array['spicy', 'savory']::text[], '{}'::text[], null, 'traditional', 'baechu-kimchi', 'classic', 'Refrigerate in a sealed jar up to 3 months, always pressed under the brine. It keeps getting more sour; older kimchi is perfect for stews and fried rice.', 'Home fermentation: use very clean hands (or gloves), bowls and jars, keep the cabbage pressed under its brine, ferment at cool room temperature (60–70°F) for just 1–2 days and then refrigerate. Throw the batch out if you see fuzzy mold (white, green, black or pink) or if it smells rotten or feels slimy rather than pleasantly sour.', 'owned', array['fish', 'shellfish']::text[], array['fish', 'shellfish']::text[], array['pescatarian', 'gluten_free', 'dairy_free']::text[], array['napa cabbage', 'coarse salt', 'rice flour', 'gochugaru', 'fish sauce', 'shrimp', 'garlic', 'ginger', 'radish daikon', 'scallion']::text[], 'coarse salt|fish sauce|garlic|ginger|gochugaru|napa cabbage|radish daikon|rice flour|scallion|shrimp',
  null, null, null, null, null, null, null, null)
