  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 1, 'Cabbage', '1 large napa cabbage, about 4 lb', 'large napa cabbage', 1, null, 'about 4 lb', false),
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 2, 'Cabbage', '½ cup coarse sea salt, Korean or kosher; not iodized table salt', 'coarse sea salt', 0.5, 'cup', 'Korean or kosher; not iodized table salt', false),
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 3, 'Porridge', '1 cup water', 'water', 1, 'cup', null, false),
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 4, 'Porridge', '2 tbsp sweet rice flour (mochiko)', 'sweet rice flour (mochiko)', 2, 'tbsp', null, false),
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 5, 'Porridge', '1 tbsp sugar', 'sugar', 1, 'tbsp', null, false),
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 6, 'Paste', '½ cup gochugaru (Korean chili flakes)', 'gochugaru (Korean chili flakes)', 0.5, 'cup', null, false),
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 7, 'Paste', '¼ cup fish sauce', 'fish sauce', 0.25, 'cup', null, false),
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 8, 'Paste', '2 tbsp salted shrimp (saeujeot), minced', 'salted shrimp (saeujeot)', 2, 'tbsp', 'minced', false),
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 9, 'Paste', '8 cloves garlic, minced', 'garlic', 8, 'clove', 'minced', false),
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 10, 'Paste', '1 tbsp fresh ginger, minced', 'fresh ginger', 1, 'tbsp', 'minced', false),
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 11, 'Vegetables', '8 oz Korean radish or daikon, peeled and cut into matchsticks', 'Korean radish or daikon', 8, 'oz', 'peeled and cut into matchsticks', false),
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 12, 'Vegetables', '5 scallions, cut into 1-inch lengths', 'scallions', 5, null, 'cut into 1-inch lengths', false),
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 13, 'Vegetables', '1 carrot, cut into matchsticks', 'carrot', 1, null, 'cut into matchsticks', true);
delete from public.recipe_instructions where recipe_id = 'bf57fac8-f47e-4544-8fc3-2419e1249601';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 1, 'Cabbage', 'Quarter the cabbage lengthwise, cut out the core and cut the leaves into 2-inch pieces. Toss in a large bowl with the salt and let stand 2 hours, tossing every 30 minutes, until the thick parts bend without snapping.', 7200, null, null),
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 2, 'Cabbage', 'Rinse the cabbage in three changes of cold water and drain well in a colander for 30 minutes.', 1800, null, null),
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 3, 'Porridge', 'Whisk the water and sweet rice flour in a small pot and cook over medium heat, stirring, until thick and translucent, 3–5 minutes. Stir in the sugar and let cool.', 300, null, null),
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 4, 'Paste', 'Stir the cooled porridge with the gochugaru, fish sauce, salted shrimp, garlic and ginger. Let it sit 10 minutes so the chili flakes soften.', 600, null, null),
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 5, 'Vegetables', 'Wearing gloves, toss the cabbage, radish, scallions and carrot with the paste until every piece is coated.', 600, null, null),
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 6, null, 'Pack tightly into a clean 2-quart glass jar, pressing down to push out air pockets until the brine rises over the cabbage. Leave 2 inches of headspace and close the lid loosely.', 600, null, null),
  ('bf57fac8-f47e-4544-8fc3-2419e1249601', 7, null, 'Ferment at cool room temperature for 1–2 days, pressing the kimchi down once a day, until it smells pleasantly sour and you see small bubbles. Seal and refrigerate. It''s good to eat right away and best after a week or two.', 86400, null, null);

