values ('6a72fbce-91f6-44ff-b4aa-5fce2f64b870', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'massaman-curry-beef', 'massaman-curry-with-beef-6a72fb', 'Massaman Curry with Beef', 'Beef chuck braised until tender in coconut milk with massaman curry paste, potatoes, peanuts, tamarind and warm spices — the mild, rich curry of Thailand''s Muslim south.', 'thai', 3, 20, 140, 160, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['comfort', 'make-ahead']::text[], array['Most massaman curry pastes contain shrimp paste — check the label if you''re cooking for someone with a shellfish allergy.', 'Like most braises, it tastes even better the next day.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'comfort']::text[], array['stew']::text[], array['tangy', 'rich', 'savory', 'aromatic']::text[], '{}'::text[], 'Southern Thailand', 'traditional', 'massaman-curry-beef', 'classic', 'Refrigerate up to 4 days or freeze up to 3 months (the potatoes soften a little when frozen).', null, 'owned', array['fish', 'peanut']::text[], array['beef', 'fish']::text[], array['gluten_free', 'dairy_free']::text[], array['beef chuck', 'coconut milk', 'cinnamon stick', 'cardamom pod', 'bay leave', 'curry paste', 'gold potato', 'yellow onion', 'roasted peanut', 'fish sauce', 'palm sugar', 'tamarind concentrate', 'jasmine rice']::text[], 'bay leave|beef chuck|cardamom pod|cinnamon stick|coconut milk|curry paste|fish sauce|gold potato|jasmine rice|palm sugar|roasted peanut|tamarind concentrate|yellow onion',
