insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('6a72fbce-91f6-44ff-b4aa-5fce2f64b870', 1, null, 'Put the beef in a Dutch oven with one can of coconut milk, the water, cinnamon, cardamom and bay leaves. Bring to a simmer, cover and simmer gently until the beef is nearly tender (well past 145°F), about 1½ hours.', 5400, null, 62.8),
  ('6a72fbce-91f6-44ff-b4aa-5fce2f64b870', 2, null, 'Meanwhile, spoon the thick cream from the top of the second can into a skillet and simmer over medium heat until it thickens and the oil starts to separate, 3–4 minutes. Add the curry paste and fry, stirring, until very fragrant, 2–3 minutes.', 360, null, null),
  ('6a72fbce-91f6-44ff-b4aa-5fce2f64b870', 3, null, 'Scrape the fried paste into the beef with the rest of the second can, the potatoes, onion, peanuts, fish sauce, palm sugar and tamarind. Simmer uncovered until the potatoes are tender and the beef falls apart, 30–40 minutes.', 2100, null, null),
  ('6a72fbce-91f6-44ff-b4aa-5fce2f64b870', 4, null, 'Taste and balance: it should be gently sweet, salty and a little sour. Add more fish sauce, sugar or tamarind as needed.', null, null, null),
  ('6a72fbce-91f6-44ff-b4aa-5fce2f64b870', 5, null, 'Fish out the cinnamon and bay leaves and serve with jasmine rice.', null, null, null);

-- Tom Yum Goong
