values ('22336e6f-3d97-48ee-92c5-58e569e65ea9', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'tom-yum-goong', 'tom-yum-goong-22336e', 'Tom Yum Goong', 'Hot, sour and fragrant Thai shrimp soup in the clear (nam sai) style, built on a quick stock from the shrimp shells with lemongrass, galangal, lime leaves and a spoonful of roasted chili paste.', 'thai', 2, 20, 25, 45, 4, 'main', null, 0, array['stove']::text[], array['weeknight']::text[], array['Thai roasted chili paste (nam prik pao) usually contains dried shrimp and often soybean oil — check the jar if anyone has a soy allergy.', 'For the creamy nam khon version, stir ⅓ cup evaporated milk into the pot just before the lime juice.']::text[], 'https://images.unsplash.com/photo-1777828827870-92e3069424bd', 'Spicy tom yum soup with shrimp, lemongrass and herbs', 'Jamie Trinh', 'https://unsplash.com/@jtrinh_artwork', 'https://unsplash.com/photos/spicy-shrimp-soup-with-herbs-and-vegetables-_lgT5W2QBG4', 'unsplash', true, 'public', false,
  'pending_review', array['soup', 'main', 'dinner']::text[], array['stew', 'boil']::text[], array['spicy', 'tangy', 'fresh', 'savory']::text[], '{}'::text[], null, 'traditional', 'tom-yum-goong', 'classic', 'Best fresh. Refrigerate up to 2 days and reheat only until steaming so the shrimp don''t toughen.', null, 'owned', array['fish', 'shellfish']::text[], array['fish', 'shellfish']::text[], array['pescatarian', 'gluten_free', 'dairy_free']::text[], array['shrimp', 'lemongrass', 'galangal', 'lime leave', 'shallot', 'thai chile', 'oyster mushroom', 'chili paste', 'fish sauce', 'lime juice', 'cilantro leave']::text[], 'chili paste|cilantro leave|fish sauce|galangal|lemongrass|lime juice|lime leave|oyster mushroom|shallot|shrimp|thai chile',
  null, null, null, null, null, null, null, null)
