  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 1, null, '1 lb large shrimp, head-on if you can find them; peeled and deveined, shells and heads saved', 'large shrimp', 1, 'lb', 'head-on if you can find them; peeled and deveined, shells and heads saved', false),
  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 2, null, '5 cups water', 'water', 5, 'cup', null, false),
  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 3, null, '3 stalk lemongrass, bottom 4 inches, bruised and cut into 2-inch lengths', 'lemongrass', 3, 'stalk', 'bottom 4 inches, bruised and cut into 2-inch lengths', false),
  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 4, null, '1 piece fresh galangal, 2-inch piece, thinly sliced; or fresh ginger', 'fresh galangal', 1, 'piece', '2-inch piece, thinly sliced; or fresh ginger', false),
  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 5, null, '6 makrut lime leaves, torn, center rib removed', 'makrut lime leaves', 6, null, 'torn, center rib removed', false),
  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 6, null, '2 small shallots, halved', 'small shallots', 2, null, 'halved', false),
  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 7, null, '4 Thai chiles, lightly crushed', 'Thai chiles', 4, null, 'lightly crushed', false),
  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 8, null, '8 oz oyster mushrooms, torn into strips, or straw mushrooms', 'oyster mushrooms', 8, 'oz', 'torn into strips, or straw mushrooms', false),
  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 9, null, '2 plum tomatoes, cut into wedges', 'plum tomatoes', 2, null, 'cut into wedges', true),
  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 10, null, '2 tbsp Thai roasted chili paste (nam prik pao)', 'Thai roasted chili paste (nam prik pao)', 2, 'tbsp', null, false),
  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 11, null, '3 tbsp fish sauce', 'fish sauce', 3, 'tbsp', null, false),
  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 12, null, '1 tsp sugar', 'sugar', 1, 'tsp', null, false),
  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 13, null, '¼ cup lime juice, from about 3 limes', 'lime juice', 0.25, 'cup', 'from about 3 limes', false),
  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 14, null, '¼ cup fresh cilantro leaves', 'fresh cilantro leaves', 0.25, 'cup', null, false);
delete from public.recipe_instructions where recipe_id = '22336e6f-3d97-48ee-92c5-58e569e65ea9';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 1, null, 'Put the shrimp shells and heads in a pot with the water, bring to a boil, then simmer 10 minutes. Strain, pressing on the shells, and return the stock to the pot.', 720, null, null),
  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 2, null, 'Bring the stock back to a simmer and add the lemongrass, galangal, lime leaves, shallots and chiles. Simmer 5 minutes to infuse.', 300, null, null),
  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 3, null, 'Add the mushrooms and tomatoes and simmer 3 minutes. Stir in the chili paste, fish sauce and sugar until dissolved.', 180, null, null),
  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 4, null, 'Add the shrimp and simmer gently just until they curl, turn pink and are opaque all the way through (145°F), 2–3 minutes.', 180, null, 62.8),
  ('22336e6f-3d97-48ee-92c5-58e569e65ea9', 5, null, 'Turn off the heat and stir in the lime juice — boiling it makes it taste bitter. Taste: it should be boldly sour, salty and hot, with a little sweetness behind. Top with cilantro. The lemongrass, galangal and lime leaves are for flavor, not for eating.', null, null, null);

-- Khao Soi
