values ('69f30a1e-63a4-46cc-940e-c336be674051', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'khao-soi-chicken', 'khao-soi-69f30a', 'Khao Soi', 'Chiang Mai''s curry noodle soup — bone-in chicken simmered in a golden coconut curry, poured over egg noodles and crowned with crispy fried noodles; we boost store-bought red curry paste with curry powder, turmeric and ginger instead of pounding the paste from scratch.', 'thai', 3, 25, 55, 80, 4, 'main', null, 0, array['stove']::text[], array['comfort', 'entertaining']::text[], array['Most Thai curry pastes contain shrimp paste — check the label if you''re cooking for someone with a shellfish allergy.', 'Fresh egg noodles are often labeled wonton or Hong Kong-style noodles; dried egg noodles work too.']::text[], 'https://images.unsplash.com/photo-1646850148817-c3a5e8a35fd9', 'Bowl of khao soi curry noodle soup with a spoon', 'Kittitep Khotchalee', 'https://unsplash.com/@duckman1992', 'https://unsplash.com/photos/a-bowl-of-food-with-a-spoon-in-it-vxJZOosHvcU', 'unsplash', true, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'comfort', 'entertaining']::text[], array['stew', 'boil']::text[], array['spicy', 'tangy', 'rich', 'fresh', 'savory', 'aromatic']::text[], '{}'::text[], 'Chiang Mai', 'adapted', 'khao-soi', 'classic', 'Refrigerate the curry up to 3 days or freeze up to 2 months; keep noodles separate. Crispy noodles stay crisp 1 day in an airtight container.', null, 'owned', array['egg', 'fish', 'gluten', 'wheat']::text[], array['chicken', 'fish']::text[], array['dairy_free']::text[], array['coconut milk', 'curry paste', 'curry powder', 'ground turmeric', 'ginger', 'drumstick thigh', 'chicken stock', 'fish sauce', 'palm sugar', 'egg noodle', 'mustard green', 'shallot', 'lime', 'cilantro']::text[], 'chicken stock|cilantro|coconut milk|curry paste|curry powder|drumstick thigh|egg noodle|fish sauce|ginger|ground turmeric|lime|mustard green|palm sugar|shallot',
  null, null, null, null, null, null, null, null)
