values ('0a4e4179-80ed-4c3c-9a30-68661787f561', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'pho-bo-hanoi', 'pho-bo-0a4e41', 'Phở Bò', 'Hanoi-style beef pho: a clear, deeply beefy broth perfumed with charred onion, ginger and whole spices, ladled over flat rice noodles, tender brisket and paper-thin slices of beef that cook in the bowl.', 'vietnamese', 3, 40, 300, 340, 6, 'main', null, 0, array['stove', 'cast_iron']::text[], array['make-ahead', 'comfort', 'entertaining']::text[], array['Make the broth a day ahead: chill it and lift off the fat cap for the cleanest, clearest bowl.', 'A pressure cooker shortens the bone simmer to about 1½ hours at high pressure, though the broth is a little cloudier.']::text[], 'https://images.unsplash.com/photo-1766050586763-723571af4dde', 'Bowl of beef pho with rice noodles and fresh herbs', 'You Le', 'https://unsplash.com/@le_y0u', 'https://unsplash.com/photos/a-bowl-of-vietnamese-pho-with-beef-and-noodles-i5OO8PJQ-HY', 'unsplash', true, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'comfort', 'entertaining']::text[], array['stew', 'boil']::text[], array['tangy', 'fresh', 'savory', 'aromatic']::text[], '{}'::text[], 'Hanoi', 'traditional', 'pho-bo', 'classic', 'Refrigerate the broth up to 4 days or freeze up to 3 months; keep noodles, meat and herbs separate.', 'The paper-thin beef slices cook only in the boiling broth and may stay pink (below 145°F). For anyone pregnant, very young, older or with a weakened immune system, swish the slices in the simmering broth until no pink remains before adding them to the bowl.', 'owned', array['fish']::text[], array['beef', 'fish']::text[], array['gluten_free', 'dairy_free']::text[], array['beef soup', 'beef brisket', 'yellow onion', 'ginger', 'anise pod', 'cinnamon stick', 'coriander seed', 'clove', 'fish sauce', 'rock sugar', 'rice noodle', 'round sirloin', 'scallion', 'cilantro', 'lime', 'thai chile']::text[], 'anise pod|beef brisket|beef soup|cilantro|cinnamon stick|clove|coriander seed|fish sauce|ginger|lime|rice noodle|rock sugar|round sirloin|scallion|thai chile|yellow onion',
  null, null, null, null, null, null, null, null)
