  ('0a4e4179-80ed-4c3c-9a30-68661787f561', 1, 'Broth', '4 lb beef soup bones, knuckle and marrow bones', 'beef soup bones', 4, 'lb', 'knuckle and marrow bones', false),
  ('0a4e4179-80ed-4c3c-9a30-68661787f561', 2, 'Broth', '1½ lb beef brisket, in one piece', 'beef brisket', 1.5, 'lb', 'in one piece', false),
