values ('4edc4c3e-ce09-4a1f-aaa7-ceeb6e1c753e', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'banh-mi-thit-nuong', 'banh-mi-4edc4c', 'Bánh Mì', 'A crackly Vietnamese baguette stuffed with lemongrass-caramelized pork (thịt nướng, one of the most popular fillings), pâté, mayonnaise, quick-pickled carrot and daikon, cucumber, cilantro and chiles.', 'vietnamese', 2, 45, 15, 60, 4, 'main', null, 0, array['stove', 'cast_iron', 'oven']::text[], array['lunch', 'make-ahead']::text[], array['Liver pâté can contain milk, egg or wheat — check the label if you''re cooking for someone with allergies.', 'Maggi seasoning sauce is made from wheat and soy; a few drops of soy sauce give a similar savory hit.']::text[], 'https://images.unsplash.com/photo-1600454309261-3dc9b7597637', 'Vietnamese banh mi baguette filled with herbs and vegetables', 'Amy Tran', 'https://unsplash.com/@minhanh258', 'https://unsplash.com/photos/green-vegetable-on-brown-bread-pTcexK1TB98', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'lunch']::text[], array['pan_fry']::text[], array['spicy', 'tangy', 'fresh', 'savory']::text[], '{}'::text[], null, 'traditional', 'banh-mi', 'classic', 'Pickles keep 2 weeks and cooked pork 3 days in the fridge. Assemble sandwiches just before eating.', null, 'owned', array['egg', 'fish', 'gluten', 'soy', 'wheat']::text[], array['pork', 'fish']::text[], array['dairy_free']::text[], array['carrot', 'daikon radish', 'rice vinegar', 'pork shoulder', 'lemongrass', 'garlic', 'shallot', 'fish sauce', 'soy sauce', 'vietnamese-style baguette', 'mayonnaise', 'cucumber', 'cilantro', 'jalapeno']::text[], 'carrot|cilantro|cucumber|daikon radish|fish sauce|garlic|jalapeno|lemongrass|mayonnaise|pork shoulder|rice vinegar|shallot|soy sauce|vietnamese-style baguette',
  null, null, null, null, null, null, null, null)
