insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('4edc4c3e-ce09-4a1f-aaa7-ceeb6e1c753e', 1, 'Pickles', 'Stir the vinegar, warm water, sugar and salt until dissolved. Add the carrot and daikon and let stand at least 30 minutes (or refrigerate up to 2 weeks).', 1800, null, null),
  ('4edc4c3e-ce09-4a1f-aaa7-ceeb6e1c753e', 2, 'Pork', 'Toss the pork with the lemongrass, garlic, shallot, fish sauce, soy sauce, sugar, pepper and 1 tablespoon of the oil. Marinate 30 minutes at room temperature, or refrigerate up to overnight.', 1800, null, null),
  ('4edc4c3e-ce09-4a1f-aaa7-ceeb6e1c753e', 3, 'Pork', 'Heat the remaining oil in a cast-iron skillet over medium-high heat. Cook the pork in batches in a single layer, turning once, until caramelized at the edges, no pink remains and it reaches 145°F, 2–3 minutes per side.', 600, null, 62.8),
  ('4edc4c3e-ce09-4a1f-aaa7-ceeb6e1c753e', 4, 'Sandwiches', 'Heat the oven to 400°F and warm the baguettes directly on the rack until the crust crackles, 3–4 minutes.', 240, 204.4, null),
  ('4edc4c3e-ce09-4a1f-aaa7-ceeb6e1c753e', 5, 'Sandwiches', 'Split the baguettes, keeping one side hinged, and pull out a little of the soft crumb. Spread mayonnaise on one side and pâté on the other, add a few drops of Maggi, then layer in the pork, drained pickles, cucumber, cilantro and jalapeños. Eat right away.', null, null, null);

-- Bún Chả
