values ('9fa0e378-1944-4bc7-a960-f5a10601902c', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'bun-cha-hanoi', 'bun-cha-9fa0e3', 'Bún Chả', 'Hanoi''s lunchtime classic: smoky grilled pork patties and caramelized pork belly served in a warm, sweet-sour fish sauce broth with lightly pickled green papaya, thin rice noodles and a pile of herbs.', 'vietnamese', 3, 50, 25, 75, 4, 'main', null, 0, array['grill', 'stove']::text[], array['entertaining', 'summer']::text[], array['No grill? Cook the pork under a hot broiler on a foil-lined pan, turning once — you''ll lose a little smokiness but none of the flavor.', 'Frozen shredded green papaya from Asian grocers works well here.']::text[], 'https://images.unsplash.com/photo-1763703544688-2ac7839b0659', 'Bun cha grilled pork with rice noodles, fresh herbs and dipping sauce', 'Yoav Aziz', 'https://unsplash.com/@yoavaziz', 'https://unsplash.com/photos/vietnamese-dish-with-noodles-herbs-and-dipping-sauce-LZ5hWxVZVDM', 'unsplash', true, 'public', false,
  'pending_review', array['grilling', 'main', 'dinner', 'entertaining']::text[], array['grill']::text[], array['tangy', 'fresh', 'savory']::text[], '{}'::text[], 'Hanoi', 'traditional', 'bun-cha', 'classic', 'The dipping broth keeps 1 week and grilled pork 3 days in the fridge. Cook noodles fresh.', null, 'owned', array['fish']::text[], array['pork', 'fish']::text[], array['gluten_free', 'dairy_free']::text[], array['fish sauce', 'rice vinegar', 'garlic', 'thai chile', 'green papaya', 'carrot', 'ground pork', 'pork belly', 'shallot', 'honey', 'rice noodle', 'bibb lettuce', 'mint', 'cilantro', 'lime']::text[], 'bibb lettuce|carrot|cilantro|fish sauce|garlic|green papaya|ground pork|honey|lime|mint|pork belly|rice noodle|rice vinegar|shallot|thai chile',
  null, null, null, null, null, null, null, null)
