values ('72257fc8-9245-44de-85d2-44665fd7d7ad', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'ca-kho-to', 'ca-kho-to-caramelized-fish-72257f', 'Cá Kho Tộ (Caramelized Fish)', 'Thick slices of catfish braised in a clay pot of dark caramel, fish sauce and coconut water until sticky, peppery and deeply savory — a southern Vietnamese home staple eaten with plenty of rice.', 'vietnamese', 2, 20, 40, 60, 4, 'main', null, 0, array['stove']::text[], array['comfort', 'budget']::text[], array['If the caramel turns black or smells acrid, start again — burnt caramel makes the whole dish bitter.', 'Bottled Vietnamese caramel sauce (nước màu) can replace step 2; use 2 tablespoons.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'budget', 'comfort']::text[], array['braise', 'stew']::text[], array['savory']::text[], '{}'::text[], null, 'traditional', 'ca-kho-to', 'classic', 'Refrigerate up to 4 days; the flavor improves overnight. Reheat gently with a splash of water.', null, 'owned', array['fish']::text[], array['fish']::text[], array['pescatarian', 'gluten_free', 'dairy_free']::text[], array['catfish', 'fish sauce', 'shallot', 'garlic', 'coconut water', 'thai chile', 'scallion', 'jasmine rice']::text[], 'catfish|coconut water|fish sauce|garlic|jasmine rice|scallion|shallot|thai chile',
  null, null, null, null, null, null, null, null)
