insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('72257fc8-9245-44de-85d2-44665fd7d7ad', 1, null, 'Toss the fish with the fish sauce, pepper and half the shallots and garlic, and let it sit 15 minutes.', 900, null, null),
  ('72257fc8-9245-44de-85d2-44665fd7d7ad', 2, null, 'In a clay pot or small heavy saucepan over medium heat, cook the sugar and water, swirling (not stirring), until it turns a deep mahogany caramel, 5–7 minutes. Take it off the heat and carefully add the oil and remaining shallots and garlic — it will sputter.', 360, null, null),
  ('72257fc8-9245-44de-85d2-44665fd7d7ad', 3, null, 'Lay the fish in the pot in a single layer with all its marinade and turn to coat. Pour in coconut water to come about halfway up the fish, add the chiles and bring to a simmer.', 180, null, null),
  ('72257fc8-9245-44de-85d2-44665fd7d7ad', 4, null, 'Braise uncovered at a lively simmer, spooning the sauce over and turning the fish once, until the sauce has reduced to a sticky glaze and the fish flakes easily and reaches 145°F, 25–30 minutes.', 1680, null, 62.8),
  ('72257fc8-9245-44de-85d2-44665fd7d7ad', 5, null, 'Scatter in the scallions and plenty of black pepper and cook 1 minute more. Serve straight from the pot with rice and a simple green vegetable or soup.', 60, null, null);

-- Lechon Kawali
