values ('9c172a21-6e8d-4d5c-a8e3-0026604a0957', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'lechon-kawali', 'lechon-kawali-9c172a', 'Lechon Kawali', 'Filipino pork belly simmered with garlic, bay and peppercorns, chilled until dry, then deep-fried until the skin blisters into crackling — served with a garlicky spiced-vinegar dip.', 'filipino', 3, 20, 75, 335, 6, 'main', null, 240, array['stove', 'dutch_oven']::text[], array['entertaining']::text[], array['Bottled lechon sauce, a sweet, peppery liver gravy, is the other classic dip.', 'Save the simmering liquid — it makes a good base for noodle soup or sinigang.']::text[], 'https://images.unsplash.com/photo-1625477811233-044633d10dd1', 'Crispy fried pork belly pieces on a green plate', 'Amanda Lim', 'https://unsplash.com/@mandimelanie', 'https://unsplash.com/photos/cooked-food-on-green-plate-ENsAKjY3YOs', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'entertaining']::text[], array['boil', 'fry']::text[], array['tangy', 'savory']::text[], '{}'::text[], null, 'traditional', 'lechon-kawali', 'classic', 'Best fresh. Refrigerate up to 3 days and re-crisp in a 425°F oven or an air fryer for 8–10 minutes.', 'Pork belly spatters fiercely in hot oil. Dry it thoroughly, use a deep, heavy pot filled no more than halfway, wear long sleeves, keep a lid or splatter screen at hand, and never leave the oil unattended.', 'owned', array['gluten', 'soy', 'wheat']::text[], array['pork']::text[], array['dairy_free']::text[], array['pork belly', 'garlic', 'bay leave', 'black peppercorn', 'cane vinegar', 'soy sauce', 'red onion', 'thai chile']::text[], 'bay leave|black peppercorn|cane vinegar|garlic|pork belly|red onion|soy sauce|thai chile',
  null, null, null, null, null, null, null, null)
