  ('9c172a21-6e8d-4d5c-a8e3-0026604a0957', 5, 'Pork', '1 tbsp black peppercorns', 'black peppercorns', 1, 'tbsp', null, false),
  ('9c172a21-6e8d-4d5c-a8e3-0026604a0957', 6, 'Pork', '2 tbsp kosher salt, plus 1 tsp for the skin', 'kosher salt', 2, 'tbsp', 'plus 1 tsp for the skin', false),
  ('9c172a21-6e8d-4d5c-a8e3-0026604a0957', 7, 'Frying', '2 quart vegetable oil, for deep-frying', 'vegetable oil', 2, 'quart', 'for deep-frying', false),
  ('9c172a21-6e8d-4d5c-a8e3-0026604a0957', 8, 'Dip', '½ cup cane vinegar, or white vinegar', 'cane vinegar', 0.5, 'cup', 'or white vinegar', false),
  ('9c172a21-6e8d-4d5c-a8e3-0026604a0957', 9, 'Dip', '1 tbsp soy sauce', 'soy sauce', 1, 'tbsp', null, false),
