delete from public.recipe_instructions where recipe_id = '9c172a21-6e8d-4d5c-a8e3-0026604a0957';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('9c172a21-6e8d-4d5c-a8e3-0026604a0957', 1, 'Pork', 'Put the pork, water, garlic, bay leaves, peppercorns and 2 tablespoons salt in a large pot. Bring to a boil, skim, then cover and simmer until a skewer slides in easily and the pork is well past 145°F, 45–60 minutes.', 3300, null, 62.8),
  ('9c172a21-6e8d-4d5c-a8e3-0026604a0957', 2, 'Pork', 'Lift the pork out, pat it very dry and rub the skin with 1 teaspoon salt. Set it skin-side up on a rack over a tray and refrigerate, uncovered, at least 4 hours or overnight so the skin dries out.', 14400, null, null),
  ('9c172a21-6e8d-4d5c-a8e3-0026604a0957', 3, 'Frying', 'Pour the oil into a heavy Dutch oven no more than half full and heat to 375°F. Keep a lid or splatter screen nearby and children and pets away.', 600, 190.6, null),
  ('9c172a21-6e8d-4d5c-a8e3-0026604a0957', 4, 'Frying', 'Pat the pork dry once more. Using long tongs, lower one slab into the oil away from you, partly cover with the splatter screen and fry, turning once or twice, until the skin is blistered and deep golden, 8–12 minutes. Drain on a rack and let the oil come back to 375°F before the next slab.', 1200, 190.6, null),
  ('9c172a21-6e8d-4d5c-a8e3-0026604a0957', 5, 'Dip', 'Stir the vinegar, soy sauce, garlic, onion, chiles, sugar and pepper together.', null, null, null),
  ('9c172a21-6e8d-4d5c-a8e3-0026604a0957', 6, null, 'Rest the pork 5 minutes, then chop it into bite-size pieces with a heavy knife, skin-side down so the crackling stays whole. Serve with the dip and steamed rice.', 300, null, null);

-- Sinigang na Baboy
