values ('68d28048-c83b-4a6b-a0bd-cf296ca1c4e8', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'sinigang-na-baboy', 'sinigang-na-baboy-68d280', 'Sinigang na Baboy', 'The Philippines'' beloved sour soup: tender pork ribs simmered with tamarind, tomatoes and onion and loaded with taro, daikon, long beans, eggplant and greens; we sour it with tamarind pulp, though the instant mix many home cooks reach for works too.', 'filipino', 2, 25, 90, 115, 6, 'main', null, 0, array['stove']::text[], array['comfort']::text[], array['Instant sinigang mix (one 1.4-oz packet) can replace the tamarind; many contain MSG and some contain shrimp or wheat, so check the label.', 'Swap the taro for a small potato if you can''t find it.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'comfort']::text[], array['stew', 'steam', 'boil']::text[], array['tangy', 'savory']::text[], '{}'::text[], null, 'traditional', 'sinigang-na-baboy', 'classic', 'Refrigerate up to 3 days. The vegetables soften on reheating, so add fresh greens if you like.', null, 'owned', array['fish']::text[], array['pork', 'fish']::text[], array['gluten_free', 'dairy_free']::text[], array['tamarind pulp', 'pork sparerib', 'yellow onion', 'tomato', 'fish sauce', 'taro root', 'daikon radish', 'green bean', 'japanese eggplant', 'green chile', 'water spinach']::text[], 'daikon radish|fish sauce|green bean|green chile|japanese eggplant|pork sparerib|tamarind pulp|taro root|tomato|water spinach|yellow onion',
  null, null, null, null, null, null, null, null)
