values ('efb3a802-1405-4108-be42-8bd27374dc7d', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'kare-kare-oxtail', 'kare-kare-efb3a8', 'Kare-Kare', 'Oxtail braised until falling-apart tender in a golden peanut and toasted-rice sauce colored with annatto, with bok choy, eggplant and long beans — served with salty sautéed shrimp paste (bagoong) on the side, as at a Filipino fiesta.', 'filipino', 3, 20, 210, 230, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['entertaining', 'make-ahead']::text[], array['Buy sautéed (ginisang) bagoong in a jar at Filipino or Asian grocers; it''s salty, so start with a little.', 'A pressure cooker gets the oxtail tender in 45–50 minutes at high pressure with a natural release.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['holiday', 'main', 'dinner', 'entertaining']::text[], array['stew', 'steam', 'boil']::text[], array['savory']::text[], array['christmas', 'dinner-party']::text[], null, 'traditional', 'kare-kare', 'classic', 'Refrigerate up to 4 days or freeze (without the vegetables) up to 3 months. The sauce thickens as it sits; loosen it with broth.', null, 'owned', array['fish', 'peanut', 'shellfish']::text[], array['beef', 'fish', 'shellfish']::text[], array['gluten_free', 'dairy_free']::text[], array['oxtail', 'yellow onion', 'garlic', 'black peppercorn', 'bay leave', 'annatto seed', 'rice flour', 'peanut butter', 'roasted peanut', 'fish sauce', 'bok choy', 'chinese eggplant', 'green bean', 'shrimp paste']::text[], 'annatto seed|bay leave|black peppercorn|bok choy|chinese eggplant|fish sauce|garlic|green bean|oxtail|peanut butter|rice flour|roasted peanut|shrimp paste|yellow onion',
  null, null, null, null, null, null, null, null)
