insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 1, 'Oxtail', '3½ lb oxtail, in 2-inch pieces, trimmed of excess fat', 'oxtail', 3.5, 'lb', 'in 2-inch pieces, trimmed of excess fat', false),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 2, 'Oxtail', '3 quart water', 'water', 3, 'quart', null, false),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 3, 'Oxtail', '1 yellow onion, quartered', 'yellow onion', 1, null, 'quartered', false),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 4, 'Oxtail', '6 cloves garlic, smashed', 'garlic', 6, 'clove', 'smashed', false),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 5, 'Oxtail', '1 tsp black peppercorns', 'black peppercorns', 1, 'tsp', null, false),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 6, 'Oxtail', '2 bay leaves', 'bay leaves', 2, null, null, false),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 7, 'Oxtail', '2 tsp kosher salt', 'kosher salt', 2, 'tsp', null, false),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 8, 'Sauce', '2 tbsp annatto seeds, or 1 tbsp annatto powder', 'annatto seeds', 2, 'tbsp', 'or 1 tbsp annatto powder', false),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 9, 'Sauce', '3 tbsp vegetable oil', 'vegetable oil', 3, 'tbsp', null, false),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 10, 'Sauce', '3 tbsp rice flour', 'rice flour', 3, 'tbsp', null, false),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 11, 'Sauce', '1 yellow onion, chopped', 'yellow onion', 1, null, 'chopped', false),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 12, 'Sauce', '5 cloves garlic, minced', 'garlic', 5, 'clove', 'minced', false),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 13, 'Sauce', '¾ cup creamy natural peanut butter, unsweetened', 'creamy natural peanut butter', 0.75, 'cup', 'unsweetened', false),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 14, 'Sauce', '⅓ cup roasted unsalted peanuts, finely ground', 'roasted unsalted peanuts', 0.33, 'cup', 'finely ground', false),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 15, 'Sauce', '1 tbsp fish sauce', 'fish sauce', 1, 'tbsp', null, false),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 16, 'Vegetables', '1 lb baby bok choy, halved', 'baby bok choy', 1, 'lb', 'halved', false),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 17, 'Vegetables', '2 Chinese eggplants, cut into 2-inch pieces', 'Chinese eggplants', 2, null, 'cut into 2-inch pieces', false),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 18, 'Vegetables', '8 oz long beans or green beans, cut into 3-inch lengths', 'long beans or green beans', 8, 'oz', 'cut into 3-inch lengths', false),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 19, 'To serve', '½ cup sautéed shrimp paste (bagoong alamang)', 'sautéed shrimp paste (bagoong alamang)', 0.5, 'cup', null, false);
delete from public.recipe_instructions where recipe_id = 'efb3a802-1405-4108-be42-8bd27374dc7d';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 1, 'Oxtail', 'Cover the oxtail with cold water in a Dutch oven, boil 10 minutes, then drain and rinse the pieces and the pot. This gives a cleaner sauce.', 900, null, null),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 2, 'Oxtail', 'Return the oxtail to the pot with the 3 quarts water, onion, garlic, peppercorns, bay leaves and salt. Cover and simmer gently until the meat pulls easily from the bone (far beyond 145°F), 2½–3 hours. Lift out the oxtail, strain the broth, skim the fat and keep 4 cups.', 9900, null, 62.8),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 3, 'Sauce', 'Warm the annatto seeds in the oil over low heat until the oil turns deep orange, 3–4 minutes. Strain and discard the seeds. In a dry skillet over medium heat, toast the rice flour, stirring, until light tan, 3–4 minutes.', 480, null, null),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 4, 'Sauce', 'Heat the annatto oil in the cleaned Dutch oven over medium heat and cook the onion and garlic until soft, 4 minutes. Whisk in the 4 cups broth, peanut butter and ground peanuts until smooth and simmer 5 minutes. Whisk the toasted rice flour with ½ cup of the broth, stir it in and simmer until the sauce is as thick as gravy, about 5 minutes. Add the oxtail and fish sauce and heat through.', 900, null, null),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 5, 'Vegetables', 'Meanwhile, blanch the vegetables in a pot of salted boiling water: long beans 3 minutes, eggplant 3 minutes, bok choy 1 minute. Drain.', 480, null, null),
  ('efb3a802-1405-4108-be42-8bd27374dc7d', 6, null, 'Arrange the vegetables over the oxtail and sauce and serve with steamed rice and the bagoong at the table. The sauce is deliberately mild — a little bagoong on each bite does the seasoning.', null, null, null);

-- Beef Rendang
