values ('66a3740c-ec6d-4cff-84b4-b53d3d972832', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'beef-rendang', 'beef-rendang-66a374', 'Beef Rendang', 'Minangkabau-style dry rendang: chunks of beef slowly cooked in coconut milk and a fiery spice paste until the liquid is gone and the meat fries in its own coconut oil to a dark, caramelized crust.', 'indonesian', 4, 35, 220, 255, 6, 'main', null, 0, array['stove', 'dutch_oven', 'blender']::text[], array['make-ahead', 'entertaining']::text[], array['Stop after step 4 and you have kalio, the saucier stage many families serve too; true rendang is cooked until nearly dry.', 'Rendang tastes even better made a day or two ahead.']::text[], 'https://images.pexels.com/photos/37080534/pexels-photo-37080534.jpeg', 'Close-up of dark, spicy beef rendang on a plate', 'Wahyu Prabowo', 'https://www.pexels.com/@wahyu-prabowo-2158742291/', 'https://www.pexels.com/photo/traditional-indonesian-beef-rendang-dish-close-up-37080534/', 'pexels', true, 'public', false,
  'pending_review', array['holiday', 'main', 'dinner', 'entertaining']::text[], array['braise', 'stew']::text[], array['tangy', 'rich', 'aromatic']::text[], array['eid-al-fitr', 'eid-al-adha']::text[], 'West Sumatra', 'traditional', 'beef-rendang', 'classic', 'Refrigerate up to 1 week or freeze up to 3 months. Reheat gently in a covered skillet.', null, 'owned', '{}'::text[], array['beef']::text[], array['gluten_free', 'dairy_free']::text[], array['red chile', 'shallot', 'garlic', 'galangal', 'ginger', 'turmeric', 'beef chuck', 'coconut milk', 'lemongrass', 'lime leave', 'tamarind paste', 'unsweetened coconut']::text[], 'beef chuck|coconut milk|galangal|garlic|ginger|lemongrass|lime leave|red chile|shallot|tamarind paste|turmeric|unsweetened coconut',
  null, null, null, null, null, null, null, null)
