insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 1, 'Spice paste', '10 dried red chiles, stemmed, soaked in hot water 15 minutes', 'dried red chiles', 10, null, 'stemmed, soaked in hot water 15 minutes', false),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 2, 'Spice paste', '4 fresh red chiles, such as Fresno, roughly chopped', 'fresh red chiles', 4, null, 'such as Fresno, roughly chopped', false),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 3, 'Spice paste', '6 oz shallots, about 8, peeled', 'shallots', 6, 'oz', 'about 8, peeled', false),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 4, 'Spice paste', '6 cloves garlic', 'garlic', 6, 'clove', null, false),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 5, 'Spice paste', '1 piece fresh galangal, 2-inch piece, sliced', 'fresh galangal', 1, 'piece', '2-inch piece, sliced', false),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 6, 'Spice paste', '1 piece fresh ginger, 1-inch piece, sliced', 'fresh ginger', 1, 'piece', '1-inch piece, sliced', false),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 7, 'Spice paste', '1 piece fresh turmeric, 2-inch piece; or 1 tsp ground turmeric', 'fresh turmeric', 1, 'piece', '2-inch piece; or 1 tsp ground turmeric', false),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 8, 'Rendang', '3 lb boneless beef chuck, cut into 2-inch chunks', 'boneless beef chuck', 3, 'lb', 'cut into 2-inch chunks', false),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 9, 'Rendang', '40 oz canned coconut milk, three 13.5-oz cans', 'canned coconut milk', 40, 'oz', 'three 13.5-oz cans', false),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 10, 'Rendang', '2 stalk lemongrass, bruised and tied in a knot', 'lemongrass', 2, 'stalk', 'bruised and tied in a knot', false),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 11, 'Rendang', '6 makrut lime leaves, torn', 'makrut lime leaves', 6, null, 'torn', false),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 12, 'Rendang', '1 turmeric leaf, knotted', 'turmeric leaf', 1, null, 'knotted', true),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 13, 'Rendang', '2 tbsp tamarind paste', 'tamarind paste', 2, 'tbsp', null, false),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 14, 'Rendang', '2 tsp kosher salt', 'kosher salt', 2, 'tsp', null, false),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 15, 'Rendang', '½ cup unsweetened shredded coconut', 'unsweetened shredded coconut', 0.5, 'cup', null, false);
delete from public.recipe_instructions where recipe_id = '66a3740c-ec6d-4cff-84b4-b53d3d972832';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 1, 'Spice paste', 'Drain the dried chiles and blend them with the fresh chiles, shallots, garlic, galangal, ginger and turmeric and ¼ cup of the coconut milk until very smooth.', 300, null, null),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 2, 'Rendang', 'Toast the shredded coconut in a dry skillet over medium-low heat, stirring constantly, until evenly deep brown, 8–10 minutes. While it''s warm, grind it in a spice grinder or pound it in a mortar until it turns into an oily paste (kerisik).', 600, null, null),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 3, 'Rendang', 'Put the beef, spice paste, remaining coconut milk, lemongrass, lime leaves, turmeric leaf and salt in a wide Dutch oven. Bring to a boil over medium-high heat, stirring, then simmer uncovered, stirring every 10–15 minutes, for 1½ hours. The sauce reduces and turns orange-brown, and the beef is well past 145°F.', 5400, null, 62.8),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 4, 'Rendang', 'Stir in the kerisik and tamarind and keep simmering, stirring more often as it thickens, until most of the liquid has gone and the coconut oil separates, about 1 hour.', 3600, null, null),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 5, 'Rendang', 'Lower the heat to medium-low and stir every couple of minutes as the beef fries in the released oil, until the paste darkens to a deep chocolate brown and clings to the meat, and the beef is very tender, 30–60 minutes. Scrape the bottom often so nothing scorches.', 2700, null, null),
  ('66a3740c-ec6d-4cff-84b4-b53d3d972832', 6, null, 'Remove the lemongrass and leaves and let the rendang rest 15 minutes. Serve with steamed rice and something fresh, like sliced cucumber.', 900, null, null);

-- Gado-Gado
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
