values ('a652a910-7fc8-44ee-b571-8d1c5d1e7c85', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'gado-gado', 'gado-gado-a652a9', 'Gado-Gado', 'Indonesian salad of blanched vegetables, potatoes, crisp tofu and tempeh and hard-boiled eggs under a thick, sweet-spicy peanut sauce, finished with fried shallots and crackers.', 'indonesian', 2, 30, 35, 65, 4, 'main', null, 0, array['stove', 'blender']::text[], array['make-ahead', 'entertaining']::text[], array['Kecap manis contains soy and usually wheat. Skip the shrimp paste and shrimp chips if you''re cooking for someone avoiding shellfish.', 'Store-bought fried shallots are often coated in wheat flour — check the label if that matters.']::text[], 'https://images.pexels.com/photos/37113568/pexels-photo-37113568.jpeg', 'Gado-gado vegetables and tofu with peanut sauce', 'Man Fong Wong', 'https://www.pexels.com/@man-fong-wong-278505948/', 'https://www.pexels.com/photo/indonesian-gado-gado-dish-with-peanut-sauce-37113568/', 'pexels', true, 'public', false,
  'pending_review', array['salad', 'main', 'dinner', 'entertaining']::text[], array['boil']::text[], array['spicy', 'tangy', 'savory']::text[], '{}'::text[], null, 'traditional', 'gado-gado', 'classic', 'The peanut sauce keeps 1 week in the fridge (thin it with hot water); the vegetables and eggs keep 3 days. Assemble just before serving.', null, 'owned', array['egg', 'gluten', 'peanut', 'shellfish', 'soy', 'wheat']::text[], array['tofu']::text[], array['pescatarian', 'vegetarian', 'dairy_free']::text[], array['roasted peanut', 'garlic', 'thai chile', 'kecap mani', 'palm sugar', 'tamarind paste', 'waxy potato', 'egg', 'green bean', 'green cabbage', 'bean sprout', 'extra-firm tofu', 'tempeh', 'english cucumber', 'fried shallot']::text[], 'bean sprout|egg|english cucumber|extra-firm tofu|fried shallot|garlic|green bean|green cabbage|kecap mani|palm sugar|roasted peanut|tamarind paste|tempeh|thai chile|waxy potato',
  null, null, null, null, null, null, null, null)
