insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('a652a910-7fc8-44ee-b571-8d1c5d1e7c85', 1, 'Salad', 'Boil the potatoes in salted water until tender, 15–20 minutes. Drain, cool and quarter.', 1080, null, null),
  ('a652a910-7fc8-44ee-b571-8d1c5d1e7c85', 2, 'Salad', 'Lower the eggs into boiling water and cook 10 minutes for firm yolks (160°F). Cool in ice water, peel and quarter.', 600, null, 71.1),
  ('a652a910-7fc8-44ee-b571-8d1c5d1e7c85', 3, 'Salad', 'In a pot of boiling salted water, blanch the green beans 3 minutes, the cabbage 1 minute and the bean sprouts 30 seconds. Cool in ice water and drain well.', 300, null, null),
  ('a652a910-7fc8-44ee-b571-8d1c5d1e7c85', 4, 'Salad', 'Heat the oil in a nonstick skillet over medium-high heat and fry the tofu and tempeh, turning, until golden and crisp on all sides, 8–10 minutes. Drain on paper towels.', 600, null, null),
  ('a652a910-7fc8-44ee-b571-8d1c5d1e7c85', 5, 'Peanut sauce', 'Blend the peanuts, garlic, chiles, shrimp paste, kecap manis, palm sugar, tamarind and salt with the hot water to a thick, pourable sauce, adding more water a spoonful at a time if needed. Warm it in a small saucepan for 2–3 minutes.', 300, null, null),
  ('a652a910-7fc8-44ee-b571-8d1c5d1e7c85', 6, null, 'Arrange the vegetables, potatoes, tofu, tempeh, eggs and cucumber on a platter. Pour the sauce over (or serve it alongside) and top with fried shallots and crackers.', null, null, null);

-- Nasi Lemak
