values ('56d9cf26-2283-4483-a033-8fce5f2f12e6', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'nasi-lemak', 'nasi-lemak-56d9cf', 'Nasi Lemak', 'Malaysia''s national dish: pandan-scented coconut rice with sweet, fiery sambal, crisp fried anchovies and peanuts, cucumber and a hard-boiled egg — the classic everyday plate, often served with fried chicken or rendang on the side.', 'malaysian', 3, 30, 55, 85, 4, 'main', null, 0, array['stove', 'blender']::text[], array['breakfast', 'comfort']::text[], array['Shrimp paste smells strong as it fries — open a window. The sambal keeps 2 weeks in the fridge, so a double batch is worth it.', 'Look for dried anchovies (ikan bilis) in the dried-goods aisle of Southeast Asian grocers; split them and pull out the dark gut for the best flavor.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'comfort']::text[], array['stew', 'stir_fry', 'boil']::text[], array['tangy', 'rich']::text[], '{}'::text[], null, 'traditional', 'nasi-lemak', 'classic', 'Sambal keeps 2 weeks refrigerated; fried anchovies and peanuts stay crisp 3 days in an airtight jar. Refrigerate leftover rice within 1 hour and reheat until steaming.', null, 'owned', array['egg', 'fish', 'peanut', 'shellfish']::text[], array['fish', 'shellfish']::text[], array['pescatarian', 'gluten_free', 'dairy_free']::text[], array['jasmine rice', 'coconut milk', 'ginger', 'red chile', 'shallot', 'garlic', 'shrimp paste', 'red onion', 'tamarind paste', 'peanut', 'dried anchovy', 'egg', 'english cucumber']::text[], 'coconut milk|dried anchovy|egg|english cucumber|garlic|ginger|jasmine rice|peanut|red chile|red onion|shallot|shrimp paste|tamarind paste',
  null, null, null, null, null, null, null, null)
