  ('56d9cf26-2283-4483-a033-8fce5f2f12e6', 4, 'Coconut rice', '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('56d9cf26-2283-4483-a033-8fce5f2f12e6', 5, 'Coconut rice', '2 pandan leaves, tied in a knot', 'pandan leaves', 2, null, 'tied in a knot', true),
  ('56d9cf26-2283-4483-a033-8fce5f2f12e6', 6, 'Coconut rice', '1 slice fresh ginger', 'fresh ginger', 1, 'slice', null, false),
  ('56d9cf26-2283-4483-a033-8fce5f2f12e6', 7, 'Sambal', '15 dried red chiles, stemmed, soaked in hot water 20 minutes', 'dried red chiles', 15, null, 'stemmed, soaked in hot water 20 minutes', false),
  ('56d9cf26-2283-4483-a033-8fce5f2f12e6', 8, 'Sambal', '4 shallots, peeled', 'shallots', 4, null, 'peeled', false),
