  ('56d9cf26-2283-4483-a033-8fce5f2f12e6', 16, 'Toppings', '½ cup vegetable oil, for frying', 'vegetable oil', 0.5, 'cup', 'for frying', false),
  ('56d9cf26-2283-4483-a033-8fce5f2f12e6', 17, 'Toppings', '½ cup skin-on peanuts, unroasted', 'skin-on peanuts', 0.5, 'cup', 'unroasted', false),
  ('56d9cf26-2283-4483-a033-8fce5f2f12e6', 18, 'Toppings', '1 cup dried anchovies (ikan bilis), heads removed, rinsed and patted dry', 'dried anchovies (ikan bilis)', 1, 'cup', 'heads removed, rinsed and patted dry', false),
  ('56d9cf26-2283-4483-a033-8fce5f2f12e6', 19, 'Toppings', '4 large eggs', 'large eggs', 4, null, null, false),
