delete from public.recipe_instructions where recipe_id = '56d9cf26-2283-4483-a033-8fce5f2f12e6';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('56d9cf26-2283-4483-a033-8fce5f2f12e6', 1, 'Coconut rice', 'Combine the rice, coconut milk, water, salt, pandan and ginger in a heavy saucepan (or rice cooker). Bring to a simmer, stir once, cover and cook on the lowest heat 15 minutes. Rest off the heat, covered, 10 minutes, then fluff.', 1500, null, null),
  ('56d9cf26-2283-4483-a033-8fce5f2f12e6', 2, 'Toppings', 'Lower the eggs into boiling water and cook 10 minutes (160°F). Cool in ice water, peel and halve.', 720, null, 71.1),
  ('56d9cf26-2283-4483-a033-8fce5f2f12e6', 3, 'Toppings', 'Heat the ½ cup oil in a small skillet or wok over medium heat to about 325°F. Fry the peanuts, stirring, until golden, 4–5 minutes, and lift out. Fry the anchovies until crisp and golden, 3–4 minutes — don''t let them go dark or they turn bitter. Drain both on paper towels and save the oil.', 540, 162.8, null),
  ('56d9cf26-2283-4483-a033-8fce5f2f12e6', 4, 'Sambal', 'Blend the drained chiles, shallots, garlic and shrimp paste with 3 tablespoons water to a smooth paste.', 180, null, null),
  ('56d9cf26-2283-4483-a033-8fce5f2f12e6', 5, 'Sambal', 'Heat the ⅓ cup oil (some of the anchovy oil is good here) in a skillet over medium heat and fry the paste, stirring often, until it darkens and the oil separates, 12–15 minutes — don''t rush this. Add the onion rings, tamarind, sugar, salt and ¼ cup water and simmer until thick and glossy, about 5 minutes.', 1200, null, null),
  ('56d9cf26-2283-4483-a033-8fce5f2f12e6', 6, null, 'Pack some rice into a small bowl and turn it out onto each plate. Arrange the sambal, anchovies, peanuts, egg and cucumber around it and serve warm.', null, null, null);

-- Laksa
