values ('7fa76ddc-91bd-4c94-84e0-1910925bc387', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'penang-asam-laksa', 'laksa-7fa76d', 'Laksa', 'Penang''s asam laksa — the sour, spicy fish-and-tamarind laksa rather than the coconut curry kind — with flaked mackerel, thick rice noodles and a heap of pineapple, cucumber, onion and mint.', 'malaysian', 3, 35, 60, 95, 4, 'main', null, 0, array['stove', 'blender']::text[], array['entertaining']::text[], array['Hae ko, the thick black shrimp paste drizzled on top, is sold in jars at Malaysian and Chinese grocers; some brands contain wheat, so check the label.', 'Shortcut: use two drained 15-oz cans of mackerel in brine with 2 quarts water in step 4 and skip the poaching.']::text[], 'https://images.unsplash.com/photo-1768703321790-e09a80a46f2c', 'Bowl of laksa noodle soup with shrimp, lime and cilantro', 'You Le', 'https://unsplash.com/@le_y0u', 'https://unsplash.com/photos/a-bowl-of-delicious-laksa-soup-with-noodles-and-shrimp-2h-BQpdUmYo', 'unsplash', true, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'entertaining']::text[], array['stew', 'boil']::text[], array['tangy', 'fresh', 'aromatic']::text[], '{}'::text[], 'Penang', 'traditional', 'asam-laksa', 'classic', 'Refrigerate the broth up to 3 days or freeze up to 2 months; keep noodles and toppings separate.', null, 'owned', array['fish', 'shellfish']::text[], array['fish', 'shellfish']::text[], array['pescatarian', 'gluten_free', 'dairy_free']::text[], array['mackerel', 'red chile', 'shallot', 'lemongrass', 'galangal', 'turmeric', 'shrimp paste', 'tamarind paste', 'vietnamese mint', 'rice noodle', 'pineapple', 'english cucumber', 'red onion', 'mint leave']::text[], 'english cucumber|galangal|lemongrass|mackerel|mint leave|pineapple|red chile|red onion|rice noodle|shallot|shrimp paste|tamarind paste|turmeric|vietnamese mint',
  null, null, null, null, null, null, null, null)
