  ('7fa76ddc-91bd-4c94-84e0-1910925bc387', 16, 'Bowls', '1 lb fresh thick rice noodles, or 12 oz dried thick round rice noodles', 'fresh thick rice noodles', 1, 'lb', 'or 12 oz dried thick round rice noodles', false),
  ('7fa76ddc-91bd-4c94-84e0-1910925bc387', 17, 'Bowls', '1 cup fresh pineapple, cut into matchsticks', 'fresh pineapple', 1, 'cup', 'cut into matchsticks', false),
