delete from public.recipe_instructions where recipe_id = '7fa76ddc-91bd-4c94-84e0-1910925bc387';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7fa76ddc-91bd-4c94-84e0-1910925bc387', 1, 'Fish stock', 'Bring the water to a boil in a large pot, add the mackerel and simmer gently until the flesh flakes from the bone and reaches 145°F, 10–12 minutes. Lift out the fish and keep the stock.', 720, null, 62.8),
  ('7fa76ddc-91bd-4c94-84e0-1910925bc387', 2, 'Fish stock', 'When the fish is cool enough to handle, flake the flesh, picking out every fine bone and the skin. Return the head and bones to the stock, simmer 15 minutes, then strain.', 900, null, null),
  ('7fa76ddc-91bd-4c94-84e0-1910925bc387', 3, 'Spice paste', 'Blend the drained dried chiles, fresh chiles, shallots, lemongrass, galangal, turmeric and shrimp paste with a splash of the stock until smooth.', 180, null, null),
  ('7fa76ddc-91bd-4c94-84e0-1910925bc387', 4, 'Broth', 'Bring the strained stock to a boil and stir in the spice paste, tamarind paste, tamarind slices, the Vietnamese mint stems, torch ginger flower, sugar and salt. Add about two-thirds of the flaked fish (it thickens the broth) and simmer 20–25 minutes. Taste: it should be sour, spicy, savory and a little sweet.', 1500, null, null),
  ('7fa76ddc-91bd-4c94-84e0-1910925bc387', 5, 'Bowls', 'Cook the noodles following the package, drain and divide among four bowls.', 300, null, null),
  ('7fa76ddc-91bd-4c94-84e0-1910925bc387', 6, 'Bowls', 'Ladle the hot broth and fish over the noodles. Top with pineapple, cucumber, onion, mint, chiles, the Vietnamese mint leaves and the remaining fish, and drizzle with black shrimp paste.', null, null, null);

