values ('fbbb077e-ad8b-4a13-8c82-285579b4cb1a', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'hainanese-chicken-rice', 'hainanese-chicken-rice-fbbb07', 'Hainanese Chicken Rice', 'Silky poached whole chicken with rice cooked in its fat and broth, served with chili-lime sauce, pounded ginger and dark soy — Singapore''s hawker-center favorite.', 'singaporean', 3, 25, 80, 105, 6, 'main', null, 0, array['stove', 'blender']::text[], array['comfort', 'entertaining']::text[], array['In Singapore the chicken is often served just cooked, with rosy bones; we take the thigh to 165°F for safety, and the ice bath keeps it juicy.', 'Dark soy sauce is thick and molasses-sweet; kecap manis is a good substitute.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'comfort', 'entertaining']::text[], array['stew', 'poach', 'boil']::text[], array['tangy', 'fresh', 'savory']::text[], '{}'::text[], null, 'traditional', 'hainanese-chicken-rice', 'classic', 'Refrigerate chicken, rice and sauces separately up to 3 days. Cool the rice quickly and reheat until steaming.', null, 'owned', array['gluten', 'sesame', 'soy', 'wheat']::text[], array['chicken']::text[], array['dairy_free']::text[], array['chicken', 'ginger', 'scallion', 'ice cube', 'sesame oil', 'soy sauce', 'jasmine rice', 'chicken fat', 'garlic', 'poaching broth', 'red chile', 'lime juice', 'english cucumber', 'cilantro sprig']::text[], 'chicken|chicken fat|cilantro sprig|english cucumber|garlic|ginger|ice cube|jasmine rice|lime juice|poaching broth|red chile|scallion|sesame oil|soy sauce',
  null, null, null, null, null, null, null, null)
