insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('fbbb077e-ad8b-4a13-8c82-285579b4cb1a', 1, 'Chicken', 'Rub the chicken all over with 1 tablespoon of the salt, rinse and stuff the cavity with half the ginger and the scallions. Bring the water, remaining ginger and remaining salt to a boil in a pot that just fits the chicken.', 900, null, null),
  ('fbbb077e-ad8b-4a13-8c82-285579b4cb1a', 2, 'Chicken', 'Lower the chicken in breast-side up, lift it out and dip it back in three times so hot water fills the cavity, then submerge it. Return to a bare simmer, turn the heat to the lowest setting, cover and poach without boiling until the thickest part of the thigh reads 165°F, 35–45 minutes.', 2400, null, 73.9),
  ('fbbb077e-ad8b-4a13-8c82-285579b4cb1a', 3, 'Chicken', 'Plunge the chicken into a big bowl of ice water for 10 minutes to firm the skin and stop the cooking. Drain and rub with the sesame oil. Keep the broth hot.', 600, null, null),
  ('fbbb077e-ad8b-4a13-8c82-285579b4cb1a', 4, 'Rice', 'Render the saved chicken fat in a saucepan over medium-low heat until you have about 3 tablespoons liquid fat, 5–8 minutes; discard the solids. Fry the garlic and ginger 1 minute, add the rice and stir 2 minutes to coat. Add the broth, salt and pandan, bring to a boil, cover and cook on low 15 minutes. Rest 10 minutes off the heat.', 1800, null, null),
  ('fbbb077e-ad8b-4a13-8c82-285579b4cb1a', 5, null, 'Blend all the chili sauce ingredients until fairly smooth. For the ginger sauce, put the grated ginger and salt in a heatproof bowl, heat the oil until shimmering and pour it over.', 300, null, null),
  ('fbbb077e-ad8b-4a13-8c82-285579b4cb1a', 6, null, 'Carve the chicken into pieces and drizzle with the light soy sauce and a spoonful of broth. Serve with the rice, cucumber, cilantro, both sauces, dark soy for drizzling and small bowls of the hot broth topped with scallions.', null, null, null);

-- Chili Crab
