values ('82b36528-39bf-4c46-94b9-ac92443f11b7', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'singapore-chili-crab', 'chili-crab-82b365', 'Chili Crab', 'Singapore''s sweet, tangy, gently spicy chili crab — whole crab pieces tossed in a tomato-chili sauce thickened with ribbons of egg; we use Dungeness crab, which is easier to find in the US than the traditional mud crab.', 'singaporean', 3, 40, 25, 65, 4, 'main', null, 0, array['stove', 'blender']::text[], array['entertaining']::text[], array['Using cooked frozen crab clusters? Thaw them in the fridge and add them in step 4 for just 4–5 minutes, until heated through.', 'Sweet chili sauce and sambal brands vary in heat and sweetness; adjust the sugar at the end.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['seafood_raw_bar', 'main', 'dinner', 'holiday', 'entertaining']::text[], array['stir_fry', 'boil']::text[], array['spicy', 'tangy', 'fresh', 'savory']::text[], array['dinner-party']::text[], null, 'adapted', 'chili-crab', 'classic', 'Best eaten right away. Refrigerate leftovers within 1 hour and eat within 1 day.', 'Cook live crabs the day you buy them and discard any that have died before cooking. If you use precooked frozen crab, thaw it in the fridge and heat it through in the sauce until steaming.', 'owned', array['egg', 'gluten', 'shellfish', 'soy', 'wheat']::text[], array['shellfish']::text[], array['pescatarian', 'dairy_free']::text[], array['dungeness crab', 'shallot', 'garlic', 'ginger', 'red chile', 'shrimp paste', 'ketchup', 'chili sauce', 'sambal oelek', 'soy sauce', 'cornstarch', 'egg', 'rice vinegar', 'scallion', 'cilantro']::text[], 'chili sauce|cilantro|cornstarch|dungeness crab|egg|garlic|ginger|ketchup|red chile|rice vinegar|sambal oelek|scallion|shallot|shrimp paste|soy sauce',
  null, null, null, null, null, null, null, null)
