values ('6b773109-1d86-422c-8ec8-b87281e1e883', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'mohinga', 'mohinga-6b7731', 'Mohinga', 'Myanmar''s national breakfast: thin rice noodles in a thick, peppery catfish broth with lemongrass, ginger and toasted chickpea flour, topped with hard-boiled egg, crisp fried onions, lime and cilantro.', 'burmese', 3, 25, 65, 90, 6, 'main', null, 0, array['stove', 'blender']::text[], array['breakfast', 'comfort']::text[], array['Ready-made fried onions and fritters often contain wheat flour — check the label if that matters.', 'Ngapi, Burmese fermented fish paste, adds depth; anchovy paste is a close stand-in.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'comfort']::text[], array['stew', 'boil']::text[], array['spicy', 'fresh', 'savory', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'mohinga', 'classic', 'Refrigerate the broth up to 3 days or freeze up to 2 months. It thickens as it cools; thin with water when reheating.', null, 'owned', array['egg', 'fish']::text[], array['fish', 'beans']::text[], array['pescatarian', 'dairy_free']::text[], array['catfish fillet', 'lemongrass', 'ground turmeric', 'chickpea flour', 'rice flour', 'yellow onion', 'garlic', 'ginger', 'sweet paprika', 'cayenne pepper', 'shallot', 'fish sauce', 'rice noodle', 'egg', 'fried onion', 'lime', 'cilantro']::text[], 'catfish fillet|cayenne pepper|chickpea flour|cilantro|egg|fish sauce|fried onion|garlic|ginger|ground turmeric|lemongrass|lime|rice flour|rice noodle|shallot|sweet paprika|yellow onion',
  null, null, null, null, null, null, null, null)
