  ('6b773109-1d86-422c-8ec8-b87281e1e883', 18, 'Broth', '3 tbsp fish sauce', 'fish sauce', 3, 'tbsp', null, false),
  ('6b773109-1d86-422c-8ec8-b87281e1e883', 19, 'Broth', '1 tsp black pepper', 'black pepper', 1, 'tsp', null, false),
  ('6b773109-1d86-422c-8ec8-b87281e1e883', 20, 'Bowls', '1 lb thin rice noodles, rice vermicelli', 'thin rice noodles', 1, 'lb', 'rice vermicelli', false),
  ('6b773109-1d86-422c-8ec8-b87281e1e883', 21, 'Bowls', '6 large eggs', 'large eggs', 6, null, null, false),
  ('6b773109-1d86-422c-8ec8-b87281e1e883', 22, 'Bowls', '½ cup crispy fried onions, or split-pea fritters', 'crispy fried onions', 0.5, 'cup', 'or split-pea fritters', false),
  ('6b773109-1d86-422c-8ec8-b87281e1e883', 23, 'Bowls', '2 limes, cut into wedges', 'limes', 2, null, 'cut into wedges', false),
