delete from public.recipe_instructions where recipe_id = '6b773109-1d86-422c-8ec8-b87281e1e883';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('6b773109-1d86-422c-8ec8-b87281e1e883', 1, 'Fish', 'Bring the water, lemongrass, turmeric and salt to a boil. Add the catfish and simmer gently until it flakes easily and reaches 145°F, 8–10 minutes. Lift out the fish, flake it, and keep the stock.', 600, null, 62.8),
  ('6b773109-1d86-422c-8ec8-b87281e1e883', 2, 'Broth', 'Toast the chickpea flour and rice flour in a dry skillet over medium-low heat, stirring constantly, until nutty-smelling and light golden, 5–7 minutes. Let cool, then whisk with 1 cup cool water to a smooth slurry.', 360, null, null),
  ('6b773109-1d86-422c-8ec8-b87281e1e883', 3, 'Broth', 'Blend the onion, garlic, ginger and sliced lemongrass to a coarse paste. Heat the oil in a large pot over medium heat and fry the paste with the paprika and cayenne until golden and fragrant, 6–8 minutes. Add the flaked fish and fish paste and fry 2 minutes, mashing gently.', 600, null, null),
  ('6b773109-1d86-422c-8ec8-b87281e1e883', 4, 'Broth', 'Add the fish stock plus enough water to make 3 quarts, the whole shallots and banana stem and simmer 20 minutes. Whisk in the flour slurry and simmer, stirring often so it doesn''t catch, until the broth is as thick as a light gravy and the shallots are tender, about 15 minutes. Season with the fish sauce and black pepper.', 2100, null, null),
  ('6b773109-1d86-422c-8ec8-b87281e1e883', 5, 'Bowls', 'Meanwhile, boil the eggs 10 minutes (160°F), cool in ice water, peel and quarter. Cook the noodles following the package and rinse.', 720, null, 71.1),
  ('6b773109-1d86-422c-8ec8-b87281e1e883', 6, 'Bowls', 'Divide the noodles among bowls, ladle the soup over and top with egg, fried onions, cilantro and chile flakes. Serve with lime.', null, null, null);

-- Tea Leaf Salad (Lahpet Thoke)
