values ('efb0bdf9-4aa0-41af-8a96-92bf659fc1ee', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'lahpet-thoke', 'tea-leaf-salad-lahpet-thoke-efb0bd', 'Tea Leaf Salad (Lahpet Thoke)', 'Myanmar''s famous salad of tangy fermented tea leaves tossed with crunchy fried beans, garlic chips, peanuts, sesame and dried shrimp, plus cabbage, tomato, lime and chile.', 'burmese', 2, 20, 8, 28, 4, 'side', null, 0, array['stove']::text[], array['entertaining']::text[], array['Look for jarred lahpet at Burmese or Southeast Asian grocers or online. No lahpet? Steep 3 tbsp loose green tea in hot water 5 minutes, squeeze dry, chop and mix with lime juice, garlic, salt and oil — milder and not fermented, but still good.', 'Tea leaves contain caffeine, so go easy serving this late in the evening or to children.']::text[], 'https://images.pexels.com/photos/8161900/pexels-photo-8161900.jpeg', 'Burmese tea leaf salad with peanuts beside lemon and tomato slices', 'Tony Wu', 'https://www.pexels.com/@tonywuphotography/', 'https://www.pexels.com/photo/slices-of-lemon-and-tomatoes-beside-a-bowl-of-tea-leaf-salad-8161900/', 'pexels', true, 'public', false,
  'pending_review', array['salad', 'side', 'entertaining']::text[], '{}'::text[], array['tangy', 'savory']::text[], '{}'::text[], null, 'traditional', 'lahpet-thoke', 'classic', 'Store the tea leaves (refrigerated, after opening) and crunchy toppings (airtight, room temperature, up to 1 week) separately; toss the salad just before serving.', null, 'owned', array['fish', 'peanut', 'sesame', 'shellfish']::text[], array['fish', 'shellfish', 'beans']::text[], array['pescatarian', 'dairy_free']::text[], array['garlic', 'dried shrimp', 'roasted peanut', 'sesame seed', 'split pea', 'tea leave', 'green cabbage', 'plum tomato', 'thai chile', 'lime juice', 'fish sauce']::text[], 'dried shrimp|fish sauce|garlic|green cabbage|lime juice|plum tomato|roasted peanut|sesame seed|split pea|tea leave|thai chile',
  null, null, null, null, null, null, null, null)
