  ('efb0bdf9-4aa0-41af-8a96-92bf659fc1ee', 5, 'Crunchy toppings', '2 tbsp toasted sesame seeds', 'toasted sesame seeds', 2, 'tbsp', null, false),
  ('efb0bdf9-4aa0-41af-8a96-92bf659fc1ee', 6, 'Crunchy toppings', '⅓ cup store-bought fried broad beans or yellow split peas, or salted roasted chickpeas', 'store-bought fried broad beans or yellow split peas', 0.33, 'cup', 'or salted roasted chickpeas', false),
  ('efb0bdf9-4aa0-41af-8a96-92bf659fc1ee', 7, 'Salad', '½ cup fermented tea leaves (lahpet), from a jar', 'fermented tea leaves (lahpet)', 0.5, 'cup', 'from a jar', false),
