delete from public.recipe_instructions where recipe_id = 'efb0bdf9-4aa0-41af-8a96-92bf659fc1ee';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('efb0bdf9-4aa0-41af-8a96-92bf659fc1ee', 1, 'Crunchy toppings', 'Put the garlic and oil in a small cold skillet and heat over medium, stirring, until the garlic is pale golden, 4–6 minutes. Pour straight through a sieve into a heatproof bowl (the chips keep darkening off the heat), drain the chips on paper towels and save the garlic oil.', 360, null, null),
  ('efb0bdf9-4aa0-41af-8a96-92bf659fc1ee', 2, 'Crunchy toppings', 'Toss the dried shrimp in 1 teaspoon of the garlic oil in the same skillet over medium heat until crisp and fragrant, about 2 minutes.', 120, null, null),
  ('efb0bdf9-4aa0-41af-8a96-92bf659fc1ee', 3, 'Salad', 'If the tea leaves are very wet, squeeze out the excess, then loosen them with 1 tablespoon of the garlic oil.', null, null, null),
  ('efb0bdf9-4aa0-41af-8a96-92bf659fc1ee', 4, null, 'Arrange the cabbage and tomatoes on a platter with the tea leaves in the middle and small piles of garlic chips, shrimp, peanuts, sesame and fried beans around them — the traditional way to present it. At the table, add the chiles, lime juice, fish sauce, salt and 1–2 tablespoons garlic oil and toss everything together. Eat right away, while the toppings are crunchy.', null, null, null);

-- Fish Amok
