values ('aee662a8-e825-41ea-9cfd-60291886ccc5', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'fish-amok', 'fish-amok-aee662', 'Fish Amok', 'Cambodia''s national dish: white fish folded into a fragrant kroeung (lemongrass spice paste), coconut milk and egg, then steamed in banana-leaf cups until just set like a soft mousse.', 'cambodian', 3, 35, 25, 60, 4, 'main', null, 0, array['stove', 'blender']::text[], array['entertaining']::text[], array['No steamer? Set ramekins on a folded towel in a roasting pan, pour in hot water halfway up, cover with foil and bake at 350°F for about 25 minutes.', 'Ready-made Cambodian kroeung or Thai yellow curry paste can stand in; most contain shrimp paste, so check the label for shellfish.']::text[], 'https://images.pexels.com/photos/216560/pexels-photo-216560.jpeg', 'Steamed fish curry in banana leaf topped with coconut cream and red chili', 'icon0 com', 'https://www.pexels.com/@icon0/', 'https://www.pexels.com/photo/dish-with-spice-216560/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner', 'entertaining']::text[], array['steam', 'boil']::text[], array['spicy', 'tangy', 'rich', 'savory', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'fish-amok', 'classic', 'Best fresh. Refrigerate up to 2 days and reheat gently in the steamer.', null, 'owned', array['egg', 'fish', 'shellfish']::text[], array['fish', 'shellfish']::text[], array['pescatarian', 'gluten_free', 'dairy_free']::text[], array['lemongrass', 'galangal', 'turmeric', 'garlic', 'shallot', 'lime leave', 'red chile', 'shrimp paste', 'catfish fillet', 'coconut milk', 'egg', 'fish sauce', 'palm sugar', 'spinach', 'leaf square', 'jasmine rice']::text[], 'catfish fillet|coconut milk|egg|fish sauce|galangal|garlic|jasmine rice|leaf square|lemongrass|lime leave|palm sugar|red chile|shallot|shrimp paste|spinach|turmeric',
