  ('aee662a8-e825-41ea-9cfd-60291886ccc5', 10, 'Amok', '13½ oz canned coconut milk, unshaken; 3 tbsp of the thick top layer reserved', 'canned coconut milk', 13.5, 'oz', 'unshaken; 3 tbsp of the thick top layer reserved', false),
  ('aee662a8-e825-41ea-9cfd-60291886ccc5', 11, 'Amok', '1 large egg', 'large egg', 1, null, null, false),
  ('aee662a8-e825-41ea-9cfd-60291886ccc5', 12, 'Amok', '1 tbsp fish sauce', 'fish sauce', 1, 'tbsp', null, false),
