values ('253aceff-af52-4a16-8c0d-d36defb91f41', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'lao-larb-beef', 'larb-253ace', 'Larb', 'Laos''s national dish in its everyday cooked form, made with beef — the most common choice — tossed warm with lime, fish sauce, toasted sticky-rice powder, galangal, chiles and handfuls of mint, cilantro and scallions, and eaten with sticky rice.', 'laotian', 2, 20, 15, 35, 4, 'side', null, 0, array['stove']::text[], array['weeknight']::text[], array['Padaek, a chunky fermented fish sauce sold in jars at Southeast Asian grocers, is what makes larb taste distinctly Lao.', 'Raw-beef larb (laab dib) is also popular in Laos; we cook the beef through for safety.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['salad', 'side']::text[], '{}'::text[], array['spicy', 'tangy', 'fresh', 'savory']::text[], '{}'::text[], null, 'traditional', 'lao-larb', 'classic', 'Best fresh, as the herbs wilt. Refrigerate up to 2 days and eat cold or at room temperature.', null, 'owned', array['fish']::text[], array['beef', 'fish']::text[], array['gluten_free', 'dairy_free']::text[], array['sticky rice', 'ground beef', 'galangal', 'lemongrass', 'fish sauce', 'lime juice', 'chile flake', 'shallot', 'scallion', 'mint leave', 'cilantro', 'lettuce cabbage', 'cucumber']::text[], 'chile flake|cilantro|cucumber|fish sauce|galangal|ground beef|lemongrass|lettuce cabbage|lime juice|mint leave|scallion|shallot|sticky rice',
  null, null, null, null, null, null, null, null)
