delete from public.recipe_instructions where recipe_id = '253aceff-af52-4a16-8c0d-d36defb91f41';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('253aceff-af52-4a16-8c0d-d36defb91f41', 1, 'Toasted rice', 'Toast the uncooked rice in a dry skillet over medium heat, shaking often, until deep golden, 6–8 minutes. Cool, then grind to a coarse powder in a mortar or spice grinder.', 420, null, null),
  ('253aceff-af52-4a16-8c0d-d36defb91f41', 2, 'Larb', 'Put the beef and water in the skillet over medium heat and cook, breaking it into fine crumbs, until no pink remains and it reaches 160°F, 6–8 minutes. Stir in the galangal and lemongrass for the last minute.', 480, null, 71.1),
  ('253aceff-af52-4a16-8c0d-d36defb91f41', 3, 'Larb', 'Take the pan off the heat and let it cool 2 minutes. Stir in the fish sauce, padaek, lime juice, chile flakes and 2 tablespoons of the rice powder.', null, null, null),
  ('253aceff-af52-4a16-8c0d-d36defb91f41', 4, 'Larb', 'Fold in the shallots, scallions, mint and cilantro. Taste — it should be salty, sour, hot and very herby. Sprinkle with the rest of the rice powder and serve warm or at room temperature with sticky rice, lettuce and cucumber.', null, null, null);

-- Hyderabadi Chicken Biryani
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
