values ('3050bab2-fb39-460b-abce-5f42d7c29ed6', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'hyderabadi-chicken-biryani', 'hyderabadi-chicken-biryani-3050ba', 'Hyderabadi Chicken Biryani', 'Hyderabad''s kacchi biryani: yogurt-marinated chicken layered under part-cooked saffron basmati and fried onions, then sealed and slow-cooked on dum so the rice steams in the chicken''s juices.', 'indian', 3, 40, 90, 250, 6, 'main', null, 120, array['stove', 'dutch_oven']::text[], array['entertaining']::text[], array['A tight seal is everything: traditionally the lid is sealed with a rope of dough, but a double layer of foil under the lid works.', 'Store-bought fried onions save 25 minutes; many are coated in wheat flour, so check the label if that matters.']::text[], 'https://images.pexels.com/photos/35287418/pexels-photo-35287418.jpeg', 'Hyderabadi biryani with raita, onion, lime and chili', 'Milton Das', 'https://www.pexels.com/@miltonphotography/', 'https://www.pexels.com/photo/delicious-hyderabadi-biryani-with-side-dishes-35287418/', 'pexels', true, 'public', false,
  'pending_review', array['holiday', 'main', 'dinner', 'entertaining']::text[], array['steam', 'boil']::text[], array['spicy', 'tangy', 'rich', 'fresh', 'aromatic']::text[], array['eid-al-fitr', 'eid-al-adha', 'dinner-party']::text[], 'Hyderabad', 'traditional', 'hyderabadi-chicken-biryani', 'classic', 'Refrigerate up to 3 days. Reheat covered, with a sprinkle of water, until the chicken is steaming hot.', 'The chicken goes into the pot uncooked under the rice, so check it with a thermometer: the thickest piece must reach 165°F before serving.', 'owned', array['milk']::text[], array['chicken']::text[], array['gluten_free']::text[], array['yellow onion', 'whole-milk yogurt', 'ginger-garlic paste', 'chili powder', 'ground turmeric', 'garam masala', 'lemon juice', 'green chile', 'mint leave', 'cilantro', 'basmati rice', 'cardamom pod', 'clove', 'cinnamon stick', 'bay leave', 'caraway seed', 'saffron thread', 'ghee']::text[], 'basmati rice|bay leave|caraway seed|cardamom pod|chili powder|cilantro|cinnamon stick|clove|garam masala|ghee|ginger-garlic paste|green chile|ground turmeric|lemon juice|mint leave|saffron thread|whole-milk yogurt|yellow onion',
  null, null, null, null, null, null, null, null)
