insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('3050bab2-fb39-460b-abce-5f42d7c29ed6', 1, 'Fried onions', 'Heat the oil in a wide, heavy skillet (no more than half full) to 325°F. Fry the onions in two batches, stirring, until evenly deep golden, 12–15 minutes per batch. Lift out and spread on paper towels to crisp. Save the oil.', 1500, 162.8, null),
  ('3050bab2-fb39-460b-abce-5f42d7c29ed6', 2, 'Chicken', 'Mix the chicken with the yogurt, ginger-garlic paste, chili powder, turmeric, garam masala, salt, lemon juice, chiles, half the mint and cilantro, half the fried onions (crushed) and 3 tablespoons of the onion oil. Cover and refrigerate at least 2 hours or overnight.', 7200, null, null),
  ('3050bab2-fb39-460b-abce-5f42d7c29ed6', 3, 'Chicken', 'Take the chicken out of the fridge 30 minutes before cooking, then spread it with all its marinade in an even layer in a heavy 6- to 7-quart Dutch oven.', null, null, null),
  ('3050bab2-fb39-460b-abce-5f42d7c29ed6', 4, 'Rice', 'Bring the water to a rolling boil with the salt and whole spices. Add the drained rice and boil until about 70% cooked — a grain should snap with a firm white core — 4–5 minutes. Drain well.', 480, null, null),
  ('3050bab2-fb39-460b-abce-5f42d7c29ed6', 5, 'Finishing', 'Spread the rice loosely over the chicken without pressing it down. Top with the remaining fried onions, mint and cilantro, drizzle with the saffron milk and ghee, then seal the pot tightly with foil and the lid.', 300, null, null),
  ('3050bab2-fb39-460b-abce-5f42d7c29ed6', 6, 'Finishing', 'Cook over medium-high heat until you hear steady sizzling and see steam at the edges, 8–10 minutes, then set the pot on a heat diffuser or an upturned cast-iron skillet over the lowest heat for 35–40 minutes. Rest 10 minutes unopened, then check: the thickest piece of chicken must read 165°F at the bone. If not, reseal and cook 10 minutes more.', 3000, null, 73.9),
  ('3050bab2-fb39-460b-abce-5f42d7c29ed6', 7, null, 'Serve by scooping straight down through the layers so everyone gets rice and chicken, with raita and a salad of sliced onion and lemon.', null, null, null);

-- Pork Vindaloo
