values ('7c06b404-0515-4e60-8995-377a5a94d6a9', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'goan-pork-vindaloo', 'pork-vindaloo-7c06b4', 'Pork Vindaloo', 'Goa''s fiery, tangy pork curry with Portuguese roots — pork shoulder marinated overnight in a paste of Kashmiri chiles, garlic, vinegar and warm spices, then slowly braised until tender.', 'indian', 3, 30, 110, 500, 6, 'main', null, 360, array['stove', 'dutch_oven', 'blender']::text[], array['make-ahead', 'entertaining']::text[], array['Kashmiri chiles give the deep red color with moderate heat; add 2–4 dried árbol chiles if you want it fiercer.', 'Vindaloo is a classic make-ahead dish: the vinegar keeps it well, and the flavor improves after a day.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'entertaining']::text[], array['stew']::text[], array['tangy', 'aromatic']::text[], '{}'::text[], 'Goa', 'traditional', 'pork-vindaloo', 'classic', 'Refrigerate up to 5 days or freeze up to 3 months.', null, 'owned', '{}'::text[], array['pork']::text[], array['gluten_free', 'dairy_free']::text[], array['kashmiri chile', 'cider vinegar', 'garlic', 'ginger', 'cumin seed', 'black peppercorn', 'clove', 'cinnamon stick', 'cardamom pod', 'ground turmeric', 'pork shoulder', 'yellow onion']::text[], 'black peppercorn|cardamom pod|cider vinegar|cinnamon stick|clove|cumin seed|garlic|ginger|ground turmeric|kashmiri chile|pork shoulder|yellow onion',
  null, null, null, null, null, null, null, null)
