delete from public.recipe_instructions where recipe_id = '7c06b404-0515-4e60-8995-377a5a94d6a9';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7c06b404-0515-4e60-8995-377a5a94d6a9', 1, 'Paste', 'Toast the chiles, cumin, peppercorns, cloves, cinnamon and cardamom in a dry skillet over medium heat until fragrant, 1–2 minutes, without letting the chiles blacken. Soak everything in the vinegar for 20 minutes.', 1320, null, null),
  ('7c06b404-0515-4e60-8995-377a5a94d6a9', 2, 'Paste', 'Blend the chiles and spices with the vinegar, garlic, ginger, turmeric, sugar and salt until very smooth.', 240, null, null),
  ('7c06b404-0515-4e60-8995-377a5a94d6a9', 3, 'Curry', 'Rub the pork with the paste in a glass or stainless bowl, cover and refrigerate at least 6 hours or overnight.', 21600, null, null),
  ('7c06b404-0515-4e60-8995-377a5a94d6a9', 4, 'Curry', 'Heat the oil in a Dutch oven over medium heat and cook the onions, stirring often, until deep golden, 12–15 minutes.', 840, null, null),
  ('7c06b404-0515-4e60-8995-377a5a94d6a9', 5, 'Curry', 'Add the pork and every bit of the paste and fry, stirring, until the paste darkens and the oil begins to separate, 8–10 minutes. Add the water, bring to a simmer, cover and cook over low heat, stirring now and then, until the pork is very tender and well past 145°F, 75–90 minutes.', 5100, null, 62.8),
  ('7c06b404-0515-4e60-8995-377a5a94d6a9', 6, 'Curry', 'Uncover for the last 10 minutes to thicken the sauce. Taste and balance with a little more salt, sugar or vinegar — it should be hot, sour and rich. Serve with rice or soft bread rolls.', 600, null, null);

-- Masala Dosa
