values ('ff67a5c5-f7ba-4846-9652-49988f04fdd5', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'masala-dosa', 'masala-dosa-ff67a5', 'Masala Dosa', 'Crisp, lacy fermented rice-and-lentil crêpes wrapped around turmeric-spiced potatoes and served with fresh coconut chutney — the South Indian breakfast classic, started a day ahead.', 'indian', 3, 1110, 75, 1185, 6, 'main', null, 0, array['stove', 'blender', 'cast_iron']::text[], array['breakfast', 'make-ahead']::text[], array['If the first dosa sticks or won''t spread thinly, the pan is too hot — sprinkle it with water, wipe and try again; the first one is usually a tester.', 'In a hot kitchen, check the batter after 6 hours; in a cold one, the oven-light trick keeps fermentation on track.']::text[], 'https://images.unsplash.com/photo-1668236543090-82eba5ee5976', 'Crispy masala dosa with potato filling, sambar and chutneys', 'Deepal Tamang', 'https://unsplash.com/@deepal_tamang', 'https://unsplash.com/photos/dosa-with-masala-and-chutney-breakfast-5oF7d_hPJG4', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner']::text[], array['roast', 'boil']::text[], array['spicy', 'tangy', 'fresh', 'aromatic']::text[], '{}'::text[], 'South India', 'traditional', 'masala-dosa', 'classic', 'Fermented batter keeps 4–5 days refrigerated (it gets more sour); potato masala 3 days; coconut chutney 2 days.', 'The batter ferments at warm room temperature. Use clean bowls and utensils, ferment no longer than about 14 hours, then refrigerate. It should smell pleasantly sour; throw it out if it smells rotten or shows pink, orange or fuzzy mold.', 'owned', '{}'::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], array['parboiled rice', 'urad dal', 'chana dal', 'fenugreek seed', 'gold potato', 'mustard seed', 'curry leave', 'green chile', 'ginger', 'yellow onion', 'ground turmeric', 'cilantro', 'lime juice', 'frozen coconut', 'red chile']::text[], 'chana dal|cilantro|curry leave|fenugreek seed|frozen coconut|ginger|gold potato|green chile|ground turmeric|lime juice|mustard seed|parboiled rice|red chile|urad dal|yellow onion',
  null, null, null, null, null, null, null, null)
