  ('ff67a5c5-f7ba-4846-9652-49988f04fdd5', 20, 'Coconut chutney', '2 tbsp roasted chana dal (dalia)', 'roasted chana dal (dalia)', 2, 'tbsp', null, false),
  ('ff67a5c5-f7ba-4846-9652-49988f04fdd5', 21, 'Coconut chutney', '2 green chiles', 'green chiles', 2, null, null, false),
  ('ff67a5c5-f7ba-4846-9652-49988f04fdd5', 22, 'Coconut chutney', '1 piece fresh ginger, ½-inch piece', 'fresh ginger', 1, 'piece', '½-inch piece', false),
  ('ff67a5c5-f7ba-4846-9652-49988f04fdd5', 23, 'Coconut chutney', '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
