values ('34fea4ce-f172-4be6-9f64-355991cf2ca9', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'kashmiri-rogan-josh', 'rogan-josh-34fea4', 'Rogan Josh', 'Kashmiri Pandit-style rogan josh — lamb braised with yogurt, fennel, dried ginger and Kashmiri chili into a glossy brick-red gravy, made as in Kashmiri Pandit homes without onion, garlic or tomato.', 'indian', 2, 15, 100, 115, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['make-ahead', 'comfort', 'entertaining']::text[], array['Asafoetida powder is usually blended with wheat flour — check the label if that matters.', 'Mustard oil sold in the US is often labeled for external use only; vegetable oil works fine if you''d rather not use it.']::text[], 'https://images.pexels.com/photos/30203309/pexels-photo-30203309.jpeg', 'Rogan josh in a metal bowl surrounded by whole spices', 'Nosh Caterers', 'https://www.pexels.com/@nosh-caterers-2148640437/', 'https://www.pexels.com/photo/authentic-rogan-josh-surrounded-by-mixed-spices-30203309/', 'pexels', true, 'public', false,
