insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('34fea4ce-f172-4be6-9f64-355991cf2ca9', 1, null, 'Heat the oil in a Dutch oven over medium-high heat until shimmering (if using mustard oil, heat it until it just smokes, then let it cool 1 minute to mellow). Add the asafoetida, cardamom, cloves, cinnamon and bay leaves and stir 30 seconds.', 180, null, null),
  ('34fea4ce-f172-4be6-9f64-355991cf2ca9', 2, null, 'Add the lamb in batches and sear, turning, until browned on all sides, 8–10 minutes in total.', 600, null, null),
  ('34fea4ce-f172-4be6-9f64-355991cf2ca9', 3, null, 'Lower the heat to medium and stir in the chili paste for 1 minute. Take the pot off the heat for a minute, then add the yogurt a spoonful at a time, stirring constantly so it doesn''t split. Return to medium heat and cook, stirring, until the yogurt is absorbed and the oil glistens, 8–10 minutes.', 600, null, null),
  ('34fea4ce-f172-4be6-9f64-355991cf2ca9', 4, null, 'Stir in the fennel, ginger, salt and hot water. Cover and simmer gently until the lamb is tender and pulling from the bone (well past 145°F), 60–75 minutes.', 4200, null, 62.8),
  ('34fea4ce-f172-4be6-9f64-355991cf2ca9', 5, null, 'Uncover and simmer until the gravy coats the meat and a layer of red oil shows on top, 5–10 minutes. Stir in the garam masala and serve with steamed basmati rice.', 480, null, null);

