values ('bdf30220-c806-4c6d-b10a-b550d58212aa', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chettinad-chicken', 'chettinad-chicken-bdf302', 'Chettinad Chicken', 'A fiery, pepper-forward chicken curry from the Chettinad region of Tamil Nadu, built on a freshly roasted and ground masala of chiles, black pepper, fennel, coconut and whole spices.', 'indian', 3, 30, 55, 85, 4, 'main', null, 0, array['stove', 'blender']::text[], array['entertaining']::text[], array['Grind the masala fresh — the roasted pepper and fennel are the soul of the dish.', 'Kalpasi (stone flower) is a dried lichen sold at Indian grocers that adds an earthy note; skip it if you can''t find it.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'entertaining']::text[], array['roast', 'stew']::text[], array['tangy', 'fresh', 'aromatic']::text[], '{}'::text[], 'Tamil Nadu', 'traditional', 'chettinad-chicken', 'classic', 'Refrigerate up to 4 days or freeze up to 3 months.', null, 'owned', array['sesame']::text[], array['chicken']::text[], array['gluten_free', 'dairy_free']::text[], array['thigh drumstick', 'ground turmeric', 'red chile', 'coriander seed', 'cumin seed', 'fennel seed', 'black peppercorn', 'clove', 'cinnamon stick', 'cardamom pod', 'anise pod', 'frozen coconut', 'sesame oil', 'curry leave', 'shallot', 'ginger-garlic paste', 'tomato', 'lime juice', 'cilantro']::text[], 'anise pod|black peppercorn|cardamom pod|cilantro|cinnamon stick|clove|coriander seed|cumin seed|curry leave|fennel seed|frozen coconut|ginger-garlic paste|ground turmeric|lime juice|red chile|sesame oil|shallot|thigh drumstick|tomato',
