delete from public.recipe_instructions where recipe_id = 'bdf30220-c806-4c6d-b10a-b550d58212aa';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('bdf30220-c806-4c6d-b10a-b550d58212aa', 1, 'Chicken', 'Toss the chicken with the turmeric and salt and set aside while you make the masala.', 900, null, null),
  ('bdf30220-c806-4c6d-b10a-b550d58212aa', 2, 'Masala', 'Dry-roast the chiles and whole spices (but not the coconut) in a skillet over medium-low heat, stirring, until fragrant and a shade darker, 3–4 minutes. Add the coconut and roast until golden, 2–3 minutes. Let cool, then grind with ½ cup water to a smooth paste.', 480, null, null),
  ('bdf30220-c806-4c6d-b10a-b550d58212aa', 3, 'Curry', 'Heat the oil in a heavy pot over medium heat. Add the fennel seeds and curry leaves and let them crackle, then add the shallots and fry until golden, about 8 minutes. Stir in the ginger-garlic paste for 1 minute, then the tomatoes, and cook until soft and jammy, about 5 minutes.', 840, null, null),
  ('bdf30220-c806-4c6d-b10a-b550d58212aa', 4, 'Curry', 'Add the masala paste and fry, stirring, until it darkens and the oil separates, 3–4 minutes. Add the chicken, turn to coat and cook 5 minutes.', 540, null, null),
  ('bdf30220-c806-4c6d-b10a-b550d58212aa', 5, 'Curry', 'Pour in the water, cover and simmer, stirring now and then, until the chicken is tender and reads 165°F next to the bone, 25–30 minutes. Uncover for the last few minutes to thicken the gravy.', 1800, null, 73.9),
  ('bdf30220-c806-4c6d-b10a-b550d58212aa', 6, 'Curry', 'Stir in the lime juice and cilantro and serve with rice or flaky parotta.', null, null, null);

