values ('1c2e6626-fc0f-459f-b94c-19b800d73550', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'goan-fish-curry', 'goan-fish-curry-1c2e66', 'Goan Fish Curry', 'The coastal curry Goans eat with rice almost every day: firm fish simmered in a smooth, coral-red coconut gravy soured with tamarind (and kokum, if you have it) and spiced with Kashmiri chiles and coriander.', 'indian', 3, 25, 30, 55, 4, 'main', null, 0, array['stove', 'blender']::text[], array['weeknight']::text[], array['Kokum, a dried sour fruit from the Konkan coast, gives a gentle tartness; leave it out and add a little more tamarind instead.', 'The curry is even better a few hours after it''s made, once the fish has absorbed the gravy.']::text[], 'https://images.pexels.com/photos/38324319/pexels-photo-38324319.jpeg', 'Coconut fish curry served with steamed rice', 'Gansham Ramchandani', 'https://www.pexels.com/@gunshe/', 'https://www.pexels.com/photo/delicious-indian-fish-curry-with-rice-and-coconut-38324319/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner']::text[], array['stew', 'steam']::text[], array['tangy', 'rich', 'aromatic']::text[], '{}'::text[], 'Goa', 'traditional', 'goan-fish-curry', 'classic', 'Refrigerate up to 2 days; reheat gently so the fish doesn''t break up.', null, 'owned', array['fish']::text[], array['fish']::text[], array['pescatarian', 'gluten_free', 'dairy_free']::text[], array['kingfish', 'ground turmeric', 'frozen coconut', 'kashmiri chile', 'coriander seed', 'cumin seed', 'black peppercorn', 'garlic', 'ginger', 'yellow onion', 'tamarind paste', 'green chile']::text[], 'black peppercorn|coriander seed|cumin seed|frozen coconut|garlic|ginger|green chile|ground turmeric|kashmiri chile|kingfish|tamarind paste|yellow onion',
  null, null, null, null, null, null, null, null)
