insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('1c2e6626-fc0f-459f-b94c-19b800d73550', 1, 'Fish', 'Rub the fish with the turmeric and salt and set aside 15 minutes.', 900, null, null),
  ('1c2e6626-fc0f-459f-b94c-19b800d73550', 2, 'Masala', 'Blend the coconut, drained chiles, coriander, cumin, peppercorns, turmeric, garlic and ginger with the warm water until very smooth, 3–4 minutes. (If you''re using coconut milk, blend the spices with ½ cup water, then stir in the coconut milk.)', 300, null, null),
  ('1c2e6626-fc0f-459f-b94c-19b800d73550', 3, 'Curry', 'Heat the oil in a wide pan over medium heat and cook the onion until soft and golden, 6–7 minutes. Add the masala, rinse the blender with the 1 cup water and add that too. Simmer, stirring, until the gravy no longer tastes harshly of spice and a little oil shows at the edges, 8–10 minutes.', 960, null, null),
  ('1c2e6626-fc0f-459f-b94c-19b800d73550', 4, 'Curry', 'Stir in the tamarind, kokum, green chiles and salt. The gravy should be pourable, like thin cream; add a splash of water if needed.', null, null, null),
  ('1c2e6626-fc0f-459f-b94c-19b800d73550', 5, 'Fish', 'Slide in the fish in a single layer and simmer gently — swirl the pan rather than stirring — until the fish flakes and reaches 145°F, 6–8 minutes.', 420, null, 62.8),
  ('1c2e6626-fc0f-459f-b94c-19b800d73550', 6, null, 'Let the curry rest off the heat for 10 minutes so the fish soaks up the gravy, then serve with steamed rice.', 600, null, null);

-- Garlic Naan
