values ('abc9d4c7-a42a-44a9-98d0-7392f7f1a342', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'garlic-naan-skillet', 'garlic-naan-abc9d4', 'Garlic Naan', 'Soft, chewy yogurt flatbreads blistered in a hot pan and brushed with garlic-cilantro butter; adapted to cook in a cast-iron skillet instead of a tandoor.', 'indian', 3, 120, 20, 140, 8, 'side', null, 0, array['stove', 'cast_iron']::text[], array['kid-friendly', 'make-ahead']::text[], array['For more char, hold each cooked naan with tongs over a gas flame for a few seconds per side.', 'Wrap the stack in a clean towel as you go — the trapped steam keeps the breads soft.']::text[], 'https://images.pexels.com/photos/35066813/pexels-photo-35066813.jpeg', 'Garlic naan bread on a white plate against a blue background', 'Milton Das', 'https://www.pexels.com/@miltonphotography/', 'https://www.pexels.com/photo/delicious-garlic-naan-on-a-white-plate-35066813/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'side', 'comfort']::text[], '{}'::text[], array['tangy', 'rich', 'fresh']::text[], '{}'::text[], null, 'adapted', 'garlic-naan', 'classic', 'Keep wrapped at room temperature for 1 day, or freeze with parchment between them up to 2 months. Reheat in a hot skillet or wrapped in foil at 350°F for 10 minutes.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['instant yeast', 'baking powder', 'whole-milk yogurt', 'garlic', 'cilantro']::text[], 'baking powder|cilantro|garlic|instant yeast|whole-milk yogurt',
  null, null, null, null, null, null, null, null)
