  ('abc9d4c7-a42a-44a9-98d0-7392f7f1a342', 7, 'Dough', '⅔ cup warm water, about 110°F', 'warm water', 0.66, 'cup', 'about 110°F', false),
  ('abc9d4c7-a42a-44a9-98d0-7392f7f1a342', 8, 'Dough', '2 tbsp vegetable oil', 'vegetable oil', 2, 'tbsp', null, false),
