  ('abc9d4c7-a42a-44a9-98d0-7392f7f1a342', 10, 'Garlic butter', '6 cloves garlic, finely chopped, divided', 'garlic', 6, 'clove', 'finely chopped, divided', false),
  ('abc9d4c7-a42a-44a9-98d0-7392f7f1a342', 11, 'Garlic butter', '3 tbsp fresh cilantro, finely chopped, divided', 'fresh cilantro', 3, 'tbsp', 'finely chopped, divided', false),
