delete from public.recipe_instructions where recipe_id = 'abc9d4c7-a42a-44a9-98d0-7392f7f1a342';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('abc9d4c7-a42a-44a9-98d0-7392f7f1a342', 1, 'Dough', 'Whisk the flour, yeast, sugar, salt and baking powder in a large bowl. Add the yogurt, warm water and oil and mix to a shaggy dough, then knead on the counter until smooth, soft and only slightly tacky, 6–8 minutes.', 480, null, null),
  ('abc9d4c7-a42a-44a9-98d0-7392f7f1a342', 2, 'Dough', 'Put the dough in an oiled bowl, cover and leave somewhere warm until doubled, 1–1½ hours.', 5400, null, null),
  ('abc9d4c7-a42a-44a9-98d0-7392f7f1a342', 3, 'Garlic butter', 'Melt the butter with half the garlic over low heat until fragrant but not browned, about 2 minutes. Stir in half the cilantro and keep warm.', 120, null, null),
  ('abc9d4c7-a42a-44a9-98d0-7392f7f1a342', 4, 'Dough', 'Divide the dough into 8 balls, cover and rest 10 minutes so it relaxes. Heat a 10- or 12-inch cast-iron skillet over medium-high heat for 5 minutes, until a drop of water skitters across it.', 600, null, null),
  ('abc9d4c7-a42a-44a9-98d0-7392f7f1a342', 5, 'Dough', 'Roll one ball into an oval about ¼ inch thick. Press a little of the remaining chopped garlic, cilantro and nigella seeds into the top. Lay it in the skillet garlic side up, cover with a lid and cook until big bubbles puff up and the underside is spotted dark brown, 1–1½ minutes.', 120, null, null),
  ('abc9d4c7-a42a-44a9-98d0-7392f7f1a342', 6, 'Dough', 'Flip and cook the garlic side for 30–45 seconds, just until spotted — watch that the garlic doesn''t burn. Brush with garlic butter, sprinkle with flaky salt and stack in a towel-lined basket. Repeat with the rest, keeping each one covered.', 960, null, null);

-- Vegetable Samosas
