values ('da0ddfa8-c015-49e3-b4f5-1e5775c65c56', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'vegetable-samosas-potato-pea', 'vegetable-samosas-da0ddf', 'Vegetable Samosas', 'Crisp, blistered pastry cones packed with a spiced potato and pea filling — the classic Punjabi-style samosa, the most common kind, fried low and slow for a flaky shell.', 'indian', 2, 60, 50, 110, 6, 'starter', null, 0, array['stove']::text[], array['make-ahead', 'entertaining']::text[], array['Low oil is the secret: if the oil is too hot the shell bubbles up and stays soft and greasy underneath.', 'Freeze shaped, uncooked samosas on a tray, then bag them. Fry from frozen, adding 3–4 minutes.']::text[], 'https://images.unsplash.com/photo-1601050690597-df0568f70950', 'Three golden fried samosas on a wooden tray with green chilli and pomegranate seeds', 'kabir cheema', 'https://unsplash.com/@kabircheema', 'https://unsplash.com/photos/samosas-with-green-chili-and-pomegranate-8T9AVksyt7s', 'unsplash', true, 'public', false,
  'pending_review', array['appetizer', 'holiday', 'entertaining']::text[], array['boil']::text[], array['spicy', 'tangy', 'rich', 'fresh', 'aromatic']::text[], array['diwali', 'game-day']::text[], null, 'traditional', 'samosa', 'classic', 'Refrigerate cooked samosas up to 3 days and re-crisp at 375°F for 10–12 minutes.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['russet potato', 'cumin seed', 'coriander seed', 'ginger', 'serrano chile', 'frozen pea', 'garam masala', 'chili powder', 'amchur', 'cilantro']::text[], 'amchur|chili powder|cilantro|coriander seed|cumin seed|frozen pea|garam masala|ginger|russet potato|serrano chile',
  null, null, null, null, null, null, null, null)
