  ('da0ddfa8-c015-49e3-b4f5-1e5775c65c56', 5, 'Pastry', '½ cup cold water, plus 1–2 tbsp as needed', 'cold water', 0.5, 'cup', 'plus 1–2 tbsp as needed', false),
  ('da0ddfa8-c015-49e3-b4f5-1e5775c65c56', 6, 'Filling', '1½ lb russet potatoes, about 3 medium, unpeeled', 'russet potatoes', 1.5, 'lb', 'about 3 medium, unpeeled', false),
