  ('da0ddfa8-c015-49e3-b4f5-1e5775c65c56', 8, 'Filling', '1 tsp cumin seeds', 'cumin seeds', 1, 'tsp', null, false),
  ('da0ddfa8-c015-49e3-b4f5-1e5775c65c56', 9, 'Filling', '1 tsp coriander seeds, coarsely crushed', 'coriander seeds', 1, 'tsp', 'coarsely crushed', false),
  ('da0ddfa8-c015-49e3-b4f5-1e5775c65c56', 10, 'Filling', '1 tbsp fresh ginger, finely grated', 'fresh ginger', 1, 'tbsp', 'finely grated', false),
