values ('f4d4567c-910e-4d5c-894f-abb7ccfacabf', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'gulab-jamun-milk-powder', 'gulab-jamun-f4d456', 'Gulab Jamun', 'Soft, golden milk dumplings soaked in warm cardamom-rose syrup, a festival favorite for Diwali and weddings; adapted to use dry milk powder instead of slow-cooked khoya.', 'indian', 2, 25, 35, 120, 8, 'dessert', 'plated', 60, array['stove']::text[], array['make-ahead', 'entertaining']::text[], array['If the balls crack while frying, the dough is too dry: work a few drops of milk into the rest and reroll.', 'Warm gulab jamun over a scoop of vanilla ice cream is a popular party way to serve them.']::text[], 'https://images.pexels.com/photos/15014918/pexels-photo-15014918.jpeg', 'Gulab jamun in syrup in a white bowl on a dark background', 'Nishess Shakya', 'https://www.pexels.com/@nishess-shakya-401526881/', 'https://www.pexels.com/photo/bowl-with-gulab-jamun-sweet-15014918/', 'pexels', true, 'public', false,
  'pending_review', array['holiday', 'dessert', 'entertaining']::text[], array['stew']::text[], array['tangy', 'rich', 'aromatic', 'sweet']::text[], array['diwali', 'eid-al-fitr']::text[], null, 'adapted', 'gulab-jamun', 'classic', 'Refrigerate in their syrup up to 5 days. Warm in the microwave for 20–30 seconds before serving.', null, 'owned', array['gluten', 'milk', 'tree_nut', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['cardamom pod', 'rose water', 'lemon juice', 'milk powder', 'baking soda', 'ghee', 'milk']::text[], 'baking soda|cardamom pod|ghee|lemon juice|milk|milk powder|rose water',
  null, null, null, null, null, null, null, null)
