  ('f4d4567c-910e-4d5c-894f-abb7ccfacabf', 1, 'Syrup', '2 cups sugar', 'sugar', 2, 'cup', null, false),
  ('f4d4567c-910e-4d5c-894f-abb7ccfacabf', 2, 'Syrup', '2 cups water', 'water', 2, 'cup', null, false),
