  ('f4d4567c-910e-4d5c-894f-abb7ccfacabf', 4, 'Syrup', 'saffron threads', 'saffron threads', null, 'pinch', null, true),
  ('f4d4567c-910e-4d5c-894f-abb7ccfacabf', 5, 'Syrup', '1 tsp rose water', 'rose water', 1, 'tsp', null, false),
  ('f4d4567c-910e-4d5c-894f-abb7ccfacabf', 6, 'Syrup', '1 tsp lemon juice', 'lemon juice', 1, 'tsp', null, false),
  ('f4d4567c-910e-4d5c-894f-abb7ccfacabf', 7, 'Dumplings', '1 cup nonfat dry milk powder', 'nonfat dry milk powder', 1, 'cup', null, false),
  ('f4d4567c-910e-4d5c-894f-abb7ccfacabf', 8, 'Dumplings', '¼ cup all-purpose flour', 'all-purpose flour', 0.25, 'cup', null, false),
