insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('f4d4567c-910e-4d5c-894f-abb7ccfacabf', 1, 'Syrup', 'Simmer the sugar, water, cardamom and saffron in a wide saucepan until the sugar dissolves and the syrup feels slightly sticky between your fingers (not stringy), about 6 minutes. Take off the heat, stir in the rose water and lemon juice and keep warm.', 480, null, null),
  ('f4d4567c-910e-4d5c-894f-abb7ccfacabf', 2, 'Dumplings', 'Whisk the milk powder, flour and baking soda. Rub in the ghee, then add the milk a tablespoon at a time, mixing gently, to make a soft, slightly sticky dough. Don''t knead. Cover and rest 10 minutes.', 600, null, null),
  ('f4d4567c-910e-4d5c-894f-abb7ccfacabf', 3, 'Dumplings', 'Grease your palms with ghee and roll the dough into 24 smooth balls about ¾ inch across, with no cracks — they roughly double as they fry.', null, null, null),
  ('f4d4567c-910e-4d5c-894f-abb7ccfacabf', 4, 'Frying', 'Heat the oil in a wide, heavy saucepan, no more than half full, to 290°F. A test ball should sink, then rise slowly with small bubbles. Keep children away and never leave hot oil unattended.', null, 143.3, null),
  ('f4d4567c-910e-4d5c-894f-abb7ccfacabf', 5, 'Frying', 'Fry 8 at a time over low heat, swirling the oil gently instead of poking the balls, until evenly deep golden brown, 7–8 minutes. If they brown in less than 5 minutes the oil is too hot and the centers will stay doughy.', 1440, 143.3, null),
  ('f4d4567c-910e-4d5c-894f-abb7ccfacabf', 6, 'Syrup', 'Lift the dumplings out, drain a few seconds and drop straight into the warm syrup. Soak at least 1 hour, until they swell and are soft all the way through. Serve warm or at room temperature with pistachios.', 3600, null, null);

