values ('a44f0349-0bc5-4a32-86e3-87f8095571f5', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-karahi-tomato', 'chicken-karahi-a44f03', 'Chicken Karahi', 'Bone-in chicken cooked hard and fast in a wok-like karahi with tomatoes, ginger, garlic, green chiles and cracked black pepper until the sauce clings — the tomato-based roadside style most Pakistani homes make.', 'pakistani', 3, 20, 35, 55, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'spicy']::text[], array['Ask the butcher to cut a whole chicken into karahi-size pieces (about 12), or use thighs and drumsticks cut through the bone with a cleaver.', 'Leave out the yogurt for a sharper, Peshawari-style finish.']::text[], 'https://images.pexels.com/photos/39378356/pexels-photo-39378356.jpeg', 'Spiced chicken curry simmering in a traditional karahi', 'Bachir Mamud', 'https://www.pexels.com/@bachir-mamud-1422142/', 'https://www.pexels.com/photo/spicy-chicken-curry-in-traditional-karahi-39378356/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner']::text[], array['stir_fry']::text[], array['spicy', 'tangy', 'rich', 'fresh', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'chicken-karahi', 'classic', 'Refrigerate up to 3 days; reheat in a covered pan with a splash of water.', null, 'owned', array['milk']::text[], array['chicken']::text[], array['gluten_free']::text[], array['ginger', 'garlic', 'tomato', 'chili powder', 'cumin seed', 'coriander seed', 'black peppercorn', 'serrano chile', 'garam masala', 'cilantro', 'lemon']::text[], 'black peppercorn|chili powder|cilantro|coriander seed|cumin seed|garam masala|garlic|ginger|lemon|serrano chile|tomato',
  null, null, null, null, null, null, null, null)
