insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('a44f0349-0bc5-4a32-86e3-87f8095571f5', 1, null, 'Heat the oil in a karahi, wok or wide heavy skillet over high heat. Add the chicken and stir-fry until white all over, about 5 minutes.', 300, null, null),
  ('a44f0349-0bc5-4a32-86e3-87f8095571f5', 2, null, 'Add the grated ginger, garlic and salt and stir-fry until fragrant and no longer sharp-smelling, 1–2 minutes.', 120, null, null),
  ('a44f0349-0bc5-4a32-86e3-87f8095571f5', 3, null, 'Add the tomatoes, cover and cook over medium heat until they collapse and the skins loosen, about 10 minutes. Fish out any loose skins with tongs if you like, and mash the tomatoes with the spoon.', 600, null, null),
  ('a44f0349-0bc5-4a32-86e3-87f8095571f5', 4, null, 'Uncover, turn the heat to high and add the chili powder, cumin, coriander and black pepper. Stir and scrape constantly until the tomatoes melt into a thick sauce that clings to the chicken, oil pools at the edges and the chicken reads 165°F at the bone, 10–12 minutes.', 720, null, 73.9),
  ('a44f0349-0bc5-4a32-86e3-87f8095571f5', 5, null, 'Lower the heat, stir in the yogurt, half the chiles and half the ginger matchsticks and cook 2–3 minutes. Sprinkle with garam masala, the rest of the chiles and ginger, and the cilantro. Serve from the pan with lemon wedges and naan.', 180, null, null);

