values ('e407d90f-f7a4-4ee5-9b5d-d3c3a8d0fd2a', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'beef-nihari', 'nihari-e407d9', 'Nihari', 'Beef shank slow-simmered overnight-style with a warm fennel-and-cardamom spice blend until it falls apart into a silky, peppery gravy — the Pakistani breakfast stew, made with beef as it most often is.', 'pakistani', 3, 30, 330, 360, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['comfort', 'make-ahead', 'entertaining']::text[], array['Pressure-cooker shortcut: after step 3, cook at high pressure for 75 minutes, release naturally, then thicken as in step 5.', 'A packet of nihari masala can replace the homemade blend; some brands include flour or other additives, so check the label if anyone eating has allergies.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner', 'holiday', 'entertaining']::text[], array['stew', 'pan_fry', 'boil']::text[], array['spicy', 'rich', 'fresh', 'aromatic']::text[], array['eid-al-adha']::text[], null, 'traditional', 'nihari', 'classic', 'Tastes even better the next day. Refrigerate up to 4 days or freeze up to 3 months; loosen with water when reheating.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], array['beef']::text[], '{}'::text[], array['fennel seed', 'cumin seed', 'coriander seed', 'black peppercorn', 'clove', 'cardamom pod', 'cinnamon stick', 'ground nutmeg', 'ground ginger', 'ghee', 'yellow onion', 'beef shank', 'ginger', 'garlic', 'chili powder', 'ground turmeric', 'whole-wheat flour', 'green chile', 'cilantro', 'lemon']::text[], 'beef shank|black peppercorn|cardamom pod|chili powder|cilantro|cinnamon stick|clove|coriander seed|cumin seed|fennel seed|garlic|ghee|ginger|green chile|ground ginger|ground nutmeg|ground turmeric|lemon|whole-wheat flour|yellow onion',
