  ('e407d90f-f7a4-4ee5-9b5d-d3c3a8d0fd2a', 20, 'Stew', '1 tsp ground turmeric', 'ground turmeric', 1, 'tsp', null, false),
  ('e407d90f-f7a4-4ee5-9b5d-d3c3a8d0fd2a', 21, 'Stew', '8 cups water', 'water', 8, 'cup', null, false),
