values ('41610c33-bb2b-467d-aae5-409c14705f66', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'kacchi-biryani-goat', 'kacchi-biryani-41610c', 'Kacchi Biryani', 'Dhaka''s celebration biryani: raw goat marinated in yogurt and warm spices, layered under half-cooked basmati with potatoes, saffron milk and crisp fried onions, then sealed and slow-steamed together.', 'bangladeshi', 3, 300, 130, 430, 8, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['entertaining', 'make-ahead']::text[], array['Goat from a halal butcher is the Dhaka classic; bone-in lamb shoulder works the same way.', 'Store-bought crispy fried onions often have wheat flour coatings; if you buy instead of making them, check the label.']::text[], 'https://images.pexels.com/photos/5695615/pexels-photo-5695615.jpeg', 'Mutton biryani with tender meat on a white plate, garnished with spices and lime', 'Shourav Sheikh', 'https://www.pexels.com/@shouravsheikh/', 'https://www.pexels.com/photo/meal-on-plate-5695615/', 'pexels', true, 'public', false,
  'pending_review', array['holiday', 'main', 'dinner', 'entertaining']::text[], array['boil']::text[], array['spicy', 'tangy', 'rich', 'aromatic']::text[], array['eid-al-adha', 'eid-al-fitr']::text[], null, 'traditional', 'kacchi-biryani', 'classic', 'Refrigerate up to 3 days. Reheat covered, with a splash of water, in a 325°F oven until steaming hot.', 'The meat goes into the pot raw and cooks only in the sealed steam, so cut it no bigger than 2 inches, use a heavy pot, and check that a piece from the center is tender and reads at least 145°F before serving.', 'owned', array['milk']::text[], array['goat']::text[], array['gluten_free']::text[], array['yellow onion', 'goat meat', 'whole-milk yogurt', 'ginger', 'garlic', 'chili powder', 'garam masala', 'ground nutmeg', 'cardamom pod', 'cinnamon stick', 'clove', 'bay leave', 'lemon juice', 'green chile', 'gold potato', 'ground turmeric', 'basmati rice', 'milk', 'saffron thread', 'ghee']::text[], 'basmati rice|bay leave|cardamom pod|chili powder|cinnamon stick|clove|garam masala|garlic|ghee|ginger|goat meat|gold potato|green chile|ground nutmeg|ground turmeric|lemon juice|milk|saffron thread|whole-milk yogurt|yellow onion',
  null, null, null, null, null, null, null, null)
