insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('41610c33-bb2b-467d-aae5-409c14705f66', 1, 'Fried onions', 'Heat the oil in a wide skillet to about 325°F. Fry the onions in 2 batches, stirring often, until evenly deep golden, 12–15 minutes per batch — pull them a shade early, as they darken as they drain. Spread on paper towels to crisp and save the oil. Never leave hot oil unattended.', 1680, 162.8, null),
  ('41610c33-bb2b-467d-aae5-409c14705f66', 2, 'Goat', 'In a large bowl mix the yogurt, ginger, garlic, salt, chili powder, garam masala, nutmeg, mace, whole spices, sugar, lemon juice, chiles, plums, 3 tablespoons of the onion oil and half the fried onions, crushed. Add the goat and coat well. Cover and refrigerate at least 4 hours or overnight.', 14400, null, null),
  ('41610c33-bb2b-467d-aae5-409c14705f66', 3, 'Potatoes', 'Toss the potatoes with the turmeric and salt and fry in 2 tablespoons of the onion oil over medium heat until golden on the outside, about 8 minutes.', 480, null, null),
  ('41610c33-bb2b-467d-aae5-409c14705f66', 4, 'Rice', 'Bring 4 quarts of water to a boil with the salt, cardamom and bay leaves. Add the drained rice and boil until about 70% cooked — a grain should snap with a hard white core — 4–5 minutes. Drain well. Stir the saffron into the warm milk.', 360, null, null),
  ('41610c33-bb2b-467d-aae5-409c14705f66', 5, null, 'Spread the goat and all its marinade in an even layer in a heavy 6- to 7-quart Dutch oven and tuck in the potatoes. Spoon the rice over evenly, then drizzle with the saffron milk, kewra water, ghee and 2 tablespoons onion oil, and scatter over the rest of the fried onions. Cover with two layers of foil, crimped tight, then the lid.', null, null, null),
  ('41610c33-bb2b-467d-aae5-409c14705f66', 6, null, 'Cook over medium heat until you hear a steady sizzle, about 10 minutes. Set the pot on a heat diffuser or a flat cast-iron griddle over the lowest heat and cook, without opening, 75–90 minutes. Rest 15 minutes off the heat.', 6000, null, null),
  ('41610c33-bb2b-467d-aae5-409c14705f66', 7, null, 'Open the pot and test a piece of goat from the center: it should pull easily from the bone and read at least 145°F. If not, reseal and cook 15 minutes more. Serve by digging straight down with a large spoon so everyone gets rice, meat and potato.', null, null, 62.8);

-- Sri Lankan Chicken Curry
