values ('14a0afb7-cf64-492f-b5fe-c61efe61a81a', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'sri-lankan-chicken-curry-coconut', 'sri-lankan-chicken-curry-14a0af', 'Sri Lankan Chicken Curry', 'Bone-in chicken simmered in coconut milk with dark-roasted curry powder, curry leaves, pandan and lemongrass — a fragrant, peppery home-style kukul mas curry.', 'sri_lankan', 3, 40, 45, 85, 4, 'main', null, 0, array['stove']::text[], array['comfort', 'spicy']::text[], array['Sri Lankan roasted curry powder is darker and toastier than Indian blends; find it at South Asian grocers or online.', 'Fresh curry leaves freeze well — keep a bag in the freezer and add them straight from frozen.']::text[], 'https://images.unsplash.com/photo-1708658767771-718c38b75a9b', 'Sri Lankan chicken curry with rice and vegetable sides on a white plate, seen from above', 'Rakitha Perera', 'https://unsplash.com/@rakithaperera', 'https://unsplash.com/photos/a-white-plate-topped-with-rice-meat-and-veggies-tP8dXmCHqBc', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'comfort']::text[], array['stew', 'boil']::text[], array['spicy', 'tangy', 'rich', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'sri-lankan-chicken-curry', 'classic', 'Refrigerate up to 3 days or freeze up to 3 months. Reheat gently so the coconut milk doesn''t split.', null, 'owned', '{}'::text[], array['chicken']::text[], array['gluten_free', 'dairy_free']::text[], array['curry powder', 'chili powder', 'ground turmeric', 'white vinegar', 'coconut oil', 'cinnamon stick', 'cardamom pod', 'clove', 'curry leave', 'lemongrass', 'yellow onion', 'garlic', 'ginger', 'green chile', 'tomato', 'coconut milk', 'lime juice']::text[], 'cardamom pod|chili powder|cinnamon stick|clove|coconut milk|coconut oil|curry leave|curry powder|garlic|ginger|green chile|ground turmeric|lemongrass|lime juice|tomato|white vinegar|yellow onion',
  null, null, null, null, null, null, null, null)
