  ('14a0afb7-cf64-492f-b5fe-c61efe61a81a', 15, 'Curry', '1 yellow onion, finely chopped', 'yellow onion', 1, null, 'finely chopped', false),
  ('14a0afb7-cf64-492f-b5fe-c61efe61a81a', 16, 'Curry', '4 cloves garlic, finely chopped', 'garlic', 4, 'clove', 'finely chopped', false),
  ('14a0afb7-cf64-492f-b5fe-c61efe61a81a', 17, 'Curry', '1 tbsp fresh ginger, finely grated', 'fresh ginger', 1, 'tbsp', 'finely grated', false),
  ('14a0afb7-cf64-492f-b5fe-c61efe61a81a', 18, 'Curry', '2 green chiles, slit', 'green chiles', 2, null, 'slit', false),
  ('14a0afb7-cf64-492f-b5fe-c61efe61a81a', 19, 'Curry', '1 tomato, chopped', 'tomato', 1, null, 'chopped', false),
  ('14a0afb7-cf64-492f-b5fe-c61efe61a81a', 20, 'Curry', '1 can coconut milk, 13.5 oz, unshaken', 'coconut milk', 1, 'can', '13.5 oz, unshaken', false),
  ('14a0afb7-cf64-492f-b5fe-c61efe61a81a', 21, 'Curry', '½ cup water', 'water', 0.5, 'cup', null, false),
