delete from public.recipe_instructions where recipe_id = '14a0afb7-cf64-492f-b5fe-c61efe61a81a';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('14a0afb7-cf64-492f-b5fe-c61efe61a81a', 1, 'Chicken', 'Toss the chicken with the curry powder, chili powder, turmeric, pepper, salt and vinegar. Leave 30 minutes at room temperature, or up to overnight in the fridge.', 1800, null, null),
  ('14a0afb7-cf64-492f-b5fe-c61efe61a81a', 2, 'Curry', 'Heat the oil in a wide, heavy pot over medium heat. Add the cinnamon, cardamom and cloves for 30 seconds, then the curry leaves, pandan and lemongrass until the leaves crackle, about 30 seconds more.', 60, null, null),
  ('14a0afb7-cf64-492f-b5fe-c61efe61a81a', 3, 'Curry', 'Add the onion and cook until golden, about 8 minutes. Stir in the garlic, ginger and chiles for 1 minute.', 540, null, null),
  ('14a0afb7-cf64-492f-b5fe-c61efe61a81a', 4, 'Curry', 'Add the chicken and all its spices and stir until coated and lightly browned, about 5 minutes. Add the tomato.', 300, null, null),
  ('14a0afb7-cf64-492f-b5fe-c61efe61a81a', 5, 'Curry', 'Spoon the thick cream from the top of the coconut milk can into a bowl. Pour the thin coconut milk left in the can and the water into the pot, cover and simmer gently, stirring now and then, for 25 minutes.', 1500, null, null),
  ('14a0afb7-cf64-492f-b5fe-c61efe61a81a', 6, 'Curry', 'Stir in the thick coconut cream and simmer uncovered, without boiling hard, until the gravy thickens and the chicken reads 165°F at the bone, about 5 minutes. Stir in the lime juice, taste for salt and serve with rice.', 300, null, 73.9);

