values ('c91c906c-cf38-439d-9e47-d36b6da8c9c4', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'egg-hoppers-appa', 'egg-hoppers-c91c90', 'Egg Hoppers', 'Bowl-shaped, lacy-edged rice flour and coconut milk pancakes with a soft-centered egg baked into each one, served with a fiery onion sambol for breakfast; you''ll need a hopper pan or a small nonstick wok with a lid.', 'sri_lankan', 3, 180, 45, 225, 4, 'breakfast', null, 0, array['stove', 'blender']::text[], array['brunch']::text[], array['The first hopper is a test: if the edges are thick, thin the batter with a spoonful of water; if they tear, cook a little longer before lifting.', 'Maldive fish is dried cured tuna — leave it out if you don''t eat fish.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['breakfast', 'holiday']::text[], array['stir_fry']::text[], array['spicy', 'tangy', 'rich']::text[], array['brunch-party']::text[], null, 'traditional', 'egg-hoppers', 'classic', 'Hoppers are best straight from the pan. The batter keeps in the fridge 1 day; bring it to room temperature first. Lunu miris keeps 3 days refrigerated.', 'The egg yolks in hoppers are traditionally left runny, so they don''t reach 160°F. Use pasteurized eggs for anyone pregnant, very young, older, or with a weakened immune system, or cook covered 2–3 minutes longer until the yolks are firm.', 'owned', array['egg', 'fish']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free', 'dairy_free']::text[], array['white rice', 'instant yeast', 'rice flour', 'coconut milk', 'baking soda', 'coconut oil', 'egg', 'red onion', 'chili flake', 'lime juice']::text[], 'baking soda|chili flake|coconut milk|coconut oil|egg|instant yeast|lime juice|red onion|rice flour|white rice',
  null, null, null, null, null, null, null, null)
