  ('c91c906c-cf38-439d-9e47-d36b6da8c9c4', 1, 'Batter', '¼ cup cooked white rice', 'cooked white rice', 0.25, 'cup', null, false),
  ('c91c906c-cf38-439d-9e47-d36b6da8c9c4', 2, 'Batter', '¾ cup warm water, about 105°F, plus up to ½ cup more to thin', 'warm water', 0.75, 'cup', 'about 105°F, plus up to ½ cup more to thin', false),
