  ('c91c906c-cf38-439d-9e47-d36b6da8c9c4', 5, 'Batter', '2 cups white rice flour, not glutinous or sweet rice flour', 'white rice flour', 2, 'cup', 'not glutinous or sweet rice flour', false),
  ('c91c906c-cf38-439d-9e47-d36b6da8c9c4', 6, 'Batter', '1 can coconut milk, 13.5 oz, divided', 'coconut milk', 1, 'can', '13.5 oz, divided', false),
