values ('be5c046c-d9ef-43d7-8e78-33aea81ab406', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-momos-tomato-achar', 'momos-be5c04', 'Momos', 'Juicy steamed dumplings filled with ginger-garlic spiced ground chicken — the most common filling today, though buffalo is the old Kathmandu classic — served with a smoky tomato-sesame achar.', 'nepali', 3, 75, 35, 110, 6, 'starter', null, 0, array['stove', 'blender']::text[], array['make-ahead', 'entertaining']::text[], array['Freeze shaped, uncooked momos on a tray, then bag them; steam from frozen for 15 minutes.', 'Sichuan peppercorns are a close substitute for Nepali timur — both give a citrusy, tingly buzz.']::text[], 'https://images.unsplash.com/photo-1694923450868-b432a8ee52aa', 'Steamed momos on a white plate with a cup of dipping sauce', 'kabita Darlami', 'https://unsplash.com/@itskabita', 'https://unsplash.com/photos/a-white-plate-topped-with-dumplings-next-to-a-cup-of-sauce-90SXZzJpySc', 'unsplash', true, 'public', false,
  'pending_review', array['appetizer', 'entertaining']::text[], array['steam', 'boil']::text[], array['tangy', 'fresh', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'momos', 'classic', 'Refrigerate cooked momos up to 2 days and re-steam 5 minutes, or pan-fry for crisp bottoms. The achar keeps 5 days refrigerated.', null, 'owned', array['gluten', 'sesame', 'wheat']::text[], array['chicken']::text[], array['dairy_free']::text[], array['ground chicken', 'red onion', 'scallion', 'cilantro', 'ginger', 'garlic', 'ground cumin', 'tomato', 'red chile', 'sesame seed', 'lemon juice']::text[], 'cilantro|garlic|ginger|ground chicken|ground cumin|lemon juice|red chile|red onion|scallion|sesame seed|tomato',
  null, null, null, null, null, null, null, null)
