delete from public.recipe_instructions where recipe_id = 'be5c046c-d9ef-43d7-8e78-33aea81ab406';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('be5c046c-d9ef-43d7-8e78-33aea81ab406', 1, 'Wrappers', 'Mix the flour and salt, then add the water gradually to make a firm, smooth dough. Knead 5 minutes, cover and rest 30 minutes.', 1800, null, null),
  ('be5c046c-d9ef-43d7-8e78-33aea81ab406', 2, 'Filling', 'Mix all the filling ingredients thoroughly with your hand until sticky. Cover and refrigerate while you make the achar.', null, null, null),
  ('be5c046c-d9ef-43d7-8e78-33aea81ab406', 3, 'Tomato achar', 'Char the whole tomatoes and dried chiles in a dry skillet over medium-high heat, turning, until blackened in spots and the tomatoes soften, about 10 minutes (pull the chiles after 1 minute). Toast the sesame seeds in the same pan until golden, 2 minutes. Blend everything with the garlic, timur, cilantro, lemon juice and salt until smooth.', 720, null, null),
  ('be5c046c-d9ef-43d7-8e78-33aea81ab406', 4, 'Wrappers', 'Roll the dough into a log and cut into 30 pieces. Roll each into a 3-inch round, thinner at the edge than the center. Put a heaping teaspoon of filling in the middle, then pleat the edge around it and twist to close into a little purse. Keep finished momos covered.', null, null, null),
  ('be5c046c-d9ef-43d7-8e78-33aea81ab406', 5, 'Wrappers', 'Bring 2 inches of water to a boil under an oiled steamer basket. Steam the momos in batches, 1 inch apart and covered, until the wrappers look slightly translucent and the filling reads 165°F, 10–12 minutes per batch. Serve hot with the achar.', 1440, null, 73.9);

-- Dal Bhat
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
