values ('65c3df7d-1573-4b31-aff6-9b86f0fb69a4', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'dal-bhat-tarkari', 'dal-bhat-65c3df', 'Dal Bhat', 'Nepal''s everyday plate: soupy red lentil dal finished with a sizzling garlic-cumin tempering, steamed rice and a turmeric-spiced potato and cauliflower tarkari.', 'nepali', 2, 15, 40, 55, 4, 'main', null, 0, array['stove']::text[], array['budget', 'comfort', 'weeknight']::text[], array['Nepali cooks often use mustard oil for the tarkari; it adds a pleasant sharp heat if you can find one sold for cooking.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['budget', 'main', 'dinner', 'comfort']::text[], array['stew', 'boil']::text[], array['spicy', 'tangy', 'rich', 'fresh', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'dal-bhat', 'classic', 'Refrigerate each part separately up to 4 days. The dal thickens as it sits; loosen with hot water when reheating.', null, 'owned', array['milk']::text[], array['beans']::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['white rice', 'red lentil', 'ground turmeric', 'ghee', 'cumin seed', 'red chile', 'garlic', 'fenugreek seed', 'yellow onion', 'ginger', 'tomato', 'ground cumin', 'ground coriander', 'gold potato', 'cauliflower', 'cilantro', 'lime']::text[], 'cauliflower|cilantro|cumin seed|fenugreek seed|garlic|ghee|ginger|gold potato|ground coriander|ground cumin|ground turmeric|lime|red chile|red lentil|tomato|white rice|yellow onion',
  null, null, null, null, null, null, null, null)
