insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('65c3df7d-1573-4b31-aff6-9b86f0fb69a4', 1, 'Bhat', 'Rinse the rice until the water runs nearly clear. Bring it to a boil with the water, cover, turn the heat to low and cook 15 minutes. Rest off the heat, covered, 10 minutes.', 1500, null, null),
  ('65c3df7d-1573-4b31-aff6-9b86f0fb69a4', 2, 'Dal', 'Bring the lentils, water and turmeric to a boil, skim the foam, and simmer partly covered, stirring now and then, until completely soft and soupy, 20 minutes. Whisk to break them up and stir in the salt.', 1200, null, null),
  ('65c3df7d-1573-4b31-aff6-9b86f0fb69a4', 3, 'Tarkari', 'Meanwhile, heat the oil in a skillet over medium heat. Add the cumin and fenugreek seeds until they darken slightly, 30 seconds, then the onion until soft, 5 minutes. Stir in the ginger, garlic, tomato and ground spices and cook 2 minutes.', 480, null, null),
  ('65c3df7d-1573-4b31-aff6-9b86f0fb69a4', 4, 'Tarkari', 'Add the potatoes, cauliflower, salt and water. Cover and cook over medium-low, stirring occasionally, until the potatoes are tender, 15 minutes. Uncover and cook off any liquid, then add the cilantro.', 1020, null, null),
  ('65c3df7d-1573-4b31-aff6-9b86f0fb69a4', 5, 'Dal', 'For the tempering, heat the ghee in a small pan until shimmering. Add the cumin seeds, jimbu, chile and garlic and sizzle until the garlic turns golden, about 1 minute. Pour it straight into the dal (stand back — it spits) and stir.', 60, null, null),
  ('65c3df7d-1573-4b31-aff6-9b86f0fb69a4', 6, null, 'Serve the rice with the dal ladled over or beside it, the tarkari and lime wedges, and any pickle you like.', null, null, null);

