values ('d2fa0334-8a77-4b12-b9f7-2838ca7c5ce5', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'kabuli-pulao-lamb', 'kabuli-pulao-d2fa03', 'Kabuli Pulao', 'Afghanistan''s national dish: cumin-scented rice steamed in rich lamb broth, colored by deeply browned onions, with tender lamb hidden underneath and sweet carrots, raisins and almonds on top.', 'afghan', 3, 75, 160, 235, 6, 'main', null, 0, array['stove', 'oven', 'dutch_oven']::text[], array['entertaining', 'comfort']::text[], array['Don''t rush the onions: pale onions give pale pulao. If they catch, add a spoonful of water and keep going.']::text[], 'https://images.unsplash.com/photo-1694004599545-9f25feaf665a', 'Close-up of a plate of Kabuli pulao rice', 'Ahmad Redai Hashmi', 'https://unsplash.com/@ahmad_redai_hashmi', 'https://unsplash.com/photos/a-close-up-of-a-plate-of-food-on-a-table-IRZZBK4rO7k', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'holiday', 'comfort', 'entertaining']::text[], array['stew', 'pan_fry', 'bake', 'boil']::text[], array['aromatic']::text[], array['eid-al-adha', 'eid-al-fitr', 'dinner-party']::text[], null, 'traditional', 'kabuli-pulao', 'classic', 'Refrigerate up to 3 days. Reheat covered in a 325°F oven with a splash of broth.', null, 'owned', array['tree_nut']::text[], array['lamb']::text[], array['gluten_free', 'dairy_free']::text[], array['yellow onion', 'lamb shoulder', 'ground cumin', 'ground cardamom', 'basmati rice', 'carrot', 'raisin', 'slivered almond']::text[], 'basmati rice|carrot|ground cardamom|ground cumin|lamb shoulder|raisin|slivered almond|yellow onion',
  null, null, null, null, null, null, null, null)
