delete from public.recipe_instructions where recipe_id = 'd2fa0334-8a77-4b12-b9f7-2838ca7c5ce5';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('d2fa0334-8a77-4b12-b9f7-2838ca7c5ce5', 1, 'Lamb', 'Heat the oil in a large Dutch oven over medium-high heat and fry the onions, stirring often, until very dark brown but not burnt, 15–20 minutes. This browning gives the rice its color.', 1080, null, null),
  ('d2fa0334-8a77-4b12-b9f7-2838ca7c5ce5', 2, 'Lamb', 'Add the lamb and salt and brown on all sides, about 8 minutes. Stir in the cumin, cardamom and pepper for 1 minute, then add the water. Bring to a boil, skim, cover and simmer until the lamb is tender and pulls from the bone (well past 145°F), 75–90 minutes.', 5400, null, 62.8),
  ('d2fa0334-8a77-4b12-b9f7-2838ca7c5ce5', 3, 'Topping', 'Meanwhile, heat the oil in a skillet over medium heat. Cook the carrots with the sugar until just tender and glossy, 5 minutes. Add the raisins and cook until plump, 1–2 minutes; transfer to a plate. Toast the almonds and pistachios in the same pan until golden, 2 minutes.', 540, null, null),
  ('d2fa0334-8a77-4b12-b9f7-2838ca7c5ce5', 4, 'Rice', 'Heat the oven to 325°F. Bring 3 quarts of water with the salt to a boil, add the drained rice and boil 4 minutes, until half cooked. Drain.', 360, 162.8, null),
  ('d2fa0334-8a77-4b12-b9f7-2838ca7c5ce5', 5, 'Rice', 'Lift the lamb out of the pot. Measure 1½ cups of the broth with its onions and fat (save the rest for soup) and return it to the pot with the cumin and cardamom. Gently fold in the rice, bury the lamb in it and pile the carrots and raisins on top. Cover with foil and the lid.', null, 162.8, null),
  ('d2fa0334-8a77-4b12-b9f7-2838ca7c5ce5', 6, 'Rice', 'Bake until the rice is tender and fluffy, 45 minutes. To serve, mound the rice on a platter with the lamb, then the carrots, raisins and nuts on top.', 2700, 162.8, null);

