values ('8bef5be1-5551-4e11-a0a8-0b691904e1b2', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'uzbek-plov-lamb', 'plov-8bef5b', 'Plov', 'Uzbekistan''s one-pot feast: lamb, onions and a mountain of carrot matchsticks fried in a heavy pot with cumin, then cooked under a layer of rice with whole heads of garlic — the lamb version is the most common.', 'uzbek', 3, 45, 100, 145, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['entertaining', 'comfort']::text[], array['Cut the carrots by hand rather than grating them — grated carrots turn to mush. Yellow carrots, as used in Uzbekistan, are worth buying if you see them.']::text[], 'https://images.pexels.com/photos/10541694/pexels-photo-10541694.jpeg', 'Plov with rice, meat and vegetables on a blue and white plate', 'eugene k', 'https://www.pexels.com/@eugene-k-151118282/', 'https://www.pexels.com/photo/food-on-blue-and-white-ceramic-plate-10541694/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner', 'holiday', 'comfort', 'entertaining']::text[], array['stew', 'pan_fry', 'boil']::text[], array['aromatic']::text[], array['new-year', 'dinner-party']::text[], null, 'traditional', 'plov', 'classic', 'Refrigerate up to 3 days. Reheat covered in a skillet with a splash of water.', null, 'owned', '{}'::text[], array['lamb']::text[], array['gluten_free', 'dairy_free']::text[], array['yellow onion', 'lamb shoulder', 'carrot', 'cumin seed', 'coriander seed', 'garlic', 'red chile', 'medium-grain rice', 'boiling water']::text[], 'boiling water|carrot|coriander seed|cumin seed|garlic|lamb shoulder|medium-grain rice|red chile|yellow onion',
  null, null, null, null, null, null, null, null)
