  ('8bef5be1-5551-4e11-a0a8-0b691904e1b2', 9, 'Zirvak', '2 head garlic, loose papery skin rubbed off, left whole', 'garlic', 2, 'head', 'loose papery skin rubbed off, left whole', false),
  ('8bef5be1-5551-4e11-a0a8-0b691904e1b2', 10, 'Zirvak', '2 dried red chiles', 'dried red chiles', 2, null, null, false),
  ('8bef5be1-5551-4e11-a0a8-0b691904e1b2', 11, 'Zirvak', '1 can chickpeas, 15 oz, drained', 'chickpeas', 1, 'can', '15 oz, drained', true),
  ('8bef5be1-5551-4e11-a0a8-0b691904e1b2', 12, 'Zirvak', '4 cups water', 'water', 4, 'cup', null, false),
  ('8bef5be1-5551-4e11-a0a8-0b691904e1b2', 13, 'Rice', '3 cups medium-grain rice, or basmati, soaked 30 minutes', 'medium-grain rice', 3, 'cup', 'or basmati, soaked 30 minutes', false),
