values ('9c572458-1d61-4842-b98f-18f0d043133b', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'pavlova-passionfruit', 'pavlova-9c5724', 'Pavlova', 'A crisp-shelled, marshmallowy meringue piled with softly whipped cream, passionfruit and fresh berries — the Australian summer and Christmas classic (New Zealand claims it too).', 'australian', 3, 25, 80, 225, 8, 'dessert', 'cakes', 120, array['oven', 'stand_mixer']::text[], array['make-ahead', 'entertaining']::text[], array['Cracks and a slight collapse are normal — the cream and fruit cover everything.', 'Avoid making meringue on a humid day; the shell softens and weeps.']::text[], 'https://images.unsplash.com/photo-1641848373324-bc744c442d5b', 'Strawberry pavlova topped with whipped cream and fresh strawberries', 'Léo Roza', 'https://unsplash.com/@leoroza', 'https://unsplash.com/photos/a-cake-with-white-frosting-and-strawberries-on-top-Pf8pXy0L1DA', 'unsplash', true, 'public', false,
  'pending_review', array['dessert', 'baking', 'holiday', 'entertaining']::text[], array['bake']::text[], array['tangy', 'rich', 'sweet']::text[], array['christmas', 'dinner-party']::text[], null, 'traditional', 'pavlova', 'classic', 'The plain meringue keeps 2 days in an airtight container at room temperature. Once topped, serve within 1 hour; leftovers soften in the fridge but taste fine the next day.', null, 'owned', array['egg', 'milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['egg white', 'superfine sugar', 'cornstarch', 'white vinegar', 'vanilla extract', 'heavy cream', 'powdered sugar', 'passionfruit', 'strawberry', 'kiwifruit']::text[], 'cornstarch|egg white|heavy cream|kiwifruit|passionfruit|powdered sugar|strawberry|superfine sugar|vanilla extract|white vinegar',
  null, null, null, null, null, null, null, null)
