insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('9c572458-1d61-4842-b98f-18f0d043133b', 1, 'Meringue', '4 large egg whites, at room temperature', 'large egg whites', 4, null, 'at room temperature', false),
  ('9c572458-1d61-4842-b98f-18f0d043133b', 2, 'Meringue', 'kosher salt', 'kosher salt', null, 'pinch', null, false),
  ('9c572458-1d61-4842-b98f-18f0d043133b', 3, 'Meringue', '1 cup superfine sugar, or granulated sugar pulsed 30 seconds in a blender', 'superfine sugar', 1, 'cup', 'or granulated sugar pulsed 30 seconds in a blender', false),
  ('9c572458-1d61-4842-b98f-18f0d043133b', 4, 'Meringue', '2 tsp cornstarch', 'cornstarch', 2, 'tsp', null, false),
  ('9c572458-1d61-4842-b98f-18f0d043133b', 5, 'Meringue', '1 tsp white vinegar', 'white vinegar', 1, 'tsp', null, false),
  ('9c572458-1d61-4842-b98f-18f0d043133b', 6, 'Meringue', '1 tsp vanilla extract', 'vanilla extract', 1, 'tsp', null, false),
  ('9c572458-1d61-4842-b98f-18f0d043133b', 7, 'Topping', '1½ cups heavy cream, cold', 'heavy cream', 1.5, 'cup', 'cold', false),
