delete from public.recipe_instructions where recipe_id = '9c572458-1d61-4842-b98f-18f0d043133b';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('9c572458-1d61-4842-b98f-18f0d043133b', 1, 'Meringue', 'Heat the oven to 250°F. Draw an 8-inch circle on a sheet of parchment, flip it over and lay it on a baking sheet.', null, 121.1, null),
  ('9c572458-1d61-4842-b98f-18f0d043133b', 2, 'Meringue', 'In a spotlessly clean stand-mixer bowl, whisk the egg whites and salt on medium until soft peaks form. With the mixer on high, add the sugar a tablespoon at a time, then keep whisking until the meringue is stiff and glossy and feels smooth, not gritty, between your fingers, 8–10 minutes in all.', 600, null, null),
  ('9c572458-1d61-4842-b98f-18f0d043133b', 3, 'Meringue', 'Sift the cornstarch over, add the vinegar and vanilla and fold in gently. Pile the meringue inside the circle and spread it out, making the sides a little higher than the center.', null, null, null),
  ('9c572458-1d61-4842-b98f-18f0d043133b', 4, 'Meringue', 'Bake until the outside is dry and crisp and lifts off the paper, 75–80 minutes. Turn off the oven, prop the door open slightly and leave the meringue to cool inside for at least 2 hours, or overnight.', 4800, 121.1, null),
  ('9c572458-1d61-4842-b98f-18f0d043133b', 5, 'Topping', 'Just before serving, whip the cream with the powdered sugar to soft peaks. Set the meringue on a platter, spread the cream over the top and finish with the strawberries, kiwi and passionfruit pulp. Cut with a serrated knife.', 180, null, null);

-- Lamb Chops with Mint Sauce
