values ('8c299c9f-d647-45b3-aefe-142300502b6a', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'lamb-loin-chops-mint-sauce', 'lamb-chops-with-mint-sauce-8c299c', 'Lamb Chops with Mint Sauce', 'Thick lamb loin chops seared hard with garlic and rosemary and served with a sharp, sweet fresh mint sauce — an Australian Sunday favorite.', 'australian', 2, 30, 12, 42, 4, 'main', null, 0, array['stove', 'cast_iron']::text[], array['weeknight', 'entertaining']::text[], array['Many Australian and British cooks use malt vinegar instead; it is made from barley, so it adds gluten.', 'The chops also grill beautifully over high direct heat — same timing.']::text[], 'https://images.pexels.com/photos/10821331/pexels-photo-10821331.jpeg', 'Lamb chops with potatoes and greens being drizzled with sauce', 'furkanfdemir', 'https://www.pexels.com/@furkanfdemir/', 'https://www.pexels.com/photo/person-pouring-sauce-on-meat-10821331/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner', 'holiday', 'entertaining']::text[], array['pan_fry', 'boil']::text[], array['tangy', 'fresh']::text[], array['easter', 'date-night']::text[], null, 'traditional', 'lamb-chops-mint-sauce', 'classic', 'Refrigerate cooked chops up to 3 days and the mint sauce up to 1 week.', null, 'owned', '{}'::text[], array['lamb']::text[], array['gluten_free', 'dairy_free']::text[], array['loin chop', 'garlic', 'rosemary', 'mint leave', 'boiling water', 'wine vinegar']::text[], 'boiling water|garlic|loin chop|mint leave|rosemary|wine vinegar',
  null, null, null, null, null, null, null, null)
