  ('8c299c9f-d647-45b3-aefe-142300502b6a', 1, 'Lamb', '8 lamb loin chops, about 1¼ inches thick (2½ lb total)', 'lamb loin chops', 8, null, 'about 1¼ inches thick (2½ lb total)', false),
  ('8c299c9f-d647-45b3-aefe-142300502b6a', 2, 'Lamb', '2 tbsp olive oil', 'olive oil', 2, 'tbsp', null, false),
