  ('8c299c9f-d647-45b3-aefe-142300502b6a', 7, 'Mint sauce', '1 cup fresh mint leaves, packed, finely chopped', 'fresh mint leaves', 1, 'cup', 'packed, finely chopped', false),
  ('8c299c9f-d647-45b3-aefe-142300502b6a', 8, 'Mint sauce', '2 tbsp sugar', 'sugar', 2, 'tbsp', null, false),
