insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('8c299c9f-d647-45b3-aefe-142300502b6a', 1, 'Lamb', 'Pat the chops dry and rub with 1 tablespoon of the oil, the garlic, rosemary, salt and pepper. Leave at room temperature for 20 minutes.', 1200, null, null),
  ('8c299c9f-d647-45b3-aefe-142300502b6a', 2, 'Mint sauce', 'Stir the sugar into the boiling water until dissolved, then add the vinegar, mint and salt. Let it stand at least 20 minutes for the flavor to develop.', 1200, null, null),
  ('8c299c9f-d647-45b3-aefe-142300502b6a', 3, 'Lamb', 'Heat a large cast-iron skillet over high heat until just smoking and add the remaining oil. Stand the chops on their fat edge (use tongs to hold them together) for 1–2 minutes to render and brown the fat.', 120, null, null),
  ('8c299c9f-d647-45b3-aefe-142300502b6a', 4, 'Lamb', 'Lay the chops flat and sear 3–4 minutes per side, until well browned and 145°F in the center for medium-rare. Work in 2 batches if the pan is crowded.', 480, null, 62.8),
  ('8c299c9f-d647-45b3-aefe-142300502b6a', 5, null, 'Rest the chops 5 minutes on a warm plate, then serve with the mint sauce spooned over.', 300, null, null);

-- Kokoda (Coconut-Lime Fish)
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
