values ('223d089f-d5b4-449c-b76a-f22e593ae7d3', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'kokoda-fiji-coconut-lime-fish', 'kokoda-coconut-lime-fish-223d08', 'Kokoda (Coconut-Lime Fish)', 'Fiji''s answer to ceviche: cubes of firm white fish cured in lime juice, then folded into creamy coconut milk with chile, tomato and onion and served icy cold.', 'pacific_islands', 2, 25, 0, 100, 4, 'main', null, 75, '{}'::text[], array['summer', 'entertaining']::text[], array['Walu (Spanish mackerel) is the usual fish in Fiji; mahi-mahi, snapper or halibut work just as well.', 'Don''t leave the fish in the lime juice much longer than an hour, or it turns chalky.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['seafood_raw_bar', 'main', 'dinner', 'entertaining']::text[], array['raw', 'no_cook']::text[], array['spicy', 'tangy', 'rich']::text[], '{}'::text[], 'Fiji', 'traditional', 'kokoda', 'classic', 'Best eaten the day it''s made. Keep refrigerated and eat within 24 hours.', 'The fish is only ''cooked'' by lime juice, which doesn''t kill bacteria or parasites the way heat does. Use very fresh fish sold for eating raw that has been frozen (as most sushi-grade fish is) to kill parasites, keep it cold, and don''t serve it to anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['fish']::text[], array['fish']::text[], array['pescatarian', 'gluten_free', 'dairy_free']::text[], array['mahi-mahi fillet', 'lime juice', 'coconut cream', 'red onion', 'roma tomato', 'english cucumber', 'eye chile', 'scallion']::text[], 'coconut cream|english cucumber|eye chile|lime juice|mahi-mahi fillet|red onion|roma tomato|scallion',
  null, null, null, null, null, null, null, null)
