insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('223d089f-d5b4-449c-b76a-f22e593ae7d3', 1, null, 'Put the fish in a glass or ceramic bowl, add 1 teaspoon of the salt and the lime juice and stir so every piece is covered. Cover and refrigerate, stirring once, until the fish is opaque on the outside and still slightly translucent in the middle, 45–60 minutes.', 3600, null, null),
  ('223d089f-d5b4-449c-b76a-f22e593ae7d3', 2, null, 'Drain the fish well, keeping about 2 tablespoons of the lime juice.', null, null, null),
  ('223d089f-d5b4-449c-b76a-f22e593ae7d3', 3, null, 'Stir the coconut cream with the remaining salt, the chile and the reserved lime juice. Fold in the fish, onion, tomatoes, cucumber and scallions.', null, null, null),
  ('223d089f-d5b4-449c-b76a-f22e593ae7d3', 4, null, 'Chill 15 minutes and serve cold, in small bowls or hollowed coconut shells, with lime wedges.', 900, null, null);

