values ('f5c91ff5-e8ec-4370-bfb9-7f60b020ce0d', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'jewish-holiday-braised-brisket', 'braised-brisket-f5c91f', 'Braised Brisket', 'Ashkenazi holiday brisket braised low and slow on a bed of sweet onions with red wine and tomato, then sliced cold and reheated in its gravy for the most tender slices.', 'jewish', 3, 30, 270, 300, 8, 'main', null, 0, array['stove', 'oven', 'dutch_oven']::text[], array['make-ahead', 'entertaining', 'comfort']::text[], array['Look at the grain before you cook and cut a small notch across it, so you can still find the direction once it''s braised.', 'If you swap the broth for bouillon, check the label: some contain wheat or soy.']::text[], 'https://images.pexels.com/photos/32986967/pexels-photo-32986967.jpeg', 'Braised beef brisket topped with red onions in rich gravy', 'Hussain Hussaini', 'https://www.pexels.com/@hussain-hussaini-715213188/', 'https://www.pexels.com/photo/tender-beef-brisket-with-onions-and-gravy-32986967/', 'pexels', true, 'public', false,
