insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('f5c91ff5-e8ec-4370-bfb9-7f60b020ce0d', 1, null, 'Heat the oven to 325°F. Pat the brisket dry and rub all over with the salt, pepper and paprika.', null, 162.8, null),
  ('f5c91ff5-e8ec-4370-bfb9-7f60b020ce0d', 2, null, 'Heat the oil in a large Dutch oven or roasting pan over medium-high heat and brown the brisket well, 5 minutes per side (cut it in half to fit if needed). Set aside.', 600, null, null),
  ('f5c91ff5-e8ec-4370-bfb9-7f60b020ce0d', 3, null, 'Lower the heat to medium, add the onions and cook, stirring, until soft and golden, 15 minutes. Stir in the garlic and tomato paste for 2 minutes, then pour in the wine and scrape up the browned bits. Simmer 3 minutes.', 1200, null, null),
  ('f5c91ff5-e8ec-4370-bfb9-7f60b020ce0d', 4, null, 'Stir in the tomatoes, broth, brown sugar, bay and thyme. Lay the brisket on the onions fat side up, spoon some over the top and tuck the carrots around it.', 120, null, null),
  ('f5c91ff5-e8ec-4370-bfb9-7f60b020ce0d', 5, null, 'Cover tightly and braise until a fork slides in with no resistance, 3½–4 hours (well past the 145°F safe minimum). Baste once or twice.', 13500, 162.8, 62.8),
  ('f5c91ff5-e8ec-4370-bfb9-7f60b020ce0d', 6, null, 'For the best slices, cool the brisket in its liquid and refrigerate overnight. Lift off the solid fat, slice the cold meat thinly across the grain and lay the slices back in the gravy. Reheat covered at 325°F until hot through, 40 minutes. (To serve the same day, rest 30 minutes before slicing.)', 2400, 162.8, null);

-- Matzo Ball Soup
