values ('1c5231ba-58d2-417a-81e9-7da0d42420a1', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'matzo-ball-soup-chicken', 'matzo-ball-soup-1c5231', 'Matzo Ball Soup', 'Golden homemade chicken soup with carrots and dill, and light, fluffy matzo balls simmered until tender — the Passover and sick-day classic.', 'jewish', 2, 30, 140, 200, 8, 'main', null, 30, array['stove']::text[], array['comfort', 'make-ahead']::text[], array['Matzo meal is ground matzo, which is made from wheat flour.', 'For fluffy ''floaters'', use the seltzer and roll gently; for dense ''sinkers'', swap the seltzer for broth and roll firmly.']::text[], 'https://images.pexels.com/photos/36439924/pexels-photo-36439924.jpeg', 'Matzo ball soup in a white bowl beside a red napkin', 'Sofia Avogadri', 'https://www.pexels.com/@sofia-avogadri-2159997799/', 'https://www.pexels.com/photo/top-view-of-matzah-ball-soup-on-wood-table-36439924/', 'pexels', true, 'public', false,
  'pending_review', array['soup', 'holiday', 'main', 'dinner', 'comfort']::text[], array['stew', 'boil']::text[], array['fresh']::text[], array['passover', 'rosh-hashanah']::text[], null, 'traditional', 'matzo-ball-soup', 'classic', 'Refrigerate the soup up to 4 days and freeze up to 3 months. Keep the matzo balls in some of the broth, separately, up to 3 days.', null, 'owned', array['egg', 'gluten', 'wheat']::text[], array['chicken']::text[], array['dairy_free']::text[], array['yellow onion', 'carrot', 'celery', 'parsnip', 'dill', 'flat-leaf parsley', 'black peppercorn', 'egg', 'schmaltz', 'club soda', 'matzo meal']::text[], 'black peppercorn|carrot|celery|club soda|dill|egg|flat-leaf parsley|matzo meal|parsnip|schmaltz|yellow onion',
  null, null, null, null, null, null, null, null)
