  ('1c5231ba-58d2-417a-81e9-7da0d42420a1', 10, 'Soup', '1 tsp black peppercorns', 'black peppercorns', 1, 'tsp', null, false),
  ('1c5231ba-58d2-417a-81e9-7da0d42420a1', 11, 'Matzo balls', '4 large eggs', 'large eggs', 4, null, null, false),
