delete from public.recipe_instructions where recipe_id = '1c5231ba-58d2-417a-81e9-7da0d42420a1';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('1c5231ba-58d2-417a-81e9-7da0d42420a1', 1, 'Soup', 'Put the chicken and cold water in a large stockpot and bring to a boil, skimming off the foam. Add the onions, carrot chunks, celery, parsnip, half the dill, the parsley, salt and peppercorns. Simmer very gently, partly covered, for 1½ hours; the chicken will be far past 165°F.', 5400, null, 73.9),
  ('1c5231ba-58d2-417a-81e9-7da0d42420a1', 2, 'Matzo balls', 'Whisk the eggs, schmaltz, seltzer, salt and pepper. Stir in the matzo meal and dill until just combined, cover and refrigerate 30 minutes so the meal hydrates.', 1800, null, null),
  ('1c5231ba-58d2-417a-81e9-7da0d42420a1', 3, 'Soup', 'Strain the soup, discarding the vegetables. Pull the chicken into bite-size pieces, discarding skin and bones. Skim the fat from the broth (save it as schmaltz), return the broth to the pot with the sliced carrots and simmer until tender, 10 minutes. Season with salt.', 900, null, null),
  ('1c5231ba-58d2-417a-81e9-7da0d42420a1', 4, 'Matzo balls', 'Bring a large pot of salted water to a boil. With wet hands, roll the mixture into 16 balls about 1¼ inches across, without packing them, and drop them in. Cover, lower to a gentle simmer and cook without lifting the lid for 30–35 minutes, until they''re the same color all the way through when you cut one open (160°F).', 2100, null, 71.1),
  ('1c5231ba-58d2-417a-81e9-7da0d42420a1', 5, null, 'Lift the matzo balls into the soup with the chicken and warm through, 5 minutes. Serve 2 balls per bowl, scattered with the rest of the dill, chopped.', 300, null, null);

