values ('9555de30-0391-4514-85eb-0ad4f9dc1b51', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'potato-latkes-crispy', 'potato-latkes-9555de', 'Potato Latkes', 'Lacy, crisp-edged potato and onion pancakes fried in plenty of oil for Hanukkah and served hot with applesauce and sour cream.', 'jewish', 2, 25, 35, 60, 6, 'side', null, 0, array['stove', 'oven', 'cast_iron']::text[], array['kid-friendly', 'comfort']::text[], array['Work quickly once the potatoes are grated so they don''t turn gray, and squeeze them really dry — wet potatoes make soggy latkes.']::text[], 'https://images.pexels.com/photos/13991403/pexels-photo-13991403.jpeg', 'Stack of crispy homemade potato pancakes on a white plate', 'Reveca Chavez Perez', 'https://www.pexels.com/@reveca-chavez-perez-338103/', 'https://www.pexels.com/photo/potato-pancakes-on-a-plate-13991403/', 'pexels', true, 'public', false,
  'pending_review', array['holiday', 'side', 'comfort']::text[], '{}'::text[], '{}'::text[], array['hanukkah']::text[], null, 'traditional', 'potato-latkes', 'classic', 'Cool on a rack, then refrigerate up to 3 days or freeze in a single layer up to 2 months. Re-crisp at 400°F for 8–10 minutes.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'dairy_free']::text[], array['russet potato', 'yellow onion', 'egg', 'matzo meal']::text[], 'egg|matzo meal|russet potato|yellow onion',
  null, null, null, null, null, null, null, null)
