insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('9555de30-0391-4514-85eb-0ad4f9dc1b51', 1, 'Latkes', '2½ lb russet potatoes, peeled', 'russet potatoes', 2.5, 'lb', 'peeled', false),
  ('9555de30-0391-4514-85eb-0ad4f9dc1b51', 2, 'Latkes', '1 large yellow onion', 'large yellow onion', 1, null, null, false),
  ('9555de30-0391-4514-85eb-0ad4f9dc1b51', 3, 'Latkes', '2 large eggs, beaten', 'large eggs', 2, null, 'beaten', false),
  ('9555de30-0391-4514-85eb-0ad4f9dc1b51', 4, 'Latkes', '⅓ cup matzo meal, or all-purpose flour', 'matzo meal', 0.33, 'cup', 'or all-purpose flour', false),
  ('9555de30-0391-4514-85eb-0ad4f9dc1b51', 5, 'Latkes', '1½ tsp kosher salt, plus more for sprinkling', 'kosher salt', 1.5, 'tsp', 'plus more for sprinkling', false),
  ('9555de30-0391-4514-85eb-0ad4f9dc1b51', 6, 'Latkes', '½ tsp black pepper', 'black pepper', 0.5, 'tsp', null, false),
  ('9555de30-0391-4514-85eb-0ad4f9dc1b51', 7, 'Latkes', '1½ cups vegetable oil, for frying', 'vegetable oil', 1.5, 'cup', 'for frying', false),
  ('9555de30-0391-4514-85eb-0ad4f9dc1b51', 8, 'To serve', '1 cup applesauce', 'applesauce', 1, 'cup', null, true),
  ('9555de30-0391-4514-85eb-0ad4f9dc1b51', 9, 'To serve', '1 cup sour cream', 'sour cream', 1, 'cup', null, true);
delete from public.recipe_instructions where recipe_id = '9555de30-0391-4514-85eb-0ad4f9dc1b51';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('9555de30-0391-4514-85eb-0ad4f9dc1b51', 1, 'Latkes', 'Heat the oven to 200°F and set a wire rack on a sheet pan inside to keep the finished latkes warm.', null, 93.3, null),
  ('9555de30-0391-4514-85eb-0ad4f9dc1b51', 2, 'Latkes', 'Grate the potatoes and onion on the large holes of a box grater or with a food processor''s grating disc. Pile into a clean kitchen towel and wring out as much liquid as you can into a bowl. Let the liquid sit 5 minutes, then pour it off, keeping the white starch at the bottom.', 600, null, null),
  ('9555de30-0391-4514-85eb-0ad4f9dc1b51', 3, 'Latkes', 'Mix the potatoes and onion with the starch, eggs, matzo meal, salt and pepper.', null, null, null),
  ('9555de30-0391-4514-85eb-0ad4f9dc1b51', 4, 'Latkes', 'Heat ¼ inch of oil in a large cast-iron skillet over medium-high heat to 350°F, when a shred of potato sizzles at once. Never leave hot oil unattended and keep children away.', null, 176.7, null),
  ('9555de30-0391-4514-85eb-0ad4f9dc1b51', 5, 'Latkes', 'Drop in ¼-cup mounds, flatten to 3-inch rounds and fry, without crowding, until deep golden and crisp, 3–4 minutes per side. Drain on the rack in the oven and sprinkle with salt. Add oil between batches and let it reheat.', 1800, 176.7, null),
  ('9555de30-0391-4514-85eb-0ad4f9dc1b51', 6, null, 'Serve hot with applesauce and sour cream.', null, null, null);

-- Chilled Seafood Tower
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
  status, categories, methods, flavors, occasions, region, authenticity, dish_key, variant, storage_notes, safety_note, text_license, allergens, proteins, diet_tags, core_ingredients, fingerprint,
  attribution, reviewed_by, reviewed_at, calories_per_serving, protein_g, carbs_g, fat_g, nutrition_source)
values ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chilled-seafood-tower-platter', 'chilled-seafood-tower-7c37ce', 'Chilled Seafood Tower', 'A showpiece platter of freshly shucked oysters and clams, poached shrimp and lobster tails on crushed ice with mignonette and cocktail sauce; you''ll need an oyster knife and a tiered stand or large rimmed platters.', 'seafood', 3, 75, 20, 95, 8, 'starter', null, 0, array['stove']::text[], array['entertaining']::text[], array['Worcestershire sauce contains anchovies, so the cocktail sauce has fish in it.', 'Many fishmongers will shuck oysters and clams to order — pick them up on ice and serve within the hour.']::text[], 'https://images.pexels.com/photos/33474027/pexels-photo-33474027.jpeg', 'Chilled seafood platter with lobster, crab legs and oysters on ice', 'Deane Bayas', 'https://www.pexels.com/@dbaler/', 'https://www.pexels.com/photo/exquisite-seafood-platter-with-lobster-and-crab-33474027/', 'pexels', true, 'public', false,
  'pending_review', array['seafood_raw_bar', 'entertaining', 'appetizer', 'holiday']::text[], array['raw', 'poach']::text[], array['tangy', 'savory']::text[], array['new-year', 'dinner-party']::text[], null, null, 'seafood-tower', 'classic', 'Raw oysters and clams don''t keep once shucked — discard leftovers. Cooked shrimp and lobster that stayed on ice keep 2 days refrigerated.', 'Raw oysters and clams can carry Vibrio and norovirus. Buy from a reputable fishmonger, keep them on ice, discard any that are open before shucking, and skip them if you''re pregnant, older, have liver disease or a weakened immune system.', 'owned', array['fish', 'shellfish']::text[], array['shellfish']::text[], array['pescatarian', 'gluten_free', 'dairy_free']::text[], array['live oyster', 'littleneck clam', 'jumbo shrimp', 'lobster tail', 'lemon', 'bay leave', 'shallot', 'wine vinegar', 'ketchup', 'prepared horseradish', 'lemon juice', 'worcestershire sauce', 'sauce', 'ice']::text[], 'bay leave|ice|jumbo shrimp|ketchup|lemon|lemon juice|littleneck clam|live oyster|lobster tail|prepared horseradish|sauce|shallot|wine vinegar|worcestershire sauce',
  null, null, null, null, null, null, null, null)
