  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 1, 'Shellfish', '24 live oysters, scrubbed, kept cold', 'live oysters', 24, null, 'scrubbed, kept cold', false),
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 2, 'Shellfish', '24 live littleneck clams, scrubbed, kept cold', 'live littleneck clams', 24, null, 'scrubbed, kept cold', false),
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 3, 'Shellfish', '2 lb jumbo shrimp, shell on, deveined', 'jumbo shrimp', 2, 'lb', 'shell on, deveined', false),
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 4, 'Shellfish', '4 lobster tails, about 6 oz each', 'lobster tails', 4, null, 'about 6 oz each', false),
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 5, 'Poaching', '1 lemon, halved', 'lemon', 1, null, 'halved', false),
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 6, 'Poaching', '2 bay leaves', 'bay leaves', 2, null, null, false),
