  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 8, 'Mignonette', '1 shallot, very finely minced', 'shallot', 1, null, 'very finely minced', false),
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 9, 'Mignonette', '⅓ cup red wine vinegar', 'red wine vinegar', 0.33, 'cup', null, false),
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 10, 'Mignonette', '1 tsp black pepper, coarsely cracked', 'black pepper', 1, 'tsp', 'coarsely cracked', false),
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 11, 'Cocktail sauce', '¾ cup ketchup', 'ketchup', 0.75, 'cup', null, false),
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 12, 'Cocktail sauce', '3 tbsp prepared horseradish', 'prepared horseradish', 3, 'tbsp', null, false),
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 13, 'Cocktail sauce', '1 tbsp lemon juice', 'lemon juice', 1, 'tbsp', null, false),
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 14, 'Cocktail sauce', '1 tsp Worcestershire sauce', 'Worcestershire sauce', 1, 'tsp', null, false),
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 15, 'Cocktail sauce', '½ tsp hot sauce', 'hot sauce', 0.5, 'tsp', null, false),
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 16, 'To serve', '15 lb crushed ice', 'crushed ice', 15, 'lb', null, false),
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 17, 'To serve', '3 lemons, in wedges', 'lemons', 3, null, 'in wedges', false);
delete from public.recipe_instructions where recipe_id = '7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 1, 'Mignonette', 'Stir the shallot, vinegar and pepper together. In another bowl, mix the cocktail sauce ingredients. Chill both at least 30 minutes.', 1800, null, null),
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 2, 'Poaching', 'Bring 4 quarts of water to a boil with the lemon, bay and salt. Turn off the heat, add the shrimp and leave until pink, opaque and 145°F, 3–4 minutes. Lift into a bowl of ice water, then peel, leaving the tails on.', 240, null, 62.8),
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 3, 'Poaching', 'Bring the same water back to a boil, add the lobster tails and simmer until the shells are bright red and the meat is opaque and 145°F, 6–8 minutes. Chill in ice water, then split each tail lengthwise with kitchen shears and loosen the meat in the shell. Refrigerate the shrimp and lobster until serving.', 480, null, 62.8),
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 4, 'Shellfish', 'Discard any oysters or clams that are cracked or that are open and won''t close when tapped. Shuck them no more than 30 minutes before serving: work an oyster knife into the oyster hinge and twist, or between the clam shells opposite the hinge, cut the muscle and loosen each one in its bottom shell, keeping the juices.', null, null, null),
  ('7c37ce9b-6368-4efb-b42e-ff4bf69c8ad0', 5, null, 'Pack the tiers or platters with crushed ice. Arrange the oysters and clams in their shells, the shrimp and lobster around them, and nestle in the sauces and lemon wedges. Serve at once, topping up the ice, and clear it away after 2 hours (1 hour on a hot day).', null, null, null);

-- Steamed Snow Crab Legs with Drawn Butter
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
