values ('1fb7bf37-2e50-4e53-9361-5b824ecc2b24', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'steamed-snow-crab-legs-drawn-butter', 'steamed-snow-crab-legs-with-drawn-butter-1fb7bf', 'Steamed Snow Crab Legs with Drawn Butter', 'Sweet snow crab clusters steamed over lemon and Old Bay and served with warm clarified butter for dipping — snow crab is sold already cooked and frozen, so this just heats it gently through.', 'seafood', 2, 15, 20, 35, 4, 'main', null, 0, array['stove']::text[], array['entertaining', 'date-night']::text[], array['Short on time? Thaw the clusters in a colander under cold running water for 20–30 minutes instead of overnight.', 'Snip along the flat, pale side of each leg with kitchen shears and the meat slides out in one piece.']::text[], 'https://images.unsplash.com/photo-1767252740441-44dfe6da44ec', 'Cooked crab legs arranged on a striped cloth', 'Jason Leung', 'https://unsplash.com/@ninjason', 'https://unsplash.com/photos/cooked-crab-legs-arranged-on-a-striped-cloth-6WQouJz2Oa8', 'unsplash', true, 'public', false,
  'pending_review', array['seafood_raw_bar', 'main', 'dinner', 'holiday', 'date_night', 'entertaining']::text[], array['steam', 'boil']::text[], array['tangy']::text[], array['date-night', 'new-year']::text[], null, null, 'snow-crab-legs', 'classic', 'Refrigerate leftover crab up to 2 days and eat cold, or re-steam 2–3 minutes. The drawn butter keeps 2 weeks refrigerated.', null, 'owned', array['milk', 'shellfish']::text[], array['shellfish']::text[], array['pescatarian']::text[], array['leg cluster', 'lemon', 'bay leave', 'bay seasoning']::text[], 'bay leave|bay seasoning|leg cluster|lemon',
  null, null, null, null, null, null, null, null)
