insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('1fb7bf37-2e50-4e53-9361-5b824ecc2b24', 1, 'Crab', '4 lb cooked snow crab leg clusters, thawed overnight in the fridge', 'cooked snow crab leg clusters', 4, 'lb', 'thawed overnight in the fridge', false),
  ('1fb7bf37-2e50-4e53-9361-5b824ecc2b24', 2, 'Crab', '1 lemon, halved, plus wedges to serve', 'lemon', 1, null, 'halved, plus wedges to serve', false),
  ('1fb7bf37-2e50-4e53-9361-5b824ecc2b24', 3, 'Crab', '2 bay leaves', 'bay leaves', 2, null, null, false),
  ('1fb7bf37-2e50-4e53-9361-5b824ecc2b24', 4, 'Crab', '1 tbsp Old Bay seasoning, plus more to serve', 'Old Bay seasoning', 1, 'tbsp', 'plus more to serve', false),
  ('1fb7bf37-2e50-4e53-9361-5b824ecc2b24', 5, 'Drawn butter', '1 cup unsalted butter, 2 sticks, cut into pieces', 'unsalted butter', 1, 'cup', '2 sticks, cut into pieces', false),
  ('1fb7bf37-2e50-4e53-9361-5b824ecc2b24', 6, 'Drawn butter', 'kosher salt', 'kosher salt', null, 'pinch', null, false),
  ('1fb7bf37-2e50-4e53-9361-5b824ecc2b24', 7, 'To serve', '2 tbsp fresh flat-leaf parsley, chopped', 'fresh flat-leaf parsley', 2, 'tbsp', 'chopped', true);
delete from public.recipe_instructions where recipe_id = '1fb7bf37-2e50-4e53-9361-5b824ecc2b24';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('1fb7bf37-2e50-4e53-9361-5b824ecc2b24', 1, 'Drawn butter', 'Melt the butter over low heat without stirring until it foams and the milky solids sink, 8–10 minutes. Skim off the foam, then carefully pour the clear yellow butter into warm ramekins, leaving the milky layer behind. Add the salt.', 600, null, null),
  ('1fb7bf37-2e50-4e53-9361-5b824ecc2b24', 2, 'Crab', 'Pour 1 inch of water into a large pot fitted with a steamer basket. Squeeze in the lemon halves and drop them in with the bay leaves and Old Bay, and bring to a boil.', 300, null, null),
  ('1fb7bf37-2e50-4e53-9361-5b824ecc2b24', 3, 'Crab', 'Add the crab clusters, cover and steam until hot all the way through and steaming at the joints, 5–7 minutes (145°F in the thickest part of a leg). Work in 2 batches if they don''t fit loosely.', 420, null, 62.8),
  ('1fb7bf37-2e50-4e53-9361-5b824ecc2b24', 4, null, 'Pile the crab on a platter, sprinkle with parsley and a little Old Bay and serve with the drawn butter, lemon wedges and kitchen shears for snipping open the shells.', null, null, null);

-- Scallop Crudo
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
