values ('94996255-dff4-426a-aef6-f568e9689de7', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'scallop-crudo-citrus-chile', 'scallop-crudo-949962', 'Scallop Crudo', 'Paper-thin coins of raw sea scallop dressed at the last minute with good olive oil, orange and lemon, sliced chile, chives and flaky salt.', 'seafood', 3, 25, 0, 40, 4, 'starter', null, 15, '{}'::text[], array['entertaining']::text[], array['Avoid ''wet-packed'' scallops treated with phosphates — they taste soapy raw and won''t slice cleanly.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['seafood_raw_bar', 'appetizer', 'holiday', 'entertaining']::text[], array['raw', 'no_cook']::text[], array['spicy', 'tangy', 'fresh']::text[], array['date-night', 'dinner-party']::text[], null, null, 'scallop-crudo', 'classic', 'Don''t store once dressed. Keep undressed raw scallops on ice in the fridge and serve within 24 hours of purchase.', 'Raw scallops can carry bacteria and viruses. Buy dry-packed sea scallops your fishmonger says are fit to eat raw, keep them on ice, serve within a day of purchase, and skip it if you''re pregnant, older, have liver disease or a weakened immune system.', 'owned', array['shellfish']::text[], array['shellfish']::text[], array['pescatarian', 'gluten_free', 'dairy_free']::text[], array['dry-packed scallop', 'navel orange', 'lemon', 'fresno chile', 'chive']::text[], 'chive|dry-packed scallop|fresno chile|lemon|navel orange',
  null, null, null, null, null, null, null, null)
