delete from public.recipe_ingredients where recipe_id = '94996255-dff4-426a-aef6-f568e9689de7';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('94996255-dff4-426a-aef6-f568e9689de7', 1, null, '12 oz dry-packed sea scallops, sold for eating raw, very cold', 'dry-packed sea scallops', 12, 'oz', 'sold for eating raw, very cold', false),
  ('94996255-dff4-426a-aef6-f568e9689de7', 2, null, '1 navel orange', 'navel orange', 1, null, null, false),
  ('94996255-dff4-426a-aef6-f568e9689de7', 3, null, '1 lemon', 'lemon', 1, null, null, false),
  ('94996255-dff4-426a-aef6-f568e9689de7', 4, null, '2 tbsp extra-virgin olive oil', 'extra-virgin olive oil', 2, 'tbsp', null, false),
  ('94996255-dff4-426a-aef6-f568e9689de7', 5, null, '1 Fresno chile, sliced paper-thin', 'Fresno chile', 1, null, 'sliced paper-thin', false),
  ('94996255-dff4-426a-aef6-f568e9689de7', 6, null, '1 tbsp fresh chives, finely sliced', 'fresh chives', 1, 'tbsp', 'finely sliced', false),
  ('94996255-dff4-426a-aef6-f568e9689de7', 7, null, '½ tsp flaky sea salt', 'flaky sea salt', 0.5, 'tsp', null, false),
  ('94996255-dff4-426a-aef6-f568e9689de7', 8, null, 'black pepper, freshly ground', 'black pepper', null, 'pinch', 'freshly ground', false);
delete from public.recipe_instructions where recipe_id = '94996255-dff4-426a-aef6-f568e9689de7';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('94996255-dff4-426a-aef6-f568e9689de7', 1, null, 'Put four small plates in the freezer. Pull off the small tough side muscle from each scallop, then lay the scallops on a plate and freeze 15 minutes to firm up for slicing.', 900, null, null),
  ('94996255-dff4-426a-aef6-f568e9689de7', 2, null, 'Cut the peel and pith off the orange and cut out the segments between the membranes; halve the segments. Finely grate the lemon zest, then squeeze 1 tablespoon of lemon juice and 1 tablespoon of orange juice from the leftover orange membranes.', null, null, null),
  ('94996255-dff4-426a-aef6-f568e9689de7', 3, null, 'With your sharpest knife, slice each scallop across into 3–4 thin coins. Fan them out on the cold plates.', null, null, null),
  ('94996255-dff4-426a-aef6-f568e9689de7', 4, null, 'Right before serving, spoon the citrus juices and olive oil over the scallops, then scatter with the orange segments, lemon zest, chile, chives, flaky salt and pepper. Serve at once, before the citrus starts to turn the scallops opaque.', null, null, null);

