values ('0d7069d0-6f91-45c0-9d5d-fc0721d3d76d', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'moules-marinieres-white-wine', 'moules-marinieres-0d7069', 'Moules Marinières', 'Mussels steamed open in white wine with shallots, garlic, thyme and butter, finished with parsley — the French coastal bistro classic, with crusty bread for the broth.', 'seafood', 2, 20, 12, 32, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'entertaining']::text[], array['Farmed mussels are usually clean and nearly beardless — a quick rinse is often all they need.', 'For moules-frites, serve with fries instead of bread.']::text[], 'https://images.pexels.com/photos/30649002/pexels-photo-30649002.jpeg', 'Pot of steamed mussels with fresh herbs and lemon wedges', 'Electra Studio', 'https://www.pexels.com/@electra-studio-32883186/', 'https://www.pexels.com/photo/steamed-mussels-with-lemon-and-herbs-30649002/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner', 'holiday', 'entertaining']::text[], array['boil']::text[], '{}'::text[], array['date-night']::text[], null, 'traditional', 'moules-marinieres', 'classic', 'Best eaten straight away. Refrigerate shelled leftover mussels in their broth up to 1 day.', null, 'owned', array['gluten', 'milk', 'shellfish', 'wheat']::text[], array['shellfish']::text[], array['pescatarian']::text[], array['live mussel', 'shallot', 'garlic', 'white wine', 'thyme', 'bay leaf', 'flat-leaf parsley', 'crusty baguette']::text[], 'bay leaf|crusty baguette|flat-leaf parsley|garlic|live mussel|shallot|thyme|white wine',
  null, null, null, null, null, null, null, null)
