insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('0d7069d0-6f91-45c0-9d5d-fc0721d3d76d', 1, null, '4 lb live mussels', 'live mussels', 4, 'lb', null, false),
  ('0d7069d0-6f91-45c0-9d5d-fc0721d3d76d', 2, null, '3 tbsp unsalted butter, divided', 'unsalted butter', 3, 'tbsp', 'divided', false),
  ('0d7069d0-6f91-45c0-9d5d-fc0721d3d76d', 3, null, '2 shallots, finely chopped', 'shallots', 2, null, 'finely chopped', false),
  ('0d7069d0-6f91-45c0-9d5d-fc0721d3d76d', 4, null, '3 cloves garlic, finely chopped', 'garlic', 3, 'clove', 'finely chopped', false),
  ('0d7069d0-6f91-45c0-9d5d-fc0721d3d76d', 5, null, '1 cup dry white wine, such as Muscadet', 'dry white wine', 1, 'cup', 'such as Muscadet', false),
  ('0d7069d0-6f91-45c0-9d5d-fc0721d3d76d', 6, null, '4 sprigs fresh thyme', 'fresh thyme', 4, 'sprig', null, false),
  ('0d7069d0-6f91-45c0-9d5d-fc0721d3d76d', 7, null, '1 bay leaf', 'bay leaf', 1, null, null, false),
