values ('fc5b2ec0-45d6-4bec-96a9-076a6cdc0117', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'grilled-whole-branzino-lemon-herb', 'grilled-whole-branzino-fc5b2e', 'Grilled Whole Branzino', 'Whole Mediterranean sea bass stuffed with lemon, garlic and herbs, grilled until the skin is crisp and charred, and finished with a lemon-oregano olive oil dressing.', 'seafood', 3, 20, 15, 35, 4, 'main', null, 0, array['grill']::text[], array['entertaining', 'summer']::text[], array['A hinged fish basket makes turning foolproof if you''re nervous about sticking.', 'Red snapper, sea bream or small striped bass of the same size cook the same way.']::text[], 'https://images.pexels.com/photos/28446446/pexels-photo-28446446.jpeg', 'Whole grilled fish with tomatoes and parsley on a platter', 'Alexander Afanasyev', 'https://www.pexels.com/@alexanderafan/', 'https://www.pexels.com/photo/grilled-whole-fish-with-vegetables-on-ceramic-platter-28446446/', 'pexels', true, 'public', false,
  'pending_review', array['grilling', 'main', 'dinner', 'holiday', 'entertaining']::text[], array['grill']::text[], array['tangy']::text[], array['july-4th', 'dinner-party']::text[], null, null, 'grilled-whole-branzino', 'classic', 'Best hot off the grill. Refrigerate leftover flaked fish up to 2 days and eat cold in a salad.', null, 'owned', array['fish']::text[], array['fish']::text[], array['pescatarian', 'gluten_free', 'dairy_free']::text[], array['branzino', 'lemon', 'garlic', 'thyme oregano', 'flat-leaf parsley', 'lemon juice', 'dried oregano']::text[], 'branzino|dried oregano|flat-leaf parsley|garlic|lemon|lemon juice|thyme oregano',
  null, null, null, null, null, null, null, null)
