  ('fc5b2ec0-45d6-4bec-96a9-076a6cdc0117', 1, 'Fish', '2 whole branzino, 1¼–1½ lb each, scaled and gutted', 'whole branzino', 2, null, '1¼–1½ lb each, scaled and gutted', false),
  ('fc5b2ec0-45d6-4bec-96a9-076a6cdc0117', 2, 'Fish', '2 tbsp olive oil, plus more for the grates', 'olive oil', 2, 'tbsp', 'plus more for the grates', false),
