  ('fc5b2ec0-45d6-4bec-96a9-076a6cdc0117', 4, 'Fish', '½ tsp black pepper', 'black pepper', 0.5, 'tsp', null, false),
  ('fc5b2ec0-45d6-4bec-96a9-076a6cdc0117', 5, 'Fish', '1 lemon, thinly sliced', 'lemon', 1, null, 'thinly sliced', false),
  ('fc5b2ec0-45d6-4bec-96a9-076a6cdc0117', 6, 'Fish', '2 cloves garlic, thinly sliced', 'garlic', 2, 'clove', 'thinly sliced', false),
  ('fc5b2ec0-45d6-4bec-96a9-076a6cdc0117', 7, 'Fish', '4 sprigs fresh thyme or oregano', 'fresh thyme or oregano', 4, 'sprig', null, false),
  ('fc5b2ec0-45d6-4bec-96a9-076a6cdc0117', 8, 'Fish', '4 sprigs fresh flat-leaf parsley', 'fresh flat-leaf parsley', 4, 'sprig', null, false),
  ('fc5b2ec0-45d6-4bec-96a9-076a6cdc0117', 9, 'Dressing', '¼ cup extra-virgin olive oil', 'extra-virgin olive oil', 0.25, 'cup', null, false),
