insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('fc5b2ec0-45d6-4bec-96a9-076a6cdc0117', 1, 'Fish', 'Pat the fish very dry inside and out. Cut 3 shallow slashes on each side, down to the bone. Season inside and out with the salt and pepper, stuff the cavities with the lemon, garlic and herbs and rub the outside with the oil. Rest 15 minutes.', 900, null, null),
  ('fc5b2ec0-45d6-4bec-96a9-076a6cdc0117', 2, 'Fish', 'Heat a grill to medium-high (about 450°F). Scrape the grates very clean, then oil them well with a wad of oiled paper towel held in tongs.', null, 232.2, null),
  ('fc5b2ec0-45d6-4bec-96a9-076a6cdc0117', 3, 'Fish', 'Lay the fish on the grates diagonally and leave them alone until the skin is charred and releases easily, 6–8 minutes. Turn carefully with two wide spatulas.', 420, 232.2, null),
  ('fc5b2ec0-45d6-4bec-96a9-076a6cdc0117', 4, 'Fish', 'Grill the second side until the flesh near the backbone is opaque, flakes easily and reads 145°F at the thickest point, 5–7 minutes.', 360, 232.2, 62.8),
  ('fc5b2ec0-45d6-4bec-96a9-076a6cdc0117', 5, 'Dressing', 'Whisk the olive oil, lemon juice, oregano, parsley and salt.', null, null, null),
  ('fc5b2ec0-45d6-4bec-96a9-076a6cdc0117', 6, null, 'To serve, run a knife along the backbone, lift off the top fillet, lift out the skeleton and spoon the dressing over both fillets.', null, null, null);

