values ('af0cead2-aa3a-49ec-9668-10f7c13e950f', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-parmesan-baked-finish', 'chicken-parmesan-af0cea', 'Chicken Parmesan', 'Crisp breaded chicken cutlets topped with marinara and melted mozzarella — the Italian-American red-sauce favorite, shallow-fried and finished in the oven instead of fried in a deep pan of oil.', 'italian', 2, 20, 25, 45, 4, 'main', null, 0, array['stove', 'oven']::text[], array['comfort', 'kid-friendly', 'weeknight']::text[], array['Pounding the cutlets to an even ½ inch is the secret to chicken that''s cooked through by the time the crust is golden.', 'Chicken tenderloins work too — skip the pounding and fry 1–2 minutes per side.']::text[], 'https://images.pexels.com/photos/13443376/pexels-photo-13443376.jpeg', 'Breaded chicken cutlet topped with tomato sauce and melted cheese, served with spaghetti', 'Reynaldo Yodia', 'https://www.pexels.com/@reynaldoyodia/', 'https://www.pexels.com/photo/chicken-parmigiana-13443376/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner']::text[], array['bake']::text[], array['fresh', 'savory']::text[], '{}'::text[], null, 'adapted', 'chicken-parmesan', 'classic', 'Refrigerate up to 3 days. Reheat on a rack in a 375°F oven for 12–15 minutes to keep the crust crisp.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], array['chicken']::text[], '{}'::text[], array['egg', 'panko breadcrumb', 'parmesan cheese', 'dried oregano', 'marinara sauce', 'mozzarella cheese', 'basil']::text[], 'basil|dried oregano|egg|marinara sauce|mozzarella cheese|panko breadcrumb|parmesan cheese',
  null, null, null, null, null, null, null, null)
