  ('af0cead2-aa3a-49ec-9668-10f7c13e950f', 5, 'Chicken', '2 large eggs, beaten with 1 tbsp water', 'large eggs', 2, null, 'beaten with 1 tbsp water', false),
  ('af0cead2-aa3a-49ec-9668-10f7c13e950f', 6, 'Chicken', '1¼ cups panko breadcrumbs, or Italian-style breadcrumbs', 'panko breadcrumbs', 1.25, 'cup', 'or Italian-style breadcrumbs', false),
  ('af0cead2-aa3a-49ec-9668-10f7c13e950f', 7, 'Chicken', '½ cup grated Parmesan cheese, divided', 'grated Parmesan cheese', 0.5, 'cup', 'divided', false),
  ('af0cead2-aa3a-49ec-9668-10f7c13e950f', 8, 'Chicken', '1 tsp dried oregano', 'dried oregano', 1, 'tsp', null, false),
  ('af0cead2-aa3a-49ec-9668-10f7c13e950f', 9, 'Chicken', '½ cup vegetable oil, for shallow-frying', 'vegetable oil', 0.5, 'cup', 'for shallow-frying', false),
  ('af0cead2-aa3a-49ec-9668-10f7c13e950f', 10, 'Topping', '1½ cups marinara sauce, warmed', 'marinara sauce', 1.5, 'cup', 'warmed', false),
  ('af0cead2-aa3a-49ec-9668-10f7c13e950f', 11, 'Topping', '1½ cups shredded low-moisture mozzarella cheese', 'shredded low-moisture mozzarella cheese', 1.5, 'cup', null, false),
  ('af0cead2-aa3a-49ec-9668-10f7c13e950f', 12, 'Topping', '6 leaf fresh basil, torn', 'fresh basil', 6, 'leaf', 'torn', false),
  ('af0cead2-aa3a-49ec-9668-10f7c13e950f', 13, 'Topping', '12 oz spaghetti, cooked, to serve', 'spaghetti', 12, 'oz', 'cooked, to serve', true);
delete from public.recipe_instructions where recipe_id = 'af0cead2-aa3a-49ec-9668-10f7c13e950f';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('af0cead2-aa3a-49ec-9668-10f7c13e950f', 1, 'Chicken', 'Heat the oven to 425°F and set a wire rack on a sheet pan. Season the cutlets on both sides with the salt and pepper.', null, 218.3, null),
  ('af0cead2-aa3a-49ec-9668-10f7c13e950f', 2, 'Chicken', 'Set up three shallow dishes: flour; beaten egg; and the breadcrumbs mixed with ¼ cup of the Parmesan and the oregano. Coat each cutlet in flour, shake off the extra, dip in egg, then press firmly into the crumbs on both sides.', 480, null, null),
  ('af0cead2-aa3a-49ec-9668-10f7c13e950f', 3, 'Chicken', 'Heat the oil in a large skillet over medium-high heat until it shimmers (about 350°F). Fry the cutlets two at a time until deep golden, 2–3 minutes per side. Move them to the rack; they''ll finish cooking in the oven.', 600, 176.7, null),
  ('af0cead2-aa3a-49ec-9668-10f7c13e950f', 4, 'Topping', 'Spoon about ⅓ cup marinara down the middle of each cutlet, leaving the edges bare so they stay crisp. Top with the mozzarella and the remaining Parmesan.', 120, null, null),
  ('af0cead2-aa3a-49ec-9668-10f7c13e950f', 5, 'Topping', 'Bake until the cheese is melted and spotted brown and the chicken reaches 165°F in the thickest part, 10–12 minutes.', 660, 218.3, 73.9),
  ('af0cead2-aa3a-49ec-9668-10f7c13e950f', 6, 'Topping', 'Scatter with basil and serve with spaghetti tossed in the remaining marinara, if you like.', 60, null, null);

-- Chicken Alfredo
