values ('e0eff40d-5c81-43fa-adc7-41f374a041db', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'creamy-chicken-alfredo', 'chicken-alfredo-e0eff4', 'Chicken Alfredo', 'Fettuccine in a silky garlic-butter, cream and Parmesan sauce with sliced pan-seared chicken; the Italian-American version adds cream and chicken to Rome''s original butter-and-cheese pasta.', 'italian', 1, 10, 25, 35, 4, 'main', null, 0, array['stove']::text[], array['comfort', 'kid-friendly', 'weeknight']::text[], array['Grate the Parmesan yourself — pre-shredded cheese is coated to stop it clumping and can make the sauce grainy.']::text[], 'https://images.pexels.com/photos/37118296/pexels-photo-37118296.jpeg', 'Creamy chicken Alfredo pasta topped with grated Parmesan and parsley', 'Kemal Can', 'https://www.pexels.com/@kemalcanfilm/', 'https://www.pexels.com/photo/delicious-chicken-alfredo-pasta-dish-37118296/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'quick', 'main', 'dinner']::text[], array['stew', 'boil']::text[], array['rich', 'fresh', 'savory']::text[], '{}'::text[], null, 'adapted', 'chicken-alfredo', 'classic', 'Best fresh. Refrigerate up to 2 days; reheat gently with a splash of milk, stirring, as the sauce thickens when cold.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], array['chicken']::text[], '{}'::text[], array['fettuccine', 'garlic', 'heavy cream', 'parmesan cheese', 'parsley']::text[], 'fettuccine|garlic|heavy cream|parmesan cheese|parsley',
  null, null, null, null, null, null, null, null)
