values ('10bfacce-0b4c-434c-a5b4-81a615743b7d', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'garlic-butter-shrimp-scampi-linguine', 'shrimp-scampi-10bfac', 'Shrimp Scampi', 'Juicy shrimp and linguine tossed in garlic, butter, white wine and lemon — the Italian-American restaurant classic, ready in about half an hour.', 'italian', 1, 15, 20, 35, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'date-night']::text[], array['Frozen shrimp are fine: thaw them overnight in the fridge or in a bowl of cold water for 15 minutes, then dry them well so they sear instead of steam.']::text[], 'https://images.pexels.com/photos/4175148/pexels-photo-4175148.jpeg', 'Garlic butter shrimp served on a blue plate', 'Isaac Quesada', 'https://www.pexels.com/@isaacquesada/', 'https://www.pexels.com/photo/garlic-and-buttered-shrimp-4175148/', 'pexels', true, 'public', false,
  'pending_review', array['quick', 'main', 'dinner', 'holiday', 'date_night']::text[], array['stew', 'pan_fry', 'boil']::text[], array['spicy', 'tangy', 'fresh']::text[], array['date-night']::text[], null, 'adapted', 'shrimp-scampi', 'classic', 'Best eaten right away. Refrigerate up to 2 days; reheat gently so the shrimp don''t toughen.', null, 'owned', array['gluten', 'milk', 'shellfish', 'wheat']::text[], array['shellfish']::text[], '{}'::text[], array['linguine', 'shrimp', 'garlic', 'pepper flake', 'white wine', 'lemon', 'parsley']::text[], 'garlic|lemon|linguine|parsley|pepper flake|shrimp|white wine',
  null, null, null, null, null, null, null, null)
