  ('10bfacce-0b4c-434c-a5b4-81a615743b7d', 2, null, '1½ lb large shrimp, peeled and deveined, patted dry', 'large shrimp', 1.5, 'lb', 'peeled and deveined, patted dry', false),
  ('10bfacce-0b4c-434c-a5b4-81a615743b7d', 3, null, '1 tsp kosher salt, plus more for the pasta water', 'kosher salt', 1, 'tsp', 'plus more for the pasta water', false),
  ('10bfacce-0b4c-434c-a5b4-81a615743b7d', 4, null, '¼ tsp black pepper', 'black pepper', 0.25, 'tsp', null, false),
  ('10bfacce-0b4c-434c-a5b4-81a615743b7d', 5, null, '3 tbsp olive oil, divided', 'olive oil', 3, 'tbsp', 'divided', false),
