insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('10bfacce-0b4c-434c-a5b4-81a615743b7d', 1, null, 'Bring a large pot of well-salted water to a boil and cook the linguine until just tender. Scoop out 1 cup of the pasta water, then drain.', 600, null, null),
  ('10bfacce-0b4c-434c-a5b4-81a615743b7d', 2, null, 'Meanwhile, season the shrimp with the salt and pepper. Heat 2 tablespoons of the oil in a large skillet over medium-high heat and sear the shrimp in a single layer for 1 minute per side, until just turning pink. Move to a plate — they''ll finish in the sauce.', 180, null, null),
  ('10bfacce-0b4c-434c-a5b4-81a615743b7d', 3, null, 'Lower the heat to medium-low, add the remaining oil, the garlic and pepper flakes and cook, stirring, until the garlic is pale gold, 1–2 minutes.', 120, null, null),
  ('10bfacce-0b4c-434c-a5b4-81a615743b7d', 4, null, 'Pour in the wine and simmer until reduced by half, about 2 minutes. Swirl in the butter until creamy, then add the lemon zest and juice.', 180, null, null),
  ('10bfacce-0b4c-434c-a5b4-81a615743b7d', 5, null, 'Return the shrimp and any juices and cook until pink, opaque all the way through and 145°F, about 1 minute.', 60, null, 62.8),
  ('10bfacce-0b4c-434c-a5b4-81a615743b7d', 6, null, 'Add the linguine, parsley and a splash of pasta water and toss until glossy. Taste for salt and serve.', 60, null, null);

