values ('78693f1f-12a5-4cb0-baad-4a39203c593f', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'spaghetti-and-baked-meatballs', 'spaghetti-and-meatballs-78693f', 'Spaghetti and Meatballs', 'Tender beef-and-pork meatballs browned in the oven, then simmered in a quick garlicky tomato sauce and piled on spaghetti — the Italian-American Sunday dinner, easy enough for a weeknight.', 'italian', 2, 25, 45, 70, 6, 'main', null, 0, array['stove', 'oven', 'dutch_oven']::text[], array['comfort', 'kid-friendly', 'make-ahead', 'freezer-friendly']::text[], array['All beef works if you prefer — use 85% lean so the meatballs stay juicy.']::text[], 'https://images.pexels.com/photos/12720645/pexels-photo-12720645.jpeg', 'Spaghetti and meatballs in tomato sauce with basil on a white plate', 'Hexuye Ye', 'https://www.pexels.com/@hexuye-ye-81431575/', 'https://www.pexels.com/photo/a-spaghetti-with-meatballs-on-a-ceramic-plate-12720645/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner']::text[], array['stew', 'pan_fry', 'bake', 'boil']::text[], array['spicy', 'fresh', 'savory']::text[], '{}'::text[], null, 'adapted', 'spaghetti-and-meatballs', 'classic', 'Refrigerate meatballs in sauce up to 4 days, or freeze up to 3 months. Reheat covered over low heat; cook pasta fresh.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], array['beef', 'pork']::text[], '{}'::text[], array['panko breadcrumb', 'milk', 'ground beef', 'ground pork', 'egg', 'parmesan cheese', 'garlic', 'parsley', 'yellow onion', 'tomato', 'basil', 'spaghetti']::text[], 'basil|egg|garlic|ground beef|ground pork|milk|panko breadcrumb|parmesan cheese|parsley|spaghetti|tomato|yellow onion',
