delete from public.recipe_instructions where recipe_id = '78693f1f-12a5-4cb0-baad-4a39203c593f';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('78693f1f-12a5-4cb0-baad-4a39203c593f', 1, 'Meatballs', 'Heat the oven to 425°F and oil a rimmed sheet pan. In a large bowl, soak the panko in the milk until soft, about 5 minutes.', 300, 218.3, null),
  ('78693f1f-12a5-4cb0-baad-4a39203c593f', 2, 'Meatballs', 'Add the beef, pork, egg, Parmesan, garlic, parsley, salt and pepper and mix gently with your hands just until combined — overmixing makes them tough. Roll into about 24 balls (1½ inches) and set on the pan.', 600, null, null),
  ('78693f1f-12a5-4cb0-baad-4a39203c593f', 3, 'Meatballs', 'Bake until browned on the outside, about 15 minutes. They don''t need to be cooked through yet.', 900, 218.3, null),
  ('78693f1f-12a5-4cb0-baad-4a39203c593f', 4, 'Sauce', 'Meanwhile, heat the oil in a Dutch oven over medium heat. Cook the onion until soft, about 6 minutes, then add the garlic and pepper flakes for 1 minute. Add the tomatoes, salt and sugar if using, and simmer 10 minutes.', 1020, null, null),
  ('78693f1f-12a5-4cb0-baad-4a39203c593f', 5, 'Sauce', 'Slide the meatballs and their juices into the sauce, cover and simmer gently, stirring once or twice, until the meatballs are cooked through and 160°F in the center, 15–20 minutes. Stir in the basil.', 1080, null, 71.1),
  ('78693f1f-12a5-4cb0-baad-4a39203c593f', 6, 'Pasta', 'While the meatballs simmer, cook the spaghetti in well-salted boiling water until just tender. Drain, toss with a couple of ladles of sauce, and serve topped with meatballs, more sauce and Parmesan.', 660, null, null);

-- Chicken Marsala
