values ('6276b540-59bc-4d0b-8ec0-7c66a6ee6f4e', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-marsala-mushroom-pan-sauce', 'chicken-marsala-6276b5', 'Chicken Marsala', 'Golden chicken cutlets in a glossy mushroom and Marsala wine pan sauce — an Italian-American restaurant dish built on a Sicilian fortified wine, made in one skillet.', 'italian', 2, 15, 25, 40, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'date-night', 'entertaining']::text[], array['Buy dry Marsala from the wine aisle — sweet Marsala makes the sauce sugary and "cooking Marsala" is heavily salted.', 'Good with mashed potatoes, buttered noodles or polenta to soak up the sauce.']::text[], 'https://images.unsplash.com/photo-1788462612914-44793f2980f2', 'Chicken breast in mushroom sauce with mashed potatoes and steamed vegetables on a black plate', 'gabbiistudios', 'https://unsplash.com/@gabrielonodegba', 'https://unsplash.com/photos/chicken-dinner-with-mushroom-sauce-UdO-JP67I-4', 'unsplash', true, 'public', false,
  'pending_review', array['quick', 'main', 'dinner', 'holiday', 'date_night', 'entertaining']::text[], array['stew', 'boil']::text[], array['rich', 'fresh']::text[], array['date-night', 'dinner-party']::text[], null, 'adapted', 'chicken-marsala', 'classic', 'Refrigerate up to 3 days. Reheat gently, covered, with a splash of stock.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], array['chicken']::text[], '{}'::text[], array['cremini mushroom', 'shallot', 'garlic', 'marsala wine', 'chicken stock', 'parsley']::text[], 'chicken stock|cremini mushroom|garlic|marsala wine|parsley|shallot',
  null, null, null, null, null, null, null, null)
