insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('6276b540-59bc-4d0b-8ec0-7c66a6ee6f4e', 1, null, 'Season the cutlets with ¾ teaspoon of the salt and the pepper, then coat in flour and shake off the excess.', 180, null, null),
  ('6276b540-59bc-4d0b-8ec0-7c66a6ee6f4e', 2, null, 'Heat the oil and 1 tablespoon of the butter in a large skillet over medium-high heat. Cook the cutlets until golden and 165°F in the thickest part, 3–4 minutes per side. Move to a plate.', 480, null, 73.9),
  ('6276b540-59bc-4d0b-8ec0-7c66a6ee6f4e', 3, null, 'Add 1 tablespoon butter and the mushrooms with the remaining salt. Cook without stirring for 2 minutes, then stir until browned and their liquid has cooked off, about 6 minutes total. Add the shallot and garlic for 1 minute.', 420, null, null),
  ('6276b540-59bc-4d0b-8ec0-7c66a6ee6f4e', 4, null, 'Pour in the Marsala, scraping up the browned bits, and boil until reduced by half, about 3 minutes. Add the stock and simmer until slightly syrupy, 3–4 minutes. Stir in the cream if using.', 420, null, null),
  ('6276b540-59bc-4d0b-8ec0-7c66a6ee6f4e', 5, null, 'Turn the heat to low, swirl in the remaining butter, then return the chicken and its juices for 1 minute, spooning the sauce over. Sprinkle with parsley and serve.', 60, null, null);

