values ('f760ee6d-32cc-4286-a942-9ed219759f81', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-piccata-lemon-caper', 'chicken-piccata-f760ee', 'Chicken Piccata', 'Thin, golden chicken cutlets in a bright lemon, butter and caper pan sauce — the Italian-American take on veal piccata, on the table in 35 minutes.', 'italian', 2, 15, 20, 35, 4, 'main', null, 0, array['stove']::text[], array['weeknight']::text[], array['Taste the sauce before adding any salt — capers and stock are already salty.']::text[], null, null, null, null, null, null, null, 'public', false,
