values ('38efb0d3-2b21-4fea-a42e-d24e291fb839', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'vegetable-lasagna-ricotta-spinach', 'vegetable-lasagna-38efb0', 'Vegetable Lasagna', 'Layers of no-boil noodles, marinara, herbed ricotta, melted mozzarella and sautéed zucchini, peppers, mushrooms and spinach; this Italian-American bake uses jarred sauce and no-boil noodles to save time.', 'italian', 2, 30, 60, 110, 8, 'main', null, 20, array['stove', 'oven']::text[], array['make-ahead', 'freezer-friendly', 'comfort', 'potluck']::text[], array['Traditional Parmigiano-Reggiano is made with animal rennet. For a strictly vegetarian lasagna, choose a Parmesan-style cheese labeled as made with vegetarian or microbial rennet.', 'Cooking the water out of the vegetables first keeps the lasagna from turning soupy.']::text[], 'https://images.pexels.com/photos/32125999/pexels-photo-32125999.jpeg', 'Slice of vegetarian lasagna topped with fresh greens', 'Christine Cleireny', 'https://www.pexels.com/@cleireny/', 'https://www.pexels.com/photo/gourmet-vegetarian-lasagna-with-fresh-greens-32125999/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'baking', 'main', 'dinner', 'holiday']::text[], array['pan_fry', 'bake']::text[], array['fresh', 'savory']::text[], array['potluck']::text[], null, 'adapted', 'vegetable-lasagna', 'classic', 'Assemble up to 1 day ahead and refrigerate, adding 10 minutes to the covered bake. Leftovers keep 4 days refrigerated; freeze portions up to 3 months.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['yellow onion', 'zucchini', 'bell pepper', 'cremini mushroom', 'garlic', 'dried oregano', 'spinach', 'ricotta cheese', 'egg', 'parmesan cheese', 'basil', 'marinara sauce', 'lasagna noodle', 'mozzarella cheese']::text[], 'basil|bell pepper|cremini mushroom|dried oregano|egg|garlic|lasagna noodle|marinara sauce|mozzarella cheese|parmesan cheese|ricotta cheese|spinach|yellow onion|zucchini',
  null, null, null, null, null, null, null, null)
