insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('38efb0d3-2b21-4fea-a42e-d24e291fb839', 1, 'Vegetables', 'Heat the oven to 375°F. Heat the oil in a large skillet over medium-high heat and cook the onion, zucchini, bell pepper and mushrooms, stirring now and then, until browned and any liquid has cooked off, 10–12 minutes.', 720, 190.6, null),
  ('38efb0d3-2b21-4fea-a42e-d24e291fb839', 2, 'Vegetables', 'Add the garlic and oregano for 1 minute, then the spinach and salt, stirring until wilted, about 2 minutes. Set aside.', 180, null, null),
  ('38efb0d3-2b21-4fea-a42e-d24e291fb839', 3, 'Ricotta', 'Stir the ricotta, egg, ½ cup of the Parmesan, the basil, salt and pepper together in a bowl.', null, null, null),
  ('38efb0d3-2b21-4fea-a42e-d24e291fb839', 4, 'Assembly', 'Spread 1 cup marinara over the bottom of a 9×13-inch baking dish. Layer 3 noodles, half the ricotta, half the vegetables, 1 cup mozzarella and 1 cup marinara. Repeat. Top with 3 more noodles, 1 cup marinara, then the last 3 noodles and the rest of the sauce, making sure every noodle is covered. Finish with the remaining mozzarella and Parmesan.', 600, null, null),
  ('38efb0d3-2b21-4fea-a42e-d24e291fb839', 5, 'Assembly', 'Cover tightly with foil (lightly oiled on the underside so the cheese doesn''t stick) and bake 40 minutes.', 2400, 190.6, null),
  ('38efb0d3-2b21-4fea-a42e-d24e291fb839', 6, 'Assembly', 'Uncover and bake until bubbling at the edges, browned on top and 160°F in the center, 15–20 minutes more.', 1080, 190.6, 71.1),
  ('38efb0d3-2b21-4fea-a42e-d24e291fb839', 7, 'Assembly', 'Let the lasagna rest 20 minutes before cutting so the layers hold together.', 1200, null, null);

