values ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-pot-pie-skillet', 'chicken-pot-pie-606bd3', 'Chicken Pot Pie', 'Tender chicken and vegetables in a creamy thyme gravy under a flaky golden crust, baked right in the skillet with a store-bought pie crust.', 'american', 2, 25, 60, 85, 6, 'main', null, 0, array['stove', 'oven', 'cast_iron']::text[], array['comfort', 'kid-friendly', 'make-ahead']::text[], array['Short on time? Use 3 cups shredded rotisserie chicken and 2 cups store-bought stock and skip the first step.', 'No oven-safe skillet: pour the filling into a 2½-quart baking dish and top as directed.']::text[], 'https://images.pexels.com/photos/39070796/pexels-photo-39070796.jpeg', 'Golden-crusted chicken pie with a slice cut out to show the filling', 'Mayara Caroline Mombelli', 'https://www.pexels.com/@mayaramombellifotografias/', 'https://www.pexels.com/photo/delicious-chicken-pot-pie-on-orange-plate-39070796/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'baking', 'main', 'dinner']::text[], array['stew', 'steam', 'bake']::text[], '{}'::text[], '{}'::text[], null, null, 'chicken-pot-pie', 'classic', 'Refrigerate up to 3 days and reheat in a 350°F oven, covered with foil, until hot. The cooled filling can be made a day ahead; top and bake when ready, adding 10 minutes.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], array['chicken']::text[], '{}'::text[], array['chicken stock', 'yellow onion', 'carrot', 'celery', 'garlic', 'milk', 'thyme leave', 'frozen pea', 'pie crust', 'egg']::text[], 'carrot|celery|chicken stock|egg|frozen pea|garlic|milk|pie crust|thyme leave|yellow onion',
  null, null, null, null, null, null, null, null)
