  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 1, 'Filling', '1¼ lb boneless, skinless chicken thighs', 'boneless, skinless chicken thighs', 1.25, 'lb', null, false),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 2, 'Filling', '2 cups low-sodium chicken stock', 'low-sodium chicken stock', 2, 'cup', null, false),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 3, 'Filling', '5 tbsp unsalted butter', 'unsalted butter', 5, 'tbsp', null, false),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 4, 'Filling', '1 yellow onion, diced', 'yellow onion', 1, null, 'diced', false),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 5, 'Filling', '2 carrots, diced', 'carrots', 2, null, 'diced', false),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 6, 'Filling', '2 stalk celery, diced', 'celery', 2, 'stalk', 'diced', false),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 7, 'Filling', '2 cloves garlic, minced', 'garlic', 2, 'clove', 'minced', false),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 8, 'Filling', '⅓ cup all-purpose flour', 'all-purpose flour', 0.33, 'cup', null, false),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 9, 'Filling', '1 cup whole milk', 'whole milk', 1, 'cup', null, false),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 10, 'Filling', '1 tsp fresh thyme leaves, or ½ tsp dried', 'fresh thyme leaves', 1, 'tsp', 'or ½ tsp dried', false),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 11, 'Filling', '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 12, 'Filling', '½ tsp black pepper', 'black pepper', 0.5, 'tsp', null, false),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 13, 'Filling', '1 cup frozen peas', 'frozen peas', 1, 'cup', null, false),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 14, 'Crust', '1 refrigerated pie crust, half a 14-oz box, or homemade', 'refrigerated pie crust', 1, null, 'half a 14-oz box, or homemade', false),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 15, 'Crust', '1 large egg, beaten with 1 tbsp water', 'large egg', 1, null, 'beaten with 1 tbsp water', false);
