insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 1, 'Filling', 'Heat the oven to 400°F. Put the chicken and stock in a saucepan, bring to a simmer, cover and cook over medium-low heat until the chicken is 165°F in the thickest piece, 15–18 minutes. Lift out the chicken, shred it with two forks and keep the stock.', 1080, 204.4, 73.9),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 2, 'Filling', 'Melt the butter in a 10-inch cast-iron or other oven-safe skillet over medium heat. Cook the onion, carrots and celery until softened, about 8 minutes, then add the garlic for 1 minute.', 540, null, null),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 3, 'Filling', 'Sprinkle in the flour and stir 2 minutes. Slowly whisk in the reserved stock, then the milk, and simmer, stirring, until thick enough to coat a spoon, 4–5 minutes. Stir in the chicken, thyme, salt, pepper and peas and take off the heat.', 420, null, null),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 4, 'Crust', 'Unroll the crust over the hot filling, tuck the edges inside the pan, brush with the egg wash and cut four slits in the top so steam can escape.', 180, null, null),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 5, 'Crust', 'Set the skillet on a sheet pan to catch drips and bake until the crust is deep golden and the filling bubbles through the slits, 30–35 minutes.', 1920, 204.4, null),
  ('606bd3bf-8416-4a00-9f3a-9104a1959cfb', 6, 'Crust', 'Let it rest 15 minutes so the filling thickens before serving.', 900, null, null);

