values ('95d8ec85-b4f3-413d-8668-95c48d201b2a', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'classic-beef-and-bean-chili', 'classic-beef-chili-95d8ec', 'Classic Beef Chili', 'A thick, deeply seasoned pot of ground beef, kidney beans and tomatoes simmered with chili powder and cumin — the game-day and weeknight standby that''s even better the next day.', 'american', 1, 15, 75, 90, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['comfort', 'budget', 'make-ahead', 'freezer-friendly', 'one-pot']::text[], array['For a thicker, more Tex-Mex body, stir 2 tablespoons masa harina into ¼ cup water and simmer it in for the last 5 minutes.']::text[], 'https://images.unsplash.com/photo-1790701909034-6c7b45c7b58a', 'Bowl of beef and kidney bean chili topped with shredded cheese, sour cream and scallions', 'Chad Montano', 'https://unsplash.com/@briewilly', 'https://unsplash.com/photos/chili-bowl-with-cheese-and-cream-HNVi6m5KCr8', 'unsplash', true, 'public', false,
  'pending_review', array['comfort', 'budget', 'main', 'dinner', 'holiday']::text[], array['stew', 'boil']::text[], array['spicy', 'smoky', 'tangy', 'aromatic']::text[], array['game-day']::text[], null, null, 'beef-chili', 'classic', 'Refrigerate up to 4 days or freeze up to 3 months. Reheat over medium-low heat with a splash of water.', null, 'owned', array['milk']::text[], array['beef', 'beans']::text[], array['dairy_free']::text[], array['ground beef', 'yellow onion', 'bell pepper', 'garlic', 'chili powder', 'ground cumin', 'dried oregano', 'smoked paprika', 'tomato paste', 'tomato', 'kidney bean', 'beef stock', 'cider vinegar']::text[], 'beef stock|bell pepper|chili powder|cider vinegar|dried oregano|garlic|ground beef|ground cumin|kidney bean|smoked paprika|tomato|tomato paste|yellow onion',
  null, null, null, null, null, null, null, null)
