insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('95d8ec85-b4f3-413d-8668-95c48d201b2a', 1, 'Chili', 'Heat the oil in a Dutch oven over medium-high heat. Add the beef and cook, breaking it up, until well browned, no pink remains and it reaches 160°F, about 10 minutes. Spoon off all but about 2 tablespoons of the fat.', 600, null, 71.1),
  ('95d8ec85-b4f3-413d-8668-95c48d201b2a', 2, 'Chili', 'Add the onion, bell pepper and jalapeño and cook until softened, about 6 minutes.', 360, null, null),
  ('95d8ec85-b4f3-413d-8668-95c48d201b2a', 3, 'Chili', 'Stir in the garlic, chili powder, cumin, oregano, paprika, cayenne and tomato paste and cook 2 minutes, until the spices smell toasty and the paste darkens.', 120, null, null),
  ('95d8ec85-b4f3-413d-8668-95c48d201b2a', 4, 'Chili', 'Add the tomatoes, beans, stock and salt and bring to a boil. Lower the heat, partly cover and simmer, stirring every 10 minutes so nothing sticks, until thick and rich, 45–60 minutes.', 3300, null, null),
  ('95d8ec85-b4f3-413d-8668-95c48d201b2a', 5, 'Chili', 'Stir in the vinegar, then taste and adjust the salt and heat. Serve with cheddar, sour cream and scallions.', 60, null, null);

