values ('2754d974-59d7-407f-a7e4-4e249ee49b64', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'hearty-oven-braised-beef-stew', 'hearty-beef-stew-2754d9', 'Hearty Beef Stew', 'Fork-tender chunks of beef chuck braised low and slow with red wine, potatoes and carrots in a rich, thick gravy — Sunday-supper comfort that mostly cooks itself.', 'american', 2, 25, 170, 195, 6, 'main', null, 0, array['stove', 'oven', 'dutch_oven']::text[], array['comfort', 'make-ahead', 'one-pot']::text[], array['Worcestershire sauce usually contains anchovies (fish). Leave it out or use a fish-free version if anyone has a fish allergy.', 'Buy a whole chuck roast and cut it yourself — packaged "stew meat" is often odds and ends that cook unevenly.']::text[], 'https://images.pexels.com/photos/10692537/pexels-photo-10692537.jpeg', 'Beef stew with carrots and potatoes in a white bowl', 'Yang Hao', 'https://www.pexels.com/@yang-hao-155871170/', 'https://www.pexels.com/photo/cooked-food-on-white-ceramic-bowl-10692537/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'soup', 'main', 'dinner']::text[], array['braise', 'stew', 'pan_fry']::text[], array['fresh', 'savory']::text[], '{}'::text[], null, null, 'beef-stew', 'classic', 'Refrigerate up to 4 days; it tastes even better the next day. Freezes up to 3 months, though the potatoes turn a little soft.', null, 'owned', array['fish', 'gluten', 'wheat']::text[], array['beef']::text[], array['dairy_free']::text[], array['chuck roast', 'yellow onion', 'garlic', 'tomato paste', 'red wine', 'beef stock', 'worcestershire sauce', 'bay leave', 'dried thyme', 'gold potato', 'carrot', 'celery', 'frozen pea', 'parsley']::text[], 'bay leave|beef stock|carrot|celery|chuck roast|dried thyme|frozen pea|garlic|gold potato|parsley|red wine|tomato paste|worcestershire sauce|yellow onion',
  null, null, null, null, null, null, null, null)
