delete from public.recipe_instructions where recipe_id = '2754d974-59d7-407f-a7e4-4e249ee49b64';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('2754d974-59d7-407f-a7e4-4e249ee49b64', 1, null, 'Heat the oven to 325°F. Pat the beef dry, season with 1½ teaspoons of the salt and the pepper, then toss with the flour.', 180, 162.8, null),
  ('2754d974-59d7-407f-a7e4-4e249ee49b64', 2, null, 'Heat 2 tablespoons of the oil in a Dutch oven over medium-high heat. Brown the beef in 2–3 batches without crowding, about 4 minutes per batch, adding more oil as needed. Move to a bowl.', 720, null, null),
  ('2754d974-59d7-407f-a7e4-4e249ee49b64', 3, null, 'Add the onion to the pot and cook until soft, 5 minutes. Stir in the garlic and tomato paste for 1 minute, then pour in the wine and scrape up all the browned bits. Simmer 2 minutes.', 480, null, null),
  ('2754d974-59d7-407f-a7e4-4e249ee49b64', 4, null, 'Add the stock, Worcestershire, bay leaves, thyme and the beef with its juices. Bring to a simmer, cover and braise in the oven for 1½ hours.', 5400, 162.8, null),
  ('2754d974-59d7-407f-a7e4-4e249ee49b64', 5, null, 'Stir in the potatoes, carrots, celery and remaining salt, cover and return to the oven until the vegetables are tender and the beef breaks apart easily with a fork, 45–60 minutes. (The beef is far past 145°F by now; tenderness is the test.)', 3000, 162.8, 62.8),
  ('2754d974-59d7-407f-a7e4-4e249ee49b64', 6, null, 'Discard the bay leaves, stir in the peas and let them warm through for 5 minutes. Taste for salt and serve sprinkled with parsley.', 300, null, null);

