values ('32f9708e-c022-4191-af01-f22c233df910', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'beef-and-rice-stuffed-bell-peppers', 'stuffed-bell-peppers-32f970', 'Stuffed Bell Peppers', 'Bell pepper halves filled with seasoned ground beef, rice and tomato, baked until tender and finished with melted cheddar — a budget-friendly family dinner.', 'american', 1, 15, 55, 70, 4, 'main', null, 0, array['stove', 'oven']::text[], array['weeknight', 'kid-friendly', 'budget', 'make-ahead']::text[], array['Ground turkey works well here too; cook it to 165°F in the browning step.']::text[], 'https://images.unsplash.com/photo-1673646960062-9aeb2188335f', 'Bell peppers stuffed with minced meat and rice in sauce on a white plate', 'Natalia Gusakova', 'https://unsplash.com/@nataliaraylenegusakova', 'https://unsplash.com/photos/a-white-plate-topped-with-stuffed-bell-peppers-myfDbaJr6vA', 'unsplash', true, 'public', false,
  'pending_review', array['comfort', 'budget', 'main', 'dinner']::text[], array['bake']::text[], array['fresh']::text[], '{}'::text[], null, null, 'stuffed-bell-peppers', 'classic', 'Refrigerate up to 4 days. Reheat covered in a 350°F oven or the microwave. Stuff the peppers up to a day ahead and bake when ready.', null, 'owned', array['milk']::text[], array['beef']::text[], '{}'::text[], array['bell pepper', 'ground beef', 'yellow onion', 'garlic', 'tomato', 'tomato sauce', 'white rice', 'italian seasoning', 'cheddar cheese']::text[], 'bell pepper|cheddar cheese|garlic|ground beef|italian seasoning|tomato|tomato sauce|white rice|yellow onion',
  null, null, null, null, null, null, null, null)
