insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('32f9708e-c022-4191-af01-f22c233df910', 1, null, 'Heat the oven to 375°F. Arrange the pepper halves cut-side up in a 9×13-inch baking dish, add ¼ cup water to the dish, cover with foil and bake 15 minutes to soften.', 900, 190.6, null),
  ('32f9708e-c022-4191-af01-f22c233df910', 2, null, 'Meanwhile, heat the oil in a large skillet over medium-high heat. Cook the beef and onion, breaking up the meat, until browned, no pink remains and it reaches 160°F, about 8 minutes. Spoon off excess fat and stir in the garlic for 1 minute.', 540, null, 71.1),
  ('32f9708e-c022-4191-af01-f22c233df910', 3, null, 'Stir in the diced tomatoes, half the tomato sauce, the rice, Italian seasoning, salt and pepper and heat through, 2 minutes.', 120, null, null),
  ('32f9708e-c022-4191-af01-f22c233df910', 4, null, 'Pour off any water in the dish, fill the peppers generously with the beef mixture and spoon the remaining tomato sauce over the top.', 240, null, null),
  ('32f9708e-c022-4191-af01-f22c233df910', 5, null, 'Cover with foil and bake 20 minutes. Uncover, top with the cheddar and bake until the cheese is melted and the peppers are tender, about 10 minutes more. Sprinkle with parsley.', 1800, 190.6, null);

-- Pork Chops with Apples and Onions
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
