values ('3be9355f-d19d-451f-8bab-129a141445de', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'skillet-pork-chops-apples-onions', 'pork-chops-with-apples-and-onions-3be935', 'Pork Chops with Apples and Onions', 'Thick, juicy seared pork chops with apples and onions cooked down in the same skillet with cider and a little brown sugar into a sweet-tangy pan sauce.', 'american', 1, 10, 25, 35, 4, 'main', null, 0, array['stove', 'cast_iron']::text[], array['weeknight', 'comfort', 'fall']::text[], array['Pork cooked to 145°F with a short rest is safe and stays slightly pink and juicy in the middle — an instant-read thermometer takes the guesswork out.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['quick', 'comfort', 'main', 'dinner']::text[], array['stew', 'pan_fry']::text[], array['tangy']::text[], '{}'::text[], null, null, 'pork-chops-apples-onions', 'classic', 'Refrigerate up to 3 days. Reheat gently, covered, so the chops don''t dry out.', null, 'owned', array['milk']::text[], array['pork']::text[], array['gluten_free']::text[], array['pork chop', 'dried sage', 'yellow onion', 'apple', 'brown sugar', 'apple cider', 'dijon mustard', 'cider vinegar']::text[], 'apple|apple cider|brown sugar|cider vinegar|dijon mustard|dried sage|pork chop|yellow onion',
  null, null, null, null, null, null, null, null)
