  ('3be9355f-d19d-451f-8bab-129a141445de', 1, null, '4 bone-in pork chops, about 1 inch thick, 8–10 oz each', 'bone-in pork chops', 4, null, 'about 1 inch thick, 8–10 oz each', false),
  ('3be9355f-d19d-451f-8bab-129a141445de', 2, null, '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('3be9355f-d19d-451f-8bab-129a141445de', 3, null, '½ tsp black pepper', 'black pepper', 0.5, 'tsp', null, false),
  ('3be9355f-d19d-451f-8bab-129a141445de', 4, null, '1 tsp dried sage, or dried thyme', 'dried sage', 1, 'tsp', 'or dried thyme', false),
  ('3be9355f-d19d-451f-8bab-129a141445de', 5, null, '1 tbsp vegetable oil', 'vegetable oil', 1, 'tbsp', null, false),
  ('3be9355f-d19d-451f-8bab-129a141445de', 6, null, '2 tbsp unsalted butter', 'unsalted butter', 2, 'tbsp', null, false),
  ('3be9355f-d19d-451f-8bab-129a141445de', 7, null, '1 yellow onion, halved and thinly sliced', 'yellow onion', 1, null, 'halved and thinly sliced', false),
