delete from public.recipe_instructions where recipe_id = '3be9355f-d19d-451f-8bab-129a141445de';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('3be9355f-d19d-451f-8bab-129a141445de', 1, null, 'Pat the chops dry and season both sides with the salt, pepper and sage. Let them sit while the pan heats.', 180, null, null),
  ('3be9355f-d19d-451f-8bab-129a141445de', 2, null, 'Heat the oil in a large cast-iron skillet over medium-high heat until shimmering. Sear the chops until deeply browned, 4–5 minutes. Flip, lower the heat to medium and cook until 145°F in the center (not touching the bone), 4–6 minutes more. Move to a plate and rest at least 3 minutes.', 600, null, 62.8),
  ('3be9355f-d19d-451f-8bab-129a141445de', 3, null, 'Melt the butter in the skillet, add the onion and cook, stirring, until soft and golden, about 5 minutes.', 300, null, null),
  ('3be9355f-d19d-451f-8bab-129a141445de', 4, null, 'Add the apples and brown sugar and cook until the apples are just tender and lightly caramelized, 4 minutes.', 240, null, null),
  ('3be9355f-d19d-451f-8bab-129a141445de', 5, null, 'Pour in the cider, add the mustard and scrape up the browned bits. Simmer until the liquid turns syrupy, 3–4 minutes, then stir in the vinegar.', 240, null, null),
  ('3be9355f-d19d-451f-8bab-129a141445de', 6, null, 'Return the chops and any juices to the pan, spoon the apples and sauce over and serve.', 60, null, null);

