values ('a53a88d9-8f3a-41c9-9546-7a026aa2e00e', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'honey-brown-sugar-glazed-spiral-ham', 'honey-glazed-ham-a53a88', 'Honey-Glazed Ham', 'A fully cooked spiral-cut ham gently reheated under foil, then lacquered with a honey, brown sugar, orange and Dijon glaze until sticky and caramelized — the easy holiday centerpiece.', 'american', 1, 10, 135, 145, 16, 'main', null, 0, array['oven', 'stove']::text[], array['entertaining', 'holiday', 'make-ahead']::text[], array['Make sure the label says "fully cooked" — those just need reheating to 140°F. An uncooked ("fresh" or "cook before eating") ham must reach 145°F and rest 3 minutes and takes much longer.', 'Throw away the glaze packet that comes with the ham; this one tastes far better.']::text[], 'https://images.unsplash.com/photo-1785304968648-a47d113fc204', 'Whole glazed ham with a caramelised crust in a roasting tray', 'Seb Reivers', 'https://unsplash.com/@sebbiepie', 'https://unsplash.com/photos/a-large-ham-roasting-in-a-dark-oven-xP3yunnApZc', 'unsplash', true, 'public', false,
  'pending_review', array['holiday', 'entertaining', 'main', 'dinner']::text[], array['roast', 'stew', 'bake']::text[], array['aromatic']::text[], array['easter', 'christmas', 'thanksgiving']::text[], null, null, 'honey-glazed-ham', 'classic', 'Refrigerate sliced ham up to 5 days or freeze up to 2 months. Save the bone for bean or split pea soup.', null, 'owned', array['milk']::text[], array['pork']::text[], array['gluten_free']::text[], array['spiral-cut ham', 'honey', 'brown sugar', 'orange juice', 'dijon mustard', 'ground cinnamon', 'ground clove']::text[], 'brown sugar|dijon mustard|ground cinnamon|ground clove|honey|orange juice|spiral-cut ham',
  null, null, null, null, null, null, null, null)
