delete from public.recipe_ingredients where recipe_id = 'a53a88d9-8f3a-41c9-9546-7a026aa2e00e';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('a53a88d9-8f3a-41c9-9546-7a026aa2e00e', 1, 'Ham', '8 lb fully cooked bone-in spiral-cut ham', 'fully cooked bone-in spiral-cut ham', 8, 'lb', null, false),
  ('a53a88d9-8f3a-41c9-9546-7a026aa2e00e', 2, 'Ham', '½ cup water', 'water', 0.5, 'cup', null, false),
  ('a53a88d9-8f3a-41c9-9546-7a026aa2e00e', 3, 'Glaze', '½ cup honey', 'honey', 0.5, 'cup', null, false),
  ('a53a88d9-8f3a-41c9-9546-7a026aa2e00e', 4, 'Glaze', '½ cup packed light brown sugar', 'packed light brown sugar', 0.5, 'cup', null, false),
  ('a53a88d9-8f3a-41c9-9546-7a026aa2e00e', 5, 'Glaze', '4 tbsp unsalted butter', 'unsalted butter', 4, 'tbsp', null, false),
  ('a53a88d9-8f3a-41c9-9546-7a026aa2e00e', 6, 'Glaze', '¼ cup orange juice', 'orange juice', 0.25, 'cup', null, false),
  ('a53a88d9-8f3a-41c9-9546-7a026aa2e00e', 7, 'Glaze', '2 tbsp Dijon mustard', 'Dijon mustard', 2, 'tbsp', null, false),
  ('a53a88d9-8f3a-41c9-9546-7a026aa2e00e', 8, 'Glaze', '½ tsp ground cinnamon', 'ground cinnamon', 0.5, 'tsp', null, false),
  ('a53a88d9-8f3a-41c9-9546-7a026aa2e00e', 9, 'Glaze', '¼ tsp ground cloves', 'ground cloves', 0.25, 'tsp', null, false);
delete from public.recipe_instructions where recipe_id = 'a53a88d9-8f3a-41c9-9546-7a026aa2e00e';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('a53a88d9-8f3a-41c9-9546-7a026aa2e00e', 1, 'Ham', 'Heat the oven to 325°F with a rack in the lower third. Set the ham cut-side down in a roasting pan, pour the water into the pan and cover the whole pan tightly with foil.', 300, 162.8, null),
  ('a53a88d9-8f3a-41c9-9546-7a026aa2e00e', 2, 'Ham', 'Bake until the center of the ham reads about 120°F, 12–14 minutes per pound (about 1¾ hours for an 8-lb ham).', 6300, 162.8, null),
  ('a53a88d9-8f3a-41c9-9546-7a026aa2e00e', 3, 'Glaze', 'Near the end, simmer the honey, brown sugar, butter, orange juice, mustard, cinnamon and cloves in a small saucepan, stirring, until smooth and slightly thickened, 3–4 minutes.', 240, null, null),
  ('a53a88d9-8f3a-41c9-9546-7a026aa2e00e', 4, 'Glaze', 'Take the ham out and raise the oven to 400°F. Uncover and brush the glaze all over, letting some run between the slices.', 180, 204.4, null),
  ('a53a88d9-8f3a-41c9-9546-7a026aa2e00e', 5, 'Glaze', 'Return the ham uncovered and bake, brushing with more glaze every 7–8 minutes, until sticky and caramelized and the center reaches 140°F, 20–25 minutes. Watch the edges so the sugar doesn''t burn.', 1320, 204.4, null),
  ('a53a88d9-8f3a-41c9-9546-7a026aa2e00e', 6, 'Ham', 'Rest the ham 15 minutes, then spoon the pan juices over and serve.', 900, null, null);

-- Classic Roast Chicken
