values ('a2edad4a-2d0a-4d6d-814e-510319b0e4b6', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'lemon-garlic-herb-roast-chicken', 'classic-roast-chicken-a2edad', 'Classic Roast Chicken', 'A whole chicken rubbed with butter, stuffed with lemon, garlic and thyme and roasted hot on a bed of onions for crisp golden skin, juicy meat and an easy pan sauce.', 'american', 2, 15, 90, 105, 4, 'main', null, 0, array['oven', 'cast_iron']::text[], array['comfort', 'kid-friendly', 'budget']::text[], array['For extra-crisp skin, salt the chicken the day before and refrigerate it uncovered on a plate; skip the salt in step 2.']::text[], 'https://images.pexels.com/photos/10821330/pexels-photo-10821330.jpeg', 'Golden roasted whole chicken with herbs', 'furkanfdemir', 'https://www.pexels.com/@furkanfdemir/', 'https://www.pexels.com/photo/close-up-shot-of-a-roasted-chicken-10821330/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner', 'budget']::text[], array['roast', 'stew']::text[], array['tangy']::text[], '{}'::text[], null, null, 'roast-chicken', 'classic', 'Refrigerate carved chicken up to 4 days. Simmer the carcass with water, onion and carrot for stock.', null, 'owned', array['milk']::text[], array['chicken']::text[], '{}'::text[], array['chicken', 'lemon', 'garlic', 'thyme', 'yellow onion', 'chicken stock']::text[], 'chicken|chicken stock|garlic|lemon|thyme|yellow onion',
  null, null, null, null, null, null, null, null)
