insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('a2edad4a-2d0a-4d6d-814e-510319b0e4b6', 1, null, '1 whole chicken, about 4 lb, giblets removed', 'whole chicken', 1, null, 'about 4 lb, giblets removed', false),
  ('a2edad4a-2d0a-4d6d-814e-510319b0e4b6', 2, null, '2 tsp kosher salt', 'kosher salt', 2, 'tsp', null, false),
  ('a2edad4a-2d0a-4d6d-814e-510319b0e4b6', 3, null, '½ tsp black pepper', 'black pepper', 0.5, 'tsp', null, false),
  ('a2edad4a-2d0a-4d6d-814e-510319b0e4b6', 4, null, '3 tbsp unsalted butter, softened', 'unsalted butter', 3, 'tbsp', 'softened', false),
  ('a2edad4a-2d0a-4d6d-814e-510319b0e4b6', 5, null, '1 lemon, halved', 'lemon', 1, null, 'halved', false),
  ('a2edad4a-2d0a-4d6d-814e-510319b0e4b6', 6, null, '1 head garlic, halved crosswise', 'garlic', 1, 'head', 'halved crosswise', false),
  ('a2edad4a-2d0a-4d6d-814e-510319b0e4b6', 7, null, '6 sprigs fresh thyme', 'fresh thyme', 6, 'sprig', null, false),
  ('a2edad4a-2d0a-4d6d-814e-510319b0e4b6', 8, null, '2 yellow onions, cut into thick rounds', 'yellow onions', 2, null, 'cut into thick rounds', false),
  ('a2edad4a-2d0a-4d6d-814e-510319b0e4b6', 9, null, '½ cup low-sodium chicken stock, or water', 'low-sodium chicken stock', 0.5, 'cup', 'or water', false);
delete from public.recipe_instructions where recipe_id = 'a2edad4a-2d0a-4d6d-814e-510319b0e4b6';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('a2edad4a-2d0a-4d6d-814e-510319b0e4b6', 1, null, 'Heat the oven to 425°F. Pat the chicken very dry inside and out with paper towels — don''t rinse it, which only spreads bacteria around the sink.', 180, 218.3, null),
  ('a2edad4a-2d0a-4d6d-814e-510319b0e4b6', 2, null, 'Season inside and out with the salt and pepper, then rub the butter all over the skin. Tuck the lemon, garlic and half the thyme into the cavity and tie the legs together with kitchen string.', 300, null, null),
  ('a2edad4a-2d0a-4d6d-814e-510319b0e4b6', 3, null, 'Lay the onions and remaining thyme in a 12-inch cast-iron skillet or roasting pan and set the chicken on top, breast-side up.', 120, null, null),
  ('a2edad4a-2d0a-4d6d-814e-510319b0e4b6', 4, null, 'Roast until the skin is deep golden and an instant-read thermometer in the thickest part of the thigh (not touching bone) reads 165°F, 65–80 minutes. If the skin browns too fast, cover loosely with foil.', 4500, 218.3, 73.9),
  ('a2edad4a-2d0a-4d6d-814e-510319b0e4b6', 5, null, 'Tip the juices from the cavity into the pan, then move the chicken to a board and rest 15 minutes.', 900, null, null),
  ('a2edad4a-2d0a-4d6d-814e-510319b0e4b6', 6, null, 'Meanwhile, set the pan over medium heat (the handle is very hot — use an oven mitt), add the stock and scrape up the browned bits, mashing the onions. Simmer 2–3 minutes and spoon over the carved chicken.', 180, null, null);

-- Buffalo Chicken Wings
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
