values ('5667785f-bae2-42ce-b0e7-ab374db81223', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'oven-baked-buffalo-chicken-wings', 'buffalo-chicken-wings-566778', 'Buffalo Chicken Wings', 'Crisp wings tossed in tangy butter-and-hot-sauce Buffalo sauce with a cool blue cheese dip and celery; we bake them with a little baking powder instead of deep-frying, and they still come out crackly.', 'american', 1, 15, 80, 95, 6, 'starter', null, 0, array['oven', 'stove']::text[], array['game-day', 'entertaining', 'spicy']::text[], array['Use aluminum-free baking powder — regular kinds can leave a slight metallic taste.', 'For milder wings, use ⅓ cup hot sauce and 5 tablespoons butter; for hotter, add a pinch of cayenne.']::text[], 'https://images.pexels.com/photos/38896815/pexels-photo-38896815.jpeg', 'Spicy buffalo wings with a creamy dip, carrot and celery sticks', 'Mike C', 'https://www.pexels.com/@mike-c-2151163165/', 'https://www.pexels.com/photo/spicy-buffalo-wings-with-ranch-dip-38896815/', 'pexels', true, 'public', false,
  'pending_review', array['appetizer', 'holiday', 'entertaining']::text[], array['bake']::text[], array['spicy', 'tangy']::text[], array['game-day']::text[], 'Buffalo, New York', 'adapted', 'buffalo-wings', 'classic', 'Best hot. Refrigerate up to 3 days and re-crisp in a 400°F oven or air fryer for 8–10 minutes.', null, 'owned', array['egg', 'milk']::text[], array['chicken']::text[], array['gluten_free']::text[], array['chicken wing', 'baking powder', 'pepper sauce', 'garlic powder', 'sour cream', 'mayonnaise', 'blue cheese', 'lemon juice', 'celery']::text[], 'baking powder|blue cheese|celery|chicken wing|garlic powder|lemon juice|mayonnaise|pepper sauce|sour cream',
  null, null, null, null, null, null, null, null)
