delete from public.recipe_ingredients where recipe_id = '5667785f-bae2-42ce-b0e7-ab374db81223';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 1, 'Wings', '3 lb chicken wings, split into flats and drumettes, tips removed', 'chicken wings', 3, 'lb', 'split into flats and drumettes, tips removed', false),
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 2, 'Wings', '1 tbsp baking powder, aluminum-free', 'baking powder', 1, 'tbsp', 'aluminum-free', false),
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 3, 'Wings', '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 4, 'Buffalo sauce', '½ cup cayenne pepper hot sauce, such as a Louisiana-style hot sauce', 'cayenne pepper hot sauce', 0.5, 'cup', 'such as a Louisiana-style hot sauce', false),
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 5, 'Buffalo sauce', '4 tbsp unsalted butter', 'unsalted butter', 4, 'tbsp', null, false),
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 6, 'Buffalo sauce', '1 tsp honey', 'honey', 1, 'tsp', null, true),
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 7, 'Buffalo sauce', '¼ tsp garlic powder', 'garlic powder', 0.25, 'tsp', null, false),
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 8, 'Blue cheese dip', '½ cup sour cream', 'sour cream', 0.5, 'cup', null, false),
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 9, 'Blue cheese dip', '¼ cup mayonnaise', 'mayonnaise', 0.25, 'cup', null, false),
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 10, 'Blue cheese dip', '3 oz blue cheese, crumbled', 'blue cheese', 3, 'oz', 'crumbled', false),
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 11, 'Blue cheese dip', '1 tsp fresh lemon juice', 'fresh lemon juice', 1, 'tsp', null, false),
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 12, 'Blue cheese dip', '¼ tsp black pepper', 'black pepper', 0.25, 'tsp', null, false),
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 13, 'To serve', '4 stalk celery, cut into sticks', 'celery', 4, 'stalk', 'cut into sticks', false),
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 14, 'To serve', '2 carrots, cut into sticks', 'carrots', 2, null, 'cut into sticks', true);
delete from public.recipe_instructions where recipe_id = '5667785f-bae2-42ce-b0e7-ab374db81223';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 1, 'Wings', 'Heat the oven to 250°F with a rack in the upper-middle position. Line a rimmed sheet pan with foil and set a wire rack on it.', null, 121.1, null),
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 2, 'Wings', 'Pat the wings very dry with paper towels. In a large bowl, toss them with the baking powder and salt until evenly coated, then spread on the rack in a single layer, not touching.', 300, null, null),
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 3, 'Wings', 'Bake 30 minutes — this low start renders the fat. Then raise the oven to 425°F and bake until deep golden and crisp, 40–50 minutes more; they should be at least 165°F inside (they''re crispest closer to 180°F).', 4500, 218.3, 73.9),
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 4, 'Blue cheese dip', 'While the wings bake, stir the sour cream, mayonnaise, blue cheese, lemon juice and pepper together, mashing some of the cheese. Refrigerate until serving.', 180, null, null),
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 5, 'Buffalo sauce', 'Warm the hot sauce, butter, honey and garlic powder in a small saucepan over low heat, whisking until the butter melts, about 2 minutes.', 120, null, null),
  ('5667785f-bae2-42ce-b0e7-ab374db81223', 6, 'Buffalo sauce', 'Toss the hot wings in a big bowl with the sauce and serve right away with the dip, celery and carrots.', 60, null, null);

