values ('3ffc3214-4c25-4dd1-9fda-89d660ba86ec', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'maryland-lump-crab-cakes', 'maryland-crab-cakes-3ffc32', 'Maryland Crab Cakes', 'Big, tender crab cakes that are mostly sweet lump crab, held together with just a little mayonnaise, egg and crushed saltines, seasoned with Old Bay and baked until golden.', 'american', 2, 20, 15, 65, 4, 'main', null, 30, array['oven']::text[], array['entertaining', 'date-night']::text[], array['Worcestershire sauce usually contains anchovies (fish); leave it out if anyone has a fish allergy.', 'Refrigerated tubs of pasteurized lump crab by the seafood counter are the easiest choice; canned shelf-stable crab is much less sweet.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'holiday', 'date_night', 'entertaining']::text[], array['pan_fry', 'bake']::text[], array['tangy', 'fresh', 'savory']::text[], array['date-night', 'july-4th']::text[], 'Maryland', 'traditional', 'maryland-crab-cakes', 'classic', 'Shaped, uncooked cakes keep 1 day covered in the fridge. Cooked cakes keep 2 days; reheat in a 350°F oven for 10 minutes.', null, 'owned', array['egg', 'fish', 'gluten', 'milk', 'shellfish', 'wheat']::text[], array['shellfish']::text[], array['pescatarian']::text[], array['mayonnaise', 'egg', 'dijon mustard', 'worcestershire sauce', 'bay seasoning', 'lemon juice', 'parsley', 'crab meat', 'saltine cracker', 'lemon']::text[], 'bay seasoning|crab meat|dijon mustard|egg|lemon|lemon juice|mayonnaise|parsley|saltine cracker|worcestershire sauce',
  null, null, null, null, null, null, null, null)
