insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('3ffc3214-4c25-4dd1-9fda-89d660ba86ec', 1, null, 'Whisk the mayonnaise, egg, mustard, Worcestershire, Old Bay, lemon juice and parsley together in a large bowl.', 120, null, null),
  ('3ffc3214-4c25-4dd1-9fda-89d660ba86ec', 2, null, 'Add the crab and crushed crackers and fold very gently with a spatula, keeping the lumps whole, until just combined.', 120, null, null),
  ('3ffc3214-4c25-4dd1-9fda-89d660ba86ec', 3, null, 'Shape into 8 loose cakes about 1 inch thick (or 4 large ones) and set on a parchment-lined sheet pan. Cover and refrigerate 30 minutes so they hold together.', 1800, null, null),
  ('3ffc3214-4c25-4dd1-9fda-89d660ba86ec', 4, null, 'Heat the oven to 450°F. Brush the cakes with the melted butter.', null, 232.2, null),
  ('3ffc3214-4c25-4dd1-9fda-89d660ba86ec', 5, null, 'Bake until golden brown on top and heated through to 160°F in the center, 12–15 minutes (large cakes take a few minutes longer).', 780, 232.2, 71.1),
  ('3ffc3214-4c25-4dd1-9fda-89d660ba86ec', 6, null, 'Let them sit 2 minutes, then serve with lemon wedges and tartar sauce.', 120, null, null);

-- Blackened Salmon
