values ('0068a2a9-1ed5-407c-afec-43dc351567c1', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'cast-iron-blackened-salmon', 'blackened-salmon-0068a2', 'Blackened Salmon', 'Salmon fillets coated in a smoky paprika, garlic, thyme and cayenne rub and seared hard in a cast-iron skillet until a dark, spicy crust forms; the Louisiana blackening method was made for redfish, so we use salmon and a little less heat for a home kitchen.', 'cajun_creole', 2, 10, 12, 22, 4, 'main', null, 0, array['stove', 'cast_iron']::text[], array['weeknight', 'spicy', 'quick']::text[], array['Blackening is smoky by nature. If your kitchen is poorly ventilated, cook it in a cast-iron pan on an outdoor grill.', 'The rub keeps for months in a jar — make a triple batch for chicken and shrimp.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['quick', 'main', 'dinner']::text[], '{}'::text[], array['spicy', 'smoky', 'tangy']::text[], '{}'::text[], 'Louisiana', 'adapted', 'blackened-salmon', 'classic', 'Refrigerate up to 2 days. Flake cold leftovers over a salad or into tacos.', null, 'owned', array['fish', 'milk']::text[], array['fish']::text[], array['pescatarian', 'gluten_free']::text[], array['sweet paprika', 'smoked paprika', 'garlic powder', 'onion powder', 'dried thyme', 'dried oregano', 'cayenne pepper', 'salmon fillet', 'lemon']::text[], 'cayenne pepper|dried oregano|dried thyme|garlic powder|lemon|onion powder|salmon fillet|smoked paprika|sweet paprika',
  null, null, null, null, null, null, null, null)
