insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('0068a2a9-1ed5-407c-afec-43dc351567c1', 1, 'Spice rub', 'Mix all the spice rub ingredients in a small bowl.', null, null, null),
  ('0068a2a9-1ed5-407c-afec-43dc351567c1', 2, 'Salmon', 'Pat the salmon dry, brush the tops and sides with 2 tablespoons of the melted butter and press the rub evenly over the buttered sides.', 180, null, null),
  ('0068a2a9-1ed5-407c-afec-43dc351567c1', 3, 'Salmon', 'Turn on the exhaust fan and open a window. Heat a large cast-iron skillet over medium-high heat until very hot, about 5 minutes.', 300, null, null),
  ('0068a2a9-1ed5-407c-afec-43dc351567c1', 4, 'Salmon', 'Add the oil, then lay the fillets in, seasoned side down. Cook without moving until a dark crust forms, 3 minutes.', 180, null, null),
  ('0068a2a9-1ed5-407c-afec-43dc351567c1', 5, 'Salmon', 'Flip and cook until the fish flakes easily and reaches 145°F in the thickest part, 2–4 minutes more.', 180, null, 62.8),
  ('0068a2a9-1ed5-407c-afec-43dc351567c1', 6, 'Salmon', 'Drizzle with the remaining butter and serve with lemon wedges.', 60, null, null);

