values ('2889c26e-215c-4098-afe0-43fb87d43a7d', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-and-drop-dumplings', 'chicken-and-dumplings-2889c2', 'Chicken and Dumplings', 'Tender shredded chicken in a creamy, thyme-scented stew topped with fluffy drop dumplings that steam right in the pot — Southern comfort in a bowl.', 'southern', 2, 20, 55, 75, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['comfort', 'kid-friendly', 'one-pot', 'budget']::text[], array['Resist peeking while the dumplings cook — the trapped steam is what makes them light.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['comfort', 'soup', 'main', 'dinner', 'budget']::text[], array['stew', 'boil']::text[], array['rich', 'fresh']::text[], '{}'::text[], 'American South', 'traditional', 'chicken-and-dumplings', 'classic', 'Refrigerate up to 3 days; the dumplings soak up liquid, so add a splash of stock when reheating over low heat.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], array['chicken']::text[], '{}'::text[], array['yellow onion', 'carrot', 'celery', 'garlic', 'chicken stock', 'dried thyme', 'bay leaf', 'heavy cream', 'baking powder', 'milk', 'parsley chive']::text[], 'baking powder|bay leaf|carrot|celery|chicken stock|dried thyme|garlic|heavy cream|milk|parsley chive|yellow onion',
  null, null, null, null, null, null, null, null)
