delete from public.recipe_instructions where recipe_id = '2889c26e-215c-4098-afe0-43fb87d43a7d';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('2889c26e-215c-4098-afe0-43fb87d43a7d', 1, 'Stew', 'Melt the butter in a Dutch oven over medium heat. Cook the onion, carrots and celery until softened, about 6 minutes, then add the garlic for 1 minute.', 420, null, null),
  ('2889c26e-215c-4098-afe0-43fb87d43a7d', 2, 'Stew', 'Sprinkle in the flour and stir 1 minute. Slowly whisk in the stock until smooth, then add the chicken, thyme, bay leaf, salt and pepper.', 180, null, null),
  ('2889c26e-215c-4098-afe0-43fb87d43a7d', 3, 'Stew', 'Bring to a boil, lower to a gentle simmer, cover and cook until the chicken is 165°F in the thickest piece, 20–25 minutes. Lift out the chicken, shred it with two forks and return it to the pot. Discard the bay leaf and stir in the cream.', 1500, null, 73.9),
  ('2889c26e-215c-4098-afe0-43fb87d43a7d', 4, 'Dumplings', 'While the chicken cooks, whisk the flour, baking powder and salt in a bowl. Rub in the butter with your fingertips until it looks like coarse crumbs, then stir in the milk and herbs just until a sticky dough forms — don''t overmix.', 300, null, null),
  ('2889c26e-215c-4098-afe0-43fb87d43a7d', 5, 'Dumplings', 'Keep the stew at a gentle simmer and drop the dough on top in 12 heaping spoonfuls, spaced apart. Cover tightly and simmer without lifting the lid for 15 minutes, until the dumplings are puffed and fluffy all the way through, not doughy, when you break one open.', 900, null, null),
  ('2889c26e-215c-4098-afe0-43fb87d43a7d', 6, 'Dumplings', 'Turn off the heat and let it stand 5 minutes, then ladle into bowls.', 300, null, null);

