values ('bebf3b81-c645-4b21-9e1c-fb7243f70eda', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'creamy-tuna-noodle-casserole-from-scratch', 'tuna-noodle-casserole-bebf3b', 'Tuna Noodle Casserole', 'Egg noodles, tuna and peas in a creamy cheddar and mushroom sauce under a crunchy buttered crumb topping — the pantry-staple casserole, with a from-scratch sauce instead of canned soup.', 'american', 1, 15, 40, 55, 6, 'main', null, 0, array['stove', 'oven']::text[], array['budget', 'kid-friendly', 'make-ahead', 'comfort']::text[], array['Canned salmon or 2 cups shredded cooked chicken can stand in for the tuna.']::text[], null, null, null, null, null, null, null, 'public', false,
