insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('bebf3b81-c645-4b21-9e1c-fb7243f70eda', 1, 'Casserole', 'Heat the oven to 375°F and butter a 9×13-inch baking dish. Cook the noodles in salted boiling water for 2 minutes less than the package says, drain and set aside.', 480, 190.6, null),
  ('bebf3b81-c645-4b21-9e1c-fb7243f70eda', 2, 'Casserole', 'In the same pot, melt the butter over medium heat. Add the mushrooms, onion and celery and cook until softened and the mushroom liquid has cooked off, about 8 minutes. Add the garlic for 1 minute.', 540, null, null),
  ('bebf3b81-c645-4b21-9e1c-fb7243f70eda', 3, 'Casserole', 'Sprinkle in the flour and stir 1 minute. Slowly whisk in the milk and stock and simmer, stirring, until thick enough to coat a spoon, 4–5 minutes.', 360, null, null),
  ('bebf3b81-c645-4b21-9e1c-fb7243f70eda', 4, 'Casserole', 'Off the heat, stir in the salt, pepper, mustard and 1½ cups of the cheddar until melted. Fold in the noodles, tuna and peas and spread in the baking dish.', 120, null, null),
  ('bebf3b81-c645-4b21-9e1c-fb7243f70eda', 5, 'Topping', 'Toss the panko with the melted butter and scatter over the top with the remaining cheddar.', 60, null, null),
  ('bebf3b81-c645-4b21-9e1c-fb7243f70eda', 6, 'Topping', 'Bake until bubbling at the edges and golden on top, 20–25 minutes. Let it stand 5 minutes before serving.', 1500, 190.6, null);

