values ('41b61ef9-68c6-467e-b637-326b2b70a21b', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'creamy-mushroom-stroganoff-noodles', 'mushroom-stroganoff-41b61e', 'Mushroom Stroganoff', 'Meaty browned mushrooms in a paprika, mustard and sour cream sauce over buttered egg noodles — a meatless take on the Russian classic, with mushrooms and a dash of soy sauce standing in for the beef.', 'russian', 1, 15, 30, 45, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'comfort', 'meatless-monday']::text[], array['Plain cremini mushrooms work fine if that''s all your store has; the shiitake and king trumpet add a meatier bite.']::text[], 'https://images.pexels.com/photos/15820588/pexels-photo-15820588.jpeg', 'Ribbon noodles in a creamy mushroom sauce topped with green onions', 'Ana Palade', 'https://www.pexels.com/@ana-palade-470459090/', 'https://www.pexels.com/photo/noodles-with-mushrooms-15820588/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'quick', 'main', 'dinner']::text[], array['stew', 'boil']::text[], array['smoky', 'fresh', 'savory']::text[], '{}'::text[], null, 'adapted', 'mushroom-stroganoff', 'classic', 'Refrigerate the sauce up to 3 days and reheat gently without boiling; cook noodles fresh.', null, 'owned', array['egg', 'gluten', 'milk', 'soy', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['mixed mushroom', 'yellow onion', 'garlic', 'smoked paprika', 'thyme leave', 'vegetable stock', 'soy sauce', 'dijon mustard', 'sour cream', 'egg noodle', 'dill parsley']::text[], 'dijon mustard|dill parsley|egg noodle|garlic|mixed mushroom|smoked paprika|sour cream|soy sauce|thyme leave|vegetable stock|yellow onion',
  null, null, null, null, null, null, null, null)
