insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('41b61ef9-68c6-467e-b637-326b2b70a21b', 1, null, 'Bring a large pot of salted water to a boil for the noodles.', 600, null, null),
  ('41b61ef9-68c6-467e-b637-326b2b70a21b', 2, null, 'Heat 1½ tablespoons of the oil in a large skillet over high heat. Add half the mushrooms and ¼ teaspoon salt and cook, stirring only now and then, until browned and their liquid has cooked off, about 5 minutes. Tip into a bowl and repeat with the remaining oil and mushrooms.', 600, null, null),
  ('41b61ef9-68c6-467e-b637-326b2b70a21b', 3, null, 'Lower the heat to medium, melt 2 tablespoons of the butter and cook the onion until soft and golden, 5 minutes. Stir in the garlic, paprika and thyme for 1 minute, then the flour for 1 minute.', 420, null, null),
  ('41b61ef9-68c6-467e-b637-326b2b70a21b', 4, null, 'Add the wine if using and let it bubble away, then stir in the stock, soy sauce, mustard and remaining salt. Simmer until slightly thickened, 3–4 minutes, and return the mushrooms.', 300, null, null),
  ('41b61ef9-68c6-467e-b637-326b2b70a21b', 5, null, 'Meanwhile, cook the noodles until tender, drain and toss with the remaining butter.', 420, null, null),
  ('41b61ef9-68c6-467e-b637-326b2b70a21b', 6, null, 'Take the skillet off the heat and stir in the sour cream and pepper — don''t let it boil or it may split. Spoon over the noodles and sprinkle with dill.', 60, null, null);

