values ('488103b2-a9bb-4688-af76-56acc1dedbeb', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'baja-beer-battered-fish-tacos', 'baja-fish-tacos-488103', 'Baja Fish Tacos', 'Light, crunchy beer-battered white fish in warm corn tortillas with shredded cabbage, pico de gallo and a tangy lime crema, the way they''re served at Ensenada street stands.', 'mexican', 2, 20, 25, 45, 4, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['entertaining', 'summer']::text[], array['Mix the batter right before frying — the bubbles in the beer are what make it light.', 'Let the oil cool completely before straining it into a jar to reuse once more, or seal it in a container for the trash; never pour it down the drain.']::text[], 'https://images.pexels.com/photos/35983504/pexels-photo-35983504.jpeg', 'Crispy fried fish taco with fresh salsa, lettuce and a lemon wedge on a dark plate', 'Matthew Baxter', 'https://www.pexels.com/@matthew-baxter-1366354232/', 'https://www.pexels.com/photo/crispy-fish-taco-with-fresh-salsa-on-dark-plate-35983504/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner', 'entertaining']::text[], array['fry']::text[], array['tangy', 'fresh']::text[], '{}'::text[], 'Baja California', 'traditional', 'baja-fish-tacos', 'classic', 'Best eaten right away. Leftover fish re-crisps in a 400°F oven for 6–8 minutes; the crema keeps 4 days refrigerated.', 'Deep-frying: use a heavy pot no more than half full of oil, a thermometer to hold the temperature, and dry food so the oil doesn''t spit. Keep children and pets away, never leave the pot unattended, and keep a lid nearby — never put water on an oil fire.', 'owned', array['egg', 'fish', 'gluten', 'milk', 'wheat']::text[], array['fish']::text[], array['pescatarian']::text[], array['sour cream', 'mayonnaise', 'lime juice', 'milk', 'cod fillet', 'baking powder', 'dried oregano', 'garlic powder', 'lager beer', 'corn tortilla', 'green cabbage', 'de gallo', 'cilantro', 'lime']::text[], 'baking powder|cilantro|cod fillet|corn tortilla|de gallo|dried oregano|garlic powder|green cabbage|lager beer|lime|lime juice|mayonnaise|milk|sour cream',
  null, null, null, null, null, null, null, null)
