values ('6d5b43bc-526e-49e7-8e2a-c31df2e29f8a', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'spiced-shrimp-tacos-lime-crema', 'shrimp-tacos-with-lime-crema-6d5b43', 'Shrimp Tacos with Lime Crema', 'Chili-and-cumin-spiced shrimp seared in minutes and tucked into warm tortillas with crunchy cabbage slaw, avocado and a zesty lime crema; a weeknight Mexican-American taco that uses sour cream in place of Mexican crema.', 'mexican', 1, 15, 10, 25, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'quick', 'kid-friendly']::text[], array['Flour tortillas work too if your family prefers them.', 'For kids, leave the shrimp unspiced except for salt and garlic powder and let the grown-ups add hot sauce at the table.']::text[], 'https://images.pexels.com/photos/10296433/pexels-photo-10296433.jpeg', 'Shrimp tacos with creamy sauce and fresh vegetables', 'Shameel mukkath', 'https://www.pexels.com/@shameel-mukkath-3421394/', 'https://www.pexels.com/photo/close-up-shot-of-shrimp-tacos-10296433/', 'pexels', true, 'public', false,
  'pending_review', array['quick', 'main', 'dinner', 'comfort']::text[], '{}'::text[], array['spicy', 'smoky', 'tangy', 'fresh', 'aromatic']::text[], '{}'::text[], null, 'adapted', 'shrimp-tacos', 'classic', 'Best fresh. Refrigerate cooked shrimp up to 2 days and the crema up to 4 days; the slaw softens overnight.', null, 'owned', array['milk', 'shellfish']::text[], array['shellfish']::text[], array['pescatarian', 'gluten_free']::text[], array['sour cream', 'lime', 'garlic', 'red cabbage', 'cilantro', 'lime juice', 'shrimp', 'chili powder', 'ground cumin', 'smoked paprika', 'garlic powder', 'corn tortilla', 'avocado']::text[], 'avocado|chili powder|cilantro|corn tortilla|garlic|garlic powder|ground cumin|lime|lime juice|red cabbage|shrimp|smoked paprika|sour cream',
  null, null, null, null, null, null, null, null)
