insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('6d5b43bc-526e-49e7-8e2a-c31df2e29f8a', 1, 'Lime crema', 'Stir the sour cream, lime zest, 1 tablespoon of the lime juice, the garlic and salt together. Thin with a little more lime juice until drizzly.', 120, null, null),
  ('6d5b43bc-526e-49e7-8e2a-c31df2e29f8a', 2, 'Slaw', 'Toss the cabbage, cilantro, lime juice and salt together and set aside to soften slightly.', 120, null, null),
  ('6d5b43bc-526e-49e7-8e2a-c31df2e29f8a', 3, 'Shrimp', 'Pat the shrimp dry and toss with the chili powder, cumin, paprika, garlic powder, salt and 1 tablespoon of the oil.', 120, null, null),
  ('6d5b43bc-526e-49e7-8e2a-c31df2e29f8a', 4, 'Shrimp', 'Heat the remaining oil in a large skillet over medium-high heat. Add the shrimp in a single layer (in two batches if needed) and cook until pink, opaque and 145°F, 1½–2 minutes per side.', 240, null, 62.8),
  ('6d5b43bc-526e-49e7-8e2a-c31df2e29f8a', 5, 'Tacos', 'Warm the tortillas in a dry skillet or directly over a gas flame for a few seconds per side and wrap in a towel.', 180, null, null),
  ('6d5b43bc-526e-49e7-8e2a-c31df2e29f8a', 6, 'Tacos', 'Fill the tortillas with slaw, shrimp and avocado, drizzle with lime crema and serve with lime wedges.', 120, null, null);

