values ('2820f0ef-63f6-446b-af71-e82ec6302e8c', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'citrus-garlic-grilled-carne-asada', 'carne-asada-2820f0', 'Carne Asada', 'Skirt steak marinated in orange, lime, garlic, cilantro and cumin, grilled hot and fast, then sliced thin for tacos with onion, cilantro and salsa — northern Mexico''s backyard cookout favorite.', 'mexican', 2, 15, 15, 150, 6, 'main', null, 120, array['grill', 'cast_iron']::text[], array['grilling', 'entertaining', 'summer', 'make-ahead']::text[], array['Skirt steak is thin and cooks quickly — use an instant-read thermometer so it doesn''t go past medium and turn chewy.']::text[], 'https://images.unsplash.com/photo-1779414518295-b03b6c60921b', 'Grilled sliced beef with roasted jalapeños and onions, served with salsas and tortillas', 'Luis Cortes', 'https://unsplash.com/@luiscortestamez', 'https://unsplash.com/photos/carne-asada-with-salsas-tortillas-and-pickled-onions-eQ83dvlvi0E', 'unsplash', true, 'public', false,
  'pending_review', array['grilling', 'main', 'dinner', 'holiday', 'entertaining']::text[], array['grill']::text[], array['spicy', 'tangy', 'fresh', 'aromatic']::text[], array['july-4th', 'game-day']::text[], 'Northern Mexico', 'traditional', 'carne-asada', 'classic', 'Refrigerate sliced steak up to 3 days. Reheat briefly in a hot skillet for tacos, burritos or nachos.', null, 'owned', '{}'::text[], array['beef']::text[], array['gluten_free', 'dairy_free']::text[], array['orange juice', 'lime juice', 'garlic', 'jalapeno', 'cilantro', 'ground cumin', 'chile powder', 'skirt steak', 'corn tortilla', 'white onion', 'salsa', 'lime']::text[], 'chile powder|cilantro|corn tortilla|garlic|ground cumin|jalapeno|lime|lime juice|orange juice|salsa|skirt steak|white onion',
  null, null, null, null, null, null, null, null)
