insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('2820f0ef-63f6-446b-af71-e82ec6302e8c', 1, 'Marinade', 'Whisk all the marinade ingredients together in a bowl.', 180, null, null),
  ('2820f0ef-63f6-446b-af71-e82ec6302e8c', 2, 'Steak', 'Put the steak in a zip-top bag, pour in the marinade, seal and refrigerate at least 2 hours and no more than 8 — the citrus turns the meat mushy if left longer.', 7200, null, null),
  ('2820f0ef-63f6-446b-af71-e82ec6302e8c', 3, 'Steak', 'Heat a grill to high (or a large cast-iron skillet over high heat until smoking). Lift the steak out, let the excess drip off and pat it fairly dry; discard the used marinade.', 600, null, null),
  ('2820f0ef-63f6-446b-af71-e82ec6302e8c', 4, 'Steak', 'Grill until well charred and 145°F in the thickest part, 3–5 minutes per side for skirt (5–7 for thicker flank). Move to a board and rest 5 minutes.', 600, null, 62.8),
  ('2820f0ef-63f6-446b-af71-e82ec6302e8c', 5, 'Steak', 'Slice thinly across the grain — on skirt steak the grain runs across the short width, so cut the steak into 5-inch sections first, turn each one and slice.', 180, null, null),
  ('2820f0ef-63f6-446b-af71-e82ec6302e8c', 6, 'To serve', 'Pile onto warm tortillas and top with onion, cilantro, salsa and a squeeze of lime.', 120, null, null);

-- Coconut Shrimp
