values ('c0db9a05-b2ed-42d9-81d0-55bea7387572', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'golden-coconut-shrimp-marmalade-dip', 'coconut-shrimp-c0db9a', 'Coconut Shrimp', 'Big shrimp in a crunchy coconut-panko coating, shallow-fried until golden and served with a sweet-tangy orange marmalade and lime dipping sauce.', 'american', 2, 20, 15, 35, 6, 'starter', null, 0, array['stove']::text[], array['entertaining', 'game-day', 'kid-friendly']::text[], array['Air-fryer option: spray the coated shrimp with oil and cook at 400°F for 8–10 minutes, flipping halfway.', 'Prefer sweet chili sauce for dipping? Some Thai sweet chili sauces contain fish sauce, so read the label if anyone has a fish allergy.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['appetizer', 'holiday', 'comfort', 'entertaining']::text[], '{}'::text[], array['spicy', 'tangy']::text[], array['game-day', 'new-year']::text[], null, null, 'coconut-shrimp', 'classic', 'Best hot. Coated, uncooked shrimp can be frozen on a tray, then bagged, for up to 1 month; fry from frozen, adding 1 minute.', 'Deep-frying: use a heavy pot no more than half full of oil, a thermometer to hold the temperature, and dry food so the oil doesn''t spit. Keep children and pets away, never leave the pot unattended, and keep a lid nearby — never put water on an oil fire.', 'owned', array['egg', 'gluten', 'shellfish', 'wheat']::text[], array['shellfish']::text[], array['pescatarian', 'dairy_free']::text[], array['orange marmalade', 'lime juice', 'prepared horseradish', 'shrimp', 'cayenne pepper', 'egg', 'sweetened coconut', 'panko breadcrumb']::text[], 'cayenne pepper|egg|lime juice|orange marmalade|panko breadcrumb|prepared horseradish|shrimp|sweetened coconut',
  null, null, null, null, null, null, null, null)
