insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('c0db9a05-b2ed-42d9-81d0-55bea7387572', 1, 'Dipping sauce', '½ cup orange marmalade', 'orange marmalade', 0.5, 'cup', null, false),
  ('c0db9a05-b2ed-42d9-81d0-55bea7387572', 2, 'Dipping sauce', '1 tbsp fresh lime juice', 'fresh lime juice', 1, 'tbsp', null, false),
  ('c0db9a05-b2ed-42d9-81d0-55bea7387572', 3, 'Dipping sauce', '1 tsp prepared horseradish, or a pinch of red pepper flakes', 'prepared horseradish', 1, 'tsp', 'or a pinch of red pepper flakes', false),
  ('c0db9a05-b2ed-42d9-81d0-55bea7387572', 4, 'Shrimp', '1 lb large shrimp, 21–25 per lb, peeled and deveined with tails left on', 'large shrimp', 1, 'lb', '21–25 per lb, peeled and deveined with tails left on', false),
  ('c0db9a05-b2ed-42d9-81d0-55bea7387572', 5, 'Shrimp', '½ cup all-purpose flour', 'all-purpose flour', 0.5, 'cup', null, false),
  ('c0db9a05-b2ed-42d9-81d0-55bea7387572', 6, 'Shrimp', '½ tsp kosher salt, plus more to finish', 'kosher salt', 0.5, 'tsp', 'plus more to finish', false),
  ('c0db9a05-b2ed-42d9-81d0-55bea7387572', 7, 'Shrimp', '¼ tsp cayenne pepper', 'cayenne pepper', 0.25, 'tsp', null, false),
  ('c0db9a05-b2ed-42d9-81d0-55bea7387572', 8, 'Shrimp', '2 large eggs, beaten', 'large eggs', 2, null, 'beaten', false),
  ('c0db9a05-b2ed-42d9-81d0-55bea7387572', 9, 'Shrimp', '1 cup sweetened shredded coconut', 'sweetened shredded coconut', 1, 'cup', null, false),
  ('c0db9a05-b2ed-42d9-81d0-55bea7387572', 10, 'Shrimp', '¾ cup panko breadcrumbs', 'panko breadcrumbs', 0.75, 'cup', null, false),
  ('c0db9a05-b2ed-42d9-81d0-55bea7387572', 11, 'Shrimp', '3 cups vegetable oil, for frying', 'vegetable oil', 3, 'cup', 'for frying', false);
delete from public.recipe_instructions where recipe_id = 'c0db9a05-b2ed-42d9-81d0-55bea7387572';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('c0db9a05-b2ed-42d9-81d0-55bea7387572', 1, 'Dipping sauce', 'Stir the marmalade, lime juice and horseradish together in a small bowl.', 60, null, null),
  ('c0db9a05-b2ed-42d9-81d0-55bea7387572', 2, 'Shrimp', 'Pat the shrimp dry. Set up three shallow bowls: flour mixed with the salt and cayenne; beaten eggs; and coconut mixed with panko.', 180, null, null),
  ('c0db9a05-b2ed-42d9-81d0-55bea7387572', 3, 'Shrimp', 'Holding each shrimp by the tail, coat it in flour, dip in egg, then press firmly into the coconut mixture. Set on a tray in a single layer.', 600, null, null),
  ('c0db9a05-b2ed-42d9-81d0-55bea7387572', 4, 'Shrimp', 'Pour the oil into a large, deep skillet to a depth of about ¾ inch (no more than half full) and heat over medium heat to 350°F. Set a wire rack over a sheet pan for draining.', 360, 176.7, null),
  ('c0db9a05-b2ed-42d9-81d0-55bea7387572', 5, 'Shrimp', 'Fry in batches of 6–8, without crowding, until golden brown and the shrimp are opaque and 145°F, about 1–1½ minutes per side. Coconut browns fast, so lower the heat if it darkens too quickly.', 480, 176.7, 62.8),
  ('c0db9a05-b2ed-42d9-81d0-55bea7387572', 6, 'Shrimp', 'Drain on the rack, sprinkle with a pinch of salt and serve hot with the dipping sauce.', 60, null, null);

-- Shrimp Po' Boy
