values ('ea6850dd-96d3-473d-95d1-690d4ccb07de', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'fried-shrimp-po-boy-remoulade', 'shrimp-po-boy-ea6850', 'Shrimp Po'' Boy', 'Cornmeal-crusted fried shrimp piled into crusty New Orleans French bread with shredded lettuce, tomato, pickles and a tangy Creole remoulade.', 'cajun_creole', 2, 25, 25, 50, 4, 'main', null, 0, array['stove', 'oven', 'dutch_oven']::text[], array['game-day', 'entertaining']::text[], array['Cajun seasoning blends are often very salty — taste yours, and cut the added salt if needed.', 'A soft hoagie roll or a split baguette works if you can''t find New Orleans-style French bread.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['lunch', 'main', 'dinner', 'holiday', 'entertaining']::text[], '{}'::text[], array['tangy', 'fresh']::text[], array['game-day']::text[], 'Louisiana', 'traditional', 'shrimp-po-boy', 'classic', 'Best assembled and eaten right away. Fried shrimp re-crisp in a 400°F oven for 5–6 minutes; the remoulade keeps 5 days refrigerated.', 'Deep-frying: use a heavy pot no more than half full of oil, a thermometer to hold the temperature, and dry food so the oil doesn''t spit. Keep children and pets away, never leave the pot unattended, and keep a lid nearby — never put water on an oil fire.', 'owned', array['egg', 'gluten', 'milk', 'shellfish', 'wheat']::text[], array['shellfish']::text[], array['pescatarian']::text[], array['mayonnaise', 'creole mustard', 'lemon juice', 'paprika', 'prepared horseradish', 'dill pickle', 'caper', 'garlic', 'scallion', 'shrimp', 'buttermilk', 'louisiana-style sauce', 'yellow cornmeal', 'cajun seasoning', 'bread roll', 'iceberg lettuce', 'tomato', 'pickle chip']::text[], 'bread roll|buttermilk|cajun seasoning|caper|creole mustard|dill pickle|garlic|iceberg lettuce|lemon juice|louisiana-style sauce|mayonnaise|paprika|pickle chip|prepared horseradish|scallion|shrimp|tomato|yellow cornmeal',
  null, null, null, null, null, null, null, null)
