  ('ea6850dd-96d3-473d-95d1-690d4ccb07de', 16, 'Shrimp', '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('ea6850dd-96d3-473d-95d1-690d4ccb07de', 17, 'Shrimp', '8 cups vegetable oil, for frying', 'vegetable oil', 8, 'cup', 'for frying', false),
  ('ea6850dd-96d3-473d-95d1-690d4ccb07de', 18, 'Sandwiches', '4 French bread rolls, about 8 inches, light and crusty, split', 'French bread rolls', 4, null, 'about 8 inches, light and crusty, split', false),
  ('ea6850dd-96d3-473d-95d1-690d4ccb07de', 19, 'Sandwiches', '2 cups shredded iceberg lettuce', 'shredded iceberg lettuce', 2, 'cup', null, false),
  ('ea6850dd-96d3-473d-95d1-690d4ccb07de', 20, 'Sandwiches', '2 ripe tomatoes, thinly sliced', 'ripe tomatoes', 2, null, 'thinly sliced', false),
