insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('ea6850dd-96d3-473d-95d1-690d4ccb07de', 1, 'Remoulade', 'Stir all the remoulade ingredients together and refrigerate while you fry.', 180, null, null),
  ('ea6850dd-96d3-473d-95d1-690d4ccb07de', 2, 'Shrimp', 'Stir the shrimp into the buttermilk and hot sauce and let sit 10–15 minutes. In a shallow dish, whisk the cornmeal, flour, Cajun seasoning and salt.', 720, null, null),
  ('ea6850dd-96d3-473d-95d1-690d4ccb07de', 3, 'Shrimp', 'Pour the oil into a heavy Dutch oven to a depth of about 2 inches — never more than half full — and heat over medium-high to 350°F. Set a wire rack on a sheet pan. Heat the oven to 400°F for the bread.', 600, 176.7, null),
  ('ea6850dd-96d3-473d-95d1-690d4ccb07de', 4, 'Shrimp', 'Lift the shrimp from the buttermilk a handful at a time, let the excess drip off and toss in the cornmeal mixture to coat. Fry in batches without crowding until golden and crisp and the shrimp are opaque and 145°F, 2–3 minutes. Drain on the rack.', 720, 176.7, 62.8),
  ('ea6850dd-96d3-473d-95d1-690d4ccb07de', 5, 'Sandwiches', 'Toast the split rolls cut-side up in the oven until warm and lightly crisp, 3–4 minutes.', 240, 204.4, null),
  ('ea6850dd-96d3-473d-95d1-690d4ccb07de', 6, 'Sandwiches', 'Spread both sides of each roll with remoulade, then layer lettuce, tomato, pickles and a generous pile of shrimp. Serve right away.', 180, null, null);

