values ('0c38e802-b577-4339-9905-8bbbe217dda4', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'orange-chicken', 'orange-chicken-0c38e8', 'Orange Chicken', 'Crisp nuggets of chicken thigh tossed in a sticky, tangy glaze of fresh orange juice and zest — the American-Chinese takeout favorite, shallow-fried in a skillet instead of a deep fryer.', 'chinese', 2, 20, 25, 45, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'kid-friendly', 'takeout']::text[], array['Toss the chicken with the sauce at the last moment — the glaze softens the crust within about 10 minutes.', 'Air-fryer option: spray the coated chicken with oil and cook at 400°F for 12–14 minutes, shaking halfway, until it reaches 165°F.']::text[], 'https://images.pexels.com/photos/12916862/pexels-photo-12916862.jpeg', 'Crispy orange chicken with steamed rice, sesame seeds and parsley', 'Denys Gromov', 'https://www.pexels.com/@jdgromov/', 'https://www.pexels.com/photo/orange-chicken-and-rice-on-a-plate-12916862/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner']::text[], array['stew']::text[], array['spicy', 'tangy', 'savory']::text[], '{}'::text[], null, 'adapted', 'orange-chicken', 'classic', 'Refrigerate chicken and sauce separately up to 3 days. Re-crisp the chicken in a 400°F oven or air fryer for 8 minutes before saucing.', null, 'owned', array['egg', 'gluten', 'soy', 'wheat']::text[], array['chicken']::text[], array['dairy_free']::text[], array['egg', 'soy sauce', 'cornstarch', 'orange zest', 'orange juice', 'rice vinegar', 'garlic', 'ginger', 'scallion', 'white rice']::text[], 'cornstarch|egg|garlic|ginger|orange juice|orange zest|rice vinegar|scallion|soy sauce|white rice',
  null, null, null, null, null, null, null, null)
