values ('f8af1e12-1edc-4d0b-a0e7-96a2cb5766d2', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'general-tsos-chicken', 'general-tso-s-chicken-f8af1e', 'General Tso''s Chicken', 'Twice-fried chicken in a sweet, garlicky, gently spicy glaze studded with dried chiles — the American-Chinese restaurant classic, a sweeter take on a Hunan-style dish, fried at home in a heavy pot.', 'chinese', 2, 20, 30, 50, 4, 'main', null, 0, array['stove']::text[], array['takeout', 'entertaining']::text[], array['Want more heat? Stir 1–2 teaspoons of chili garlic sauce into the sauce.', 'Let the oil cool completely, then strain it into a jar for one more fry or seal it in a container for the trash — never pour it down the sink.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner', 'entertaining']::text[], array['fry', 'stir_fry']::text[], array['tangy', 'savory']::text[], '{}'::text[], null, 'adapted', 'general-tsos-chicken', 'classic', 'Refrigerate up to 3 days. Re-crisp in a 400°F oven or air fryer for 8–10 minutes; the coating won''t be quite as crunchy.', null, 'owned', array['egg', 'gluten', 'soy', 'wheat']::text[], array['chicken']::text[], array['dairy_free']::text[], array['soy sauce', 'shaoxing wine', 'egg white', 'cornstarch', 'hoisin sauce', 'rice vinegar', 'red chile', 'garlic', 'ginger', 'scallion', 'white rice']::text[], 'cornstarch|egg white|garlic|ginger|hoisin sauce|red chile|rice vinegar|scallion|shaoxing wine|soy sauce|white rice',
