delete from public.recipe_instructions where recipe_id = 'f8af1e12-1edc-4d0b-a0e7-96a2cb5766d2';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('f8af1e12-1edc-4d0b-a0e7-96a2cb5766d2', 1, 'Chicken', 'Toss the chicken with the soy sauce, Shaoxing wine and egg white, then add the cornstarch and stir until every piece is coated in a thick paste. Let it sit while you make the sauce.', 600, null, null),
  ('f8af1e12-1edc-4d0b-a0e7-96a2cb5766d2', 2, 'Sauce', 'Whisk the soy sauce, hoisin, vinegar, sugar, cornstarch and water together until the sugar dissolves.', null, null, null),
  ('f8af1e12-1edc-4d0b-a0e7-96a2cb5766d2', 3, 'Chicken', 'Pour the oil into a heavy pot or wok no more than half full and heat to 350°F. Keep children and pets away and never leave hot oil unattended.', 600, 176.7, null),
  ('f8af1e12-1edc-4d0b-a0e7-96a2cb5766d2', 4, 'Chicken', 'Fry the chicken in 3 batches, dropping the pieces in one at a time so they don''t stick, until pale golden, about 3 minutes per batch. Drain on a rack.', 540, 176.7, null),
  ('f8af1e12-1edc-4d0b-a0e7-96a2cb5766d2', 5, 'Chicken', 'Raise the oil to 375°F and fry the chicken again in 2 batches until deep golden, very crisp and 165°F inside, 1–2 minutes. Drain.', 240, 190.6, 73.9),
  ('f8af1e12-1edc-4d0b-a0e7-96a2cb5766d2', 6, 'Stir-fry', 'Heat the 1 tablespoon oil in a clean wok or skillet over medium heat. Add the chiles and stir until they darken, about 30 seconds, then the garlic, ginger and scallion whites for 30 seconds more.', 60, null, null),
  ('f8af1e12-1edc-4d0b-a0e7-96a2cb5766d2', 7, null, 'Stir the sauce, pour it in and bubble until thick and glossy, about 1 minute. Add the chicken, toss to coat, scatter with scallion greens and serve with rice and broccoli.', 120, null, null);

