values ('e5fb67ca-a031-4c11-88fd-31c8975834ac', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'sesame-chicken', 'sesame-chicken-e5fb67', 'Sesame Chicken', 'Golden chicken bites in a sticky honey-soy glaze showered with toasted sesame seeds — the takeout favorite, pan-fried in a thin layer of oil and sweetened with honey.', 'chinese', 2, 15, 20, 35, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'kid-friendly', 'takeout']::text[], array['Toast sesame seeds in a dry skillet over medium heat, shaking, until golden, 2–3 minutes — they burn quickly once they color.', 'Don''t give honey to babies under 12 months old.']::text[], 'https://images.pexels.com/photos/35081824/pexels-photo-35081824.jpeg', 'Plate of crispy sesame chicken with rice and spring onions', 'Zehra Yılmaz', 'https://www.pexels.com/@zehra-yilmaz-407275500/', 'https://www.pexels.com/photo/delicious-asian-crispy-sesame-chicken-dish-35081824/', 'pexels', true, 'public', false,
  'pending_review', array['quick', 'comfort', 'main', 'dinner']::text[], array['stew']::text[], array['tangy', 'savory']::text[], '{}'::text[], null, 'adapted', 'sesame-chicken', 'classic', 'Refrigerate up to 3 days. Reheat in a skillet with a splash of water to loosen the glaze.', null, 'owned', array['gluten', 'sesame', 'soy', 'wheat']::text[], array['chicken']::text[], array['dairy_free']::text[], array['soy sauce', 'cornstarch', 'honey', 'rice vinegar', 'ketchup', 'sesame oil', 'garlic', 'ginger', 'sesame seed', 'scallion', 'white rice']::text[], 'cornstarch|garlic|ginger|honey|ketchup|rice vinegar|scallion|sesame oil|sesame seed|soy sauce|white rice',
  null, null, null, null, null, null, null, null)
