insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('e5fb67ca-a031-4c11-88fd-31c8975834ac', 1, 'Chicken', 'Toss the chicken with the soy sauce, then with the cornstarch until each piece is evenly dusted.', 120, null, null),
  ('e5fb67ca-a031-4c11-88fd-31c8975834ac', 2, 'Sauce', 'Whisk the honey, soy sauce, vinegar, ketchup, sesame oil, garlic, ginger, cornstarch and water together.', null, null, null),
  ('e5fb67ca-a031-4c11-88fd-31c8975834ac', 3, 'Chicken', 'Heat the oil in a 12-inch nonstick skillet over medium-high until shimmering, about 350°F. Shake excess starch off the chicken and fry half of it in a single layer, turning, until golden on all sides and 165°F inside, 6–7 minutes. Drain on a rack and repeat.', 780, 176.7, 73.9),
  ('e5fb67ca-a031-4c11-88fd-31c8975834ac', 4, 'Sauce', 'Pour off all but a teaspoon of oil. Stir the sauce, add it to the skillet and simmer, stirring, until thick and glossy, 1–2 minutes.', 120, null, null),
  ('e5fb67ca-a031-4c11-88fd-31c8975834ac', 5, null, 'Return the chicken and toss until coated. Sprinkle with sesame seeds and scallions and serve over rice.', 60, null, null);

