values ('7185db48-1bd3-4957-b9d9-d0ea042131fe', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'teriyaki-chicken', 'teriyaki-chicken-7185db', 'Teriyaki Chicken', 'Juicy chicken thighs seared until crisp and glazed in a glossy soy-mirin teriyaki sauce — thickened with a little cornstarch the way American takeout spots serve it.', 'japanese', 1, 5, 20, 25, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'kid-friendly', 'budget', 'takeout']::text[], array['Double the sauce and keep half in the fridge for a week — it''s great on salmon, tofu or a quick noodle stir-fry.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['quick', 'main', 'dinner', 'budget', 'comfort']::text[], array['stew']::text[], array['savory']::text[], '{}'::text[], null, 'adapted', 'teriyaki-chicken', 'classic', 'Refrigerate up to 4 days. Reheat covered in the microwave or in a skillet with a splash of water.', null, 'owned', array['gluten', 'soy', 'wheat']::text[], array['chicken']::text[], array['dairy_free']::text[], array['chicken thigh', 'soy sauce', 'mirin', 'sake', 'brown sugar', 'ginger', 'garlic', 'cornstarch', 'short-grain rice', 'broccoli floret', 'scallion']::text[], 'broccoli floret|brown sugar|chicken thigh|cornstarch|garlic|ginger|mirin|sake|scallion|short-grain rice|soy sauce',
