insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7185db48-1bd3-4957-b9d9-d0ea042131fe', 1, 'Sauce', 'Stir the soy sauce, mirin, sake, brown sugar, ginger and garlic together in a measuring cup.', null, null, null),
  ('7185db48-1bd3-4957-b9d9-d0ea042131fe', 2, 'Chicken', 'Season the chicken with the salt. Heat the oil in a large skillet over medium heat and lay the thighs in skin-side (or smooth-side) down. Cook without moving, pressing now and then with a spatula, until deep golden and crisp, 7–8 minutes.', 480, null, null),
  ('7185db48-1bd3-4957-b9d9-d0ea042131fe', 3, 'Chicken', 'Flip and cook until the thickest part reaches 165°F, 5–6 minutes.', 360, null, 73.9),
  ('7185db48-1bd3-4957-b9d9-d0ea042131fe', 4, 'Sauce', 'Pour off the fat and wipe the pan. Add the sauce and simmer, turning the chicken often, until the sauce reduces by about half, 2–3 minutes. Stir in the cornstarch mixture and bubble until glossy, 30 seconds.', 180, null, null),
  ('7185db48-1bd3-4957-b9d9-d0ea042131fe', 5, null, 'Slice the chicken, spoon over the sauce and serve with rice, broccoli and scallions.', 60, null, null);

