values ('89a5250a-0bb8-4de4-82d8-81826197fd3f', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-lo-mein', 'chicken-lo-mein-89a525', 'Chicken Lo Mein', 'Soft egg noodles tossed with chicken, cabbage, carrots and mushrooms in a savory soy and oyster sauce — the takeout staple, made in a big skillet if you don''t own a wok.', 'chinese', 1, 20, 15, 35, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'kid-friendly', 'takeout']::text[], array['No lo mein noodles? Spaghetti cooked al dente works well.', 'For a shellfish allergy, swap the oyster sauce for a mushroom-based vegetarian stir-fry sauce or 1 extra tablespoon soy sauce plus 1 teaspoon sugar.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['quick', 'main', 'dinner', 'comfort']::text[], array['stir_fry', 'boil']::text[], array['savory']::text[], '{}'::text[], null, 'adapted', 'chicken-lo-mein', 'classic', 'Refrigerate up to 3 days. Reheat in a skillet with a splash of water.', null, 'owned', array['egg', 'gluten', 'sesame', 'shellfish', 'soy', 'wheat']::text[], array['chicken']::text[], array['dairy_free']::text[], array['soy sauce', 'cornstarch', 'oyster sauce', 'sesame oil', 'egg noodle', 'garlic', 'carrot', 'green cabbage', 'shiitake mushroom', 'scallion']::text[], 'carrot|cornstarch|egg noodle|garlic|green cabbage|oyster sauce|scallion|sesame oil|shiitake mushroom|soy sauce',
