insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('89a5250a-0bb8-4de4-82d8-81826197fd3f', 1, 'Chicken', 'Toss the chicken with the soy sauce and cornstarch.', 60, null, null),
  ('89a5250a-0bb8-4de4-82d8-81826197fd3f', 2, 'Sauce', 'Stir the soy sauces, oyster sauce, sesame oil, sugar and water together.', null, null, null),
  ('89a5250a-0bb8-4de4-82d8-81826197fd3f', 3, 'Noodles', 'Cook the noodles in boiling water 1 minute less than the package says. Drain, rinse under cold water and shake dry so they don''t clump.', 240, null, null),
  ('89a5250a-0bb8-4de4-82d8-81826197fd3f', 4, 'Chicken', 'Heat 1 tablespoon of the oil in a wok or 12-inch skillet over high heat. Add the chicken in a single layer and stir-fry until no longer pink and 165°F, 3–4 minutes. Move to a plate.', 240, null, 73.9),
  ('89a5250a-0bb8-4de4-82d8-81826197fd3f', 5, 'Noodles', 'Add the remaining oil, then the garlic, carrot, cabbage and mushrooms. Stir-fry until the cabbage wilts but still has some crunch, about 3 minutes.', 180, null, null),
  ('89a5250a-0bb8-4de4-82d8-81826197fd3f', 6, null, 'Add the noodles, chicken, sauce, scallions and bean sprouts. Toss with tongs over high heat until the noodles are hot and evenly coated, about 2 minutes. Serve right away.', 120, null, null);

-- Shrimp Fried Rice
