values ('35ccec7e-97c6-4525-9b39-e26ae9a2c0ea', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'shrimp-fried-rice', 'shrimp-fried-rice-35ccec', 'Shrimp Fried Rice', 'Day-old jasmine rice fried hot with juicy shrimp, scrambled egg, peas, carrots and scallions — faster than delivery and a great way to use up leftover rice.', 'chinese', 1, 10, 15, 25, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'kid-friendly', 'takeout', 'leftovers']::text[], array['Freshly cooked rice turns mushy. No leftovers? Spread hot rice on a sheet pan and chill it uncovered for 30 minutes first.']::text[], 'https://images.pexels.com/photos/35228296/pexels-photo-35228296.jpeg', 'Close-up of shrimp fried rice with egg and scallions', '黃Lunny 設計', 'https://www.pexels.com/@lunny-2150661847/', 'https://www.pexels.com/photo/delicious-shrimp-fried-rice-close-up-35228296/', 'pexels', true, 'public', false,
  'pending_review', array['quick', 'budget', 'main', 'dinner', 'comfort']::text[], array['stir_fry']::text[], array['savory']::text[], '{}'::text[], null, 'traditional', 'shrimp-fried-rice', 'classic', 'Cool quickly and refrigerate within 1 hour; keeps 3 days. Reheat until steaming hot all the way through.', null, 'owned', array['egg', 'gluten', 'sesame', 'shellfish', 'soy', 'wheat']::text[], array['shellfish']::text[], array['pescatarian', 'dairy_free']::text[], array['shrimp', 'white pepper', 'egg', 'garlic', 'scallion', 'pea carrot', 'jasmine rice', 'soy sauce', 'sesame oil']::text[], 'egg|garlic|jasmine rice|pea carrot|scallion|sesame oil|shrimp|soy sauce|white pepper',
  null, null, null, null, null, null, null, null)
