insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('35ccec7e-97c6-4525-9b39-e26ae9a2c0ea', 1, null, 'Season the shrimp with half the salt and the white pepper. Heat 1 tablespoon of the oil in a wok or large skillet over high heat and stir-fry the shrimp until pink and opaque all the way through (145°F), 2–3 minutes. Move to a plate.', 180, null, 62.8),
  ('35ccec7e-97c6-4525-9b39-e26ae9a2c0ea', 2, null, 'Add another tablespoon of oil, pour in the eggs and scramble until just set with no runny egg left (160°F), about 1 minute. Add to the shrimp.', 60, null, 71.1),
  ('35ccec7e-97c6-4525-9b39-e26ae9a2c0ea', 3, null, 'Add the remaining oil, the garlic, scallion whites and peas and carrots and stir-fry 2 minutes.', 120, null, null),
  ('35ccec7e-97c6-4525-9b39-e26ae9a2c0ea', 4, null, 'Add the rice and spread it across the pan. Let it sit 30 seconds to toast, then stir and repeat until the grains are hot and separate, 4–5 minutes.', 300, null, null),
  ('35ccec7e-97c6-4525-9b39-e26ae9a2c0ea', 5, null, 'Drizzle in the soy sauce and sesame oil, add the remaining salt, then return the shrimp and eggs with the scallion greens. Toss 1 minute and serve.', 60, null, null);

