insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7f682aa8-58e2-4cd8-be55-3d74b204d907', 1, null, 'Bring the stock and ginger to a simmer in a saucepan and simmer 5 minutes. Lift out the ginger.', 360, null, null),
  ('7f682aa8-58e2-4cd8-be55-3d74b204d907', 2, null, 'Stir in the soy sauce, white pepper, salt and turmeric. Stir the cornstarch mixture, pour it in while stirring and simmer until the broth thickens slightly, about 1 minute.', 120, null, null),
  ('7f682aa8-58e2-4cd8-be55-3d74b204d907', 3, null, 'Keep the broth at a gentle simmer. Stir it in a slow circle with one hand while you pour the eggs in a thin stream with the other. Stop stirring and let the ribbons set until fully cooked (160°F), about 30 seconds.', 60, null, 71.1),
  ('7f682aa8-58e2-4cd8-be55-3d74b204d907', 4, null, 'Turn off the heat, stir in the sesame oil and serve topped with scallions.', 60, null, null);

-- Hot and Sour Soup
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
