values ('c367a9ad-dfec-4a3a-b8d3-cd979e1445c9', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'hot-and-sour-soup', 'hot-and-sour-soup-c367a9', 'Hot and Sour Soup', 'A peppery, tangy broth thick with shiitakes, bamboo shoots, tofu, pork and egg ribbons — the heat comes from white pepper and the sourness from vinegar added right at the end.', 'chinese', 2, 30, 20, 50, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'comfort', 'takeout']::text[], array['Chinkiang black vinegar gives a deeper, maltier sourness — use half black vinegar and half rice vinegar. It''s usually brewed with wheat, so leave it out for a wheat allergy.', 'Add the vinegar off the heat: boiling it drives off the sharp sourness.']::text[], 'https://images.pexels.com/photos/16845596/pexels-photo-16845596.jpeg', 'Hot and sour soup garnished with greens in a black bowl', 'Huzaifa Bukhari', 'https://www.pexels.com/@huzaifabukhari/', 'https://www.pexels.com/photo/bowl-of-soup-16845596/', 'pexels', true, 'public', false,
  'pending_review', array['soup', 'comfort', 'main', 'dinner']::text[], array['stew', 'boil']::text[], array['spicy', 'tangy', 'savory']::text[], '{}'::text[], null, 'traditional', 'hot-and-sour-soup', 'classic', 'Refrigerate up to 3 days. The sourness fades, so add a splash of vinegar when you reheat.', null, 'owned', array['egg', 'gluten', 'sesame', 'soy', 'wheat']::text[], array['pork', 'tofu']::text[], array['dairy_free']::text[], array['shiitake mushroom', 'pork loin', 'soy sauce', 'cornstarch', 'chicken stock', 'bamboo shoot', 'tofu', 'egg', 'rice vinegar', 'white pepper', 'sesame oil', 'scallion']::text[], 'bamboo shoot|chicken stock|cornstarch|egg|pork loin|rice vinegar|scallion|sesame oil|shiitake mushroom|soy sauce|tofu|white pepper',
  null, null, null, null, null, null, null, null)
