  ('c367a9ad-dfec-4a3a-b8d3-cd979e1445c9', 11, 'Soup', '¼ cup cornstarch, mixed with ¼ cup cold water', 'cornstarch', 0.25, 'cup', 'mixed with ¼ cup cold water', false),
  ('c367a9ad-dfec-4a3a-b8d3-cd979e1445c9', 12, 'Soup', '2 large eggs, beaten', 'large eggs', 2, null, 'beaten', false),
