delete from public.recipe_instructions where recipe_id = 'c367a9ad-dfec-4a3a-b8d3-cd979e1445c9';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('c367a9ad-dfec-4a3a-b8d3-cd979e1445c9', 1, 'Soup', 'Cover the shiitakes (and wood ears, if using) with 1½ cups hot water and soak until soft, 20 minutes. Squeeze them out, keeping the liquid, trim off the shiitake stems and slice the caps thin.', 1200, null, null),
  ('c367a9ad-dfec-4a3a-b8d3-cd979e1445c9', 2, 'Soup', 'Toss the pork with the 1 teaspoon soy sauce and the 1 teaspoon cornstarch.', null, null, null),
  ('c367a9ad-dfec-4a3a-b8d3-cd979e1445c9', 3, 'Soup', 'Bring the stock and ½ cup of the soaking liquid (leave any grit behind) to a boil in a large pot. Add the mushrooms and bamboo shoots and simmer 5 minutes.', 360, null, null),
  ('c367a9ad-dfec-4a3a-b8d3-cd979e1445c9', 4, 'Soup', 'Add the pork, stirring to separate the strips, and simmer until no pink remains and it reaches 145°F, about 2 minutes. Add the tofu, 3 tablespoons soy sauce and sugar and simmer 2 minutes more.', 240, null, 62.8),
  ('c367a9ad-dfec-4a3a-b8d3-cd979e1445c9', 5, 'Soup', 'Stir the cornstarch mixture, pour it in while stirring and simmer until the soup thickens, about 1 minute. Stirring slowly, drizzle in the eggs and let them set into ribbons until fully cooked (160°F), about 30 seconds.', 120, null, 71.1),
  ('c367a9ad-dfec-4a3a-b8d3-cd979e1445c9', 6, 'Finish', 'Turn off the heat and stir in the vinegar, white pepper, sesame oil and chili oil. Taste and add more vinegar or pepper until it''s as hot and sour as you like. Serve topped with scallions.', 60, null, null);

