values ('969b50dd-131b-4668-8b8e-2c739bba69b5', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'pork-cabbage-egg-rolls', 'egg-rolls-969b50', 'Egg Rolls', 'Crackly, blistered egg rolls stuffed with a savory pork and cabbage filling — the American-Chinese takeout starter, made with store-bought wrappers and fried in a heavy pot.', 'chinese', 2, 40, 25, 65, 6, 'starter', null, 0, array['stove']::text[], array['entertaining', 'make-ahead', 'freezer-friendly', 'takeout']::text[], array['To freeze, set uncooked rolls on a tray until solid, then bag them. Fry from frozen at 325°F for 7–8 minutes so the centers heat through.', 'Air-fryer option: brush the rolls with oil and cook at 390°F for 10–12 minutes, turning halfway.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['appetizer', 'holiday', 'entertaining']::text[], array['fry']::text[], array['spicy', 'savory']::text[], array['game-day']::text[], null, 'adapted', 'egg-rolls', 'classic', 'Best hot. Refrigerate cooked rolls up to 3 days and re-crisp in a 400°F oven or air fryer for 8 minutes. Uncooked, freeze up to 3 months.', null, 'owned', array['egg', 'gluten', 'sesame', 'shellfish', 'soy', 'wheat']::text[], array['pork']::text[], array['dairy_free']::text[], array['ground pork', 'garlic', 'ginger', 'green cabbage', 'carrot', 'scallion', 'soy sauce', 'oyster sauce', 'sesame oil', 'white pepper', 'cornstarch', 'roll wrapper', 'egg', 'chili sauce']::text[], 'carrot|chili sauce|cornstarch|egg|garlic|ginger|green cabbage|ground pork|oyster sauce|roll wrapper|scallion|sesame oil|soy sauce|white pepper',
  null, null, null, null, null, null, null, null)
