  ('969b50dd-131b-4668-8b8e-2c739bba69b5', 13, 'Wrapping and frying', '12 egg roll wrappers, thawed if frozen', 'egg roll wrappers', 12, null, 'thawed if frozen', false),
  ('969b50dd-131b-4668-8b8e-2c739bba69b5', 14, 'Wrapping and frying', '1 large egg, beaten, for sealing', 'large egg', 1, null, 'beaten, for sealing', false),
  ('969b50dd-131b-4668-8b8e-2c739bba69b5', 15, 'Wrapping and frying', '6 cups vegetable oil, for deep-frying', 'vegetable oil', 6, 'cup', 'for deep-frying', false),
  ('969b50dd-131b-4668-8b8e-2c739bba69b5', 16, 'Wrapping and frying', '½ cup sweet chili sauce, for dipping', 'sweet chili sauce', 0.5, 'cup', 'for dipping', false);
delete from public.recipe_instructions where recipe_id = '969b50dd-131b-4668-8b8e-2c739bba69b5';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('969b50dd-131b-4668-8b8e-2c739bba69b5', 1, 'Filling', 'Heat the oil in a large skillet over medium-high heat. Add the pork and cook, breaking it up, until no pink remains and it reaches 160°F, about 5 minutes. Add the garlic and ginger and stir 30 seconds.', 360, null, 71.1),
  ('969b50dd-131b-4668-8b8e-2c739bba69b5', 2, 'Filling', 'Add the cabbage and carrot and cook, tossing, until wilted, 3–4 minutes. Stir in the scallions, soy sauce, oyster sauce, sesame oil, white pepper and cornstarch and cook 1 minute until no liquid pools in the pan.', 300, null, null),
  ('969b50dd-131b-4668-8b8e-2c739bba69b5', 3, 'Filling', 'Spread the filling on a sheet pan and let it cool completely, about 15 minutes — warm filling tears the wrappers.', 900, null, null),
  ('969b50dd-131b-4668-8b8e-2c739bba69b5', 4, 'Wrapping and frying', 'Set a wrapper on the counter like a diamond. Put 3 tablespoons of filling just below the center, fold the bottom corner over it, fold in the sides, then roll up tightly toward the top corner. Brush the last corner with egg and press to seal. Keep the finished rolls under a damp towel.', 900, null, null),
  ('969b50dd-131b-4668-8b8e-2c739bba69b5', 5, 'Wrapping and frying', 'Pour the oil into a heavy pot no more than half full and heat to 350°F. Keep children and pets away and never leave hot oil unattended.', 600, 176.7, null),
  ('969b50dd-131b-4668-8b8e-2c739bba69b5', 6, 'Wrapping and frying', 'Fry 3 or 4 rolls at a time, turning, until deep golden and blistered, 4–5 minutes. Drain on a rack set over a sheet pan and let the oil come back to 350°F between batches. Serve hot with sweet chili sauce.', 900, 176.7, null);

