values ('45dd87dc-fe74-4d6f-87c4-8ac987bcce10', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'scallion-pancakes', 'scallion-pancakes-45dd87', 'Scallion Pancakes', 'Flaky, chewy, many-layered flatbreads laced with scallions and pan-fried until crisp — made from a simple hot-water dough and served with a soy-vinegar dip.', 'chinese', 2, 60, 20, 80, 4, 'starter', null, 0, array['stove']::text[], array['budget', 'kid-friendly', 'make-ahead', 'freezer-friendly', 'takeout']::text[], array['Make ahead: stack shaped, uncooked pancakes between parchment and freeze in a bag. Cook from frozen over medium-low, covered for the first 3 minutes.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['appetizer', 'budget', 'comfort']::text[], array['boil']::text[], array['spicy', 'tangy', 'savory']::text[], '{}'::text[], null, 'traditional', 'scallion-pancakes', 'classic', 'Best fresh. Refrigerate cooked pancakes up to 2 days and re-crisp in a dry skillet. Uncooked, freeze up to 2 months.', null, 'owned', array['gluten', 'soy', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'dairy_free']::text[], array['boiling water', 'white pepper', 'scallion', 'soy sauce', 'rice vinegar']::text[], 'boiling water|rice vinegar|scallion|soy sauce|white pepper',
