values ('49a6783f-b064-4789-aede-08b3f08cd320', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'congee-ginger-scallion', 'congee-with-ginger-and-scallion-49a678', 'Congee with Ginger and Scallion', 'Jasmine rice simmered slowly until it melts into a silky, soothing porridge, then topped with fresh ginger, scallions, soy sauce and sesame oil.', 'cantonese', 1, 5, 75, 80, 4, 'breakfast', null, 0, array['stove']::text[], array['budget', 'comfort', 'make-ahead']::text[], array['Pressure-cooker shortcut: cook the rice, liquid and ginger on high pressure for 30 minutes and let the pressure release naturally.', 'Make it a fuller meal with a soft-boiled egg, shredded rotisserie chicken or leftover roast pork on top.']::text[], 'https://images.pexels.com/photos/32835478/pexels-photo-32835478.jpeg', 'Bowl of plain rice congee topped with sliced scallions', 'FOX ^.ᆽ.^= ∫', 'https://www.pexels.com/@fox-58267/', 'https://www.pexels.com/photo/delicious-homemade-rice-porridge-in-ceramic-bowl-32835478/', 'pexels', true, 'public', false,
  'pending_review', array['breakfast', 'comfort', 'budget']::text[], array['stew', 'boil']::text[], array['spicy', 'savory']::text[], '{}'::text[], 'Guangdong', 'traditional', 'congee', 'classic', 'Cool quickly and refrigerate within 1 hour; keeps 4 days. It sets firm when cold — loosen with water as you reheat until steaming hot.', null, 'owned', array['gluten', 'sesame', 'soy', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'dairy_free']::text[], array['jasmine rice', 'ginger', 'scallion', 'soy sauce', 'sesame oil', 'white pepper']::text[], 'ginger|jasmine rice|scallion|sesame oil|soy sauce|white pepper',
  null, null, null, null, null, null, null, null)
