delete from public.recipe_instructions where recipe_id = '49a6783f-b064-4789-aede-08b3f08cd320';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('49a6783f-b064-4789-aede-08b3f08cd320', 1, 'Congee', 'Rinse the rice in a sieve under cold water until the water runs mostly clear.', 120, null, null),
  ('49a6783f-b064-4789-aede-08b3f08cd320', 2, 'Congee', 'Put the rice, water, stock (if using) and ginger slices in a large heavy pot and bring to a boil over high heat, stirring once or twice so the rice doesn''t stick.', 600, null, null),
  ('49a6783f-b064-4789-aede-08b3f08cd320', 3, 'Congee', 'Lower the heat so it barely bubbles, set the lid ajar and simmer, stirring and scraping the bottom every 10–15 minutes, until the grains break down into a thick, creamy porridge, 60–70 minutes. Add hot water if it gets thicker than you like.', 3900, null, null),
  ('49a6783f-b064-4789-aede-08b3f08cd320', 4, 'Congee', 'Fish out the ginger slices and season with the salt.', null, null, null),
  ('49a6783f-b064-4789-aede-08b3f08cd320', 5, 'Toppings', 'Ladle into bowls and top with the ginger matchsticks, scallions, a drizzle of soy sauce and sesame oil, a pinch of white pepper and chili crisp if you like.', null, null, null);

-- Kitsune Udon
