values ('63937705-a626-4195-aa44-57face3e8e14', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'kitsune-udon', 'kitsune-udon-639377', 'Kitsune Udon', 'Thick, chewy udon in a light, golden dashi broth, crowned with sweet-savory simmered fried tofu pouches and scallions — Osaka''s classic noodle bowl.', 'japanese', 1, 10, 25, 35, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'comfort', 'kid-friendly']::text[], array['Can''t find aburaage? Canned or refrigerated seasoned inari pouches (sold for inari sushi) are already simmered — just warm them in the broth.', 'Instant dashi granules can contain wheat or soy, and shichimi togarashi usually contains sesame seeds — read the labels if you''re cooking around allergies.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['comfort', 'quick', 'main', 'dinner']::text[], array['stew', 'boil']::text[], array['savory']::text[], '{}'::text[], 'Osaka', 'traditional', 'kitsune-udon', 'classic', 'Keep the broth and simmered tofu separately in the fridge up to 3 days; cook the noodles fresh.', null, 'owned', array['fish', 'gluten', 'soy', 'wheat']::text[], array['tofu']::text[], array['pescatarian', 'dairy_free']::text[], array['aburaage', 'dashi', 'soy sauce', 'mirin', 'udon noodle', 'scallion']::text[], 'aburaage|dashi|mirin|scallion|soy sauce|udon noodle',
  null, null, null, null, null, null, null, null)
