  ('63937705-a626-4195-aa44-57face3e8e14', 4, 'Tofu', '2 tbsp mirin', 'mirin', 2, 'tbsp', null, false),
  ('63937705-a626-4195-aa44-57face3e8e14', 5, 'Tofu', '2 tbsp sugar', 'sugar', 2, 'tbsp', null, false),
  ('63937705-a626-4195-aa44-57face3e8e14', 6, 'Broth', '6 cups dashi, homemade or made from instant dashi granules', 'dashi', 6, 'cup', 'homemade or made from instant dashi granules', false),
  ('63937705-a626-4195-aa44-57face3e8e14', 7, 'Broth', '3 tbsp light soy sauce (usukuchi), or regular soy sauce', 'light soy sauce (usukuchi)', 3, 'tbsp', 'or regular soy sauce', false),
  ('63937705-a626-4195-aa44-57face3e8e14', 8, 'Broth', '2 tbsp mirin', 'mirin', 2, 'tbsp', null, false),
