insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('63937705-a626-4195-aa44-57face3e8e14', 1, 'Tofu', 'Put the aburaage in a sieve and pour boiling water over both sides to rinse off excess oil. Press out the water and cut each sheet in half on the diagonal.', 180, null, null),
  ('63937705-a626-4195-aa44-57face3e8e14', 2, 'Tofu', 'Bring the ¾ cup dashi, soy sauce, mirin and sugar to a simmer in a small saucepan. Add the tofu, cover with a small lid or round of parchment resting on the tofu, and simmer gently, turning once, until most of the liquid is absorbed, 10–12 minutes.', 720, null, null),
  ('63937705-a626-4195-aa44-57face3e8e14', 3, 'Broth', 'Meanwhile, heat the 6 cups dashi with the light soy sauce, mirin and salt until just simmering. Taste and adjust the salt.', 480, null, null),
  ('63937705-a626-4195-aa44-57face3e8e14', 4, 'Noodles', 'Cook the udon in a large pot of boiling water until separated and heated through, 1–2 minutes (or as the package says). Drain well.', 120, null, null),
  ('63937705-a626-4195-aa44-57face3e8e14', 5, 'Noodles', 'Divide the noodles among deep bowls and ladle the hot broth over. Top each with two pieces of tofu, scallions and kamaboko, and pass shichimi at the table.', 60, null, null);

