values ('1767777b-f404-4124-bcf8-3663b6a15241', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'yakisoba', 'yakisoba-176777', 'Yakisoba', 'Chewy wheat noodles stir-fried with pork, cabbage, onion and carrot in a tangy, fruity homemade yakisoba sauce — a Japanese festival and home-cooking favorite in 30 minutes.', 'japanese', 1, 15, 15, 30, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'kid-friendly', 'budget']::text[], array['Bottled yakisoba sauce works in place of homemade; most brands contain Worcestershire (with anchovy) and wheat.', 'Swap the pork for sliced chicken thighs (cook to 165°F) or extra-firm tofu.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['quick', 'main', 'dinner', 'budget', 'comfort']::text[], array['stir_fry']::text[], array['tangy', 'savory']::text[], '{}'::text[], null, 'traditional', 'yakisoba', 'classic', 'Refrigerate up to 3 days. Reheat in a skillet with a splash of water.', null, 'owned', array['fish', 'gluten', 'shellfish', 'soy', 'wheat']::text[], array['pork']::text[], array['dairy_free']::text[], array['worcestershire sauce', 'oyster sauce', 'soy sauce', 'ketchup', 'yakisoba noodle', 'pork belly', 'yellow onion', 'carrot', 'green cabbage', 'scallion']::text[], 'carrot|green cabbage|ketchup|oyster sauce|pork belly|scallion|soy sauce|worcestershire sauce|yakisoba noodle|yellow onion',
