values ('22efb208-fc93-46e3-b88a-61c23adc9e54', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'thai-pineapple-fried-rice', 'pineapple-fried-rice-22efb2', 'Pineapple Fried Rice', 'Jasmine rice fried with chicken, egg, juicy pineapple, cashews and a hint of curry powder, seasoned with fish sauce — sweet, salty and ready in 30 minutes.', 'thai', 1, 15, 15, 30, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'kid-friendly', 'takeout', 'leftovers']::text[], array['For a party, halve a whole pineapple lengthwise, scoop out the flesh to use in the rice, and serve the fried rice in the shells.', 'Canned pineapple chunks work too — drain them well and pat dry so the rice doesn''t get soggy.']::text[], 'https://images.pexels.com/photos/19582731/pexels-photo-19582731.jpeg', 'Shrimp fried rice served in a hollowed-out pineapple with herbs', 'Nadin Sh', 'https://www.pexels.com/@nadin-sh-78971847/', 'https://www.pexels.com/photo/a-dish-in-a-pineapple-19582731/', 'pexels', true, 'public', false,
  'pending_review', array['quick', 'main', 'dinner', 'comfort']::text[], array['stir_fry']::text[], array['tangy', 'fresh', 'savory', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'pineapple-fried-rice', 'classic', 'Cool quickly and refrigerate within 1 hour; keeps 3 days. Reheat until steaming hot.', null, 'owned', array['egg', 'fish', 'gluten', 'soy', 'tree_nut', 'wheat']::text[], array['chicken', 'fish']::text[], array['dairy_free']::text[], array['egg', 'shallot', 'garlic', 'curry powder', 'jasmine rice', 'pineapple', 'frozen pea', 'fish sauce', 'soy sauce', 'roasted cashew', 'scallion', 'lime']::text[], 'curry powder|egg|fish sauce|frozen pea|garlic|jasmine rice|lime|pineapple|roasted cashew|scallion|shallot|soy sauce',
  null, null, null, null, null, null, null, null)
