insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('22efb208-fc93-46e3-b88a-61c23adc9e54', 1, null, 'Heat 1 tablespoon of the oil in a wok or large skillet over high heat. Stir-fry the chicken until browned, no pink remains and it reaches 165°F, 4–5 minutes. Move to a plate.', 300, null, 73.9),
  ('22efb208-fc93-46e3-b88a-61c23adc9e54', 2, null, 'Add another tablespoon of oil, pour in the eggs and scramble until just set with no runny egg left (160°F), about 1 minute. Add to the chicken.', 60, null, 71.1),
  ('22efb208-fc93-46e3-b88a-61c23adc9e54', 3, null, 'Add the remaining oil, the shallot and garlic and stir-fry 1 minute, then sprinkle in the curry powder and stir 15 seconds.', 60, null, null),
  ('22efb208-fc93-46e3-b88a-61c23adc9e54', 4, null, 'Add the rice and spread it out; let it toast 30 seconds, then stir and repeat until hot and separate, about 4 minutes.', 240, null, null),
  ('22efb208-fc93-46e3-b88a-61c23adc9e54', 5, null, 'Add the pineapple, peas, fish sauce, soy sauce and sugar and toss until the pineapple is hot, 2 minutes. Return the chicken and eggs, add the cashews and scallions and toss 1 minute.', 180, null, null),
  ('22efb208-fc93-46e3-b88a-61c23adc9e54', 6, null, 'Serve with cilantro and lime wedges for squeezing.', null, null, null);

-- Tofu and Vegetable Stir-Fry
