values ('0a148857-2004-4548-b062-e0d4caef521f', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'tofu-vegetable-stir-fry', 'tofu-and-vegetable-stir-fry-0a1488', 'Tofu and Vegetable Stir-Fry', 'Crisp-edged golden tofu and a rainbow of crunchy vegetables in a glossy garlic-ginger soy sauce — an easy, budget-friendly weeknight stir-fry over rice.', 'chinese', 1, 25, 15, 40, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'budget', 'meatless']::text[], array['Use whatever vegetables are in the crisper — mushrooms, bok choy, zucchini and green beans all work; add harder ones first.']::text[], 'https://images.pexels.com/photos/5848480/pexels-photo-5848480.jpeg', 'Tofu stir-fried with bell peppers, green beans and wood ear mushrooms', 'Polina Tankilevitch', 'https://www.pexels.com/@polina-tankilevitch/', 'https://www.pexels.com/photo/close-up-photo-of-a-tofu-dish-5848480/', 'pexels', true, 'public', false,
  'pending_review', array['quick', 'budget', 'main', 'dinner']::text[], array['stir_fry', 'steam']::text[], array['tangy', 'savory']::text[], '{}'::text[], null, null, 'tofu-vegetable-stir-fry', 'classic', 'Refrigerate up to 3 days. The tofu softens; reheat in a hot skillet to bring back some crunch.', null, 'owned', array['gluten', 'sesame', 'soy', 'wheat']::text[], array['tofu']::text[], array['pescatarian', 'vegetarian', 'vegan', 'dairy_free']::text[], array['extra-firm tofu', 'cornstarch', 'soy sauce', 'hoisin sauce', 'rice vinegar', 'maple syrup', 'sesame oil', 'carrot', 'broccoli floret', 'bell pepper', 'snap pea', 'garlic', 'ginger', 'scallion', 'jasmine rice']::text[], 'bell pepper|broccoli floret|carrot|cornstarch|extra-firm tofu|garlic|ginger|hoisin sauce|jasmine rice|maple syrup|rice vinegar|scallion|sesame oil|snap pea|soy sauce',
  null, null, null, null, null, null, null, null)
