insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('0a148857-2004-4548-b062-e0d4caef521f', 1, 'Tofu', 'Wrap the tofu block in a clean towel and press under a heavy pan for 15 minutes, then cube it. Toss with the cornstarch and salt.', 900, null, null),
  ('0a148857-2004-4548-b062-e0d4caef521f', 2, 'Tofu', 'Heat the 2 tablespoons oil in a large nonstick skillet over medium-high heat. Fry the tofu in a single layer, turning every couple of minutes, until golden and crisp on several sides, about 8 minutes. Move to a plate.', 480, null, null),
  ('0a148857-2004-4548-b062-e0d4caef521f', 3, 'Sauce', 'Whisk the soy sauce, hoisin, vinegar, maple syrup, sesame oil, cornstarch and water together.', null, null, null),
  ('0a148857-2004-4548-b062-e0d4caef521f', 4, 'Vegetables', 'Add the 1 tablespoon oil to the skillet with the carrot and broccoli and 2 tablespoons water. Cover and steam-fry 2 minutes, then uncover, add the bell pepper and snap peas and stir-fry 2 minutes until crisp-tender.', 240, null, null),
  ('0a148857-2004-4548-b062-e0d4caef521f', 5, 'Vegetables', 'Add the garlic and ginger and stir 30 seconds. Stir the sauce, pour it in and bubble until thick and glossy, about 1 minute.', 120, null, null),
  ('0a148857-2004-4548-b062-e0d4caef521f', 6, null, 'Return the tofu, toss gently to coat, scatter with scallions and serve over rice.', 60, null, null);

-- Thai Red Curry with Vegetables
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
