values ('b3fd38eb-7e7d-475a-8238-e02e27bea041', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'thai-red-curry-vegetables', 'thai-red-curry-with-vegetables-b3fd38', 'Thai Red Curry with Vegetables', 'Sweet potato, broccoli, green beans and bell pepper simmered in a rich coconut red curry with lime leaves and Thai basil; we use a curry paste made without shrimp paste and season with soy sauce instead of fish sauce.', 'thai', 1, 15, 25, 40, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'make-ahead', 'meatless']::text[], array['Most Thai red curry pastes contain shrimp paste and some contain fish sauce — read the ingredient list and choose one made without them for a vegan curry or a shellfish allergy.', 'Add cubes of pan-fried tofu or a can of drained chickpeas with the broccoli for more protein.']::text[], 'https://images.pexels.com/photos/10527603/pexels-photo-10527603.jpeg', 'Bowl of Thai red curry with tofu and vegetables', 'Nourishment DECODED', 'https://www.pexels.com/@nourishmentdecoded/', 'https://www.pexels.com/photo/cooked-food-on-white-ceramic-bowl-10527603/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner']::text[], array['stew']::text[], array['tangy', 'rich', 'fresh', 'savory']::text[], '{}'::text[], null, 'adapted', 'red-curry-vegetables', 'classic', 'Refrigerate up to 4 days or freeze up to 2 months (without the basil).', null, 'owned', array['gluten', 'soy', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'dairy_free']::text[], array['curry paste', 'coconut milk', 'sweet potato', 'soy sauce', 'brown sugar', 'broccoli floret', 'green bean', 'bell pepper', 'lime juice', 'basil leave', 'jasmine rice']::text[], 'basil leave|bell pepper|broccoli floret|brown sugar|coconut milk|curry paste|green bean|jasmine rice|lime juice|soy sauce|sweet potato',
  null, null, null, null, null, null, null, null)
