delete from public.recipe_instructions where recipe_id = 'b3fd38eb-7e7d-475a-8238-e02e27bea041';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('b3fd38eb-7e7d-475a-8238-e02e27bea041', 1, null, 'Spoon the thick cream from the top of one can of coconut milk into a large pot. Simmer over medium heat, stirring, until it bubbles thickly and the oil starts to separate, about 3 minutes. (If your coconut milk doesn''t separate, add the oil and fry the paste in it.)', 180, null, null),
  ('b3fd38eb-7e7d-475a-8238-e02e27bea041', 2, null, 'Add the curry paste and fry, stirring constantly, until very fragrant, about 2 minutes.', 120, null, null),
  ('b3fd38eb-7e7d-475a-8238-e02e27bea041', 3, null, 'Stir in the remaining coconut milk, the water, sweet potato, soy sauce, sugar and lime leaves. Bring to a gentle simmer and cook until the sweet potato is almost tender, 10 minutes.', 600, null, null),
  ('b3fd38eb-7e7d-475a-8238-e02e27bea041', 4, null, 'Add the broccoli and green beans and simmer 4 minutes, then the bell pepper for 2 minutes more, until all the vegetables are just tender.', 360, null, null),
  ('b3fd38eb-7e7d-475a-8238-e02e27bea041', 5, null, 'Turn off the heat, stir in the lime juice and basil, and taste for salt (soy sauce), sweetness and heat. Serve with jasmine rice.', 60, null, null);

