values ('0c988710-ab44-459f-b311-c5f499f5b9c8', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-korma', 'chicken-korma-0c9887', 'Chicken Korma', 'Tender chicken in a mild, silky sauce of golden onions, yogurt, cashews and warm whole spices; a restaurant-style version, blended smooth and finished with a little cream.', 'indian', 2, 20, 45, 65, 4, 'main', null, 0, array['stove', 'blender', 'dutch_oven']::text[], array['kid-friendly', 'make-ahead', 'freezer-friendly', 'takeout']::text[], array['No cashews? Use 3 tablespoons of ground almonds instead — the sauce is just as creamy.', 'Garam masala blends vary; buy from a brand that lists its ingredients if you''re cooking around allergies.']::text[], null, null, null, null, null, null, null, 'public', false,
