delete from public.recipe_instructions where recipe_id = '0c988710-ab44-459f-b311-c5f499f5b9c8';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('0c988710-ab44-459f-b311-c5f499f5b9c8', 1, 'Chicken', 'Stir the chicken with the yogurt and salt and set aside while you make the sauce base. Soak the cashews in the hot water.', 120, null, null),
  ('0c988710-ab44-459f-b311-c5f499f5b9c8', 2, 'Sauce', 'Melt the ghee in a Dutch oven or heavy pot over medium heat. Add the cinnamon, cardamom, cloves and bay leaves and stir until fragrant, 30 seconds. Add the onions and cook, stirring often, until soft and deep golden, 12–15 minutes.', 900, null, null),
  ('0c988710-ab44-459f-b311-c5f499f5b9c8', 3, 'Sauce', 'Add the garlic and ginger and cook 1 minute, then the coriander, cumin, turmeric and chili powder for 30 seconds more.', 120, null, null),
  ('0c988710-ab44-459f-b311-c5f499f5b9c8', 4, 'Sauce', 'Pick out the cinnamon stick, bay leaves and as many cardamom pods as you can find. Scrape the onion mixture into a blender with the cashews and their soaking water and blend until completely smooth. Vent the lid and cover with a towel — hot liquids expand.', 120, null, null),
  ('0c988710-ab44-459f-b311-c5f499f5b9c8', 5, 'Chicken', 'Pour the sauce back into the pot with the ½ cup water and bring to a gentle simmer. Add the chicken with its yogurt, cover and cook over low heat, stirring now and then, until the chicken reaches 165°F, 15–18 minutes. Keep it at a gentle bubble so the yogurt doesn''t split.', 1080, null, 73.9),
  ('0c988710-ab44-459f-b311-c5f499f5b9c8', 6, 'Finish', 'Stir in the cream, garam masala and sugar and simmer 2 minutes. Taste for salt, scatter with cilantro and serve with basmati rice.', 120, null, null);

