values ('c0c7a4a3-62cd-4452-9897-bf2ebb226e11', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'tandoori-chicken-oven', 'tandoori-chicken-c0c7a4', 'Tandoori Chicken', 'Bone-in chicken marinated in spiced yogurt, then roasted hot and charred under the broiler; we use the oven instead of a clay tandoor and Kashmiri chili for color instead of food dye.', 'indian', 1, 80, 35, 115, 4, 'main', null, 0, array['oven']::text[], array['make-ahead', 'kid-friendly', 'entertaining', 'takeout']::text[], array['On the grill: cook over medium-high heat with the lid closed, turning every few minutes, until charred and 165°F near the bone, 20–25 minutes.', 'Wash hands, boards and anything that touched the raw chicken in hot soapy water before handling the serving garnishes.']::text[], 'https://images.pexels.com/photos/29173119/pexels-photo-29173119.jpeg', 'Close-up of red-spiced tandoori chicken with fresh garnish', 'Kunal Lakhotia', 'https://www.pexels.com/@kunal-lakhotia-781256899/', 'https://www.pexels.com/photo/delicious-grilled-tandoori-chicken-in-close-up-29173119/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner', 'comfort', 'entertaining']::text[], array['roast']::text[], array['spicy', 'tangy', 'fresh', 'aromatic']::text[], '{}'::text[], 'Punjab', 'adapted', 'tandoori-chicken', 'classic', 'Refrigerate up to 3 days. Leftovers are great sliced into wraps or salads.', null, 'owned', array['milk']::text[], array['chicken']::text[], array['gluten_free']::text[], array['lemon juice', 'greek yogurt', 'garlic', 'ginger', 'chili powder', 'garam masala', 'ground cumin', 'ground coriander', 'ground turmeric', 'red onion', 'lemon', 'cilantro leave']::text[], 'chili powder|cilantro leave|garam masala|garlic|ginger|greek yogurt|ground coriander|ground cumin|ground turmeric|lemon|lemon juice|red onion',
  null, null, null, null, null, null, null, null)
