delete from public.recipe_instructions where recipe_id = 'c0c7a4a3-62cd-4452-9897-bf2ebb226e11';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('c0c7a4a3-62cd-4452-9897-bf2ebb226e11', 1, 'Chicken', 'Cut 2–3 deep slashes into each piece of chicken down to the bone. Rub with the lemon juice and salt and let sit 10 minutes.', 600, null, null),
  ('c0c7a4a3-62cd-4452-9897-bf2ebb226e11', 2, 'Marinade', 'Mix the yogurt, garlic, ginger, chili powder, garam masala, cumin, coriander, turmeric and oil. Coat the chicken thoroughly, working the marinade into the slashes. Cover and refrigerate at least 1 hour or up to 24 hours.', 3600, null, null),
  ('c0c7a4a3-62cd-4452-9897-bf2ebb226e11', 3, 'Chicken', 'Heat the oven to 450°F with a rack in the upper third. Line a sheet pan with foil, set an oiled wire rack on it and arrange the chicken on the rack with space between the pieces. Discard leftover marinade.', 900, 232.2, null),
  ('c0c7a4a3-62cd-4452-9897-bf2ebb226e11', 4, 'Chicken', 'Roast until the chicken reaches 165°F near the bone, 25–30 minutes.', 1680, 232.2, 73.9),
  ('c0c7a4a3-62cd-4452-9897-bf2ebb226e11', 5, 'Chicken', 'Switch to broil and broil until charred in spots, 3–5 minutes, watching closely. Rest 5 minutes and serve with onion rings, lemon wedges and cilantro.', 480, null, null);

-- Saag Aloo
