values ('58a6c2f1-b2c1-4acf-8230-8a3724526654', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'saag-aloo', 'saag-aloo-58a6c2', 'Saag Aloo', 'Golden-edged potatoes folded into garlicky, cumin-scented spinach — a quick Punjabi-style side that''s just as good as a light meal with rice or flatbread.', 'indian', 1, 15, 30, 45, 4, 'side', null, 0, array['stove']::text[], array['weeknight', 'budget', 'make-ahead', 'takeout']::text[], array['Frozen spinach makes this a pantry dish — squeeze it really dry so the potatoes can still brown.']::text[], 'https://images.pexels.com/photos/13513758/pexels-photo-13513758.jpeg', 'Spiced spinach saag in a kadai, garnished with herbs', 'Sagar Konduri', 'https://www.pexels.com/@sagar-konduri-298000195/', 'https://www.pexels.com/photo/herbs-in-pot-13513758/', 'pexels', true, 'public', false,
