delete from public.recipe_instructions where recipe_id = '58a6c2f1-b2c1-4acf-8230-8a3724526654';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('58a6c2f1-b2c1-4acf-8230-8a3724526654', 1, null, 'Boil the potatoes in well-salted water until just tender when poked with a knife, 6–8 minutes. Drain and let them steam dry.', 600, null, null),
  ('58a6c2f1-b2c1-4acf-8230-8a3724526654', 2, null, 'If using fresh spinach, wilt it in the empty pot with a splash of water, about 2 minutes. Cool briefly, squeeze out the water and chop finely.', 240, null, null),
  ('58a6c2f1-b2c1-4acf-8230-8a3724526654', 3, null, 'Heat the oil in a large skillet over medium heat. Add the cumin and mustard seeds and cook until they crackle, about 30 seconds. Add the onion and cook until soft and golden, 6–8 minutes.', 480, null, null),
  ('58a6c2f1-b2c1-4acf-8230-8a3724526654', 4, null, 'Add the garlic, ginger and chile and cook 1 minute, then the coriander, turmeric, chili powder and tomato. Cook, stirring, until the tomato breaks down, about 3 minutes.', 240, null, null),
  ('58a6c2f1-b2c1-4acf-8230-8a3724526654', 5, null, 'Add the potatoes and fry, turning now and then, until golden at the edges, 6–8 minutes.', 420, null, null),
  ('58a6c2f1-b2c1-4acf-8230-8a3724526654', 6, null, 'Stir in the spinach, salt and 2 tablespoons water and cook until hot, 2–3 minutes. Finish with the garam masala and lemon juice and serve.', 180, null, null);

