values ('a3c74ca1-83a9-4607-b43f-3807e7178938', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'vegetable-biryani', 'vegetable-biryani-a3c74c', 'Vegetable Biryani', 'Fragrant basmati layered over spiced vegetables in yogurt with crisp fried onions, mint and saffron milk, then steamed until every grain is separate; we seal the pot with foil instead of dough.', 'indian', 2, 40, 60, 100, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['entertaining', 'make-ahead', 'meatless']::text[], array['Short on time? Store-bought crispy fried onions (birista) replace step 2 — use about 1½ cups.', 'No saffron? Skip it; stir ¼ teaspoon turmeric into the warm milk for color instead.']::text[], 'https://images.pexels.com/photos/7593230/pexels-photo-7593230.jpeg', 'Vegetable biryani with cashews, peas and carrots in a metal bowl', 'Ahmad No More', 'https://www.pexels.com/@ahmad-no-more-1880480/', 'https://www.pexels.com/photo/chilies-and-a-bowl-of-vegetable-biryani-7593230/', 'pexels', true, 'public', false,
  'pending_review', array['entertaining', 'comfort', 'main', 'dinner', 'holiday']::text[], array['stew', 'boil']::text[], array['spicy', 'tangy', 'rich', 'fresh', 'aromatic']::text[], array['diwali', 'eid-al-fitr']::text[], null, 'adapted', 'vegetable-biryani', 'classic', 'Cool quickly and refrigerate within 1 hour; keeps 3 days. Sprinkle with water, cover and reheat until steaming hot.', null, 'owned', array['milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['basmati rice', 'cardamom pod', 'clove', 'bay', 'yellow onion', 'ghee', 'cumin seed', 'garlic', 'ginger', 'green chile', 'garam masala', 'chili powder', 'ground turmeric', 'gold potato', 'carrot', 'cauliflower floret', 'green bean', 'whole-milk yogurt', 'frozen pea', 'saffron thread', 'milk', 'mint leave', 'cilantro leave']::text[], 'basmati rice|bay|cardamom pod|carrot|cauliflower floret|chili powder|cilantro leave|clove|cumin seed|frozen pea|garam masala|garlic|ghee|ginger|gold potato|green bean|green chile|ground turmeric|milk|mint leave|saffron thread|whole-milk yogurt|yellow onion',
