delete from public.recipe_instructions where recipe_id = 'a3c74ca1-83a9-4607-b43f-3807e7178938';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('a3c74ca1-83a9-4607-b43f-3807e7178938', 1, 'Rice', 'Rinse the rice in several changes of water until it runs nearly clear, then cover with fresh water and soak 20 minutes. Stir the saffron into the warm milk and set aside.', 1200, null, null),
  ('a3c74ca1-83a9-4607-b43f-3807e7178938', 2, 'Onions', 'Heat the oil in a Dutch oven over medium heat. Fry the onions, stirring often and lowering the heat as they darken, until deep golden brown and crisp at the edges, 15–20 minutes. Lift them onto paper towels and pour off all but 1 tablespoon of the oil.', 1080, null, null),
  ('a3c74ca1-83a9-4607-b43f-3807e7178938', 3, 'Vegetables', 'Add the ghee to the pot over medium heat with the cumin seeds for 30 seconds, then the garlic, ginger and chile for 1 minute. Stir in the garam masala, chili powder, turmeric and salt, then the potato, carrots, cauliflower and green beans, and toss 3 minutes.', 300, null, null),
  ('a3c74ca1-83a9-4607-b43f-3807e7178938', 4, 'Vegetables', 'Lower the heat, stir in the yogurt and water, cover and simmer gently until the vegetables are almost tender, about 10 minutes. Stir in the peas and half the fried onions.', 600, null, null),
  ('a3c74ca1-83a9-4607-b43f-3807e7178938', 5, 'Rice', 'Meanwhile, bring the 3 quarts water to a boil with the salt, cardamom, cloves and bay leaf. Drain the rice, add it and boil until the grains are long and about three-quarters cooked — a grain should snap with a firm white core — 5–6 minutes. Drain well.', 360, null, null),
  ('a3c74ca1-83a9-4607-b43f-3807e7178938', 6, 'Layering', 'Spread the rice evenly over the vegetables without stirring. Scatter with mint, cilantro and the remaining onions, then drizzle with the saffron milk and melted ghee. Cover the pot tightly with foil, then the lid.', null, null, null),
  ('a3c74ca1-83a9-4607-b43f-3807e7178938', 7, 'Layering', 'Cook over the lowest heat for 20 minutes, then turn off the heat and leave it covered for 10 minutes. Fluff gently from the sides, scooping up rice and vegetables together, and serve with raita.', 1800, null, null);

-- Greek Chicken Gyros
