values ('17867f61-a554-45a8-93f1-f63a820640ab', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'greek-chicken-gyros', 'greek-chicken-gyros-17867f', 'Greek Chicken Gyros', 'Lemon-oregano marinated chicken thighs seared in a hot skillet, sliced and wrapped in warm pita with garlicky tzatziki, tomato and onion; we sear instead of carving from a vertical rotisserie.', 'greek', 1, 45, 15, 60, 4, 'main', null, 0, array['stove', 'cast_iron']::text[], array['weeknight', 'kid-friendly', 'make-ahead', 'takeout']::text[], array['In Greece, gyros are often stuffed with a few French fries too — oven fries make it a full takeout-style dinner.']::text[], 'https://images.unsplash.com/photo-1745126009946-1b35b1a16fec', 'Pita gyro wrapped around sliced meat and fries', 'Nick Nice', 'https://unsplash.com/@nicknice', 'https://unsplash.com/photos/a-delicious-gyro-filled-with-meat-and-fries-t_MgBtiEZV4', 'unsplash', true, 'public', false,
  'pending_review', array['quick', 'main', 'dinner', 'comfort']::text[], '{}'::text[], array['smoky', 'tangy', 'fresh', 'aromatic']::text[], '{}'::text[], null, 'adapted', 'chicken-gyros', 'classic', 'Refrigerate chicken up to 4 days and tzatziki up to 3 days. Assemble just before eating.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], array['chicken']::text[], '{}'::text[], array['greek yogurt', 'lemon juice', 'garlic', 'dried oregano', 'smoked paprika', 'ground cumin', 'english cucumber', 'dill', 'pita bread', 'roma tomato', 'red onion', 'romaine lettuce']::text[], 'dill|dried oregano|english cucumber|garlic|greek yogurt|ground cumin|lemon juice|pita bread|red onion|roma tomato|romaine lettuce|smoked paprika',
  null, null, null, null, null, null, null, null)
