insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('17867f61-a554-45a8-93f1-f63a820640ab', 1, 'Chicken', 'Mix the yogurt, 2 tablespoons oil, lemon juice, garlic, oregano, paprika, cumin, salt and pepper in a bowl. Add the chicken and turn to coat. Cover and refrigerate at least 30 minutes or up to 24 hours.', 1800, null, null),
  ('17867f61-a554-45a8-93f1-f63a820640ab', 2, 'Tzatziki', 'Stir the yogurt, cucumber, garlic, lemon juice, oil, dill and salt together. Chill until serving.', null, null, null),
  ('17867f61-a554-45a8-93f1-f63a820640ab', 3, 'Chicken', 'Heat the remaining tablespoon of oil in a large cast-iron skillet over medium-high heat. Shake excess marinade off the chicken and cook until charred in spots and 165°F in the thickest part, 5–6 minutes per side. Rest 5 minutes, then slice thinly.', 900, null, 73.9),
  ('17867f61-a554-45a8-93f1-f63a820640ab', 4, null, 'Wipe the skillet and warm the pitas in it, about 30 seconds per side.', 120, null, null),
  ('17867f61-a554-45a8-93f1-f63a820640ab', 5, null, 'Spread each pita with tzatziki, pile on the chicken, tomatoes, onion and lettuce, and roll up in a square of foil or parchment to hold it together.', null, null, null);

