values ('36f71996-1044-49e0-8e70-b4ea8b8ca289', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'moroccan-chickpea-stew', 'moroccan-chickpea-stew-36f719', 'Moroccan Chickpea Stew', 'Chickpeas, sweet potato and tomatoes simmered with cumin, cinnamon, ginger and dried apricots, finished with spinach, lemon and cilantro; a quick pot stew inspired by tagine flavors rather than a slow-cooked tagine.', 'moroccan', 1, 15, 35, 50, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['weeknight', 'budget', 'make-ahead', 'freezer-friendly', 'meatless']::text[], array['Serve over couscous or with warm flatbread to soak up the broth.', 'Harissa varies a lot in heat — start with a teaspoon.']::text[], 'https://images.pexels.com/photos/30168757/pexels-photo-30168757.jpeg', 'Chickpea stew garnished with fresh herbs in a rustic brown bowl', 'Anthony Rahayel', 'https://www.pexels.com/@anthony-rahayel-125801377/', 'https://www.pexels.com/photo/delicious-homemade-chickpea-stew-in-rustic-bowl-30168757/', 'pexels', true, 'public', false,
  'pending_review', array['budget', 'comfort', 'main', 'dinner', 'soup']::text[], array['stew', 'boil']::text[], array['spicy', 'tangy', 'fresh', 'aromatic']::text[], '{}'::text[], null, 'adapted', 'moroccan-chickpea-stew', 'classic', 'Refrigerate up to 5 days or freeze up to 3 months; it thickens as it sits, so loosen with water when reheating.', null, 'owned', '{}'::text[], array['beans']::text[], array['pescatarian', 'vegetarian', 'vegan', 'dairy_free']::text[], array['yellow onion', 'carrot', 'garlic', 'ginger', 'ground cumin', 'sweet paprika', 'ground coriander', 'ground cinnamon', 'ground turmeric', 'cayenne pepper', 'tomato paste', 'chickpea', 'tomato', 'sweet potato', 'vegetable broth', 'dried apricot', 'spinach', 'lemon juice', 'cilantro']::text[], 'carrot|cayenne pepper|chickpea|cilantro|dried apricot|garlic|ginger|ground cinnamon|ground coriander|ground cumin|ground turmeric|lemon juice|spinach|sweet paprika|sweet potato|tomato|tomato paste|vegetable broth|yellow onion',
