insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('36f71996-1044-49e0-8e70-b4ea8b8ca289', 1, null, 'Heat the oil in a Dutch oven over medium heat. Add the onion and carrots and cook until softened, about 6 minutes.', 360, null, null),
  ('36f71996-1044-49e0-8e70-b4ea8b8ca289', 2, null, 'Add the garlic, ginger, cumin, paprika, coriander, cinnamon, turmeric, cayenne and tomato paste and stir until the paste darkens and the spices smell toasty, 1–2 minutes.', 120, null, null),
  ('36f71996-1044-49e0-8e70-b4ea8b8ca289', 3, null, 'Add the chickpeas, tomatoes, sweet potato, broth, apricots and salt. Bring to a boil, then simmer partly covered until the sweet potato is tender, 20–25 minutes.', 1380, null, null),
  ('36f71996-1044-49e0-8e70-b4ea8b8ca289', 4, null, 'Mash a ladleful of chickpeas against the side of the pot to thicken the stew. Stir in the spinach until wilted, about 2 minutes.', 120, null, null),
  ('36f71996-1044-49e0-8e70-b4ea8b8ca289', 5, null, 'Off the heat, stir in the lemon juice and most of the cilantro. Taste for salt and serve topped with the rest of the cilantro and a spoonful of harissa.', 60, null, null);

