values ('283796a9-a9c6-444f-bd97-5e435fa49d1c', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'korean-bbq-beef-tacos', 'korean-bbq-beef-tacos-283796', 'Korean BBQ Beef Tacos', 'Thin-sliced, bulgogi-style marinated beef seared hot and piled into warm corn tortillas with a crunchy gochujang-lime slaw — the Korean-Mexican food-truck mash-up from Los Angeles.', 'fusion', 1, 50, 15, 65, 4, 'main', null, 0, array['stove', 'cast_iron']::text[], array['weeknight', 'entertaining', 'make-ahead']::text[], array['Gochujang is usually made with wheat, and most kimchi contains fish sauce or salted shrimp — read the labels if you''re cooking around allergies.', 'Many supermarkets and Asian grocers sell pre-sliced beef for bulgogi or hot pot, which saves the freezing and slicing.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['quick', 'main', 'dinner', 'holiday', 'entertaining']::text[], array['pan_fry']::text[], array['spicy', 'tangy', 'fresh', 'savory']::text[], array['game-day']::text[], 'Los Angeles', null, 'korean-bbq-beef-tacos', 'classic', 'Refrigerate cooked beef up to 3 days and the slaw up to 1 day. Reheat the beef quickly in a hot skillet.', null, 'owned', array['gluten', 'sesame', 'soy', 'wheat']::text[], array['beef']::text[], array['dairy_free']::text[], array['sirloin steak', 'soy sauce', 'brown sugar', 'asian pear', 'sesame oil', 'garlic', 'ginger', 'scallion', 'green cabbage', 'gochujang', 'rice vinegar', 'lime juice', 'cilantro', 'corn tortilla', 'lime', 'sesame seed']::text[], 'asian pear|brown sugar|cilantro|corn tortilla|garlic|ginger|gochujang|green cabbage|lime|lime juice|rice vinegar|scallion|sesame oil|sesame seed|sirloin steak|soy sauce',
  null, null, null, null, null, null, null, null)
