insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('283796a9-a9c6-444f-bd97-5e435fa49d1c', 1, 'Beef', 'For easy slicing, freeze the steak 30 minutes, then cut across the grain as thin as you can. Mix the soy sauce, sugar, pear, sesame oil, garlic, ginger, scallions and pepper, add the beef and toss. Refrigerate at least 15 minutes or up to 8 hours.', 2700, null, null),
  ('283796a9-a9c6-444f-bd97-5e435fa49d1c', 2, 'Slaw', 'Whisk the gochujang, vinegar, lime juice, sugar and sesame oil, then toss with the cabbage and cilantro.', null, null, null),
  ('283796a9-a9c6-444f-bd97-5e435fa49d1c', 3, 'Beef', 'Heat a large cast-iron skillet over high heat with a little of the oil until smoking. Add a third of the beef in a single layer (shake off excess marinade) and sear until browned and caramelized at the edges and cooked through to 145°F, 1–2 minutes per side. Repeat with the rest, adding oil as needed.', 480, null, 62.8),
  ('283796a9-a9c6-444f-bd97-5e435fa49d1c', 4, null, 'Warm the tortillas in a dry skillet or directly over a gas flame until soft and lightly charred, about 30 seconds per side. Stack them in a towel to stay warm.', 240, null, null),
  ('283796a9-a9c6-444f-bd97-5e435fa49d1c', 5, null, 'Fill each tortilla with beef and slaw, sprinkle with sesame seeds, add kimchi if you like, and serve with lime wedges.', 120, null, null);

