values ('c5583492-ec5e-42b5-b4d0-3878af3bac86', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'katsu-sando', 'katsu-sando-c55834', 'Katsu Sando', 'A crisp panko-crusted pork cutlet with tangy katsu sauce and finely shredded cabbage between pillowy slices of Japanese milk bread, crusts trimmed — Japan''s favorite convenience-store sandwich made fresh.', 'japanese', 2, 20, 20, 40, 4, 'main', null, 0, array['stove']::text[], array['kid-friendly', 'picnic']::text[], array['Bottled tonkatsu sauce (such as Bull-Dog) can replace the homemade sauce.', 'Worcestershire sauce contains anchovies; leave it out and add 1 teaspoon rice vinegar for a fish allergy.']::text[], 'https://images.unsplash.com/photo-1771398269757-0763f7ecd52c', 'Two tonkatsu sandwiches with breaded pork cutlet and sauce on a plate', 'Moises Guillen', 'https://unsplash.com/@moisesvisuals', 'https://unsplash.com/photos/two-katsu-sandwiches-with-garnish-on-a-plate-RdDWM2gRtjY', 'unsplash', true, 'public', false,
  'pending_review', array['lunch', 'main', 'dinner', 'comfort']::text[], '{}'::text[], array['savory']::text[], '{}'::text[], null, 'traditional', 'katsu-sando', 'classic', 'Best fresh. Wrapped tightly, sandwiches keep in the fridge until the next day for a packed lunch; cooked cutlets keep 3 days and re-crisp in a 400°F oven.', null, 'owned', array['egg', 'fish', 'gluten', 'milk', 'soy', 'wheat']::text[], array['pork']::text[], '{}'::text[], array['loin chop', 'egg', 'panko breadcrumb', 'ketchup', 'worcestershire sauce', 'soy sauce', 'milk bread', 'kewpie mayonnaise', 'green cabbage']::text[], 'egg|green cabbage|ketchup|kewpie mayonnaise|loin chop|milk bread|panko breadcrumb|soy sauce|worcestershire sauce',
  null, null, null, null, null, null, null, null)
