  ('c5583492-ec5e-42b5-b4d0-3878af3bac86', 1, 'Cutlets', '4 boneless pork loin chops, 4–5 oz each, about ½ inch thick', 'boneless pork loin chops', 4, null, '4–5 oz each, about ½ inch thick', false),
  ('c5583492-ec5e-42b5-b4d0-3878af3bac86', 2, 'Cutlets', '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('c5583492-ec5e-42b5-b4d0-3878af3bac86', 3, 'Cutlets', '¼ tsp black pepper', 'black pepper', 0.25, 'tsp', null, false),
