  ('c5583492-ec5e-42b5-b4d0-3878af3bac86', 5, 'Cutlets', '2 large eggs, beaten', 'large eggs', 2, null, 'beaten', false),
  ('c5583492-ec5e-42b5-b4d0-3878af3bac86', 6, 'Cutlets', '1½ cups panko breadcrumbs', 'panko breadcrumbs', 1.5, 'cup', null, false),
  ('c5583492-ec5e-42b5-b4d0-3878af3bac86', 7, 'Cutlets', '2 cups vegetable oil, for shallow-frying', 'vegetable oil', 2, 'cup', 'for shallow-frying', false),
  ('c5583492-ec5e-42b5-b4d0-3878af3bac86', 8, 'Katsu sauce', '¼ cup ketchup', 'ketchup', 0.25, 'cup', null, false),
  ('c5583492-ec5e-42b5-b4d0-3878af3bac86', 9, 'Katsu sauce', '2 tbsp Worcestershire sauce', 'Worcestershire sauce', 2, 'tbsp', null, false),
