  ('c5583492-ec5e-42b5-b4d0-3878af3bac86', 12, 'Sandwiches', '8 slice Japanese milk bread (shokupan), or thick-cut soft white sandwich bread', 'Japanese milk bread (shokupan)', 8, 'slice', 'or thick-cut soft white sandwich bread', false),
  ('c5583492-ec5e-42b5-b4d0-3878af3bac86', 13, 'Sandwiches', '2 tbsp Kewpie mayonnaise, or regular mayonnaise', 'Kewpie mayonnaise', 2, 'tbsp', 'or regular mayonnaise', false),
