insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('c5583492-ec5e-42b5-b4d0-3878af3bac86', 1, 'Cutlets', 'Pound the chops between plastic wrap to an even ½-inch thickness and trim them roughly to the size of the bread. Season with salt and pepper.', 300, null, null),
  ('c5583492-ec5e-42b5-b4d0-3878af3bac86', 2, 'Cutlets', 'Set out the flour, eggs and panko in three shallow dishes. Dredge each cutlet in flour, dip in egg, then press firmly into the panko on both sides.', 300, null, null),
  ('c5583492-ec5e-42b5-b4d0-3878af3bac86', 3, 'Katsu sauce', 'Stir the ketchup, Worcestershire, soy sauce and sugar together until the sugar dissolves.', null, null, null),
  ('c5583492-ec5e-42b5-b4d0-3878af3bac86', 4, 'Cutlets', 'Pour the oil into a large, heavy skillet — about ½ inch deep and no more than half full — and heat over medium-high to 350°F. Keep children and pets away and never leave hot oil unattended.', 300, 176.7, null),
  ('c5583492-ec5e-42b5-b4d0-3878af3bac86', 5, 'Cutlets', 'Fry 2 cutlets at a time until deep golden, 3–4 minutes per side, until the center reaches 145°F. Drain on a rack and rest 3 minutes.', 900, 176.7, 62.8),
  ('c5583492-ec5e-42b5-b4d0-3878af3bac86', 6, 'Sandwiches', 'Spread mayonnaise on 4 slices of bread and top with cabbage. Brush each cutlet generously with katsu sauce on both sides, lay it on the cabbage and close with the remaining bread.', 180, null, null),
  ('c5583492-ec5e-42b5-b4d0-3878af3bac86', 7, 'Sandwiches', 'Press gently for a minute, trim off the crusts with a serrated knife and cut each sandwich in half or into thirds.', 120, null, null);

