values ('9597b554-4f98-4e40-8334-0204cb0c8a1f', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'vietnamese-lemongrass-chicken', 'vietnamese-lemongrass-chicken-9597b5', 'Vietnamese Lemongrass Chicken', 'Chicken thighs marinated in lemongrass, garlic, shallot and fish sauce, then seared until sticky and caramelized, served with rice, fresh herbs and a bright nước chấm dipping sauce.', 'vietnamese', 1, 45, 15, 60, 4, 'main', null, 0, array['stove', 'cast_iron']::text[], array['weeknight', 'make-ahead', 'kid-friendly']::text[], array['Frozen minced lemongrass from Asian grocers saves a lot of chopping; use about 3 tablespoons.', 'Grill option: cook over medium heat with the lid closed, 5–6 minutes per side, until 165°F.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['quick', 'main', 'dinner', 'comfort']::text[], '{}'::text[], array['spicy', 'tangy', 'fresh', 'savory']::text[], '{}'::text[], null, 'traditional', 'lemongrass-chicken', 'classic', 'Refrigerate cooked chicken up to 4 days and nước chấm up to 1 week.', null, 'owned', array['fish', 'gluten', 'soy', 'wheat']::text[], array['chicken', 'fish']::text[], array['dairy_free']::text[], array['lemongrass', 'garlic', 'shallot', 'fish sauce', 'brown sugar', 'soy sauce', 'lime juice', 'jasmine rice', 'cucumber', 'cilantro leave', 'lettuce']::text[], 'brown sugar|cilantro leave|cucumber|fish sauce|garlic|jasmine rice|lemongrass|lettuce|lime juice|shallot|soy sauce',
