insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('9597b554-4f98-4e40-8334-0204cb0c8a1f', 1, 'Chicken', 'Mix the lemongrass, garlic, shallots, fish sauce, brown sugar, soy sauce, 2 tablespoons of the oil and the pepper. Add the chicken and turn to coat. Refrigerate at least 30 minutes or up to overnight.', 1800, null, null),
  ('9597b554-4f98-4e40-8334-0204cb0c8a1f', 2, 'Nước chấm', 'Stir the sugar into the warm water until dissolved, then add the fish sauce, lime juice, garlic and chile. Taste — it should be salty, sour and sweet in balance.', null, null, null),
  ('9597b554-4f98-4e40-8334-0204cb0c8a1f', 3, 'Chicken', 'Heat the remaining tablespoon of oil in a large cast-iron skillet over medium heat. Lay in the chicken (scrape off loose bits of marinade, which burn) and cook until deeply caramelized on the bottom, 5–6 minutes.', 360, null, null),
  ('9597b554-4f98-4e40-8334-0204cb0c8a1f', 4, 'Chicken', 'Flip and cook until the other side is caramelized and the thickest part reaches 165°F, 5–6 minutes more. Turn the heat down if the sugar starts to blacken.', 360, null, 73.9),
  ('9597b554-4f98-4e40-8334-0204cb0c8a1f', 5, null, 'Rest the chicken 3 minutes, slice and serve over rice with cucumber, lettuce, herbs and the nước chấm for spooning over.', 180, null, null);

