values ('11cb8536-6cf0-4ff7-89c8-9eca03f2173a', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'creamy-tomato-soup', 'creamy-tomato-soup-11cb85', 'Creamy Tomato Soup', 'Canned whole tomatoes simmered with butter-softened onion and garlic, blended silky and finished with a splash of cream — the pantry soup made for dunking grilled cheese.', 'american', 1, 10, 35, 45, 4, 'main', null, 0, array['stove', 'blender']::text[], array['weeknight', 'budget', 'kid-friendly', 'comfort', 'make-ahead', 'freezer-friendly']::text[], array['Swap the cream for whole milk for a lighter soup, or stir a spoonful of pesto into each bowl.', 'If you use bouillon cubes or paste instead of boxed broth, read the label — some contain wheat or milk.']::text[], 'https://images.unsplash.com/photo-1692776407523-8f3c4678ad36', 'Bowl of tomato soup topped with croutons and parsley', 'Customers 1st', 'https://unsplash.com/@c1st', 'https://unsplash.com/photos/a-bowl-of-tomato-soup-with-croutons-and-parsley-6ucunWGcZxY', 'unsplash', true, 'public', false,
  'pending_review', array['soup', 'comfort', 'budget', 'main', 'dinner']::text[], array['stew', 'boil']::text[], array['rich', 'fresh']::text[], '{}'::text[], null, null, 'creamy-tomato-soup', 'classic', 'Refrigerate up to 4 days. Freeze up to 3 months, ideally before adding the cream; stir it in when you reheat.', null, 'owned', array['milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['yellow onion', 'garlic', 'tomato paste', 'tomato', 'vegetable broth', 'dried basil', 'heavy cream']::text[], 'dried basil|garlic|heavy cream|tomato|tomato paste|vegetable broth|yellow onion',
  null, null, null, null, null, null, null, null)
