values ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'broccoli-cheddar-soup', 'broccoli-cheddar-soup-bd7e7e', 'Broccoli Cheddar Soup', 'Tender broccoli and carrot in a velvety, roux-thickened broth with plenty of sharp cheddar melted in at the end — the café favorite made in one pot.', 'american', 2, 15, 30, 45, 6, 'main', null, 0, array['stove']::text[], array['weeknight', 'kid-friendly', 'comfort']::text[], array['Grate the cheese yourself: pre-shredded cheese is coated with starch that keeps it from melting smoothly.', 'If you use bouillon cubes or paste instead of boxed broth, read the label — some contain wheat or milk.']::text[], 'https://images.pexels.com/photos/5639475/pexels-photo-5639475.jpeg', 'Creamy broccoli cheddar soup in a red ceramic bowl', 'Shameel mukkath', 'https://www.pexels.com/@shameel-mukkath-3421394/', 'https://www.pexels.com/photo/creamy-soup-in-red-ceramic-bowl-5639475/', 'pexels', true, 'public', false,
  'pending_review', array['soup', 'comfort', 'main', 'dinner']::text[], array['stew', 'boil']::text[], '{}'::text[], '{}'::text[], null, null, 'broccoli-cheddar-soup', 'classic', 'Refrigerate up to 3 days and reheat gently over low heat, stirring. It doesn''t freeze well — the cheese separates.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], '{}'::text[], '{}'::text[], array['yellow onion', 'garlic', 'chicken broth', 'milk', 'broccoli', 'carrot', 'ground nutmeg', 'cheddar cheese']::text[], 'broccoli|carrot|cheddar cheese|chicken broth|garlic|ground nutmeg|milk|yellow onion',
  null, null, null, null, null, null, null, null)
