  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 1, null, '4 tbsp unsalted butter', 'unsalted butter', 4, 'tbsp', null, false),
  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 2, null, '1 yellow onion, diced', 'yellow onion', 1, null, 'diced', false),
  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 3, null, '2 cloves garlic, minced', 'garlic', 2, 'clove', 'minced', false),
  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 4, null, '¼ cup all-purpose flour', 'all-purpose flour', 0.25, 'cup', null, false),
  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 5, null, '3 cups low-sodium chicken broth, or vegetable broth', 'low-sodium chicken broth', 3, 'cup', 'or vegetable broth', false),
  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 6, null, '2 cups whole milk', 'whole milk', 2, 'cup', null, false),
  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 7, null, '1 lb broccoli, 1 large head; florets chopped small, stems peeled and diced', 'broccoli', 1, 'lb', '1 large head; florets chopped small, stems peeled and diced', false),
  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 8, null, '1 large carrot, coarsely grated', 'large carrot', 1, null, 'coarsely grated', false),
  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 9, null, '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 10, null, '¼ tsp black pepper', 'black pepper', 0.25, 'tsp', null, false),
  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 11, null, '1 pinch ground nutmeg', 'ground nutmeg', 1, 'pinch', null, false),
  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 12, null, '½ tsp dry mustard powder', 'dry mustard powder', 0.5, 'tsp', null, true),
  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 13, null, '8 oz sharp cheddar cheese, coarsely grated (about 2 cups)', 'sharp cheddar cheese', 8, 'oz', 'coarsely grated (about 2 cups)', false);
delete from public.recipe_instructions where recipe_id = 'bd7e7ebd-d308-4542-80d7-fdcc515fe231';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 1, null, 'Melt the butter in a Dutch oven or large pot over medium heat. Add the onion and cook until soft, about 5 minutes, then stir in the garlic for 30 seconds.', 360, null, null),
  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 2, null, 'Sprinkle in the flour and stir constantly for 2 minutes, until it smells toasty but hasn''t browned.', 120, null, null),
  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 3, null, 'Pour in the broth a little at a time, whisking out any lumps, then whisk in the milk. Bring to a gentle simmer, whisking often, until it thickens enough to coat a spoon, about 5 minutes.', 300, null, null),
  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 4, null, 'Add the broccoli, carrot, salt, pepper, nutmeg and mustard. Simmer gently, uncovered, stirring often and scraping the bottom so it doesn''t catch, until the broccoli is very tender, 15–18 minutes.', 960, null, null),
  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 5, null, 'For a smoother soup, blend about a third of it right in the pot with an immersion blender, leaving plenty of chunks. This is optional.', null, null, null),
  ('bd7e7ebd-d308-4542-80d7-fdcc515fe231', 6, null, 'Turn the heat to low. Add the cheese one handful at a time, stirring until each melts before adding the next. Don''t let the soup boil once the cheese is in or it can turn grainy. Taste for salt and serve.', 180, null, null);

-- Roasted Butternut Squash Soup
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
