values ('1fa35ad8-f49b-48d9-bf59-0de9c05bc412', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'roasted-butternut-squash-soup', 'roasted-butternut-squash-soup-1fa35a', 'Roasted Butternut Squash Soup', 'Butternut squash, onion, carrot and garlic roasted until caramelized, then blended with broth, a little maple and nutmeg into a silky, golden fall soup.', 'american', 1, 20, 50, 70, 6, 'main', null, 0, array['oven', 'stove', 'blender']::text[], array['make-ahead', 'freezer-friendly', 'comfort', 'fall', 'entertaining']::text[], array['Short on time? Buy 2½ lb of pre-cut squash. To peel a whole one more easily, pierce it a few times and microwave it for 3 minutes to soften the skin.', 'If you use bouillon cubes or paste instead of boxed broth, read the label — some contain wheat or milk.']::text[], 'https://images.pexels.com/photos/1277483/pexels-photo-1277483.jpeg', 'Creamy orange squash soup topped with seeds in a blue bowl', 'Valeria Boltneva', 'https://www.pexels.com/@valeriya/', 'https://www.pexels.com/photo/shallow-focus-photography-of-squash-soup-1277483/', 'pexels', true, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'holiday', 'comfort', 'entertaining']::text[], array['roast', 'stew', 'steam']::text[], array['spicy', 'rich']::text[], array['thanksgiving']::text[], null, null, 'butternut-squash-soup', 'classic', 'Refrigerate up to 5 days or freeze up to 3 months. It thickens as it sits; loosen with water when reheating.', null, 'owned', array['milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'dairy_free']::text[], array['butternut squash', 'yellow onion', 'carrot', 'garlic', 'vegetable broth', 'maple syrup', 'ground nutmeg']::text[], 'butternut squash|carrot|garlic|ground nutmeg|maple syrup|vegetable broth|yellow onion',
  null, null, null, null, null, null, null, null)
