  ('1fa35ad8-f49b-48d9-bf59-0de9c05bc412', 4, null, '4 cloves garlic, left unpeeled', 'garlic', 4, 'clove', 'left unpeeled', false),
  ('1fa35ad8-f49b-48d9-bf59-0de9c05bc412', 5, null, '3 tbsp olive oil', 'olive oil', 3, 'tbsp', null, false),
  ('1fa35ad8-f49b-48d9-bf59-0de9c05bc412', 6, null, '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('1fa35ad8-f49b-48d9-bf59-0de9c05bc412', 7, null, '½ tsp black pepper', 'black pepper', 0.5, 'tsp', null, false),
  ('1fa35ad8-f49b-48d9-bf59-0de9c05bc412', 8, null, '4 cups low-sodium vegetable broth, plus more to thin', 'low-sodium vegetable broth', 4, 'cup', 'plus more to thin', false),
  ('1fa35ad8-f49b-48d9-bf59-0de9c05bc412', 9, null, '1 tbsp maple syrup', 'maple syrup', 1, 'tbsp', null, false),
