values ('af499c71-3c55-47ae-abbe-6691e8858b3b', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'potato-leek-soup', 'potato-leek-soup-af499c', 'Potato Leek Soup', 'Leeks melted slowly in butter, simmered with Yukon Gold potatoes and blended smooth with a little cream — France''s everyday potage, mild, silky and cheap to make.', 'french', 1, 15, 35, 50, 4, 'main', null, 0, array['stove', 'blender']::text[], array['budget', 'comfort', 'make-ahead', 'weeknight']::text[], array['Chill it and serve it cold and you have vichyssoise.', 'If you use bouillon cubes or paste instead of boxed broth, read the label — some contain wheat or milk.']::text[], 'https://images.pexels.com/photos/5789/bread-healthy-white-cooking.jpg', 'Bowl of creamy leek and potato soup beside sliced baguette', 'Karolina Grabowska www.kaboompics.com', 'https://www.pexels.com/@karola-g2/', 'https://www.pexels.com/photo/leek-and-potato-soup-with-bread-5789/', 'pexels', true, 'public', false,
  'pending_review', array['soup', 'budget', 'main', 'dinner', 'comfort']::text[], array['stew', 'boil']::text[], array['rich', 'fresh']::text[], '{}'::text[], null, 'traditional', 'potato-leek-soup', 'classic', 'Refrigerate up to 4 days. Freeze up to 3 months before adding the cream, then stir it in when reheating.', null, 'owned', array['milk']::text[], '{}'::text[], '{}'::text[], array['leek', 'garlic', 'gold potato', 'chicken broth', 'bay leaf', 'thyme', 'heavy cream', 'chive']::text[], 'bay leaf|chicken broth|chive|garlic|gold potato|heavy cream|leek|thyme',
  null, null, null, null, null, null, null, null)
