values ('8e05b6c9-040a-4d53-81d1-477f84e6f688', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'black-bean-soup', 'black-bean-soup-8e05b6', 'Black Bean Soup', 'Cuban-style black bean soup built on onion, green pepper, garlic, cumin and oregano and brightened with a splash of vinegar; we use canned beans so it''s done in under an hour.', 'cuban', 1, 10, 35, 45, 4, 'main', null, 0, array['stove', 'blender']::text[], array['weeknight', 'budget', 'make-ahead', 'freezer-friendly']::text[], array['Have time? Cook 1 lb dried black beans until tender and use them with 3 cups of their cooking liquid in place of the canned beans and broth — the soup gets even richer.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['soup', 'budget', 'main', 'dinner']::text[], array['stew', 'boil']::text[], array['tangy', 'aromatic']::text[], '{}'::text[], null, 'adapted', 'black-bean-soup', 'classic', 'Refrigerate up to 5 days or freeze up to 3 months. It thickens as it stands; loosen with water when reheating.', null, 'owned', array['milk']::text[], array['beans']::text[], array['pescatarian', 'vegetarian', 'vegan', 'dairy_free']::text[], array['yellow onion', 'bell pepper', 'garlic', 'ground cumin', 'dried oregano', 'bay leaf', 'black bean', 'vegetable broth', 'wine vinegar', 'white onion']::text[], 'bay leaf|bell pepper|black bean|dried oregano|garlic|ground cumin|vegetable broth|white onion|wine vinegar|yellow onion',
  null, null, null, null, null, null, null, null)
