insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('8e05b6c9-040a-4d53-81d1-477f84e6f688', 1, 'Soup', 'Heat the oil in a large pot over medium heat. Add the onion, bell pepper and a pinch of the salt and cook, stirring, until soft, about 8 minutes.', 480, null, null),
  ('8e05b6c9-040a-4d53-81d1-477f84e6f688', 2, 'Soup', 'Stir in the garlic, cumin and oregano and cook until fragrant, about 1 minute.', 60, null, null),
  ('8e05b6c9-040a-4d53-81d1-477f84e6f688', 3, 'Soup', 'Add the beans, broth, bay leaf and remaining salt. Bring to a boil, then lower the heat and simmer partly covered for 20 minutes, stirring occasionally.', 1200, null, null),
  ('8e05b6c9-040a-4d53-81d1-477f84e6f688', 4, 'Soup', 'Remove the bay leaf. Blend about half the soup — a few pulses of an immersion blender, or ladle 2 cups into a blender (no more than half full, lid vented) and stir it back in — so it''s thick but still has plenty of whole beans.', null, null, null),
  ('8e05b6c9-040a-4d53-81d1-477f84e6f688', 5, 'Soup', 'Stir in the vinegar, simmer 2 minutes and taste for salt.', 120, null, null),
  ('8e05b6c9-040a-4d53-81d1-477f84e6f688', 6, 'To serve', 'Ladle over a scoop of rice if you like, and top with chopped onion, a spoonful of sour cream and a squeeze of lime.', null, null, null);

