values ('a1c01394-a970-4fec-98f6-174c8edc778f', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'split-pea-soup-with-ham', 'split-pea-soup-with-ham-a1c013', 'Split Pea Soup with Ham', 'Green split peas simmered low and slow with a smoky ham hock and vegetables until they collapse into a thick, hearty soup — cheap, filling and better the next day.', 'american', 1, 15, 100, 115, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['budget', 'make-ahead', 'freezer-friendly', 'comfort']::text[], array['The soup sets almost solid in the fridge; that''s normal. Loosen it with water as it reheats.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['soup', 'budget', 'comfort', 'main', 'dinner']::text[], array['stew', 'boil']::text[], array['smoky']::text[], '{}'::text[], null, null, 'split-pea-soup', 'classic', 'Refrigerate up to 5 days or freeze up to 3 months.', null, 'owned', '{}'::text[], array['pork']::text[], array['dairy_free']::text[], array['yellow onion', 'carrot', 'celery', 'garlic', 'split pea', 'ham hock', 'bay leave', 'dried thyme']::text[], 'bay leave|carrot|celery|dried thyme|garlic|ham hock|split pea|yellow onion',
