insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('a1c01394-a970-4fec-98f6-174c8edc778f', 1, null, 'Heat the oil in a Dutch oven or large pot over medium heat. Add the onion, carrots and celery and cook, stirring, until softened, about 8 minutes. Add the garlic for the last 30 seconds.', 480, null, null),
  ('a1c01394-a970-4fec-98f6-174c8edc778f', 2, null, 'Add the split peas, ham hock, water, bay leaves, thyme and pepper. Bring to a boil and skim off any foam that rises.', 300, null, null),
  ('a1c01394-a970-4fec-98f6-174c8edc778f', 3, null, 'Lower the heat so it barely bubbles, cover partly and simmer, stirring and scraping the bottom every 15 minutes (the peas like to stick), until the peas have broken down and the soup is thick, 1¼–1½ hours. Add a splash of water if it gets too thick before the peas are soft.', 4800, null, null),
  ('a1c01394-a970-4fec-98f6-174c8edc778f', 4, null, 'Lift out the ham hock and let it cool for a few minutes. Pull the meat off the bone, discard the skin, fat and bone, chop the meat and return it to the pot with the diced ham, if using.', 300, null, null),
  ('a1c01394-a970-4fec-98f6-174c8edc778f', 5, null, 'Remove the bay leaves. Stir hard with a whisk for a smoother soup, or leave it rustic. Taste and add salt only now — the ham is salty.', 120, null, null);

