values ('2a42d192-3f83-464a-8d56-1079c40daa7d', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-tortilla-soup', 'chicken-tortilla-soup-2a42d1', 'Chicken Tortilla Soup', 'A brothy, smoky tomato-and-chipotle soup with shredded chicken, black beans and corn, piled with crisp tortilla strips, avocado and lime; we bake the strips instead of frying them.', 'tex_mex', 2, 20, 40, 60, 6, 'main', null, 0, array['stove', 'oven']::text[], array['weeknight', 'make-ahead', 'freezer-friendly', 'kid-friendly']::text[], array['Chipotles are hot and smoky — start with one and add more at the end if you want.', 'Some corn tortillas are made with added wheat flour; check the package if that matters to anyone at the table.']::text[], 'https://images.pexels.com/photos/33112177/pexels-photo-33112177.jpeg', 'Bowl of Mexican tortilla soup (sopa azteca)', 'Juan TM', 'https://www.pexels.com/@juantrevilla/', 'https://www.pexels.com/photo/mexican-sopa-azteca-served-in-traditional-setting-33112177/', 'pexels', true, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'baking', 'comfort']::text[], array['stew', 'bake', 'boil']::text[], array['spicy', 'smoky', 'tangy', 'fresh', 'aromatic']::text[], '{}'::text[], null, 'adapted', 'chicken-tortilla-soup', 'classic', 'Refrigerate the soup up to 4 days or freeze up to 3 months, without toppings. Keep the strips in an airtight container at room temperature up to 3 days.', null, 'owned', array['milk']::text[], array['chicken', 'beans']::text[], array['dairy_free']::text[], array['corn tortilla', 'yellow onion', 'jalapeno', 'garlic', 'ground cumin', 'chili powder', 'dried oregano', 'fire-roasted tomato', 'adobo sauce', 'chicken broth', 'black bean', 'corn kernel', 'lime juice', 'avocado', 'cilantro', 'lime']::text[], 'adobo sauce|avocado|black bean|chicken broth|chili powder|cilantro|corn kernel|corn tortilla|dried oregano|fire-roasted tomato|garlic|ground cumin|jalapeno|lime|lime juice|yellow onion',
