  ('2a42d192-3f83-464a-8d56-1079c40daa7d', 11, 'Soup', '1 can fire-roasted diced tomatoes, 14.5 oz', 'fire-roasted diced tomatoes', 1, 'can', '14.5 oz', false),
  ('2a42d192-3f83-464a-8d56-1079c40daa7d', 12, 'Soup', '1 chipotle pepper in adobo sauce, minced, plus 1 tsp of the sauce', 'chipotle pepper in adobo sauce', 1, null, 'minced, plus 1 tsp of the sauce', false),
