  ('2a42d192-3f83-464a-8d56-1079c40daa7d', 15, 'Soup', '1 can black beans, 15 oz, drained and rinsed', 'black beans', 1, 'can', '15 oz, drained and rinsed', false),
  ('2a42d192-3f83-464a-8d56-1079c40daa7d', 16, 'Soup', '1 cup frozen corn kernels', 'frozen corn kernels', 1, 'cup', null, false),
  ('2a42d192-3f83-464a-8d56-1079c40daa7d', 17, 'Soup', '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
