insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('2a42d192-3f83-464a-8d56-1079c40daa7d', 1, 'Tortilla strips', 'Heat the oven to 400°F. Toss the tortilla strips with the oil and salt on a sheet pan and spread them out. Bake, stirring once, until crisp and golden, 10–14 minutes. They crisp more as they cool.', 720, 204.4, null),
  ('2a42d192-3f83-464a-8d56-1079c40daa7d', 2, 'Soup', 'Meanwhile, heat the oil in a large pot over medium heat. Cook the onion and jalapeño until soft, about 6 minutes. Add the garlic, cumin, chili powder and oregano and stir 1 minute.', 420, null, null),
  ('2a42d192-3f83-464a-8d56-1079c40daa7d', 3, 'Soup', 'Add the tomatoes, chipotle and adobo sauce and the broth and bring to a boil. Add the chicken whole, lower the heat, cover and simmer until the thickest piece reads 165°F, 15–20 minutes.', 1080, null, 73.9),
  ('2a42d192-3f83-464a-8d56-1079c40daa7d', 4, 'Soup', 'Move the chicken to a board and shred it with two forks.', 180, null, null),
  ('2a42d192-3f83-464a-8d56-1079c40daa7d', 5, 'Soup', 'Return the chicken to the pot with the beans and corn and simmer 5 minutes. Stir in the lime juice and salt, then taste and adjust.', 300, null, null),
  ('2a42d192-3f83-464a-8d56-1079c40daa7d', 6, 'To serve', 'Ladle into bowls and top with tortilla strips, avocado, cilantro, cheese and sour cream, with lime wedges on the side.', null, null, null);

