values ('91f02eb0-2df5-42c9-b62f-3a1adaa4e110', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'sweet-corn-chowder', 'sweet-corn-chowder-91f02e', 'Sweet Corn Chowder', 'A creamy summer chowder of fresh corn, potatoes and smoky bacon, with the stripped cobs simmered in the broth for extra sweet corn flavor.', 'american', 1, 20, 35, 55, 6, 'main', null, 0, array['stove', 'blender']::text[], array['summer', 'comfort', 'kid-friendly']::text[], array['Leave out the bacon and use vegetable broth and 1 more tablespoon of butter for a meatless chowder; a pinch of smoked paprika brings back some smokiness.']::text[], 'https://images.pexels.com/photos/6693174/pexels-photo-6693174.jpeg', 'Creamy corn chowder topped with croutons and parsley in a white bowl', 'Max Griss', 'https://www.pexels.com/@max-griss-16866522/', 'https://www.pexels.com/photo/a-mouthwatering-corn-soup-6693174/', 'pexels', true, 'public', false,
  'pending_review', array['soup', 'comfort', 'main', 'dinner']::text[], array['stew', 'boil']::text[], array['rich', 'fresh']::text[], '{}'::text[], null, null, 'corn-chowder', 'classic', 'Refrigerate up to 3 days and reheat gently. It doesn''t freeze well — the potatoes turn grainy.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], array['pork']::text[], '{}'::text[], array['thick-cut bacon', 'yellow onion', 'celery', 'bell pepper', 'garlic', 'chicken broth', 'gold potato', 'ear corn', 'thyme', 'milk', 'heavy cream', 'chive']::text[], 'bell pepper|celery|chicken broth|chive|ear corn|garlic|gold potato|heavy cream|milk|thick-cut bacon|thyme|yellow onion',
  null, null, null, null, null, null, null, null)
