insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('91f02eb0-2df5-42c9-b62f-3a1adaa4e110', 1, null, 'Cook the bacon in a large pot over medium heat, stirring, until crisp, about 8 minutes. Lift it out onto paper towels and leave about 2 tablespoons of fat in the pot. Add the butter.', 480, null, null),
  ('91f02eb0-2df5-42c9-b62f-3a1adaa4e110', 2, null, 'Add the onion, celery and bell pepper and cook until soft, about 6 minutes. Stir in the garlic and flour and cook 1 minute, stirring.', 420, null, null),
  ('91f02eb0-2df5-42c9-b62f-3a1adaa4e110', 3, null, 'Slowly whisk in the broth, then add the potatoes, the corn cobs snapped in half and the thyme. Bring to a boil, lower the heat and simmer until the potatoes are tender, 12–15 minutes.', 840, null, null),
  ('91f02eb0-2df5-42c9-b62f-3a1adaa4e110', 4, null, 'Remove the cobs, scraping any pulp back into the pot with the back of a knife, and the thyme stems. Add the corn kernels, milk and cream and simmer gently until the corn is tender, about 5 minutes — keep it below a hard boil.', 300, null, null),
  ('91f02eb0-2df5-42c9-b62f-3a1adaa4e110', 5, null, 'Blend about 2 cups of the chowder (a few pulses of an immersion blender, or in a half-full countertop blender with the lid vented) and stir it back in for a creamy body. Season with the salt and pepper and top each bowl with bacon and chives.', 120, null, null);

