values ('e921b0ee-ae93-4925-afd8-75b670f33cfc', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'classic-caesar-salad', 'classic-caesar-salad-e921b0', 'Classic Caesar Salad', 'Crisp romaine tossed in a garlicky, lemony anchovy-and-Parmesan dressing whisked by hand, with homemade olive-oil croutons.', 'american', 2, 20, 12, 32, 4, 'side', null, 0, array['oven']::text[], array['entertaining']::text[], array['No pasteurized eggs? Replace the yolk with 3 tablespoons of store-bought mayonnaise, which is made with pasteurized eggs, for a dressing without raw egg.', 'Top with sliced grilled chicken or shrimp to make it a main course.']::text[], 'https://images.unsplash.com/photo-1746211108786-ca20c8f80ecd', 'Caesar salad with croutons', 'Cliffer Rebelo', 'https://unsplash.com/@cliffer14', 'https://unsplash.com/photos/delicious-caesar-salad-is-presented-on-a-table-UdLsLK_KFLw', 'unsplash', true, 'public', false,
  'pending_review', array['salad', 'side', 'entertaining']::text[], array['bake']::text[], array['tangy', 'savory']::text[], '{}'::text[], null, null, 'caesar-salad', 'classic', 'Refrigerate the dressing up to 2 days and keep the croutons airtight at room temperature up to 3 days. Dressed salad doesn''t keep.', 'This uses raw eggs. Use pasteurized eggs, and don''t serve it to anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['egg', 'fish', 'gluten', 'milk', 'wheat']::text[], array['fish']::text[], array['pescatarian']::text[], array['crusty bread', 'garlic', 'egg yolk', 'oil-packed anchovy', 'lemon juice', 'dijon mustard', 'worcestershire sauce', 'parmesan cheese', 'romaine lettuce']::text[], 'crusty bread|dijon mustard|egg yolk|garlic|lemon juice|oil-packed anchovy|parmesan cheese|romaine lettuce|worcestershire sauce',
  null, null, null, null, null, null, null, null)
