  ('e921b0ee-ae93-4925-afd8-75b670f33cfc', 1, 'Croutons', '4 cups crusty bread, about half a baguette, cut into ¾-inch cubes', 'crusty bread', 4, 'cup', 'about half a baguette, cut into ¾-inch cubes', false),
  ('e921b0ee-ae93-4925-afd8-75b670f33cfc', 2, 'Croutons', '3 tbsp extra-virgin olive oil', 'extra-virgin olive oil', 3, 'tbsp', null, false),
