  ('e921b0ee-ae93-4925-afd8-75b670f33cfc', 5, 'Dressing', '1 large egg yolk, pasteurized recommended', 'large egg yolk', 1, null, 'pasteurized recommended', false),
  ('e921b0ee-ae93-4925-afd8-75b670f33cfc', 6, 'Dressing', '4 fillet oil-packed anchovies, minced, or 2 tsp anchovy paste', 'oil-packed anchovies', 4, 'fillet', 'minced, or 2 tsp anchovy paste', false),
  ('e921b0ee-ae93-4925-afd8-75b670f33cfc', 7, 'Dressing', '1 clove garlic, finely grated', 'garlic', 1, 'clove', 'finely grated', false),
  ('e921b0ee-ae93-4925-afd8-75b670f33cfc', 8, 'Dressing', '2 tbsp fresh lemon juice', 'fresh lemon juice', 2, 'tbsp', null, false),
