  ('e921b0ee-ae93-4925-afd8-75b670f33cfc', 11, 'Dressing', '½ cup extra-virgin olive oil, or half olive oil, half vegetable oil', 'extra-virgin olive oil', 0.5, 'cup', 'or half olive oil, half vegetable oil', false),
  ('e921b0ee-ae93-4925-afd8-75b670f33cfc', 12, 'Dressing', '½ cup Parmesan cheese, finely grated', 'Parmesan cheese', 0.5, 'cup', 'finely grated', false),
