values ('99cc9bcc-69e4-4be3-bad6-490d6b54c096', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'cobb-salad', 'cobb-salad-99cc9b', 'Cobb Salad', 'The Hollywood classic: crisp greens lined with rows of seared chicken, bacon, hard-cooked egg, avocado, tomato and blue cheese, with a tangy red wine vinaigrette.', 'american', 2, 25, 30, 55, 4, 'main', null, 0, array['stove']::text[], array['entertaining', 'make-ahead']::text[], array['Shortcut: use 3 cups of diced rotisserie chicken and skip the chicken step.', 'Worcestershire sauce contains anchovies — leave it out of the dressing if anyone avoids fish.']::text[], 'https://images.pexels.com/photos/10480250/pexels-photo-10480250.jpeg', 'Cobb salad with chicken, egg, bacon, avocado and tomato on a white plate', 'Alberta Studios', 'https://www.pexels.com/@iamabdullahsheik/', 'https://www.pexels.com/photo/cobb-salad-in-white-ceramic-plate-10480250/', 'pexels', true, 'public', false,
  'pending_review', array['salad', 'main', 'dinner', 'entertaining']::text[], array['boil']::text[], array['tangy', 'fresh', 'savory']::text[], '{}'::text[], 'California', 'traditional', 'cobb-salad', 'classic', 'Keep the components separately in the fridge up to 3 days; dice the avocado and dress the salad just before serving.', null, 'owned', array['egg', 'fish', 'milk']::text[], array['chicken', 'pork']::text[], array['gluten_free']::text[], array['egg', 'bacon', 'avocado', 'cherry tomato', 'blue cheese', 'chive', 'romaine lettuce', 'watercress', 'wine vinegar', 'lemon juice', 'dijon mustard', 'worcestershire sauce', 'garlic']::text[], 'avocado|bacon|blue cheese|cherry tomato|chive|dijon mustard|egg|garlic|lemon juice|romaine lettuce|watercress|wine vinegar|worcestershire sauce',
  null, null, null, null, null, null, null, null)
