  ('99cc9bcc-69e4-4be3-bad6-490d6b54c096', 12, 'Greens', '2 cups watercress, tough stems removed, or baby arugula', 'watercress', 2, 'cup', 'tough stems removed, or baby arugula', false),
  ('99cc9bcc-69e4-4be3-bad6-490d6b54c096', 13, 'Dressing', '¼ cup red wine vinegar', 'red wine vinegar', 0.25, 'cup', null, false),
