delete from public.recipe_instructions where recipe_id = '99cc9bcc-69e4-4be3-bad6-490d6b54c096';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('99cc9bcc-69e4-4be3-bad6-490d6b54c096', 1, 'Toppings', 'Put the eggs in a saucepan, cover with cold water by 1 inch and bring to a full boil. Cover, take off the heat and let stand 11 minutes, then move to a bowl of ice water for 5 minutes. Peel and chop — the yolks should be completely firm.', 1200, null, null),
  ('99cc9bcc-69e4-4be3-bad6-490d6b54c096', 2, 'Toppings', 'Meanwhile, cook the bacon in a large skillet over medium heat, turning, until crisp, 8–10 minutes. Drain on paper towels and crumble. Pour off all but 1 tablespoon of the fat.', 540, null, null),
  ('99cc9bcc-69e4-4be3-bad6-490d6b54c096', 3, 'Chicken', 'Pound the chicken breasts to an even ¾-inch thickness and season with the salt and pepper. Add the oil to the skillet and cook the chicken over medium-high heat until browned and 165°F in the thickest part, 5–6 minutes per side. Rest 5 minutes, then dice.', 720, null, 73.9),
  ('99cc9bcc-69e4-4be3-bad6-490d6b54c096', 4, 'Dressing', 'Shake all the dressing ingredients together in a jar until creamy.', null, null, null),
  ('99cc9bcc-69e4-4be3-bad6-490d6b54c096', 5, null, 'Spread the romaine and watercress on a large platter. Arrange the chicken, bacon, eggs, avocado, tomatoes and blue cheese over the greens in neat rows and sprinkle with chives. Bring it to the table with the dressing and toss just before serving.', null, null, null);

