values ('23aa3ea6-73ed-4bbd-b9cb-81d464292c38', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'classic-potato-salad', 'classic-potato-salad-23aa3e', 'Classic Potato Salad', 'Tender potatoes seasoned with vinegar while still warm, folded with a creamy mustard-mayo dressing, chopped egg, celery, onion and pickle relish — the cookout staple.', 'american', 1, 20, 20, 100, 8, 'side', null, 60, array['stove']::text[], array['make-ahead', 'budget', 'kid-friendly']::text[], array['Starting the potatoes in cold water cooks them evenly, so the outsides don''t fall apart before the centers are done.', 'Mayonnaise salads shouldn''t sit out more than 2 hours (1 hour above 90°F). At a picnic, nest the bowl in a larger bowl of ice.']::text[], 'https://images.pexels.com/photos/30146054/pexels-photo-30146054.jpeg', 'Creamy potato salad in a white bowl on a checkered tablecloth', 'tom davis', 'https://www.pexels.com/@tom-davis-2148511154/', 'https://www.pexels.com/photo/delicious-homemade-potato-salad-on-picnic-table-30146054/', 'pexels', true, 'public', false,
  'pending_review', array['salad', 'side', 'holiday', 'budget', 'comfort']::text[], array['stew', 'boil']::text[], array['tangy', 'fresh']::text[], array['picnic', 'july-4th', 'potluck']::text[], null, null, 'potato-salad', 'classic', 'Refrigerate up to 3 days.', null, 'owned', array['egg']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free', 'dairy_free']::text[], array['red potato', 'cider vinegar', 'egg', 'mayonnaise', 'yellow mustard', 'celery', 'red onion', 'pickle relish', 'dill parsley', 'paprika']::text[], 'celery|cider vinegar|dill parsley|egg|mayonnaise|paprika|pickle relish|red onion|red potato|yellow mustard',
  null, null, null, null, null, null, null, null)
