insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('23aa3ea6-73ed-4bbd-b9cb-81d464292c38', 1, 'Potatoes', 'Put the eggs in a saucepan, cover with cold water by 1 inch and bring to a full boil. Cover, take off the heat and let stand 11 minutes, then cool in ice water for 5 minutes. Peel and chop — the yolks should be completely firm.', 1200, null, null),
  ('23aa3ea6-73ed-4bbd-b9cb-81d464292c38', 2, 'Potatoes', 'Meanwhile, put the potatoes in a large pot, cover with cold water by 1 inch and add the tablespoon of salt. Bring to a boil, then simmer until a knife slides in with little resistance but the chunks still hold their shape, 10–15 minutes.', 900, null, null),
  ('23aa3ea6-73ed-4bbd-b9cb-81d464292c38', 3, 'Potatoes', 'Drain well, spread the potatoes on a sheet pan and sprinkle with the vinegar while they''re hot so they soak it up. Let cool 15 minutes.', 900, null, null),
  ('23aa3ea6-73ed-4bbd-b9cb-81d464292c38', 4, 'Dressing', 'In a large bowl, stir together the mayonnaise, mustard, salt and pepper, then fold in the celery, onion and relish.', null, null, null),
  ('23aa3ea6-73ed-4bbd-b9cb-81d464292c38', 5, null, 'Gently fold in the potatoes and eggs. Cover and chill at least 1 hour so the flavors meld. Sprinkle with paprika and dill before serving.', 3600, null, null);

