insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('5a4affb2-d649-468d-a2cf-7cd536723f40', 1, 'Pasta', 'Bring a large pot of water to a boil with the salt. Cook the macaroni 1–2 minutes past the package''s al dente time so it''s fully tender — it firms up in the fridge.', 600, null, null),
  ('5a4affb2-d649-468d-a2cf-7cd536723f40', 2, 'Pasta', 'Drain, rinse under cold running water until cool, then drain very well, shaking the colander so no water dilutes the dressing.', 120, null, null),
  ('5a4affb2-d649-468d-a2cf-7cd536723f40', 3, 'Dressing', 'In a large bowl, whisk the mayonnaise, vinegar, mustard, sugar, salt, pepper and milk until smooth.', null, null, null),
  ('5a4affb2-d649-468d-a2cf-7cd536723f40', 4, null, 'Add the macaroni and vegetables and stir until everything is coated. Cover and chill at least 1 hour.', 3600, null, null),
  ('5a4affb2-d649-468d-a2cf-7cd536723f40', 5, null, 'Just before serving, stir in a splash of milk or a spoonful of mayonnaise — the pasta drinks up dressing as it sits. Taste for salt.', null, null, null);

-- Deviled Eggs
