values ('74afe7f3-2bb2-42f1-9c48-d717d81988f0', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'deviled-eggs', 'deviled-eggs-74afe7', 'Deviled Eggs', 'Hard-cooked egg whites filled with a smooth, tangy yolk-and-mayo filling and dusted with smoky paprika — the party platter that always empties first.', 'american', 1, 20, 15, 65, 6, 'starter', null, 30, array['stove']::text[], array['make-ahead', 'entertaining', 'kid-friendly', 'budget']::text[], array['Keep them cold: deviled eggs shouldn''t sit out more than 2 hours (1 hour above 90°F). Set the platter over ice at outdoor parties.', 'A green ring around the yolk means the eggs were overcooked — cool them in ice water right on time.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['appetizer', 'holiday', 'budget', 'comfort', 'entertaining']::text[], array['boil']::text[], array['smoky', 'tangy', 'fresh']::text[], array['easter', 'picnic', 'potluck']::text[], null, null, 'deviled-eggs', 'classic', 'Fill up to 1 day ahead and keep covered in the fridge, or store the whites and filling separately up to 2 days and fill before serving.', null, 'owned', array['egg']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free', 'dairy_free']::text[], array['egg', 'mayonnaise', 'dijon mustard', 'cider vinegar', 'smoked paprika']::text[], 'cider vinegar|dijon mustard|egg|mayonnaise|smoked paprika',
