insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('74afe7f3-2bb2-42f1-9c48-d717d81988f0', 1, null, 'Put the eggs in a saucepan in a single layer and cover with cold water by 1 inch. Bring to a full boil over high heat, cover, take off the heat and let stand 12 minutes.', 900, null, null),
  ('74afe7f3-2bb2-42f1-9c48-d717d81988f0', 2, null, 'Move the eggs to a bowl of ice water for 10 minutes. Tap each one all over on the counter and peel under cool running water.', 600, null, null),
  ('74afe7f3-2bb2-42f1-9c48-d717d81988f0', 3, null, 'Halve the eggs lengthwise, wiping the knife between cuts, and pop the yolks into a bowl. Set the whites on a platter.', null, null, null),
  ('74afe7f3-2bb2-42f1-9c48-d717d81988f0', 4, null, 'Mash the yolks very finely with a fork, then stir in the mayonnaise, mustard, vinegar, relish, salt and pepper until smooth.', null, null, null),
  ('74afe7f3-2bb2-42f1-9c48-d717d81988f0', 5, null, 'Spoon the filling into the whites, or pipe it from a zip-top bag with a corner snipped off. Dust with paprika and chives and chill until serving.', 1800, null, null);

