values ('d122e35f-9526-4b5e-a287-08999e76bbc1', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'grilled-cheese-sandwich', 'grilled-cheese-sandwich-d122e3', 'Grilled Cheese Sandwich', 'Buttery, golden, crackly bread around a molten center of sharp cheddar, cooked low and slow under a lid so the cheese melts before the bread burns.', 'american', 1, 5, 15, 20, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'quick', 'kid-friendly', 'budget', 'comfort']::text[], array['For an extra-crisp, evenly browned crust, swap the butter on the outside for a thin layer of mayonnaise.', 'Serve with Creamy Tomato Soup for dunking.']::text[], 'https://images.unsplash.com/photo-1634598603851-1c2987de821f', 'Grilled cheese sandwich browning in a frying pan', 'Gio Bartlett', 'https://unsplash.com/@giobartlett', 'https://unsplash.com/photos/a-toasted-sandwich-in-a-frying-pan-on-a-stove-OV4oTyLfvDo', 'unsplash', true, 'public', false,
  'pending_review', array['lunch', 'quick', 'comfort', 'main', 'dinner', 'budget']::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, 'grilled-cheese', 'classic', 'Best eaten hot. Reheat leftovers in a dry skillet or air fryer, not the microwave.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['sandwich bread', 'cheddar cheese']::text[], 'cheddar cheese|sandwich bread',
  null, null, null, null, null, null, null, null)
