  ('d122e35f-9526-4b5e-a287-08999e76bbc1', 3, null, '8 oz sharp cheddar cheese, coarsely grated (about 2 cups)', 'sharp cheddar cheese', 8, 'oz', 'coarsely grated (about 2 cups)', false),
  ('d122e35f-9526-4b5e-a287-08999e76bbc1', 4, null, '4 slice American cheese, for extra melt', 'American cheese', 4, 'slice', 'for extra melt', true);
