insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('d122e35f-9526-4b5e-a287-08999e76bbc1', 1, null, 'Spread one side of each slice of bread with butter, all the way to the edges.', null, null, null),
  ('d122e35f-9526-4b5e-a287-08999e76bbc1', 2, null, 'Set 4 slices butter-side down on a board. Pile on the cheddar (and a slice of American cheese, if using) and top with the remaining slices, butter-side up.', null, null, null),
  ('d122e35f-9526-4b5e-a287-08999e76bbc1', 3, null, 'Heat a large nonstick or cast-iron skillet over medium-low heat for 2 minutes. Add as many sandwiches as fit, cover with a lid and cook until the bottoms are deep golden, 3–4 minutes.', 240, null, null),
  ('d122e35f-9526-4b5e-a287-08999e76bbc1', 4, null, 'Flip, press gently with a spatula and cook uncovered until the second side is golden and the cheese has melted, about 3 minutes. Repeat with any remaining sandwiches.', 180, null, null),
  ('d122e35f-9526-4b5e-a287-08999e76bbc1', 5, null, 'Let rest 1 minute so the cheese doesn''t all run out, then cut in half diagonally.', 60, null, null);

-- BLT Sandwich
