values ('f68da78f-9b05-4ab5-8d05-cb58816f68f8', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'blt-sandwich', 'blt-sandwich-f68da7', 'BLT Sandwich', 'Crisp oven-baked bacon, juicy salted tomato and cold crunchy lettuce on toast slathered with mayonnaise — simple, and perfect in tomato season.', 'american', 1, 10, 20, 30, 4, 'main', null, 0, array['oven']::text[], array['weeknight', 'quick', 'summer', 'kid-friendly']::text[], array['Let the bacon fat cool and set on the foil, then fold it up and throw it away — never pour hot fat down the drain.']::text[], 'https://images.unsplash.com/photo-1722041220514-f6a26e286f2e', 'Bacon, lettuce and tomato sandwich on a plate', 'David Trinks', 'https://unsplash.com/@dtrinksrph', 'https://unsplash.com/photos/a-bacon-tomato-and-lettuce-sandwich-on-a-plate-p5K85hCgf2w', 'unsplash', true, 'public', false,
  'pending_review', array['lunch', 'quick', 'main', 'dinner', 'comfort']::text[], array['bake']::text[], '{}'::text[], '{}'::text[], null, null, 'blt', 'classic', 'Best assembled right before eating. Cooked bacon keeps in the fridge up to 4 days; re-crisp it in the oven or a skillet.', null, 'owned', array['egg', 'gluten', 'wheat']::text[], array['pork']::text[], array['dairy_free']::text[], array['thick-cut bacon', 'tomato', 'sandwich bread', 'mayonnaise', 'iceberg lettuce']::text[], 'iceberg lettuce|mayonnaise|sandwich bread|thick-cut bacon|tomato',
  null, null, null, null, null, null, null, null)
