insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('f68da78f-9b05-4ab5-8d05-cb58816f68f8', 1, null, 'Heat the oven to 400°F. Line a rimmed sheet pan with foil and lay the bacon on it in a single layer without overlapping.', null, 204.4, null),
  ('f68da78f-9b05-4ab5-8d05-cb58816f68f8', 2, null, 'Bake until browned and crisp, 15–20 minutes, checking from 12 minutes since thickness varies. Drain on paper towels.', 1020, 204.4, null),
  ('f68da78f-9b05-4ab5-8d05-cb58816f68f8', 3, null, 'While the bacon bakes, lay the tomato slices on paper towels and season with the salt and pepper.', null, null, null),
  ('f68da78f-9b05-4ab5-8d05-cb58816f68f8', 4, null, 'Toast the bread and spread one side of each slice with mayonnaise.', 180, null, null),
  ('f68da78f-9b05-4ab5-8d05-cb58816f68f8', 5, null, 'On 4 slices, layer lettuce, tomato and 3 slices of bacon (broken to fit). Top with the remaining bread, mayo-side down, press gently and cut in half diagonally.', null, null, null);

