values ('1d007bc1-9b0b-4df2-a8ab-01465c92af35', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'reuben-sandwich', 'reuben-sandwich-1d007b', 'Reuben Sandwich', 'Warm corned beef, tangy sauerkraut, melted Swiss and homemade Russian dressing griddled between buttery slices of rye until crisp — the deli classic at home.', 'american', 2, 10, 15, 25, 4, 'main', null, 0, array['stove']::text[], array['comfort', 'quick']::text[], array['Squeeze the sauerkraut really dry in your hands or a towel so the bread stays crisp.', 'Worcestershire sauce contains anchovies — leave it out of the dressing if anyone avoids fish.']::text[], 'https://images.pexels.com/photos/23531331/pexels-photo-23531331.jpeg', 'Close-up of a rye bread sandwich stacked with cured beef, cheese and sauerkraut', 'Anthony Rahayel', 'https://www.pexels.com/@anthony-rahayel-125801377/', 'https://www.pexels.com/photo/close-up-of-a-ham-sandwich-23531331/', 'pexels', true, 'public', false,
  'pending_review', array['lunch', 'comfort', 'main', 'dinner', 'quick', 'holiday']::text[], '{}'::text[], array['fresh', 'savory']::text[], array['game-day']::text[], null, null, 'reuben', 'classic', 'Best eaten hot. The dressing keeps in the fridge up to 1 week.', null, 'owned', array['egg', 'fish', 'gluten', 'milk', 'wheat']::text[], array['beef']::text[], '{}'::text[], array['mayonnaise', 'ketchup', 'prepared horseradish', 'dill pickle', 'worcestershire sauce', 'paprika', 'corned beef', 'sauerkraut', 'rye bread', 'swiss cheese']::text[], 'corned beef|dill pickle|ketchup|mayonnaise|paprika|prepared horseradish|rye bread|sauerkraut|swiss cheese|worcestershire sauce',
  null, null, null, null, null, null, null, null)
