values ('beb8b9bb-72fe-4cca-975a-d5a37a505997', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-salad-sandwich', 'chicken-salad-sandwich-beb8b9', 'Chicken Salad Sandwich', 'Gently poached chicken folded into a lemony mayo dressing with celery, grapes, toasted pecans and dill, piled on soft bread with lettuce.', 'american', 1, 15, 20, 65, 4, 'main', null, 30, array['stove']::text[], array['make-ahead', 'kid-friendly']::text[], array['Shortcut: use 3 cups of diced rotisserie chicken and skip the poaching.', 'Save the poaching liquid — strain it and use it as a light broth for soup or rice.']::text[], 'https://images.unsplash.com/photo-1754652327450-23700a7a6bb4', 'Chicken salad sandwich on white bread', 'Dillon Lobo', 'https://unsplash.com/@dillon_lobo', 'https://unsplash.com/photos/a-chicken-salad-sandwich-on-white-bread-Ek3FFUe6-4o', 'unsplash', true, 'public', false,
  'pending_review', array['lunch', 'main', 'dinner', 'salad', 'holiday', 'comfort']::text[], array['stew', 'poach']::text[], array['tangy', 'fresh']::text[], array['picnic']::text[], null, null, 'chicken-salad-sandwich', 'classic', 'Refrigerate the chicken salad up to 3 days; assemble sandwiches just before eating so the bread doesn''t go soggy.', null, 'owned', array['egg', 'gluten', 'tree_nut', 'wheat']::text[], array['chicken']::text[], array['dairy_free']::text[], array['bay leaf', 'black peppercorn', 'mayonnaise', 'lemon juice', 'dijon mustard', 'celery', 'dill parsley', 'sandwich bread', 'leaf lettuce']::text[], 'bay leaf|black peppercorn|celery|dijon mustard|dill parsley|leaf lettuce|lemon juice|mayonnaise|sandwich bread',
