insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('beb8b9bb-72fe-4cca-975a-d5a37a505997', 1, 'Chicken', 'Lay the chicken in a saucepan in a single layer, cover with cold water by 1 inch and add the salt, bay leaf and peppercorns. Bring to a bare simmer over medium heat, then turn to low, cover and poach gently until the thickest part reads 165°F, 12–15 minutes.', 1080, null, 73.9),
  ('beb8b9bb-72fe-4cca-975a-d5a37a505997', 2, 'Chicken', 'Transfer the chicken to a plate and let it cool 15 minutes (or chill it), then dice or shred it finely.', 900, null, null),
  ('beb8b9bb-72fe-4cca-975a-d5a37a505997', 3, 'Salad', 'In a large bowl, stir the mayonnaise, lemon juice, mustard, salt and pepper together. Fold in the chicken, celery, grapes, pecans and dill, then taste and adjust.', null, null, null),
  ('beb8b9bb-72fe-4cca-975a-d5a37a505997', 4, null, 'Chill for 30 minutes if you have time, then pile onto the bread with lettuce.', 1800, null, null);

