values ('1109ce60-f56c-4368-a755-90ead3c85e57', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'tuna-melt', 'tuna-melt-1109ce', 'Tuna Melt', 'Classic diner tuna salad with celery, onion and pickle, griddled in buttery bread with melted cheddar until crisp outside and gooey inside.', 'american', 1, 10, 10, 20, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'quick', 'budget']::text[], array['For open-faced melts, toast the bread, top with tuna salad and cheese, and broil 2–3 minutes until bubbly — watch it closely.']::text[], 'https://images.unsplash.com/photo-1788791069117-574bda4b6635', 'Grilled tuna melt with char marks beside a small bowl of greens', 'Carl Tronders', 'https://unsplash.com/@allvar', 'https://unsplash.com/photos/grilled-cheese-sandwich-lunch-fgvYsZlS1TU', 'unsplash', true, 'public', false,
