insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('1109ce60-f56c-4368-a755-90ead3c85e57', 1, null, 'In a bowl, mix the tuna, mayonnaise, celery, onion, relish, mustard, lemon juice and pepper, flaking the tuna with a fork.', null, null, null),
  ('1109ce60-f56c-4368-a755-90ead3c85e57', 2, null, 'Butter one side of each slice of bread. On 4 slices, butter-side down, layer a slice of cheese, about ½ cup tuna salad, a few tomato slices if using, and a second slice of cheese. Top with the remaining bread, butter-side up.', null, null, null),
  ('1109ce60-f56c-4368-a755-90ead3c85e57', 3, null, 'Cook in a large skillet over medium-low heat, covered, until the bottoms are golden, about 4 minutes.', 240, null, null),
  ('1109ce60-f56c-4368-a755-90ead3c85e57', 4, null, 'Flip, press gently and cook uncovered until golden and the cheese has melted, 3–4 minutes more. Rest 1 minute and cut in half.', 240, null, null);

