insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('6bc6cd31-82d2-4560-b90a-566df9b56231', 1, null, 'Heat the oven to 400°F. Lay the bacon on a foil-lined rimmed sheet pan in a single layer and bake until crisp, 15–20 minutes. Drain on paper towels and break each slice in half.', 1020, 204.4, null),
  ('6bc6cd31-82d2-4560-b90a-566df9b56231', 2, null, 'Toast the bread. Spread mayonnaise on one side of 8 slices and on both sides of the remaining 4 — those are the middle layers.', 240, null, null),
  ('6bc6cd31-82d2-4560-b90a-566df9b56231', 3, null, 'For each sandwich, top a bottom slice (mayo-side up) with turkey and lettuce. Add a middle slice, then bacon and tomato seasoned with a little salt and pepper. Finish with a top slice, mayo-side down.', null, null, null),
  ('6bc6cd31-82d2-4560-b90a-566df9b56231', 4, null, 'Push 4 toothpicks or cocktail picks through each sandwich, one in each quarter, then cut corner to corner both ways into 4 triangles. Remind everyone to pull out the picks before eating.', null, null, null);

