values ('037aaebd-63f7-49de-a2f4-28347af0f707', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'barbecue-baked-beans', 'barbecue-baked-beans-037aae', 'Barbecue Baked Beans', 'Navy beans baked low and slow in a smoky-sweet sauce of molasses, brown sugar, ketchup and mustard, with bacon cooked in and crisped on top.', 'southern', 1, 15, 105, 120, 8, 'side', null, 0, array['stove', 'oven', 'dutch_oven']::text[], array['make-ahead', 'budget', 'crowd-pleaser']::text[], array['Worcestershire sauce contains anchovies, and many barbecue sauces include it too; some also contain wheat or soy. Check the barbecue sauce label if anyone at the table has allergies.', 'Slow cooker: after step 3, transfer to a slow cooker and cook on low 4–5 hours with the lid slightly ajar so the sauce can thicken.']::text[], 'https://images.pexels.com/photos/30146171/pexels-photo-30146171.jpeg', 'Barbecue baked beans in a white bowl on a red checkered tablecloth', 'tom davis', 'https://www.pexels.com/@tom-davis-2148511154/', 'https://www.pexels.com/photo/delicious-baked-beans-on-red-checkered-tablecloth-30146171/', 'pexels', true, 'public', false,
  'pending_review', array['side', 'holiday', 'budget']::text[], array['stew', 'bake']::text[], array['smoky', 'tangy', 'savory']::text[], array['july-4th', 'picnic', 'potluck', 'game-day']::text[], null, 'traditional', 'baked-beans', 'classic', 'Refrigerate up to 5 days or freeze up to 3 months. They taste even better the next day.', null, 'owned', array['fish']::text[], array['pork', 'beans']::text[], array['gluten_free', 'dairy_free']::text[], array['bacon', 'yellow onion', 'bell pepper', 'garlic', 'ketchup', 'barbecue sauce', 'brown sugar', 'molasse', 'yellow mustard', 'cider vinegar', 'worcestershire sauce', 'smoked paprika', 'navy bean']::text[], 'bacon|barbecue sauce|bell pepper|brown sugar|cider vinegar|garlic|ketchup|molasse|navy bean|smoked paprika|worcestershire sauce|yellow mustard|yellow onion',
  null, null, null, null, null, null, null, null)
