values ('a6385f83-3ef9-4439-8636-07577b7194fa', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'roasted-brussels-sprouts-balsamic', 'roasted-brussels-sprouts-with-balsamic-a6385f', 'Roasted Brussels Sprouts with Balsamic', 'Brussels sprouts roasted cut-side down on a preheated pan until deeply browned and crisp-edged, then tossed in a quick balsamic-honey glaze.', 'american', 1, 10, 25, 35, 4, 'side', null, 0, array['oven', 'stove']::text[], array['weeknight', 'entertaining']::text[], array['Give the sprouts room: crowded on the pan they steam and go soft instead of browning. Use two pans for a double batch.']::text[], 'https://images.pexels.com/photos/3510155/pexels-photo-3510155.jpeg', 'Browned roasted Brussels sprout halves in a cast-iron skillet', 'Sebastian Coman Photography', 'https://www.pexels.com/@sebastian-coman-photography-1598188/', 'https://www.pexels.com/photo/cooked-vegetable-on-pan-3510155/', 'pexels', true, 'public', false,
  'pending_review', array['side', 'holiday', 'entertaining']::text[], array['roast', 'stew']::text[], array['spicy', 'tangy', 'savory']::text[], array['thanksgiving', 'christmas']::text[], null, null, 'roasted-brussels-sprouts', 'classic', 'Refrigerate up to 3 days. Re-crisp in a hot oven or air fryer for 5 minutes.', null, 'owned', array['milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free', 'dairy_free']::text[], array['brussel sprout', 'balsamic vinegar', 'honey']::text[], 'balsamic vinegar|brussel sprout|honey',
  null, null, null, null, null, null, null, null)
