  ('a6385f83-3ef9-4439-8636-07577b7194fa', 1, null, '1½ lb Brussels sprouts, trimmed and halved; quartered if large', 'Brussels sprouts', 1.5, 'lb', 'trimmed and halved; quartered if large', false),
  ('a6385f83-3ef9-4439-8636-07577b7194fa', 2, null, '3 tbsp olive oil', 'olive oil', 3, 'tbsp', null, false),
  ('a6385f83-3ef9-4439-8636-07577b7194fa', 3, null, '¾ tsp kosher salt', 'kosher salt', 0.75, 'tsp', null, false),
  ('a6385f83-3ef9-4439-8636-07577b7194fa', 4, null, '¼ tsp black pepper', 'black pepper', 0.25, 'tsp', null, false),
  ('a6385f83-3ef9-4439-8636-07577b7194fa', 5, null, '3 tbsp balsamic vinegar', 'balsamic vinegar', 3, 'tbsp', null, false),
  ('a6385f83-3ef9-4439-8636-07577b7194fa', 6, null, '1 tbsp honey, or maple syrup', 'honey', 1, 'tbsp', 'or maple syrup', false),
  ('a6385f83-3ef9-4439-8636-07577b7194fa', 7, null, '1 pinch red pepper flakes', 'red pepper flakes', 1, 'pinch', null, true),
  ('a6385f83-3ef9-4439-8636-07577b7194fa', 8, null, '¼ cup Parmesan cheese, finely grated', 'Parmesan cheese', 0.25, 'cup', 'finely grated', true);
