insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('a6385f83-3ef9-4439-8636-07577b7194fa', 1, null, 'Put a large rimmed sheet pan on the lowest oven rack and heat the oven to 425°F.', null, 218.3, null),
  ('a6385f83-3ef9-4439-8636-07577b7194fa', 2, null, 'In a bowl, toss the Brussels sprouts with the oil, salt and pepper.', null, null, null),
  ('a6385f83-3ef9-4439-8636-07577b7194fa', 3, null, 'Carefully pull out the hot pan and spread the sprouts on it, cut sides down — they should sizzle. Roast without stirring until the undersides are deep brown, about 15 minutes, then toss and roast until tender, 5–10 minutes more.', 1320, 218.3, null),
  ('a6385f83-3ef9-4439-8636-07577b7194fa', 4, null, 'Meanwhile, simmer the balsamic vinegar and honey in a small saucepan until syrupy and reduced by about a third, 2–3 minutes.', 180, null, null),
  ('a6385f83-3ef9-4439-8636-07577b7194fa', 5, null, 'Toss the hot sprouts with the glaze and red pepper flakes, sprinkle with Parmesan if using, and serve.', null, null, null);

