values ('72866b9e-d5ab-4b64-8808-24ee0e5c599b', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'green-beans-almondine', 'green-beans-almondine-72866b', 'Green Beans Almondine', 'Bright, crisp-tender green beans tossed in nutty browned butter with toasted sliced almonds, shallot and lemon — the French bistro side that''s ready in 20 minutes.', 'french', 1, 10, 12, 22, 4, 'side', null, 0, array['stove']::text[], array['weeknight', 'quick', 'entertaining', 'make-ahead']::text[], array['Make ahead: blanch and chill the beans up to 1 day ahead, keep them dry in the fridge, and do the browned-butter finish just before serving.']::text[], 'https://images.unsplash.com/photo-1677449477669-03421e56a53d', 'White bowl of green beans topped with nuts', 'Jason Leung', 'https://unsplash.com/@ninjason', 'https://unsplash.com/photos/a-white-bowl-filled-with-green-beans-and-nuts-kxCUbqB1W8Y', 'unsplash', true, 'public', false,
  'pending_review', array['side', 'holiday', 'entertaining']::text[], array['boil']::text[], array['tangy', 'fresh']::text[], array['thanksgiving', 'christmas']::text[], null, 'traditional', 'green-beans-almondine', 'classic', 'Refrigerate up to 3 days; reheat in a skillet.', null, 'owned', array['milk', 'tree_nut']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['green bean', 'almond', 'shallot', 'lemon juice', 'lemon zest', 'parsley']::text[], 'almond|green bean|lemon juice|lemon zest|parsley|shallot',
  null, null, null, null, null, null, null, null)
