  ('72866b9e-d5ab-4b64-8808-24ee0e5c599b', 1, null, '1 lb green beans, or haricots verts, trimmed', 'green beans', 1, 'lb', 'or haricots verts, trimmed', false),
  ('72866b9e-d5ab-4b64-8808-24ee0e5c599b', 2, null, '1 tbsp kosher salt, for the cooking water', 'kosher salt', 1, 'tbsp', 'for the cooking water', false),
  ('72866b9e-d5ab-4b64-8808-24ee0e5c599b', 3, null, '3 tbsp unsalted butter', 'unsalted butter', 3, 'tbsp', null, false),
  ('72866b9e-d5ab-4b64-8808-24ee0e5c599b', 4, null, '⅓ cup sliced almonds', 'sliced almonds', 0.33, 'cup', null, false),
  ('72866b9e-d5ab-4b64-8808-24ee0e5c599b', 5, null, '1 shallot, finely chopped', 'shallot', 1, null, 'finely chopped', false),
