insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('72866b9e-d5ab-4b64-8808-24ee0e5c599b', 1, null, 'Bring a large pot of water to a boil with the tablespoon of salt and set a bowl of ice water nearby. Boil the beans until bright green and crisp-tender, 3–5 minutes (2–3 for thin haricots verts).', 240, null, null),
  ('72866b9e-d5ab-4b64-8808-24ee0e5c599b', 2, null, 'Drain and plunge the beans into the ice water to stop the cooking, then drain again and pat dry.', 120, null, null),
  ('72866b9e-d5ab-4b64-8808-24ee0e5c599b', 3, null, 'Melt the butter in a large skillet over medium heat. Add the almonds and stir constantly until golden and the butter smells nutty and turns light brown, 2–3 minutes. Watch closely — almonds go from golden to burnt fast.', 180, null, null),
  ('72866b9e-d5ab-4b64-8808-24ee0e5c599b', 4, null, 'Add the shallot and cook 1 minute, then add the beans and the ¼ teaspoon salt and toss until hot and glossy, 2–3 minutes.', 180, null, null),
  ('72866b9e-d5ab-4b64-8808-24ee0e5c599b', 5, null, 'Off the heat, toss with the lemon juice, zest, pepper and parsley and serve.', null, null, null);

