insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 1, 'Filling', '3½ lb sweet potatoes, about 5 medium, peeled and cut into 1-inch chunks', 'sweet potatoes', 3.5, 'lb', 'about 5 medium, peeled and cut into 1-inch chunks', false),
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 2, 'Filling', '⅓ cup packed light brown sugar', 'packed light brown sugar', 0.33, 'cup', null, false),
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 3, 'Filling', '4 tbsp unsalted butter, melted, plus more for the dish', 'unsalted butter', 4, 'tbsp', 'melted, plus more for the dish', false),
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 4, 'Filling', '½ cup whole milk', 'whole milk', 0.5, 'cup', null, false),
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 5, 'Filling', '2 large eggs, beaten', 'large eggs', 2, null, 'beaten', false),
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 6, 'Filling', '1 tsp vanilla extract', 'vanilla extract', 1, 'tsp', null, false),
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 7, 'Filling', '½ tsp ground cinnamon', 'ground cinnamon', 0.5, 'tsp', null, false),
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 8, 'Filling', '¼ tsp ground nutmeg', 'ground nutmeg', 0.25, 'tsp', null, false),
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 9, 'Filling', '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 10, 'Topping', '¾ cup packed light brown sugar', 'packed light brown sugar', 0.75, 'cup', null, false),
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 11, 'Topping', '⅓ cup all-purpose flour', 'all-purpose flour', 0.33, 'cup', null, false),
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 12, 'Topping', '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 13, 'Topping', '4 tbsp unsalted butter, melted', 'unsalted butter', 4, 'tbsp', 'melted', false),
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 14, 'Topping', '1 cup pecans, chopped', 'pecans', 1, 'cup', 'chopped', false),
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 15, 'Topping', '1 cup mini marshmallows', 'mini marshmallows', 1, 'cup', null, true);
delete from public.recipe_instructions where recipe_id = '2c5dfabd-f782-4ab5-b993-2d642ae2bd10';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 1, 'Filling', 'Heat the oven to 350°F and butter a 9-by-13-inch baking dish. Cover the sweet potatoes with cold salted water in a large pot, bring to a boil and simmer until very tender, 15–20 minutes.', 1080, 176.7, null),
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 2, 'Filling', 'Drain well and return the potatoes to the hot pot for 2 minutes to steam off excess water. Mash until smooth with a potato masher or hand mixer.', 180, null, null),
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 3, 'Filling', 'Beat in the brown sugar, butter, milk, eggs, vanilla, cinnamon, nutmeg and salt until fluffy. Spread evenly in the dish.', null, null, null),
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 4, 'Topping', 'Stir the brown sugar, flour and salt together, then stir in the melted butter until clumpy. Mix in the pecans and scatter evenly over the sweet potatoes.', null, null, null),
  ('2c5dfabd-f782-4ab5-b993-2d642ae2bd10', 5, null, 'Bake until the topping is browned and the filling is puffed and set with the center reading 160°F, 30–35 minutes. If using marshmallows, tuck them into the gaps in the topping for the last 10 minutes. Rest 10 minutes before serving.', 1980, 176.7, 71.1);

-- Rice Pilaf
