values ('8ff6bd7e-8353-4d7b-bea2-e5d6e6df0d16', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'rice-pilaf', 'rice-pilaf-8ff6bd', 'Rice Pilaf', 'Long-grain rice and orzo toasted in butter until golden and nutty, then steamed in seasoned broth with onion and herbs until every grain is separate and fluffy.', 'american', 1, 10, 35, 45, 6, 'side', null, 0, array['stove']::text[], array['weeknight', 'budget', 'kid-friendly']::text[], array['Use vegetable broth for a meatless side. If you use bouillon cubes or paste instead of boxed broth, read the label — some contain wheat or milk.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['side', 'budget', 'comfort']::text[], array['boil']::text[], array['fresh']::text[], '{}'::text[], null, null, 'rice-pilaf', 'classic', 'Cool and refrigerate within 2 hours; keeps up to 4 days. Reheat with a splash of water, covered, until steaming.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], '{}'::text[], '{}'::text[], array['orzo pasta', 'yellow onion', 'garlic', 'white rice', 'chicken broth', 'bay leaf', 'dried thyme', 'parsley']::text[], 'bay leaf|chicken broth|dried thyme|garlic|orzo pasta|parsley|white rice|yellow onion',
  null, null, null, null, null, null, null, null)
