  ('8ff6bd7e-8353-4d7b-bea2-e5d6e6df0d16', 1, null, '2 tbsp unsalted butter', 'unsalted butter', 2, 'tbsp', null, false),
  ('8ff6bd7e-8353-4d7b-bea2-e5d6e6df0d16', 2, null, '1 tbsp olive oil', 'olive oil', 1, 'tbsp', null, false),
