  ('8ff6bd7e-8353-4d7b-bea2-e5d6e6df0d16', 4, null, '1 small yellow onion, finely chopped', 'small yellow onion', 1, null, 'finely chopped', false),
  ('8ff6bd7e-8353-4d7b-bea2-e5d6e6df0d16', 5, null, '1 stalk celery, finely chopped', 'celery', 1, 'stalk', 'finely chopped', true),
  ('8ff6bd7e-8353-4d7b-bea2-e5d6e6df0d16', 6, null, '1 clove garlic, minced', 'garlic', 1, 'clove', 'minced', false),
