  ('8ff6bd7e-8353-4d7b-bea2-e5d6e6df0d16', 8, null, '3 cups low-sodium chicken broth, hot', 'low-sodium chicken broth', 3, 'cup', 'hot', false),
  ('8ff6bd7e-8353-4d7b-bea2-e5d6e6df0d16', 9, null, '½ tsp kosher salt, less if your broth is salty', 'kosher salt', 0.5, 'tsp', 'less if your broth is salty', false),
