delete from public.recipe_instructions where recipe_id = '8ff6bd7e-8353-4d7b-bea2-e5d6e6df0d16';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('8ff6bd7e-8353-4d7b-bea2-e5d6e6df0d16', 1, null, 'Melt the butter with the oil in a medium saucepan that has a tight-fitting lid, over medium heat. Add the orzo and stir constantly until deep golden brown, 3–4 minutes.', 240, null, null),
  ('8ff6bd7e-8353-4d7b-bea2-e5d6e6df0d16', 2, null, 'Add the onion and celery and cook until soft, about 4 minutes. Stir in the garlic for 30 seconds.', 240, null, null),
  ('8ff6bd7e-8353-4d7b-bea2-e5d6e6df0d16', 3, null, 'Add the rice and stir until the grains are coated and the edges look translucent, about 2 minutes.', 120, null, null),
  ('8ff6bd7e-8353-4d7b-bea2-e5d6e6df0d16', 4, null, 'Pour in the hot broth and add the salt, bay leaf and thyme. Bring to a boil, cover tightly, turn the heat to the lowest setting and cook 18 minutes without lifting the lid.', 1080, null, null),
  ('8ff6bd7e-8353-4d7b-bea2-e5d6e6df0d16', 5, null, 'Take off the heat and let stand, still covered, for 10 minutes. Remove the bay leaf, fluff with a fork and fold in the parsley.', 600, null, null);

-- Southern Cornbread
