values ('73ba563f-3f37-4ec4-81d6-483d67e61799', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'southern-cornbread', 'southern-cornbread-73ba56', 'Southern Cornbread', 'Savory, crunchy-edged buttermilk cornbread made with all cornmeal and little fuss, baked in a sizzling-hot cast-iron skillet the way Southern cooks do.', 'southern', 1, 15, 25, 40, 8, 'side', null, 0, array['oven', 'cast_iron']::text[], array['budget', 'comfort']::text[], array['Southern-style cornbread is savory, with little or no sugar; stir 2 tablespoons of sugar into the dry ingredients if you like it a touch sweet.', 'Some cornmeal is milled in plants that also handle wheat — check the label if that matters to anyone at the table.']::text[], 'https://images.unsplash.com/photo-1664339031047-970bf639e43f', 'Slice of cornbread with butter on a plate', 'Holly Spangler', 'https://unsplash.com/@h_spangler', 'https://unsplash.com/photos/a-plate-of-food-LmULfNDZ6YQ', 'unsplash', true, 'public', false,
  'pending_review', array['baking', 'side', 'budget', 'comfort']::text[], array['bake']::text[], array['tangy']::text[], '{}'::text[], null, 'traditional', 'southern-cornbread', 'classic', 'Wrap and keep at room temperature up to 2 days, or freeze up to 3 months. Warm in a 350°F oven.', null, 'owned', array['egg', 'milk']::text[], array['pork']::text[], array['gluten_free']::text[], array['bacon dripping', 'white cornmeal', 'baking powder', 'baking soda', 'buttermilk', 'egg']::text[], 'bacon dripping|baking powder|baking soda|buttermilk|egg|white cornmeal',
  null, null, null, null, null, null, null, null)
