delete from public.recipe_ingredients where recipe_id = '73ba563f-3f37-4ec4-81d6-483d67e61799';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('73ba563f-3f37-4ec4-81d6-483d67e61799', 1, null, '4 tbsp bacon drippings, or unsalted butter or vegetable shortening', 'bacon drippings', 4, 'tbsp', 'or unsalted butter or vegetable shortening', false),
  ('73ba563f-3f37-4ec4-81d6-483d67e61799', 2, null, '2 cups stone-ground yellow or white cornmeal, not self-rising', 'stone-ground yellow or white cornmeal', 2, 'cup', 'not self-rising', false),
  ('73ba563f-3f37-4ec4-81d6-483d67e61799', 3, null, '1 tsp baking powder', 'baking powder', 1, 'tsp', null, false),
  ('73ba563f-3f37-4ec4-81d6-483d67e61799', 4, null, '½ tsp baking soda', 'baking soda', 0.5, 'tsp', null, false),
  ('73ba563f-3f37-4ec4-81d6-483d67e61799', 5, null, '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('73ba563f-3f37-4ec4-81d6-483d67e61799', 6, null, '2 cups buttermilk', 'buttermilk', 2, 'cup', null, false),
  ('73ba563f-3f37-4ec4-81d6-483d67e61799', 7, null, '2 large eggs', 'large eggs', 2, null, null, false),
  ('73ba563f-3f37-4ec4-81d6-483d67e61799', 8, null, '2 tbsp unsalted butter, softened, to serve', 'unsalted butter', 2, 'tbsp', 'softened, to serve', true);
delete from public.recipe_instructions where recipe_id = '73ba563f-3f37-4ec4-81d6-483d67e61799';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('73ba563f-3f37-4ec4-81d6-483d67e61799', 1, null, 'Put the bacon drippings in a 10-inch cast-iron skillet and set it in the oven. Heat the oven to 450°F with the skillet inside for at least 10 minutes, until the fat is shimmering.', 720, 232.2, null),
  ('73ba563f-3f37-4ec4-81d6-483d67e61799', 2, null, 'Meanwhile, whisk the cornmeal, baking powder, baking soda and salt in a large bowl. In another bowl, whisk the buttermilk and eggs.', null, null, null),
  ('73ba563f-3f37-4ec4-81d6-483d67e61799', 3, null, 'Pour the wet ingredients into the dry and stir just until combined — a few lumps are fine. Using oven mitts, take out the hot skillet, swirl the fat up the sides, then pour most of it into the batter and stir quickly to mix.', null, null, null),
  ('73ba563f-3f37-4ec4-81d6-483d67e61799', 4, null, 'Pour the batter into the skillet — it should sizzle. Bake until golden brown with crisp edges and a toothpick in the center comes out clean, 20–25 minutes.', 1320, 232.2, null),
  ('73ba563f-3f37-4ec4-81d6-483d67e61799', 5, null, 'Cool in the pan 5 minutes, then turn out or cut into wedges right in the skillet. Serve warm with butter.', 300, null, null);

