values ('1aa15244-c731-480c-9231-23c5494d7a69', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'classic-french-toast', 'classic-french-toast-1aa152', 'Classic French Toast', 'Thick slices of day-old bread soaked in a vanilla-cinnamon custard and griddled in butter until crisp outside and custardy but fully set inside.', 'american', 1, 10, 16, 26, 4, 'breakfast', null, 0, array['stove']::text[], array['weeknight', 'kid-friendly', 'budget', 'comfort']::text[], array['Fresh, soft sandwich bread turns soggy — use bread that''s a day or two old, or dry fresh slices in a 300°F oven for 8 minutes first.', 'If the outside browns before the middle sets, turn the heat down a notch; patience gives a better result than high heat.']::text[], 'https://images.unsplash.com/photo-1788462613181-3d3c2b62e710', 'French toast topped with sliced bananas on a black plate', 'gabbiistudios', 'https://unsplash.com/@gabrielonodegba', 'https://unsplash.com/photos/french-toast-with-bananas-breakfast-yUQmFofH-Aw', 'unsplash', true, 'public', false,
  'pending_review', array['breakfast', 'quick', 'budget', 'holiday', 'comfort']::text[], '{}'::text[], array['aromatic']::text[], array['brunch-party', 'mothers-day']::text[], null, null, 'french-toast', 'classic', 'Refrigerate leftovers up to 2 days, or freeze in a single layer then bag up to 2 months. Reheat in the toaster or a 350°F oven.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['egg', 'milk', 'vanilla extract', 'ground cinnamon', 'brioche bread', 'maple syrup']::text[], 'brioche bread|egg|ground cinnamon|maple syrup|milk|vanilla extract',
  null, null, null, null, null, null, null, null)
