  ('1aa15244-c731-480c-9231-23c5494d7a69', 1, null, '4 large eggs', 'large eggs', 4, null, null, false),
  ('1aa15244-c731-480c-9231-23c5494d7a69', 2, null, '1 cup whole milk', 'whole milk', 1, 'cup', null, false),
  ('1aa15244-c731-480c-9231-23c5494d7a69', 3, null, '2 tbsp sugar', 'sugar', 2, 'tbsp', null, false),
  ('1aa15244-c731-480c-9231-23c5494d7a69', 4, null, '1 tsp vanilla extract', 'vanilla extract', 1, 'tsp', null, false),
  ('1aa15244-c731-480c-9231-23c5494d7a69', 5, null, '½ tsp ground cinnamon', 'ground cinnamon', 0.5, 'tsp', null, false),
  ('1aa15244-c731-480c-9231-23c5494d7a69', 6, null, '1 pinch kosher salt', 'kosher salt', 1, 'pinch', null, false),
  ('1aa15244-c731-480c-9231-23c5494d7a69', 7, null, '8 slice challah or brioche bread, about ¾ inch thick, a day or two old', 'challah or brioche bread', 8, 'slice', 'about ¾ inch thick, a day or two old', false),
  ('1aa15244-c731-480c-9231-23c5494d7a69', 8, null, '3 tbsp unsalted butter, divided', 'unsalted butter', 3, 'tbsp', 'divided', false),
  ('1aa15244-c731-480c-9231-23c5494d7a69', 9, null, '½ cup maple syrup, warmed, to serve', 'maple syrup', 0.5, 'cup', 'warmed, to serve', false),
