delete from public.recipe_instructions where recipe_id = '1aa15244-c731-480c-9231-23c5494d7a69';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('1aa15244-c731-480c-9231-23c5494d7a69', 1, null, 'Whisk the eggs, milk, sugar, vanilla, cinnamon and salt in a shallow dish (a pie plate is ideal) until completely smooth with no streaks of egg white.', 120, null, null),
  ('1aa15244-c731-480c-9231-23c5494d7a69', 2, null, 'Heat the oven to 200°F to keep the first batch warm. Set a large nonstick or cast-iron skillet over medium heat and melt 1 tablespoon of the butter until it foams.', 120, 93.3, null),
  ('1aa15244-c731-480c-9231-23c5494d7a69', 3, null, 'Lay 2–3 slices of bread in the custard and soak 15–20 seconds per side, so they''re soaked through but not falling apart. Lift, let the excess drip off and lay them in the pan.', null, null, null),
  ('1aa15244-c731-480c-9231-23c5494d7a69', 4, null, 'Cook until deep golden underneath, 3–4 minutes, then flip and cook the second side 3 minutes more. The center should spring back when pressed and show no wet custard when you cut into a slice (160°F). Keep warm in the oven while you cook the rest, adding butter to the pan for each batch.', 720, null, 71.1),
  ('1aa15244-c731-480c-9231-23c5494d7a69', 5, null, 'Serve hot with warm maple syrup and berries.', 60, null, null);

-- Belgian Waffles
