values ('f09f1f73-59fc-42fe-848a-54f9bae4f739', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'belgian-waffles', 'belgian-waffles-f09f1f', 'Belgian Waffles', 'Tall, crisp-shelled waffles with a light, airy middle, made with whipped egg whites in an American-style Belgian (deep-pocket) waffle iron.', 'american', 2, 15, 25, 40, 4, 'breakfast', null, 0, '{}'::text[], array['kid-friendly', 'weekend', 'freezer-friendly']::text[], array['You''ll need a Belgian (deep-pocket) waffle iron; a standard thin iron works too but makes more, thinner waffles.', 'Stacking hot waffles on a plate makes them steam and go limp — keep them in a single layer on a rack.']::text[], 'https://images.unsplash.com/photo-1513456753721-b3f94be66822', 'Belgian waffle with cream and berries on a plate', 'Natasha Bhogal', 'https://unsplash.com/@natashabhogal', 'https://unsplash.com/photos/selective-focus-photography-of-belgian-waffle-on-plate-jZC0CPr7Xtw', 'unsplash', true, 'public', false,
  'pending_review', array['breakfast', 'holiday', 'comfort']::text[], array['steam']::text[], '{}'::text[], array['brunch-party']::text[], null, null, 'belgian-waffles', 'classic', 'Cool leftovers on a rack, then freeze in a bag up to 2 months. Reheat straight from frozen in the toaster.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['baking powder', 'egg', 'milk', 'vanilla extract', 'maple syrup']::text[], 'baking powder|egg|maple syrup|milk|vanilla extract',
  null, null, null, null, null, null, null, null)
