insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('f09f1f73-59fc-42fe-848a-54f9bae4f739', 1, null, 'Heat a Belgian waffle iron to medium-high, and heat the oven to 200°F with a wire rack set on a baking sheet inside to keep waffles crisp.', 300, 93.3, null),
  ('f09f1f73-59fc-42fe-848a-54f9bae4f739', 2, null, 'Whisk the flour, sugar, baking powder and salt in a large bowl. In a second bowl, whisk the egg yolks, milk, melted butter and vanilla.', null, null, null),
  ('f09f1f73-59fc-42fe-848a-54f9bae4f739', 3, null, 'In a clean bowl, beat the egg whites with a whisk or hand mixer until they hold soft, droopy peaks, 2–3 minutes.', 180, null, null),
  ('f09f1f73-59fc-42fe-848a-54f9bae4f739', 4, null, 'Pour the milk mixture into the flour and stir gently until just combined — a few lumps are fine. Fold in the egg whites in two additions until no large white streaks remain.', 120, null, null),
  ('f09f1f73-59fc-42fe-848a-54f9bae4f739', 5, null, 'Brush the iron lightly with oil. Pour in enough batter to just cover the grid (usually about ¾ cup), close and cook until deep golden and the steam slows to a wisp, 4–5 minutes. Don''t open the lid early or the waffle will tear.', 300, null, null),
  ('f09f1f73-59fc-42fe-848a-54f9bae4f739', 6, null, 'Move each waffle to the rack in the oven while you cook the rest, then serve with maple syrup, berries or whipped cream.', 900, null, null);

-- Eggs Benedict
