values ('9e470439-6292-4726-871b-0e6aed579b19', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'eggs-benedict', 'eggs-benedict-9e4704', 'Eggs Benedict', 'Toasted English muffins topped with seared Canadian bacon, softly poached eggs and a lemony hollandaise whisked gently over simmering water.', 'american', 3, 10, 25, 35, 4, 'breakfast', null, 0, array['stove']::text[], array['entertaining', 'weekend']::text[], array['If the hollandaise splits, whisk a tablespoon of hot water into a clean bowl and slowly whisk the broken sauce back into it.', 'Poaching for a crowd: poach the eggs ahead, chill them in ice water, then rewarm in hot (not simmering) water for 1 minute before serving.']::text[], 'https://images.unsplash.com/photo-1674315604997-bc5fcaa1ac32', 'Eggs Benedict with asparagus on a plate', 'Eiliv Aceron', 'https://unsplash.com/@shootdelicious', 'https://unsplash.com/photos/a-plate-of-food-with-asparagus-and-eggs-tGpBPnc3ZoA', 'unsplash', true, 'public', false,
  'pending_review', array['breakfast', 'entertaining', 'holiday']::text[], array['stew', 'pan_fry', 'poach', 'boil']::text[], array['spicy', 'tangy', 'fresh']::text[], array['brunch-party', 'mothers-day', 'fathers-day']::text[], 'New York', 'traditional', 'eggs-benedict', 'classic', 'Best served right away. Hollandaise doesn''t reheat well; make it fresh. Poached eggs keep in cold water in the fridge up to 1 day.', 'The poached eggs keep runny yolks, so they don''t reach 160°F. Use pasteurized eggs for anyone pregnant, very young, older, or with a weakened immune system, or poach 5–6 minutes until the yolks are firm.', 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], array['pork']::text[], '{}'::text[], array['egg yolk', 'lemon juice', 'white vinegar', 'egg', 'english muffin', 'canadian bacon']::text[], 'canadian bacon|egg|egg yolk|english muffin|lemon juice|white vinegar',
  null, null, null, null, null, null, null, null)
