insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('9e470439-6292-4726-871b-0e6aed579b19', 1, 'Hollandaise', '3 large egg yolks', 'large egg yolks', 3, null, null, false),
  ('9e470439-6292-4726-871b-0e6aed579b19', 2, 'Hollandaise', '1 tbsp fresh lemon juice', 'fresh lemon juice', 1, 'tbsp', null, false),
  ('9e470439-6292-4726-871b-0e6aed579b19', 3, 'Hollandaise', '1 tbsp water', 'water', 1, 'tbsp', null, false),
  ('9e470439-6292-4726-871b-0e6aed579b19', 4, 'Hollandaise', '10 tbsp unsalted butter, melted and kept warm', 'unsalted butter', 10, 'tbsp', 'melted and kept warm', false),
  ('9e470439-6292-4726-871b-0e6aed579b19', 5, 'Hollandaise', '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('9e470439-6292-4726-871b-0e6aed579b19', 6, 'Hollandaise', '1 pinch cayenne pepper', 'cayenne pepper', 1, 'pinch', null, true),
  ('9e470439-6292-4726-871b-0e6aed579b19', 7, 'Eggs and assembly', '1 tbsp distilled white vinegar', 'distilled white vinegar', 1, 'tbsp', null, false),
  ('9e470439-6292-4726-871b-0e6aed579b19', 8, 'Eggs and assembly', '8 large eggs, very fresh', 'large eggs', 8, null, 'very fresh', false),
  ('9e470439-6292-4726-871b-0e6aed579b19', 9, 'Eggs and assembly', '4 English muffins, split, or 8 thick slices of sourdough bread', 'English muffins', 4, null, 'split, or 8 thick slices of sourdough bread', false),
  ('9e470439-6292-4726-871b-0e6aed579b19', 10, 'Eggs and assembly', '8 slice Canadian bacon', 'Canadian bacon', 8, 'slice', null, false),
  ('9e470439-6292-4726-871b-0e6aed579b19', 11, 'Eggs and assembly', '1 tbsp unsalted butter, for the muffins', 'unsalted butter', 1, 'tbsp', 'for the muffins', false),
  ('9e470439-6292-4726-871b-0e6aed579b19', 12, 'Eggs and assembly', '1 tbsp fresh chives, finely chopped', 'fresh chives', 1, 'tbsp', 'finely chopped', true);
delete from public.recipe_instructions where recipe_id = '9e470439-6292-4726-871b-0e6aed579b19';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('9e470439-6292-4726-871b-0e6aed579b19', 1, 'Hollandaise', 'Bring 1 inch of water to a bare simmer in a saucepan. In a heatproof bowl that sits above (not in) the water, whisk the yolks, lemon juice and 1 tablespoon water. Whisk constantly over the pan until the yolks thicken, turn pale and leave a trail, and reach 160°F, 2–4 minutes. Lift the bowl off whenever the edges start to look grainy.', 240, null, 71.1),
  ('9e470439-6292-4726-871b-0e6aed579b19', 2, 'Hollandaise', 'Off the heat, whisk in the warm melted butter a thin stream at a time until thick and glossy. Season with the salt and cayenne. Set the bowl over the warm (heat off) pan to hold while you cook the eggs.', 180, null, null),
  ('9e470439-6292-4726-871b-0e6aed579b19', 3, 'Eggs and assembly', 'Fill a wide saucepan with 3 inches of water, add the vinegar and bring to a gentle simmer — small bubbles, not a rolling boil. Toast the English muffins and butter them. Brown the Canadian bacon in a dry skillet over medium-high heat, about 1 minute per side.', 360, null, null),
  ('9e470439-6292-4726-871b-0e6aed579b19', 4, 'Eggs and assembly', 'Crack each egg into a small cup. Stir the water to make a gentle swirl and slide in 4 eggs, one at a time. Poach until the whites are fully set and opaque but the yolks still wobble, 3–4 minutes. Lift out with a slotted spoon and blot on a paper towel. Repeat with the remaining eggs.', 480, null, null),
  ('9e470439-6292-4726-871b-0e6aed579b19', 5, null, 'Top each muffin half with Canadian bacon and a poached egg, spoon over the hollandaise and scatter with chives. Serve right away.', 120, null, null);

-- French Omelette
