values ('26486e8f-a6c3-417f-8740-6305eafac6a4', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'french-omelette', 'french-omelette-26486e', 'French Omelette', 'A smooth, pale-gold rolled omelette with a soft, creamy center — the classic two-minute French technique of stirring the eggs into tiny curds.', 'french', 2, 3, 6, 9, 2, 'breakfast', null, 0, array['stove']::text[], array['quick', 'weeknight', 'budget']::text[], array['Too much heat is the most common problem: the outside should stay pale yellow, with no brown spots.', 'Prefer it fully set? Cook 30 seconds longer before rolling, until no wet egg remains.']::text[], 'https://images.unsplash.com/photo-1786213591036-96b02dbff18e', 'Folded omelette with toast and a small cup of jam on a blue plate', 'DL314 Lin', 'https://unsplash.com/@dickenslin76', 'https://unsplash.com/photos/breakfast-omelet-with-toast-and-jam-vq8iQKYfggs', 'unsplash', true, 'public', false,
  'pending_review', array['breakfast', 'quick', 'budget']::text[], '{}'::text[], array['fresh']::text[], '{}'::text[], null, 'traditional', 'french-omelette', 'classic', 'Best eaten right away; omelettes don''t keep well.', 'The eggs here aren''t cooked to 160°F. Use pasteurized eggs if you''re serving anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['egg', 'milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['egg', 'chive']::text[], 'chive|egg',
  null, null, null, null, null, null, null, null)
