insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('26486e8f-a6c3-417f-8740-6305eafac6a4', 1, null, 'Crack 3 eggs into a bowl, add half the salt and beat with a fork until completely uniform with no streaks of white, about 30 seconds.', 60, null, null),
  ('26486e8f-a6c3-417f-8740-6305eafac6a4', 2, null, 'Melt 1 tablespoon of butter in an 8-inch nonstick skillet over medium-low heat until it foams but doesn''t brown. Pour in the eggs.', 60, null, null),
  ('26486e8f-a6c3-417f-8740-6305eafac6a4', 3, null, 'Immediately stir with a silicone spatula while shaking the pan back and forth, so the eggs form very small, soft curds. Keep going until they look like a loose, creamy scramble but are still a little wet on top, 45–60 seconds.', 60, null, null),
  ('26486e8f-a6c3-417f-8740-6305eafac6a4', 4, null, 'Stop stirring, smooth the eggs into an even layer and let the base set for 15 seconds. Sprinkle over half the chives (and cheese, if using).', null, null, null),
  ('26486e8f-a6c3-417f-8740-6305eafac6a4', 5, null, 'Tilt the pan away from you and use the spatula to roll the omelette over itself toward the far edge, then tip it seam-side down onto a warm plate. Rub the top with a little butter for shine and season with pepper. Repeat for the second omelette.', 120, null, null);

-- Huevos Rancheros
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
