values ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'huevos-rancheros', 'huevos-rancheros-8d9526', 'Huevos Rancheros', 'Lightly fried corn tortillas topped with refried beans, fried eggs and a warm, chunky tomato–serrano ranchero sauce, finished with queso fresco and cilantro.', 'mexican', 2, 10, 25, 35, 4, 'breakfast', null, 0, array['stove', 'blender']::text[], array['budget', 'weekend', 'spicy']::text[], array['Short on time? Use 1½ cups of a good jarred salsa roja, simmered 5 minutes, in place of the homemade sauce.', 'Canned refried beans are sometimes made with lard — look for vegetarian refried beans if that matters.']::text[], 'https://images.pexels.com/photos/31823016/pexels-photo-31823016.jpeg', 'Huevos rancheros with avocado and cheese on a plate', 'Allan González', 'https://www.pexels.com/@allanglezg/', 'https://www.pexels.com/photo/delicious-mexican-huevos-rancheros-on-a-plate-31823016/', 'pexels', true, 'public', false,
  'pending_review', array['breakfast', 'budget', 'holiday']::text[], array['stew']::text[], array['spicy', 'fresh']::text[], array['brunch-party']::text[], null, 'traditional', 'huevos-rancheros', 'classic', 'The ranchero sauce keeps 5 days in the fridge or 3 months frozen. Fry the tortillas and eggs fresh.', 'The fried eggs here keep runny yolks, so they don''t reach 160°F. Use pasteurized eggs for anyone pregnant, very young, older, or with a weakened immune system, or cover the pan for the last minute until the yolks are firm.', 'owned', array['egg', 'milk']::text[], array['beans']::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['roma tomato', 'white onion', 'garlic', 'serrano chile', 'pinto bean', 'corn tortilla', 'egg', 'queso fresco', 'cilantro']::text[], 'cilantro|corn tortilla|egg|garlic|pinto bean|queso fresco|roma tomato|serrano chile|white onion',
  null, null, null, null, null, null, null, null)
