  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 1, 'Ranchero sauce', '4 Roma tomatoes, about 1 lb, cored and quartered', 'Roma tomatoes', 4, null, 'about 1 lb, cored and quartered', false),
  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 2, 'Ranchero sauce', '¼ white onion, roughly chopped', 'white onion', 0.25, null, 'roughly chopped', false),
  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 3, 'Ranchero sauce', '1 clove garlic', 'garlic', 1, 'clove', null, false),
  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 4, 'Ranchero sauce', '1 serrano chile, stemmed; seeded for less heat', 'serrano chile', 1, null, 'stemmed; seeded for less heat', false),
  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 5, 'Ranchero sauce', '1 tbsp vegetable oil', 'vegetable oil', 1, 'tbsp', null, false),
