  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 7, 'Tostadas and eggs', '1 can refried pinto beans, 16 oz', 'refried pinto beans', 1, 'can', '16 oz', false),
  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 8, 'Tostadas and eggs', '¼ cup vegetable oil, divided', 'vegetable oil', 0.25, 'cup', 'divided', false),
  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 9, 'Tostadas and eggs', '8 corn tortillas, 6-inch', 'corn tortillas', 8, null, '6-inch', false),
  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 10, 'Tostadas and eggs', '8 large eggs', 'large eggs', 8, null, null, false),
  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 11, 'Tostadas and eggs', '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 12, 'To serve', '½ cup queso fresco, crumbled', 'queso fresco', 0.5, 'cup', 'crumbled', false),
  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 13, 'To serve', '¼ cup fresh cilantro, chopped', 'fresh cilantro', 0.25, 'cup', 'chopped', false),
  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 14, 'To serve', '1 ripe avocado, sliced', 'ripe avocado', 1, null, 'sliced', true);
delete from public.recipe_instructions where recipe_id = '8d95265c-3c36-4fe5-8f8b-6f0c41f38f70';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 1, 'Ranchero sauce', 'Blend the tomatoes, onion, garlic and serrano until mostly smooth but still a little chunky, about 15 seconds.', 60, null, null),
  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 2, 'Ranchero sauce', 'Heat the oil in a saucepan over medium-high heat, pour in the purée (it will spatter) and stir in the salt. Simmer, stirring now and then, until it darkens slightly and thickens to a spoonable sauce, 8–10 minutes. Keep warm.', 600, null, null),
  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 3, 'Tostadas and eggs', 'Warm the refried beans in a small pan over low heat with a splash of water, stirring, until hot and spreadable, about 5 minutes.', 300, null, null),
  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 4, 'Tostadas and eggs', 'Heat 2 tablespoons of the oil in a large skillet over medium-high heat. Fry the tortillas one or two at a time until softened and just starting to crisp at the edges, about 20 seconds per side. Drain on paper towels and set two on each plate, overlapping.', 240, null, null),
  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 5, 'Tostadas and eggs', 'Lower the heat to medium, add the remaining oil and crack in 4 eggs. Season with salt and fry until the whites are completely set and the edges are lacy, 3–4 minutes. Repeat with the rest.', 420, null, null),
  ('8d95265c-3c36-4fe5-8f8b-6f0c41f38f70', 6, null, 'Spread beans over the tortillas, top each plate with two eggs and spoon the warm ranchero sauce around them. Finish with queso fresco, cilantro and avocado.', 120, null, null);

-- Breakfast Burritos
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
