values ('7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'breakfast-burritos', 'breakfast-burritos-7cdb9a', 'Breakfast Burritos', 'Big flour tortillas rolled around crispy potatoes, browned breakfast sausage, soft scrambled eggs, melted Monterey Jack and salsa — made by the batch and freezer-friendly.', 'tex_mex', 1, 15, 30, 45, 6, 'breakfast', null, 0, array['stove']::text[], array['make-ahead', 'freezer-friendly', 'kid-friendly', 'meal-prep']::text[], array['Some breakfast sausages contain milk, soy or wheat fillers — check the label if anyone has allergies.', 'To freeze, let the filling cool before rolling (skip the salsa inside so they don''t get soggy), wrap each burrito in foil and bag them.']::text[], 'https://images.pexels.com/photos/5848050/pexels-photo-5848050.jpeg', 'Close-up of a breakfast burrito filled with scrambled eggs and sauce', 'Polina Tankilevitch', 'https://www.pexels.com/@polina-tankilevitch/', 'https://www.pexels.com/photo/close-up-shot-of-a-burrito-5848050/', 'pexels', true, 'public', false,
  'pending_review', array['breakfast', 'comfort']::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, 'breakfast-burrito', 'classic', 'Refrigerate wrapped burritos up to 4 days, or freeze up to 3 months. Reheat from frozen: unwrap, wrap in a damp paper towel and microwave 2–3 minutes, turning halfway, until steaming in the center.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], array['pork']::text[], '{}'::text[], array['russet potato', 'breakfast sausage', 'egg', 'milk', 'jack cheese', 'flour tortilla', 'tomato salsa']::text[], 'breakfast sausage|egg|flour tortilla|jack cheese|milk|russet potato|tomato salsa',
  null, null, null, null, null, null, null, null)
