insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a', 1, null, '1 lb russet potatoes, peeled and cut into ½-inch dice', 'russet potatoes', 1, 'lb', 'peeled and cut into ½-inch dice', false),
  ('7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a', 2, null, '2 tbsp vegetable oil', 'vegetable oil', 2, 'tbsp', null, false),
  ('7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a', 3, null, '1 tsp kosher salt, divided', 'kosher salt', 1, 'tsp', 'divided', false),
  ('7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a', 4, null, '12 oz bulk pork breakfast sausage', 'bulk pork breakfast sausage', 12, 'oz', null, false),
  ('7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a', 5, null, '10 large eggs', 'large eggs', 10, null, null, false),
  ('7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a', 6, null, '¼ cup whole milk', 'whole milk', 0.25, 'cup', null, false),
  ('7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a', 7, null, '¼ tsp black pepper', 'black pepper', 0.25, 'tsp', null, false),
  ('7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a', 8, null, '1½ cups Monterey Jack cheese, shredded', 'Monterey Jack cheese', 1.5, 'cup', 'shredded', false),
  ('7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a', 9, null, '6 large flour tortillas, 10-inch', 'large flour tortillas', 6, null, '10-inch', false),
  ('7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a', 10, null, '¾ cup tomato salsa, plus more to serve', 'tomato salsa', 0.75, 'cup', 'plus more to serve', false),
  ('7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a', 11, null, '1 tbsp hot sauce, to serve', 'hot sauce', 1, 'tbsp', 'to serve', true);
delete from public.recipe_instructions where recipe_id = '7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a', 1, null, 'Heat the oil in a large nonstick skillet over medium-high heat. Add the potatoes and half the salt, cover and cook 5 minutes, then uncover and cook, turning every few minutes, until golden and tender all the way through, 10–12 minutes more. Tip into a bowl.', 960, null, null),
  ('7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a', 2, null, 'Add the sausage to the same pan and cook, breaking it into small crumbles, until browned with no pink remaining and 160°F, 6–8 minutes. Spoon it over the potatoes and pour off all but 1 teaspoon of fat.', 420, null, 71.1),
  ('7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a', 3, null, 'Whisk the eggs, milk, remaining salt and pepper. Turn the heat to medium-low, pour the eggs into the pan and stir slowly until they form soft curds with no liquid egg left (160°F), 3–4 minutes.', 240, null, 71.1),
  ('7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a', 4, null, 'Warm the tortillas one at a time in a dry skillet or wrapped in a damp towel in the microwave for 30 seconds, so they''re soft enough to fold without cracking.', 180, null, null),
  ('7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a', 5, null, 'Down the middle of each tortilla, layer potatoes and sausage, eggs, ¼ cup cheese and 2 tablespoons salsa. Fold in the sides, then roll up tightly from the bottom.', null, null, null),
  ('7cdb9a8d-bab9-4f8b-b8a8-d9b23ef72d9a', 6, null, 'For crisp burritos, toast them seam-side down in a dry skillet over medium heat, 1–2 minutes per side, until golden and the cheese melts. Serve with extra salsa and hot sauce.', 180, null, null);

-- Overnight Oats
