values ('a9169af9-a105-484b-9957-de65c271cade', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'overnight-oats', 'overnight-oats-a9169a', 'Overnight Oats', 'Rolled oats soaked overnight in milk and yogurt with chia and maple until thick and creamy — four grab-and-go jars ready before bedtime.', 'american', 1, 10, 0, 490, 4, 'breakfast', null, 480, '{}'::text[], array['make-ahead', 'no-cook', 'budget', 'meal-prep', 'kid-friendly']::text[], array['Use old-fashioned rolled oats: quick oats turn mushy and steel-cut oats stay hard without cooking.', 'Oats are often processed alongside wheat — if gluten matters to anyone eating, check the oat package label.']::text[], 'https://images.pexels.com/photos/2147647/pexels-photo-2147647.jpeg', 'Overnight oats with chia seeds in a glass jar', 'Karine Monteiro', 'https://www.pexels.com/@karine-monteiro-1132429/', 'https://www.pexels.com/photo/clear-glass-jar-2147647/', 'pexels', true, 'public', false,
  'pending_review', array['breakfast', 'quick', 'budget', 'comfort']::text[], array['no_cook']::text[], array['tangy', 'aromatic']::text[], '{}'::text[], null, null, 'overnight-oats', 'classic', 'Keeps 4 days in the fridge in sealed jars; add crunchy toppings just before eating.', null, 'owned', array['milk', 'tree_nut']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['rolled oat', 'milk', 'greek yogurt', 'chia seed', 'maple syrup', 'vanilla extract', 'ground cinnamon', 'mixed berry']::text[], 'chia seed|greek yogurt|ground cinnamon|maple syrup|milk|mixed berry|rolled oat|vanilla extract',
  null, null, null, null, null, null, null, null)
