delete from public.recipe_instructions where recipe_id = 'a9169af9-a105-484b-9957-de65c271cade';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('a9169af9-a105-484b-9957-de65c271cade', 1, null, 'In a large bowl or pitcher, stir together the milk, yogurt, chia seeds, maple syrup, vanilla, cinnamon and salt until smooth.', 120, null, null),
  ('a9169af9-a105-484b-9957-de65c271cade', 2, null, 'Stir in the oats, making sure they''re all submerged. Let stand 5 minutes, then stir again so the chia seeds don''t clump.', 300, null, null),
  ('a9169af9-a105-484b-9957-de65c271cade', 3, null, 'Divide among four jars or containers with lids, top each with berries (frozen ones thaw overnight), seal and refrigerate at least 6 hours or overnight.', 28800, null, null),
  ('a9169af9-a105-484b-9957-de65c271cade', 4, null, 'In the morning, stir, loosen with a splash of milk if it''s thicker than you like and top with almonds. Eat cold, or warm in the microwave for 1–2 minutes.', 60, null, null);

