values ('59e3f0ed-fb5e-4176-9fd2-662f0612b5fb', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'homemade-granola', 'homemade-granola-59e3f0', 'Homemade Granola', 'Big, crunchy clusters of oats, pecans and pumpkin seeds baked with maple syrup and cinnamon, with dried cherries stirred in once it cools.', 'american', 1, 10, 35, 75, 12, 'breakfast', null, 30, array['oven']::text[], array['make-ahead', 'budget', 'meal-prep', 'gift']::text[], array['Granola feels slightly soft straight out of the oven; don''t bake it longer, just let it cool. Pressing it down firmly before and during baking is what makes big clusters.', 'Oats are often processed alongside wheat — check the oat package if gluten matters to anyone eating.']::text[], 'https://images.unsplash.com/photo-1724441980123-aca7911329d0', 'Jar of granola beside a wooden spoon', 'Mayte Baque', 'https://unsplash.com/@mtbaque', 'https://unsplash.com/photos/a-jar-filled-with-granola-next-to-a-wooden-spoon-LQftwRfGjOM', 'unsplash', true, 'public', false,
  'pending_review', array['breakfast', 'baking', 'budget']::text[], array['bake']::text[], array['aromatic']::text[], '{}'::text[], null, null, 'granola', 'classic', 'Keeps 2 weeks in an airtight jar at room temperature, or 3 months in the freezer.', null, 'owned', array['tree_nut']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'dairy_free']::text[], array['rolled oat', 'pecan', 'pumpkin seed', 'ground cinnamon', 'maple syrup', 'vanilla extract', 'tart cherry']::text[], 'ground cinnamon|maple syrup|pecan|pumpkin seed|rolled oat|tart cherry|vanilla extract',
  null, null, null, null, null, null, null, null)
