insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('59e3f0ed-fb5e-4176-9fd2-662f0612b5fb', 1, null, '3 cups old-fashioned rolled oats', 'old-fashioned rolled oats', 3, 'cup', null, false),
  ('59e3f0ed-fb5e-4176-9fd2-662f0612b5fb', 2, null, '1 cup pecans, roughly chopped', 'pecans', 1, 'cup', 'roughly chopped', false),
  ('59e3f0ed-fb5e-4176-9fd2-662f0612b5fb', 3, null, '½ cup pumpkin seeds (pepitas)', 'pumpkin seeds (pepitas)', 0.5, 'cup', null, false),
  ('59e3f0ed-fb5e-4176-9fd2-662f0612b5fb', 4, null, '½ cup unsweetened shredded coconut', 'unsweetened shredded coconut', 0.5, 'cup', null, true),
  ('59e3f0ed-fb5e-4176-9fd2-662f0612b5fb', 5, null, '1 tsp ground cinnamon', 'ground cinnamon', 1, 'tsp', null, false),
  ('59e3f0ed-fb5e-4176-9fd2-662f0612b5fb', 6, null, '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('59e3f0ed-fb5e-4176-9fd2-662f0612b5fb', 7, null, '½ cup maple syrup', 'maple syrup', 0.5, 'cup', null, false),
  ('59e3f0ed-fb5e-4176-9fd2-662f0612b5fb', 8, null, '⅓ cup extra-virgin olive oil, or melted coconut oil', 'extra-virgin olive oil', 0.33, 'cup', 'or melted coconut oil', false),
  ('59e3f0ed-fb5e-4176-9fd2-662f0612b5fb', 9, null, '1 tsp vanilla extract', 'vanilla extract', 1, 'tsp', null, false),
  ('59e3f0ed-fb5e-4176-9fd2-662f0612b5fb', 10, null, '¾ cup dried tart cherries, or raisins', 'dried tart cherries', 0.75, 'cup', 'or raisins', false);
delete from public.recipe_instructions where recipe_id = '59e3f0ed-fb5e-4176-9fd2-662f0612b5fb';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('59e3f0ed-fb5e-4176-9fd2-662f0612b5fb', 1, null, 'Heat the oven to 325°F and line a large rimmed baking sheet with parchment paper.', null, 162.8, null),
  ('59e3f0ed-fb5e-4176-9fd2-662f0612b5fb', 2, null, 'In a large bowl, toss the oats, pecans, pumpkin seeds, coconut, cinnamon and salt. In a measuring cup, whisk the maple syrup, oil and vanilla, pour over the oats and stir until everything is evenly coated.', 180, null, null),
  ('59e3f0ed-fb5e-4176-9fd2-662f0612b5fb', 3, null, 'Spread the mixture on the baking sheet and press it down firmly with a spatula into an even layer.', 60, null, null),
  ('59e3f0ed-fb5e-4176-9fd2-662f0612b5fb', 4, null, 'Bake 15 minutes, then rotate the pan and turn the granola over in large pieces with the spatula. Press it down again and bake until deep golden and fragrant, 15–20 minutes more. Watch the edges in the last few minutes — they brown fastest.', 2100, 162.8, null),
  ('59e3f0ed-fb5e-4176-9fd2-662f0612b5fb', 5, null, 'Let it cool completely on the pan without stirring — it crisps as it cools. Break into clusters and stir in the dried cherries.', 1800, null, null);

