values ('722811a9-eb19-46a0-8226-3ed6b6b3dfaf', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'blueberry-muffins', 'blueberry-muffins-722811', 'Blueberry Muffins', 'Tender, domed buttermilk muffins packed with blueberries and a hint of lemon, under a crackly sugar top.', 'american', 1, 15, 22, 37, 12, 'breakfast', null, 0, array['oven']::text[], array['kid-friendly', 'make-ahead', 'freezer-friendly']::text[], array['No buttermilk? Stir 1 tablespoon lemon juice into 1 cup whole milk and let it stand 5 minutes.', 'Toss frozen blueberries with a tablespoon of the flour mixture before folding in so they streak less purple.']::text[], 'https://images.unsplash.com/photo-1722251172903-cc8774501df7', 'Three blueberry muffins on a black plate', 'Elena Taranukhina', 'https://unsplash.com/@elena_yt', 'https://unsplash.com/photos/a-black-plate-topped-with-three-blueberry-muffins-G8SrS1ewVXM', 'unsplash', true, 'public', false,
  'pending_review', array['breakfast', 'baking', 'holiday', 'comfort']::text[], array['bake']::text[], array['tangy']::text[], array['brunch-party']::text[], null, null, 'blueberry-muffins', 'classic', 'Keep in an airtight container at room temperature up to 2 days, or freeze up to 3 months. Warm frozen muffins in a 300°F oven for 10 minutes.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['baking powder', 'baking soda', 'egg', 'buttermilk', 'vanilla extract', 'blueberry', 'turbinado sugar']::text[], 'baking powder|baking soda|blueberry|buttermilk|egg|turbinado sugar|vanilla extract',
  null, null, null, null, null, null, null, null)
