insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('722811a9-eb19-46a0-8226-3ed6b6b3dfaf', 1, null, 'Heat the oven to 375°F. Line a 12-cup muffin tin with paper liners or grease it well.', null, 190.6, null),
  ('722811a9-eb19-46a0-8226-3ed6b6b3dfaf', 2, null, 'Whisk the flour, sugar, baking powder, baking soda and salt in a large bowl. In another bowl, whisk the melted butter, eggs, buttermilk, vanilla and lemon zest.', 180, null, null),
  ('722811a9-eb19-46a0-8226-3ed6b6b3dfaf', 3, null, 'Pour the wet ingredients into the dry and fold with a spatula until only a few streaks of flour remain. Gently fold in the blueberries — stop as soon as they''re spread through; overmixing makes muffins tough.', 120, null, null),
  ('722811a9-eb19-46a0-8226-3ed6b6b3dfaf', 4, null, 'Divide the batter among the cups (they''ll be full to the top) and sprinkle with the coarse sugar.', null, null, null),
  ('722811a9-eb19-46a0-8226-3ed6b6b3dfaf', 5, null, 'Bake until risen, golden and a toothpick in the center comes out clean or with a few moist crumbs, 20–24 minutes.', 1320, 190.6, null),
  ('722811a9-eb19-46a0-8226-3ed6b6b3dfaf', 6, null, 'Cool in the tin 5 minutes, then lift onto a rack. Serve warm or at room temperature.', 300, null, null);

