values ('68885a16-080c-42d3-9856-b06aaad826ee', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'cinnamon-rolls', 'cinnamon-rolls-68885a', 'Cinnamon Rolls', 'Soft, buttery yeast rolls swirled with brown sugar and cinnamon and spread with tangy cream cheese icing while they''re still warm.', 'american', 2, 150, 25, 175, 12, 'breakfast', null, 0, array['oven']::text[], array['make-ahead', 'comfort', 'entertaining', 'kid-friendly']::text[], array['Overnight rolls: after cutting and arranging them, cover tightly and refrigerate up to 16 hours. In the morning, let them sit on the counter 1 hour to finish rising, then bake.', 'Milk hotter than about 120°F can kill the yeast — it should feel just warm on your wrist.']::text[], 'https://images.unsplash.com/photo-1694632288834-17d86b340745', 'Pan of cinnamon rolls covered in icing', 'Anisa Cakesandbakes', 'https://unsplash.com/@anisacakesandbakes', 'https://unsplash.com/photos/a-pan-filled-with-cinnamon-rolls-covered-in-icing-c07YNJmNfaE', 'unsplash', true, 'public', false,
  'pending_review', array['breakfast', 'baking', 'holiday', 'comfort', 'entertaining']::text[], array['bake']::text[], array['rich', 'aromatic']::text[], array['christmas', 'brunch-party']::text[], null, null, 'cinnamon-rolls', 'classic', 'Keep covered at room temperature 1 day or in the fridge up to 4 days; warm individual rolls in the microwave for 15–20 seconds. Freeze un-iced rolls up to 2 months.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['milk', 'instant yeast', 'egg', 'brown sugar', 'ground cinnamon', 'cream cheese', 'powdered sugar', 'vanilla extract']::text[], 'brown sugar|cream cheese|egg|ground cinnamon|instant yeast|milk|powdered sugar|vanilla extract',
  null, null, null, null, null, null, null, null)
