insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('68885a16-080c-42d3-9856-b06aaad826ee', 1, 'Dough', 'In a large bowl (or a stand mixer with the dough hook), stir the warm milk, yeast and sugar. Add the eggs and softened butter, then the flour and salt, and mix into a shaggy dough.', 300, null, null),
  ('68885a16-080c-42d3-9856-b06aaad826ee', 2, 'Dough', 'Knead on a lightly floured counter (or 6 minutes on medium-low in the mixer) until smooth, soft and slightly tacky, 8–10 minutes. Add flour a tablespoon at a time only if it sticks badly. Put it in a greased bowl, cover and let rise somewhere warm until doubled, 1–1½ hours.', 4800, null, null),
  ('68885a16-080c-42d3-9856-b06aaad826ee', 3, 'Filling', 'Mix the brown sugar and cinnamon. Butter a 9×13-inch baking pan. Roll the dough into a 16×12-inch rectangle, spread with the soft butter right to the edges and sprinkle evenly with the cinnamon sugar.', 600, null, null),
  ('68885a16-080c-42d3-9856-b06aaad826ee', 4, 'Filling', 'Starting from a long side, roll the dough up snugly into a log and pinch the seam closed. Cut into 12 even slices with a sharp knife or a loop of unflavored dental floss and arrange cut-side up in the pan. Cover and let rise until puffy and touching, 30–45 minutes.', 2400, null, null),
  ('68885a16-080c-42d3-9856-b06aaad826ee', 5, null, 'Meanwhile, heat the oven to 350°F. Bake the rolls until golden brown and the center roll reads 190°F, 22–26 minutes. If they brown too fast, lay foil loosely over the top.', 1440, 176.7, null),
  ('68885a16-080c-42d3-9856-b06aaad826ee', 6, 'Icing', 'While they bake, beat the cream cheese, butter, powdered sugar and vanilla until smooth, adding milk until spreadable. Let the rolls cool 10 minutes, then spread with the icing and serve warm.', 600, null, null);

-- Crispy Hash Browns
