values ('7be00e7b-6202-4f0c-a070-33a91a138fcd', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'crispy-hash-browns', 'crispy-hash-browns-7be00e', 'Crispy Hash Browns', 'Shredded russet potatoes squeezed bone-dry and fried in one big golden cake in a hot cast-iron skillet, diner-style.', 'american', 1, 15, 16, 31, 4, 'breakfast', null, 0, array['stove', 'cast_iron']::text[], array['budget', 'kid-friendly', 'weeknight']::text[], array['Grate the potatoes right before cooking — shreds left sitting turn gray.', 'Short on time? Use 20 oz refrigerated shredded hash brown potatoes and skip the rinsing; just pat them dry.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['breakfast', 'side', 'budget', 'comfort']::text[], '{}'::text[], '{}'::text[], '{}'::text[], null, null, 'hash-browns', 'classic', 'Best fresh. Refrigerate leftovers up to 2 days and re-crisp in a hot skillet or a 425°F oven.', null, 'owned', array['milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['russet potato']::text[], 'russet potato',
  null, null, null, null, null, null, null, null)
