insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7be00e7b-6202-4f0c-a070-33a91a138fcd', 1, null, 'Peel the potatoes (or leave the skins on) and grate them on the large holes of a box grater. Put the shreds in a bowl of cold water and swish them around for 30 seconds to wash off the surface starch, then drain.', 360, null, null),
  ('7be00e7b-6202-4f0c-a070-33a91a138fcd', 2, null, 'Pile the potatoes onto a clean kitchen towel, gather it up and twist hard over the sink until no more water drips out. Getting them really dry is what makes them crisp. Toss with the onion, salt and pepper.', 180, null, null),
  ('7be00e7b-6202-4f0c-a070-33a91a138fcd', 3, null, 'Heat a 12-inch cast-iron skillet over medium-high heat with 3 tablespoons of the oil and 1 tablespoon of the butter until the butter foams. Spread the potatoes in an even layer about ½ inch thick and press down lightly.', 120, null, null),
  ('7be00e7b-6202-4f0c-a070-33a91a138fcd', 4, null, 'Cook without stirring until the bottom is deep golden and crisp, 7–8 minutes (lift an edge to check). Cut into quarters with the spatula and flip each piece, adding the remaining oil and butter around the edges.', 480, null, null),
  ('7be00e7b-6202-4f0c-a070-33a91a138fcd', 5, null, 'Cook the second side until golden and the potatoes are tender inside, 6–7 minutes more. Slide onto paper towels, sprinkle with a little more salt and serve hot.', 420, null, null);

