values ('417b4119-af83-43df-b1ef-bc9cbbf13602', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'banana-bread', 'banana-bread-417b41', 'Banana Bread', 'A moist, deeply banana-flavored loaf made in one bowl with melted butter and brown sugar — the best use for spotty bananas.', 'american', 1, 15, 60, 105, 10, 'dessert', 'cakes', 30, array['oven']::text[], array['kid-friendly', 'budget', 'make-ahead', 'freezer-friendly', 'comfort']::text[], array['Freeze overripe bananas in their skins; thaw them in a bowl and use the bananas and their liquid.', 'The darker the banana skins, the sweeter and more flavorful the bread.']::text[], 'https://images.pexels.com/photos/4114142/pexels-photo-4114142.jpeg', 'Sliced loaf of banana bread with fresh bananas on a wooden table', 'alleksana', 'https://www.pexels.com/@alleksana/', 'https://www.pexels.com/photo/bananas-and-banana-bread-4114142/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'comfort', 'budget', 'dessert']::text[], array['bake']::text[], array['aromatic', 'sweet']::text[], '{}'::text[], null, null, 'banana-bread', 'classic', 'Wrap and keep at room temperature up to 3 days, or freeze whole or in slices up to 3 months.', null, 'owned', array['egg', 'gluten', 'milk', 'tree_nut', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['very banana', 'brown sugar', 'egg', 'vanilla extract', 'baking soda', 'ground cinnamon']::text[], 'baking soda|brown sugar|egg|ground cinnamon|vanilla extract|very banana',
  null, null, null, null, null, null, null, null)
