values ('728a3b10-1262-438b-812e-c705d5053ffe', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'zucchini-bread', 'zucchini-bread-728a3b', 'Zucchini Bread', 'A tender, lightly spiced loaf that turns a glut of summer zucchini into something everyone will eat, with optional walnuts for crunch.', 'american', 1, 15, 55, 100, 10, 'dessert', 'cakes', 30, array['oven']::text[], array['kid-friendly', 'make-ahead', 'freezer-friendly', 'budget', 'summer']::text[], array['Leave the zucchini skin on — it disappears into the loaf and adds pretty green flecks.', 'Stir ½ cup chocolate chips in with the walnuts for a sweeter loaf kids love.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['baking', 'budget', 'dessert', 'comfort']::text[], array['bake']::text[], array['aromatic', 'sweet']::text[], '{}'::text[], null, null, 'zucchini-bread', 'classic', 'Wrap and keep at room temperature up to 3 days or in the fridge up to a week; freeze up to 3 months.', null, 'owned', array['egg', 'gluten', 'tree_nut', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'dairy_free']::text[], array['zucchini', 'ground cinnamon', 'ground nutmeg', 'baking soda', 'baking powder', 'egg', 'brown sugar', 'vanilla extract']::text[], 'baking powder|baking soda|brown sugar|egg|ground cinnamon|ground nutmeg|vanilla extract|zucchini',
