values ('99b688a9-849e-452d-a7e2-662a5e504fea', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'carrot-cake', 'carrot-cake-99b688', 'Carrot Cake', 'A moist, warmly spiced carrot and pineapple sheet cake under a thick layer of tangy cream cheese frosting — no layers to stack.', 'american', 2, 30, 38, 158, 16, 'dessert', 'cakes', 90, array['oven']::text[], array['entertaining', 'make-ahead', 'potluck']::text[], array['Grate the carrots on the small holes of a box grater or with a food processor''s fine disc — big shreds stay crunchy.', 'Use brick-style cream cheese for the frosting; the spreadable tub kind makes it runny.']::text[], 'https://images.pexels.com/photos/5594502/pexels-photo-5594502.jpeg', 'Slice of layered carrot cake with cream cheese frosting and walnuts', 'Leeloo The First', 'https://www.pexels.com/@leeloothefirst/', 'https://www.pexels.com/photo/a-slice-of-layer-cake-lying-on-a-plate-with-a-fork-5594502/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'entertaining', 'dessert', 'holiday']::text[], array['bake']::text[], array['rich', 'aromatic', 'sweet']::text[], array['easter', 'birthday', 'potluck']::text[], null, null, 'carrot-cake', 'classic', 'Because of the frosting, keep the cake covered in the fridge up to 5 days; let slices sit out 20 minutes before serving. Unfrosted cake freezes up to 2 months.', null, 'owned', array['egg', 'gluten', 'milk', 'tree_nut', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['baking powder', 'baking soda', 'ground cinnamon', 'ground ginger', 'ground nutmeg', 'egg', 'brown sugar', 'vanilla extract', 'carrot', 'pineapple', 'cream cheese', 'powdered sugar']::text[], 'baking powder|baking soda|brown sugar|carrot|cream cheese|egg|ground cinnamon|ground ginger|ground nutmeg|pineapple|powdered sugar|vanilla extract',
  null, null, null, null, null, null, null, null)
