insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('99b688a9-849e-452d-a7e2-662a5e504fea', 1, 'Cake', 'Heat the oven to 350°F. Grease a 9×13-inch baking pan and line the bottom with parchment paper.', null, 176.7, null),
  ('99b688a9-849e-452d-a7e2-662a5e504fea', 2, 'Cake', 'Whisk the flour, baking powder, baking soda, salt, cinnamon, ginger and nutmeg in a bowl. In a large bowl, whisk the eggs, oil, both sugars and vanilla until smooth and slightly thickened, about 1 minute.', 240, null, null),
  ('99b688a9-849e-452d-a7e2-662a5e504fea', 3, 'Cake', 'Fold the flour mixture into the egg mixture until just combined, then fold in the carrots, pineapple and nuts, if using.', 120, null, null),
  ('99b688a9-849e-452d-a7e2-662a5e504fea', 4, 'Cake', 'Spread in the pan and bake until the top springs back when pressed and a toothpick in the center comes out clean, 35–40 minutes.', 2280, 176.7, null),
  ('99b688a9-849e-452d-a7e2-662a5e504fea', 5, 'Cake', 'Cool completely in the pan on a rack, at least 1½ hours — frosting a warm cake makes it slide off.', 5400, null, null),
  ('99b688a9-849e-452d-a7e2-662a5e504fea', 6, 'Frosting', 'Beat the cream cheese and butter with a hand mixer until smooth and lump-free, then beat in the powdered sugar, vanilla and salt on low, then medium, until fluffy, about 2 minutes. Spread over the cooled cake.', 300, null, null);

-- Fudgy Brownies
