values ('a0928c48-ae42-4e44-813f-499f88f75145', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'fudgy-brownies', 'fudgy-brownies-a0928c', 'Fudgy Brownies', 'Dense, deeply chocolatey brownies with a shiny, crackly top and chunks of melted chocolate, mixed in one saucepan.', 'american', 1, 15, 28, 103, 16, 'dessert', 'cookies', 60, array['stove', 'oven']::text[], array['kid-friendly', 'make-ahead', 'potluck', 'comfort']::text[], array['Many chocolate bars and chips contain milk or soy lecithin — check the label if anyone has allergies.', 'A glass pan bakes slower and darker at the edges; add 5 minutes and check early.']::text[], 'https://images.pexels.com/photos/7157867/pexels-photo-7157867.jpeg', 'Stack of chocolate brownies on a white plate', 'Ludwig Kwan', 'https://www.pexels.com/@ludawigakwana/', 'https://www.pexels.com/photo/chocolate-brownies-on-a-white-ceramic-plate-7157867/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'comfort', 'dessert', 'holiday']::text[], array['bake']::text[], array['sweet']::text[], array['birthday', 'potluck']::text[], null, null, 'brownies', 'classic', 'Keep in an airtight container at room temperature up to 4 days, or freeze individually wrapped up to 3 months.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['cocoa powder', 'vanilla extract', 'egg', 'bittersweet chocolate']::text[], 'bittersweet chocolate|cocoa powder|egg|vanilla extract',
  null, null, null, null, null, null, null, null)
