insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('a0928c48-ae42-4e44-813f-499f88f75145', 1, null, '10 tbsp unsalted butter', 'unsalted butter', 10, 'tbsp', null, false),
  ('a0928c48-ae42-4e44-813f-499f88f75145', 2, null, '1¼ cups sugar', 'sugar', 1.25, 'cup', null, false),
  ('a0928c48-ae42-4e44-813f-499f88f75145', 3, null, '¾ cup unsweetened cocoa powder', 'unsweetened cocoa powder', 0.75, 'cup', null, false),
  ('a0928c48-ae42-4e44-813f-499f88f75145', 4, null, '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('a0928c48-ae42-4e44-813f-499f88f75145', 5, null, '1 tsp vanilla extract', 'vanilla extract', 1, 'tsp', null, false),
  ('a0928c48-ae42-4e44-813f-499f88f75145', 6, null, '2 large eggs, cold', 'large eggs', 2, null, 'cold', false),
  ('a0928c48-ae42-4e44-813f-499f88f75145', 7, null, '½ cup all-purpose flour', 'all-purpose flour', 0.5, 'cup', null, false),
  ('a0928c48-ae42-4e44-813f-499f88f75145', 8, null, '4 oz bittersweet chocolate, chopped, or ⅔ cup chocolate chips', 'bittersweet chocolate', 4, 'oz', 'chopped, or ⅔ cup chocolate chips', false);
delete from public.recipe_instructions where recipe_id = 'a0928c48-ae42-4e44-813f-499f88f75145';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('a0928c48-ae42-4e44-813f-499f88f75145', 1, null, 'Heat the oven to 325°F. Line an 8-inch square metal baking pan with parchment paper, leaving some hanging over two sides as handles.', null, 162.8, null),
  ('a0928c48-ae42-4e44-813f-499f88f75145', 2, null, 'Melt the butter in a medium saucepan over low heat. Take it off the heat and stir in the sugar, cocoa and salt. Let it cool for 5 minutes until warm, not hot.', 420, null, null),
  ('a0928c48-ae42-4e44-813f-499f88f75145', 3, null, 'Stir in the vanilla, then add the eggs one at a time, beating hard with a wooden spoon after each until the batter turns thick, shiny and pulls away from the pan, about 1 minute in all. This vigorous beating gives the crackly top.', 120, null, null),
  ('a0928c48-ae42-4e44-813f-499f88f75145', 4, null, 'Stir in the flour until no streaks remain, then fold in the chopped chocolate. Spread evenly in the pan.', 60, null, null),
  ('a0928c48-ae42-4e44-813f-499f88f75145', 5, null, 'Bake until the edges are set and a toothpick in the center comes out with moist crumbs (not wet batter), 25–30 minutes.', 1680, 162.8, null),
  ('a0928c48-ae42-4e44-813f-499f88f75145', 6, null, 'Cool completely in the pan on a rack, at least 1 hour (or chill for the cleanest cuts), then lift out and cut into 16 squares.', 3600, null, null);

-- Southern Banana Pudding
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
