values ('b833a975-8a16-4245-9f09-c433f88c449a', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'southern-banana-pudding', 'southern-banana-pudding-b833a9', 'Southern Banana Pudding', 'Layers of vanilla wafers, sliced bananas and a from-scratch stovetop vanilla custard, chilled until the cookies go soft and cakey, then crowned with whipped cream.', 'southern', 2, 25, 12, 277, 10, 'dessert', 'plated', 240, array['stove']::text[], array['make-ahead', 'potluck', 'comfort', 'kid-friendly']::text[], array['Vanilla wafers usually contain wheat, egg, milk and soy — check the box if anyone has allergies.', 'Covering every banana slice with custard keeps them from browning.']::text[], 'https://images.pexels.com/photos/13554342/pexels-photo-13554342.jpeg', 'Banana pudding layered with wafer cookies in glasses', 'Angela Khebou', 'https://www.pexels.com/@angela-khebou-259135285/', 'https://www.pexels.com/photo/glasses-with-creamy-dessert-13554342/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'entertaining', 'dessert', 'holiday']::text[], '{}'::text[], array['rich', 'sweet']::text[], array['potluck', 'july-4th']::text[], null, 'traditional', 'banana-pudding', 'classic', 'Keeps covered in the fridge up to 2 days; the bananas darken and the wafers get softer after that.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['cornstarch', 'milk', 'egg yolk', 'vanilla extract', 'wafer cooky', 'banana', 'heavy cream', 'powdered sugar']::text[], 'banana|cornstarch|egg yolk|heavy cream|milk|powdered sugar|vanilla extract|wafer cooky',
  null, null, null, null, null, null, null, null)
