  ('b833a975-8a16-4245-9f09-c433f88c449a', 1, 'Custard', '¾ cup sugar', 'sugar', 0.75, 'cup', null, false),
  ('b833a975-8a16-4245-9f09-c433f88c449a', 2, 'Custard', '¼ cup cornstarch', 'cornstarch', 0.25, 'cup', null, false),
  ('b833a975-8a16-4245-9f09-c433f88c449a', 3, 'Custard', '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('b833a975-8a16-4245-9f09-c433f88c449a', 4, 'Custard', '3 cups whole milk', 'whole milk', 3, 'cup', null, false),
  ('b833a975-8a16-4245-9f09-c433f88c449a', 5, 'Custard', '4 large egg yolks', 'large egg yolks', 4, null, null, false),
  ('b833a975-8a16-4245-9f09-c433f88c449a', 6, 'Custard', '2 tbsp unsalted butter', 'unsalted butter', 2, 'tbsp', null, false),
  ('b833a975-8a16-4245-9f09-c433f88c449a', 7, 'Custard', '2 tsp vanilla extract', 'vanilla extract', 2, 'tsp', null, false),
  ('b833a975-8a16-4245-9f09-c433f88c449a', 8, 'Layers', '1 package vanilla wafer cookies, 11 oz box', 'vanilla wafer cookies', 1, 'package', '11 oz box', false),
