insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('b833a975-8a16-4245-9f09-c433f88c449a', 1, 'Custard', 'Whisk the sugar, cornstarch and salt in a medium saucepan, then whisk in the milk and egg yolks until smooth.', 120, null, null),
  ('b833a975-8a16-4245-9f09-c433f88c449a', 2, 'Custard', 'Cook over medium heat, whisking constantly and scraping the bottom and corners, until it thickens and a couple of slow bubbles pop on the surface, 7–9 minutes (it will be well above 160°F). Cook 1 minute more, then take off the heat and whisk in the butter and vanilla.', 540, null, 71.1),
  ('b833a975-8a16-4245-9f09-c433f88c449a', 3, 'Custard', 'Press plastic wrap onto the surface so it doesn''t form a skin and let it cool 15 minutes.', 900, null, null),
  ('b833a975-8a16-4245-9f09-c433f88c449a', 4, 'Layers', 'Slice the bananas into ¼-inch rounds. In a 2½- to 3-quart dish, layer a third of the wafers, a third of the bananas and a third of the custard. Repeat twice, ending with custard, and save a handful of wafers for the top.', 480, null, null),
  ('b833a975-8a16-4245-9f09-c433f88c449a', 5, null, 'Cover and refrigerate at least 4 hours or overnight, until the wafers soften.', 14400, null, null),
  ('b833a975-8a16-4245-9f09-c433f88c449a', 6, 'Topping', 'Before serving, whip the cream and powdered sugar to soft peaks, spread over the pudding and crumble the reserved wafers on top.', 240, null, null);

