values ('8f613be8-bfb1-453a-8714-18ac3e5fe2ad', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'peach-cobbler', 'peach-cobbler-8f613b', 'Peach Cobbler', 'Juicy cinnamon peaches baked into a buttery Southern batter that rises up around the fruit with crisp, golden edges.', 'southern', 1, 20, 55, 95, 8, 'dessert', 'fruit', 20, array['stove', 'oven']::text[], array['comfort', 'summer', 'potluck', 'kid-friendly']::text[], array['To peel fresh peaches quickly, drop them in boiling water for 30 seconds, then into ice water; the skins slip off.', 'Canned peaches work too: use two 29-oz cans, drained, and cut the sugar on the fruit to 2 tablespoons.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['baking', 'comfort', 'dessert', 'holiday']::text[], array['bake']::text[], array['tangy', 'aromatic', 'sweet']::text[], array['july-4th', 'potluck']::text[], null, 'traditional', 'peach-cobbler', 'classic', 'Cover and refrigerate up to 4 days. Rewarm portions in the microwave or a 325°F oven.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['peache', 'lemon juice', 'ground cinnamon', 'ground nutmeg', 'baking powder', 'milk', 'vanilla extract']::text[], 'baking powder|ground cinnamon|ground nutmeg|lemon juice|milk|peache|vanilla extract',
  null, null, null, null, null, null, null, null)
