  ('8f613be8-bfb1-453a-8714-18ac3e5fe2ad', 4, 'Peaches', '½ tsp ground cinnamon', 'ground cinnamon', 0.5, 'tsp', null, false),
  ('8f613be8-bfb1-453a-8714-18ac3e5fe2ad', 5, 'Peaches', '1 pinch ground nutmeg', 'ground nutmeg', 1, 'pinch', null, false),
  ('8f613be8-bfb1-453a-8714-18ac3e5fe2ad', 6, 'Batter', '8 tbsp unsalted butter', 'unsalted butter', 8, 'tbsp', null, false),
  ('8f613be8-bfb1-453a-8714-18ac3e5fe2ad', 7, 'Batter', '1 cup all-purpose flour', 'all-purpose flour', 1, 'cup', null, false),
