delete from public.recipe_instructions where recipe_id = '8f613be8-bfb1-453a-8714-18ac3e5fe2ad';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('8f613be8-bfb1-453a-8714-18ac3e5fe2ad', 1, 'Peaches', 'Heat the oven to 350°F. In a saucepan over medium heat, stir the peaches, sugar, lemon juice, cinnamon and nutmeg and cook until the sugar dissolves and the peaches release their juice, about 5 minutes. Set aside.', 300, 176.7, null),
  ('8f613be8-bfb1-453a-8714-18ac3e5fe2ad', 2, 'Batter', 'Put the butter in a 9×13-inch baking dish and set it in the oven until melted, about 5 minutes. Take it out carefully.', 300, 176.7, null),
  ('8f613be8-bfb1-453a-8714-18ac3e5fe2ad', 3, 'Batter', 'Whisk the flour, sugar, baking powder and salt, then whisk in the milk and vanilla until smooth. Pour the batter evenly over the melted butter — don''t stir.', 180, null, null),
  ('8f613be8-bfb1-453a-8714-18ac3e5fe2ad', 4, null, 'Spoon the peaches and their juice evenly over the batter — again, don''t stir. The batter will rise up around the fruit as it bakes.', 60, null, null),
  ('8f613be8-bfb1-453a-8714-18ac3e5fe2ad', 5, null, 'Bake until the top is deep golden, the edges are crisp and the center is set when jiggled, 45–50 minutes.', 2880, 176.7, null),
  ('8f613be8-bfb1-453a-8714-18ac3e5fe2ad', 6, null, 'Let rest 20 minutes so the juices thicken, then serve warm with vanilla ice cream.', 1200, null, null);

