values ('bf98c53f-b77d-47f9-945a-d9590179712c', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'key-lime-pie', 'key-lime-pie-bf98c5', 'Key Lime Pie', 'A sweet-tart, silky lime custard of sweetened condensed milk and egg yolks baked in a buttery graham cracker crust and chilled until sliceable.', 'american', 1, 20, 32, 352, 8, 'dessert', 'pastries', 300, array['oven']::text[], array['make-ahead', 'summer', 'entertaining']::text[], array['Graham crackers usually contain wheat and sometimes milk or soy — check the box if anyone has allergies.', 'Fresh Key limes are tiny and fiddly (you''ll need about 20); bottled Key lime juice or regular Persian limes both work well.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['baking', 'entertaining', 'dessert', 'holiday']::text[], array['bake']::text[], array['tangy', 'rich', 'sweet']::text[], array['july-4th', 'easter']::text[], 'Florida Keys', 'traditional', 'key-lime-pie', 'classic', 'Keep covered in the fridge up to 3 days, or freeze the pie (without the cream) up to 1 month and serve semi-frozen.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['cracker crumb', 'condensed milk', 'egg yolk', 'lime juice', 'lime zest', 'heavy cream', 'powdered sugar']::text[], 'condensed milk|cracker crumb|egg yolk|heavy cream|lime juice|lime zest|powdered sugar',
  null, null, null, null, null, null, null, null)
