  ('bf98c53f-b77d-47f9-945a-d9590179712c', 1, 'Crust', '1½ cups graham cracker crumbs, about 11 full sheets', 'graham cracker crumbs', 1.5, 'cup', 'about 11 full sheets', false),
  ('bf98c53f-b77d-47f9-945a-d9590179712c', 2, 'Crust', '3 tbsp sugar', 'sugar', 3, 'tbsp', null, false),
  ('bf98c53f-b77d-47f9-945a-d9590179712c', 3, 'Crust', '6 tbsp unsalted butter, melted', 'unsalted butter', 6, 'tbsp', 'melted', false),
  ('bf98c53f-b77d-47f9-945a-d9590179712c', 4, 'Crust', '1 pinch kosher salt', 'kosher salt', 1, 'pinch', null, false),
  ('bf98c53f-b77d-47f9-945a-d9590179712c', 5, 'Filling', '1 can sweetened condensed milk, 14 oz', 'sweetened condensed milk', 1, 'can', '14 oz', false),
  ('bf98c53f-b77d-47f9-945a-d9590179712c', 6, 'Filling', '4 large egg yolks', 'large egg yolks', 4, null, null, false),
  ('bf98c53f-b77d-47f9-945a-d9590179712c', 7, 'Filling', '½ cup Key lime juice, fresh or bottled, or regular lime juice', 'Key lime juice', 0.5, 'cup', 'fresh or bottled, or regular lime juice', false),
  ('bf98c53f-b77d-47f9-945a-d9590179712c', 8, 'Filling', '1 tbsp lime zest, finely grated', 'lime zest', 1, 'tbsp', 'finely grated', false),
