delete from public.recipe_instructions where recipe_id = 'bf98c53f-b77d-47f9-945a-d9590179712c';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('bf98c53f-b77d-47f9-945a-d9590179712c', 1, 'Crust', 'Heat the oven to 350°F. Stir the graham cracker crumbs, sugar, melted butter and salt until it looks like wet sand. Press firmly and evenly over the bottom and up the sides of a 9-inch pie plate, using the bottom of a measuring cup.', 300, 176.7, null),
  ('bf98c53f-b77d-47f9-945a-d9590179712c', 2, 'Crust', 'Bake until fragrant and a shade darker, 10 minutes. Let it cool for at least 15 minutes.', 600, 176.7, null),
  ('bf98c53f-b77d-47f9-945a-d9590179712c', 3, 'Filling', 'Whisk the egg yolks and lime zest for 1 minute, then whisk in the condensed milk and finally the lime juice until smooth and slightly thickened.', 120, null, null),
  ('bf98c53f-b77d-47f9-945a-d9590179712c', 4, 'Filling', 'Pour into the crust and bake until the edges are set and the center barely wobbles and reads 160°F, 18–22 minutes.', 1200, 176.7, 71.1),
  ('bf98c53f-b77d-47f9-945a-d9590179712c', 5, null, 'Cool to room temperature on a rack, about 1 hour, then refrigerate until firm and cold, at least 4 hours.', 18000, null, null),
  ('bf98c53f-b77d-47f9-945a-d9590179712c', 6, 'Topping', 'Before serving, whip the cream and powdered sugar to soft peaks and spread or pipe over the pie. Slice with a knife dipped in hot water.', 240, null, null);

