values ('4132d29e-9ed2-4b45-b14f-86d29ea276a2', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'classic-apple-pie', 'classic-apple-pie-4132d2', 'Classic Apple Pie', 'A tall double-crust pie of tart and sweet apples with cinnamon and a little lemon, in a flaky all-butter crust baked until the juices bubble thick.', 'american', 2, 50, 70, 360, 8, 'dessert', 'pastries', 240, array['oven']::text[], array['holiday', 'make-ahead', 'entertaining', 'comfort']::text[], array['Short on time? Use two store-bought refrigerated pie crusts; some contain lard or milk, so check the box if that matters.', 'Keep everything cold: if the butter softens while you roll, chill the dough for 15 minutes and carry on.']::text[], 'https://images.pexels.com/photos/12782728/pexels-photo-12782728.jpeg', 'Whole apple pie with a lattice crust seen from above', 'Hilal Bülbül', 'https://www.pexels.com/@hilalbulbul/', 'https://www.pexels.com/photo/top-view-of-an-apple-pie-12782728/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'holiday', 'comfort', 'dessert', 'entertaining']::text[], array['bake']::text[], array['tangy', 'aromatic', 'sweet']::text[], array['thanksgiving', 'july-4th', 'christmas']::text[], null, 'traditional', 'apple-pie', 'classic', 'Keep loosely covered at room temperature 2 days or in the fridge up to 4 days. Rewarm slices in a 325°F oven for 10 minutes.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['ice water', 'apple', 'brown sugar', 'cornstarch', 'lemon juice', 'ground cinnamon', 'ground nutmeg', 'egg', 'turbinado sugar']::text[], 'apple|brown sugar|cornstarch|egg|ground cinnamon|ground nutmeg|ice water|lemon juice|turbinado sugar',
  null, null, null, null, null, null, null, null)
