  ('4132d29e-9ed2-4b45-b14f-86d29ea276a2', 4, 'Crust', '2 stick cold unsalted butter, cut into ½-inch cubes', 'cold unsalted butter', 2, 'stick', 'cut into ½-inch cubes', false),
  ('4132d29e-9ed2-4b45-b14f-86d29ea276a2', 5, 'Crust', '8 tbsp ice water, you may not need it all', 'ice water', 8, 'tbsp', 'you may not need it all', false),
  ('4132d29e-9ed2-4b45-b14f-86d29ea276a2', 6, 'Filling', '3 lb apples, about 7 medium, a mix of Granny Smith and Honeycrisp, peeled and sliced ¼ inch thick', 'apples', 3, 'lb', 'about 7 medium, a mix of Granny Smith and Honeycrisp, peeled and sliced ¼ inch thick', false),
  ('4132d29e-9ed2-4b45-b14f-86d29ea276a2', 7, 'Filling', '½ cup sugar', 'sugar', 0.5, 'cup', null, false),
  ('4132d29e-9ed2-4b45-b14f-86d29ea276a2', 8, 'Filling', '¼ cup light brown sugar, packed', 'light brown sugar', 0.25, 'cup', 'packed', false),
