delete from public.recipe_instructions where recipe_id = '4132d29e-9ed2-4b45-b14f-86d29ea276a2';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('4132d29e-9ed2-4b45-b14f-86d29ea276a2', 1, 'Crust', 'Whisk the flour, sugar and salt. Toss in the butter and rub or pinch it in with your fingertips (or a pastry cutter) until the pieces are the size of peas. Drizzle in 6 tablespoons of ice water and toss with a fork until the dough holds together when squeezed, adding more water a teaspoon at a time if needed.', 600, null, null),
  ('4132d29e-9ed2-4b45-b14f-86d29ea276a2', 2, 'Crust', 'Divide in two, press each into a flat disk, wrap and refrigerate at least 1 hour (or up to 2 days).', 3600, null, null),
  ('4132d29e-9ed2-4b45-b14f-86d29ea276a2', 3, 'Filling', 'Heat the oven to 425°F with a rack in the lowest position and a baking sheet on it. Toss the apples with the sugars, cornstarch, lemon juice, cinnamon, nutmeg and salt.', 600, 218.3, null),
  ('4132d29e-9ed2-4b45-b14f-86d29ea276a2', 4, null, 'On a floured counter, roll one disk into a 12-inch circle and ease it into a 9-inch pie plate. Pile in the apples (it will be tall). Roll the second disk to 11 inches, lay it over, trim, fold the edges under and crimp. Brush with the egg wash, sprinkle with turbinado sugar and cut 4–5 vents in the top.', 900, null, null),
  ('4132d29e-9ed2-4b45-b14f-86d29ea276a2', 5, null, 'Bake on the hot baking sheet for 20 minutes. Lower the oven to 375°F and bake until the crust is deep golden and thick juices bubble through the vents, 45–55 minutes more. Cover the edges with foil if they brown too fast.', 4200, 190.6, null),
  ('4132d29e-9ed2-4b45-b14f-86d29ea276a2', 6, null, 'Cool on a rack at least 3 hours so the filling sets; cut too soon and it runs.', 10800, null, null);

