values ('96f5c512-8f75-4d03-8e7f-24034baf3278', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'pecan-pie', 'pecan-pie-96f5c5', 'Pecan Pie', 'A buttery, caramel-like brown sugar custard packed with toasted pecans in a flaky crust — the Southern holiday classic, made with a store-bought or homemade crust.', 'southern', 2, 20, 60, 260, 8, 'dessert', 'pastries', 180, array['oven']::text[], array['holiday', 'make-ahead', 'entertaining']::text[], array['A thermometer takes the guesswork out: at 200°F the filling sets firm once it cools, well past the 160°F egg-safe point.', 'Store-bought pie crusts can contain lard, milk or soy — check the box if anyone has allergies.']::text[], 'https://images.pexels.com/photos/30146098/pexels-photo-30146098.jpeg', 'Pecan pie with a slice served on a white plate', 'tom davis', 'https://www.pexels.com/@tom-davis-2148511154/', 'https://www.pexels.com/photo/delicious-pecan-pie-with-a-slice-on-white-plate-30146098/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'holiday', 'dessert', 'entertaining']::text[], array['bake']::text[], array['sweet']::text[], array['thanksgiving', 'christmas']::text[], null, 'traditional', 'pecan-pie', 'classic', 'Cover and refrigerate up to 4 days (the custard needs the fridge after 2 hours out). Serve chilled or at room temperature; freezes well up to 2 months.', null, 'owned', array['egg', 'gluten', 'milk', 'tree_nut', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['pie crust', 'pecan halve', 'egg', 'corn syrup', 'brown sugar', 'vanilla extract']::text[], 'brown sugar|corn syrup|egg|pecan halve|pie crust|vanilla extract',
  null, null, null, null, null, null, null, null)
