insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('96f5c512-8f75-4d03-8e7f-24034baf3278', 1, null, '1 refrigerated pie crust, 9-inch, or homemade single crust', 'refrigerated pie crust', 1, null, '9-inch, or homemade single crust', false),
  ('96f5c512-8f75-4d03-8e7f-24034baf3278', 2, null, '2 cups pecan halves', 'pecan halves', 2, 'cup', null, false),
  ('96f5c512-8f75-4d03-8e7f-24034baf3278', 3, null, '3 large eggs', 'large eggs', 3, null, null, false),
  ('96f5c512-8f75-4d03-8e7f-24034baf3278', 4, null, '1 cup light corn syrup', 'light corn syrup', 1, 'cup', null, false),
  ('96f5c512-8f75-4d03-8e7f-24034baf3278', 5, null, '¾ cup light brown sugar, packed', 'light brown sugar', 0.75, 'cup', 'packed', false),
  ('96f5c512-8f75-4d03-8e7f-24034baf3278', 6, null, '4 tbsp unsalted butter, melted', 'unsalted butter', 4, 'tbsp', 'melted', false),
  ('96f5c512-8f75-4d03-8e7f-24034baf3278', 7, null, '2 tsp vanilla extract', 'vanilla extract', 2, 'tsp', null, false),
  ('96f5c512-8f75-4d03-8e7f-24034baf3278', 8, null, '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('96f5c512-8f75-4d03-8e7f-24034baf3278', 9, null, '1 tbsp bourbon', 'bourbon', 1, 'tbsp', null, true);
delete from public.recipe_instructions where recipe_id = '96f5c512-8f75-4d03-8e7f-24034baf3278';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('96f5c512-8f75-4d03-8e7f-24034baf3278', 1, null, 'Heat the oven to 350°F with a rack in the lower third. Spread the pecans on a baking sheet and toast until fragrant, 6–8 minutes. Let them cool a little.', 420, 176.7, null),
  ('96f5c512-8f75-4d03-8e7f-24034baf3278', 2, null, 'Fit the crust into a 9-inch pie plate (not deep-dish), fold the overhang under and crimp. Chill while you make the filling.', 300, null, null),
  ('96f5c512-8f75-4d03-8e7f-24034baf3278', 3, null, 'Whisk the eggs in a large bowl until smooth, then whisk in the corn syrup, brown sugar, melted butter, vanilla, salt and bourbon until the sugar dissolves. Stir in the pecans.', 180, null, null),
  ('96f5c512-8f75-4d03-8e7f-24034baf3278', 4, null, 'Set the pie plate on a baking sheet and pour in the filling. Bake until the edges are puffed and the center jiggles only slightly, like set gelatin, and reads 200°F, 50–60 minutes. Lay foil over the crust edge if it browns too fast.', 3300, 176.7, 71.1),
  ('96f5c512-8f75-4d03-8e7f-24034baf3278', 5, null, 'Cool completely on a rack, at least 3 hours, so the filling sets cleanly.', 10800, null, null);

-- Creamy Rice Pudding
