values ('9ddfd013-b004-4142-ad23-a8a206893c39', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'creamy-rice-pudding', 'creamy-rice-pudding-9ddfd0', 'Creamy Rice Pudding', 'Slow-simmered stovetop rice pudding — just rice, milk, sugar, vanilla and a cinnamon stick — that''s lush and spoonable warm or cold.', 'american', 1, 5, 45, 50, 6, 'dessert', 'plated', 0, array['stove']::text[], array['budget', 'kid-friendly', 'make-ahead', 'comfort']::text[], array['Arborio (risotto) rice gives the creamiest result; long-grain rice works but is less silky.', 'No cinnamon stick? Stir in ¼ teaspoon ground cinnamon with the vanilla.']::text[], 'https://images.pexels.com/photos/37825038/pexels-photo-37825038.jpeg', 'Creamy rice pudding dusted with cinnamon in a glass bowl', 'Samet Kaplan 🇹🇷', 'https://www.pexels.com/@sametkaplan/', 'https://www.pexels.com/photo/traditional-turkish-sutlac-in-glass-bowl-37825038/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'budget', 'dessert']::text[], array['stew', 'boil']::text[], array['aromatic', 'sweet']::text[], '{}'::text[], null, null, 'rice-pudding', 'classic', 'Refrigerate in a covered container up to 4 days. Stir in a splash of milk when serving, cold or rewarmed.', null, 'owned', array['milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['arborio rice', 'milk', 'cinnamon stick', 'vanilla extract', 'ground cinnamon']::text[], 'arborio rice|cinnamon stick|ground cinnamon|milk|vanilla extract',
  null, null, null, null, null, null, null, null)
