delete from public.recipe_ingredients where recipe_id = '9ddfd013-b004-4142-ad23-a8a206893c39';
insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('9ddfd013-b004-4142-ad23-a8a206893c39', 1, null, '¾ cup Arborio rice, or medium-grain white rice', 'Arborio rice', 0.75, 'cup', 'or medium-grain white rice', false),
  ('9ddfd013-b004-4142-ad23-a8a206893c39', 2, null, '1½ cups water', 'water', 1.5, 'cup', null, false),
  ('9ddfd013-b004-4142-ad23-a8a206893c39', 3, null, '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('9ddfd013-b004-4142-ad23-a8a206893c39', 4, null, '4 cups whole milk, plus more to loosen', 'whole milk', 4, 'cup', 'plus more to loosen', false),
  ('9ddfd013-b004-4142-ad23-a8a206893c39', 5, null, '½ cup sugar', 'sugar', 0.5, 'cup', null, false),
  ('9ddfd013-b004-4142-ad23-a8a206893c39', 6, null, '1 cinnamon stick', 'cinnamon stick', 1, null, null, false),
  ('9ddfd013-b004-4142-ad23-a8a206893c39', 7, null, '2 tsp vanilla extract', 'vanilla extract', 2, 'tsp', null, false),
  ('9ddfd013-b004-4142-ad23-a8a206893c39', 8, null, '1 tbsp unsalted butter', 'unsalted butter', 1, 'tbsp', null, false),
  ('9ddfd013-b004-4142-ad23-a8a206893c39', 9, null, '½ cup raisins', 'raisins', 0.5, 'cup', null, true),
  ('9ddfd013-b004-4142-ad23-a8a206893c39', 10, null, '1 pinch ground cinnamon, to serve', 'ground cinnamon', 1, 'pinch', 'to serve', false);
delete from public.recipe_instructions where recipe_id = '9ddfd013-b004-4142-ad23-a8a206893c39';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('9ddfd013-b004-4142-ad23-a8a206893c39', 1, null, 'Bring the rice, water and salt to a boil in a heavy medium saucepan. Cover, lower the heat and simmer until the water is absorbed, about 12 minutes.', 720, null, null),
  ('9ddfd013-b004-4142-ad23-a8a206893c39', 2, null, 'Stir in the milk, sugar and cinnamon stick and bring back to a gentle simmer over medium heat.', 300, null, null),
  ('9ddfd013-b004-4142-ad23-a8a206893c39', 3, null, 'Simmer uncovered, stirring every few minutes and scraping the bottom so it doesn''t catch, until the rice is very soft and the pudding is thick and creamy but still loose, 25–30 minutes. Add the raisins for the last 10 minutes, if using.', 1680, null, null),
  ('9ddfd013-b004-4142-ad23-a8a206893c39', 4, null, 'Take off the heat, remove the cinnamon stick and stir in the vanilla and butter. It thickens a lot as it cools.', 60, null, null),
  ('9ddfd013-b004-4142-ad23-a8a206893c39', 5, null, 'Serve warm with a pinch of cinnamon, or chill and loosen with a splash of milk before serving cold.', null, null, null);

-- Chocolate Lava Cakes
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
