values ('7082d5d5-b5c3-43d2-84e5-5b3af51f580f', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chocolate-lava-cakes', 'chocolate-lava-cakes-7082d5', 'Chocolate Lava Cakes', 'Individual dark chocolate cakes baked just long enough to set the outside while the center stays warm and molten — restaurant-style but simple.', 'american', 2, 15, 13, 28, 4, 'dessert', 'cakes', 0, array['oven', 'microwave']::text[], array['date-night', 'entertaining', 'make-ahead']::text[], array['Make ahead: fill the ramekins, cover and refrigerate up to 1 day, then bake straight from the fridge for 15–16 minutes.', 'Many chocolate bars contain milk or soy lecithin — check the label if anyone has allergies.']::text[], 'https://images.pexels.com/photos/36183209/pexels-photo-36183209.jpeg', 'Molten chocolate lava cake dusted with powdered sugar', 'Valeria Boltneva', 'https://www.pexels.com/@valeriya/', 'https://www.pexels.com/photo/delicious-molten-chocolate-lava-cake-on-plate-36183209/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'date_night', 'entertaining', 'dessert', 'holiday']::text[], array['bake']::text[], array['sweet']::text[], array['valentines', 'date-night', 'anniversary']::text[], null, null, 'chocolate-lava-cake', 'classic', 'Best straight from the oven. Unbaked batter keeps in the ramekins, covered, in the fridge for 1 day.', 'The eggs here aren''t cooked to 160°F. Use pasteurized eggs if you''re serving anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['cocoa powder', 'bittersweet chocolate', 'egg', 'egg yolk']::text[], 'bittersweet chocolate|cocoa powder|egg|egg yolk',
  null, null, null, null, null, null, null, null)
