values ('9c1c6f44-3280-4a28-911d-4e1ee1c37e11', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chocolate-mousse', 'chocolate-mousse-9c1c6f', 'Chocolate Mousse', 'Silky, airy dark chocolate mousse set in glasses — adapted from the French classic: we cook the yolks into a warm custard and lighten it with whipped cream instead of raw egg whites.', 'french', 2, 25, 6, 181, 6, 'dessert', 'plated', 150, array['stove']::text[], array['make-ahead', 'entertaining', 'date-night']::text[], array['If the chocolate mixture is still warm when you fold in the cream, the cream melts and the mousse goes dense — test it on your wrist first.', 'Many chocolate bars contain milk or soy lecithin — check the label if anyone has allergies.']::text[], 'https://images.pexels.com/photos/7819053/pexels-photo-7819053.jpeg', 'Chocolate mousse topped with whipped cream in a glass', 'Max Griss', 'https://www.pexels.com/@max-griss-16866522/', 'https://www.pexels.com/photo/photo-of-dessert-in-a-glass-7819053/', 'pexels', true, 'public', false,
  'pending_review', array['entertaining', 'date_night', 'dessert', 'holiday']::text[], array['boil']::text[], array['rich', 'sweet']::text[], array['valentines', 'dinner-party', 'date-night']::text[], null, 'adapted', 'chocolate-mousse', 'classic', 'Keep covered in the fridge up to 3 days. Not suitable for freezing.', null, 'owned', array['egg', 'milk']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['bittersweet chocolate', 'egg yolk', 'milk', 'vanilla extract', 'heavy cream']::text[], 'bittersweet chocolate|egg yolk|heavy cream|milk|vanilla extract',
  null, null, null, null, null, null, null, null)
