insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('9c1c6f44-3280-4a28-911d-4e1ee1c37e11', 1, null, 'Put the chopped chocolate in a large heatproof bowl with a fine-mesh sieve set over it.', 60, null, null),
  ('9c1c6f44-3280-4a28-911d-4e1ee1c37e11', 2, null, 'Whisk the egg yolks, sugar, milk and salt in a small saucepan. Cook over medium-low heat, stirring constantly with a spatula and scraping the bottom, until it thickens enough to coat the spatula and reaches 160°F, 4–6 minutes. Don''t let it boil.', 360, null, 71.1),
  ('9c1c6f44-3280-4a28-911d-4e1ee1c37e11', 3, null, 'Pour the hot custard through the sieve onto the chocolate. Let it sit 1 minute, then stir slowly from the center until smooth and glossy. Stir in the vanilla and let it cool until just warm to the touch, about 15 minutes.', 960, null, null),
  ('9c1c6f44-3280-4a28-911d-4e1ee1c37e11', 4, null, 'Whip the cold cream to soft peaks that just hold their shape — don''t take it to stiff, or the mousse turns grainy.', 180, null, null),
  ('9c1c6f44-3280-4a28-911d-4e1ee1c37e11', 5, null, 'Stir a third of the cream into the chocolate to loosen it, then gently fold in the rest in two additions until no white streaks remain.', 180, null, null),
  ('9c1c6f44-3280-4a28-911d-4e1ee1c37e11', 6, null, 'Spoon into six small glasses or ramekins, cover and refrigerate until set, at least 2 hours. Top with raspberries to serve.', 7200, null, null);

-- Oatmeal Raisin Cookies
