  attribution, reviewed_by, reviewed_at, calories_per_serving, protein_g, carbs_g, fat_g, nutrition_source)
values ('b99d68bf-463b-4bbf-89ac-8106fbe23642', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'oatmeal-raisin-cookies', 'oatmeal-raisin-cookies-b99d68', 'Oatmeal Raisin Cookies', 'Thick, chewy brown sugar oatmeal cookies with crisp edges, plump raisins and a warm touch of cinnamon.', 'american', 1, 20, 24, 44, 30, 'dessert', 'cookies', 0, array['oven']::text[], array['kid-friendly', 'make-ahead', 'freezer-friendly', 'lunchbox']::text[], array['For thicker cookies, chill the scooped dough 30 minutes before baking.', 'Oats are often processed alongside wheat; this dough has wheat flour anyway, but it''s worth knowing if you swap the flour.']::text[], 'https://images.pexels.com/photos/10688029/pexels-photo-10688029.jpeg', 'Stack of oatmeal raisin cookies on a wooden board', 'Skyler Ewing', 'https://www.pexels.com/@skyler-ewing-266953/', 'https://www.pexels.com/photo/brown-cookies-on-brown-wooden-chopping-board-10688029/', 'pexels', true, 'public', false,
  'pending_review', array['baking', 'dessert', 'breakfast', 'comfort']::text[], array['bake']::text[], array['aromatic', 'sweet']::text[], '{}'::text[], null, null, 'oatmeal-raisin-cookies', 'classic', 'Keep in an airtight container at room temperature up to 5 days. Freeze scooped dough balls and bake from frozen, adding 1–2 minutes.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['raisin', 'brown sugar', 'egg', 'vanilla extract', 'baking soda', 'ground cinnamon', 'rolled oat']::text[], 'baking soda|brown sugar|egg|ground cinnamon|raisin|rolled oat|vanilla extract',
  null, null, null, null, null, null, null, null)
