  ('b99d68bf-463b-4bbf-89ac-8106fbe23642', 3, null, '1 cup light brown sugar, packed', 'light brown sugar', 1, 'cup', 'packed', false),
  ('b99d68bf-463b-4bbf-89ac-8106fbe23642', 4, null, '½ cup sugar', 'sugar', 0.5, 'cup', null, false),
  ('b99d68bf-463b-4bbf-89ac-8106fbe23642', 5, null, '2 large eggs, at room temperature', 'large eggs', 2, null, 'at room temperature', false),
  ('b99d68bf-463b-4bbf-89ac-8106fbe23642', 6, null, '2 tsp vanilla extract', 'vanilla extract', 2, 'tsp', null, false),
  ('b99d68bf-463b-4bbf-89ac-8106fbe23642', 7, null, '1½ cups all-purpose flour', 'all-purpose flour', 1.5, 'cup', null, false),
  ('b99d68bf-463b-4bbf-89ac-8106fbe23642', 8, null, '1 tsp baking soda', 'baking soda', 1, 'tsp', null, false),
