delete from public.recipe_instructions where recipe_id = 'b99d68bf-463b-4bbf-89ac-8106fbe23642';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('b99d68bf-463b-4bbf-89ac-8106fbe23642', 1, null, 'Heat the oven to 350°F and line two baking sheets with parchment paper. Cover the raisins with hot tap water and soak 10 minutes, then drain and pat dry — this keeps them juicy.', 600, 176.7, null),
  ('b99d68bf-463b-4bbf-89ac-8106fbe23642', 2, null, 'Beat the butter and both sugars with a hand or stand mixer until light and fluffy, about 2 minutes. Beat in the eggs one at a time, then the vanilla.', 240, null, null),
  ('b99d68bf-463b-4bbf-89ac-8106fbe23642', 3, null, 'Whisk the flour, baking soda, cinnamon and salt, add to the butter mixture and mix on low until just combined. Stir in the oats and raisins by hand.', 120, null, null),
  ('b99d68bf-463b-4bbf-89ac-8106fbe23642', 4, null, 'Scoop 2-tablespoon balls of dough 2 inches apart onto the sheets.', 300, null, null),
  ('b99d68bf-463b-4bbf-89ac-8106fbe23642', 5, null, 'Bake one sheet at a time until the edges are golden but the centers still look slightly underdone, 10–12 minutes. They firm up as they cool.', 1440, 176.7, null),
  ('b99d68bf-463b-4bbf-89ac-8106fbe23642', 6, null, 'Cool on the sheet 5 minutes, then move to a rack to cool completely.', 300, null, null);

