values ('90e49198-efe8-4c7c-9ab7-5acb36fe5065', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'snickerdoodles', 'snickerdoodles-90e491', 'Snickerdoodles', 'Soft, pillowy butter cookies rolled in cinnamon sugar, with the gentle tang and crinkly tops that only cream of tartar gives.', 'american', 1, 20, 30, 50, 36, 'dessert', 'cookies', 0, array['oven']::text[], array['kid-friendly', 'make-ahead', 'freezer-friendly', 'holiday']::text[], array['No cream of tartar? Replace it and the baking soda with 2 teaspoons baking powder; the cookies will be less tangy and less crinkly.', 'Soft dough is easier to roll after 20 minutes in the fridge.']::text[], 'https://images.unsplash.com/photo-1703187839559-3ae0b51bd4f1', 'Snickerdoodle cookies cooling on a wire rack', 'Jessica Johnston', 'https://unsplash.com/@jdjohnston', 'https://unsplash.com/photos/a-bunch-of-cookies-that-are-cooling-on-a-rack-92G0voshUr0', 'unsplash', true, 'public', false,
  'pending_review', array['baking', 'dessert', 'holiday', 'comfort']::text[], array['bake']::text[], array['aromatic', 'sweet']::text[], array['christmas']::text[], null, null, 'snickerdoodles', 'classic', 'Keep in an airtight container at room temperature up to 5 days, or freeze baked cookies up to 3 months.', null, 'owned', array['egg', 'gluten', 'milk', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian']::text[], array['cream tartar', 'baking soda', 'egg', 'vanilla extract', 'ground cinnamon']::text[], 'baking soda|cream tartar|egg|ground cinnamon|vanilla extract',
  null, null, null, null, null, null, null, null)
