delete from public.recipe_instructions where recipe_id = '90e49198-efe8-4c7c-9ab7-5acb36fe5065';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('90e49198-efe8-4c7c-9ab7-5acb36fe5065', 1, 'Dough', 'Heat the oven to 375°F and line two baking sheets with parchment paper. Whisk the flour, cream of tartar, baking soda and salt in a bowl.', null, 190.6, null),
  ('90e49198-efe8-4c7c-9ab7-5acb36fe5065', 2, 'Dough', 'Beat the butter and sugar with a hand or stand mixer until pale and fluffy, 2–3 minutes. Beat in the eggs one at a time, then the vanilla. Mix in the flour mixture on low until just combined.', 300, null, null),
  ('90e49198-efe8-4c7c-9ab7-5acb36fe5065', 3, 'Coating', 'Stir the sugar and cinnamon together in a small bowl. Roll the dough into 1½-inch balls (about 1½ tablespoons each) and roll each in the cinnamon sugar to coat.', 600, null, null),
  ('90e49198-efe8-4c7c-9ab7-5acb36fe5065', 4, null, 'Place 2 inches apart on the sheets and bake one sheet at a time until puffed, crackled on top and just set at the edges but still soft in the middle, 9–10 minutes.', 1800, 190.6, null),
  ('90e49198-efe8-4c7c-9ab7-5acb36fe5065', 5, null, 'Cool on the sheet 5 minutes — they''ll sink into crinkly domes — then move to a rack.', 300, null, null);
